/* ===== Mezo design tokens — Exist Zen "Mezo Edition" (DS-migration P1, mezo-setx.2) =====
   Normative source: docs/references/design-system-mezo.html + ADR 0018.
   Architecture: (1) the DS token block below is the ONLY place literals live;
   (2) the Pulse dark block overrides the same names token-level (components never
   branch on theme); (3) every legacy Napív/Deep-Current token further down is an
   ALIAS onto a DS token (the proven Napív swap technique) so unmigrated call sites
   keep rendering in-family until their page's sweep phase retires them (P9). */

:root {
  /* ─── Brand ramps · bg → soft → base → hover → deep ───
     Coral base fails AA as text (2.8:1) — text/links use hover/deep (ADR 0018). */
  --primary-bg:    #FFF4EF;
  --primary-soft:  #FFDFD3;
  --primary-base:  #FF6B4A;
  --primary-hover: #E05535;
  --primary-deep:  #A84A26;

  --secondary-bg:    #F1EBE2;
  --secondary-soft:  #8A7A6A;
  --secondary-base:  #5F5346;
  --secondary-hover: #2B2118;
  --secondary-deep:  #1A140E;

  --accent-bg:    #FDF8EC;
  --accent-soft:  #FAECC8;
  --accent-base:  #D4A853;
  --accent-hover: #B8902E;
  --accent-deep:  #8E6E1F;

  /* ─── Status ramps ─── */
  --success-bg:    #EEF5EC;
  --success-soft:  #D8E6D4;
  --success-base:  #6B8A5D;
  --success-hover: #4A6A3D;
  --success-deep:  #2D4D2A;

  --warning-bg:    #FEF6E2;
  --warning-soft:  #F6DC8A;
  --warning-base:  #C9971A;
  --warning-hover: #8A6918;
  --warning-deep:  #5E480F;

  --error-bg:    #FDF0EC;
  --error-soft:  #F5D5CC;
  --error-base:  #C4634B;
  --error-hover: #A4503C;
  --error-deep:  #7A3A28;

  /* ─── Surfaces · text ─── */
  --surface-page:     #FBF6EF;
  --surface-card:     #FFFFFF;
  --surface-elevated: #FFFFFF;
  --surface-recess:   rgba(43, 33, 24, 0.05);
  /* A fejléc értesítés-paneljének takarója (mezo-g9fz) — tokenizált, mert a két témában
     nem ugyanaz a sötétítés olvasható. */
  --mz-ntfscrim:      rgba(43, 33, 24, 0.18);

  --text-primary:   #2B2118;
  --text-secondary: #5F5346;
  --text-muted:     #8A7A6A;
  --text-disabled:  #A5978A;
  --text-inverse:   #FFFFFF;

  --divider: rgba(43, 33, 24, 0.10);

  /* ─── Data-viz band · outside the UI role cap (charts/rings/icons/heatmaps ONLY) ─── */
  --macro-calories: #C44B3D;
  --macro-protein:  #E26B67;
  --macro-carbs:    #D49245;
  --macro-fat:      #C4A020;
  --macro-fiber:    #6BA24A;
  --macro-sugar:    #C97A9D;
  --macro-salt:     #7A7088;

  --dv-coral: #FF6B4A;   /* Train (in UI chrome coral always = primary) */
  --dv-sage:  #7FA48A;   /* Fuel */
  --dv-lav:   #9B8FC4;   /* Sleep · Me */
  --dv-rose:  #E27A8B;   /* Sport */
  --dv-sky:   #6FA7D8;   /* Futás */
  --dv-amber: #FFB347;   /* streak · reward moments */

  /* ─── Primary CTA gradient — ONE definition (Rule 9) ─── */
  --cta-g1: #FF7A55;
  --cta-g2: #FF5B36;
  --gradient-cta: linear-gradient(135deg, var(--cta-g1), var(--cta-g2));
  --shadow-cta: 0 8px 20px rgba(255, 91, 54, 0.35);

  /* ─── Sage CTA gradient — Fuel's own domain-accent CTAs (mezo-jgh9, D4) ─── */
  --gradient-sage: linear-gradient(135deg, var(--success-base), var(--success-hover));
  --shadow-sage: 0 8px 20px rgba(93, 132, 104, 0.35);

  /* ─── Halos · page-top ambient gradients ─── */
  --halo-amber:  radial-gradient(ellipse at 50% 30%, rgba(212,168,83,0.32) 0%, rgba(251,246,239,0) 55%);
  --halo-sage:   radial-gradient(ellipse at 50% 30%, rgba(154,184,143,0.30) 0%, rgba(244,208,111,0.10) 30%, rgba(251,246,239,0) 60%);
  --halo-rose:   radial-gradient(ellipse at 50% 30%, rgba(231,134,110,0.20) 0%, rgba(251,246,239,0) 55%);
  --halo-blue:   radial-gradient(ellipse at 50% 30%, rgba(107,176,209,0.30) 0%, rgba(251,246,239,0) 60%);
  --halo-violet: radial-gradient(ellipse at 50% 30%, rgba(154,95,196,0.24) 0%, rgba(251,246,239,0) 60%);
  /* Train's own halo (mezo-ju4j6.12): the domain had none — the Titanium era drew its
     Train heroes as dark bordered posters instead. Deeper than its siblings on purpose:
     the two hero bands it grounds (Terv poszter, Terhelés hős) each carry ONE big numeral
     and a body figure, and a fainter halo left them floating on the page (style bible §2.2 C). */
  --halo-coral:  radial-gradient(ellipse at 50% 24%, rgba(255,107,74,0.34) 0%, rgba(212,168,83,0.12) 32%, rgba(251,246,239,0) 64%);

  /* ─── Spacing — every step divisible by 4 (MOBILE_UX §4.1) ─── */
  --sp-1: 4px;
  --sp-2: 8px;
  --sp-3: 12px;
  --sp-4: 16px;
  --sp-5: 24px;
  --sp-6: 32px;
  --sp-7: 40px;
  --sp-8: 48px;
  --sp-9: 64px;

  /* ─── Radius — DS scale (the old slots re-tuned: sm 8→6, md 12→10, lg 16→14,
     xl 20→18, 2xl 24→22; r-3xl is new for sheets) ─── */
  --r-sm:  6px;
  --r-md:  10px;
  --r-lg:  14px;
  --r-xl:  18px;
  --r-2xl: 22px;
  --r-3xl: 28px;
  --r-full: 9999px;

  /* Bottom breathing room the app scroller reserves for the floating tab bar. Anything that
     pins itself above the tab bar (a sticky composer) offsets by this same token. */
  --screen-bottom-pad: 118px;

  /* Horizontal gutter on the app scroller — no page or the shell header may touch the
     physical screen edge (user QA, mezo-itsq; 2px proved invisible, bumped to 12px in
     mezo-eczm). One token, applied once on .screen-content; every page and the header
     sit inside it and inherit the gutter. */
  --screen-gutter: 12px;

  /* ─── Shadows ─── */
  --shadow-xs: 0 1px 2px rgba(43, 33, 24, 0.04);
  --shadow-sm: 0 2px 6px rgba(43, 33, 24, 0.06);
  --shadow-md: 0 4px 14px rgba(43, 33, 24, 0.10);
  --shadow-lg: 0 8px 24px rgba(43, 33, 24, 0.12);
  --shadow-xl: 0 16px 40px rgba(43, 33, 24, 0.18);
  --shadow-accent: 0 8px 22px rgba(184, 144, 46, 0.40);
  --shadow-focus: 0 0 0 3px rgba(255, 107, 74, 0.32);

  /* ─── Motion ─── */
  --duration-fast: 150ms;
  --duration-normal: 250ms;
  --duration-slow: 400ms;
  --ease-out: cubic-bezier(0, 0, 0.2, 1);
  --ease-in-out: cubic-bezier(0.4, 0, 0.2, 1);
  --ease-spring: cubic-bezier(0.34, 1.56, 0.64, 1);

  /* ─── Z-index ladder ─── */
  --z-base: 0;
  --z-sticky: 10;
  --z-bottomnav: 30;
  --z-fab: 40;
  --z-sheet: 50;
  --z-modal: 60;
  --z-toast: 70;
  --z-tooltip: 80;

  /* ─── Fonts (ADR 0018 D2: Geist + Fraunces; Bricolage/Jakarta retired) ─── */
  --ff-display: 'Geist', system-ui, sans-serif;
  --ff-body:    'Geist', -apple-system, system-ui, sans-serif;
  --ff-serif:   'Fraunces', Georgia, serif;
  --ff-mono:    'Geist Mono', monospace;
  /* ── Mozaik 2.0 token delta (mezo-d20.1.5) — light values verbatim from the
        design_2.0 prototypes; dark overrides derive from the dv ramp + surfaces. */
  --mz-wash-coral: linear-gradient(150deg, #FFE7DC, #FFF7F2);
  --mz-wash-sage:  linear-gradient(150deg, #E9F1E2, #F7FBF3);
  --mz-wash-sky:   linear-gradient(150deg, #DFEDF5, #F5FAFD);
  --mz-wash-gold:  linear-gradient(150deg, #FFF1D6, #FFFAF0);
  --mz-wash-lav:   linear-gradient(150deg, #EBE6F8, #F9F6FE);
  --mz-wash-rose:  linear-gradient(150deg, #FAE3ED, #FEF8FB);
  --mz-wash-white: #FFFFFF;
  --mz-shadow:      0 17px 31px -17px rgba(43, 33, 24, 0.28), 0 2px 6px rgba(43, 33, 24, 0.04), inset 0 1px 0 rgba(255, 255, 255, 0.7);
  --mz-shadow-sage: 0 17px 31px -17px rgba(110, 139, 94, 0.45), 0 2px 6px rgba(43, 33, 24, 0.04), inset 0 1px 0 rgba(255, 255, 255, 0.7);
  --mz-shadow-sky:  0 17px 31px -17px rgba(78, 143, 184, 0.4), 0 2px 6px rgba(43, 33, 24, 0.04), inset 0 1px 0 rgba(255, 255, 255, 0.7);
  --mz-shadow-gold: 0 17px 31px -17px rgba(181, 126, 20, 0.4), 0 2px 6px rgba(43, 33, 24, 0.04), inset 0 1px 0 rgba(255, 255, 255, 0.7);
  --mz-shadow-lav:  0 17px 31px -17px rgba(93, 79, 160, 0.4), 0 2px 6px rgba(43, 33, 24, 0.04), inset 0 1px 0 rgba(255, 255, 255, 0.7);
  --mz-shadow-rose: 0 17px 31px -17px rgba(142, 63, 111, 0.35), 0 2px 6px rgba(43, 33, 24, 0.04), inset 0 1px 0 rgba(255, 255, 255, 0.7);
  --mz-shadow-most: 0 24px 40px -17px rgba(255, 107, 74, 0.42), 0 2px 7px rgba(43, 33, 24, 0.05), inset 0 1px 0 rgba(255, 255, 255, 0.85);
  --mz-cell-sage-bg: #E9F1E2;  --mz-cell-sage-ink: #4E6B42;
  --mz-cell-coral-bg: #FFE7DC; --mz-cell-coral-ink: #A84A26;
  --mz-cell-amber-bg: #FFF1D6; --mz-cell-amber-ink: #8A5E07;
  --mz-cell-lav-bg: #EBE6F8;   --mz-cell-lav-ink: #5D4FA0;
  --mz-cell-sky-bg: #DFEDF5;   --mz-cell-sky-ink: #2E6E96;
  --mz-cell-rose-bg: #FAE3ED;  --mz-cell-rose-ink: #8E3F6F;
  --mz-cell-gold-bg: #FBEBCB;  --mz-cell-gold-ink: #8A5E07;
  --mz-tone-coral: #FFE3D4; --mz-tone-gold: #FBEBCB; --mz-tone-lav: #E9E3F7;
  --mz-tone-rose: #F7E3ED;  --mz-tone-sage: #E4EEDC; --mz-tone-sky: #DCEBF4;
  /* Cél detail heroes — exact approved artifact washes, promoted to paired tokens so
     the same asymmetrical card anatomy remains theme-native instead of baking light UI
     surfaces into the component rules (mezo-ricj.6). */
  --mz-goal-hero-nutrition: radial-gradient(circle at 88% 17%, rgba(255,255,255,.64), transparent 18%), linear-gradient(145deg, #EEF8E8, #DCEFD4 58%, #F8EDC9);
  --mz-goal-hero-segment: radial-gradient(circle at 87% 17%, rgba(255,255,255,.66), transparent 18%), linear-gradient(145deg, #F0EDFF, #E5DDFF 57%, #DBEEFF);
  --mz-goal-hero-plans: radial-gradient(circle at 91% 18%, rgba(255,255,255,.65), transparent 18%), linear-gradient(145deg, #EAF8FF 0%, #D8F0ED 54%, #DFF0D5 100%);
  --mz-goal-hero-guards: radial-gradient(circle at 87% 17%, rgba(255,255,255,.65), transparent 18%), linear-gradient(145deg, #FFF0EA, #FFE0D6 56%, #FFECC5);
  --mz-goal-hero-settings: radial-gradient(circle at 87% 17%, rgba(255,255,255,.66), transparent 18%), linear-gradient(145deg, #EAF6FF, #D9ECF7 55%, #DFEEDD);
  --mz-goal-emblem: linear-gradient(145deg, rgba(255,255,255,.86), rgba(255,255,255,.40));
  --mz-cellbg: rgba(255, 255, 255, 0.72);
  --mz-chipbg: rgba(255, 255, 255, 0.7);
  --mz-stripbg: #FFFFFF;
  --mz-sheet-bg: linear-gradient(180deg, #FFFDF9 0%, #FDFAF4 100%); /* F7.3 sheet-minta */
  --mz-strength: linear-gradient(90deg, #E5C46B, #C9962E); /* habit-strength bar (nap #page-hab .hstr) */
  /* week-spark "now" bar + the derivation timeline's 04 disc (mezo-d20.15 Task 4) */
  --mz-gold-bar: linear-gradient(180deg, #FFD979, #C9962E);
  --mz-deload-stripe: repeating-linear-gradient(135deg, #E5C46B 0 3px, #F3E3B5 3px 6px);
  --mz-dstep-custom: #6C5FA3; /* derivation timeline's 03 „Rád szabva" disc */
  --mz-ink-mut: #A2958A;
  /* BodyMap/MuscleChip lit-shape hairline (mezo-88iwa.4) — a subtle stroke that separates a
     trained shape from its neighbors without competing with the heat fill. Dark párja a
     dark blokkban, azonos névvel. */
  --mz-body-outline: #2b21182e;
  /* ── Fejléc-aurora (mezo-8az6) — napszak-tónusok. A wash a sáv teteje, a foltok
        adják a mélységet; a réteg alja maszkkal fakul a tartalomba. Dark párjuk a
        dark blokkban, azonos nevekkel. */
  --mzh-wash-reggel: linear-gradient(155deg, #FFD9A8 0%, #FFE7CE 55%, #FFF3E6 100%);
  --mzh-wash-nap:    linear-gradient(155deg, #B9DCF0 0%, #D3E9F6 55%, #EAF4FA 100%);
  --mzh-wash-este:   linear-gradient(155deg, #D6CDF3 0%, #E4DDF7 55%, #F1EDFB 100%);
  --mzh-blob1-reggel: #FFC078; --mzh-blob2-reggel: #FF8E6A;
  --mzh-blob1-nap:    #7FBEE8; --mzh-blob2-nap:    #69CFBD;
  --mzh-blob1-este:   #A392E4; --mzh-blob2-este:   #E28FBB;
  --mzh-deco-line: rgba(43, 33, 24, 0.18);
  --mzh-deco-fill: rgba(43, 33, 24, 0.24);
  --mzh-glass: rgba(255, 255, 255, 0.6);
  --mzh-glass-line: rgba(43, 33, 24, 0.08);
  /* A kompakt fejléc doboz-magassága (4px felső padding + 42px kontrollsor). A lapokon
     belüli sticky chrome ehhez képest tapad ki, hogy ne csússzon a shell-fejléc alá. */
  --mzh-head-cond-h: 46px;
  /* ── Napzárás night sky (mezo-d20.8.1.1) — the ritual's six-state darkening arc.
        The flow forces data-theme=dark (RitualPage's setForceTheme), so the two :root
        blocks carry IDENTICAL values: the duplication keeps the Mozaik rule (a --rz-*
        token is declared in both blocks, never one) rather than adding a light variant
        no surface can reach. Each act deepens; act 5 gets its gold break from .rz-glow. */
  /* Üveg (mezo-me75u.3): the arc now darkens on the app's warm-graphite ground (#191614), not a
     violet night — the glass and the aurora carry the colour. */
  --rz-sky-1: linear-gradient(180deg, #231E1B 0%, #191614 100%);
  --rz-sky-2: linear-gradient(180deg, #211C19 0%, #181513 100%);
  --rz-sky-3: linear-gradient(180deg, #1F1B18 0%, #171412 100%);
  --rz-sky-4: linear-gradient(180deg, #1D1916 0%, #161311 100%);
  --rz-sky-5: linear-gradient(180deg, #221B15 0%, #171412 100%);
  --rz-sky-6: linear-gradient(180deg, #181513 0%, #121010 100%);
  --rz-gold-hi: #FFE9A8;
  --mz-ink-soft: #6E6257;
  /* quest cards (mezo-d20.2.4) — prototype .qcard.done / .qxp hexes verbatim */
  --mz-qdone-bg: linear-gradient(150deg, #EFF3EA, #FBFDF9);
  --mz-qdone-ink: #5F7A52;
  --mz-qxp-ink: #A8801F;
  --mz-qxp-bg: rgba(201, 150, 46, 0.12);
  /* Mezo hub (mezo-d20.5.1) — prototype mezo-head/body hexes verbatim */
  --mz-wash-minta: #F0EDF8;                                   /* .t-minta solid lav */
  --mz-wash-kreed: linear-gradient(140deg, #FFF2EA, #FFFFFF 75%); /* .t-kreed / .kreed */
  --mz-decring: #C9962E;                                      /* .deccard gold ring */
  --mz-decobs-bg: #FBF3DF;                                    /* .decobs recessed gold */
  --mz-shadow-dec: 0 24px 40px -17px rgba(201, 150, 46, 0.45), 0 2px 7px rgba(43, 33, 24, 0.05), inset 0 1px 0 rgba(255, 255, 255, 0.85);
  --mz-shadow-chatopen: 0 19px 35px -17px rgba(93, 79, 160, 0.45), 0 2px 6px rgba(43, 33, 24, 0.04), inset 0 1px 0 rgba(255, 255, 255, 0.85);
  /* chat face (mezo-d20.5.2) — prototype mezo-body #page-chat hexes verbatim, shadows ×1.18 */
  --mz-chat-user-bg: linear-gradient(150deg, #FFEDE4, #FFF8F4);
  --mz-chat-user-shadow: 0 12px 24px -14px rgba(216, 72, 31, 0.3), inset 0 1px 0 rgba(255, 255, 255, 0.7);
  --mz-chat-a-shadow: 0 14px 28px -17px rgba(43, 33, 24, 0.3), inset 0 1px 0 rgba(255, 255, 255, 0.85);
  --mz-chat-send-bg: linear-gradient(135deg, #8A76CC, #6C5FA3);
  --mz-chat-send-shadow: 0 7px 17px -5px rgba(108, 95, 163, 0.6);
  --mz-chat-mic-bg: rgba(93, 79, 160, 0.08);
  --mz-chat-mic-rec-bg: rgba(201, 150, 46, 0.2);
  --mz-chat-refch-bg: rgba(43, 33, 24, 0.04);
  --mz-chat-refch-bd: rgba(43, 33, 24, 0.08);
  --mz-chat-memline: rgba(138, 118, 204, 0.4);
  --mz-chat-composer-shadow: 0 -7px 28px -14px rgba(43, 33, 24, 0.25), 0 17px 31px -17px rgba(93, 79, 160, 0.4), inset 0 1px 0 rgba(255, 255, 255, 0.85);
  --mzc-strip-bd: rgba(93, 79, 160, 0.16);
  --mzc-strip-shadow: 0 10px 20px -12px rgba(93, 79, 160, 0.45), inset 0 1px 0 rgba(255, 255, 255, 0.75);
  --mzc-panel-bg: rgba(255, 255, 255, 0.85);
  --mzc-panel-line: rgba(93, 79, 160, 0.1);
  --mzc-tx-sky: #3E7396;
  --mzc-tx-rose: #8E3F6F;
  /* Minták page (mezo-d20.5.3) — prototype mezo-body #page-mintak hexes verbatim */
  --mz-mnt-motor-bg: linear-gradient(140deg, #F7F4FD, #FFFFFF 70%);
  --mz-mnt-hot-ring: #C9962E;
  --mz-mnt-bar: linear-gradient(90deg, #B4A4E4, #8A76CC);
  /* Memoár + Tudástár re-face (mezo-d20.5.5) — prototype mezo-body .memoir/.candc/.facttile */
  --mz-memoir-glow: rgba(138, 118, 204, 0.16);
  --mz-memoir-shadow: 0 24px 42px -19px rgba(93, 79, 160, 0.45), inset 0 1px 0 rgba(255, 255, 255, 0.85);
  --mz-cand-ring: #C9962E;
  --mz-cand-shadow: 0 19px 33px -17px rgba(201, 150, 46, 0.45), inset 0 1px 0 rgba(255, 255, 255, 0.85);
  --mz-fic-bg: rgba(255, 255, 255, 0.78);
  --mz-fact-off-bg: rgba(255, 255, 255, 0.6);
  /* Előrejelzések + Kísérletek (mezo-d20.5.6) — prototype .stch/.gbar/.daydots hexes verbatim */
  --mz-stch-pend-bg: rgba(138, 118, 204, 0.14); --mz-stch-pend-ink: #5D4FA0;
  --mz-stch-ok-bg: rgba(143, 175, 126, 0.2);    --mz-stch-ok-ink: #4E6B42;
  --mz-stch-prop-bg: rgba(201, 150, 46, 0.16);  --mz-stch-prop-ink: #A8801F;
  --mz-stch-act-bg: rgba(255, 107, 74, 0.12);   --mz-stch-act-ink: #A84A26;
  --mz-stch-mut-bg: rgba(43, 33, 24, 0.05);     --mz-stch-mut-ink: #6E6257;
  --mz-gbar-bg: rgba(43, 33, 24, 0.08);
  --mz-gbar-lav: linear-gradient(90deg, #B4A4E4, #8A76CC);
  --mz-gbar-sage: linear-gradient(90deg, #A9C69A, #8FAF7E);   /* Growth ritmus dots / atlétikus meters */
  --mz-gbar-sky:  linear-gradient(90deg, #9CC4DE, #4E8FB8);   /* Growth napló accents */
  --mz-line: rgba(43, 33, 24, 0.12);
  --mz-line-soft: rgba(43, 33, 24, 0.07);
  --mz-daydot: rgba(43, 33, 24, 0.1);
  --mz-daydot-f: #C9962E;
  --mz-prop-border: #C9962E;
  --mz-prop-shadow: 0 20px 34px -14px rgba(201, 150, 46, 0.45), 0 2px 6px rgba(43, 33, 24, 0.05), inset 0 1px 0 rgba(255, 255, 255, 0.85);
  --mz-pic-bg: rgba(255, 255, 255, 0.78);
  --mz-no-ink: #A8462E;
  /* Memória observatory (mezo-d20.5.7) — laycard sand wash + coral layer shadow +
     the lav flow-connector/match-ring inks (prototype mezo-body .laycard/.flowc/.mring) */
  --mz-wash-sand: linear-gradient(150deg, #F3EDE2, #FBF8F1);
  --mz-shadow-coral: 0 17px 31px -17px rgba(216, 72, 31, 0.32), 0 2px 6px rgba(43, 33, 24, 0.04), inset 0 1px 0 rgba(255, 255, 255, 0.7);
  --mz-mem-dash: #B4A8D8;
  --mz-mem-ink: #8A76CC;
  /* Én hub (mezo-d20.6.1) — prototype en-body .idhero/.goalcard/.mezotile hexes verbatim */
  --mz-titlech-bg: rgba(201, 150, 46, 0.14);
  --mz-titlech-ink: #A8801F;
  --mz-goalfill: linear-gradient(90deg, #FF9A78, #FF5B36);
  --mz-wash-band: linear-gradient(150deg, #FFEDE4, #FFF8F4);
  /* Edzés hub (mezo-d20.3.1) — prototype edzes-body hub hero + .coach hexes verbatim */
  --mz-wash-trainhero: linear-gradient(140deg, #FFE7DC, #FFFFFF 70%);
  --mz-coach-bg: #FFF4EF;
  /* Fuel hub (mezo-d20.4.1) — prototype fuel-head/body .wtile + .mezotile hexes verbatim.
     The MOST ring keeps its saturated coral in BOTH themes (the .mz-w-most precedent). */
  --mz-fh-now-ring: #FF6B4A;
  --mz-fh-miss-bd: rgba(201, 150, 46, 0.55);
