  --mz-wk-sub-nutrition: #8FAF7E;
  --mz-wk-sub-quality: var(--mz-hl-gold);
  --mz-wk-sub-training: #FF6B4A;
  --mz-wk-sub-sleep: #9B8FC4;
  --mz-wk-sub-logging: #C46FA0;
  --mz-wk-sub-rhythm: #4E8FB8;
  --mz-wk-bar-sage: linear-gradient(90deg, #A9C69A, #8FAF7E);
  --mz-wk-thin-bg: rgba(255, 255, 255, 0.5);
  --mz-wk-navt-bg: rgba(255, 255, 255, 0.7);
  /* Heti · tanulságok + felfedezések (mezo-d20.6.10) — en-body.html .lesst / .dsct /
     .ghost hexes verbatim. The prediction tile's wash is the lighter sage the
     prototype uses there, which is already tokenized as --mz-qdone-bg. */
  --mz-wkl-off-bg: rgba(255, 255, 255, 0.5);
  --mz-wkl-ghost-bg: rgba(255, 255, 255, 0.55);
  --mz-ghostbtn-bg: rgba(43, 33, 24, 0.06);
  --mz-wkd-life-ink: #33749C;
  --mz-wkd-glow-lav: rgba(93, 79, 160, 0.4);
  --mz-wkd-glow-gold: rgba(181, 126, 20, 0.4);
  --mz-wkd-glow-sky: rgba(78, 143, 184, 0.4);
  --mz-wkd-glow-rose: rgba(142, 63, 111, 0.38);
  --mz-wkd-glow-sage: rgba(110, 139, 94, 0.4);
  --mz-fh-now-shadow: 0 24px 40px -17px rgba(255, 107, 74, 0.42), 0 2px 7px rgba(43, 33, 24, 0.05), inset 0 1px 0 rgba(255, 255, 255, 0.85);

  /* Heti hub-csempék (mezo-d20.6.10) — en-body.html hub() inline washes/glows verbatim.
     The four view tiles are LIGHTER than the generic --mz-wash-* family (the hub reads as
     one calm surface with four tinted panes), so they get their own tokens. */
  --mz-wkh-rev-wash:  linear-gradient(150deg, #F3F0FC, #FDFCFF);
  --mz-wkh-rev-bd:    #8A76CC;
  --mz-wkh-rev-glow:  rgba(93, 79, 160, 0.4);
  --mz-wkh-less-wash: linear-gradient(150deg, #FFF1D6, #FFFAF0);
  --mz-wkh-less-glow: rgba(181, 126, 20, 0.4);
  --mz-wkh-days-wash: linear-gradient(150deg, #E9F1E2, #F7FBF3);
  --mz-wkh-days-glow: rgba(110, 139, 94, 0.42);
  --mz-wkh-disc-wash: linear-gradient(150deg, #DFEDF5, #F7FBFD);
  --mz-wkh-disc-glow: rgba(78, 143, 184, 0.4);
  --mz-wkh-dot-pattern:    #8A76CC;
  --mz-wkh-dot-fact:       #C9962E;
  --mz-wkh-dot-life:       #4E8FB8;
  --mz-wkh-dot-memoir:     #C46FA0;
  --mz-wkh-dot-prediction: #8FAF7E;
  --mz-wkh-hair: rgba(43, 33, 24, 0.14);

  /* Receptek v2 (mezo-d20.4.4) — category band gradients (fuel-body.html #page-recept
     card seeds, verbatim) + the NOVA dot ramp. NOVA 4 stays terracotta, never red. */
  --mz-rcp-breakfast-bw: #F6E7C6; --mz-rcp-breakfast-bd: #C9962E; --mz-rcp-breakfast-shadow: rgba(201, 150, 46, 0.4);
  --mz-rcp-lunch-bw:     #FFE3D8; --mz-rcp-lunch-bd:     #E05535; --mz-rcp-lunch-shadow:     rgba(224, 85, 53, 0.4);
  --mz-rcp-dinner-bw:    #FAE3ED; --mz-rcp-dinner-bd:    #C46FA0; --mz-rcp-dinner-shadow:    rgba(196, 111, 160, 0.4);
  --mz-rcp-snack-bw:     #E4EEDD; --mz-rcp-snack-bd:     #8FAF7E; --mz-rcp-snack-shadow:     rgba(143, 175, 126, 0.4);
  --mz-nova-1:   #8FAF7E;
  --mz-nova-mid: #C9962E;
  --mz-nova-4:   #A8462E;

  /* Nap hub 1:1 audit (mezo-d20.11) — nap-head.html tile internals: the water
     bar's track/fill, the sage tick fill and the „nehéz nap" horgony wash. */
  --mz-water-track: #D8E7F0;
  --mz-water-fill:  linear-gradient(90deg, #7FB6D9, #4E8FB8);
  --mz-tickfill:    linear-gradient(135deg, #8FAF7E, #6E8B5E);
  --mz-wash-anchor: linear-gradient(140deg, #F7EEE2, #FFFBF6 75%);

  /* Emberek S3 hub (mezo-06o0.2) — tone + context tints, en-body.html emberek-body.html's
     `TONES`/`CTX` IIFE objects verbatim. `baratok`/`egyeb` have no prototype color (the
     prototype's CTX only lists 6 of the 8 MentionContext values) — picked in-family. */
  --ppl-tone-jo:     #7FA06C;
  --ppl-tone-ok:     #B5AA9C;
  --ppl-tone-vegyes: #C9962E;
  --ppl-tone-nehez:  #C4694F;
  --ppl-ctx-munka:         #4E8FB8;
  --ppl-ctx-csalad:        #8FAF7E;
  --ppl-ctx-baratok:       #B5AA9C;
  --ppl-ctx-edzes:         #FF7A55;
  --ppl-ctx-konfliktus:    #C9962E;
  --ppl-ctx-kozos-program: #C46FA0;
  --ppl-ctx-segitseg:      #6C5FA3;
  --ppl-ctx-egyeb:         #8A7A6A;
  /* Életcél-rendszer (mezo-iizd) — PERMAH dimension surface hexes. Tokenized here (rather
     than inlined on the .lg-d-* rules below in the Mozaik section) so the Mozaik section
     stays hex-free outside :root (mozaikCssTokens.test.ts's "no hardcoded light-surface
     hexes outside :root token definitions" guard, mezo-d20.1.5). */
  --lg-p-dc: #A8801F; --lg-p-dw: #FDF0DA; --lg-p-dw2: #FFFCF5;
  --lg-e-dc: #5D4FA0; --lg-e-dw: #EBE6F8; --lg-e-dw2: #F9F6FE;
  --lg-r-dc: #8E3F6F; --lg-r-dw: #FAE3ED; --lg-r-dw2: #FEF8FB;
  --lg-m-dc: #A84A26; --lg-m-dw: #FFE7DC; --lg-m-dw2: #FFF7F2;
  --lg-a-dc: #3E7396; --lg-a-dw: #DFEDF5; --lg-a-dw2: #F5FAFD;
  --lg-h-dc: #4E6B42; --lg-h-dw: #E9F1E2; --lg-h-dw2: #F7FBF3;
  --lg-white: #FFFFFF;
  --lg-wk7-p2: #E5C46B;
  --lg-why-bg: #FFF2EA;
  /* Wizard (Task 11, mezo-iizd.1) — the extrinsic-frame warning wash and the
     "on" success washes (pillar toggle · ha–akkor plan), hoisted here so the
     mozaikCssTokens hex guard sees no raw D/E/FF hex in the wizard rules below. */
  --lg-frame-warn: #FFF1D6;
  --lg-frame-warn2: #FFFCF4;
  --lg-ok-wash: #EEF4E8;
  /* Hét/Hónap chip "on" wash (Task 9, mezo-iizd.5) — same hoisting reason as the wizard
     washes above: the mozaikCssTokens hex guard flags raw D/E/FF hex outside :root. */
  --lg-fchip-on: #FFEDE5;
  /* Dark-mód tokenizálás (mezo-hhdo): a kártya-alap, a vonalak, a chip-hátterek, a
     pötty-alapszín és a nyíl/akcentus tinták eddig hardkódolt világos értékek voltak a
     szabályokban — sötétben fehér kártya + majdnem fehér szöveg lett belőlük. Mostantól
     mind token, és mind kap dark párt; a mozaikCssTokens teszt őrzi, hogy így maradjon. */
  --lg-hairline: rgba(43,33,24,0.06);
  --lg-hairline-2: rgba(43,33,24,0.14);
  --lg-inset-hi: rgba(255,255,255,0.85);
  --lg-chipbg: rgba(43,33,24,0.06);
  --lg-dot-idle: rgba(43,33,24,0.12);
  --lg-ok-ink: #6E8B5E;
  --lg-ok-ink2: #8FAF7E;
  --lg-ink-coral: #A84A26;
  --lg-ink-amber: #A8801F;
  --lg-arrow-up: #4E6B42;
  --lg-arrow-down: #A8801F;
  --lg-hero-wash: #F2F7EC;
  --lg-dot-partial2: #C9962E;
  --lg-link-ink: #3E7396;
  --lg-link-bg: rgba(78,143,184,0.14);
  --lg-input-bg: #FDFAF4;
  --lg-ok-wash2: #FBFDF9;
}

/* ===== Dark mode · "Pulse" warm graphite — DS stop overrides =====
   The ramp inverts its text logic in dark: bg/soft darken into tinted graphite,
   base LIFTS, and deep lifts LIGHTER than base — "deep" stays the stop you write
   text with in both themes (never reuse a light deep on graphite). */
:root[data-theme="dark"] {
  --primary-bg:    #33231D;
  --primary-soft:  #4A2E24;
  --primary-base:  #FF7E5C;
  --primary-hover: #FF9377;
  --primary-deep:  #F0966B;

  --secondary-bg:    #2A2521;
  --secondary-soft:  #AFA294;
  --secondary-base:  #D8CEC2;
  --secondary-hover: #F5EFE6;
  --secondary-deep:  #FAF6EF;

  --accent-bg:    #2E2718;
  --accent-soft:  #3E3420;
  --accent-base:  #E3B565;
  --accent-hover: #EFC57F;
  --accent-deep:  #F2D094;

  --success-bg:    #1F2A1F;
  --success-soft:  #2A3A2A;
  --success-base:  #8FB49A;
  --success-hover: #9FC0A8;
  --success-deep:  #A9C79A;

  --warning-bg:    #332B16;
  --warning-soft:  #453A1E;
  --warning-base:  #FFBE60;
  --warning-hover: #FFCB7E;
  --warning-deep:  #F6D492;

  --error-bg:    #33201C;
  --error-soft:  #452A24;
  --error-base:  #F08A85;
  --error-hover: #F5A19D;
  --error-deep:  #F7B3AE;

  --surface-page:     #141210; /* mezo-nn7h0: near-black warm graphite (was #000) */
  --surface-card:     #221E1B;
  --surface-elevated: #2A2521;
  --surface-recess:   rgba(245, 239, 230, 0.05);
  --mz-ntfscrim:      rgba(0, 0, 0, 0.42);

  --text-primary:   #F5EFE6;
  --text-secondary: #D8CEC2; /* mezo-nn7h0: lifted for legibility (was #B7A899) */
  --text-muted:     #AFA294; /* mezo-nn7h0: lifted for legibility (was #8A7A6A) */
  --text-disabled:  #5E5348;
  --text-inverse:   #191614;

  --divider: rgba(245, 239, 230, 0.07);

  --dv-coral: #FF7E5C;
  --dv-sage:  #8FB49A;
  --dv-lav:   #AB9FD2;
  --dv-rose:  #E98D9D;
  --dv-sky:   #7FB2DE;
  --dv-amber: #FFBE60;

  --cta-g1: #FF8A66;
  --cta-g2: #FF6B47;

  --shadow-focus: 0 0 0 3px rgba(255, 126, 92, 0.38);
  /* ── Mozaik 2.0 dark ("Pulse") — washes/cells/tones derived from the dv dark
        ramp mixed onto the warm-graphite surfaces (mezo-d20.1.5). */
  --mz-wash-coral: linear-gradient(150deg, color-mix(in srgb, var(--dv-coral) 18%, var(--surface-card)), color-mix(in srgb, var(--dv-coral) 6%, var(--surface-page)));
  --mz-wash-sage:  linear-gradient(150deg, color-mix(in srgb, var(--dv-sage) 18%, var(--surface-card)), color-mix(in srgb, var(--dv-sage) 6%, var(--surface-page)));
  --mz-wash-sky:   linear-gradient(150deg, color-mix(in srgb, var(--dv-sky) 18%, var(--surface-card)), color-mix(in srgb, var(--dv-sky) 6%, var(--surface-page)));
  --mz-wash-gold:  linear-gradient(150deg, color-mix(in srgb, var(--dv-amber) 16%, var(--surface-card)), color-mix(in srgb, var(--dv-amber) 5%, var(--surface-page)));
  --mz-wash-lav:   linear-gradient(150deg, color-mix(in srgb, var(--dv-lav) 18%, var(--surface-card)), color-mix(in srgb, var(--dv-lav) 6%, var(--surface-page)));
  --mz-wash-rose:  linear-gradient(150deg, color-mix(in srgb, var(--dv-rose) 16%, var(--surface-card)), color-mix(in srgb, var(--dv-rose) 5%, var(--surface-page)));
  --mz-wash-white: var(--surface-card);
  --mz-shadow:      0 17px 31px -17px rgba(0, 0, 0, 0.55), 0 2px 6px rgba(0, 0, 0, 0.3), inset 0 1px 0 rgba(255, 255, 255, 0.06);
  --mz-shadow-sage: var(--mz-shadow);
  --mz-shadow-sky:  var(--mz-shadow);
  --mz-shadow-gold: var(--mz-shadow);
  --mz-shadow-lav:  var(--mz-shadow);
  --mz-shadow-rose: var(--mz-shadow);
  --mz-shadow-most: 0 24px 40px -17px color-mix(in srgb, var(--dv-coral) 45%, transparent), 0 2px 7px rgba(0, 0, 0, 0.35), inset 0 1px 0 rgba(255, 255, 255, 0.08);
  --mz-cell-sage-bg: color-mix(in srgb, var(--dv-sage) 20%, var(--surface-card));  --mz-cell-sage-ink: var(--dv-sage);
  --mz-cell-coral-bg: color-mix(in srgb, var(--dv-coral) 20%, var(--surface-card)); --mz-cell-coral-ink: var(--primary-deep);
  --mz-cell-amber-bg: color-mix(in srgb, var(--dv-amber) 18%, var(--surface-card)); --mz-cell-amber-ink: var(--dv-amber);
  --mz-cell-lav-bg: color-mix(in srgb, var(--dv-lav) 20%, var(--surface-card));   --mz-cell-lav-ink: var(--dv-lav);
  --mz-cell-sky-bg: color-mix(in srgb, var(--dv-sky) 20%, var(--surface-card));   --mz-cell-sky-ink: var(--dv-sky);
  --mz-cell-rose-bg: color-mix(in srgb, var(--dv-rose) 18%, var(--surface-card));  --mz-cell-rose-ink: var(--dv-rose);
  --mz-cell-gold-bg: color-mix(in srgb, var(--dv-amber) 22%, var(--surface-card)); --mz-cell-gold-ink: var(--dv-amber);
  --mz-tone-coral: color-mix(in srgb, var(--dv-coral) 24%, var(--surface-page));
  --mz-tone-gold:  color-mix(in srgb, var(--dv-amber) 22%, var(--surface-page));
  --mz-tone-lav:   color-mix(in srgb, var(--dv-lav) 24%, var(--surface-page));
  --mz-tone-rose:  color-mix(in srgb, var(--dv-rose) 22%, var(--surface-page));
  --mz-tone-sage:  color-mix(in srgb, var(--dv-sage) 22%, var(--surface-page));
  --mz-tone-sky:   color-mix(in srgb, var(--dv-sky) 22%, var(--surface-page));
  --mz-goal-hero-nutrition: radial-gradient(circle at 88% 17%, rgba(255,255,255,.08), transparent 18%), linear-gradient(145deg, color-mix(in srgb, var(--dv-sage) 22%, var(--surface-card)), color-mix(in srgb, var(--dv-amber) 8%, var(--surface-page)));
  --mz-goal-hero-segment: radial-gradient(circle at 87% 17%, rgba(255,255,255,.08), transparent 18%), linear-gradient(145deg, color-mix(in srgb, var(--dv-lav) 24%, var(--surface-card)), color-mix(in srgb, var(--dv-sky) 8%, var(--surface-page)));
  --mz-goal-hero-plans: radial-gradient(circle at 91% 18%, rgba(255,255,255,.08), transparent 18%), linear-gradient(145deg, color-mix(in srgb, var(--dv-sky) 20%, var(--surface-card)), color-mix(in srgb, var(--dv-sage) 10%, var(--surface-page)));
  --mz-goal-hero-guards: radial-gradient(circle at 87% 17%, rgba(255,255,255,.08), transparent 18%), linear-gradient(145deg, color-mix(in srgb, var(--dv-coral) 22%, var(--surface-card)), color-mix(in srgb, var(--dv-amber) 8%, var(--surface-page)));
  --mz-goal-hero-settings: radial-gradient(circle at 87% 17%, rgba(255,255,255,.08), transparent 18%), linear-gradient(145deg, color-mix(in srgb, var(--dv-sky) 20%, var(--surface-card)), color-mix(in srgb, var(--dv-sage) 8%, var(--surface-page)));
  --mz-goal-emblem: linear-gradient(145deg, color-mix(in srgb, var(--surface-elevated) 90%, transparent), color-mix(in srgb, var(--surface-card) 52%, transparent));
  --mz-cellbg: color-mix(in srgb, var(--surface-card) 72%, transparent);
  --mz-chipbg: color-mix(in srgb, var(--surface-elevated) 80%, transparent);
  --mz-stripbg: var(--surface-card);
  /* ── Életcél (lg-*) dark párok (mezo-hhdo) ──────────────────────────────────────
     A hat PERMAH-dimenzió a ház hat --dv-* színcsaládjára képez, így a mosás ugyanazzal
     a color-mix idiómával készül, amit a --mz-cell-*-bg tokenek is használnak fölötte —
     nem kitalált hexek. A tinta a --dv-* élénk változat, ami sötét alapon olvasható. */
  --lg-p-dc: var(--dv-amber); --lg-p-dw: color-mix(in srgb, var(--dv-amber) 22%, var(--surface-card)); --lg-p-dw2: color-mix(in srgb, var(--dv-amber) 9%, var(--surface-card));
  --lg-e-dc: var(--dv-lav);   --lg-e-dw: color-mix(in srgb, var(--dv-lav) 24%, var(--surface-card));   --lg-e-dw2: color-mix(in srgb, var(--dv-lav) 10%, var(--surface-card));
  --lg-r-dc: var(--dv-rose);  --lg-r-dw: color-mix(in srgb, var(--dv-rose) 22%, var(--surface-card));  --lg-r-dw2: color-mix(in srgb, var(--dv-rose) 9%, var(--surface-card));
  --lg-m-dc: var(--dv-coral); --lg-m-dw: color-mix(in srgb, var(--dv-coral) 22%, var(--surface-card)); --lg-m-dw2: color-mix(in srgb, var(--dv-coral) 9%, var(--surface-card));
  --lg-a-dc: var(--dv-sky);   --lg-a-dw: color-mix(in srgb, var(--dv-sky) 22%, var(--surface-card));   --lg-a-dw2: color-mix(in srgb, var(--dv-sky) 9%, var(--surface-card));
  --lg-h-dc: var(--dv-sage);  --lg-h-dw: color-mix(in srgb, var(--dv-sage) 24%, var(--surface-card));  --lg-h-dw2: color-mix(in srgb, var(--dv-sage) 10%, var(--surface-card));
  --lg-white: var(--surface-card);
  --lg-wk7-p2: var(--dv-amber);
  --lg-why-bg: color-mix(in srgb, var(--dv-coral) 16%, var(--surface-card));
  --lg-frame-warn: color-mix(in srgb, var(--dv-amber) 20%, var(--surface-card));
  --lg-frame-warn2: color-mix(in srgb, var(--dv-amber) 8%, var(--surface-card));
  --lg-ok-wash: color-mix(in srgb, var(--dv-sage) 20%, var(--surface-card));
  --lg-fchip-on: color-mix(in srgb, var(--dv-coral) 20%, var(--surface-card));
  --lg-hairline: rgba(245,239,230,0.10);
  --lg-hairline-2: rgba(245,239,230,0.20);
  --lg-inset-hi: rgba(255,255,255,0.05);
  --lg-chipbg: rgba(245,239,230,0.10);
  --lg-dot-idle: rgba(245,239,230,0.16);
  --lg-ok-ink: var(--dv-sage);
  --lg-ok-ink2: var(--dv-sage);
  --lg-ink-coral: var(--dv-coral);
  --lg-ink-amber: var(--dv-amber);
  --lg-arrow-up: var(--dv-sage);
  --lg-arrow-down: var(--dv-amber);
  --lg-hero-wash: color-mix(in srgb, var(--dv-sage) 18%, var(--surface-card));
  --lg-dot-partial2: var(--dv-amber);
  --lg-link-ink: var(--dv-sky);
  --lg-link-bg: color-mix(in srgb, var(--dv-sky) 20%, transparent);
  --lg-input-bg: var(--surface-elevated);
