/* ===== Legacy alias bridge — Deep-Current / early-token names → DS tokens =====
   Aliases only; each resolves against a THEMED DS token, so the dark override
   block below carries only the few literals with no DS slot. Retired in P9. */
:root {
  /* Canvas / surfaces */
  --canvas: var(--surface-page);
  --surface-1: var(--surface-card);
  --surface-2: var(--secondary-bg);
  --surface-3: #EFE5D8;                    /* no DS slot — literal, dies in P9 */
  --surface-glass: rgba(0, 0, 0, 0.03);

  --border-subtle: var(--divider);
  --border-strong: rgba(43, 33, 24, 0.18);

  /* Text — the primary/secondary/inverse names ARE the DS names already */
  --text-tertiary: var(--text-muted);
  --text-quaternary: var(--text-disabled);

  /* Semantic — resolve through the Napív aliases further down */
  --success: var(--sage-deep);
  --warning: var(--amber-deep);
  --error: var(--error-base);
  --info: var(--sky);

  /* Pattern category palette — re-pointed onto Napív domain accents (1:1, spec §3.1) */
  --cat-physiology: var(--sky);
  --cat-preference: var(--lav-deep);
  --cat-trigger:    var(--amber-deep);
  --cat-response:   var(--sage-deep);
  --cat-tendency:   var(--rose);
  --cat-goal-state: var(--coral-deep);

  --tool-read:    var(--lav);
  --tool-compute: var(--amber-deep);
  --tool-write:   var(--coral);

  /* Sleep-phase accents (mezo-fk9a) — aliases, so the dark swap carries them. */
  --ph-deep:  var(--lav-deep);
  --ph-light: var(--sky);
  --ph-rem:   var(--rose);
  --ph-awake: var(--faint);

  /* Medication cycle phase gradient stops — sage→amber ramp (light gradient, shared by both themes) */
  --medcycle-d1: #7FA48A; --medcycle-d2: #8FAC7E; --medcycle-d3: #A3B272; --medcycle-d4: #BCB466;
  --medcycle-d5: #D6B25B; --medcycle-d6: #EBB250; --medcycle-d7: #FFB347;   /* sage→amber ramp */

  /* AnchorMode (light, warmer) */
  --anchor-canvas:  #FBF4EC;
  --anchor-surface: #F4E7D6;
  --anchor-accent:  #B45309;
  --anchor-text:    #3A2A1A;

  /* Legacy spacing names → DS scale (values identical except --sp-xl: the DS
     scale has no 20px slot, so it stays a literal until its call sites migrate) */
  --sp-xs: var(--sp-1);  --sp-sm: var(--sp-2);  --sp-md: var(--sp-3);
  --sp-lg: var(--sp-4);  --sp-xl: 20px;         --sp-2xl: var(--sp-5);
  --sp-3xl: var(--sp-6); --sp-4xl: var(--sp-7); --sp-5xl: var(--sp-9);

  /* Desktop phone-frame backdrop (outside the DS scope — the app shell chrome) */
  --page-bg: #E6E1D8;
  --card-elevation: drop-shadow(0 1px 2px rgba(43, 33, 24, 0.06)) drop-shadow(0 4px 10px rgba(43, 33, 24, 0.07));
  --card-border: rgba(43, 33, 24, 0.10);
  --page-glow: #F0EBE2;
}

/* Legacy dark literals — ONLY the bridge tokens with no DS slot. Every alias
   above resolves against the Pulse DS block and needs no line here. */
:root[data-theme="dark"] {
  --surface-3: #332D27;
  --surface-glass: rgba(245, 239, 230, 0.05);
  --border-strong: rgba(245, 239, 230, 0.14);

  /* AnchorMode (kept: consumers — the .anch* family + train.ts's recovery template;
     VulnerabilityCard moved onto the primary ramp in mezo-setx.5.1) */
  --anchor-canvas:  #14110E;
  --anchor-surface: #1F1915;
  --anchor-accent:  #D97757;
  --anchor-text:    #E8DDD3;

  /* Page/card literals — warm-graphite tuned (previously cool navy) */
  --page-bg: #100D0B;
  --card-elevation: none;
  --card-border: var(--border-subtle);
  --page-glow: #17130F;
}

* { box-sizing: border-box; margin: 0; padding: 0; -webkit-font-smoothing: antialiased; }

html, body {
  background: var(--page-bg);
  color: var(--text-primary);
  font-family: var(--ff-body);
  font-size: 14px;
  line-height: 1.5;
  min-height: 100vh;
  overflow: hidden;
  /* Belt-and-suspenders: the document layer must never rubber-band (the .app-root is
     position:fixed so the page can't scroll, but this guards against any future scroller). */
  overscroll-behavior: none;
}

/* Native-app feel: scrollbars are never shown anywhere (scrolling is untouched).
   `width: 0` alone does not suppress macOS overlay scrollbars in Safari — only
   `display: none` does; `scrollbar-width` covers Firefox. */
* { scrollbar-width: none; }
*::-webkit-scrollbar { display: none; width: 0; height: 0; }

button { font-family: inherit; color: inherit; background: none; border: none; cursor: pointer; }
/* Disabled baseline (mezo-l3on fix-round-3, F4): a bare `disabled` button otherwise looks
   identical to an active one (full opacity, pointer cursor) — e.g. the pending-mode
   SetEditSheet's read-only ± steppers read as broken rather than intentionally locked.
   Lower specificity than `.pagerbar .pg:disabled`/`.hab-act:disabled` (element vs.
   class selectors), so those two keep their own already-tuned disabled look untouched. */
button:disabled { opacity: .45; cursor: default; }
/* The opacity above applies everywhere unopposed (neither of these rules sets it), but
   `.steprow .stepper .b`/`button.n` and `.rirrow button` each redundantly hardcode their
   OWN unconditional `cursor: pointer` at equal-or-higher specificity than the bare rule
   above — exactly the controls the pending-mode SetEditSheet disables — so the cursor
   half needs these three explicit companions to actually take effect there. */
.steprow .stepper .b:disabled,
.steprow .stepper button.n:disabled,
.rirrow button:disabled { cursor: default; }
input, textarea { font-family: inherit; color: inherit; background: none; border: none; outline: none; }

.app-root {
  position: fixed; inset: 0;
  display: flex; align-items: center; justify-content: center;
  background: radial-gradient(ellipse at center, var(--page-glow) 0%, var(--page-bg) 70%);
}

/* ============== iPhone 17 Pro Max frame ============== */
.phone {
  position: relative;
  width: 440px; height: 956px;
  border-radius: 56px;
  background: #000;
  padding: 12px;
  box-shadow:
    0 0 0 2px #0a0a0a inset,
    0 0 0 8px #1a1a1a,
    0 40px 100px rgba(0, 0, 0, 0.8);
  flex-shrink: 0;
}
.phone-screen {
  position: relative;
  width: 100%; height: 100%;
  background: var(--canvas);
  border-radius: 44px;
  overflow: hidden;
  display: flex; flex-direction: column;
}
/* AnchorMode canvas: no longer a dedicated skin — it now sits on the same canvas as the
   current daypart (desaturated via the .sky rule below), per the Napiv redesign spec. */

/* Dynamic Island */
.dynamic-island {
  position: absolute;
  top: 11px; left: 50%; transform: translateX(-50%);
  width: 124px; height: 37px;
  background: #000;
  border-radius: 20px;
  z-index: 100;
}

/* Status bar */
.status-bar {
  position: absolute; top: 0; left: 0; right: 0;
  height: 54px;
  display: flex; align-items: center; justify-content: space-between;
  padding: 18px 32px 0;
  font-family: var(--ff-body);
  font-size: 17px; font-weight: 600;
  color: var(--text-primary);
  z-index: 50;
  pointer-events: none;
  background: var(--canvas);
}
.status-icons { display: flex; align-items: center; gap: 6px; }
.status-icons svg { width: 18px; height: 18px; fill: var(--text-primary); }

/* Screen content (scrolls under notch + above tab bar) */
.screen-content {
  flex: 1;
  overflow-y: auto;
  overflow-x: hidden;
  /* The single app scroller. overscroll-behavior-y:none suppresses the iOS rubber-band
     bounce + scroll-chain at the top/bottom edge (the reported "drag the page down at the
     very top" bug) while leaving all in-range scrolling untouched. */
  overscroll-behavior-y: none;
  -webkit-overflow-scrolling: touch;
  padding-top: 54px;
  padding-bottom: var(--screen-bottom-pad);
  padding-inline: var(--screen-gutter);
  scroll-behavior: smooth;
  position: relative;
}
/* Sticky page chrome (breadcrumb/back rows) — pins below the fake status bar
   while the content scrolls under it, like native app navigation chrome. */
.sticky-top {
  position: sticky;
  /* NEM 0 és NEM 54px: a .screen-content padding-topja (54px) továbbra is a fake
     státuszsáv alá offsetel, de a shell-fejléc (mezo-8az6) mostantól maga is kitapad
     ugyanoda — a lap chrome-ja ezért a KOMPAKT fejléc magasságával (--mzh-head-cond-h)
     lejjebb tapad ki, hogy ne csússzon a shell-fejléc alá. Ez CSAK akkor igaz, ha van
     shell-fejléc: a chrome nélküli oldalakon (AppLayout.tsx hideChrome) nincs mi alá
     tapadni, ott a 0 a helyes — innen a :has() scope. */
  top: 0;
  z-index: 40;
  background: var(--canvas);
}
.screen-content:has(.app-head) .sticky-top { top: var(--mzh-head-cond-h); }

/* Lock background scroll when a sheet/modal (or the SubNavDropdown popover, whose
   backdrop is portaled into .phone-screen the same way) is open. GlassBox
   (.gl-backdrop) is portaled into .phone-screen the same way (mezo-88iwa.13
   fix round 1) and must lock scroll too. */
.phone-screen:has(.sheet-backdrop, .dd-backdrop, .gl-backdrop) .screen-content {
  overflow: hidden !important;
  touch-action: none;
}

/* Bottom tab bar */
.tab-bar {
  position: absolute; bottom: 0; left: 0; right: 0;
  height: 88px;
  padding: 8px 12px 28px;
  /* Fully opaque + theme-aware (matches .status-bar / .sticky-top) so scrolled
     content can never bleed through the bar. The old translucent frosted-glass
     bar (rgba(10,15,20,0.92) + blur) still leaked ~8% and was hardcoded dark, so
     it broke in light theme too — see mezo-ci5. */
  background: var(--canvas);
  border-top: 1px solid var(--border-subtle);
  display: flex; align-items: stretch; justify-content: space-around;
  z-index: 40;
}
.tab-item {
  flex: 1;
  display: flex; flex-direction: column; align-items: center; justify-content: center;
  gap: 2px;
  /* Design 2.0 .mtab recipe (mezo-d20.1.1): sentence-case label, clay icon above;
     active speaks text-safe coral, inactive mutes the clay via filter. */
  font-family: var(--ff-body);
  font-size: 11px;
  font-weight: 600;
  color: var(--text-secondary);
  transition: color var(--duration-fast) var(--ease-out);
  position: relative;
}
.tab-item.active { color: var(--primary-deep); }   /* text-safe coral (DS active tab) */
.tab-item .tab-ico { display: grid; place-items: center; }
.tab-item:not(.active) .tab-ico svg { filter: grayscale(1) brightness(1.04) opacity(0.48); }
.tab-item svg { transition: filter var(--duration-normal) var(--ease-out); }

/* Avatar-only domain switch: keep the companion in full colour. */
.tab-item.domain-switch {
  border: none; background: none; cursor: pointer; padding: 0;
  font: inherit;
}
.tab-item.domain-switch .tab-ico svg { filter: none; }


/* Recipe editor save/cancel bar (mezo-3vu4). Portaled into .phone-screen so it
   anchors to the device viewport like .sheet — floating just above the tab bar,
   NOT scrolling with (or clipping) the recipe content. Opaque var(--canvas):
   the old translucent blur leaked + broke light theme (mezo-ci5). */
.recipe-save-bar {
  position: absolute;
  left: 0; right: 0;
  bottom: 92px; /* above the floating tab-bar capsule (top edge ≈78px on desktop; 92px leaves 14px clearance) */
  z-index: 45;  /* above tab-bar (40), below sheets (200+) so the picker covers it */
  display: flex;
  gap: 9px;
  padding: 12px 16px;
  background: var(--canvas);
  border-top: 1px solid var(--border-subtle);
}

/* ===== FloatingReturnLayer (mezo-78sd) — session⇄chat quick-return chrome =====
   Mounted once in AppLayout. z 45: above the tab-bar capsule (40), below sheets
   (200+) so any open sheet's backdrop covers it. */
.float-stack {
  position: absolute; right: 14px;
  bottom: 158px; /* above the quick-log FAB: its 92px seat + 56px + 10px gap (mezo-d20.1.1) */
  display: flex; flex-direction: column; /* bottom-anchored container: the chat bubble (last child) keeps its spot, the train FAB grows upward above it */
  align-items: center; gap: 10px;
  z-index: 45;
}
/* The session screen has no tab bar and no docked bottom chrome (the "Szett kész"
   CTA and the .restbar are inline in the card flow) — the bubble drops to the corner. */
.float-stack-session { bottom: 24px; }
.float-fab {
  position: relative;
  width: 52px; height: 52px; border-radius: 50%; border: none; cursor: pointer;
  display: flex; align-items: center; justify-content: center; color: #fff;
}
/* Lavender = the companion's voice (--lav ramp). Literal gradient stops on purpose —
   like --gradient-cta — so the bubble reads identically in light and dark (the
   dark-theme --lav-deep flip is a TEXT-contrast stop, not a surface color). */
.float-fab-chat {
  background: linear-gradient(135deg, #9B8FC4, #7A6DA8);
  box-shadow: 0 10px 24px color-mix(in srgb, #7A6DA8 40%, transparent);
}
.float-fab-train { background: var(--gradient-cta); box-shadow: var(--shadow-cta); }
.float-fab-badge {
  position: absolute; top: -4px; right: -4px;
  min-width: 20px; height: 20px; padding: 0 5px;
  border-radius: 999px; background: var(--surface-card); color: var(--coral-deep);
  font: 800 11px/20px var(--ff-body); text-align: center;
  box-shadow: 0 1px 4px rgba(0, 0, 0, .18);
}
/* Chat route: the return-to-workout bar floats just above the sticky composer.
   The offset is empirical (browser-measured): the composer's sticky `bottom` resolves
   inside the scroller, not against .phone-screen, so pad + composer-height is not enough
   — pad + 88px lands the bar ~10px above the COLLAPSED composer's top edge.
   z 19, deliberately UNDER the composer (20), off the floating-bar 45 tier: the auto-grow
   textarea (mezo-a837) raises the composer up to ~104px tall while typing, and the opaque
   composer sliding OVER the bar beats the bar covering the text being typed. */
.float-return {
  position: absolute; left: 14px; right: 14px;
  bottom: calc(var(--screen-bottom-pad) + 88px);
  z-index: 19; height: 52px; border-radius: 999px; border: none; cursor: pointer;
  display: flex; align-items: center; gap: 10px; padding: 0 8px 0 18px;
  background: var(--gradient-cta); color: #fff; box-shadow: var(--shadow-cta);
  font-family: inherit; text-align: left;
}
.float-return-text { flex: 1; min-width: 0; display: flex; flex-direction: column; gap: 1px; }
.float-return-title { font-size: 13.5px; font-weight: 700; }
.float-return-meta {
  font-size: 11px; font-weight: 500; opacity: .85;
  white-space: nowrap; overflow: hidden; text-overflow: ellipsis;
}
.float-return-go {
  flex: none; width: 36px; height: 36px; border-radius: 50%;
  background: rgba(255, 255, 255, .22);
  display: flex; align-items: center; justify-content: center;
}
@keyframes float-pop { from { transform: scale(.6); opacity: 0; } to { transform: scale(1); opacity: 1; } }
@media (prefers-reduced-motion: no-preference) {
  .float-fab-train, .float-return { animation: float-pop var(--duration-normal) var(--np-ease-spring); }
}
/* Real device / installed PWA: track the lifted tab bar the way .recipe-save-bar does. */
@media (max-width: 519px), (display-mode: standalone), (display-mode: fullscreen), (display-mode: minimal-ui) {
  .float-stack { bottom: calc(88px + env(safe-area-inset-bottom)); }
  .float-stack-session { bottom: calc(24px + env(safe-area-inset-bottom)); }
}

/* Home indicator */
.home-indicator {
  position: absolute; bottom: 8px; left: 50%; transform: translateX(-50%);
  width: 134px; height: 5px; background: var(--text-primary);
  opacity: 0.4; border-radius: 3px; z-index: 60;
}

/* ============== Real mobile / installed PWA: full-bleed ==============
   The .phone block above is a desktop *preview* mockup of an iPhone 17 Pro Max
   (bezel, fake Dynamic Island, fake status bar, fake home indicator). On a real
   phone — any viewport too narrow to hold the 440px frame, OR an installed
   standalone/fullscreen PWA — we drop the mockup chrome and let the app fill the
   screen, deferring to the device's real island/notch and home bar via
   safe-area insets (the index.html viewport uses viewport-fit=cover). */
@media (max-width: 519px),
       (display-mode: standalone),
       (display-mode: fullscreen),
       (display-mode: minimal-ui) {
  html, body { background: var(--canvas); }

  .app-root { display: block; background: var(--canvas); }

  .phone {
    width: 100%; height: 100%;
    border-radius: 0;
    padding: 0;
    box-shadow: none;
  }
  .phone-screen { border-radius: 0; }

  /* The real device renders these — hide the mockups to avoid duplicates */
  .dynamic-island,
  .home-indicator,
  .status-bar { display: none; }

  /* Defer to the device's real safe areas instead of the fake chrome heights */
  .screen-content {
    padding-top: env(safe-area-inset-top);
    padding-bottom: calc(96px + env(safe-area-inset-bottom));
  }
  /* A shell-fejléc valódi eszközön is kitapad (mezo-8az6), ezért a lap chrome-ja itt sem
     tapadhat ki 0-nál — ugyanaz a kompakt fejléc-magasság, mint az alapszabályban.
     Ugyanúgy csak fejléces oldalon: lásd az alapszabály :has() scope-ját. */
  .screen-content:has(.app-head) .sticky-top { top: var(--mzh-head-cond-h); }
  .tab-bar {
    height: auto;
    padding-top: 8px;
    padding-bottom: calc(8px + env(safe-area-inset-bottom));
  }
  /* Mobile tab bar is height:auto (~icon+label+pad) + safe area; float above it. */
  .recipe-save-bar {
    bottom: calc(56px + env(safe-area-inset-bottom));
  }
}

/* ============== Common ============== */
.eyebrow {
  /* DS text-eyebrow role: 12 / 700 / 0.22em uppercase (design-system-mezo.html §Typography) */
  font: 700 12px/1 var(--ff-body);
  letter-spacing: .22em; text-transform: uppercase;
  color: var(--faint);
  white-space: nowrap;
}
.eyebrow.brand { color: var(--coral-deep); }
.label-mono {
  font: 700 11px/1.2 var(--ff-body);
  letter-spacing: .06em; text-transform: uppercase;
  color: var(--faint);
  font-variant-numeric: tabular-nums;
  white-space: nowrap;
}
.h-display {
  font-family: var(--ff-display);
  font-weight: 700;   /* DS heading weight (h1/h2 = 700); 800 was the Bricolage look */
  letter-spacing: -0.02em;
  line-height: 1.05;
  color: var(--text-primary);
}
.h-display.size-xl { font-size: 32px; }
.h-display.size-lg { font-size: 24px; }
.h-display.size-md { font-size: 20px; }
.h-display.size-sm { font-size: 16px; }

/* DS text-meta-sm — the Fraunces italic "meta voice" for source lines, empty-state
   subtitles and asides. The idiom was already in use inline at three sites
   (.rz-thin, .creedchip-tx, the paused-plan aside); this is the shared class new
   call sites should reach for (mezo-setx.6.4). Existing sites are left alone —
   retrofitting them is not this bead's job. */
.text-meta-sm { font: italic 500 14px/1.45 var(--ff-serif); }

.page-header {
  padding: 14px 24px 18px;
  display: flex; justify-content: space-between; align-items: flex-end;
}

/* Cards / surfaces */
.card {
  background: var(--surface-1);
  border: 1px solid var(--card-border);
  border-radius: var(--r-2xl);   /* DS card radius (22) */
  filter: var(--card-elevation);
}
.card.glass {
  background: var(--surface-glass);
  backdrop-filter: blur(16px);
}
/* A deactivated-but-still-editable card (the routine editor's inactive chains, mezo-n5e9.2):
   dimmed, not disabled — every control inside stays interactive. */
.card.is-inert { opacity: .55; }
/* Same dimming, for the editor's deactivated def ROWS (not wrapped in a `.card`) — mezo-n5e9.2. */
.row.is-inert { opacity: .55; }

/* Napív inset radii — successors of the retired notch-* tokens for non-card elements (mezo-x3x0) */
.rad-12 { border-radius: 12px; }
.rad-16 { border-radius: 16px; }
.rad-20 { border-radius: 20px; }
.rad-24 { border-radius: 24px; }

/* Chip / tag */
.chip {
  display: inline-flex; align-items: center; gap: 6px;
  padding: 6px 12px;              /* DS chip padding */
  border-radius: var(--r-full);
  font-family: var(--ff-body);
  font-size: 11px; font-weight: 600;
  color: var(--text-secondary);
  background: var(--surface-1);
  border: 1px solid var(--line);
  white-space: nowrap;
}
.toolchip { white-space: nowrap; }
.chip.brand {
  /* DS selected-chip treatment: primary wash + text-safe coral */
  background: var(--primary-bg);
  border-color: var(--primary-base);
  color: var(--primary-deep);
  font-weight: 700;
}
.chip.warning {
  color: var(--warning-hover);
  border-color: var(--warning-soft);
  background: var(--warning-bg);
}
.chip.error {
  color: var(--error-deep);
  border-color: var(--error-soft);
  background: var(--error-bg);
}
/* A toggle chip's pressed state (e.g. the Mesociklusok library's „Összevetés" mode switch)
   — same DS treatment as .segtab[aria-pressed='true'] below, for a plain chip that carries
   no domain-accent override of its own. A chip with its own inline pressed styling (several
   sheet mode-toggles) simply overrides this via specificity/inline style. */
.chip[aria-pressed='true'] {
  background: var(--primary-bg);
  border-color: var(--primary-base);
  color: var(--primary-deep);
  font-weight: 700;
}

/* Tool chip (transparency) */
.toolchip {
  display: inline-flex; align-items: center; gap: 6px;
  padding: 4px 8px;
  font-family: var(--ff-mono);
  font-size: 10px; font-weight: 500;
  border: 1px solid var(--border-subtle);
  border-radius: 12px;
  color: var(--text-secondary);
}
.toolchip.read    { color: var(--lav); border-color: color-mix(in srgb, var(--lav) 32%, transparent); background: color-mix(in srgb, var(--lav) 8%, transparent); }
.toolchip.compute { color: var(--warning); border-color: rgba(245, 158, 11, 0.35); background: rgba(245, 158, 11, 0.05); }
.toolchip.write   { color: var(--coral); border-color: color-mix(in srgb, var(--coral) 32%, transparent); background: color-mix(in srgb, var(--coral) 8%, transparent); }

/* CTA */
.cta-primary {
  width: 100%;
  padding: 16px 20px;
  background: var(--gradient-cta);   /* Rule 9: ONE definition */
  color: #fff;
  border-radius: var(--r-full);
  box-shadow: var(--shadow-cta);
  font-family: var(--ff-body);
  font-size: 16px; font-weight: 700;
  display: inline-flex; align-items: center; justify-content: center; gap: 12px;
  transition: all var(--duration-fast) var(--ease-out);
  white-space: nowrap;
}
.cta-primary:hover { filter: brightness(1.05); }
.cta-primary:active { transform: scale(0.98); }

.cta-ghost {
  padding: 12px 16px;
  border: 1px solid var(--line);
  border-radius: 999px;
  background: var(--warm);
  color: var(--ink);
  font-family: var(--ff-body);
  font-size: 11px; font-weight: 700;
}

/* Progress bar */
.bar {
  position: relative;
  height: 4px; background: var(--surface-2);
  overflow: hidden;
}
.bar-fill {
  position: absolute; left: 0; top: 0; height: 100%;
  background: var(--coral);
  transition: width var(--duration-slow) var(--ease-out);
}
.bar-fill.glow { background: linear-gradient(90deg, var(--coral-deep), var(--coral)); }
.bar-fill.warning { background: var(--warning); }
.bar-fill.error { background: var(--error); }

/* Sheet (bottom modal) */
.sheet-backdrop {
  position: absolute; inset: 0;
  background: rgba(0, 0, 0, 0.5);
  backdrop-filter: blur(4px);
  z-index: 200;
  touch-action: none;
  overscroll-behavior: contain;
  animation: sheet-fade 0.28s ease both;
}
.sheet {
  position: absolute;
  left: 0; right: 0; bottom: 0;
  background: var(--surface-1);
  border-top: 1px solid var(--border-strong);
  border-radius: var(--r-3xl) var(--r-3xl) 0 0;   /* DS sheet radius (28) */
  padding: 4px 20px calc(20px + env(safe-area-inset-bottom));
  z-index: 201;
  overscroll-behavior: contain;
  max-height: 88%;
  overflow-y: auto;
  box-shadow: 0 -20px 60px rgba(0, 0, 0, 0.6);
  /* Slide up from the bottom on mount; `both` keeps the start frame applied
     before the first paint so it never flashes at full position. */
  animation: sheet-rise 0.34s cubic-bezier(0.22, 1, 0.36, 1) both;
  will-change: transform;
}
/* ============================================================
   F7.3 · A sheet-minta (mezo-d20.8.3.1, fuel-mely.html §D)
   One family, one face: every Fuel/Me sheet rides the shared <Sheet> shell, so
   the generation shift happens HERE once — warm Mozaik ground, and the sheets'
   `.card` field containers take the washed mz-qcard face (the border-radius
   drops below the DS 22 to the sheet's tighter 15 rhythm). Component code only
   changes where the prototype drew something specific (score/stack-item hero). */
.sheet { background: var(--mz-sheet-bg); border-top: none; }
.sheet .card {
  background: var(--mz-stripbg);
  border: 0.5px solid rgba(43, 33, 24, 0.06);
  border-radius: 15px;
  filter: none;
  box-shadow: 0 10px 20px -14px rgba(43, 33, 24, 0.28), inset 0 1px 0 rgba(255, 255, 255, 0.85);
}
/* tinted hero band — only where there is something to headline (score, stack-item) */
.mz-sheet-hero {
  display: flex; align-items: center; gap: 12px;
  border-radius: 17px; padding: 11px 13px; margin-bottom: 11px;
  background: var(--mz-wash-sage);
  box-shadow: var(--mz-shadow-sage);
}

@keyframes sheet-rise {
  from { transform: translateY(100%); }
  to   { transform: translateY(0); }
}
@keyframes sheet-fade {
  from { opacity: 0; }
  to   { opacity: 1; }
}
/* Drag-to-dismiss grab zone — wide hit area around the handle */
.sheet-handle-zone {
  display: flex; justify-content: center;
  padding: 12px 0 14px;
  margin: 0 -20px 2px;
  touch-action: none;
  cursor: grab;
}
.sheet-handle-zone:active { cursor: grabbing; }
.sheet-handle {
  width: 28px; height: 3px;                     /* DS drag-handle spec */
  background: var(--border-strong);
  border-radius: var(--r-full);
}
/* Nested sheet (a picker opened on top of another sheet). Lift both the
   nested sheet and its sibling backdrop above the parent sheet (201/200) so
   the picker fully overlays the sheet that launched it. The backdrop is the
   immediate previous sibling of the sheet element in the portal output. */
.sheet.sheet-nested { z-index: 211; }
.sheet-backdrop:has(+ .sheet-nested) { z-index: 210; }
@media (prefers-reduced-motion: reduce) {
  .sheet, .sheet-backdrop { animation-duration: 0.01ms; }
}

/* Toast · DS §Notification (mezo-k5sa) — top-right stack, max 3 visible */
.toast-stack {
  position: absolute;
  top: calc(env(safe-area-inset-top, 0px) + 14px);
  left: auto; right: 14px;
  width: calc(100% - 28px);
  max-width: 296px;
  display: flex;
  flex-direction: column;
  gap: 8px;
  /* The app's real toast tier: above sheets (200/211) and the level-up overlay (250).
     The nominal --z-toast (70) belongs to the DS's abstract ladder (sheet 50 / modal 60 /
     toast 70), which this stylesheet expresses at a different absolute scale — same order,
     different numbers. DS §z-index: "Toast above Modal … must be visible." */
  z-index: 300;
  pointer-events: none;
}
.toast {
  position: relative;
  border-radius: 18px;
  overflow: hidden;
  pointer-events: auto;
  color: #fff;
  background: var(--coral);
  box-shadow: 0 14px 32px rgba(0,0,0,0.42), 0 4px 10px rgba(0,0,0,0.18);
  transform-origin: top right;
  animation: toast-in 420ms cubic-bezier(0.32, 0.72, 0.32, 1);
  transition:
    transform 420ms cubic-bezier(0.32, 0.72, 0.32, 1),
    opacity 420ms cubic-bezier(0.32, 0.72, 0.32, 1);
}
@keyframes toast-in {
  from { transform: translateX(36px) translateY(-4px); opacity: 0; }
  to   { transform: translateX(0) translateY(0); opacity: 1; }
}
/* Stack depth — newest (idx 0) full size, older ones recede. */
.toast[data-idx="1"] { transform: scale(0.96); opacity: 0.78; }
.toast[data-idx="2"] { transform: scale(0.93); opacity: 0.55; }
.toast[data-idx="hidden"] { display: none; }
.toast.is-leaving { transform: translateX(36px); opacity: 0; }

.toast[data-kind="success"] { background: var(--success); }
.toast[data-kind="error"]   { background: var(--error); }
.toast[data-kind="info"]    { background: var(--coral); }

.t-close {
  position: absolute; top: 8px; right: 8px;
  width: 22px; height: 22px;
  border-radius: 50%;
  background: rgba(0,0,0,0.10);
  border: none;
  display: grid; place-items: center;
  cursor: pointer;
  color: rgba(255,255,255,0.60);
}
.t-pad { padding: 12px 14px; }
/* DS caption floor: 14px for sentence-case feedback text */
.t-simple-text { font-size: 14px; font-weight: 600; padding-right: 20px; display: block; }

/* Reward variant — DS §Notification: sage→terracotta gradient card */
.toast[data-kind="reward"] {
  background: linear-gradient(135deg, rgba(123,143,107,0.96), rgba(196,131,106,0.88));
  border: 1px solid rgba(255,255,255,0.22);
}
.t-eyebrow {
  font-size: 11px; font-weight: 700; letter-spacing: 0.22em;
  text-transform: uppercase; color: rgba(255,255,255,0.80);
  margin-bottom: 6px; padding-right: 26px;
}
.t-title {
  font-family: 'Fraunces', 'Crimson Pro', serif;
  font-size: 16px; font-weight: 500; line-height: 1.25; letter-spacing: -0.005em;
}
.t-meta { font-style: italic; font-weight: 400; color: rgba(255,255,255,0.72); }
/* a felhasználó saját ünneplés-mondata (mezo-3zue.5) — a cím alatt, saját sorban: ez az
   ő hangja, nem mennyiségi addendum, ezért nem a `.t-meta` helyét foglalja el */
.t-celebrate {
  margin-top: 5px;
  font-size: 14px; font-style: italic; font-weight: 400; line-height: 1.35;
  color: rgba(255,255,255,0.82);
}
.t-meter {
  display: flex; align-items: center; gap: 9px;
  margin-top: 10px; padding: 7px 11px;
  border-radius: 12px; background: rgba(0,0,0,0.28);
}
.t-mdot {
  width: 8px; height: 8px; border-radius: 50%;
  background: #b8cdaa; box-shadow: 0 0 7px rgba(184,205,170,0.85);
  flex-shrink: 0;
}
.t-mlabel { font-size: 11.5px; font-weight: 700; letter-spacing: 0.01em; }
.t-mdelta {
  margin-left: auto;
  font-size: 15px; font-weight: 800; letter-spacing: -0.01em; line-height: 1;
  color: #ffd87a; font-variant-numeric: tabular-nums;
  animation: toast-delta-pop 500ms cubic-bezier(0.34, 1.56, 0.64, 1);
}
@keyframes toast-delta-pop {
  0% { transform: scale(0.6); } 60% { transform: scale(1.18); } 100% { transform: scale(1); }
}
.t-lvup {
  display: inline-flex; align-items: center; gap: 6px;
  margin-top: 8px; padding: 4px 10px; border-radius: 999px;
  background: rgba(0,0,0,0.30);
  border: 1px solid rgba(255,216,122,0.35);
  font-size: 10.5px; font-weight: 800; letter-spacing: 0.08em; color: #ffd87a;
}

/* Reduced motion: the toast still appears, just without the slide (DS §Notification).
   Both paths matter — the class covers the useReducedMotion hook's runtime read, the
   media query covers a user who flips the OS setting while a toast is on screen. */
.toast.is-reduced { animation: none; transition: none; }
.toast.is-reduced .t-mdelta { animation: none; }
@media (prefers-reduced-motion: reduce) {
  .toast { animation: none; transition: none; }
  .t-mdelta { animation: none; }
}

/* Standalone feature-local confirmation (MedalToast) — keeps the pre-mezo-k5sa
   `.toast` geometry now that the shared `.toast` is a stack child. */
.toast-solo {
  position: absolute;
  left: auto; right: 14px;
  top: 70px;
  width: calc(100% - 28px);
  max-width: 296px;
  /* The app's real toast tier: above sheets (200/211) and the level-up overlay (250).
     The nominal --z-toast (70) belongs to the DS's abstract ladder (sheet 50 / modal 60 /
     toast 70), which this stylesheet expresses at a different absolute scale — same order,
     different numbers. DS §z-index: "Toast above Modal … must be visible." */
  z-index: 300;
  padding: 14px 16px;
  color: var(--text-inverse);
  border-radius: var(--r-lg);
  box-shadow: var(--shadow-xl);
}

/* Brand glyph (M = mesocycle wave) */
.brand-glyph { fill: var(--coral); }

/* Utility */
.row { display: flex; align-items: center; }
.col { display: flex; flex-direction: column; }
.gap-xs { gap: 4px; } .gap-sm { gap: 8px; } .gap-md { gap: 12px; }
.gap-lg { gap: 16px; } .gap-xl { gap: 20px; }
.flex-1 { flex: 1; }
.flex-wrap { flex-wrap: wrap; }
.mt-sm { margin-top: 8px; } .mt-md { margin-top: 12px; }
.mt-lg { margin-top: 16px; } .mt-xl { margin-top: 24px; }
.text-secondary { color: var(--text-secondary); }
.text-tertiary { color: var(--text-tertiary); }
.text-brand { color: var(--coral); }
.text-warning { color: var(--warning); }
.text-error { color: var(--error); }
.text-success { color: var(--success); }

/* MedicationCyclePhaseBar */
.medcycle-bar {
  display: flex; gap: 3px;
  padding: 0 24px;
  margin-top: 8px;
  height: 6px;
}
.medcycle-seg {
  flex: 1;
  background: var(--surface-2);
  opacity: 0.5;
  transition: all 0.3s ease;
}
.medcycle-seg.active {
  opacity: 1;
  box-shadow: 0 0 10px currentColor;
}
.medcycle-seg.past { opacity: 0.4; }

/* Set dots */
.set-dots { display: flex; gap: 6px; }
.set-dot {
  width: 10px; height: 10px;
  border-radius: 50%;
  border: 1.5px solid var(--text-tertiary);
}
.set-dot.done { background: var(--coral); border-color: var(--coral); }
.set-dot.extra { border: 1px dashed var(--coral); box-sizing: border-box; }
.set-dot.warm { border-color: color-mix(in srgb, var(--warning) 40%, transparent); background: color-mix(in srgb, var(--warning) 8%, transparent); }
.set-dot.warm.done { background: var(--warning); border-color: var(--warning); }
.set-dot.active {
  border-color: var(--coral);
  box-shadow: 0 0 0 3px color-mix(in srgb, var(--coral) 20%, transparent);
  animation: pulse-soft 1.5s ease-in-out infinite;
}
@keyframes pulse-soft {
  0%, 100% { box-shadow: 0 0 0 3px color-mix(in srgb, var(--coral) 20%, transparent); }
  50% { box-shadow: 0 0 0 6px color-mix(in srgb, var(--coral) 10%, transparent); }
}
@media (prefers-reduced-motion: reduce) { .set-dot.active { animation: none; } }

/* Loading skeleton — light coral (brand-accent) sweep over a surface-2 block. */
.sk {
  position: relative;
  overflow: hidden;
  border-radius: 7px;
  background: var(--surface-2);
}
.sk::after {
  content: '';
  position: absolute;
  inset: 0;
  transform: translateX(-100%);
  background: linear-gradient(90deg, transparent, color-mix(in srgb, var(--coral) 10%, transparent), transparent);
  animation: mezo-shimmer 1.5s infinite;
}
@keyframes mezo-shimmer { 100% { transform: translateX(100%); } }
.sk--circle { border-radius: 50%; }
@media (prefers-reduced-motion: reduce) { .sk::after { display: none; } }

/* ChallengeGenerationLoader — game-style loading while the day's challenges
   LLM-generate (mezo-tvw8). Rotating status line (fade replays via key remount)
   + fake-progress bar: fast start, decelerating creep toward ~92%, never
   self-completing — the data arriving unmounts the whole loader. */
.mz-chload { display: flex; flex-direction: column; gap: 10px; padding: 18px 4px; align-items: center; }
.mz-chload-line {
  font-size: 13px;
  color: var(--text-secondary);
  animation: mz-chload-fade .45s ease-out;
}
.mz-chload-bar {
  width: min(260px, 80%);
  height: 6px;
  border-radius: 3px;
  background: var(--border-subtle);
  overflow: hidden;
}
.mz-chload-fill {
  height: 100%;
  border-radius: 3px;
  background: var(--coral);
  width: 4%;
  animation: mz-chload-fill 28s cubic-bezier(0.15, 0.6, 0.3, 1) forwards;
}
@keyframes mz-chload-fade { from { opacity: 0; transform: translateY(3px); } to { opacity: 1; transform: none; } }
@keyframes mz-chload-fill { 0% { width: 4%; } 8% { width: 42%; } 30% { width: 70%; } 100% { width: 92%; } }
@media (prefers-reduced-motion: reduce) {
  .mz-chload-line { animation: none; }
  .mz-chload-fill { animation: none; width: 60%; }
}

/* Stepper */
.stepper {
  display: grid;
  grid-template-columns: auto 1fr auto;
  align-items: center;
  background: var(--surface-2);
  padding: 6px;
}
.stepper button {
  width: 44px; height: 44px;
  font-size: 22px;
  color: var(--coral);
  font-weight: 300;
}
.stepper-display {
  text-align: center;
  font-family: var(--ff-display);
  font-size: 32px;
  font-weight: 600;
  color: var(--text-primary);
}
.stepper-display .unit {
  font-family: var(--ff-body);
  font-size: 11px;
  color: var(--text-tertiary);
  margin-left: 4px;
}

/* RIR row */
.rir-row { display: grid; grid-template-columns: repeat(4, 1fr); gap: 6px; }
.rir-cell {
  padding: 10px;
  background: var(--surface-1);
  border: 1px solid var(--border-subtle);
  font-family: var(--ff-display);
  font-size: 18px; font-weight: 600;
  color: var(--text-secondary);
  text-align: center;
}
.rir-cell.active {
  color: var(--coral);
  background: color-mix(in srgb, var(--coral) 10%, transparent);
  border-color: var(--coral);
  box-shadow: inset 0 0 0 1px color-mix(in srgb, var(--coral) 20%, transparent);
}

/* Macro bar */
.macro-bar {
  display: grid;
  grid-template-columns: 1fr 1fr 1fr;
  gap: 8px;
}
.macro-cell {
  background: var(--surface-1);
  border: 1px solid var(--border-subtle);
  padding: 12px;
}
.macro-cell .name {
  font-family: var(--ff-body);
  font-size: 9px; font-weight: 600;
  letter-spacing: 0.18em; text-transform: uppercase;
  color: var(--text-tertiary);
}
.macro-cell .val {
  font-family: var(--ff-display);
  font-size: 22px; font-weight: 600;
  color: var(--text-primary);
  margin: 4px 0;
}
.macro-cell .val .unit {
  font-family: var(--ff-body);
  font-size: 11px;
  color: var(--text-tertiary);
  margin-left: 2px;
}

/* Force directed graph */
.graph-canvas {
  width: 100%;
  height: 100%;
  cursor: grab;
  touch-action: none;
}
.graph-node { cursor: pointer; }
.graph-node-pulse {
  animation: node-pulse 2.5s ease-in-out infinite;
}
@keyframes node-pulse {
  0%, 100% { opacity: 1; }
  50% { opacity: 0.6; }
}
@media (prefers-reduced-motion: reduce) { .graph-node-pulse { animation: none; } }

/* Pattern card critique mini-bars */
.critique-grid {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 8px;
  margin-top: 12px;
}
.critique-bar { font-size: 10px; }
.critique-bar .lbl {
  font-family: var(--ff-body);
  font-size: 9px; font-weight: 600;
  letter-spacing: 0.12em; text-transform: uppercase;
  color: var(--text-tertiary);
}

/* Memoir card */
.memoir-card {
  background: linear-gradient(180deg, var(--surface-1) 0%, var(--surface-2) 100%);
  border: 1px solid var(--line);
}

/* RecipeFitBadge / fit-zone pending sparkle pulse (recipes-*.html @keyframes tw) */
@keyframes mezo-twinkle {
  0%, 100% { opacity: 0.45; transform: scale(0.9); }
  50% { opacity: 1; transform: scale(1.08); }
}
.np-twinkle { animation: mezo-twinkle 2.6s ease-in-out infinite; }
@media (prefers-reduced-motion: reduce) { .np-twinkle { animation: none; } }
/* Shared soft-pulse dot (typing indicator, live-system dot, planner loader) — reduce-guarded.
   Dominant duration 1.2s; the 2s live-system dot overrides via inline animationDuration, and the
   staggered dot rows keep their per-index inline animationDelay (the guard still kills the name). */
.np-pulse { animation: pulse-soft 1.2s ease-in-out infinite; }
@media (prefers-reduced-motion: reduce) { .np-pulse { animation: none; } }

/* ============================================================
   Progression level-up overlay (P5, mezo-te8k) — ported from
   levelup-v4.html; raw mockup vars mapped to app design tokens.
   Self-portaled into .phone-screen; z-index 250 covers TabBar
   (40) + sheets (200/211), sits below the toast tier (300).
   ============================================================ */
.levelup {
  position: absolute;
  inset: 0;
  z-index: 250;
  overflow-y: auto;
  display: flex;
  flex-direction: column;
  background: radial-gradient(120% 80% at 50% 0%, var(--surface-1), var(--surface-1) 70%);
  color: var(--text-primary);
}
.lu-glow {
  position: absolute;
  top: -130px;
  left: 50%;
  transform: translateX(-50%);
  width: 430px;
  height: 430px;
  background: radial-gradient(circle, color-mix(in srgb, var(--coral) 22%, transparent), transparent 62%);
  filter: blur(8px);
  pointer-events: none;
  animation: levelup-breathe 4s ease-in-out infinite;
  z-index: 0;
}
.lu-body {
  position: relative;
  z-index: 2;
  padding: 24px 22px;
  text-align: center;
  flex: 1;
  display: flex;
  flex-direction: column;
}
/* mezo-tr5v: the content block centers vertically (auto block margins absorb the free space
   evenly), leaving the CTA pinned to the bottom — instead of top-loading with empty space
   below. On overflow (many skills) the auto margins collapse to 0 and it scrolls normally. */
.lu-content {
  display: flex;
  flex-direction: column;
  margin-block: auto;
}
.levelup .lu-anim { opacity: 0; animation: levelup-fade-up 0.55s ease forwards; }
.levelup .lu-pop { opacity: 0; animation: levelup-pop 0.55s cubic-bezier(0.2, 1.25, 0.4, 1) forwards; }
.sr-only, .lu-sr-only {
  position: absolute; width: 1px; height: 1px; padding: 0; margin: -1px;
  overflow: hidden; clip: rect(0, 0, 0, 0); white-space: nowrap; border: 0;
}

.lu-chip {
  align-self: center;
  display: inline-flex;
  align-items: center;
  gap: 8px;
  padding: 6px 14px;
  border-radius: 30px;
  background: var(--surface-2);
  border: 1px solid var(--border-strong);
  font-family: var(--ff-body);
  font-size: 10.5px;
  letter-spacing: 0.08em;
  color: var(--text-secondary);
}
.lu-headline {
  font-family: var(--ff-display);
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: 0.015em;
  font-size: 31px;
  line-height: 1.04;
  margin-top: 13px;
}
.lu-xpwrap { margin-top: 14px; }
.lu-xpnum {
  font-family: var(--ff-display);
  font-weight: 700;
  font-size: 66px;
  line-height: 0.9;
  color: var(--coral);
  text-shadow: 0 0 26px color-mix(in srgb, var(--coral) 50%, transparent);
  letter-spacing: 0.01em;
}
.lu-xpnum .lu-plus { font-size: 0.5em; vertical-align: 0.32em; opacity: 0.65; margin-right: 0.12em; font-weight: 600; }
.lu-xplabel {
  font-family: var(--ff-body);
  font-size: 11px;
  letter-spacing: 0.32em;
  color: var(--text-secondary);
  margin-top: 6px;
}
.lu-seclabel {
  display: flex;
  align-items: center;
  gap: 9px;
  margin: 18px 0 11px;
  font-family: var(--ff-body);
  font-size: 9.5px;
  letter-spacing: 0.2em;
  text-transform: uppercase;
  color: var(--text-tertiary);
}
.lu-seclabel::before, .lu-seclabel::after { content: ''; flex: 1; height: 1px; background: var(--border-subtle); }
.lu-seclabel .lu-cnt { color: var(--coral); }

.lu-lvrow {
  display: flex;
  align-items: center;
  gap: 13px;
  text-align: left;
  padding: 9px 12px;
  margin-bottom: 8px;
  border-radius: 14px;
  background: linear-gradient(120deg, color-mix(in srgb, var(--coral) 12%, transparent), color-mix(in srgb, var(--coral) 3%, transparent));
  border: 1px solid var(--line);
}
.lu-lvrow.muscle {
  background: linear-gradient(120deg, color-mix(in srgb, var(--coral) 13%, transparent), color-mix(in srgb, var(--coral) 2%, transparent));
}
.lu-miniring { position: relative; width: 58px; height: 58px; flex-shrink: 0; }
.lu-miniring svg { transform: rotate(-90deg); }
.lu-mr-track { fill: none; stroke: var(--border-strong); stroke-width: 5; }
.lu-mr-prog {
  fill: none;
  stroke: var(--coral);
  stroke-width: 5;
  stroke-linecap: round;
  stroke-dashoffset: 163.36; /* RING_C — empty; keyframe fills to --lu-ring-offset */
  filter: drop-shadow(0 0 4px color-mix(in srgb, var(--coral) 70%, transparent));
  animation: levelup-ring 1.7s cubic-bezier(0.3, 0.8, 0.2, 1) forwards;
}
.lu-lvrow.muscle .lu-mr-prog {
  stroke: var(--coral);
  filter: drop-shadow(0 0 4px color-mix(in srgb, var(--coral) 70%, transparent));
}
.lu-mr-num {
  position: absolute;
  inset: 0;
  display: flex;
  align-items: center;
  justify-content: center;
  font-family: var(--ff-display);
  font-weight: 700;
  font-size: 26px;
  color: var(--text-primary);
  padding-bottom: 2px;
}
.lu-lvinfo { flex: 1; min-width: 0; }
.lu-lvname {
  font-family: var(--ff-display);
  font-size: 18px;
  text-transform: uppercase;
  letter-spacing: 0.01em;
  display: flex;
  align-items: center;
  gap: 7px;
}
.lu-lvbadge {
  display: inline-flex;
  align-items: center;
  gap: 5px;
  margin-top: 5px;
  padding: 3px 9px;
  border-radius: 20px;
  background: var(--coral);
  color: var(--text-inverse);
  font-family: var(--ff-body);
  font-weight: 600;
  font-size: 9.5px;
  letter-spacing: 0.1em;
}
.lu-lvrow.muscle .lu-lvbadge { background: var(--coral); }

.lu-perk {
  display: flex;
  align-items: center;
  gap: 9px;
  text-align: left;
  margin-top: 2px;
  margin-bottom: 8px;
  padding: 9px 13px;
  border-radius: 12px;
  background: color-mix(in srgb, var(--warning) 7%, transparent);
  border: 1px solid color-mix(in srgb, var(--warning) 30%, transparent);
}
.lu-perk .lu-pk-ic { font-size: 15px; color: var(--warning); }
.lu-perk .lu-pk-tx { flex: 1; font-size: 11.5px; color: var(--text-secondary); line-height: 1.4; }
.lu-perk .lu-pk-tx b { color: var(--warning); font-weight: 600; font-family: var(--ff-display); font-size: 13px; letter-spacing: 0.02em; }
.lu-perk .lu-pk-tx .lu-eff { color: var(--coral-deep); } /* was --wash-gym: a wash-as-text misuse, unreadable on Pulse graphite */

.lu-growgrid { display: grid; grid-template-columns: 1fr 1fr; gap: 8px; text-align: left; }
.lu-gcell { background: var(--surface-1); border: 1px solid var(--border-subtle); border-radius: 10px; padding: 8px 10px; }
.lu-gtop { display: flex; align-items: center; gap: 7px; margin-bottom: 6px; }
.lu-gic {
  width: 22px;
  height: 22px;
  border-radius: 6px;
  display: grid;
  place-items: center;
  font-size: 12px;
  flex-shrink: 0;
  background: radial-gradient(circle at 50% 30%, color-mix(in srgb, var(--coral) 14%, transparent), color-mix(in srgb, var(--coral) 4%, transparent));
  border: 1px solid var(--line);
}
.lu-gcell.mus .lu-gic { background: color-mix(in srgb, var(--coral) 10%, transparent); border-color: color-mix(in srgb, var(--coral) 30%, transparent); }
.lu-gname { font-size: 11px; font-weight: 500; flex: 1; white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
.lu-gxp { font-family: var(--ff-body); font-size: 10px; font-weight: 600; color: var(--coral); }
.lu-gcell.mus .lu-gxp { color: var(--coral); }
.lu-gbar { height: 5px; border-radius: 3px; background: var(--border-subtle); overflow: hidden; position: relative; }
.lu-gfill {
  position: absolute;
  inset: 0 auto 0 0;
  border-radius: 3px;
  background: linear-gradient(90deg, var(--coral-deep), var(--coral));
  box-shadow: 0 0 6px -1px var(--coral);
  width: var(--lu-from);
  animation: levelup-bar 1.3s cubic-bezier(0.25, 0.8, 0.25, 1) forwards;
}
.lu-gcell.mus .lu-gfill { background: linear-gradient(90deg, var(--coral-deep), var(--coral)); box-shadow: 0 0 6px -1px var(--coral); }

.lu-robust {
  margin-top: 10px;
  display: flex;
  align-items: center;
  gap: 9px;
  padding: 8px 13px;
  border-radius: 11px;
  text-align: left;
  background: var(--surface-1);
  border: 1px solid var(--border-subtle);
}
.lu-robust .lu-r-ic { font-size: 15px; }
.lu-robust .lu-r-tx { flex: 1; font-size: 11px; color: var(--text-secondary); }
.lu-robust .lu-r-tx b { color: var(--text-primary); font-weight: 500; }
.lu-robust .lu-r-xp { font-family: var(--ff-body); font-size: 11px; color: var(--success); font-weight: 600; }

.lu-ctas { margin-top: 0; padding-top: 16px; } /* mezo-tr5v: bottom-pinned by .lu-content's margin-block:auto */
.lu-cta {
  width: 100%;
  padding: 14px;
  border-radius: 14px;
  font-family: var(--ff-body);
  font-size: 12.5px;
  font-weight: 600;
  letter-spacing: 0.03em;
  border: none;
  cursor: pointer;
  text-align: center;
  background: linear-gradient(90deg, var(--coral-deep), var(--coral));
  color: var(--text-inverse);
  box-shadow: 0 10px 28px -12px var(--coral);
}

@keyframes levelup-fade-up { from { opacity: 0; transform: translateY(12px); } to { opacity: 1; transform: translateY(0); } }
@keyframes levelup-pop { from { opacity: 0; transform: scale(0.85); } to { opacity: 1; transform: scale(1); } }
@keyframes levelup-ring { to { stroke-dashoffset: var(--lu-ring-offset); } }
@keyframes levelup-bar { to { width: var(--lu-to); } }
@keyframes levelup-breathe {
  0%, 100% { opacity: 0.5; transform: translateX(-50%) scale(1); }
  50% { opacity: 0.9; transform: translateX(-50%) scale(1.08); }
}

/* Reduced motion: collapse the stagger; rings/bars render in their final state
   (the offset/width are set inline by the component). */
.levelup--reduced .lu-anim,
.levelup--reduced .lu-pop { animation: none; opacity: 1; transform: none; }
.levelup--reduced .lu-mr-prog,
.levelup--reduced .lu-gfill,
.levelup--reduced .lu-glow { animation: none; }
@media (prefers-reduced-motion: reduce) {
  .levelup .lu-anim, .levelup .lu-pop { animation: none; opacity: 1; transform: none; }
  .levelup .lu-mr-prog, .levelup .lu-gfill, .levelup .lu-glow { animation: none; }
  .levelup .lu-gfill { width: var(--lu-to); }
}

/* ============================================================
   Progression meter rows (P6, mezo-xje5) — the top-skill bars used
   by the Growth-page band cards. The athletic-radar + muscle-levels
   + rstat chrome retired with the profile radars (mezo-rmhr).
   ============================================================ */
/* meter rows (Growth band cards) */
.progress-mrow { display: flex; align-items: center; gap: 10px; }
.progress-mrk { font-family: var(--ff-body); font-size: 10px; color: var(--text-tertiary); width: 16px; flex-shrink: 0; }
.progress-mnm { font-size: 12px; color: var(--text-primary); width: 84px; flex-shrink: 0; white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
.progress-mlv { font-family: var(--ff-body); font-size: 10px; color: var(--coral); width: 34px; flex-shrink: 0; }
.progress-mbar { flex: 1; height: 6px; border-radius: 3px; background: var(--border-subtle); overflow: hidden; }
.progress-mfill {
  height: 100%;
  border-radius: 3px;
  background: linear-gradient(90deg, var(--coral-deep), var(--coral));
  box-shadow: 0 0 7px -1px var(--coral);
  width: var(--w);
  animation: progress-mbar-grow 1.1s cubic-bezier(0.25, 0.8, 0.25, 1) forwards;
}
.progress-mfill--reduced { animation: none; }
@keyframes progress-mbar-grow { from { width: 0; } to { width: var(--w); } }
@media (prefers-reduced-motion: reduce) { .progress-mfill { animation: none; } }

/* ===== Napív tokens → DS alias bridge (P1, mezo-setx.2) =====
   The 2026-07-13 Napív palette IS the DS palette's ancestor — every name below
   now aliases its DS token (both themes resolve through the Pulse block).
   Two intentional value shifts: --coral-deep #C4622F → primary-deep #A84A26
   (the old value fails AA as text, ADR 0018) and --sage-deep #5F7A52 →
   success-hover #4A6A3D (same role, ramp-exact). --lav-deep keeps literals
   (lavender is demoted to data-viz; no DS slot). --cta-g1/g2 moved up into the
   DS block. The --np-* shadow/ease literals stay: the Sheet + card motion
   timing is battle-tested machinery, restyled only when P2 touches it. */
:root {
  --surface: var(--surface-card);
  --warm: var(--secondary-bg);
  --line: var(--divider);
  --ink: var(--text-primary);
  --sub: var(--text-secondary);
  --faint: var(--text-disabled);
  --coral: var(--primary-base);  --coral-deep: var(--primary-deep);
  --amber: var(--dv-amber);
  --sage: var(--dv-sage);        --sage-deep: var(--success-hover);
  --lav: var(--dv-lav);          --lav-deep: #7A6DA8;
  --rose: var(--dv-rose);
  --sky: var(--dv-sky);
  --np-shadow-card: 0 2px 4px rgba(43,33,24,.04), 0 12px 30px rgba(43,33,24,.08);
  --np-shadow-row: 0 8px 20px rgba(43,33,24,.05);
  --np-ease-ios: cubic-bezier(.32,.72,0,1);
  --np-ease-spring: cubic-bezier(.34,1.4,.44,1);
}

/* Pulse dark — only the tokens that stayed literal above need dark values. */
:root[data-theme="dark"] {
  --lav-deep: #B9ACD9;
  --np-shadow-card: 0 2px 4px rgba(0,0,0,.3), 0 12px 30px rgba(0,0,0,.35);
  --np-shadow-row: 0 8px 20px rgba(0,0,0,.3);
}

/* Transitional shape softening: chamfers become rounded corners app-wide.
   Radii follow spec §3.3 (rows 18-20px, cards 20-28px). */

/* Napív tab bar — frosted floating capsule (supersedes mezo-ci5's opaque bar; blur+tint solves both recorded failure modes) */
.tab-bar {
  position: absolute; left: 14px; right: 14px; bottom: 14px;
  border-radius: 999px; border-top: none;
  background: color-mix(in srgb, var(--canvas) 66%, transparent);
  -webkit-backdrop-filter: blur(20px) saturate(1.5);
  backdrop-filter: blur(20px) saturate(1.5);
  box-shadow: 0 14px 34px rgba(43,33,24,.16), inset 0 0 0 1px rgba(255,255,255,.55);
  padding: 10px 18px;
  display: flex; align-items: center; justify-content: space-around;
  z-index: 40; height: 64px;
}
@supports not (backdrop-filter: blur(1px)) {
  .tab-bar { background: color-mix(in srgb, var(--canvas) 96%, transparent); }
}
/* Floating quick-log FAB (Design 2.0 decision B, mezo-d20.1.1) — bottom-right thumb
   zone above the tab bar; prototype .floatfab recipe with the DS CTA gradient. */
.quicklog-fab {
  position: absolute; right: 14px; bottom: 92px;
  width: 56px; height: 56px; border-radius: 50%; border: none;
  background: var(--gradient-cta); color: #fff;
  display: flex; align-items: center; justify-content: center;
  box-shadow: 0 12px 24px -6px color-mix(in srgb, var(--cta-g2) 65%, transparent);
  cursor: pointer; z-index: 44;
  transition: transform var(--duration-fast) var(--ease-out);
}
.quicklog-fab:active { transform: scale(0.92); }   /* Rule 21: visible press feedback */
/* FAB soft glow pulse (prototype fabglow) — motion only under no-preference. */
@keyframes np-fabglow { 0%,100% { box-shadow: 0 8px 18px -5px color-mix(in srgb, var(--cta-g2) 60%, transparent); }
  50% { box-shadow: 0 8px 26px -3px color-mix(in srgb, var(--cta-g2) 85%, transparent); } }
@media (prefers-reduced-motion: no-preference) { .quicklog-fab { animation: np-fabglow 3.2s ease-in-out 1.6s infinite; } }
/* QuickInputSheet — the FAB's 6-tile quick-log launcher (DS re-dress mezo-setx.5.4) */
.quicklog { padding: 4px 6px 10px; }
.quicklog h2 { font-family: var(--ff-display); font-size: 24px; font-weight: 700; letter-spacing: -0.02em; color: var(--text-primary); }
.quicklog-sub { font-size: 14px; color: var(--text-secondary); font-weight: 400; margin-top: 2px; }
/* 9 tiles in a 3-wide rhythm; flex (not grid) so a short last row centres itself (mezo-967c) */
.quicklog-grid { display: flex; flex-wrap: wrap; justify-content: center; gap: var(--sp-3); margin-top: var(--sp-3); }
.quicklog-tile {
  flex: 0 0 calc((100% - 2 * var(--sp-3)) / 3);
  border-radius: var(--r-2xl); padding: 16px 8px 14px; text-align: center;
  border: 1px solid var(--divider); background: var(--surface-page); cursor: pointer;
  display: flex; flex-direction: column; align-items: center; gap: 2px; font-family: inherit;
}
/* quick-log v2 (mezo-7lst) → the tile material + hues live in QuickLogSurface.css (mezo-reocc) */
.quicklog-label { font-size: 14px; font-weight: 700; color: var(--text-primary); }
/* The one non-logging entry, lifted out of the grid so the companion chat stops hiding (mezo-967c) */
.quicklog-chat {
  width: 100%; margin-top: var(--sp-4); padding: 12px 14px;
  display: flex; align-items: center; gap: 12px; text-align: left;
  border: none; border-radius: var(--r-2xl); cursor: pointer; font-family: inherit;
  background: var(--gradient-cta); color: #fff; box-shadow: var(--shadow-cta);
}
.quicklog-chat-text { flex: 1; min-width: 0; display: flex; flex-direction: column; gap: 1px; }
.quicklog-chat-label { font-size: 15px; font-weight: 700; }
.quicklog-chat-hint { font-size: 12px; font-weight: 500; opacity: 0.82; }
.screen-content { padding-bottom: var(--screen-bottom-pad); }
.icon-btn { width: 48px; height: 48px; border-radius: 50%; background: var(--surface); box-shadow: var(--np-shadow-row); display: inline-flex; align-items: center; justify-content: center; color: var(--sub); } /* DS Rule 6: 48dp tap target */

/* ===== Circadian atmosphere (every screen; spec §3.4) ===== */
.sky {
  position: absolute; top: 0; left: 0; right: 0; height: 295px; z-index: 0;
  pointer-events: none; transition: background 1s ease;
  -webkit-mask-image: linear-gradient(#000 55%, transparent);
  mask-image: linear-gradient(#000 55%, transparent);
}
.phone-screen { transition: background 1s ease; }
.phone-screen[data-day="reggel"] {
  background: #FCF1DF;
}
.phone-screen[data-day="reggel"] .sky {
  background: radial-gradient(440px 310px at 18% 0%, rgba(255,158,66,.45), transparent 72%),
              linear-gradient(180deg, #FFDDAE, #FFEDD4 55%, transparent);
}
.phone-screen[data-day="delutan"] .sky {
  background: radial-gradient(420px 260px at 50% -6%, rgba(255,199,115,.16), transparent 70%),
              linear-gradient(180deg, #FAF3E6, #FBF6EF 65%, transparent);
}
.phone-screen[data-day="este"] {
  background: #F3EDF2;
}
.phone-screen[data-day="este"] .sky {
  background: radial-gradient(440px 310px at 82% 2%, rgba(155,143,196,.4), transparent 72%),
              linear-gradient(180deg, #E2D9EF, #F0E9E9 62%, transparent);
}
/* Dark theme keeps its own canvas (graphite) — the daypart tint on the canvas stays a
   light-theme device. The S8 Pulse pass (mezo-8141) designs the night sky variants below:
   the canvas stays graphite; only the faint sky band glows per daypart. */
:root[data-theme="dark"] .phone-screen[data-day] { background: var(--canvas); }
/* Pulse night skies — canvas stays graphite; only the sky band glows faintly */
:root[data-theme="dark"] .sky { opacity: .5; }
:root[data-theme="dark"] .phone-screen[data-day="reggel"] .sky { background: radial-gradient(60% 40% at 18% 0%, rgba(255,179,71,.10), transparent 70%); }
:root[data-theme="dark"] .phone-screen[data-day="delutan"] .sky { background: radial-gradient(60% 40% at 50% 0%, rgba(245,239,230,.06), transparent 70%); }
:root[data-theme="dark"] .phone-screen[data-day="este"] .sky { background: radial-gradient(60% 40% at 82% 0%, rgba(155,143,196,.12), transparent 70%); }
/* AnchorMode: rough days mute the atmosphere — the S3 restyle dropped the dedicated anchor canvas skin, so anchor now only dims the daypart sky (mezo-8141). */
.phone-screen.anchor .sky { opacity: .35; filter: saturate(.6); }

/* ===== Napív motion vocabulary (spec §3.5) ===== */
@keyframes np-rise { from { opacity: 0; transform: translateY(16px); } to { opacity: 1; transform: none; } }
@keyframes np-pop  { 0% { opacity: 0; transform: scale(.3); } 70% { transform: scale(1.15); } 100% { opacity: 1; transform: scale(1); } }
@keyframes np-grow { to { transform: scaleX(1); } }
@keyframes np-draw { to { stroke-dashoffset: 0; } }

.np-anim { opacity: 0; animation: np-rise .55s var(--np-ease-ios) forwards; animation-delay: calc(var(--i, 0) * 70ms); }
.np-press { transition: transform .18s var(--np-ease-spring); }
.np-press:active { transform: scale(.955); }

@media (prefers-reduced-motion: reduce) {
  .np-anim { animation: none; opacity: 1; }
  .np-press, .np-press:active { transition: none; transform: none; }
  .sky, .phone-screen { transition: none; }
}

/* A back navigation is a RETURN, not an arrival — the entrance settles instantly instead of
   replaying, which is what made swipe-back read as the page flashing/reloading (mezo-kuwj).
   Same neutralisation the reduce query above applies, keyed on the shell's arrival marker
   (ScreenContent). The `.rise` family needs no rule here: EntranceGroup withholds its
   `.mz-play` arming class on a pop, so `.mz-play .rise { opacity: 0 }` simply never matches. */
[data-arrival="pop"] .np-anim { animation: none; opacity: 1; }

/* The `.dayarc`/`.arc-*`/`.arclbl` day-arc family retired with the daypart faces
   (mezo-j7u4) — the DayFaceStrip pill counters carry the day-progress job now. The
   Bézier itself lives on in `logic/dayArc.ts`, redrawn by the Napzárás recap under
   the dark-canvas `.rz-arc-*` rules below. */

/* ===== Napív Today hero =====
   `.np-hero*` retired with `WorkoutTeaser` (mezo-j7u4): the day face's hero is the
   shared `.todaycard` now. The type tags + CTA rules below stay — they are the shared
   card language's, worn across Today, Train and Fuel. */
.h2row { display: flex; align-items: center; gap: 10px; margin-top: 7px; flex-wrap: wrap; }
.h2row h2 { font-family: var(--ff-display); font-size: 29px; font-weight: 800; letter-spacing: -.4px; color: var(--ink); }
.typetag { display: inline-block; border-radius: var(--r-sm); padding: 3px 8px; font-size: 10px; font-weight: 800; letter-spacing: .10em; text-transform: uppercase; }
.typetag-gym { background: var(--wash-gym); color: var(--tag-gym); }
.typetag-sport { background: var(--wash-sport); color: var(--tag-sport); }
.typetag-run { background: var(--wash-run); color: var(--tag-run); }
.typetag-cross { background: var(--wash-cross); color: var(--tag-cross); }
.typetag-trx { background: var(--wash-trx); color: var(--tag-trx); }
.typetag-body { background: var(--wash-sage); color: var(--sage-deep); }
.typetag-mind { background: var(--wash-lav); color: var(--lav-deep); }
.typetag-fuel { background: var(--wash-amber); color: var(--amber-deep); }
/* the niggle strip — the DS warning Alert idiom, token-only (both themes flip via the ramp) */
.warmstrip { display: flex; align-items: center; gap: 10px; background: var(--warning-bg); border: 1px solid var(--warning-soft); border-radius: var(--r-lg); padding: 10px 12px; font: 500 13px/1.45 var(--ff-body); color: var(--warning-deep); margin-top: 12px; }
.np-ctarow { display: flex; gap: 10px; margin-top: 14px; position: relative; z-index: 1; }
.np-cta { flex: 1; border: 0; cursor: pointer; font: inherit; background: linear-gradient(135deg, var(--cta-g1), var(--cta-g2)); color: #fff; border-radius: 999px; padding: 15px 0; text-align: center; font-weight: 800; font-size: 15.5px; box-shadow: 0 10px 24px color-mix(in srgb, var(--cta-g2) 35%, transparent), inset 0 1px 0 rgba(255,255,255,.25); }

/* `.np-eventrow*` retired with `VolleyballCard`, `.alt-btn` with `WorkoutTeaser`'s
   details button (mezo-j7u4): the day face's sport hero is the shared `.todaycard`. */

/* ===== Briefing bubble — the CoachBubble-dressed briefing (mezo-setx.5.1) =====
   The shell is `shared/ui/CoachBubble` (`.coach-bubble`); these are its briefing-only
   children: the collapsed clamp row, the lead/rest paragraph pair (coach voice over
   body prose), the refs row and the meta+toggle foot. */
.brief-bubble, .today-note { margin: 0 24px 16px; }
.brief { display: flex; gap: 10px; align-items: flex-end; }
.brief-clamp { display: -webkit-box; -webkit-line-clamp: 3; -webkit-box-orient: vertical; overflow: hidden; }
.brief-more { border: 0; background: none; cursor: pointer; font: 700 14px/1 var(--ff-body); color: var(--primary-deep); white-space: nowrap; padding: 8px 2px; align-self: flex-end; }
.briefing-body { display: flex; flex-direction: column; gap: 10px; }
/* the lead inherits the .cb-body coach voice; the remaining paragraphs step down to body */
.brief-rest { font: 400 16px/1.55 var(--ff-body); letter-spacing: 0; color: var(--text-primary); }
.brief-refs { display: flex; flex-wrap: wrap; gap: 8px; align-items: center; margin-top: 14px; padding-top: 10px; border-top: 1px solid color-mix(in srgb, var(--primary-base) 18%, transparent); }
.brief-refs-l { font: 700 10px/1 var(--ff-body); letter-spacing: .18em; text-transform: uppercase; color: var(--primary-deep); }
.brief-foot { display: flex; align-items: baseline; justify-content: flex-end; gap: 10px; margin-top: 6px; }
.brief-meta { font: 600 11px/1.2 var(--ff-body); letter-spacing: .06em; text-transform: uppercase; color: var(--text-muted); font-variant-numeric: tabular-nums; }

/* The `.beats`/`.beat*` heartbeat strip retired with `CheckInStrip` (mezo-j7u4) — the
   check-in slots are ordinary `.itemrow`s inside their face's TodoCard now. */
.secthead-np { display: flex; justify-content: space-between; align-items: baseline; margin: 16px 6px 9px; }
.secthead-np h3 { font-size: 14.5px; font-weight: 800; color: var(--ink); }
.secthead-np span { font-size: 12px; color: var(--faint); font-weight: 700; }

/* The `.zonediv` zone boundary (mezo-gj2y) retired with the two-zone Today: the faces
   own the split, and a within-face section line is `.zoneline` (mezo-j7u4). `.scard`
   went with `QuickStat`/`QuickStatsRow` — the day's numbers are the briefing's
   `.metapill` facts now. */

/* ===== Napív S4 — train-type accent tokens (mockup stag/lic palette) ===== */
:root {
  --wash-gym: #FFEDE6;
  --wash-sport: #FBE9EC;
  --wash-run: #E7F0F8;
  --wash-cross: #FBF0DD;          /* cross gets its own amber family (mezo-9bbc) */
  --wash-trx: #F0EDF8;            /* TRX rides the lavender family (mezo-9bbc) */
  --tag-gym: #C4622F;
  --tag-sport: #B14B5E;
  --tag-run: #3E6E9E;
  --tag-cross: #B07A2E;
  --tag-trx: #7A6DA8;
}
:root[data-theme="dark"] {
  --wash-gym: rgba(255,107,74,.16);
  --wash-sport: rgba(226,122,139,.16);
  --wash-run: rgba(111,167,216,.16);
  --wash-cross: rgba(224,164,88,.16);
  --wash-trx: rgba(171,159,210,.16);
  --tag-gym: #F0966B; --tag-sport: #E9A3AE; --tag-run: #9CC0E4;
  --tag-cross: #E0A458; --tag-trx: #B9ACD9;
}

/* ===== Napív page head (pgheadrow — Train sub-pages; Fuel/Me adopt later) ===== */
.pghead-np { display: flex; justify-content: space-between; align-items: flex-end; padding: 10px 24px 0; margin-bottom: 12px; } /* bottom gap so the first content block never sits flush (mezo-nhra) */
.pghead-np .over { font-size: 11px; font-weight: 800; letter-spacing: 1.2px; text-transform: uppercase; color: var(--coral-deep); }
.pghead-np h1 { font-family: var(--ff-display); font-weight: 800; letter-spacing: -.4px; font-size: 27px; color: var(--ink); }
.pgact-np { display: inline-flex; align-items: center; gap: 4px; border: 0; cursor: pointer; font: inherit; border-radius: 999px; padding: 8px 14px; font-size: 12px; font-weight: 800; background: var(--warm); color: var(--coral-deep); white-space: nowrap; }

/* ===== Napív session type tags (weekly plan + session rows) ===== */
.stag { display: inline-block; border-radius: 8px; padding: 3px 7px; font-size: 9px; font-weight: 800; letter-spacing: .5px; flex-shrink: 0; text-transform: uppercase; }
.stag-gym { background: var(--wash-gym); color: var(--tag-gym); }
.stag-sport { background: var(--wash-sport); color: var(--tag-sport); }
.stag-run { background: var(--wash-run); color: var(--tag-run); }
.stag-cross { background: var(--wash-cross); color: var(--tag-cross); }
.stag-trx { background: var(--wash-trx); color: var(--tag-trx); }

/* ===== Napív weekly load tiles (Mai, spec §4.3) ===== */
/* Scrolls rather than clips (mezo-setx.6.3): the tiles hold free-form values
   ("2× · sprint"), and at DS type sizes three of them can exceed a phone width
   by a few px — a nowrap value in a shrinking flex child is then silently cut
   off. Same escape hatch as `.pgactrow`. */
.loadrow { display: flex; gap: 9px; margin: 14px 24px 0; overflow-x: auto; scrollbar-width: none; }
.loadrow::-webkit-scrollbar { display: none; }
/* DS-migrated (mezo-setx.6.3): DS card chrome + the StatStrip label/value voice. */
.loadtile { flex: 1 0 auto; border-radius: var(--r-lg); padding: 10px 12px; display: flex; align-items: center; gap: var(--sp-3); background: var(--surface-1); border: 1px solid var(--card-border); box-shadow: var(--shadow-sm); min-width: 0; }
.loadtile .lic { width: 32px; height: 32px; border-radius: var(--r-md); display: flex; align-items: center; justify-content: center; font-size: 16px; flex-shrink: 0; }
.loadtile .lic-gym { background: var(--wash-gym); }
.loadtile .lic-sport { background: var(--wash-sport); }
.loadtile .lic-run { background: var(--wash-run); }
.loadtile .lk { font-size: 9px; font-weight: 700; letter-spacing: .18em; text-transform: uppercase; color: var(--text-muted); }
/* Caption size (14), not the 16 body floor: these are compact metric values in a
   three-across row, and at 16 the row could not hold "2× · sprint" on one line —
   it overflowed the page, and letting it wrap broke "5× · 73p" after the dot. */
.loadtile .lva { font-size: 14px; font-weight: 700; letter-spacing: -0.02em; font-family: var(--ff-display); margin-top: 2px; color: var(--text-primary); white-space: nowrap; font-variant-numeric: tabular-nums; }
.loadtile > div:last-child { min-width: 0; }

/* ===== Napív meta pill — one fact of a session (time, duration, role, RPE…).
   Shared by the weekly day cards and Mai's today session cards (mezo-lruy). ===== */
.metapill { display: inline-flex; align-items: center; border-radius: var(--r-full); padding: 4px 10px; font-size: 11px; font-weight: 700; color: var(--text-secondary); background: var(--surface-recess); white-space: nowrap; font-variant-numeric: tabular-nums; }

/* ===== Napív day strip — Mai's week navigator (mezo-9bbc) ===== */
.daystrip { display: flex; gap: 9px; overflow-x: auto; scroll-snap-type: x proximity; padding: 2px 24px 6px; }
.daystrip::-webkit-scrollbar { height: 0; }
.daychip { flex: none; width: 62px; scroll-snap-align: center; border-radius: 20px; background: var(--surface); box-shadow: var(--np-shadow-row); padding: 9px 0 8px; text-align: center; border: 1.5px solid transparent; font-family: inherit; cursor: pointer; }
.daychip .dl { display: block; font-size: 10px; font-weight: 800; letter-spacing: .1em; text-transform: uppercase; color: var(--faint); }
.daychip .dn { display: block; font-family: var(--ff-display); font-size: 17px; font-weight: 800; color: var(--ink); margin-top: 1px; }
.daychip .dots { display: flex; gap: 3px; justify-content: center; margin-top: 6px; min-height: 6px; }
.daychip .dot { width: 6px; height: 6px; border-radius: 50%; }
.dot-gym { background: var(--tag-gym); }
.dot-sport { background: var(--tag-sport); }
.dot-cross { background: var(--tag-cross); }
.dot-trx { background: var(--tag-trx); }
.dot-run { background: var(--tag-run); }
.daychip .ck { display: block; font-size: 9px; font-weight: 800; color: var(--sage-deep); margin-top: 5px; letter-spacing: .04em; }
.daychip.rest { background: transparent; box-shadow: none; border-style: dashed; border-color: var(--line); }
.daychip.rest .ck { color: var(--faint); }
.daychip.today { border-color: var(--coral); }
.daychip.today .dl { color: var(--coral-deep); }
.daychip.sel { background: var(--ink); border-color: var(--ink); }
.daychip.sel .dl { color: color-mix(in srgb, var(--surface) 70%, transparent); }
.daychip.sel .dn { color: var(--surface); }
.daychip.sel.today { box-shadow: 0 0 0 2px var(--coral); }
/* On the ink-filled selected chip the marker's sage/faint colours drop below a
   readable contrast, and a `rest` chip's dashed --ink border disappears into the
   fill entirely — both need a surface-tinted override (mezo-9bbc final review). */
.daychip.sel .ck, .daychip.sel.rest .ck { color: color-mix(in srgb, var(--surface) 82%, transparent); }
.daychip.sel.rest { border-color: color-mix(in srgb, var(--surface) 45%, transparent); }

/* ===== Napív weekly plan day cards (Mai, spec §4.3) =====
   Stacked layout (mezo-lruy): a day header row (label + MA marker + chevron)
   over one padded block per session — type tag + title + state chip on the top
   line, the session's facts as meta pills below. The pre-mezo-lruy single-line
   variant (tag · title · joined meta · chip) collided on long titles. */
/* DS-migrated (mezo-setx.6.3): DS card chrome (r-2xl, sp-4, shadow-sm, token
   border), the eyebrow voice on the day label, ListItem-sized session titles and
   the 48dp tap floor on every tappable session block. */
.dayrow { background: var(--surface-1); border: 1px solid var(--card-border); border-radius: var(--r-2xl); padding: var(--sp-4); box-shadow: var(--shadow-sm); margin-bottom: 10px; }
.dayrow-head { display: flex; align-items: center; justify-content: space-between; gap: 8px; margin-bottom: var(--sp-3); }
.dayrow .d { display: inline-flex; align-items: center; gap: 7px; font: 700 12px/1.4 var(--ff-body); color: var(--text-secondary); text-transform: uppercase; letter-spacing: .18em; }
.dayrow .d small { border-radius: var(--r-full); padding: 2px 8px; font-size: 9.5px; font-weight: 800; color: var(--primary-deep); background: var(--primary-bg); letter-spacing: .10em; }
.dayrow .sess { display: flex; flex-direction: column; gap: 8px; min-width: 0; }
.dayrow .sess .s { display: flex; flex-direction: column; justify-content: center; gap: 8px; width: 100%; min-height: 48px; padding: 10px 12px; border-radius: var(--r-lg); background: var(--surface-recess); border: 0; text-align: left; font-family: inherit; cursor: inherit; }
.dayrow .sess .s-top { display: flex; align-items: center; gap: 8px; min-width: 0; }
.dayrow .sess .s-title { font-size: 16px; font-weight: 600; color: var(--text-primary); line-height: 1.3; min-width: 0; }
.dayrow .sess .s-meta { display: flex; flex-wrap: wrap; gap: 6px; }
/* On the wash-tinted session block the pills invert to the card surface. */
.dayrow .sess .s .metapill { background: var(--surface-1); color: var(--text-secondary); }
.dayrow .sess .s .meta { color: var(--text-tertiary); font-weight: 600; font-size: 14px; }
.dayrow .chev { color: var(--text-tertiary); font-size: 17px; line-height: 1; }
.dayrow.today { border-color: var(--primary-base); box-shadow: var(--shadow-md); cursor: pointer; }
.dayrow.today .chev { color: var(--primary-deep); }
/* Rest day: nothing to lay out — the dashed card stays a single compact line. */
.dayrow.rest { display: flex; align-items: center; gap: 12px; padding: 12px 16px; background: transparent; box-shadow: none; border: 1px dashed var(--divider); }
.dayrow.rest .dayrow-head { margin-bottom: 0; }
.dayrow.rest .sess { flex: 1; }
.dayrow.rest .sess .s { padding: 0; background: transparent; }
/* Status stamps on a session block — the DS Tag spec (9.5/800/0.10em, r-sm). */
.dayrow .done-chip { border-radius: var(--r-sm); padding: 2px 7px; font-size: 9.5px; font-weight: 800; letter-spacing: .10em; text-transform: uppercase; margin-left: auto; flex-shrink: 0; background: var(--wash-sage); color: var(--sage-deep); }
.dayrow .log-chip { border-radius: var(--r-sm); padding: 2px 7px; font-size: 9.5px; font-weight: 800; letter-spacing: .10em; text-transform: uppercase; margin-left: auto; flex-shrink: 0; }

/* ===== Napív today session card (Mai — sport/run, mezo-lruy; K3 language mezo-9bbc) =====
   The gym hero's lighter sibling: icon shield + eyebrow → title → fact pills →
   full-width CTA, tinted per modality via --tc-accent/--tc-wash. */
.todaycard { --tc-accent: var(--tag-sport); --tc-wash: var(--wash-sport); background: linear-gradient(165deg, var(--tc-wash), var(--surface-card) 72%); border: 1px solid color-mix(in srgb, var(--tc-accent) 16%, transparent); border-radius: var(--r-2xl); padding: var(--sp-4); margin: 0 24px 16px; box-shadow: var(--shadow-sm); }
.todaycard-gym { --tc-accent: var(--tag-gym); --tc-wash: var(--wash-gym); }
.todaycard-sport { --tc-accent: var(--tag-sport); --tc-wash: var(--wash-sport); }
.todaycard-cross { --tc-accent: var(--tag-cross); --tc-wash: var(--wash-cross); }
.todaycard-trx { --tc-accent: var(--tag-trx); --tc-wash: var(--wash-trx); }
.todaycard-run { --tc-accent: var(--tag-run); --tc-wash: var(--wash-run); }
.todaycard-body { --tc-accent: var(--sage-deep); --tc-wash: var(--wash-sage); }
.todaycard-mind { --tc-accent: var(--lav-deep);  --tc-wash: var(--wash-lav); }
.todaycard-fuel { --tc-accent: var(--amber-deep); --tc-wash: var(--wash-amber); }
.todaycard.logged { --tc-accent: var(--sage-deep); --tc-wash: var(--wash-sage); }
.todaycard-top { display: flex; align-items: flex-start; gap: var(--sp-3); }
.todaycard-icon { flex: none; width: 44px; height: 44px; border-radius: var(--r-lg); background: var(--surface-card); box-shadow: var(--shadow-xs); display: inline-flex; align-items: center; justify-content: center; font-size: 21px; }
.todaycard.logged .todaycard-icon { background: var(--success-base); color: var(--text-inverse); }
.todaycard-head { flex: 1; min-width: 0; display: flex; flex-wrap: wrap; align-items: center; gap: 8px; }
.todaycard-time { font-size: 14px; font-weight: 600; color: var(--tc-accent); font-variant-numeric: tabular-nums; }
.todaycard-title { flex-basis: 100%; font-family: var(--ff-display); font-size: 18px; font-weight: 700; letter-spacing: -0.02em; line-height: 1.2; color: var(--text-primary); }
.todaycard-state { flex: none; display: inline-flex; align-items: center; border-radius: var(--r-full); padding: 4px 10px; font-size: 10px; font-weight: 700; letter-spacing: .10em; text-transform: uppercase; color: var(--tc-accent); background: var(--surface-card); border: 1px solid color-mix(in srgb, var(--tc-accent) 20%, transparent); }
.todaycard-pills { display: flex; flex-wrap: wrap; gap: var(--sp-2); margin-top: var(--sp-3); }
.todaycard-cta { width: 100%; display: inline-flex; align-items: center; justify-content: center; gap: 7px; margin-top: 14px; padding: 12px 16px; min-height: 48px; border-radius: var(--r-full); font-family: inherit; font-size: 14px; font-weight: 700; cursor: pointer; color: var(--tc-accent); background: var(--surface-card); border: 1px solid color-mix(in srgb, var(--tc-accent) 28%, transparent); }
/* --- Emitted by ItemCard *children*, not by ItemCard itself (mezo-j7u4) --------------------
   The card language's prose slots: `-note` is the sentence that carries the WHY / provenance
   (RitualCard's window framing, WindDownBanner's Walker citation), `-tip*` the explanatory
   advice lines, `-rows` nests shared `ItemRow`s inside the card (the `.tdc .itemrow` idiom).
   No existing rule covers standalone card prose — `.itemrow-t2`, `.donebar-detail` and
   `.fhc-next-tx s` are all structural children of other primitives. */
.todaycard-note { margin-top: 12px; font: 500 13px/1.55 var(--ff-body); color: var(--text-secondary); }
.todaycard-note b { color: var(--success-hover); font-weight: 700; }
.todaycard-tips { margin-top: 12px; display: flex; flex-direction: column; gap: 10px; }
.todaycard-tip { display: flex; align-items: center; gap: 10px; font: 500 13px/1.5 var(--ff-body); color: var(--text-secondary); }
.todaycard-tip b { color: var(--text-primary); font-weight: 700; }
.todaycard-tip-ic { flex: none; width: 30px; height: 30px; border-radius: var(--r-md); background: var(--surface-card);
  display: inline-flex; align-items: center; justify-content: center; font-size: 14px; }
.todaycard-rows { margin-top: 10px; }
.todaycard-rows .itemrow { width: 100%; margin: 0; padding: 8px 4px; background: transparent; box-shadow: none; border-color: transparent; }

/* ===== Napív done bar — shared logged-state bar (mezo-9bbc) ===== */
.donebar { display: flex; align-items: center; gap: 10px; width: 100%; margin-top: 12px; padding: 11px 13px; border-radius: var(--r-lg); background: var(--success-bg); border: 1px solid var(--success-soft); font-family: inherit; text-align: left; cursor: inherit; }
.donebar-check { flex: none; width: 30px; height: 30px; border-radius: 50%; background: var(--success-base); color: var(--text-inverse); display: inline-flex; align-items: center; justify-content: center; }
.donebar-txt { font-size: 13px; font-weight: 700; color: var(--success-hover); }
.donebar-detail { display: block; margin-top: 1px; font-size: 12px; font-weight: 500; color: var(--text-secondary); letter-spacing: 0; text-transform: none; }
/* The tappable variant is a <button> (the whole bar opens the review / re-opens the
   log sheet) — the inherited cursor left it without a pointer (mezo-9bbc review). */
button.donebar { cursor: pointer; }

/* ===== ItemRow — the canonical DS ListItem (mezo-jyua; DS spec mezo-setx.5.1) =====
   Leading 40×40 tone-tinted icon shield (domain tint on an icon = legal data-viz band)
   → 16/600 title + 14/400 subtitle → trailing time / action pill / `↗` link.
   56 px minimum row height; the tone accent rides the --ir-a custom property. */
.itemrow { --ir-a: var(--primary-deep); display: flex; align-items: center; gap: var(--sp-3);
  width: calc(100% - 48px); min-height: 56px; padding: 10px 14px; border-radius: var(--r-lg);
  background: var(--surface-card); border: 1px solid var(--divider); box-shadow: var(--shadow-xs);
  margin: 0 24px 8px; font-family: inherit; text-align: left; }
.itemrow-gym   { --ir-a: var(--tag-gym); }
.itemrow-sport { --ir-a: var(--tag-sport); }
.itemrow-cross { --ir-a: var(--tag-cross); }
.itemrow-trx   { --ir-a: var(--tag-trx); }
.itemrow-run   { --ir-a: var(--tag-run); }
.itemrow-body  { --ir-a: var(--success-hover); }
.itemrow-mind  { --ir-a: var(--lav-deep); }
.itemrow-fuel  { --ir-a: var(--accent-deep); }
.itemrow-ic { flex: none; width: 40px; height: 40px; border-radius: var(--r-md); display: inline-flex;
  align-items: center; justify-content: center; font-size: 17px;
  background: color-mix(in srgb, var(--ir-a) 12%, var(--surface-card)); }
.itemrow-tx { flex: 1; min-width: 0; display: block; }
.itemrow-t1 { display: block; font-size: 16px; font-weight: 600; color: var(--text-primary); line-height: 1.3; }
.itemrow-t2 { display: block; font-size: 14px; font-weight: 400; color: var(--text-secondary); line-height: 1.35; margin-top: 2px; }
.itemrow-tm { flex: none; font-size: 14px; font-weight: 600; color: var(--ir-a); font-variant-numeric: tabular-nums; }
.itemrow-act { flex: none; border-radius: var(--r-full); padding: 9px 14px; font-size: 13px; font-weight: 700;
  font-family: inherit; cursor: pointer; color: var(--text-primary); border: 1px solid var(--divider);
  background: var(--surface-recess); white-space: nowrap; }
.itemrow-act.is-inert { cursor: default; color: var(--text-disabled); background: var(--surface-recess); border-color: transparent; }
/* Whole-row-button shape with a link: the hit area is an INNER button so the <a> is its
   sibling, never its descendant. */
.itemrow-hit { flex: 1; min-width: 0; display: flex; align-items: center; gap: var(--sp-3);
  background: none; border: 0; padding: 0; margin: 0; font: inherit; color: inherit;
  text-align: left; cursor: pointer; }
/* The item's own external content — sits NEXT TO the action pill, never instead of it. */
.itemrow-link { flex: none; width: 40px; height: 40px; border-radius: var(--r-md); display: inline-flex;
  align-items: center; justify-content: center; text-decoration: none; font-size: 14px;
  font-weight: 700; color: var(--ir-a); background: var(--surface-recess); }
.itemrow.is-done { background: transparent; box-shadow: none; border-color: transparent; }
.itemrow.is-done .itemrow-t1 { color: var(--text-secondary); }
.itemrow.is-done .itemrow-ic { background: var(--success-base); color: var(--text-inverse); }
button.itemrow { cursor: pointer; }

/* Floating capsule on real devices/PWA: lift the whole bar above the home indicator
   and keep scroll clearance (replaces the old docked-bar safe-area padding). */
@media (max-width: 519px), (display-mode: standalone), (display-mode: fullscreen), (display-mode: minimal-ui) {
  .tab-bar { bottom: calc(10px + env(safe-area-inset-bottom)); }
  .screen-content { padding-bottom: calc(var(--screen-bottom-pad) + env(safe-area-inset-bottom)); }
  .recipe-save-bar { bottom: calc(88px + env(safe-area-inset-bottom)); }
  .quicklog-fab { bottom: calc(88px + env(safe-area-inset-bottom)); }
  .float-stack { bottom: calc(154px + env(safe-area-inset-bottom)); }
}

/* ===== Napív giant set steppers (active workout, spec §4.5) =====
   Scoped under .steprow — the bare `.stepper` class is the older generic grid
   stepper above (RecipeStepper et al.), and its `display:grid` used to bleed in
   here, pushing the label into a side column and overflowing the excard
   (mezo-eerq). Layout deviates from the mockup's side-flanking ± buttons: value
   line on top, centered button row below — flanking can't fit "107,5 kg" at
   real phone widths without squashing the 40px round buttons. */
.steprow { display: flex; gap: 11px; margin-top: 18px; }
.steprow .stepper { flex: 1; min-width: 0; display: block; background: var(--canvas); border-radius: 22px; padding: 13px 12px 12px; text-align: center; border: 1.5px solid var(--line); }
.steprow .stepper .k { font-size: 10px; font-weight: 800; color: var(--faint); letter-spacing: 1px; text-transform: uppercase; }
.steprow .stepper .row { display: flex; align-items: center; justify-content: center; gap: 26px; margin-top: 8px; }
.steprow .stepper .b { flex: 0 0 40px; width: 40px; height: 40px; border-radius: 50%; background: var(--surface); box-shadow: 0 4px 12px rgba(43,33,24,.10); font-size: 19px; color: var(--coral-deep); display: flex; align-items: center; justify-content: center; font-weight: 800; border: 0; cursor: pointer; font-family: inherit; }
.steprow .stepper .n { margin-top: 4px; font-family: var(--ff-display); font-size: 28px; font-weight: 800; font-variant-numeric: tabular-nums; letter-spacing: -.5px; color: var(--ink); white-space: nowrap; }
.steprow .stepper .n small { font-size: 12px; color: var(--faint); font-weight: 800; }
/* Tap-to-edit value (mezo-o7ds): the resting .n renders as a <button> (visually
   identical — reset the UA button chrome), editing swaps in an <input> that must
   inherit the giant display font instead of the UA input font. */
.steprow .stepper button.n { display: block; width: 100%; background: none; border: 0; padding: 0; cursor: pointer; }
.steprow .stepper .n input { font: inherit; letter-spacing: inherit; color: inherit; background: none; border: 0; outline: none; padding: 0; text-align: center; }

/* ===== Napív active-workout header (spec §4.5) ===== */
.wk-top { display: flex; align-items: center; gap: 12px; padding: 12px 24px 0; position: sticky; top: 0; z-index: 5; background: var(--canvas); }
.wk-top .back { width: 42px; height: 42px; border-radius: 50%; background: var(--surface); box-shadow: var(--np-shadow-row); display: flex; align-items: center; justify-content: center; color: var(--sub); font-size: 18px; border: 0; cursor: pointer; flex-shrink: 0; font-family: inherit; }
/* .tt is now a <button> (opens the overview) — zero the UA button padding so the
   title/counter stay flush-left with the back pill (global reset omits padding). */
.wk-top .tt { min-width: 0; padding: 0; text-align: left; }
.wk-top .tt .t1 { font-family: var(--ff-display); font-size: 18px; font-weight: 800; color: var(--ink); white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
.wk-top .tt .t2 { font-size: 10.5px; color: var(--faint); font-weight: 800; letter-spacing: .6px; text-transform: uppercase; }
.exdots { margin-left: auto; display: flex; gap: 5px; flex-shrink: 0; }
.exdots i { width: 8px; height: 8px; border-radius: 50%; background: var(--line); }
.exdots i.don { background: var(--sage); }
.exdots i.cur { background: var(--coral); box-shadow: 0 0 0 3px rgba(255,107,74,.22); }
.exdots i.skp { background: transparent; border: 1.5px dashed var(--line); box-sizing: border-box; }

/* ===== Napív execution card (spec §4.5) ===== */
.donebtn { margin-top: 16px; width: 100%; background: linear-gradient(135deg, var(--cta-g1), var(--cta-g2)); color: #fff; border-radius: 999px; padding: 16px 0; text-align: center; font-weight: 800; font-size: 16px; border: 0; cursor: pointer; font-family: inherit; box-shadow: 0 10px 24px color-mix(in srgb, var(--cta-g2) 35%, transparent), inset 0 1px 0 rgba(255,255,255,.25); }

/* Generic tabular/monospace utility (JetBrains Mono) — the execution card v2's
   stat-strip/subrow numeric values (mezo-8xmf). */
.mono { font-family: var(--ff-mono); font-variant-numeric: tabular-nums; }

/* Session progress bar (under the wk-top header) — one flex segment per
   exercise, family-coloured, opacity carries the done/current/upcoming state. */
.wkx-progressbar { display: flex; gap: 3px; height: 7px; border-radius: 4px; overflow: hidden; margin: 10px 24px 0; }
.wkx-progressbar span { display: block; transition: opacity .3s ease; }

.wkx-stat-ok { color: var(--sage-deep); font-weight: 800; font-size: 12px; }
.wkx-stat-dev { color: var(--amber-deep); font-weight: 800; font-size: 10px; }

/* ===== In-card rest timer bar (CTA-morph, mezo-xt65) — swaps in for .donebtn while a
   rest runs. Same pill radius + rendered height as .donebtn => zero layout shift on the
   morph. Label is var(--ink): readable over BOTH the coral fill and the exposed warm
   track (a white label would strand on cream once the fill drains past it). ===== */
.restbar { position: relative; margin-top: 16px; border-radius: 999px; overflow: hidden; background: var(--warm); box-shadow: inset 0 1px 3px rgba(43,33,24,.08); }
.restbar .fill { position: absolute; top: 0; bottom: 0; left: 0; background: linear-gradient(135deg, var(--cta-g1), var(--cta-g2)); transition: width .5s linear; }
.restbar.paused .fill { background: var(--faint); transition: none; }
.restbar .lay { position: relative; display: flex; align-items: center; justify-content: space-between; gap: 10px; padding: 6px 7px 6px 18px; min-height: 53px; box-sizing: border-box; }
.restbar .t { text-align: left; font-weight: 800; font-size: 16px; color: var(--ink); font-variant-numeric: tabular-nums; line-height: 1.1; }
.restbar .t small { display: block; font-size: 8px; letter-spacing: 1px; text-transform: uppercase; opacity: .75; font-weight: 800; }
.restbar .btns { display: flex; gap: 7px; flex: none; }
.restbar .btns button { width: 40px; height: 40px; border-radius: 50%; border: 0; background: var(--surface); color: var(--coral-deep); font-size: 14px; font-weight: 800; display: flex; align-items: center; justify-content: center; cursor: pointer; box-shadow: 0 2px 6px rgba(43,33,24,.18); font-family: inherit; }
@media (prefers-reduced-motion: reduce) { .restbar .fill { transition: none; } }
/* Active workout · two-way pager bar (spec 2026-07-15, mockup B) — replaces the
   old one-way .nextex row. Big tap targets; ends disable at the list edges. */
.pagerbar { display: flex; gap: 8px; margin: 10px 24px 6px; }
.pagerbar .pg { flex: 1; display: flex; align-items: center; gap: 8px; background: var(--surface); border: 1px solid var(--border-subtle); border-radius: 14px; padding: 10px 12px; min-width: 0; }
.pagerbar .pg:disabled { opacity: .35; }
.pagerbar .pg.next { justify-content: flex-end; text-align: right; }
.pagerbar .ar { color: var(--coral-deep); font-size: 16px; font-weight: 700; flex: none; }
.pagerbar .lbl { display: flex; flex-direction: column; min-width: 0; }
.pagerbar .k { font-size: 8px; letter-spacing: .12em; text-transform: uppercase; color: var(--text-tertiary); font-family: var(--ff-body); font-weight: 800; }
.pagerbar .n { font-size: 11px; font-weight: 600; color: var(--text-primary); white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
.rirrow { display: flex; gap: 6px; margin-top: 12px; align-items: center; }
.rirrow .rk { font-size: 10px; font-weight: 800; color: var(--faint); letter-spacing: .6px; text-transform: uppercase; margin-right: 4px; }
.rirrow button { flex: 1; padding: 6px 0; border-radius: 12px; border: 1.5px solid var(--line); background: var(--canvas); color: var(--sub); font-family: var(--ff-display); font-size: 14px; font-weight: 800; cursor: pointer; }
.rirrow button[aria-pressed="true"] { border-color: var(--coral); color: var(--coral-deep); background: var(--surface); box-shadow: 0 0 0 1px var(--coral); }
.setnote { width: 100%; margin-top: 12px; padding: 11px 14px; border-radius: 14px; border: 1.5px solid var(--line); background: var(--canvas); color: var(--ink); font-size: 13px; font-family: inherit; }
.setnote::placeholder { color: var(--faint); }
.aistrip { display: flex; gap: 9px; background: rgba(255,179,71,.16); border-radius: 20px; padding: 13px 15px; margin: 12px 24px 0; }
.aistrip p { font-size: 12.5px; line-height: 1.55; color: #7A4A18; font-weight: 500; }
:root[data-theme="dark"] .aistrip p { color: #E8B36B; }

/* Progressive-overload signal banner (mezo-5pfe) — replaces .aistrip in the
   active-workout screen whenever the engine emits a structured progression.
   Three visual states by lever: weight=coral, rep=sage, hold/deload=amber. */
/* §3.4 (mezo-ju4j6.19): ez a sáv a gyakorlat-kártyán BELÜL él. Bekeretezett, tónusos
   dobozként egy mosott csempén ült egy másik mosott csempe — a stíluskönyv §3.4 szerint
   pont az a felállás, amiben mindkettő eltűnik. Most §2.2 B CELLA: lapos tónus + tinta,
   keret és árnyék nélkül, a ház `--mz-cell-*` párjaival (így a sötét téma is követi; a
   régi `--coral`/`--sage-deep`/`--amber-deep` a `--dv-` előtti palettáról jött, A.4 7.
   szabály). A HUE marad: ő mondja meg, melyik kart mozdítja a progresszió. */
.pobanner { border:0; border-radius:14px; padding:11px 12px; margin:8px 24px; box-shadow:none; background:var(--mz-cell-coral-bg); }
.pobanner.po-rep { background:var(--mz-cell-sage-bg); }
.pobanner.po-hold { background:var(--mz-cell-gold-bg); }
.pobanner-lab { display:flex; align-items:center; gap:8px; margin-bottom:9px; }
.pobanner-lab .txt { display:inline-flex; align-items:center; gap:5px; font-size:10px; letter-spacing:.08em; text-transform:uppercase; color:var(--mz-cell-coral-ink); font-weight:700; white-space:nowrap; }
.pobanner-lab .txt .icon { width:14px; height:14px; flex:0 0 auto; }
.pobanner.po-rep .pobanner-lab .txt { color:var(--mz-cell-sage-ink); }
.pobanner.po-hold .pobanner-lab .txt { color:var(--mz-cell-gold-ink); }
/* A delta-jelvény a cellán belül PAJZS (§3.1): telített foltként a cella tetején egy
   harmadik fokozatot nyitott volna. */
.pobanner-lab .delta { margin-left:auto; border:0; background:var(--surface-1); box-shadow:inset 0 0 0 1px var(--border-subtle); color:var(--mz-cell-coral-ink); padding:3px 9px; border-radius:999px; font-size:11px; font-weight:700; white-space:nowrap; }
.pobanner.po-rep .pobanner-lab .delta { color:var(--mz-cell-sage-ink); }
.pobanner.po-hold .pobanner-lab .delta { color:var(--mz-cell-gold-ink); }
.pobanner-cells { display:flex; align-items:stretch; }
.pobanner-cells .cell { flex:1; min-width:0; }
.pobanner-cells .cell.now { padding-left:12px; border-left:1px solid color-mix(in srgb, var(--mz-cell-coral-ink) 28%, transparent); margin-left:12px; }
.pobanner.po-rep .cell.now { border-left-color: color-mix(in srgb, var(--mz-cell-sage-ink) 28%, transparent); }
.pobanner.po-hold .cell.now { border-left-color: color-mix(in srgb, var(--mz-cell-gold-ink) 28%, transparent); }
.pobanner-cells .clab { font-size:9px; letter-spacing:.05em; text-transform:uppercase; color:var(--sub); }
.pobanner-cells .cval { font-size:15px; font-weight:650; margin-top:3px; white-space:nowrap; }
.pobanner-cells .cell.now .cval { font-size:19px; }
.pobanner-cells .cell.now .cval.up { color:var(--mz-cell-coral-ink); }
.pobanner.po-rep .cell.now .cval.up { color:var(--mz-cell-sage-ink); }
.pobanner.po-hold .cell.now .cval.up { color:var(--mz-cell-gold-ink); }
/* 320px: a két cella `white-space: nowrap`-es értékei egymásra csúsztak (a „MÚLT HÉT
   102,5 × 9 · RIR 2" és a „MA A CÉL 105 × 10" egy sorban nem fér ki). Keskeny kijelzőn
   egymás ALÁ kerülnek, és a függőleges elválasztó vízszintesre vált — a tartalom marad,
   csak a tördelés enged (mezo-ju4j6.11). */
@media (max-width: 360px) {
  .pobanner-cells { flex-direction: column; }
  .pobanner-cells .cell.now {
    padding-left: 0; margin-left: 0; margin-top: 8px; padding-top: 8px;
    border-left: 0; border-top: 1px solid color-mix(in srgb, var(--mz-cell-coral-ink) 28%, transparent);
  }
  .pobanner.po-rep .pobanner-cells .cell.now { border-top-color: color-mix(in srgb, var(--mz-cell-sage-ink) 28%, transparent); }
  .pobanner.po-hold .pobanner-cells .cell.now { border-top-color: color-mix(in srgb, var(--mz-cell-gold-ink) 28%, transparent); }
}

/* ===== Napív S6 — Fuel accent vocabulary ===== */
.pghead-np.sage .over { color: var(--sage-deep); }
:root {
  --wash-sage: #EAF0E3;
  --wash-amber: #FFF3E4;
  --wash-lav: #EEEBF6;
}
:root[data-theme="dark"] {
  --wash-sage: rgba(127,164,138,.16);
  --wash-amber: rgba(255,179,71,.16);
  --wash-lav: rgba(155,143,196,.16);
}

/* ===== Napív S7 — Me accent vocabulary (spec §4.6) ===== */
.pghead-np.lav .over { color: var(--lav-deep); }
/* P1: was #9A6A12 / dark #E3B565 — the accent ramp's text-safe stop is the
   same role (light #8E6E1F, dark lifts to #F2D094), so it aliases like the rest. */
:root { --amber-deep: var(--accent-deep); }

/* ===== Napív kcal gauge (Fuel Mai, spec §4.4) ===== */
.gauge { position: relative; display: flex; flex-direction: column; align-items: center; }
.gauge .big { position: absolute; top: 56px; text-align: center; }
.gauge .big .n { font-family: var(--ff-display); font-size: 37px; font-weight: 800; font-variant-numeric: tabular-nums; letter-spacing: -.5px; color: var(--ink); }
.gauge .big .u { font-size: 11.5px; color: var(--faint); font-weight: 700; }
@media (prefers-reduced-motion: no-preference) {
  .gauge-p { transition: stroke-dasharray .9s ease; }
}

/* ===== Napív fuel timeline slots (spec §4.4) ===== */
.slot { display: flex; gap: 12px; background: var(--surface); border-radius: 20px; padding: 13px 15px; box-shadow: var(--np-shadow-row); margin-bottom: 9px; align-items: center; }
.slot.next { box-shadow: 0 0 0 2px var(--sage), 0 10px 24px color-mix(in srgb, var(--sage) 20%, transparent); }
.slot.done { opacity: .78; }
.slot.missed { opacity: .72; }
.slot.missed .fav { filter: grayscale(1); opacity: .6; }
.slot .fav { width: 42px; height: 42px; border-radius: 15px; display: flex; align-items: center; justify-content: center; font-size: 19px; flex-shrink: 0; }
.slot .tx { flex: 1; min-width: 0; }
.slot .t1 { font-size: 14px; font-weight: 800; color: var(--ink); }
.slot .mrow { display: flex; align-items: center; gap: 9px; font-size: 10.5px; color: var(--faint); font-weight: 700; margin-top: 4px; flex-wrap: wrap; }
.slot .mrow b { color: var(--ink); font-weight: 800; font-size: 11.5px; }
.slot .mm { display: inline-flex; align-items: center; gap: 4px; font-size: 10.5px; font-weight: 800; color: var(--sub); }
.slot .mm i { width: 6px; height: 6px; border-radius: 50%; }
.slot .st { width: 28px; height: 28px; border-radius: 50%; display: flex; align-items: center; justify-content: center; font-size: 13px; flex-shrink: 0; }
.slot.done .st { background: var(--wash-sage); color: var(--sage-deep); }
.chx { border: 0; cursor: pointer; font: inherit; border-radius: 999px; padding: 7px 13px; font-size: 11.5px; font-weight: 700; }

/* ===== Napív fuel Mai — chips + macro soft bars (spec §4.4) ===== */
.fuelchips { display: flex; gap: 7px; justify-content: center; margin-top: 10px; flex-wrap: wrap; }
/* .macror/.mac (the DayBudgetCard macro bars) RETIRED — window-river Task 6 (mezo-jgh9): DayBudgetCard
   was their only consumer, deleted with the ablak-folyam recomposition (its job moved into KeretBelt's
   own macro-bar rows, itself since retired in turn — keret-hero Task 4, mezo-c9t5 — the macro readout
   now lives in KeretHero's `.khero-rings`). MacroCells (shared/ui) is an unrelated component and never
   used this family. */

/* ===== Napív Me identity header (spec §4.6) ===== */
.mehead { display: flex; align-items: center; gap: 14px; padding: 14px 24px 0; }
.mehead .avatar { width: 64px; height: 64px; border-radius: 50%; background: linear-gradient(140deg, #EEEBF6, #E2DCF0); color: var(--lav-deep); font-family: var(--ff-display); font-weight: 800; font-size: 22px; display: flex; align-items: center; justify-content: center; box-shadow: 0 0 0 3px var(--surface), 0 0 0 5.5px var(--lav), 0 10px 22px rgba(122,109,168,.25); flex-shrink: 0; }
.mehead .t1 { font-family: var(--ff-display); font-size: 24px; font-weight: 800; letter-spacing: -.3px; color: var(--ink); }
.mehead .t2 { font-size: 12.5px; color: var(--sub); font-weight: 600; margin-top: 1px; }
:root[data-theme="dark"] .mehead .avatar { background: linear-gradient(140deg, rgba(155,143,196,.25), rgba(122,109,168,.25)); }

/* ===== Napív biometria + growth summary cards (Profil, spec §4.6) ===== */
.biocard .bhd { display: flex; justify-content: space-between; align-items: center; margin-bottom: 13px; }
.biocard .bhd h3 { font-size: 14.5px; font-weight: 800; color: var(--ink); }
.biocard .bhd button { border: 0; background: none; cursor: pointer; font: inherit; font-size: 12px; font-weight: 700; color: var(--lav-deep); }
.biogrid { display: grid; grid-template-columns: 1fr 1fr; gap: 11px 14px; }
.bio .k { font-size: 10px; color: var(--faint); font-weight: 800; letter-spacing: .4px; text-transform: uppercase; }
.bio .v { font-size: 17px; font-weight: 800; font-family: var(--ff-display); margin-top: 2px; color: var(--ink); font-variant-numeric: tabular-nums; }
.bio .v small { font-size: 11px; color: var(--sub); font-weight: 700; }
.tdee { display: flex; justify-content: space-between; align-items: center; border-top: 1.5px solid var(--line); margin-top: 14px; padding-top: 13px; }
.tdee .k { font-size: 12px; font-weight: 700; color: var(--sub); }
.tdee .v { font-family: var(--ff-display); font-size: 20px; font-weight: 800; color: var(--sage-deep); }
.growth2 .hd { display: flex; justify-content: space-between; align-items: center; }
.growth2 .hd .t { font-size: 14px; font-weight: 800; color: var(--ink); }
.growth2 .hd .xp { background: var(--wash-amber); color: var(--amber-deep); font-size: 11px; font-weight: 800; border-radius: 999px; padding: 6px 12px; white-space: nowrap; }
.skl { display: flex; align-items: center; gap: 9px; margin-top: 11px; }
.skl .k { flex: 0 0 112px; font-size: 12.5px; font-weight: 700; color: var(--sub); min-width: 0; overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }
.skl .bar { flex: 1; height: 9px; border-radius: 999px; background: var(--warm); overflow: hidden; }
.skl .bar i { display: block; height: 100%; border-radius: 999px; background: linear-gradient(90deg, var(--lav), #B7A8E0); }
.skl .lv { width: 36px; text-align: right; font-size: 12px; font-weight: 800; color: var(--lav-deep); }
@media (prefers-reduced-motion: no-preference) {
  .skl .bar i { transform-origin: left; transform: scaleX(0);
                animation: np-grow .9s var(--np-ease-ios) forwards; animation-delay: var(--d, .45s); }
}

/* ===== AppHero v2 — compact single-row sticky header on all 5 sections (mezo-ugqb).
   Sticky at z 45: above content and tab-bar (40), below StatusBar (50) / island (60) /
   sheets (200+). The border-bottom is the header/content separator from the spec. ===== */
.apphero {
  display: flex; align-items: center; gap: 10px; padding: 8px 24px;
  position: sticky; top: 0; z-index: 45;
  background: var(--canvas); border-bottom: 1px solid var(--line);
}
.apphero .avwrap { position: relative; width: 48px; height: 48px; flex-shrink: 0; }
.apphero .avlink { position: absolute; inset: 0; display: block; }
.apphero .avatar {
  position: absolute; inset: 5px; border-radius: 50%;
  background: linear-gradient(140deg, #EEEBF6, #E2DCF0); color: var(--lav-deep);
  font-family: var(--ff-display); font-weight: 800; font-size: 15px;
  display: flex; align-items: center; justify-content: center;
}
:root[data-theme="dark"] .apphero .avatar { background: linear-gradient(140deg, rgba(155,143,196,.25), rgba(122,109,168,.25)); }
.apphero .lvbadge {
  position: absolute; right: -2px; bottom: -2px; min-width: 18px; height: 18px;
  border-radius: 999px; background: var(--coral); color: #fff; font-size: 9.5px; font-weight: 800;
  display: flex; align-items: center; justify-content: center; border: 2px solid var(--canvas);
  padding: 0 3px; font-family: var(--ff-display); text-decoration: none;
}
.apphero .idcol { min-width: 0; }
.apphero .t1 {
  display: block; font-family: var(--ff-display); font-size: 16px; font-weight: 700;
  letter-spacing: -.02em; color: var(--ink); text-decoration: none;
  white-space: nowrap; overflow: hidden; text-overflow: ellipsis;
}
.apphero .t2 { display: block; background: none; border: none; padding: 0; cursor: pointer; font-size: 10px; color: var(--lav-deep); font-weight: 800; margin-top: 1px; letter-spacing: .4px; text-transform: uppercase; text-align: left; font-family: var(--ff-body); }
.apphero .counters { margin-left: auto; display: flex; align-items: center; gap: 2px; }
.apphero .cnt {
  background: none; border: none; padding: 6px 4px; cursor: pointer;
  font: 800 12px/1 var(--ff-body); text-decoration: none; white-space: nowrap;
}
.apphero .cnt.fire { color: var(--amber-deep); }
.apphero .cnt.quest { color: var(--coral-deep); }
.apphero .cnt.coin { color: var(--sage-deep); }
.apphero .util { display: flex; gap: 7px; align-items: center; }

/* ===== SubNavDropdown — sub-nav popover in the sticky AppHero row (mezo-ugqb) =====
   z-scale: chip lives inside .apphero (z 45, above tab-bar 40). The menu paints
   within that stacking context. The backdrop is portaled into .phone-screen (same
   target + fallback as Sheet, see Sheet.tsx) so its `position: absolute; inset: 0`
   covers the whole device viewport instead of escaping the phone mockup on desktop —
   z 44 keeps it above content + tab-bar (40) but strictly below the header/menu (45)
   and sheets (200+), independent of portal DOM order. */
.subnav-dd { position: relative; }
.subnav-dd .dd-chip {
  /* DS tab-label voice (12/700) on a pill chip; 40px min target inside the 65px hero row */
  display: inline-flex; align-items: center; gap: 5px; min-height: 40px;
  background: var(--surface-card); border: 1px solid var(--divider); border-radius: var(--r-full);
  padding: 7px 12px; font: 700 12px/1 var(--ff-body); letter-spacing: .02em;
  color: var(--subnav-accent, var(--text-primary)); cursor: pointer; white-space: nowrap;
}
.dd-backdrop {
  position: absolute; inset: 0; background: rgba(0, 0, 0, 0.35);
  border: none; padding: 0; cursor: default; z-index: 44;
}
.subnav-dd .dd-menu {
  position: absolute; top: calc(100% + 8px); right: 0; min-width: 190px;
  background: var(--surface-card); border: 1px solid var(--divider);
  border-radius: var(--r-lg); padding: 5px 0; box-shadow: var(--shadow-lg);
}
.subnav-dd .dd-item {
  /* DS menu items = ListItem rows: 48dp targets, caption-floor 14px labels */
  display: flex; align-items: center; justify-content: space-between; gap: 10px;
  width: 100%; min-height: 48px; padding: 12px 16px; font: 600 14px/1.2 var(--ff-body);
  color: var(--text-secondary); text-decoration: none; background: none; border: none;
  cursor: pointer; text-align: left;
}
.subnav-dd .dd-item.on { color: var(--subnav-accent, var(--primary-deep)); }
.subnav-dd .dd-sep { border-top: 1px solid var(--divider); margin: 4px 0; }

.nf-dot { width: 7px; height: 7px; border-radius: 50%; background: var(--primary-base); position: absolute; left: 6px; top: 50%; transform: translateY(-50%); }
.nf-ico { width: 32px; height: 32px; border-radius: 10px; flex-shrink: 0; display: flex; align-items: center; justify-content: center; font-size: 15px; }
.nf-ico.pattern { background: color-mix(in srgb, var(--dv-lav) 18%, transparent); }
.nf-ico.knowledge { background: color-mix(in srgb, var(--dv-sage) 20%, transparent); }
.nf-ico.prediction { background: color-mix(in srgb, var(--dv-sky) 18%, transparent); }
.nf-ico.experiment { background: color-mix(in srgb, var(--dv-amber) 22%, transparent); }
.nf-ico.memoir { background: color-mix(in srgb, var(--primary-base) 12%, transparent); }
.nf-ico.memory { background: var(--surface-recess); }
.nf-ico.goal { background: color-mix(in srgb, var(--dv-coral) 18%, transparent); }
/* mezo-0cbh — a négy új fajta három új tintje. `people` az emberi/gráf jelölteké,
   `habit` a formálódásé, `character` a havi portréé. */
.nf-ico.people { background: color-mix(in srgb, var(--dv-sky) 22%, transparent); }
.nf-ico.habit { background: color-mix(in srgb, var(--dv-sage) 24%, transparent); }
.nf-ico.character { background: color-mix(in srgb, var(--dv-lav) 24%, transparent); }

/* ===== Habit routine =====
   The `.hab-chain`/`.hab-row`/`.hab-node`/`.hab-main`/`.hab-anchor`/`.hab-title`/`.hab-link`/
   `.hab-note`/`.hab-right`/`.hab-xp`/`.hab-earned` thread and its `hab-pulse` keyframes
   retired with `RoutineCard` (mezo-j7u4) — a habit is an `.itemrow` in its face's TodoCard
   now. `.hab-act` below survives (CreedSheet/IntentionSheet wear it); `.hab-g*`/`.hab-s*`
   below belong to Growth's "Rutin" tab (RoutinesTab). */

/* current-habit primary action — gradient pill, soft glow, press feedback + icon */
.hab-act {
  display: inline-flex; align-items: center; gap: 5px;
  padding: 8px 14px; border-radius: 999px; font: 700 12px/1 var(--ff-body);
  color: #fff; border: none; white-space: nowrap; cursor: pointer;
  background: linear-gradient(135deg, var(--lav), var(--lav-deep));
  box-shadow: 0 2px 7px color-mix(in srgb, var(--lav-deep) 42%, transparent);
  transition: transform .12s ease, box-shadow .12s ease, filter .12s ease;
}
.hab-act svg { width: 13px; height: 13px; }
.hab-act:hover { filter: brightness(1.05); }
.hab-act:active { transform: scale(.94); box-shadow: 0 1px 3px color-mix(in srgb, var(--lav-deep) 34%, transparent); }
.hab-act:disabled { opacity: .55; cursor: default; box-shadow: none; }

/* The `.rt-toggle`/`.rt-label`/`.rt-eve`/`.rt-chev` afternoon summary retired with
   `RoutineCard` (mezo-j7u4): retroactive logging needs no toggle now — every pending chain
   step is directly tappable on its face. */

/* Growth "Rutin" tab — 28-day strength rows (title + % on top, bar as an underline) */
.hab-gstat { flex: 1; background: var(--warm); border-radius: 14px; padding: 12px 14px; }
.hab-gnum { font: 700 26px/1 var(--ff-display); color: var(--ink); letter-spacing: -.02em; }
.hab-gof { font: 600 12px/1 var(--ff-body); color: var(--faint); }
.hab-glab {
  font: 700 10.5px/1.3 var(--ff-body); text-transform: uppercase; letter-spacing: .05em;
  color: var(--faint); margin-top: 5px;
}
.hab-gtrack { height: 5px; border-radius: 999px; background: var(--surface-1); margin-top: 9px; overflow: hidden; }
.hab-gfill { height: 100%; border-radius: 999px; }
.hab-srow { padding: 9px 0; }
.hab-srow + .hab-srow { border-top: 1px solid var(--border-subtle); }
.hab-stop { display: flex; align-items: center; gap: 8px; }
.hab-sdot { width: 15px; text-align: center; font-size: 13px; flex: 0 0 auto; }
.hab-sname {
  flex: 1; min-width: 0; font: 600 13.5px/1.3 var(--ff-body); color: var(--ink);
  white-space: nowrap; overflow: hidden; text-overflow: ellipsis;
}
.hab-spct { font: 700 12.5px/1 var(--ff-mono); color: var(--lav-deep); letter-spacing: -.02em; flex: 0 0 auto; }
.hab-sbar { height: 7px; border-radius: 999px; background: var(--warm); overflow: hidden; margin-top: 7px; margin-left: 23px; }
.hab-sbar i { display: block; height: 100%; border-radius: 999px; background: linear-gradient(90deg, var(--lav), #B7A8E0); }

/* The `.quest*`/`.quests-*` card family (mezo-vj0b) retired with `TodayQuestsCard`
   (mezo-j7u4): a quest is an `.itemrow` inside its face's TodoCard now, and Growth's
   own `DailyQuestsCard` never wore these rules. */

/* ===== Daily intention (mezo-a686) =====
   The full-card `.intent*` banner retired with the daypart faces (mezo-j7u4): the creed became
   the one-line `.creedchip` below and the foci moved into the face's TodoCard/hero rows.
   `.intent-creed` retired in mezo-setx.5.5 — IntentionSheet's creed quote wears the
   DS `.shcreed` Fraunces meta-voice callout now (sheet form family, above the .vuln block). */

/* ===== Intention creed chip (mezo-j7u4) ===== */
.creedchip { margin: 0 24px 16px; padding: 12px 14px; border-radius: var(--r-lg);
  background: var(--wash-lav); }
.creedchip-hd { display: flex; gap: 10px; align-items: center; }
.creedchip-st { color: var(--lav-deep); font-size: 13px; }
.creedchip-cnt { flex: none; font-size: 10px; font-weight: 700; letter-spacing: .06em;
  color: var(--text-muted); font-variant-numeric: tabular-nums; }
/* the day's stated intentions — the `◆` prose rows the retired `.fx` list used */
.creedchip-foci { margin-top: 10px; display: flex; flex-direction: column; gap: 6px; }
.creedchip-fx { display: flex; gap: 8px; align-items: flex-start; font: 500 14px/1.4 var(--ff-body); color: var(--text-primary); }
.creedchip-fx-mark { flex: 0 0 auto; color: var(--lav-deep); font-size: 9px; line-height: 1.8; }
/* the creed is a quote — narrative meta-text, so it speaks Fraunces italic (DS text-meta-sm) */
.creedchip-tx { flex: 1; min-width: 0; text-align: left; font: italic 500 14px/1.45 var(--ff-serif);
  color: var(--lav-deep); }
/* the creed text doubles as the CreedSheet opener — a button, stripped back to plain text */
button.creedchip-tx { border: 0; background: none; padding: 0; cursor: pointer; }
.creedchip-go { flex: none; font-size: 12px; font-weight: 700; color: var(--lav-deep); border: 0;
  border-radius: var(--r-full); padding: 7px 11px; font-family: var(--ff-body); font-style: normal; cursor: pointer;
  background: color-mix(in srgb, var(--surface-card) 70%, transparent); white-space: nowrap; }

/* evening reflect — the option row of `ReflectSheet` (its only consumer). The wrapper
   `.reflect`/`.reflect-q` and the `.reflect-done` confirmation belonged to the retired
   IntentionBanner's `variant="reflect"` block, deleted with it in mezo-d20.9.1; the sheet
   brings its own heading and closes on answer, so only the options language survives. */
.reflect-opts { display: flex; gap: 8px; }
.reflect-opt {
  flex: 1; min-height: 44px; padding: 10px 6px; border: 0; border-radius: var(--r-md);
  font: 700 13px/1 var(--ff-body); color: var(--text-secondary); font-family: inherit;
  background: var(--surface-recess); text-align: center; cursor: pointer;
  transition: transform var(--duration-fast) var(--ease-out);
}
.reflect-opt:active { transform: scale(.97); }
.reflect-opt.on-yes { background: var(--success-bg); color: var(--success-hover); box-shadow: inset 0 0 0 1.5px var(--success-soft); }

/* ===== StatStrip — the DS 3-cell glance strip (shared/ui/StatStrip, mezo-setx.5.1) ===== */
.statstrip { display: grid; grid-auto-flow: column; grid-auto-columns: 1fr; gap: 1px;
  background: var(--divider); border: 1px solid var(--divider); border-radius: var(--r-lg); overflow: hidden; }
.statstrip-c { background: var(--surface-card); padding: 10px; text-align: center; }
.statstrip-v { font-size: 20px; font-weight: 700; letter-spacing: -0.02em; line-height: 1.05;
  color: var(--text-primary); font-variant-numeric: tabular-nums; }
.statstrip-u { font-size: 11px; font-weight: 500; color: var(--text-muted); margin-left: 2px; }
.statstrip-l { font-size: 9px; font-weight: 700; letter-spacing: .18em; text-transform: uppercase;
  color: var(--text-muted); margin-top: 2px; }
/* Today's „Ma eddig" placement (FaceMorning) */
.today-stats { margin: 0 24px 16px; }

/* ===== Sheet form fields — the DS form composition for the Today sheets (mezo-setx.5.5):
   visible label over a bordered 16px field (Rule 17 + the input-size floor), focus ring
   from the shared token. `.shcreed` is the creed quote's Fraunces meta-voice callout. ===== */
.shlabel { font: 500 14px/1.5 var(--ff-body); color: var(--text-secondary); }
.shta { width: 100%; padding: 12px 14px; border-radius: var(--r-md); border: 1px solid var(--divider);
  background: var(--surface-card); color: var(--text-primary); font: 400 16px/1.45 var(--ff-body); resize: none; }
.shta:focus-visible { border-color: var(--primary-base); box-shadow: var(--shadow-focus); }
.shcreed { padding: 10px 12px; border-radius: var(--r-md); background: var(--wash-lav);
  font: italic 500 14px/1.45 var(--ff-serif); color: var(--lav-deep); }

/* ===== VulnerabilityCard — the coral info-Alert tone notice (mezo-setx.5.1) ===== */
.vuln { margin: 0 24px 16px; padding: 12px 14px; border-radius: var(--r-lg);
  background: var(--primary-bg); border: 1px solid var(--primary-soft); }
.vuln-eyebrow { font: 700 12px/1.4 var(--ff-body); letter-spacing: .22em; text-transform: uppercase;
  color: var(--primary-deep); }
.vuln p { font: 500 13px/1.55 var(--ff-body); color: var(--text-primary); margin-top: 6px; }

/* the companion's bubble, muted off coral onto the anchor amber. Doubled-up
   selectors on purpose: the `.coach-bubble` base block sits LATER in this file,
   so a same-specificity override here would lose the source-order tie. */
.coach-bubble.anch-coach { margin: var(--sp-5) 24px 16px;
  background: color-mix(in srgb, var(--anchor-accent) 7%, transparent);
  border-left-color: var(--anchor-accent); }
.coach-bubble.anch-coach .cb-avatar { background: radial-gradient(circle at 30% 30%, var(--accent-soft), var(--anchor-accent));
  box-shadow: 0 0 12px color-mix(in srgb, var(--anchor-accent) 30%, transparent); }
.coach-bubble.anch-coach .cb-eyebrow, .coach-bubble.anch-coach .cb-body { color: var(--anchor-text); }
/* ===== WindDownBanner — the Today evening/night band (mezo-d71m, spec D2/D3) =====
   The dim/winddown phases wear the shared `ItemCard` since mezo-j7u4, so the light-surface
   `.wdb*` rules are gone; only the night entry row keeps its own surface. */
/* night entry row — literal dark (theme-independent, like NightPage; also used by SleepPage) */
.wdb-night { display: flex; align-items: center; gap: 14px; margin: 8px 24px; padding: 20px 18px;
             border-radius: 22px; text-decoration: none;
             background: linear-gradient(140deg, #1A1622 0%, #221E1B 82%);
             box-shadow: 0 2px 8px rgba(0,0,0,.28); }
.wdb-night-moon { font-size: 22px; filter: drop-shadow(0 0 7px rgba(185,172,217,.45)); }
.wdb-night-tx { flex: 1; display: flex; flex-direction: column; gap: 4px; }
.wdb-night-t1 { font: 600 16px/1.3 var(--ff-display); color: #F5EFE6; }
.wdb-night-t2 { font: 500 11.5px/1.55 var(--ff-body); color: var(--text-secondary); }
.wdb-night-chev { color: #B9ACD9; font-size: 17px; }

/* ═════════ Today három sziget (mezo-euze) ═════════
   The sky: three islands, exactly one big. The shell is ONE continuous bubble —
   capsule 29px ↔ big 34px radius on a single spring curve (flex + radius together),
   the capsule layer absolute on the shell and cross-fading, so the morph never
   pauses or shows an empty frame. Every animation here has its reduced-motion
   counterpart at the end of this section, `:where()`-wrapped so the disable
   cannot be outranked (the todayReducedMotion contract). */
/* The app scroller becomes a flex column while Today's sky is mounted, so the sky
   FILLS the viewport (L0 never scrolls — only the L1 list inside an island). */
.screen-content:has(.sky-islands) { display: flex; flex-direction: column; }
.sky-islands { flex: 1; display: flex; flex-direction: column; gap: 10px; padding: 12px 14px;
               min-height: 0; transition: gap .5s ease; }
.isl { position: relative; overflow: hidden; border: 1px solid var(--card-border);
       background: var(--surface-1); box-shadow: var(--shadow-sm); border-radius: 29px;
       flex: 0 1 58px; min-height: 58px;
       transition: flex .55s cubic-bezier(.3,.9,.35,1), border-radius .55s cubic-bezier(.3,.9,.35,1),
                   background .6s ease, opacity .45s ease; }
.isl.isl-big { flex: 1 1 100%; border-radius: 34px; box-shadow: var(--shadow-md); }
/* `.sky-flow` — the sky variant for a page that carries content ABOVE it (Fuel's Mai, whose
   KeretHero is ~255px tall). Today's viewport-fill model (ADR 0022, "L0 nem görgethető")
   assumes the sky IS the page: `.sky-islands { flex: 1; min-height: 0 }` hands the islands
   whatever is left and `.isl.isl-big { flex: 1 1 100% }` lets the big one shrink to
   `min-height`, so on any phone shorter than ~950px the island fell below its own content
   height and `.isl { overflow: hidden }` CLIPPED the CTA row — while the flex fill kept
   `scrollHeight === clientHeight`, so the page could not scroll to it either (mezo-gllr;
   measured: 66px clipped at 852px, 118px at 800px, 0 at the goldens' 956px).
   The flow variant keeps the fill-when-there-is-room look (`flex-grow: 1`) but sets
   `flex-shrink: 0` with a content-sized basis everywhere, so an island can never be
   squeezed below its content; the sky then genuinely overflows `.screen-content`, which
   is the app's scroller. Trade-off: the capsule↔big morph's height step no longer
   interpolates (basis `auto` is not animatable) — the cross-fade and radius morph still do. */
.sky-islands.sky-flow { flex: 1 0 auto; }
.sky-flow .isl { flex: 0 0 auto; }
.sky-flow .isl.isl-big { flex: 1 0 auto; }
.isl-blob { position: absolute; width: 300px; height: 300px; top: -100px; left: 50%;
            margin-left: -150px; filter: blur(2px); opacity: 0; transition: opacity .6s ease;
            pointer-events: none; z-index: 0; }
.isl.isl-big .isl-blob { opacity: .9; }
:where(.isl.isl-big) .isl-blob { animation: isl-morph 9s ease-in-out infinite alternate; }
.isl[data-tone="reggel"] .isl-blob { background: radial-gradient(ellipse at 50% 45%,
    color-mix(in srgb, var(--accent-base) 34%, transparent),
    color-mix(in srgb, var(--primary-soft) 25%, transparent) 55%, transparent 75%); }
.isl[data-tone="nap"] .isl-blob { background: radial-gradient(ellipse at 50% 45%,
    color-mix(in srgb, var(--primary-base) 20%, transparent),
    color-mix(in srgb, var(--accent-base) 16%, transparent) 55%, transparent 75%); }
.isl[data-tone="este"] .isl-blob { background: radial-gradient(ellipse at 50% 45%,
    color-mix(in srgb, var(--dv-lav) 30%, transparent), transparent 75%); }
.isl[data-tone="fuel"] .isl-blob { background: radial-gradient(ellipse at 50% 45%,
    color-mix(in srgb, var(--sage) 32%, transparent),
    color-mix(in srgb, var(--amber) 14%, transparent) 55%, transparent 75%); }
.isl-cap { position: absolute; inset: 0; z-index: 2; display: flex; align-items: center; gap: 10px;
           padding: 0 16px; background: none; border: none; font-family: inherit; text-align: left;
           cursor: pointer; opacity: 1; transition: opacity .22s ease .18s; }
.isl.isl-big .isl-cap { opacity: 0; pointer-events: none; transition: opacity .15s ease; }
.isl-cap-t { display: block; font-size: 13px; font-weight: 700; color: var(--ink); }
.isl-cap-m { display: block; font-size: 11px; color: var(--faint); margin-top: 1px; }
.isl-cap-n { margin-left: auto; font-size: 11px; font-weight: 700; color: var(--sub);
             background: var(--surface-recess); padding: 4px 10px; border-radius: var(--r-full);
             white-space: nowrap; }
.isl-nowtag { font-size: 8.5px; font-weight: 800; letter-spacing: .16em; color: var(--accent-deep);
              background: var(--accent-bg); border: 1px solid var(--accent-soft); padding: 2px 7px;
              border-radius: var(--r-full); }
.isl.now-clock:not(.isl-big) { border-color: var(--accent-base);
              box-shadow: 0 0 0 4px color-mix(in srgb, var(--accent-base) 15%, transparent); }
:where(.isl:not(.isl-big)) { animation: isl-floaty 5.4s ease-in-out infinite; }
:where(.isl[data-tone="reggel"]:not(.isl-big)) { animation-delay: .8s; }
:where(.isl[data-tone="este"]:not(.isl-big)) { animation-delay: 1.6s; }
.isl-bigview { position: relative; z-index: 1; display: flex; flex-direction: column; height: 100%;
               padding: 22px 18px 16px; text-align: center; min-height: 0; opacity: 0;
               pointer-events: none; transition: opacity .32s ease .14s; }
.isl.isl-big .isl-bigview { opacity: 1; pointer-events: auto; }
/* night: the shell itself darkens — theme-invariant literal dark, the .wdb-night heritage */
.isl.isl-night { background: linear-gradient(165deg, #28223c, #1d1930);
                 border-color: rgba(255,255,255,.09); }
@keyframes isl-morph {
  0%   { border-radius: 58% 42% 55% 45% / 50% 58% 42% 50%; transform: translate(-8px,-6px); }
  50%  { border-radius: 45% 55% 48% 52% / 58% 44% 56% 42%; }
  100% { border-radius: 52% 48% 60% 40% / 44% 54% 46% 56%; transform: translate(6px,4px) scale(1.05); }
}
@keyframes isl-floaty { 0%, 100% { transform: translateY(0); } 50% { transform: translateY(-4px); } }
/* big-view content: DS Hero numeral + fact cells (StatStrip idiom + delta line) + act row */
.isl-hero-v { font-size: 52px; font-weight: 200; letter-spacing: -.04em; line-height: 1;
              color: var(--ink); font-variant-numeric: tabular-nums; margin-top: 26px; }
.isl-hero-v.is-word { font-size: 36px; margin-top: 34px; }
.isl-hero-u { font-size: 19px; font-weight: 300; color: var(--faint); margin-left: 5px; letter-spacing: 0; }
.isl-hero-sub { font-size: 12px; color: var(--sub); font-weight: 500; margin-top: 8px; }
.isl-facts { display: grid; gap: 1px; background: var(--line); border-radius: var(--r-lg);
             overflow: hidden; margin-top: 18px; }
.isl-fact { background: var(--surface-1); padding: 11px 8px 10px; text-align: center; }
.isl-fact-v { font-size: 19px; font-weight: 700; letter-spacing: -.02em; color: var(--ink); }
.isl-fact-u { font-size: 10px; font-weight: 500; color: var(--faint); margin-left: 2px; }
.isl-fact-l { font-size: 8.5px; font-weight: 700; letter-spacing: .18em; text-transform: uppercase;
              color: var(--faint); margin-top: 2px; }
.isl-fact-d { font-size: 10px; font-weight: 600; margin-top: 4px; }
.isl-fact-d.is-good { color: var(--success-hover); }
.isl-fact-d.is-warn { color: var(--warning-hover); }
.isl-fact-d.is-muted { color: var(--faint); }
.isl-warnchip { display: inline-flex; align-items: center; gap: 5px; background: var(--warning-bg);
                color: var(--warning-deep); border: 1px solid var(--warning-soft);
                border-radius: var(--r-full); font-size: 11px; font-weight: 600; padding: 5px 12px;
                margin: 14px auto 0; }
.isl-act { margin-top: auto; padding-top: 14px; display: flex; align-items: center;
           justify-content: center; gap: 10px; }
.isl-cta { display: inline-flex; align-items: center; gap: 6px; padding: 11px 20px;
           border-radius: var(--r-full); background: var(--gradient-cta); color: #fff;
           font-size: 13px; font-weight: 700; box-shadow: var(--shadow-cta); border: none;
           font-family: inherit; cursor: pointer; }
.isl-cta.is-lav { background: linear-gradient(135deg, #8d7fc0, #6d5f9c);
                  box-shadow: 0 8px 20px rgba(109,95,156,.35); }
.isl-cta.cta-sage { background: var(--gradient-sage); box-shadow: var(--shadow-sage); }
.isl-more { display: inline-flex; padding: 9px 14px; border-radius: var(--r-full);
            background: transparent; color: var(--sub); font-size: 12px; font-weight: 600;
            border: 1px solid var(--line); cursor: pointer; font-family: inherit; }
/* Mai standing log row (mezo-66te) — the always-available meal/AI log entry under the sky.
   Quiet ghost pair; exists in every day state because the big island's CTAs vanish on an
   all-done day and the + FAB's Étkezés tile only navigates here. */
.mai-logrow { display: flex; justify-content: center; gap: 10px; padding: 2px 0 4px; }
.isl-openhead { font-size: 10.5px; font-weight: 700; letter-spacing: .2em; text-transform: uppercase;
                color: var(--sub); text-align: left; flex: none; }
.isl-anchor-rows { margin-top: 18px; text-align: left; }
.isl-anchor-rows .itemrow { margin-bottom: 6px; }
/* night: light-on-dark text pairs (theme-invariant dark surface) */
.isl-night .isl-hero-v { color: #F5EFE6; }
.isl-night .isl-hero-u, .isl-night .isl-hero-sub { color: #9c92b8; }
.isl-night .isl-openhead { color: #B9ACD9; }
/* L1 — the unfolded list inside a big island. Scrolls internally; the sky itself never does. */
.isl-l1 { overflow-y: auto; flex: 1 1 auto; text-align: left; scrollbar-width: none; margin-top: 6px; }
.isl-l1::-webkit-scrollbar { display: none; }
.isl-grouph { display: flex; align-items: baseline; justify-content: space-between; font-size: 9px;
              font-weight: 800; letter-spacing: .18em; text-transform: uppercase; color: var(--faint);
              margin: 14px 2px 6px; }
.isl-grouph-go { font-size: 10px; letter-spacing: 0; text-transform: none; font-weight: 700;
                 color: var(--sub); text-decoration: none; }
.isl-l1 .itemrow { margin-bottom: 6px; }
.isl-dayxp { text-align: center; font-size: 12px; font-weight: 700; color: var(--success-hover);
             padding: 8px 0; }
.isl-l1-close { display: block; width: 100%; text-align: center; font-size: 12px; font-weight: 700;
                color: var(--sub); background: none; border: none; font-family: inherit;
                cursor: pointer; padding: 10px 0 2px; }
/* row entrance stagger — 70ms ladder, open-ended tail so long lists stay bounded */
:where(.isl-l1) .itemrow { animation: isl-rowin .35s ease both; }
:where(.isl-l1) .itemrow:where(:nth-child(2)) { animation-delay: 70ms; }
:where(.isl-l1) .itemrow:where(:nth-child(3)) { animation-delay: 140ms; }
:where(.isl-l1) .itemrow:where(:nth-child(4)) { animation-delay: 210ms; }
:where(.isl-l1) .itemrow:where(:nth-child(5)) { animation-delay: 280ms; }
:where(.isl-l1) .itemrow:where(:nth-child(6)) { animation-delay: 350ms; }
:where(.isl-l1) .itemrow:where(:nth-child(7)) { animation-delay: 420ms; }
:where(.isl-l1) .itemrow:where(:nth-child(n+8)) { animation-delay: 490ms; }
@keyframes isl-rowin { from { opacity: 0; transform: translateY(6px); } to { opacity: 1; transform: none; } }
@media (prefers-reduced-motion: reduce) {
  :where(.isl.isl-big) .isl-blob { animation: none; }
  :where(.isl:not(.isl-big)) { animation: none; }
  :where(.isl-l1) .itemrow { animation: none; }
  .isl, .isl-cap, .isl-bigview, .sky-islands { transition: none; }
}

/* ═════════ Fuel WindowIsland — .isl-mealchip family (mezo-jgh9, window-river Task 4) ═════════
   The window-island's plan-meal chip: name + kcal/P meta + an illik-score badge when the
   meal-score/fit data exists. Terv nélküli ablakon (no real meal idea) the ghost variant
   takes its place — dashed, muted, no fabricated numbers. */
.isl-mealchip { display: flex; align-items: center; gap: 8px; background: var(--surface-recess);
                border-radius: var(--r-lg); padding: 9px 11px; margin-top: 12px; text-align: left; }
.isl-mealchip-em { font-size: 16px; }
.isl-mealchip-tx { min-width: 0; }
.isl-mealchip-t { font-size: 12.5px; font-weight: 700; color: var(--ink); }
.isl-mealchip-m { font-size: 10.5px; color: var(--faint); margin-top: 1px; }
.isl-mealchip-score { margin-left: auto; font-size: 10px; font-weight: 800; color: var(--success-hover);
                       background: var(--success-bg); border-radius: var(--r-full); padding: 3px 8px;
                       white-space: nowrap; }
.isl-mealchip-ghost { display: flex; align-items: center; justify-content: center; gap: 6px;
                       margin-top: 12px; padding: 11px; border: 1.5px dashed var(--line);
                       border-radius: var(--r-lg); color: var(--faint); font-size: 12px; font-weight: 600; }

/* A `.khero-*` család KIVEZETVE (Fuel Titanium S5, mezo-qt5q): a `KeretHero.tsx` utolsó
   hordozója, a `/fuel/log` lap megszűnt — a Mai energia-műszere a `.fmx-hero`
   (`FuelEnergyHero` + `FuelMacroRings`) saját családja. */

/* ═════════ Fuel done-window capsule — .kdone family (mezo-c9t5, keret-hero Task 3) ═════════
   The day's done meal windows, merged into ONE expandable capsule sitting first in the sky
   (`DoneWindowsCapsule.tsx`) — replaces the retired per-window done capsules + the belt's own
   done-summary line. Rides the shared `.isl` shell for the sky's visual chrome, but overrides its
   fixed-height/overflow-hidden flex sizing (content-driven height instead — the shell's `isl-big`
   morph mechanism doesn't apply here, this capsule is never "big"/selected). No new motion beyond
   the list's own height/opacity reveal. */
.isl.kdone { flex: 0 0 auto; overflow: visible; min-height: 0; }
.kdone-cap { display: flex; align-items: center; gap: 10px; width: 100%; padding: 14px 16px;
             background: none; border: none; cursor: pointer; font-family: inherit; text-align: left;
             color: var(--success-hover); font-size: 15px; }
.kdone-cap-tx { flex: 1; font-size: 12px; font-weight: 700; color: var(--text-primary); }
.kdone-arrow { font-size: 13px; color: var(--success-hover); flex: none; }
.kdone-list { border-top: 1px solid var(--divider); }
.kdone-row { display: flex; align-items: center; gap: 9px; width: 100%; padding: 9px 16px;
             background: none; border: none; border-top: 1px solid var(--divider); cursor: pointer;
             font-family: inherit; text-align: left; }
.kdone-row:first-child { border-top: none; }
.kdone-row-inert { cursor: default; }
.kdone-row-tx { flex: 1; display: flex; flex-direction: column; gap: 1px; min-width: 0; }
.kdone-row-t { font-size: 12px; font-weight: 700; color: var(--text-primary); }
.kdone-row-m { font-size: 10px; color: var(--text-muted); }
.kdone-roletag { font-size: 7.5px; font-weight: 800; letter-spacing: .1em; padding: 2px 6px;
                 border-radius: var(--r-full); margin-left: 6px; vertical-align: 1px;
                 color: var(--text-muted); background: var(--surface-recess); border: 1px solid var(--divider); }
.kdone-roletag-pre, .kdone-roletag-post { color: var(--accent-deep); background: var(--accent-bg);
                                           border-color: var(--accent-soft); }
.kdone-chip { margin-left: auto; flex: none; display: inline-flex; align-items: center; gap: 4px;
              font-size: 11px; font-weight: 800; color: var(--success-hover); background: var(--success-bg);
              border: 1px solid var(--success-soft); border-radius: var(--r-full); padding: 3px 9px;
              white-space: nowrap; }
.kdone-chip-mid { color: var(--accent-deep); background: var(--accent-bg); border-color: var(--accent-soft); }

/* ===== NightPage calm tools (mezo-d71m, spec D6) — literal dark, theme-independent ===== */
.nb, .ns, .nw { display: flex; flex-direction: column; flex: 1; min-height: 0; }
.nb-stage { position: relative; height: 250px; display: flex; align-items: center; justify-content: center; }
.nb-orb { width: 180px; height: 180px; border-radius: 50%;
          background: radial-gradient(circle at 50% 42%, rgba(185,172,217,.34), rgba(185,172,217,.06) 70%);
          box-shadow: 0 0 52px rgba(185,172,217,.18);
          animation: nb-breath 18s ease-in-out infinite; }
@keyframes nb-breath {
  0% { transform: scale(.52); } 27.8% { transform: scale(1); }
  61.1% { transform: scale(1); } 100% { transform: scale(.52); }
}
.nb-labels { position: absolute; inset: 0; display: flex; align-items: center; justify-content: center; }
.nb-labels span { position: absolute; font: 600 21px/1 var(--ff-display); color: #F5EFE6; opacity: 0; }
.nb-in { animation: nb-lb-in 18s linear infinite; }
.nb-hold { animation: nb-lb-hold 18s linear infinite; }
.nb-out { animation: nb-lb-out 18s linear infinite; }
@keyframes nb-lb-in { 0% { opacity: .9; } 25% { opacity: .9; } 29% { opacity: 0; } 100% { opacity: 0; } }
@keyframes nb-lb-hold { 0% { opacity: 0; } 27% { opacity: 0; } 31% { opacity: .9; } 58% { opacity: .9; } 63% { opacity: 0; } 100% { opacity: 0; } }
@keyframes nb-lb-out { 0% { opacity: 0; } 60% { opacity: 0; } 64% { opacity: .9; } 97% { opacity: .9; } 100% { opacity: 0; } }
@media (prefers-reduced-motion: reduce) {
  .nb-orb { animation: none; }
  /* labels keep cycling — the pacing survives without motion */
}
.nb-hint, .ns-hint, .nw-note { font: 500 12px/1.7 var(--ff-body); color: #6E6156; text-align: center; margin-top: 12px; }
.ns-card, .nw-stage { display: block; width: 100%; text-align: center; margin-top: 24px;
                      background: #1A1613; border: 1px solid rgba(245,239,230,.05); border-radius: 20px; padding: 26px 20px; }
.ns-part { font: 600 20px/1.3 var(--ff-display); color: #F5EFE6; margin-bottom: 12px; }
.ns-tx { font: 500 13.5px/1.75 var(--ff-body); color: var(--text-secondary); }
.ns-dots { display: flex; gap: 7px; justify-content: center; margin-top: 22px; }
.ns-dot { width: 5px; height: 5px; border-radius: 50%; background: rgba(245,239,230,.14); }
.ns-dot.on { background: #B9ACD9; }
.nw-setup, .nw-remind { display: block; }
.nw-t { display: block; font: 600 17px/1.35 var(--ff-display); color: #F5EFE6; margin-bottom: 10px; }
.nw-tx { display: block; font: 500 13px/1.7 var(--ff-body); color: var(--text-secondary); }
.nw-rtx { display: block; font: 500 13px/1.7 var(--ff-body); color: var(--text-secondary); font-style: italic; }

/* ===== NightPage — full-screen, forced extra-dark, no clock (mezo-d71m, spec D4/D5) ===== */
.night { display: flex; flex-direction: column; min-height: 100%; padding: 26px 20px 24px;
         background: #0E0B09;
         /* Full-bleed dark ground: light --screen-gutter strips beside the extra-dark
            surface would defeat the <30 lux goal — pull out of the gutter, the 20px
            inner padding keeps the content off the edge. */
         margin-inline: calc(-1 * var(--screen-gutter)); }
.night-back { font: 600 11px/1 var(--ff-body); color: #6E6156; text-decoration: none; margin-bottom: 20px; }
.night-body { display: flex; flex-direction: column; flex: 1; min-height: 0; }
.night-eye { font: 700 10px/1 var(--ff-body); letter-spacing: .14em; color: #6E6156;
             text-transform: uppercase; text-align: center; margin-bottom: 10px; }
.night-moon { text-align: center; font-size: 34px; margin: 26px 0 18px;
              filter: drop-shadow(0 0 14px rgba(185,172,217,.35)); }
.night-glow { text-align: center; font-size: 30px; margin: 24px 0 16px;
              filter: drop-shadow(0 0 12px rgba(255,190,96,.28)); }
.night-title { font: 600 26px/1.25 var(--ff-display); color: #F5EFE6; text-align: center; margin-bottom: 14px; }
.night-title-sm { font-size: 23px; }
.night-tx { font: 500 13.5px/1.75 var(--ff-body); color: var(--text-secondary); text-align: center; margin: 0 8px 26px; }
.night-cta { display: block; width: 100%; padding: 18px; border-radius: 999px; text-align: center;
             background: rgba(185,172,217,.14); border: 1px solid rgba(185,172,217,.32);
             font: 700 16px/1 var(--ff-body); color: #B9ACD9; margin-top: auto; }
.night-quiet { display: block; width: 100%; text-align: center; font: 600 12px/1 var(--ff-body);
               color: #6E6156; margin-top: 16px; background: none; border: none; text-decoration: none; }
.night-orb { width: 118px; height: 118px; border-radius: 50%; margin: 22px auto 20px;
             background: radial-gradient(circle at 50% 42%, rgba(185,172,217,.30), rgba(185,172,217,.05) 68%);
             box-shadow: 0 0 42px rgba(185,172,217,.16); animation: nb-breath 18s ease-in-out infinite; }
@media (prefers-reduced-motion: reduce) { .night-orb { animation: none; } }
.night-tools { display: flex; flex-direction: column; gap: 12px; margin-top: 6px; }
.night-tool { display: flex; align-items: center; gap: 14px; padding: 16px; text-align: left;
              background: #1A1613; border-radius: 18px; border: 1px solid rgba(245,239,230,.05); }
.night-tool-tx { flex: 1; display: flex; flex-direction: column; gap: 2px; }
.night-tool-tx b { font: 600 14px/1.2 var(--ff-body); color: #F5EFE6; }
.night-tool-tx i { font: 500 10.5px/1.5 var(--ff-body); color: #6E6156; font-style: normal; }
.night-steps { list-style: none; display: flex; flex-direction: column; gap: 14px; margin: 4px 6px 24px; padding: 0; }
.night-steps li { position: relative; padding-left: 18px; font: 500 13px/1.65 var(--ff-body); color: var(--text-secondary); }
.night-steps li::before { content: ''; position: absolute; left: 0; top: 7px; width: 6px; height: 6px;
                          border-radius: 50%; background: rgba(255,190,96,.75); }
.night-steps b { color: #F5EFE6; font-weight: 600; }

/* ===== Sleep education (slice C3, mezo-hd8k): daily stat card + deck sheet ===== */
.sstat { display: flex; flex-direction: column; gap: 6px; width: 100%; text-align: left;
         margin-top: 8px; padding: 16px; border-radius: 20px;
         background: linear-gradient(150deg, var(--wash-lav) 0%, var(--surface) 72%);
         box-shadow: 0 1px 3px rgba(43,33,24,.06); }
.sstat-eye { font: 700 10px/1 var(--ff-body); letter-spacing: .1em; color: var(--lav-deep); text-transform: uppercase; }
.sstat-title { font: 600 15.5px/1.3 var(--ff-display); color: var(--ink); }
.sstat-text { font: 500 12.5px/1.6 var(--ff-body); color: var(--sub); }
.sstat-src { font: 600 10px/1.4 var(--ff-body); color: var(--faint); }
.sstat-row { display: flex; flex-direction: column; gap: 5px; padding: 13px 14px;
             background: var(--surface); border: 1px solid var(--line); border-radius: 16px; }
.sstat-foot { font: 500 10.5px/1.6 var(--ff-body); color: var(--faint); margin-top: 12px; }
.sesc-sheet { display: flex; flex-direction: column; gap: 8px; padding: 14px;
              border-radius: 16px; background: var(--wash-amber); margin-bottom: 14px; }
.sesc-lead { font: 600 13.5px/1.5 var(--ff-body); color: var(--ink); }
.sesc-body { font: 500 12px/1.65 var(--ff-body); color: var(--sub); }
.sesc-body b { color: var(--ink); }
.sesc { display: flex; flex-direction: column; gap: 7px; margin-top: 8px; padding: 16px;
        border-radius: 20px; background: linear-gradient(150deg, var(--wash-amber) 0%, var(--surface) 75%);
        box-shadow: 0 1px 3px rgba(43,33,24,.06); }
.sesc-actions { display: flex; gap: 10px; align-items: center; margin-top: 4px; }
.sesc-cta { background: var(--amber-deep); color: var(--text-inverse); font: 700 12px/1 var(--ff-body);
            padding: 10px 16px; border-radius: 999px; }
.sesc-quiet { font: 600 11.5px/1 var(--ff-body); color: var(--faint); padding: 10px 8px; }

/* ===== Sleep-phase family (mezo-fk9a) — feature-scoped to the sleep surfaces ===== */
.phrail { display: flex; overflow: hidden; background: var(--surface-2); }
.phrail i { display: block; height: 100%; }

.phleg { display: grid; grid-template-columns: 1fr 1fr; gap: 7px 14px; margin-top: 12px; }
.phleg-it { display: flex; align-items: baseline; gap: 7px; font-size: 11.5px; font-weight: 700; color: var(--text-secondary); }
.phleg-dot { width: 8px; height: 8px; border-radius: 50%; flex: none; align-self: center; }
.phleg-v { margin-left: auto; font-variant-numeric: tabular-nums; font-weight: 800; color: var(--text-primary); }
.phleg-p { font-size: 10px; color: var(--faint); font-weight: 800; min-width: 30px; text-align: right; font-variant-numeric: tabular-nums; }

.phref-t { display: flex; align-items: baseline; gap: 6px; font-size: 11px; font-weight: 800; color: var(--text-secondary); margin-bottom: 5px; }
.phref-t b { font-family: var(--ff-display); font-size: 13.5px; color: var(--text-primary); }
.phref-t em { font-style: normal; margin-left: auto; font-size: 10px; font-weight: 800; color: var(--faint); }
.phref-bar { position: relative; height: 6px; border-radius: 3px; background: var(--surface-2); }
.phref-band { position: absolute; top: 0; bottom: 0; border-radius: 3px; background: color-mix(in srgb, var(--sage) 35%, transparent); }
.phref-pin { position: absolute; top: -3px; width: 3px; height: 12px; border-radius: 2px; transform: translateX(-1.5px); }

/* ===== Ritual — Napzárás full-screen flow (mezo-ilsj) =====
   Re-dressed onto the Üveg material in U3 (mezo-me75u.3): every .rz-* rule now lives in the
   `── uveg nap napzaras (` block at the end of this file. The night-sky --rz-sky-* tokens stay in
   the two :root blocks (warm-graphite values since U3). */

/* ===== Morning-training reschedule nudge (mezo-67rb): Train · Mai anchor-consumer card ===== */
.mtr { display: flex; flex-direction: column; gap: 7px; margin-top: 8px; padding: 16px;
       border-radius: 20px; background: linear-gradient(150deg, var(--wash-sage) 0%, var(--surface) 75%);
       box-shadow: 0 1px 3px rgba(43,33,24,.06); }
.mtr-eye { font: 700 10px/1 var(--ff-body); letter-spacing: .1em; color: var(--sage-deep); text-transform: uppercase; }
.mtr-lead { font: 600 13.5px/1.5 var(--ff-body); color: var(--ink); }
.mtr-body { font: 500 12.5px/1.6 var(--ff-body); color: var(--sub); }
.mtr-actions { display: flex; gap: 10px; align-items: center; margin-top: 4px; }
.mtr-cta { background: var(--sage-deep); color: var(--text-inverse); font: 700 12px/1 var(--ff-body);
           padding: 10px 16px; border-radius: 999px; }
.mtr-quiet { font: 600 11.5px/1 var(--ff-body); color: var(--faint); padding: 10px 8px; }

/* ── Energy-breakdown sheet (mezo-hobb) — the sheet moved to the `uveg fuel log` block
   (mezo-me75u.2, `.flp-e*`); only the `.dot-*` swatches (BiometricSheet) stay here. ── */
.dot-sage { background: var(--sage); }
.dot-amber { background: var(--amber); }
.dot-coral { background: var(--coral); }


/* Alap-TDEE breakdown — Variant B stacked list + emphasized total (mezo-hobb).
   Overrides the horizontal .tdee flex when both classes are present (kept for the .tdee test hook). */
.tdee-split { display: block; width: 100%; text-align: left; cursor: pointer; background: none; }
.tdee-split .row { display: flex; justify-content: space-between; align-items: center; padding: 5px 0; }
.tdee-split .lab { display: flex; align-items: center; gap: 8px; font-size: 12.5px; font-weight: 700; color: var(--sub); }
.tdee-split .dot { width: 8px; height: 8px; border-radius: 3px; flex-shrink: 0; }
.tdee-split .amt { font-family: var(--ff-display); font-size: 16px; font-weight: 800; color: var(--ink); font-variant-numeric: tabular-nums; }
.tdee-split .total { border-top: 1px dashed var(--line); margin-top: 6px; padding-top: 10px; }
.tdee-split .total .lab { color: var(--sage-deep); font-weight: 800; }
.tdee-split .total .amt { font-size: 22px; color: var(--sage-deep); }
.tdee-split .total .amt small { font-size: 12px; color: var(--sub); font-weight: 700; }
.tdee-split .infochev { color: var(--lav-deep); font-size: 12px; font-weight: 800; }

/* Tappable Fuel "Mai cél" chips — small ⓘ affordance (mezo-hobb) */
.chip-tap { position: relative; padding-right: 24px; cursor: pointer; }
.chip-tap::after { content: "i"; position: absolute; right: 7px; top: 50%; transform: translateY(-50%);
  width: 14px; height: 14px; border-radius: 50%; font-size: 9px; font-weight: 800; font-style: italic;
  display: flex; align-items: center; justify-content: center; background: var(--surface-glass); }

/* ===== Napív Fuel Mai — guided recomposition (mezo-rrtj), RETIRED (mezo-jgh9, window-river Task 6) =====
   .medcycle-micro (gyógyszer-ciklus micro-strip), .nowcard* (NowWindowCard hero), .missedstrip (MissedStrip) and
   .daybudget/.dayseg/.brk/.ebchip/.mac* (DayBudgetCard) were all deleted whole with their sole
   consumer — the ablak-folyam recomposition replaced this page outright with the .sky-islands/.isl*
   family (window-island hero + KeretBelt's kibontott view owns the energy-breakdown + macro bars
   now). The napszak zone cards below this comment (.zcard/.zrow/.zh/.zn/.zk/.zt/.a/.b) SURVIVE —
   other legacy readers still ride that shared family — only their DayZoneCard/ZoneSlotRow-only
   nested rules (donez/openz, .caps/.burn, .zf/.zv/.zacts/.log/.ai, .missedrow/.act/.anchor, .mm)
   were pruned below, along with .misstag/.coachline/.cskel (ZoneSlotRow-only) further up this file. */

/* Zone cards */
.zcard { margin: 0 24px 9px; background: var(--surface); border-radius: 20px; box-shadow: var(--np-shadow-row); overflow: hidden; }
.zcard .zh { display: flex; align-items: center; gap: 9px; padding: 11px 14px; background: var(--warm); }
.zcard .zh .zn { font-size: 10.5px; font-weight: 800; letter-spacing: .1em; text-transform: uppercase; color: var(--sub); }
.zcard .zh .zk { margin-left: auto; font-size: 11px; font-weight: 800; font-variant-numeric: tabular-nums; color: var(--ink); }
.zrow { display: flex; align-items: center; gap: 10px; padding: 11px 14px; }
/* Scoped to zone rows only — `:first-of-type` counted `div` siblings (never matched, since `.zh` is
   always the first div inside `.zcard`), and drew a stray hairline on the two standalone `.zrow`
   cards (kitchen-close, protocol footer) that sit among unrelated page-level siblings. */
.zcard .zrow { border-top: 1px solid var(--line); }
.zcard .zh + .zrow { border-top: 0; }
.zrow .zt { flex: 1; min-width: 0; }
.zrow .zt .a { font-size: 12.5px; font-weight: 800; color: var(--ink); }
.zrow .zt .b { display: flex; align-items: center; gap: 7px; font-size: 10px; color: var(--faint); font-weight: 700; margin-top: 2px; flex-wrap: wrap; }
.zrow .zt .b b { color: var(--ink); font-weight: 800; font-size: 10.5px; }
/* RETIRED (mezo-jgh9, window-river Task 6) — DayZoneCard/ZoneSlotRow were the only consumers of:
   .zcard .zh .zk .burn / .caps* (stack-pip dots) / .donez/.openz (zone-state tints); .zrow .zf
   (avatar) / .zv (kcal readout) / .zacts+.log/.ai (log/AI buttons) / .missedrow / .act(+.sport)
   / .anchor / .mm (macro dots) — plus the standalone .misstag (further up this file) and
   .coachline/.cskel below. The base .zcard/.zh/.zn/.zk/.zrow/.zt/.a/.b rules above survive. */

/* AI score chip */
.aiscore { display: inline-flex; align-items: center; gap: 5px; border: 0; cursor: pointer; font: inherit;
  border-radius: 999px; padding: 4px 9px 4px 5px; font-size: 10px; font-weight: 800; flex-shrink: 0; }
.aiscore .rg { width: 16px; height: 16px; flex-shrink: 0; }
.aiscore.s-hi { background: var(--wash-sage); color: var(--sage-deep); }
.aiscore.s-md { background: var(--wash-amber); color: var(--amber-deep); }
.aiscore.s-lo { background: var(--wash-gym); color: var(--tag-gym); }

@media (prefers-reduced-motion: no-preference) {
  .aiscore { animation: np-chip-pop .5s var(--np-ease-spring); }
}
@keyframes np-chip-pop {
  0% { transform: scale(.75); opacity: .4; }
  70% { transform: scale(1.12); }
  100% { transform: scale(1); opacity: 1; }
}

/* ===== DS P2 primitives (mezo-setx.3) — Spinner · CoachBubble · AdherenceBar · Stepper · NumberInput ===== */

/* Spinner — fallback loader (Skeleton is canonical for >2s waits) */
@keyframes ds-spin { to { transform: rotate(360deg); } }
.spinner {
  border-style: solid;
  border-color: var(--divider);
  border-radius: 50%;
  animation: ds-spin 800ms linear infinite;
  flex-shrink: 0;
  display: inline-block;
}
.spinner.sm { width: 16px; height: 16px; border-width: 2px; }
.spinner.md { width: 20px; height: 20px; border-width: 2.5px; }
.spinner.lg { width: 24px; height: 24px; border-width: 3px; }
.spinner.tone-accent  { border-top-color: var(--accent-base); }
.spinner.tone-primary { border-top-color: var(--primary-base); }
.spinner.tone-muted   { border-top-color: var(--text-muted); }
.spinner.tone-onsolid { border-color: rgba(255,255,255,0.30); border-top-color: #fff; }
@media (prefers-reduced-motion: reduce) { .spinner { animation-duration: 2s; } }

/* CoachBubble — the Coach voice: Geist 200 ultralight, never italic */
.coach-bubble {
  display: flex; gap: 14px; align-items: flex-start;
  padding: 16px 18px;
  background: color-mix(in srgb, var(--primary-base) 7%, transparent);
  border-left: 2px solid var(--primary-base);
  border-radius: 0 var(--r-lg) var(--r-lg) 0;
}
.coach-bubble .cb-avatar {
  width: 32px; height: 32px; border-radius: 50%; flex-shrink: 0;
  background: radial-gradient(circle at 30% 30%, #FFB59E, var(--primary-base));
  box-shadow: 0 0 12px color-mix(in srgb, var(--primary-base) 35%, transparent);
}
.coach-bubble .cb-head { display: flex; align-items: baseline; gap: 8px; margin-bottom: 6px; }
.coach-bubble .cb-eyebrow { font: 700 11px/1 var(--ff-body); letter-spacing: .06em; text-transform: uppercase; color: var(--primary-deep); }
.coach-bubble .cb-time { font: 400 10px/1 var(--ff-body); color: var(--text-muted); }
.coach-bubble .cb-body {
  font-family: var(--ff-body);
  font-weight: 200; font-size: 22px;
  letter-spacing: -0.02em; line-height: 1.32;
  color: var(--primary-deep);
}

/* AdherenceBar — stacked multi-segment bar + legend */
.adher-track {
  display: flex; height: 12px;
  border-radius: var(--r-full); overflow: hidden;
  background: var(--surface-recess);
}
.adher-legend { display: flex; flex-wrap: wrap; gap: 10px 14px; margin-top: 10px; }
.adher-key { display: inline-flex; align-items: center; gap: 5px; font: 400 11px/1.3 var(--ff-body); color: var(--text-secondary); }
.adher-key .swatch { width: 8px; height: 8px; border-radius: 2px; flex-shrink: 0; }
.adher-key .name { font-weight: 600; color: var(--text-primary); }

/* Stepper — wizard progress (dot mode) */
.stepper-head { display: flex; justify-content: space-between; align-items: baseline; margin-bottom: 8px; }
.stepper-title { font: 700 13px/1.3 var(--ff-body); color: var(--text-primary); }
.stepper-count { font: 600 11px/1 var(--ff-body); font-variant-numeric: tabular-nums; color: var(--accent-deep); }
.stepper-dots { display: flex; gap: 6px; align-items: center; }
.stepper-dot { width: 10px; height: 10px; border-radius: 50%; background: var(--surface-recess); border: 1px solid var(--divider); }
.stepper-dot.done { background: var(--success-base); border-color: var(--success-base); }
.stepper-dot.active { background: var(--accent-base); border-color: var(--accent-base); box-shadow: 0 0 0 3px color-mix(in srgb, var(--accent-base) 30%, transparent); }
.stepper-label { font: 400 12px/1.3 var(--ff-body); color: var(--text-secondary); margin-left: 8px; }

/* NumberInput — Rule 4 field chrome (48dp, 16px text, coral focus) */
.ninput {
  width: 100%; min-height: 48px;
  padding: 12px 16px;
  background: var(--surface-1);
  border: 1px solid var(--divider);
  border-radius: var(--r-lg);
  font-family: var(--ff-body);
  font-size: 16px;          /* iOS auto-zoom floor */
  color: var(--text-primary);
  outline: none;
  transition: border-color var(--duration-fast) var(--ease-out), box-shadow var(--duration-fast) var(--ease-out);
}
.ninput:focus-visible { border-color: var(--primary-base); box-shadow: var(--shadow-focus); }
.ninput:disabled { background: var(--surface-recess); color: var(--text-disabled); }

/* ── Exercise demo stills (mezo-8xdl.3) ──────────────────────────────────────
   The vendored free-exercise-db photos are shot in a red-walled commercial gym
   — tonally foreign to the Napív surfaces. The desaturation + the muscle rail
   running along the leading edge are what bind them to the card language; the
   rail colour is set inline per exercise. */
.exdemo {
  position: relative;
  width: 100%;
  aspect-ratio: 3 / 2;
  margin: 0;
  overflow: hidden;
  border-radius: var(--r-2xl);
  border: 1px solid var(--card-border);
  border-inline-start-width: 5px;
  border-inline-start-style: solid;   /* colour comes in inline (muscleColor.rail) */
  background: var(--surface-2);
}
.exdemo-frame {
  position: absolute;
  inset: 0;
  width: 100%;
  height: 100%;
  object-fit: cover;
  filter: saturate(0.88);
  transition: opacity var(--duration-slow, 320ms) var(--ease-out);
}
:root[data-theme='dark'] .exdemo-frame { filter: saturate(0.88) brightness(0.9); }
@media (prefers-color-scheme: dark) {
  :root:not([data-theme='light']) .exdemo-frame { filter: saturate(0.88) brightness(0.9); }
}
@media (prefers-reduced-motion: reduce) {
  .exdemo-frame { transition: none; }
}
.exdemo-toggle {
  position: absolute;
  right: 8px; bottom: 8px;
  width: 32px; height: 32px;
  border-radius: 50%;
  border: 1px solid var(--card-border);
  background: var(--surface-glass, var(--surface-1));
  backdrop-filter: blur(8px);
  color: var(--text-secondary);
  font-size: 14px;
  line-height: 1;
}
.exdemo-thumb {
  flex: none;
  width: 44px; height: 44px;
  border-radius: var(--r-md, 10px);
  object-fit: cover;
  filter: saturate(0.88);
  /* the no-image fallback tile paints its own wash + initial */
  display: grid; place-items: center;
  font: 600 15px/1 var(--ff-display);
}

/* ── .excat-tag — the DS Tag stamp (mezo-setx.6.7 → mezo-lf3cv P2) ───────────
   The Gyakorlatok catalogue that owned this block was replaced by the Titanium
   `.gy-*` section (P2 Task 4), so every `.excat*` rule except this one lost its
   last consumer and went with it. The stamp itself survives: the Futás session
   card and the running page still stamp their descriptors with it. */
.excat-tag {
  display: inline-flex; align-items: center; gap: 4px;
  padding: 2px 7px;
  border-radius: var(--r-sm);
  font: 800 9.5px/1.5 var(--ff-body);
  letter-spacing: .10em;
  text-transform: uppercase;
  white-space: nowrap;
}
@media (prefers-reduced-motion: reduce) {
  .pgact { transition: none; }
  .pgact:active { transform: none; }
}

/* Search field — the DS SearchInput: icon + borderless 16px input in field chrome. */
.searchfield {
  display: flex; align-items: center; gap: var(--sp-2, 8px);
  min-height: 48px;
  padding: 0 14px;
  background: var(--surface-1);
  border: 1px solid var(--divider);
  border-radius: var(--r-lg);
  transition: border-color var(--duration-fast) var(--ease-out), box-shadow var(--duration-fast) var(--ease-out);
}
.searchfield:focus-within { border-color: var(--primary-base); box-shadow: var(--shadow-focus); }
.searchfield input {
  flex: 1; min-width: 0;
  background: transparent; border: 0; outline: none;
  font-family: inherit; font-size: 16px;   /* body floor + the iOS auto-zoom floor */
  color: var(--text-primary);
}
/* Filter chips: the DS chip, given an iOS-standard 44px tap height (the bare DS
   chip spec is ~28px, below every target rule; padding is the sanctioned fix). */
.chip.tapchip { min-height: 44px; }

/* Page-header action — low-frequency top-right action (anti-pattern 19). */
.pgact {
  display: inline-flex; align-items: center; gap: 6px;
  min-height: 44px;
  padding: 0 16px;
  border: 0; font: inherit; cursor: pointer;
  border-radius: var(--r-full);
  font-size: 14px; font-weight: 600;
  background: var(--primary-bg);
  color: var(--primary-deep);
  white-space: nowrap;
  transition: transform var(--duration-fast) var(--ease-out);
}
.pgact:active { transform: scale(0.97); }

/* Mai's mezociklus entry — the DS canonical nav row (mezo-setx.6.2): 56px min,
   body-size label, trailing chevron. Replaces a 13px text row with a bare "→". */
.mesorow {
  display: flex; align-items: center; gap: var(--sp-3);
  width: 100%; min-height: 56px;
  padding: 12px 16px;
  text-align: left;
  font: inherit;
  transition: background var(--duration-fast) var(--ease-out);
}
.mesorow:active { background: var(--surface-recess); }
.mesorow-tx { flex: 1; min-width: 0; font-size: 16px; color: var(--text-primary); }

/* StatStrip sub-caption (mezo-setx.6.4) — the optional third line under a cell's
   label, for cells that need to say what the value is measured against
   ("kész / heti terv"). Used by GymStat; the domain-free <StatStrip> has no
   equivalent prop on purpose, so this is opt-in vocabulary, not a new default. */
.statstrip-s { font-size: 11px; font-weight: 500; color: var(--text-muted); margin-top: 2px; }

/* A page-header action ROW — for pages whose actions outgrow the header's
   top-right slot (GymPage has three labelled ones, mezo-setx.6.4). Scrolls
   horizontally rather than wrapping into a column beside the title. */
.pgactrow { display: flex; gap: var(--sp-2); overflow-x: auto; scrollbar-width: none; padding: 0 24px 12px; }
.pgactrow::-webkit-scrollbar { display: none; }
.pgactrow > * { flex: none; }
/* StatStrip in two columns — for cells whose values are phrases, not numerals. */
.statstrip-2 { grid-auto-flow: row; grid-template-columns: 1fr 1fr; }

/* Dashed "add your own" CTA — the full-width secondary entry that closes a list
   (Saját edzés on Mai and Heti). Caption role at 14 with a 48dp target; it was a
   10px uppercase strip at three call sites (mezo-setx.6.3). Mai's two inline
   copies should adopt this class when their own bead next touches them. */
.dashedcta {
  display: flex; align-items: center; justify-content: center; gap: 8px;
  width: 100%; min-height: 48px;
  padding: 12px 16px;
  background: transparent;
  border-style: dashed;
  border-color: var(--divider);
  color: var(--tag-gym);
  font-size: 14px; font-weight: 600;
}

/* ── Segmented view switcher (mezo-setx.6.5) ────────────────────────────────
   The full-width 2-4 way switcher a sub-page uses to swap what is BELOW it
   (Sport: Hét/Napló/Terhelés; Futás: E heti/Napló/Tervek). It was a row of
   10px uppercase buttons tinted in the page's domain accent — which ADR 0018
   D5 forbids on buttons: the domain colours are legal in the data-viz band
   only. The selected segment therefore speaks PRIMARY, like every other
   selected control in the DS, and the domain accent stays on the numbers. */
.segtabs { display: flex; gap: var(--sp-2); }
.segtab {
  flex: 1; min-width: 0;
  min-height: 44px;
  padding: 10px 12px;
  border-radius: var(--r-lg);
  border: 1px solid var(--divider);
  background: var(--surface-1);
  color: var(--text-secondary);
  font-family: inherit; font-size: 14px; font-weight: 600;
  cursor: pointer;
  transition: transform var(--duration-fast) var(--ease-out);
}
.segtab[aria-pressed='true'] {
  background: var(--primary-bg);
  border-color: var(--primary-base);
  color: var(--primary-deep);
  font-weight: 700;
}
.segtab:active { transform: scale(0.98); }
@media (prefers-reduced-motion: reduce) {
  .segtab { transition: none; }
  .segtab:active { transform: none; }
}
/* ===== WorkoutSummary redesign (mezo-w943) — hero+halo, region pills,
   mérleg strip, medal cards, challenge rows, set-chip map. Feature-scoped
   vocabulary (same precedent as .setdots/.excard); tokens only. ===== */
.wsum-top { display: flex; align-items: center; gap: 7px; padding: 16px 20px 0; }
.wsum-top button { display: flex; align-items: center; gap: 6px; background: none; border: none; font: inherit; cursor: pointer; color: var(--text-secondary); font-size: 11px; font-weight: 800; letter-spacing: .12em; text-transform: uppercase; }
.wsum-top .wsum-xi { width: 26px; height: 26px; border-radius: var(--r-full); background: var(--surface-recess); display: flex; align-items: center; justify-content: center; font-size: 12px; }
.wsum-hero { position: relative; text-align: center; padding: 18px 22px 0; }
.wsum-halo { position: absolute; width: 300px; height: 300px; top: -110px; left: 50%; margin-left: -150px; filter: blur(2px); z-index: 0; pointer-events: none; animation: wsum-morph 9s ease-in-out infinite alternate; }
.wsum-halo.fire { background: radial-gradient(ellipse at 50% 45%, rgba(255,107,74,.20), rgba(255,179,71,.14) 55%, transparent 75%); }
.wsum-halo.calm { background: radial-gradient(ellipse at 50% 45%, rgba(127,164,138,.22), rgba(212,168,83,.10) 55%, transparent 75%); animation-duration: 14s; }
:root[data-theme="dark"] .wsum-halo { opacity: .35; }
@keyframes wsum-morph {
  0% { border-radius: 58% 42% 55% 45%/50% 58% 42% 50%; transform: translate(-8px,-6px); }
  100% { border-radius: 52% 48% 60% 40%/44% 54% 46% 56%; transform: translate(6px,4px) scale(1.05); }
}
@media (prefers-reduced-motion: reduce) { .wsum-halo { animation: none; } }
.wsum-hero > :not(.wsum-halo) { position: relative; z-index: 1; }
.wsum-hero .wsum-over { font-size: 10px; font-weight: 800; letter-spacing: .14em; text-transform: uppercase; color: var(--coral-deep); }
.wsum-hero .wsum-over.closed { color: var(--text-muted); }
.wsum-hero h2 { font-family: var(--ff-display); font-size: 20px; font-weight: 800; letter-spacing: -.02em; margin-top: 5px; color: var(--ink); }
.wsum-num { font-size: 54px; font-weight: 200; letter-spacing: -.04em; line-height: 1; font-variant-numeric: tabular-nums; margin-top: 14px; color: var(--ink); }
.wsum-num .of { font-size: 26px; font-weight: 200; color: var(--text-muted); }
.wsum-num .unit { font-size: 17px; font-weight: 300; color: var(--text-muted); margin-left: 6px; }
.wsum-sub { font-size: 12px; color: var(--text-secondary); font-weight: 500; margin-top: 8px; }
.wsum-sub b { font-weight: 700; color: var(--ink); }
.wsum-regrow { display: flex; flex-wrap: wrap; gap: 6px; justify-content: center; padding: 14px 22px 0; position: relative; z-index: 1; }
.wsum-reg { display: inline-flex; align-items: center; gap: 5px; border-radius: var(--r-full); padding: 5px 11px; font-size: 10.5px; font-weight: 800; background: var(--fam-wash, var(--surface-recess)); color: var(--fam-deep, var(--text-secondary)); }
.wsum-reg .n { font-family: var(--ff-mono); font-weight: 600; font-size: 9.5px; opacity: .85; }
.wsum-reg.off { background: var(--surface-recess); color: var(--text-disabled); text-decoration: line-through; }
/* The stat strip is the Mozaik one (.mz-statstrip / .mz-statcell) as of mezo-d20.8.2.1 — the
   prototype's separate floating cells, not the old single grid with divider seams. Only the
   value tones stay local, because the strip primitive knows nothing about medals or targets. */
.wsum-stripwrap { padding: 16px 20px 0; }
.wsum-stripwrap .v { font-size: 17px; font-weight: 700; letter-spacing: -.02em; font-variant-numeric: tabular-nums; color: var(--ink); display: block; }
.wsum-stripwrap .v .u { font-size: 9.5px; font-weight: 500; color: var(--text-muted); margin-left: 1px; }
.wsum-stripwrap .v.gold { color: var(--amber-deep); }
.wsum-stripwrap .v.green { color: var(--sage-deep); }
.wsum-stripwrap .l { font-size: 7.5px; font-weight: 700; letter-spacing: .16em; text-transform: uppercase; color: var(--text-muted); margin-top: 3px; }
.wsum-sec { padding: 20px 20px 0; }
.wsum-slabel { font-size: 9.5px; font-weight: 800; letter-spacing: .16em; text-transform: uppercase; color: var(--text-muted); margin-bottom: 9px; display: flex; align-items: center; gap: 6px; }
.wsum-slabel .cnt { font-family: var(--ff-mono); font-size: 9px; color: var(--text-disabled); font-weight: 600; letter-spacing: 0; }
.wsum-medal { display: flex; align-items: center; gap: 10px; background: linear-gradient(120deg, var(--accent-bg), var(--surface-card) 70%); border: 1px solid var(--accent-soft); border-radius: var(--r-xl); padding: 11px 13px; box-shadow: var(--shadow-sm); }
.wsum-medal + .wsum-medal { margin-top: 8px; }
.wsum-medal .disc { width: 34px; height: 34px; border-radius: var(--r-full); background: var(--wash-amber); display: flex; align-items: center; justify-content: center; font-size: 16px; flex: none; box-shadow: inset 0 0 0 1.5px var(--accent-soft); }
.wsum-medal .tx { flex: 1; min-width: 0; }
.wsum-medal .tx .t { font-size: 12.5px; font-weight: 700; color: var(--ink); }
.wsum-medal .tx .m { font-size: 10px; color: var(--text-muted); margin-top: 2px; }
.wsum-medal .val { text-align: right; flex: none; }
.wsum-medal .val .now { font-family: var(--ff-mono); font-size: 12px; font-weight: 700; color: var(--amber-deep); white-space: nowrap; }
.wsum-medal .val .prev { font-family: var(--ff-mono); font-size: 8.5px; color: var(--text-disabled); margin-top: 2px; white-space: nowrap; }
.wsum-targets { display: flex; align-items: center; gap: 9px; background: var(--success-bg); border: 1px solid var(--success-soft); border-radius: var(--r-xl); padding: 10px 13px; margin-top: 8px; }
.wsum-targets .tick { width: 24px; height: 24px; border-radius: var(--r-full); background: var(--surface-card); color: var(--sage-deep); font-size: 12px; font-weight: 800; display: flex; align-items: center; justify-content: center; flex: none; }
.wsum-targets .t { font-size: 11.5px; font-weight: 700; color: var(--success-hover); }
.wsum-targets .chips { display: flex; flex-wrap: wrap; gap: 4px; margin-top: 4px; }
.wsum-targets .chips span { font-family: var(--ff-mono); font-size: 8.5px; font-weight: 600; color: var(--sage-deep); background: var(--surface-card); border-radius: var(--r-full); padding: 2px 7px; }
.wsum-chal { display: flex; align-items: center; gap: 10px; background: var(--surface-card); border: 1px solid var(--divider); border-radius: var(--r-xl); padding: 10px 12px; box-shadow: var(--shadow-sm); }
.wsum-chal + .wsum-chal { margin-top: 8px; }
.wsum-chal .st { width: 28px; height: 28px; border-radius: var(--r-full); display: flex; align-items: center; justify-content: center; font-size: 13px; font-weight: 800; flex: none; }
.wsum-chal.hit .st { background: var(--wash-sage); color: var(--sage-deep); }
.wsum-chal.miss .st { background: var(--warning-bg); color: var(--warning-hover); }
.wsum-chal.skip .st { background: var(--surface-recess); color: var(--text-disabled); }
.wsum-chal .tx { flex: 1; min-width: 0; }
.wsum-chal .tx .t { font-size: 12px; font-weight: 700; color: var(--ink); }
.wsum-chal .tx .m { font-family: var(--ff-mono); font-size: 9px; color: var(--text-muted); margin-top: 2px; }
.wsum-chal .out { font-size: 9.5px; font-weight: 800; border-radius: var(--r-full); padding: 4px 9px; white-space: nowrap; flex: none; }
.wsum-chal.hit .out { background: var(--wash-sage); color: var(--sage-deep); }
.wsum-chal.miss .out { background: var(--warning-bg); color: var(--warning-hover); }
.wsum-chal.skip .out { background: var(--surface-recess); color: var(--text-disabled); }
/* ===== Edzés-review · kontextus-riport (mezo-d20.8.2.1, spec 2026-08-31) ==============
   The five near-identical white exercise cards are gone: the inventory now runs sideways as a
   swimlane, and the depth lives on the exercise's own view rather than in the scroll. The
   swimlane and the exercise view serve BOTH modes — the inventory belongs to the closing
   report too; only the comparison tile and the stepping are the revisit's own. */

/* --- „Mihez képest" · closed only ------------------------------------------------- */
.wr-cmp { margin: 16px 20px 0; padding: 12px 14px 13px; border-radius: var(--r-xl);
  background: var(--mz-wash-sky); border: 0.5px solid var(--divider); box-shadow: var(--mz-shadow-sky); }
.wr-cmp .eyebrow { font-size: 8.5px; font-weight: 800; letter-spacing: .16em; text-transform: uppercase; color: var(--text-muted); }
.wr-cmp-ref { display: flex; align-items: baseline; gap: 7px; margin-top: 3px; flex-wrap: wrap; }
.wr-cmp-ref b { font-size: 13px; font-weight: 700; color: var(--ink); }
.wr-cmp-ref .ago { font-size: 10.5px; font-weight: 600; color: var(--text-muted); }
.wr-cmp-cells { display: flex; gap: 8px; margin-top: 11px; }
.wr-cmp-cell { flex: 1; text-align: center; border-radius: var(--r-lg); padding: 8px 4px 7px;
  background: var(--mz-cellbg); border: 0.5px solid var(--divider); }
/* ADR 0010, and the reason there is deliberately NO `.down` class: the number is signed and
   honest, but the palette has no punishing tone to reach for. A lighter week reads neutral. */
.wr-cmp-cell .v { display: block; font-size: 15px; font-weight: 600; font-variant-numeric: tabular-nums; color: var(--text-secondary); }
.wr-cmp-cell .v.up { color: var(--sage-deep); }
.wr-cmp-cell .l { display: block; font-size: 9px; color: var(--text-muted); margin-top: 2px; }
.wr-cmp-cell .was { display: block; font-size: 8.5px; color: var(--text-tertiary); font-variant-numeric: tabular-nums; }

/* --- gyakorlat-swimlane ------------------------------------------------------------ */
.wr-lane-head { display: flex; align-items: baseline; gap: 8px; padding: 0 2px 8px; }
.wr-lane-head .hint { margin-left: auto; font-size: 9.5px; color: var(--text-muted); }
.wr-lane { display: flex; gap: 9px; overflow-x: auto; scrollbar-width: none;
  scroll-snap-type: x mandatory; margin: 0 -20px; padding: 3px 20px 6px; }
.wr-lane::-webkit-scrollbar { display: none; }
.wr-extile { flex: none; width: 151px; scroll-snap-align: start; cursor: pointer; text-align: left;
  font: inherit; color: var(--ink); display: flex; flex-direction: column; gap: 6px;
  border: 0.5px solid var(--divider); border-radius: var(--r-xl); padding: 11px 12px 12px;
  background: var(--fam-wash); box-shadow: var(--shadow-sm); }
.wr-extile:focus-visible { outline: 2px solid var(--coral-deep); outline-offset: 2px; }
.wr-extile.dead { opacity: .6; }
.wr-extile.dead .nm { text-decoration: line-through; color: var(--text-muted); }
.wr-extile .hd { display: flex; align-items: center; }
.wr-extile .mono { width: 28px; height: 28px; border-radius: var(--r-md); display: grid; place-items: center;
  flex: none; background: var(--surface-card); color: var(--fam-deep); font-size: 13px; font-weight: 700; }
.wr-extile .stamp { margin-left: auto; font-size: 8px; font-weight: 800; letter-spacing: .1em;
  color: var(--amber-deep); background: var(--wash-amber); border-radius: var(--r-full); padding: 2px 7px; }
.wr-extile .nm { font-size: 11px; font-weight: 700; line-height: 1.25; min-height: 28px; }
.wr-extile .lbl { font-size: 8px; font-weight: 800; letter-spacing: .14em; text-transform: uppercase; color: var(--text-muted); }
/* The anchor: ONE number per exercise, big enough to read at a glance. */
.wr-extile .top { font-size: 20px; font-weight: 300; letter-spacing: -.01em; font-variant-numeric: tabular-nums; color: var(--fam-deep); }
.wr-extile .top .x { font-size: 13px; color: var(--text-muted); }
.wr-extile .foot { display: flex; align-items: baseline; gap: 5px; font-size: 9px; font-weight: 600; color: var(--text-muted); }
.wr-extile .ncnt { font-weight: 500; color: var(--text-tertiary); }
/* Set bars: solid = logged · gold = medal · faint = warmup · dashed = missed. */
.wr-setbars { display: flex; gap: 4px; }
.wr-setbars i { flex: 1; height: 5px; border-radius: 3px; background: var(--fam-deep); opacity: .42; }
.wr-setbars i.med { background: var(--amber-deep); opacity: 1; }
.wr-setbars i.warm { opacity: .16; }
.wr-setbars i.miss { background: none; border: 1px dashed var(--divider); }

/* --- gyakorlat-oldal --------------------------------------------------------------- */
.wr-exhero { display: flex; align-items: center; gap: 12px; padding: 8px 20px 14px; }
.wr-exhero .mono { width: 50px; height: 50px; border-radius: var(--r-xl); display: grid; place-items: center;
  flex: none; background: var(--fam-wash); color: var(--fam-deep); font-size: 21px; font-weight: 700; box-shadow: var(--shadow-sm); }
.wr-exhero .nm { font-size: 17px; font-weight: 700; line-height: 1.2; color: var(--ink); }
.wr-exhero .sb { display: flex; align-items: center; gap: 7px; margin-top: 3px; flex-wrap: wrap; font-size: 11px; color: var(--text-muted); }
.wr-exhero .mus { font-size: 8.5px; font-weight: 800; letter-spacing: .08em; text-transform: uppercase;
  border-radius: var(--r-sm); padding: 3px 6px; background: var(--fam-wash); color: var(--fam-deep); }

/* One tile per set — this is where the number finally gets room, and the whole reason the
   scrolling chip rows went away. */
.wr-set { display: flex; align-items: center; gap: 11px; border-radius: var(--r-lg); padding: 11px 13px;
  background: var(--surface-card); border: 1px solid var(--divider); box-shadow: var(--shadow-sm); }
.wr-set + .wr-set { margin-top: 7px; }
.wr-set .ix { width: 26px; height: 26px; border-radius: var(--r-md); flex: none; display: grid; place-items: center;
  font-size: 11px; font-weight: 700; background: var(--fam-wash); color: var(--fam-deep); font-variant-numeric: tabular-nums; }
.wr-set.warm .ix { background: var(--surface-recess); color: var(--text-disabled); }
.wr-set .tx { flex: 1; min-width: 0; }
.wr-set .load { font-size: 17px; font-weight: 300; letter-spacing: -.01em; font-variant-numeric: tabular-nums; color: var(--ink); }
.wr-set .load b { font-weight: 600; }
.wr-set .rir { font-size: 10.5px; font-weight: 600; color: var(--text-muted); margin-left: 5px; }
.wr-set .band { font-size: 8.5px; font-weight: 800; letter-spacing: .1em; text-transform: uppercase; color: var(--text-muted); margin-left: 5px; }
.wr-set .band.in { color: var(--sage-deep); }
.wr-set .note { font-size: 10.5px; color: var(--text-secondary); margin-top: 3px; }
.wr-set .vol { flex: none; font-size: 11px; font-weight: 600; color: var(--text-tertiary); font-variant-numeric: tabular-nums; }
.wr-set.rec { background: var(--wash-amber); border-color: var(--accent-soft); }
.wr-set.rec .vol { color: var(--amber-deep); }
/* The missed set stays a ghost: no red, no "hiányzik" — the report does not punish. */
.wr-set.ghost { background: transparent; border: 1px dashed var(--divider); box-shadow: none; }
.wr-set.ghost .ix { background: transparent; border: 1px dashed var(--divider); color: var(--text-disabled); }
.wr-set.ghost .load { font-size: 12px; color: var(--text-disabled); }

/* --- léptetés a template-nap láncán · closed only ---------------------------------- */
.wr-stepnav { display: flex; gap: 8px; padding: 16px 20px 0; }
.wr-stepnav button { flex: 1; font: inherit; cursor: pointer; border-radius: var(--r-lg); padding: 10px 12px;
  background: var(--surface-card); border: 1px solid var(--divider); box-shadow: var(--shadow-sm);
  text-align: left; color: var(--ink); }
.wr-stepnav button.nx { text-align: right; }
/* Disabled rather than absent: the chain's existence stays visible at either end. */
.wr-stepnav button:disabled { opacity: .42; cursor: default; box-shadow: none; }
.wr-stepnav button:focus-visible { outline: 2px solid var(--coral-deep); outline-offset: 2px; }
.wr-stepnav small { display: block; font-size: 8px; font-weight: 800; letter-spacing: .14em; text-transform: uppercase; color: var(--text-muted); }
.wr-stepnav b { font-size: 12px; font-weight: 600; }

.wsum-ctas { padding: 20px 20px 26px; display: flex; flex-direction: column; gap: 9px; }

/* ===== Markdown prose (mezo-at8x.1) — the companion's model-written answers ==========
   The chat bubble renders real markdown blocks (@/shared/lib/markdown), so the prose needs
   the block rhythm a single <p> never had: paragraph spacing, list indents, a heading weight.
   Scoped under .md-prose so the primitives can't leak into curated app copy. */
.md-prose { font-size: 14px; line-height: 1.55; color: var(--text-primary); }
.md-prose > * + * { margin-top: 10px; }
.md-p { white-space: pre-line; }
.md-h { font-weight: 700; font-size: 13.5px; letter-spacing: -0.01em; }
.md-prose .md-h + * { margin-top: 6px; }
.md-list { padding-left: 18px; display: flex; flex-direction: column; gap: 5px; }
ul.md-list { list-style: disc; }
ol.md-list { list-style: decimal; }
.md-list li { padding-left: 2px; }
.md-list li::marker { color: var(--text-tertiary); }
.md-code {
  font-family: var(--ff-mono); font-size: 12.5px;
  background: var(--surface-2); border: 1px solid var(--border-subtle);
  border-radius: var(--r-sm); padding: 1px 5px;
}

/* ===== Chat composer (mezo-at8x.2) ==================================================
   The chat rides the single app scroller, so the input pins itself just above the tab bar
   instead of scrolling away at the end of a long transcript.

   The scroller's own bottom padding is ZEROED while the composer is mounted, and the composer's
   margin reserves that clearance instead: engines disagree on whether a sticky `bottom` offset is
   measured against the scrollport's padding box or its content box, and with the padding at 0 both
   readings land in the same place. (Chrome measured it content-box, which double-counted the
   reserve and parked the bar mid-transcript — caught in browser QA, not by the tests.) */
.phone-screen:has(.chat-composer) .screen-content { padding-bottom: 0; }
/* A SHORT transcript must not leave the composer floating mid-screen: while the chat is mounted
   the scroller and the section wrapper become columns, so the thread absorbs the slack and the
   composer sits at the bottom whether there are two messages or two hundred. (Same idiom as
   `.screen-content:has(.sky-islands)`.) */
.phone-screen:has(.chat-composer) .screen-content { display: flex; flex-direction: column; }
.phone-screen:has(.chat-composer) .screen-content > :last-child { flex: 1; display: flex; flex-direction: column; }
.chat-page { flex: 1; }
.chat-thread { flex: 1; }
.chat-composer {
  position: sticky;
  bottom: var(--screen-bottom-pad);
  margin-bottom: var(--screen-bottom-pad);
  z-index: 20;
  background: var(--surface-card);
  box-shadow: var(--shadow-md);
}

/* Recording mic (mezo-at8x.4) — a slow breath while the composer is listening. */
.chat-mic-live { animation: pulse-soft 1.4s ease-in-out infinite; }
@media (prefers-reduced-motion: reduce) { .chat-mic-live { animation: none; } }

/* ============================================================
   Mozaik 2.0 primitives (design_2.0 — mezo-d20.1.3)
   Values = the prototype heads' CSS ×1.18 (330→390px frame scale),
   light-mode hexes verbatim from the prototypes. The dark ("Pulse")
   and circadian overrides for the wash tokens land in F0.5
   (mezo-d20.1.5) — components never branch on theme.
   ============================================================ */

/* entrance stagger hook — the choreography trigger (adding .play) is the
   motion kit's job (F0.4); without .play tiles render settled. */
.mz-play .rise { opacity: 0; transform: translateY(19px) scale(0.98);
  animation: mz-rise 0.5s cubic-bezier(0.22, 0.9, 0.32, 1.15) forwards; animation-delay: var(--d, 0ms); }
@keyframes mz-rise { to { opacity: 1; transform: none; } }

.mz-mosaic { display: grid; grid-template-columns: 1fr 1fr; gap: 11px; }

/* .mz-mosaic-desktop/.mz-span-* (the admin hub's 12-column counterpart to .mz-mosaic) live
   in their own §Admin hub shell section below, OUTSIDE this Mozaik section — see there for
   why: mozaikCssTokens.test.ts's hardcoded-hex guard scans this section only, and the admin
   shell's colors are ported verbatim (light-only) from the prototype rather than tokenized. */

/* The panel's own vertical rhythm — the prototype's `.dp-panel { gap: 9px }` at ×1.18,
   the same 11px the mosaic uses between tiles, so a hero, a mosaic and a stat strip are
   spaced like tiles rather than by whatever margins their components happen to carry.
   This lived as four identical per-tab copies (.eh-/.enh-/.fh-/.mzh-panel), which is
   exactly why the two pages that forgot to declare one — the Nap daypart panels and the
   Heti hub — had their children touching at 0px (mezo-d20.11.2). One class now. */
.mz-panel-stack { display: flex; flex-direction: column; gap: 11px; }

.mz-tile {
  border-radius: 20px; padding: 12px 13px; min-height: 104px;
  display: flex; flex-direction: column; text-align: left;
  font-family: inherit; color: var(--text-primary);
  border: 0.5px solid rgba(43, 33, 24, 0.06);
  box-shadow: var(--mz-shadow);
  transition: transform 0.15s cubic-bezier(0.3, 0.8, 0.4, 1.4);
  background: var(--mz-wash, var(--mz-wash-white));
}
button.mz-tile { cursor: pointer; }
button.mz-tile:active { transform: scale(0.96); }

/* washes — prototype .t-* gradients + their colored shadows */
.mz-w-coral { --mz-wash: var(--mz-wash-coral); }
.mz-w-sage  { --mz-wash: var(--mz-wash-sage); box-shadow: var(--mz-shadow-sage); }
.mz-w-sky   { --mz-wash: var(--mz-wash-sky); box-shadow: var(--mz-shadow-sky); }
.mz-w-gold  { --mz-wash: var(--mz-wash-gold); box-shadow: var(--mz-shadow-gold); }
.mz-w-lav   { --mz-wash: var(--mz-wash-lav); box-shadow: var(--mz-shadow-lav); }
.mz-w-rose  { --mz-wash: var(--mz-wash-rose); box-shadow: var(--mz-shadow-rose); }
.mz-w-white { --mz-wash: var(--mz-wash-white); }
.mz-w-most  { --mz-wash: var(--mz-wash-white); border: 1px solid #FF6B4A;
  box-shadow: var(--mz-shadow-most); }

.mz-tile-top { display: flex; align-items: center; }
.mz-eyebrow { font-size: 10px; font-weight: 700; letter-spacing: 0.18em; text-transform: uppercase; color: var(--mz-ink-mut); }
/* mezo-hq44: szemöldök/címke ikonnal — a glifa helyére lépő Icon a szöveggel egy sorban,
   optikailag középre igazítva (a .mzc-memeb mintája). Az Icon svg-je display:block, ezért
   EGYSORNYI címkénél az inline-flex a helyes hordozó (.mz-ebic); FOLYÓ szövegben, ahol a
   sortörésnek meg kell maradnia, az ikon lesz inline (.mz-icin). */
.mz-ebic { display: inline-flex; align-items: center; justify-content: center; gap: 5px; }
.mz-icin > svg { display: inline-block; vertical-align: -0.16em; }
.mz-mut { color: var(--mz-ink-soft); }
.mz-dot { width: 8px; height: 8px; border-radius: 50%; background: #FF6B4A; flex: none; margin-left: auto; }
/* The counted sibling of .mz-dot (prototype `.badge.unread`). A number already carries the
   "there is something here" signal, so a tile renders one or the other, never both. */
.mz-badge { min-width: 18px; height: 18px; margin-left: auto; flex: none; border-radius: 999px;
  padding: 0 5px; display: grid; place-items: center; background: var(--gradient-cta); color: #fff;
  font-size: 10.5px; font-weight: 700; font-variant-numeric: tabular-nums;
  box-shadow: 0 4px 9px -2px rgba(255, 91, 54, 0.6); }
.mz-spotwrap { flex: 1; display: grid; place-items: center; padding: 5px 0; }
.mz-tile-line { font-size: 11px; font-weight: 600; text-align: center;
  display: -webkit-box; -webkit-line-clamp: 2; -webkit-box-orient: vertical; overflow: hidden; }

.mz-statstrip { display: flex; gap: 11px; }
.mz-statcell {
  flex: 1; text-align: center; padding: 11px 5px; border-radius: 18px;
  background: var(--mz-cellbg); border: 0.5px solid rgba(43, 33, 24, 0.07);
  box-shadow: inset 0 1px 0 rgba(255, 255, 255, 0.8), 0 9px 19px -12px rgba(43, 33, 24, 0.25);
}
.mz-statcell b { font-size: 15px; font-weight: 600; display: block; font-variant-numeric: tabular-nums; }
.mz-statcell small { font-size: 10px; color: var(--mz-ink-soft); }
/* over its cap — the prototype's dashed cell: a flag the model will act on, not an alarm */
.mz-statcell-over { border: 1px dashed var(--mz-cell-gold-ink); background: var(--mz-cell-gold-bg); }
.mz-statcell-over small { color: var(--mz-cell-gold-ink); }

/* tinted mini-cells — the .mcells recipe */
.mz-mcells { display: flex; gap: 6px; }
.mz-mcells span { flex: 1; border-radius: 13px; padding: 6px 2px 5px; text-align: center;
  background: var(--mw); color: var(--md); box-shadow: inset 0 1px 0 rgba(255, 255, 255, 0.7); }
.mz-mcells b { display: block; font-size: 14px; font-weight: 700; font-variant-numeric: tabular-nums; letter-spacing: -0.01em; }
.mz-mcells small { font-size: 7px; font-weight: 800; letter-spacing: 0.1em; text-transform: uppercase; opacity: 0.78; }
.mz-c-sage  { --mw: var(--mz-cell-sage-bg); --md: var(--mz-cell-sage-ink); }
.mz-c-coral { --mw: var(--mz-cell-coral-bg); --md: var(--mz-cell-coral-ink); }
.mz-c-amber { --mw: var(--mz-cell-amber-bg); --md: var(--mz-cell-amber-ink); }
.mz-c-lav   { --mw: var(--mz-cell-lav-bg); --md: var(--mz-cell-lav-ink); }
.mz-c-sky   { --mw: var(--mz-cell-sky-bg); --md: var(--mz-cell-sky-ink); }
.mz-c-rose  { --mw: var(--mz-cell-rose-bg); --md: var(--mz-cell-rose-ink); }
.mz-c-gold  { --mw: var(--mz-cell-gold-bg); --md: var(--mz-cell-gold-ink); }

/* tile → own page scaffold (Huawei pattern) */
.mz-page {
  display: flex; flex-direction: column; min-height: 100%;
  background: var(--canvas);
  /* Full-bleed page background: pull out of the scroller's --screen-gutter so the
     tone gradient reaches the physical screen edge — only the CONTENT keeps the
     gutter, via the head/hero/body's own 14-17px inner padding (user QA, mezo-eczm). */
  margin-inline: calc(-1 * var(--screen-gutter));
}
.mz-p-coral { background: linear-gradient(180deg, var(--mz-tone-coral) 0%, var(--canvas) 36%); }
.mz-p-gold  { background: linear-gradient(180deg, var(--mz-tone-gold) 0%, var(--canvas) 36%); }
.mz-p-lav   { background: linear-gradient(180deg, var(--mz-tone-lav) 0%, var(--canvas) 36%); }
.mz-p-rose  { background: linear-gradient(180deg, var(--mz-tone-rose) 0%, var(--canvas) 36%); }
.mz-p-sage  { background: linear-gradient(180deg, var(--mz-tone-sage) 0%, var(--canvas) 36%); }
.mz-p-sky   { background: linear-gradient(180deg, var(--mz-tone-sky) 0%, var(--canvas) 36%); }
.mz-page-head { display: flex; align-items: center; gap: 9px; padding: 9px 14px 0; }
.mz-backbtn {
  border: none; background: var(--mz-chipbg); font-family: inherit; cursor: pointer;
  border-radius: 999px; padding: 7px 15px 7px 11px; font-size: 13px; font-weight: 600; color: var(--text-primary);
  display: flex; align-items: center; gap: 5px;
  box-shadow: 0 7px 17px -9px rgba(43, 33, 24, 0.3);
}
.mz-backbtn:focus-visible { outline: 2px solid var(--primary-deep); outline-offset: 2px; }
.mz-page-hero { display: grid; justify-items: center; text-align: center; gap: 1px; padding: 9px 17px 14px; }
.mz-hero-nm { font-size: 18px; font-weight: 700; }
.mz-hero-row { display: flex; align-items: center; gap: 9px; }
.mz-bignum { font-weight: 200; font-size: 47px; letter-spacing: -0.02em; font-variant-numeric: tabular-nums; }
.mz-hero-sb { font-size: 12px; color: var(--mz-ink-soft); }
.mz-page-body { flex: 1; min-height: 0; overflow-y: auto; scrollbar-width: none; padding: 2px 17px 19px; }
.mz-page-body::-webkit-scrollbar { display: none; }
.mz-principle { font-size: 11px; font-weight: 300; color: var(--mz-ink-mut); text-align: center; margin-top: 19px; }

/* ===== Cél Mozaik hub — state first, then one inspectable tile per concern (mezo-ricj.2) ===== */
.goal-hub-page .pgact { margin-left: auto; }
.goal-hub-body { display: flex; flex-direction: column; gap: 14px; padding-top: 8px; }
.goal-hub-title { padding: 0 3px; }
.goal-hub-title h2 { margin-top: 3px; font-size: 28px; line-height: 1; letter-spacing: -0.045em; }

.goal-course-hero {
  --goal-course-accent: var(--mz-cell-sage-ink);
  position: relative; overflow: hidden; min-height: 226px; border-radius: 29px;
  background: radial-gradient(circle at 89% 18%, color-mix(in srgb, var(--surface-card) 74%, transparent), transparent 20%), var(--mz-wash-sage);
  box-shadow: var(--mz-shadow-sage); border: 0.5px solid color-mix(in srgb, var(--goal-course-accent) 12%, transparent);
}
.goal-course-hero.is-watch { --goal-course-accent: var(--mz-cell-gold-ink); background: radial-gradient(circle at 89% 18%, color-mix(in srgb, var(--surface-card) 74%, transparent), transparent 20%), var(--mz-wash-gold); box-shadow: var(--mz-shadow-gold); }
.goal-course-hero.is-learning { --goal-course-accent: var(--mz-cell-lav-ink); background: radial-gradient(circle at 89% 18%, color-mix(in srgb, var(--surface-card) 74%, transparent), transparent 20%), var(--mz-wash-lav); box-shadow: var(--mz-shadow-lav); }
.goal-course-hero.is-invalid { --goal-course-accent: var(--mz-cell-coral-ink); background: radial-gradient(circle at 89% 18%, color-mix(in srgb, var(--surface-card) 74%, transparent), transparent 20%), var(--mz-wash-coral); box-shadow: var(--mz-shadow-coral); }
.goal-course-hero::after { content: ''; position: absolute; width: 138px; height: 138px; right: -47px; top: -53px; border-radius: 50%; border: 24px solid color-mix(in srgb, var(--surface-card) 24%, transparent); box-shadow: 0 0 0 17px color-mix(in srgb, var(--surface-card) 11%, transparent); pointer-events: none; }
.goal-course-open { position: relative; z-index: 1; width: 100%; padding: 20px 18px 17px; border: 0; background: none; color: var(--text-primary); font: inherit; text-align: left; cursor: pointer; }
.goal-course-top { display: flex; align-items: flex-start; justify-content: space-between; gap: 15px; }
.goal-course-message { min-width: 0; }
.goal-course-message h1 { max-width: 225px; margin-top: 7px; font-size: 28px; line-height: 0.98; font-weight: 800; letter-spacing: -0.045em; }
.goal-course-message p { max-width: 245px; margin-top: 8px; color: var(--mz-ink-soft); font-size: 12px; line-height: 1.45; }
.goal-course-ring { position: relative; flex: 0 0 64px; width: 64px; height: 64px; border-radius: 50%; display: grid; place-items: center; background: conic-gradient(var(--goal-course-accent) calc(var(--goal-progress) * 1%), color-mix(in srgb, var(--surface-card) 58%, transparent) 0); box-shadow: 0 10px 20px color-mix(in srgb, var(--goal-course-accent) 20%, transparent); }
.goal-course-ring::before { content: ''; position: absolute; inset: 8px; border-radius: 50%; background: color-mix(in srgb, var(--surface-card) 75%, var(--mz-tone-gold)); }
.goal-course-ring span { position: relative; z-index: 1; font-size: 14px; font-weight: 800; }
.goal-course-weights { margin-top: 23px; display: grid; grid-template-columns: 1fr minmax(56px, 1fr) 1fr; align-items: center; gap: 9px; }
.goal-course-weights span:last-child { text-align: right; }
.goal-course-weights b { display: block; font-size: 23px; line-height: 1; letter-spacing: -0.04em; font-variant-numeric: tabular-nums; }
.goal-course-weights small { display: block; margin-top: 5px; color: var(--mz-ink-mut); font-size: 9px; font-weight: 800; letter-spacing: 0.08em; text-transform: uppercase; }
.goal-course-weights i { height: 3px; border-radius: 3px; background: linear-gradient(90deg, color-mix(in srgb, var(--goal-course-accent) 55%, var(--surface-card)), var(--goal-course-accent)); }
.goal-course-paces { margin-top: 15px; display: grid; grid-template-columns: 1fr 1fr; gap: 8px; }
.goal-course-paces span { padding: 10px 11px; border-radius: 16px; background: color-mix(in srgb, var(--surface-card) 60%, transparent); }
.goal-course-paces small { display: block; color: var(--mz-ink-mut); font-size: 8px; font-weight: 800; letter-spacing: 0.08em; text-transform: uppercase; }
.goal-course-paces b { display: block; margin-top: 3px; font-size: 13px; font-variant-numeric: tabular-nums; }
.goal-course-date { display: block; margin-top: 10px; color: var(--mz-ink-soft); font-size: 10px; font-weight: 700; text-align: right; }
.goal-course-repair { position: relative; z-index: 2; margin: 0 18px 18px; padding: 9px 14px; border: 0; border-radius: 999px; color: var(--mz-cell-coral-ink); background: color-mix(in srgb, var(--surface-card) 68%, transparent); font: 800 12px/1.2 inherit; cursor: pointer; }

.goal-hub-mosaic { gap: 11px; }
.goal-hub-mosaic .mz-tile { min-height: 154px; padding: 16px; }
.goal-hub-mosaic .mz-spotwrap { padding: 3px 0 1px; }
.goal-hub-mosaic .mz-tile-line { overflow: visible; -webkit-line-clamp: unset; }
.goal-tile-copy { display: flex; min-height: 61px; flex-direction: column; align-items: center; }
.goal-tile-copy strong { font-size: 20px; line-height: 1.05; font-weight: 800; letter-spacing: -0.035em; text-align: center; overflow-wrap: anywhere; }
.goal-tile-copy small { margin-top: 7px; color: var(--mz-ink-soft); font-size: 9px; line-height: 1.3; font-weight: 600; text-align: center; }
.goal-tile-copy em { margin-top: auto; padding-top: 7px; color: var(--mz-cell-coral-ink); font-size: 9px; font-style: normal; font-weight: 800; }
.goal-empty-body { padding-top: 28px; }

.goal-skeleton-head { padding: 9px 14px 0; }
.goal-skeleton-hero { min-height: 226px; display: flex; flex-direction: column; gap: 16px; border-radius: 29px; }
.goal-skeleton-top { display: flex; justify-content: space-between; align-items: flex-start; gap: 16px; }
.goal-skeleton-top > span { display: flex; flex-direction: column; gap: 9px; }
.goal-skeleton-tile { min-height: 154px; display: flex; flex-direction: column; justify-content: space-between; align-items: center; border-radius: 20px; }
.goal-detail-shell { min-height: 140px; padding: 20px; border-radius: 24px; background: var(--mz-wash-white); box-shadow: var(--mz-shadow); color: var(--mz-ink-soft); font-size: 13px; line-height: 1.5; }

/* Cél detail family (mezo-ricj.2): the same warm, living Mozaik language as the
   hub, with one calm rise per card and all color derived from theme tokens. */
.goal-detail-loading { margin: 52px 18px 0; display: grid; gap: 12px; }
.goal-detail-loading span { display: block; height: 88px; border-radius: 24px; background: var(--mz-gbar-bg); }
.goal-detail-loading span:first-child { height: 150px; }
.goal-detail-card, .goal-attach-card, .goal-settings-grid, .goal-detail-notice {
  border: 0.5px solid var(--mz-line-soft); border-radius: 24px; padding: 18px;
  background: var(--mz-stripbg); box-shadow: var(--mz-shadow); color: var(--text-primary);
}
.goal-detail-kicker { font-size: 9px; font-weight: 850; letter-spacing: 0.12em; text-transform: uppercase; color: var(--mz-ink-mut); }
.goal-detail-notice { font-size: 13px; line-height: 1.55; background: var(--mz-wash-coral); }
.goal-detail-macros { margin-bottom: 12px; }

/* The five inspectable Goal siblings use the approved artifact's asymmetrical hero card:
   compact factual copy on the left, one oversized clay emblem, three dense facts at the
   foot. The source facts remain server-owned; only the visual anatomy is shared here. */
.goal-detail-page .mz-page-body { padding-top: 8px; }
.goal-detail-hero {
  position: relative; min-height: 220px; overflow: hidden; padding: 21px; border: 0.5px solid var(--mz-line-soft);
  border-radius: 29px; background: var(--mz-goal-hero-nutrition); box-shadow: var(--mz-shadow-sage); color: var(--text-primary);
}
.goal-detail-hero::after { content: ''; position: absolute; width: 150px; height: 150px; right: -53px; top: -52px; border-radius: 50%; border: 24px solid color-mix(in srgb, var(--surface-card) 24%, transparent); box-shadow: 0 0 0 17px color-mix(in srgb, var(--surface-card) 11%, transparent); pointer-events: none; }
.goal-detail-hero-segment { background: var(--mz-goal-hero-segment); box-shadow: var(--mz-shadow-lav); }
.goal-detail-hero-plans { background: var(--mz-goal-hero-plans); box-shadow: var(--mz-shadow-sky); }
.goal-detail-hero-guards { background: var(--mz-goal-hero-guards); box-shadow: var(--mz-shadow-coral); }
.goal-detail-hero-settings { background: var(--mz-goal-hero-settings); box-shadow: var(--mz-shadow-sky); }
.goal-detail-hero-copy { position: relative; z-index: 2; max-width: 66%; }
.goal-detail-hero-copy > span { color: var(--mz-ink-mut); font-size: 9px; font-weight: 850; letter-spacing: 0.12em; text-transform: uppercase; }
.goal-detail-hero-copy > strong { display: block; margin-top: 9px; font-size: 34px; line-height: 0.95; font-weight: 800; letter-spacing: -0.055em; font-variant-numeric: tabular-nums; }
.goal-detail-hero-copy > p { margin: 8px 0 0; color: var(--mz-ink-soft); font-size: 11px; line-height: 1.42; }
.goal-detail-emblem { position: absolute; z-index: 2; right: 21px; top: 53px; width: 96px; height: 96px; border-radius: 34px; display: grid; place-items: center; transform: rotate(6deg); background: var(--mz-goal-emblem); box-shadow: inset 5px 6px 12px color-mix(in srgb, var(--surface-card) 85%, transparent), 0 16px 28px color-mix(in srgb, var(--text-primary) 16%, transparent); }
.goal-detail-emblem-nutrition { color: var(--mz-cell-sage-ink); }
.goal-detail-emblem-segment { color: var(--mz-cell-lav-ink); }
.goal-detail-emblem-plans, .goal-detail-emblem-settings { color: var(--mz-cell-sky-ink); }
.goal-detail-emblem-guards { color: var(--mz-cell-coral-ink); }
.goal-detail-pods { position: absolute; z-index: 3; left: 20px; right: 20px; bottom: 18px; display: grid; grid-template-columns: repeat(3, minmax(0, 1fr)); gap: 7px; }
.goal-detail-pod { min-width: 0; padding: 9px 8px; border-radius: 14px; background: color-mix(in srgb, var(--surface-card) 60%, transparent); box-shadow: inset 0 1px 0 color-mix(in srgb, var(--surface-card) 90%, transparent); }
.goal-detail-pod small { display: block; overflow: hidden; color: var(--mz-ink-mut); font-size: 7px; font-weight: 850; letter-spacing: 0.08em; text-overflow: ellipsis; text-transform: uppercase; white-space: nowrap; }
.goal-detail-pod strong { display: block; margin-top: 3px; overflow: hidden; font-size: 12px; line-height: 1.1; text-overflow: ellipsis; white-space: nowrap; }
.goal-detail-section-head { display: flex; align-items: baseline; justify-content: space-between; margin: 20px 2px 9px; color: var(--mz-ink-mut); font-size: 10px; font-weight: 850; letter-spacing: 0.12em; text-transform: uppercase; }

/* Goal suggestion review (mezo-ricj.3): a fixed-baseline before/after grid. Every row keeps
   the same three-area anatomy even at 320px, so values never staircase between cards. */
.goal-suggestion-page .mz-page-hero { padding-bottom: 18px; }
.goal-suggestion-page .mz-bignum { max-width: 300px; font-size: 26px; line-height: 1.02; font-weight: 750; letter-spacing: -0.035em; }
.goal-suggestion-page .mz-page-body { padding-top: 8px; }
.gs-status { margin-top: 10px; border-radius: 999px; padding: 5px 10px; background: var(--mz-cell-gold-bg); color: var(--mz-cell-gold-ink); font-size: 9px; font-weight: 850; letter-spacing: 0.08em; text-transform: uppercase; }
.gs-status-accepted { background: var(--mz-cell-sage-bg); color: var(--mz-cell-sage-ink); }
.gs-status-dismissed, .gs-status-superseded { background: var(--mz-chipbg); color: var(--mz-ink-mut); }
.gs-section-head { display: flex; align-items: center; justify-content: space-between; margin: 0 3px 10px; color: var(--mz-ink-mut); font-size: 10px; font-weight: 850; letter-spacing: 0.12em; text-transform: uppercase; }
.gs-section-head b { border-radius: 999px; padding: 4px 8px; background: var(--mz-chipbg); color: var(--mz-cell-coral-ink); }
.gs-reason-card { position: relative; min-height: 168px; overflow: hidden; margin-bottom: 20px; padding: 20px; border: 0.5px solid var(--mz-line-soft); border-radius: 27px; background: var(--mz-wash-gold); box-shadow: var(--mz-shadow-gold); }
.gs-reason-card::after { content: ''; position: absolute; width: 126px; height: 126px; right: -37px; bottom: -57px; border-radius: 50%; border: 21px solid color-mix(in srgb, var(--surface-card) 25%, transparent); box-shadow: 0 0 0 15px color-mix(in srgb, var(--surface-card) 12%, transparent); }
.gs-reason-card > div { position: relative; z-index: 2; max-width: 61%; }
.gs-reason-card p { margin: 9px 0 0; color: var(--mz-ink-soft); font-size: 11px; line-height: 1.45; }
.gs-reason-card b { display: inline-flex; margin-top: 11px; border-radius: 9px; padding: 4px 7px; background: color-mix(in srgb, var(--surface-card) 53%, transparent); color: var(--mz-cell-gold-ink); font-size: 8px; }
.gs-reason-orb { position: absolute; z-index: 2; right: 18px; top: 39px; width: 88px; height: 88px; border-radius: 50%; display: grid; place-items: center; padding: 12px; background: radial-gradient(circle at 34% 27%, color-mix(in srgb, var(--surface-card) 96%, var(--mz-tone-gold)) 0 9%, color-mix(in srgb, var(--dv-amber) 72%, var(--surface-card)) 29%, var(--primary-base) 73%, var(--primary-hover) 100%); box-shadow: inset 8px 9px 15px color-mix(in srgb, var(--surface-card) 48%, transparent), 0 14px 25px color-mix(in srgb, var(--primary-hover) 24%, transparent); color: var(--text-primary); font-size: 13px; font-weight: 850; text-align: center; }
.gdiff-grid { display: grid; gap: 10px; }
.gdiff-row {
  display: grid; grid-template-columns: minmax(0, 1fr) 30px minmax(0, 1fr);
  grid-template-rows: 20px 52px 23px; grid-template-areas: 'label label label' 'current arrow proposed' 'delta delta delta';
  min-height: 119px; padding: 15px 15px 9px; border: 0.5px solid color-mix(in srgb, var(--surface-card) 85%, var(--mz-line));
  border-radius: 24px; background: var(--mz-wash-gold); box-shadow: var(--mz-shadow-gold); color: var(--text-primary);
}
.gdiff-row:nth-child(3n + 2) { background: var(--mz-wash-sage); box-shadow: var(--mz-shadow-sage); }
.gdiff-row:nth-child(3n) { background: var(--mz-wash-sky); box-shadow: var(--mz-shadow-sky); }
.gdiff-row[data-field='guards'], .gdiff-row[data-field='segment'] { background: var(--mz-wash-lav); box-shadow: var(--mz-shadow-lav); }
.gdiff-unchanged { filter: saturate(.67); box-shadow: var(--mz-shadow); }
.gdiff-label { grid-area: label; align-self: start; color: var(--mz-ink-mut); font-size: 9px; font-weight: 850; letter-spacing: 0.11em; text-transform: uppercase; }
.gdiff-current, .gdiff-proposed { display: grid; grid-template-rows: 15px 27px; align-content: center; min-width: 0; }
.gdiff-current { grid-area: current; }
.gdiff-proposed { grid-area: proposed; text-align: right; }
.gdiff-current small, .gdiff-proposed small { align-self: end; color: var(--mz-ink-mut); font-size: 8px; font-weight: 800; letter-spacing: 0.08em; text-transform: uppercase; }
.gdiff-current strong, .gdiff-proposed strong { align-self: start; overflow-wrap: anywhere; font-size: 15px; line-height: 27px; font-weight: 760; font-variant-numeric: tabular-nums; }
.gdiff-proposed strong { color: var(--mz-cell-sage-ink); }
.gdiff-arrow { grid-area: arrow; align-self: center; justify-self: center; display: grid; place-items: center; width: 27px; height: 27px; border-radius: 50%; background: color-mix(in srgb, var(--surface-card) 74%, transparent); color: var(--primary-deep); font-size: 17px; }
.gdiff-delta { grid-area: delta; align-self: center; justify-self: end; border-radius: 999px; padding: 4px 8px; background: var(--mz-cell-coral-bg); color: var(--mz-cell-coral-ink); font-size: 9px; font-weight: 850; font-variant-numeric: tabular-nums; }
.gdiff-unchanged .gdiff-delta { background: var(--mz-chipbg); color: var(--mz-ink-mut); font-weight: 700; }
.gs-message, .gs-history { margin-top: 12px; border-radius: 21px; padding: 15px 16px; box-shadow: var(--mz-shadow); }
.gs-message strong, .gs-history strong { display: block; font-size: 13px; }
.gs-message p, .gs-history p { margin: 6px 0 0; color: var(--mz-ink-soft); font-size: 11px; line-height: 1.5; }
.gs-warning { background: var(--mz-wash-gold); box-shadow: var(--mz-shadow-gold); }
.gs-blocker, .gs-stale { background: var(--mz-wash-coral); box-shadow: var(--mz-shadow-coral); }
.gs-refresh { margin-top: 12px; border: 0; border-radius: 999px; padding: 9px 13px; background: var(--mz-chipbg); color: var(--mz-cell-coral-ink); font: 800 11px/1 inherit; cursor: pointer; }
.gs-history { display: grid; gap: 4px; background: var(--mz-wash-sage); box-shadow: var(--mz-shadow-sage); }
.gs-history > span { width: max-content; border-radius: 999px; padding: 4px 8px; background: var(--mz-chipbg); color: var(--mz-cell-sage-ink); font-size: 9px; font-weight: 850; text-transform: uppercase; }
