.goal-segment-node small { color: var(--mz-ink-soft); font-size: 10px; font-weight: 700; }
.goal-segment-node.is-current strong { color: var(--mz-cell-amber-ink); }
.goal-segment-line { height: 3px; border-radius: 99px; background: var(--mz-gbar-bg); position: relative; }
.goal-segment-line span { position: absolute; right: 0; top: 50%; width: 9px; height: 9px; border-radius: 50%; transform: translateY(-50%); background: var(--mz-cell-amber-ink); }
