.goal-segment-note p { margin: 9px 0 0; font-size: 12px; line-height: 1.55; color: var(--mz-ink-soft); }

.goal-connection-stack { display: grid; gap: 12px; }
.goal-connection { background: var(--mz-wash-sky); box-shadow: var(--mz-shadow-sky); overflow: hidden; }
.goal-week-ruler { display: grid; grid-template-columns: repeat(var(--goal-weeks, 8), minmax(0, 1fr)); gap: 2px; margin-bottom: 11px; color: var(--mz-ink-mut); font-size: 8px; text-align: center; }
.goal-plan-lane + .goal-plan-lane { margin-top: 14px; }
.goal-plan-grid { display: grid; grid-template-columns: repeat(var(--goal-weeks), minmax(0, 1fr)); min-height: 54px; gap: 2px; align-items: center; margin-top: 6px; }
.goal-plan-bar { min-width: 0; display: flex; align-items: center; justify-content: space-between; gap: 5px; min-height: 44px; border-radius: 14px; padding: 7px 9px; background: var(--mz-cell-sky-bg); color: var(--mz-cell-sky-ink); }
.goal-plan-running_block { background: var(--mz-cell-sage-bg); color: var(--mz-cell-sage-ink); }
.goal-plan-bar span { min-width: 0; display: grid; gap: 2px; }
.goal-plan-bar strong { overflow: hidden; text-overflow: ellipsis; white-space: nowrap; font-size: 10px; }
.goal-plan-bar small { display: flex; align-items: center; flex-wrap: wrap; gap: 3px; font-size: 8px; font-weight: 700; text-transform: uppercase; letter-spacing: 0.05em; }
.goal-plan-clip { display: inline-flex; border-radius: 999px; padding: 2px 5px; background: color-mix(in srgb, currentColor 12%, transparent); white-space: nowrap; }
.goal-plan-bar button { flex: none; border: 0; border-radius: 50%; width: 28px; height: 28px; background: var(--mz-chipbg); color: inherit; font: inherit; cursor: pointer; }
.goal-plan-empty { grid-column: 1 / -1; padding: 12px; border: 1px dashed var(--mz-line); border-radius: 14px; text-align: center; font-size: 10px; color: var(--mz-ink-mut); }
.goal-gap-row { display: flex; flex-wrap: wrap; gap: 6px; margin-top: 14px; }
.goal-gap-row span { border: 1px dashed var(--mz-cell-amber-ink); border-radius: 999px; padding: 5px 9px; background: var(--mz-cell-amber-bg); color: var(--mz-cell-amber-ink); font-size: 9px; font-weight: 800; }
.goal-sport-schedule { background: var(--mz-wash-rose); }
.goal-sport-row { display: flex; align-items: center; justify-content: space-between; gap: 12px; padding: 11px 0; font-size: 10px; color: var(--mz-ink-soft); }
.goal-sport-row + .goal-sport-row { border-top: 0.5px solid var(--mz-line-soft); }
.goal-sport-row > span:first-child { display: grid; gap: 3px; }
.goal-sport-row strong { color: var(--text-primary); font-size: 12px; }
.goal-sport-row small { color: var(--mz-ink-mut); }
.goal-attach-card { display: grid; gap: 14px; background: var(--mz-stripbg); }
.goal-attach-card > div:first-child { display: grid; gap: 5px; }
.goal-attach-actions { display: grid; grid-template-columns: 1fr 1fr; gap: 9px; }
.goal-attach-actions button, .goal-settings-edit { min-height: 48px; border: 1px solid var(--mz-line); border-radius: 16px; padding: 10px 12px; background: var(--mz-chipbg); color: var(--mz-cell-sky-ink); font: inherit; font-size: 11px; font-weight: 800; cursor: pointer; }

.goal-guard-warning { padding: 13px 15px; border-radius: 18px; background: var(--mz-cell-amber-bg); color: var(--mz-cell-amber-ink); font-size: 11px; line-height: 1.5; }
.goal-guard-grid { display: grid; gap: 12px; }
.goal-guard-card { background: var(--mz-wash-lav); box-shadow: var(--mz-shadow-lav); }
.goal-guard-alert { background: var(--mz-wash-coral); box-shadow: var(--mz-shadow-coral); }
.goal-guard-inactive { background: var(--mz-stripbg); box-shadow: var(--mz-shadow); }
.goal-guard-head { display: flex; align-items: center; justify-content: space-between; gap: 12px; }
.goal-guard-head b { border-radius: 999px; padding: 5px 9px; background: var(--mz-chipbg); color: var(--mz-ink-soft); font-size: 9px; }
.goal-guard-alert .goal-guard-head b { background: var(--mz-cell-coral-bg); color: var(--mz-cell-coral-ink); }
.goal-guard-ok .goal-guard-head b { background: var(--mz-cell-sage-bg); color: var(--mz-cell-sage-ink); }
.goal-guard-value { display: block; margin-top: 16px; font-size: 30px; font-weight: 300; color: var(--mz-cell-coral-ink); }
.goal-guard-metrics { display: grid; grid-template-columns: 1fr 1fr; gap: 9px; margin-top: 14px; }
.goal-guard-metrics span { display: grid; gap: 2px; padding: 11px; border-radius: 15px; background: var(--mz-chipbg); }
.goal-guard-metrics small { color: var(--mz-ink-mut); font-size: 9px; }
.goal-guard-card ul { margin: 14px 0 0; padding-left: 17px; color: var(--mz-ink-soft); font-size: 11px; line-height: 1.5; }

.goal-settings-grid { display: grid; grid-template-columns: 1fr 1fr; gap: 9px; background: var(--mz-wash-rose); box-shadow: var(--mz-shadow-rose); }
.goal-settings-grid > div { display: grid; align-content: start; gap: 6px; min-width: 0; padding: 12px; border-radius: 17px; background: var(--mz-chipbg); }
