.ppl-trendcard, .ppl-ctxcard, .ppl-factcard { border-radius: 19px; padding: 13px 14px; margin-bottom: 11px;
  background: var(--mz-stripbg); border: 0.5px solid rgba(43, 33, 24, 0.06); box-shadow: var(--mz-shadow); }
.ppl-affbars { display: flex; gap: 5px; align-items: flex-end; height: 52px; margin-top: 9px; }
.ppl-affbars i { flex: 1; border-radius: 5px 5px 2px 2px; min-height: 5px; transform: scaleY(0); transform-origin: bottom; }
.mz-play .ppl-affbars i { animation: ppl-sparkup 0.55s cubic-bezier(0.25, 0.8, 0.35, 1) forwards; animation-delay: var(--d, 200ms); }
.ppl-affax { display: flex; justify-content: space-between; font-size: 8px; font-weight: 700;
  letter-spacing: 0.06em; color: var(--mz-ink-mut); margin-top: 5px; }
.ppl-ctxbar { display: flex; align-items: center; gap: 9px; padding: 6px 0; }
.ppl-ctxbar .ppl-ctxlb { font-size: 10px; font-weight: 600; width: 97px; flex: none; }
.ppl-ctxbar .ppl-ctxtr { flex: 1; height: 8px; border-radius: 5px; background: rgba(43, 33, 24, 0.07); overflow: hidden; }
.ppl-ctxbar .ppl-ctxtr div { height: 100%; border-radius: 5px; width: 0;
