.tud-summary { border-radius: 20px; padding: 14px 15px;
  background: var(--mz-wash-lav); border: 0.5px solid rgba(43, 33, 24, 0.06); box-shadow: var(--mz-shadow-lav); }
.tud-summary-link { display: block; margin-top: 10px; font-size: 11px; font-weight: 700;
  color: var(--mz-cell-lav-ink); text-decoration: none; }
