.wkh-sm .big span { font-size: 11px; font-weight: 700; color: var(--mz-ink-soft); }
.wkh-sm .lb { font-size: 11px; font-weight: 700; }
.wkh-sm .lb.less { color: var(--mz-stch-prop-ink); }
.wkh-sm .lb.days { color: var(--mz-cell-sage-ink); }
.wkh-sm .sub { font-size: 9px; color: var(--mz-ink-soft); line-height: 1.35; }

/* seven per-day rings on the „A hét napjai" tile */
.wkh-miniring { display: flex; gap: 3.5px; margin-top: 2px; }
.wkh-miniring i { width: 15px; height: 15px; border-radius: 50%; flex: none;
  background: conic-gradient(var(--c) calc(var(--v) * 1%), var(--mz-sc-track) 0); }
.wkh-miniring i::after { content: ''; display: block; margin: 4px; width: 7px; height: 7px;
  border-radius: 50%; background: var(--mz-fh-ringhole); }
.wkh-miniring i.is-nodata { background: none; box-shadow: inset 0 0 0 1.5px var(--mz-wkh-hair); }
.wkh-miniring i.is-nodata::after { background: none; }
.wkh-miniring i.is-future { opacity: 0.45; background: none;
  box-shadow: inset 0 0 0 1.5px var(--mz-wkh-hair); }
.wkh-miniring i.is-future::after { background: none; }

/* category dots on the „Heti felfedezések" tile */
.wkh-dots { display: flex; gap: 5px; margin-left: auto; }
.wkh-dots i { width: 8px; height: 8px; border-radius: 2px; flex: none; }
.wkh-dots i.pattern    { background: var(--mz-wkh-dot-pattern); }
.wkh-dots i.fact       { background: var(--mz-wkh-dot-fact); }
.wkh-dots i.life       { background: var(--mz-wkh-dot-life); }
.wkh-dots i.memoir     { background: var(--mz-wkh-dot-memoir); }
.wkh-dots i.prediction { background: var(--mz-wkh-dot-prediction); }

/* ── the eight mini-cells: two rows of four ────────────────────────────── */
/* The two mini-cell rows are ONE unit — the prototype pairs them 5px apart (→6) inside the
   panel's own 11px rhythm, so they sit in a wrapper rather than as two panel children. */
.wkh-cellstack { display: flex; flex-direction: column; gap: 6px; }
.wkh-cellunit { font-size: 8.5px; font-weight: 700; }

/* ── loading skeleton (the prototype's .skel shimmer) ──────────────────── */
.wkh-skel { border-radius: 20px; margin-bottom: 11px;
  background: linear-gradient(100deg, rgba(43, 33, 24, 0.05) 30%, rgba(43, 33, 24, 0.11) 50%, rgba(43, 33, 24, 0.05) 70%);
  background-size: 300% 100%; animation: wkh-shim 1.2s linear infinite; }
.wkh-skel.ring { width: 97px; height: 97px; border-radius: 50%; margin: 0 auto 11px; }
@keyframes wkh-shim { to { background-position: -200% 0; } }

@media (prefers-reduced-motion: reduce) {
  .wkh-skel { animation: none; }
  .wkh-wide, .wkh-sm { transition: none; }
}

/* ═══════════════════════════════════════════════════════════════════════════
