.wka-hlrow { display: flex; gap: 6px; flex-wrap: wrap; margin-top: 11px; }
.wka-hlch { display: inline-flex; align-items: center; gap: 6px; min-height: 44px; border-radius: 11px;
  padding: 5px 9px; font-size: 10px; font-weight: 600; color: var(--text-primary); text-align: left;
  font-family: inherit; cursor: pointer; background: var(--mz-chipbg);
