.wka-hlch.tone-rose { --hc: var(--mz-cell-rose-ink); }

.wka-revfoot { display: flex; align-items: center; flex-wrap: wrap; gap: 8px; margin-top: 12px; }
.wka-chatch { display: inline-flex; align-items: center; justify-content: center; gap: 6px; min-height: 44px;
