/* 03 · kompakt hero */
.mz-edhero { border-radius: 19px; padding: 12px 14px; background: var(--mz-wash-trainhero);
  border: 0.5px solid rgba(43, 33, 24, 0.06); box-shadow: var(--mz-shadow); }
.mz-edhero-top { display: flex; align-items: center; gap: 9px; }
.mz-edhero input { width: 100%; border: none; background: transparent; font-family: inherit;
  font-size: 19px; font-weight: 700; padding: 3px 0; color: inherit; }
.mz-minighost { flex: none; border: 1px solid rgba(43, 33, 24, 0.14); background: var(--mz-stripbg);
  border-radius: 999px; padding: 5px 12px; font-family: inherit; font-size: 10px; font-weight: 700;
  color: var(--mz-ink-soft); cursor: pointer; }
.mz-confirm { margin-top: 9px; border-radius: 12px; padding: 9px 11px; background: var(--mz-cell-gold-bg);
  color: var(--mz-cell-gold-ink); font-size: 11px; line-height: 1.45; }
.mz-confirm-acts { display: flex; gap: 7px; margin-top: 8px; }

/* 03 · nap-mozaik — csempe → saját nap-oldal */
.mz-dtile { display: block; width: 100%; border-radius: 18px; padding: 11px 13px; text-align: left; font-family: inherit;
  color: var(--text-primary); cursor: pointer; border: 0.5px solid rgba(43, 33, 24, 0.06);
  background: var(--mz-wash-coral); box-shadow: 0 14px 26px -17px rgba(43, 33, 24, 0.28);
  transition: transform 0.15s cubic-bezier(0.3, 0.8, 0.4, 1.4); }
.mz-dtile:active { transform: scale(0.96); }
.mz-dtile-sage { background: var(--mz-wash-sage); }
.mz-dtile-rose { background: var(--mz-wash-rose); }
.mz-dtile-gold { background: var(--mz-wash-gold); }
.mz-dtile-warn { background: var(--mz-cell-gold-bg); }
.mz-dtile-head { display: flex; align-items: flex-start; gap: 7px; }
.mz-dtile-dl { font-size: 21px; font-weight: 700; line-height: 1; }
.mz-dtile-tt { display: block; margin-top: 3px; font-size: 9.5px; font-weight: 700; letter-spacing: 0.1em;
  text-transform: uppercase; color: var(--mz-cell-coral-ink); }
.mz-dtile-sage .mz-dtile-tt { color: var(--mz-cell-sage-ink); }
.mz-dtile-rose .mz-dtile-tt { color: var(--mz-cell-rose-ink); }
.mz-dtile-gold .mz-dtile-tt { color: var(--mz-cell-gold-ink); }
.mz-dtile-st { flex: none; font-size: 9px; font-weight: 700; border-radius: 999px; padding: 3px 8px;
  background: var(--mz-cell-coral-bg); color: var(--mz-cell-coral-ink); }
.mz-dtile-st-done { background: var(--mz-cell-sage-bg); color: var(--mz-cell-sage-ink); }
.mz-dtile-cells { display: flex; gap: 5px; margin-top: 8px; }
.mz-dtile-cell { flex: 1; text-align: center; padding: 5px 2px; border-radius: 11px;
  background: var(--mz-cellbg); }
.mz-dtile-cells b { display: block; font-size: 14px; font-weight: 600; font-variant-numeric: tabular-nums; }
.mz-dtile-cells small { font-size: 8px; font-weight: 700; letter-spacing: 0.06em; text-transform: uppercase;
  color: var(--mz-ink-mut); }
.mz-dtile-mlist { margin-top: 8px; display: grid; gap: 5px; }
.mz-dtile-ml { display: grid; grid-template-columns: 45px 1fr 17px; align-items: center; gap: 6px;
  font-size: 10px; font-weight: 700; }
.mz-dtile-ml .bar { display: block; height: 6px; border-radius: 4px; background: var(--mz-gbar-bg); overflow: hidden; }
.mz-dtile-ml .n { text-align: right; font-variant-numeric: tabular-nums; color: var(--mz-ink-soft); }
.mz-dtile-dot { width: 7px; height: 7px; border-radius: 50%; background: var(--error); flex: none; margin-top: 5px; }

/* lépés-lábléc — egy elsődleges CTA, mellette a csendes társa */
.mz-wfoot { display: flex; gap: 9px; margin-top: 14px; }
.mz-wfoot > :first-child { flex: 1; }
/* A vázlat-szerkesztő lábléce (mezo-yty6): a MesoWeekEditor `footer` slotja EGY
   elemet kap, ami a hibacsíkot/megerősítést a CTA-sor FÖLÉ teszi — a .mz-wfoot
   sorlayoutja különben egymás mellé sodorná őket. */
.mz-draftfoot { display: grid; gap: 9px; }
.mz-draftfoot-row { display: flex; gap: 9px; }
.mz-draftfoot-row > :first-child { flex: 1; }

/* ---- aktív futam oldala (#page-run, mezo-d20.15) ----
   A blokk íve kártya alsó sora, a „Heti vizsgálat" csempe mini sáv-fürtje
   (a prototípus .wmini-je ×1.18) és a „Hétfőn jön" csempe előrejelző chipjei. */
.mz-arcline { margin-top: 4px; font-size: 10px; font-weight: 600; color: var(--mz-ink-mut); }
.mz-arcline b { color: var(--mz-cell-gold-ink); }
.mz-wmini { display: flex; gap: 4px; align-items: flex-end; height: 31px; margin: 7px 0 3px; }
.mz-wmini b { flex: 1; border-radius: 4px 4px 1px 1px; min-height: 4px;
  transform: scaleY(0); transform-origin: bottom; }
.mz-play .mz-wmini b { animation: mz-growy 0.45s ease-out forwards; animation-delay: var(--d); }
@keyframes mz-growy { to { transform: scaleY(1); } }
.mz-rollchips { display: flex; flex-wrap: wrap; gap: 4px; margin-top: 7px; }
.mz-tile-note { font-size: 10px; color: var(--mz-ink-mut); margin-top: 7px; }
@media (prefers-reduced-motion: reduce) {
  .mz-wmini b, .mz-play .mz-wmini b { transform: scaleY(1); animation: none; }
}

/* live-rollover banner (week page) */
.mz-livebanner { display: flex; gap: 8px; align-items: center; border-radius: 14px; padding: 9px 11px;
  background: var(--mz-cell-sage-bg); }
.mz-livedot { width: 7px; height: 7px; border-radius: 50%; flex: none; background: var(--mz-cell-sage-ink);
  box-shadow: 0 0 6px var(--mz-cell-sage-ink); animation: mz-pulsedot 2s ease-in-out infinite; }
.mz-livebanner-title { font-size: 10px; font-weight: 700; color: var(--mz-cell-sage-ink); }
@keyframes mz-pulsedot { 0%, 100% { opacity: 1; } 50% { opacity: 0.4; } }
@media (prefers-reduced-motion: reduce) { .mz-livedot { animation: none; } }

/* derivation timeline — „Honnan a sáv · levezetés" (DerivationSteps.tsx) */
.mz-dsteps { position: relative; margin-top: 6px; }
.mz-dstep { display: flex; gap: 9px; padding: 6px 0 10px; position: relative; }
.mz-dstep + .mz-dstep::before { content: ''; position: absolute; left: 10px; top: -8px; height: 10px; width: 1.5px;
  background: rgba(43, 33, 24, 0.12); }
.mz-dnum { width: 21px; height: 21px; border-radius: 50%; flex: none; display: grid; place-items: center;
  font-size: 8.5px; font-weight: 700; color: #fff; box-shadow: 0 4px 10px -5px rgba(43, 33, 24, 0.5); }
.mz-dnum-baseline { background: var(--mz-ink-mut); }
.mz-dnum-custom { background: var(--mz-dstep-custom); }
.mz-dnum-final { background: var(--mz-gold-bar); }
.mz-dt { font-size: 8.5px; font-weight: 700; letter-spacing: 0.12em; text-transform: uppercase; color: var(--mz-ink-soft); margin-top: 3px; }
.mz-dcells { display: flex; gap: 4px; margin-top: 5px; flex-wrap: wrap; }
.mz-dcell { flex: 1; text-align: center; padding: 4px 2px; border-radius: 9px; background: var(--mz-cellbg); min-width: 40px; }
.mz-dcell b { display: block; font-size: 12px; font-weight: 600; font-variant-numeric: tabular-nums; }
.mz-dcell small { font-size: 7px; font-weight: 700; letter-spacing: 0.06em; text-transform: uppercase; color: var(--mz-ink-mut); }
.mz-dcell.hot { background: var(--mz-cell-gold-bg); }
.mz-dcell.hot b { color: var(--mz-cell-gold-ink); }
.mz-dadj { display: flex; gap: 7px; align-items: flex-start; margin-top: 5px; }
.mz-dadj .mz-ico { font-size: 11px; flex: none; }
.mz-dadj .mz-tx { flex: 1; font-size: 11px; line-height: 1.4; color: var(--text-primary); }
.mz-eff { font-size: 8.5px; font-weight: 700; border-radius: 999px; padding: 2px 7px; flex: none; white-space: nowrap; }
.mz-confbar { height: 3px; border-radius: 2px; background: var(--mz-cellbg); overflow: hidden; margin-top: 6px; }
.mz-confbar > div { height: 100%; background: var(--mz-gold-bar); }
/* ===== Életcél-rendszer (mezo-iizd) — PERMAH tokens + hub/goal-page family =====
   The surface hexes themselves live as --lg-*-dc/dw/dw2 tokens in :root (mezo-d20.1.5's
   "Mozaik section stays hex-free outside :root" guard) — these rules just alias them into
   the local --dc/--dw/--dw2/--ds names the .lg-* component rules below read. */
.lg-d-p { --dc: var(--lg-p-dc); --dw: var(--lg-p-dw); --dw2: var(--lg-p-dw2); --ds: rgba(201,150,46,0.45); }
.lg-d-e { --dc: var(--lg-e-dc); --dw: var(--lg-e-dw); --dw2: var(--lg-e-dw2); --ds: rgba(93,79,160,0.4); }
.lg-d-r { --dc: var(--lg-r-dc); --dw: var(--lg-r-dw); --dw2: var(--lg-r-dw2); --ds: rgba(142,63,111,0.35); }
.lg-d-m { --dc: var(--lg-m-dc); --dw: var(--lg-m-dw); --dw2: var(--lg-m-dw2); --ds: rgba(216,72,31,0.35); }
.lg-d-a { --dc: var(--lg-a-dc); --dw: var(--lg-a-dw); --dw2: var(--lg-a-dw2); --ds: rgba(78,143,184,0.4); }
.lg-d-h { --dc: var(--lg-h-dc); --dw: var(--lg-h-dw); --dw2: var(--lg-h-dw2); --ds: rgba(110,139,94,0.45); }
.lg-hero { display: flex; gap: 14px; align-items: center; padding: 13px 15px; border-radius: 21px;
  background: linear-gradient(140deg, var(--lg-hero-wash), var(--lg-white) 72%); border: 0.5px solid var(--lg-hairline);
  box-shadow: 0 18px 32px -16px rgba(43,33,24,0.32), inset 0 1px 0 var(--lg-inset-hi); }
.lg-ring { width: 94px; height: 94px; position: relative; flex: none; display: grid; place-items: center; }
.lg-ring svg { position: absolute; inset: 0; transform: rotate(-90deg); }
.lg-ring .arc { fill: none; stroke: var(--dc); stroke-width: 5.5; stroke-dasharray: 27.4 161.1; opacity: 0.2; }
.lg-ring .arc.live { opacity: 1; stroke-width: 8; }
/* A REJTETT kezdőállapot az arming osztályhoz kötve — a `.rise` háza mintája
   (prototype.css `.mz-play .rise`). Feltétel nélküli rejtés esetén a vissza-navigálás
   (`EntranceGroup` szándékosan nem arm-ol pop érkezésnél, mezo-kuwj) az ívet/pöttyöt
   véglegesen eltüntetné — pontosan ez volt a mezo-7eq0 hibája. */
.mz-play .lg-ring .arc { stroke-dasharray: 0 188.5; animation: lg-arcin 0.6s cubic-bezier(0.25,0.8,0.35,1) forwards; animation-delay: calc(260ms + var(--i) * 70ms); }
@keyframes lg-arcin { to { stroke-dasharray: 27.4 161.1; } }
.lg-ring .c { text-align: center; line-height: 1; }
.lg-ring .c b { font-size: 32px; font-weight: 200; display: block; letter-spacing: -0.02em; }
.lg-ring .c small { font-size: 7.5px; font-weight: 800; letter-spacing: 0.12em; text-transform: uppercase; color: var(--text-muted, var(--text-muted)); }
.lg-dimband { display: flex; gap: 5px; flex-wrap: wrap; }
.lg-dimchip { display: inline-flex; align-items: center; gap: 5px; border-radius: 999px; padding: 4px 10px 4px 7px;
  font-size: 9px; font-weight: 800; letter-spacing: 0.06em; text-transform: uppercase; background: var(--dw); color: var(--dc); border: none; font-family: inherit; }
.lg-dimchip i { width: 8px; height: 8px; border-radius: 50%; background: var(--dc); flex: none; }
.lg-dimchip.empty { background: var(--lg-chipbg); color: var(--text-muted); }
.lg-dimchip.empty i { background: var(--lg-hairline-2); }
.lg-tile { background: linear-gradient(150deg, var(--dw), var(--dw2)) !important; box-shadow: 0 14px 26px -14px var(--ds), 0 2px 5px rgba(43,33,24,0.04), inset 0 1px 0 var(--lg-inset-hi) !important; }
.lg-tile .mz-eyebrow { color: var(--dc); }
.lg-tile .nm { font-size: 13px; font-weight: 700; text-align: left; }
.lg-arrow { display: inline-flex; align-items: baseline; gap: 4px; line-height: 1; font-variant-numeric: tabular-nums; }
.lg-arrow .g { font-size: 26px; font-weight: 300; }
.lg-arrow .v { font-size: 14px; font-weight: 600; }
.lg-arrow.up { color: var(--lg-arrow-up); } .lg-arrow.flat { color: var(--text-secondary); } .lg-arrow.down { color: var(--lg-ink-amber); } .lg-arrow.none { color: var(--text-muted); }
.lg-wk7 { display: flex; gap: 5px; align-items: center; }
.lg-wk7 i { width: 11px; height: 11px; border-radius: 50%; flex: none; background: var(--lg-dot-idle); }
.lg-wk7 i.h { background: linear-gradient(135deg, var(--lg-ok-ink2), var(--lg-ok-ink)); }
.lg-wk7 i.p { background: linear-gradient(135deg, var(--lg-wk7-p2), var(--lg-dot-partial2)); }
.lg-wk7 i.m { background: var(--lg-dot-idle); }
.lg-wk7 i.n { background: transparent; border: 1px dashed rgba(43,33,24,0.28); }
.mz-play .lg-wk7 i { transform: scale(0); animation: lg-dotpop 0.35s cubic-bezier(0.3,1.4,0.5,1) forwards; animation-delay: calc(var(--d, 0ms) + 280ms + var(--i) * 45ms); }
@keyframes lg-dotpop { to { transform: scale(1); } }
.lg-wk7 .lbl { font-size: 8.5px; font-weight: 700; color: var(--text-muted); margin-left: auto; }
/* Hét/Hónap chips + the 28-cell heatmap row (Task 9, mezo-iizd.5, prototype celok.html
   #page-g1 `.chiprow`/`.fchip`/`.hm` — reusing the `.lg-wk7 i.*` status colors so the two
   views read as the same data at two grains). */
.lg-chiprow { display: flex; gap: 8px; align-items: center; margin-bottom: 8px; }
.lg-fchip { border: 1px solid var(--lg-hairline-2); background: var(--lg-white); border-radius: 999px; padding: 4px 11px; font-size: 9px; font-weight: 700; color: var(--text-secondary); font-family: inherit; cursor: pointer; }
.lg-fchip.on { background: var(--lg-fchip-on); border-color: var(--dv-coral); color: var(--lg-ink-coral); }
.lg-fchip:focus-visible { outline: 2px solid var(--lg-ink-coral); outline-offset: 2px; }
.lg-hm { display: grid; grid-template-columns: repeat(7, 1fr); gap: 3px; margin-top: 8px; }
.lg-hm i { height: 12px; border-radius: 3px; background: var(--lg-dot-idle); }
.lg-hm i.h { background: var(--lg-ok-ink2); }
.lg-hm i.p { background: var(--lg-wk7-p2); }
.lg-hm i.m { background: var(--lg-dot-idle); }
.lg-hm i.n { background: transparent; border: 1px dashed var(--lg-hairline-2); }
.lg-parkrow { display: flex; align-items: center; gap: 10px; padding: 10px 13px; border-radius: 17px; width: 100%; text-align: left;
  background: color-mix(in srgb, var(--lg-white) 55%, transparent); border: 0.5px dashed var(--lg-hairline-2); }
/* Two real, focusable buttons live inside the row (mezo-iizd.1 review fix): a nested
   interactive element inside a <button> is both invalid HTML and keyboard-unreachable, so
   the row itself is a plain (non-interactive) div and `.lg-parkrow-nav` + `.act` are its
   two sibling <button>s. `.lg-parkrow-nav` reproduces the icon+text row the old single
   button's first two children had; `button { background:none;border:none;cursor:pointer;
   font-family:inherit;color:inherit; }` (line 788) already resets both. */
.lg-parkrow-nav { display: flex; align-items: center; gap: 10px; flex: 1; min-width: 0; padding: 0; text-align: left; }
.lg-parkrow .nm { font-size: 12px; font-weight: 600; color: var(--text-secondary); }
.lg-parkrow .sb { font-size: 9.5px; color: var(--text-muted); }
.lg-parkrow .act { margin-left: auto; font-size: 10px; font-weight: 700; color: var(--lg-ink-coral); border: 1px solid var(--lg-hairline-2); background: var(--lg-white); border-radius: 999px; padding: 4px 11px; flex: none; }
@media (prefers-reduced-motion: reduce) {
  .mz-play .lg-ring .arc { stroke-dasharray: 27.4 161.1; animation: none; }
  .mz-play .lg-wk7 i { transform: none; animation: none; }
}

/* Goal detail page (Task 10, mezo-iizd.1, prototype celok.html #page-g1): pillar card,
   Miért · ha–akkor card, status action row. */
.lg-pillar { border-radius: 18px; padding: 12px 14px 13px; margin-bottom: 10px; background: var(--lg-white); border: 0.5px solid var(--lg-hairline);
  box-shadow: 0 14px 26px -16px rgba(43,33,24,0.3), inset 0 1px 0 var(--lg-inset-hi); }
.lg-pillar.washed { background: linear-gradient(150deg, var(--dw), var(--lg-white) 72%); }
.lg-pillar.off { opacity: 0.55; }
.lg-pillar .ph { display: flex; align-items: center; gap: 8px; }
.lg-pillar .ph .nm { font-size: 13px; font-weight: 700; }
.lg-kind { font-size: 8px; font-weight: 800; letter-spacing: 0.1em; text-transform: uppercase; color: var(--text-secondary); background: var(--lg-hairline); border-radius: 6px; padding: 2px 7px; flex: none; }
.lg-kind.link { color: var(--lg-link-ink); background: var(--lg-link-bg); }
.lg-pillar .val { display: flex; align-items: baseline; gap: 7px; margin-top: 7px; }
.lg-pillar .val b { font-size: 21px; font-weight: 200; letter-spacing: -0.02em; font-variant-numeric: tabular-nums; }
.lg-pillar .val small { font-size: 10px; color: var(--text-secondary); }
.lg-why { border-radius: 18px; padding: 12px 14px; margin-bottom: 10px; background: linear-gradient(140deg, var(--lg-why-bg), var(--lg-white) 75%); border: 0.5px solid var(--lg-hairline); box-shadow: 0 12px 22px -15px rgba(43,33,24,0.3); }
.lg-why .q { font-family: var(--ff-display, "Fraunces", serif); font-style: italic; font-size: 13.5px; font-weight: 500; }
.lg-ifthen { display: flex; gap: 8px; align-items: flex-start; padding: 7px 0; font-size: 11px; }
.lg-ifthen + .lg-ifthen { border-top: 0.5px solid var(--lg-hairline); }
.lg-ifthen .ha { flex: none; width: 46px; text-align: center; font-size: 7.5px; font-weight: 800; letter-spacing: 0.12em; color: var(--lg-ink-coral); background: rgba(168,74,38,0.1); border-radius: 6px; padding: 3px 0; margin-top: 2px; }
.lg-ifthen .ha.akkor { color: var(--lg-arrow-up); background: rgba(110,139,94,0.16); }
.lg-actrow { display: flex; gap: 8px; margin: 6px 0 10px; }
.lg-actrow button { flex: 1; border: 1px solid var(--lg-hairline-2); background: var(--lg-white); border-radius: 999px; padding: 8px 0; font-size: 11px; font-weight: 700; color: var(--text-secondary); font-family: inherit; cursor: pointer; }

/* ===== Cél-varázsló (Task 11, mezo-iizd.1, prototype celok.html #page-wiz) =====
   Progress rail · fcards · Keret frame-nudge · Pillérek toggle cards · Ha–akkor
   plan editor · Összegzés summary pills. Reuses the `.lg-*` family above. */
.lg-wprog { display: flex; gap: 5px; margin-bottom: 6px; }
.lg-wprog i { flex: 1; height: 4px; border-radius: 2px; background: var(--lg-dot-idle); }
.lg-wprog i.f { background: var(--gradient-cta); }
.lg-fcard { background: var(--lg-white); border-radius: 16px; padding: 11px 13px 12px; margin-bottom: 9px; border: 0.5px solid var(--lg-hairline); box-shadow: 0 10px 20px -14px rgba(43,33,24,0.28); }
.lg-flabel { font-size: 8.5px; font-weight: 700; letter-spacing: 0.16em; text-transform: uppercase; color: var(--text-muted); margin-bottom: 5px; display: block; }
.lg-fin { width: 100%; border: 1px solid var(--lg-dot-idle); border-radius: 11px; padding: 8px 11px; font-family: inherit; font-size: 13px; background: var(--lg-input-bg); color: var(--text-primary); resize: none; }
.lg-frame { border-radius: 16px; padding: 11px 13px; margin: 8px 0; background: linear-gradient(140deg, var(--lg-frame-warn), var(--lg-frame-warn2)); box-shadow: 0 12px 22px -14px rgba(181,126,20,0.45); }
.lg-frame.ok { background: linear-gradient(140deg, var(--lg-h-dw), var(--lg-ok-wash2)); box-shadow: 0 12px 22px -14px rgba(110,139,94,0.45); }
.lg-frame .lb { font-size: 11px; font-weight: 800; color: var(--lg-ink-amber); } .lg-frame.ok .lb { color: var(--lg-arrow-up); }
.lg-frame p { font-size: 11px; color: var(--text-secondary); margin-top: 4px; }
.lg-pilcard { display: flex; align-items: center; gap: 10px; border-radius: 16px; padding: 10px 12px; margin-bottom: 8px; background: var(--lg-white); border: 1.5px solid var(--lg-hairline); box-shadow: 0 10px 20px -14px rgba(43,33,24,0.28); }
.lg-pilcard.on { border-color: var(--lg-ok-ink2); background: linear-gradient(140deg, var(--lg-ok-wash), var(--lg-white) 70%); }
.lg-pilcard.off { opacity: 0.5; }
.lg-pilcard b { font-size: 12.5px; display: block; } .lg-pilcard small { font-size: 10px; color: var(--text-secondary); display: block; }
.lg-togg { width: 38px; height: 22px; border-radius: 999px; background: var(--lg-hairline-2); position: relative; flex: none; border: none; padding: 0; cursor: pointer; }
.lg-togg::after { content: ''; position: absolute; top: 2px; left: 2px; width: 18px; height: 18px; border-radius: 50%; background: var(--lg-white); transition: left 0.15s ease; }
.lg-togg.on { background: linear-gradient(135deg, var(--lg-ok-ink2), var(--lg-ok-ink)); } .lg-togg.on::after { left: 18px; }
.lg-plan { border-radius: 16px; padding: 10px 11px 9px; margin-bottom: 8px; background: var(--lg-white); border: 1.5px solid var(--lg-hairline); }
.lg-plan.on { border-color: var(--lg-ok-ink2); background: linear-gradient(140deg, var(--lg-ok-wash), var(--lg-white) 62%); }
.lg-plan.own { border-style: dashed; }
.lg-prow { display: flex; gap: 8px; align-items: flex-start; } .lg-prow + .lg-prow { margin-top: 5px; padding-top: 6px; border-top: 0.5px solid var(--lg-hairline); }
.lg-ptxt { flex: 1; min-width: 0; border: none; background: transparent; font-family: inherit; font-size: 12px; line-height: 1.4; color: var(--text-primary); resize: none; padding: 2px 0; }
.lg-pfoot { display: flex; align-items: center; gap: 6px; margin-top: 7px; padding-top: 6px; border-top: 0.5px solid var(--lg-hairline); font-size: 9.5px; font-weight: 700; color: var(--text-secondary); }
.lg-addrow { width: 100%; border: 1.2px dashed var(--lg-hairline-2); background: none; border-radius: 12px; padding: 9px 0; font-size: 11px; font-weight: 700; color: var(--text-secondary); cursor: pointer; font-family: inherit; margin-top: 4px; }
.lg-aiwait { display: flex; align-items: center; gap: 8px; padding: 12px; border-radius: 15px; background: var(--lg-inset-hi); margin-bottom: 8px; font-size: 11px; color: var(--text-secondary); }
.lg-sumpil { display: flex; align-items: center; gap: 10px; padding: 9px 12px; margin-bottom: 6px; border-radius: 15px; background: var(--lg-white); border: 0.5px solid var(--lg-hairline); }
.lg-sumpil b { font-size: 12px; display: block; } .lg-sumpil small { font-size: 10px; color: var(--text-secondary); display: block; }

/* Jelek-oldal (mezo-iizd.7, prototype celok.html #page-jelek): forrás-sorok él/alszik ponttal. */
.lg-siglist { list-style: none; margin: 0 0 10px; padding: 0; }
.lg-sig { display: flex; align-items: center; gap: 10px; padding: 9px 12px; margin-bottom: 7px; border-radius: 16px;
  background: var(--lg-white); border: 0.5px solid var(--lg-hairline); box-shadow: 0 10px 20px -14px rgba(43,33,24,0.28); }
.lg-sig.off { opacity: 0.55; }
.lg-sig .grow { flex: 1; min-width: 0; }
.lg-sig b { font-size: 12.5px; display: block; }
.lg-sig small { font-size: 10px; color: var(--text-secondary); display: block; }
.lg-sig i.live { width: 8px; height: 8px; border-radius: 50%; flex: none; background: linear-gradient(135deg, var(--lg-ok-ink2), var(--lg-ok-ink)); }
.lg-sig i.dead { width: 8px; height: 8px; border-radius: 50%; flex: none; background: var(--lg-hairline-2); }
.lg-sigchips { display: flex; flex-wrap: wrap; gap: 4px; margin-top: 4px; }
.lg-sigchips span { font-size: 8.5px; font-weight: 700; color: var(--text-secondary); background: var(--lg-hairline); border-radius: 6px; padding: 2px 6px; }
.lg-sighead { display: flex; align-items: baseline; gap: 8px; margin: 10px 2px 6px; }
.lg-sighead .cnt { margin-left: auto; font-size: 9.5px; color: var(--text-muted); }
.lg-sighint { font-size: 11px; color: var(--text-secondary); margin: 0 2px 4px; }

/* Nap-mozaik „Célok · ma" csempe (mezo-iizd.9, prototípus celok-body.html #page-nap .gtile).
   A dimenzió-mosást a `.lg-d-*` osztály adja (ugyanaz a --dw/--dw2/--ds hármas, amit a
   `.lg-tile` is olvas), így a csempe a Célok hub tile-jaival egy nyelvet beszél. */
.lg-gtile { background: linear-gradient(150deg, var(--dw), var(--dw2)) !important;
  box-shadow: 0 14px 26px -14px var(--ds), 0 2px 5px rgba(43,33,24,0.04), inset 0 1px 0 var(--lg-inset-hi) !important; }
.lg-gtile .mz-eyebrow { color: var(--dc); display: inline-flex; align-items: center; gap: 5px; }
.lg-gtile .mz-eyebrow i { width: 6px; height: 6px; border-radius: 50%; background: var(--dc); flex: none; }
.lg-gtile-row { display: flex; align-items: center; gap: 8px; margin-top: 4px; }
.lg-gtile .lg-arrow .v { font-size: 22px; font-weight: 200; letter-spacing: -0.02em; }
.lg-gtile .lg-arrow .v small { font-size: 11px; font-weight: 500; color: var(--text-secondary); }

/* Cél-ütközés mondat (mezo-iizd.9): a backend findConflicts sorai. Figyelmeztetés, nem tiltás
   (spec D7: a konfliktus companion-mondat, nem kemény korlát) — ezért borostyán, nem piros. */
.lg-conflict { display: flex; align-items: flex-start; gap: 8px; margin: 0 0 8px; padding: 10px 12px;
  border-radius: 16px; font-size: 11.5px; line-height: 1.45; color: var(--text-secondary);
  background: linear-gradient(140deg, var(--lg-frame-warn), var(--lg-frame-warn2));
  box-shadow: 0 12px 22px -14px rgba(181,126,20,0.45); }
.lg-conflict svg { flex: none; margin-top: 1px; }

/* Heti hub cél-kártya + goalchip (mezo-iizd.9, prototípus celok-body.html #page-heti .qcard/
   .wgrow/.goalchip). A `.lg-goalchip` a Growth skill-sorban is ezt a nyelvet viseli (mezo-iizd.12).
   SZABÁLY a chip TARTALMÁRA (mezo-9r85, 4. tétel): a chip a (cél, dimenzió) pár azon felét
   nevezi meg, amit a KÖRNYEZŐ SOR nem hordoz. A Heti sor `nm`-je már kiírja a cél címét → ott
   a chip a DIMENZIÓ-címke (WeekGoalsCard). Egy skill-sor és az Én-hub heroja nem hordoz
   cél-identitást → ott a chip a CÉL CÍME (SkillBandCard, EnHubPage). Egységesítés a Heti sorban
   duplán íratná ki a címet. Negyedik fogyasztó: ezt a szabályt alkalmazd, ne érmét dobj. */
.lg-wcard { border-radius: 18px; padding: 4px 12px 10px; margin-bottom: 10px; background: var(--mz-stripbg);
  border: 0.5px solid var(--lg-hairline); box-shadow: 0 14px 26px -16px rgba(43,33,24,0.3); }
.lg-wcard-top { display: flex; align-items: baseline; gap: 8px; padding: 10px 2px 4px; }
.lg-wcard-cnt { margin-left: auto; font-size: 9.5px; color: var(--text-muted); }
.lg-wgrow { display: flex; gap: 10px; align-items: flex-start; padding: 8px 0; }
.lg-wgrow + .lg-wgrow { border-top: 0.5px solid var(--lg-hairline); }
.lg-wgrow .grow { flex: 1; min-width: 0; }
.lg-wgrow .nm { font-size: 12.5px; font-weight: 700; display: flex; align-items: center; gap: 6px; flex-wrap: wrap; }
.lg-wgrow .x { font-size: 11px; color: var(--text-secondary); margin-top: 2px; line-height: 1.4; }
.lg-goalchip { display: inline-flex; align-items: center; gap: 4px; border-radius: 999px; padding: 2px 8px 2px 6px;
  font-size: 8.5px; font-weight: 700; color: var(--dc, var(--text-secondary)); background: var(--dw, var(--lg-hairline)); flex: none; }
.lg-goalchip i { width: 6px; height: 6px; border-radius: 50%; background: var(--dc, var(--text-muted)); flex: none; }
.lg-wcard-cta { width: 100%; margin-top: 6px; border: 1px solid var(--lg-hairline-2); background: var(--mz-stripbg);
  border-radius: 999px; padding: 8px 0; font-size: 11px; font-weight: 700; color: var(--text-secondary); font-family: inherit; cursor: pointer; }

/* Lezárt cél sora (mezo-iizd.4): a parkolt sor nyelve, halványabban — egy kész cél emlék,
   nem tennivaló. A pipa a jobb szélen a lezárás egyetlen jele. */
.lg-donerow { opacity: 0.72; }
.lg-donetick { margin-left: auto; flex: none; font-size: 12px; font-weight: 700; color: var(--lg-arrow-up); }

/* Én-hub életcél-hero (mezo-iizd.4): az `.enh-goalcard` váza, súly-track nélkül — a helyére
   a célok dimenzió-chipjei kerülnek. */
.enh-lgcard .mz-eyebrow { display: inline-flex; align-items: center; gap: 5px; }
.enh-lgdims { display: flex; flex-wrap: wrap; gap: 5px; margin: 8px 0 10px; }

/* ============================================================
   Today · maradék sheet-nyelv (mezo-e26w heritage → mezo-d20.9.1)
   Ez a szekció EGYKOR a Mai oldal teljes „inset grouped list" lapnyelvét vitte
   (napszak-váltó, hero, statisztika-doboz, CTA, sorok, Életjel-ringek,
   NeedRingSheet, betöltő váz). A Design 2.0 takarításával (mezo-d20.9.1) a
   TodayPage és minden nézet-komponense kikerült a fából, így az a CSS is —
   ami itt maradt, az KIZÁRÓLAG a két túlélő felület nyelve:
     • `MezoMessagesSheet` (`.td-sheet-h`, `.td-thread`, `.td-daysep`,
       `.td-msg`, `.td-av`, `.td-bub*`) — a NapHubPage nyitja,
     • `DailyQuestsSheet` + `DailyQuestsCard` (`.td-quest-*`, plusz a
       `.daily-quests-card .td-quest-list` felülírás).
   Minden vízszintes él továbbra is a globális `--sp-4` DS-tokenből jön,
   elemenként — nincs feature-scope-olt custom property (a `--td-gut` csapdája
   miatt). A `todayCssTokens.test.ts`, ami ezt az invariánst őrizte, a Today
   view-réteggel együtt megszűnt; a `--mz-*` tokenekre a `mozaikCssTokens.test.ts`
   stíluslap-szintű ellenőrzése maradt (mezo-sm21).
   ============================================================ */

.td-av { flex: 0 0 auto; width: 26px; height: 26px; border-radius: 50%; position: relative;
         background: var(--gradient-cta); color: var(--text-inverse); display: grid;
         place-items: center; font-size: 12px; box-shadow: 0 2px 6px rgba(255, 91, 54, .30); }

/* ── Napi küldetések sheet ── */
.td-quest-sheet { max-height: 76%; overflow-y: auto; }
.td-quest-summary { display: flex; justify-content: space-between; padding: 0 var(--sp-4) 8px;
                    font-size: 12.5px; color: var(--text-muted); }
.td-quest-progress { height: 5px; margin: 0 var(--sp-4) 8px; overflow: hidden;
                     border-radius: var(--r-full); background: var(--surface-recess); }
.td-quest-progress > span { display: block; height: 100%; border-radius: inherit;
                            background: var(--accent-base); transition: width var(--duration-fast) var(--ease-out); }
.td-quest-list { margin: 0 var(--sp-4); border-top: .5px solid var(--divider); }
.daily-quests-card .td-quest-list { margin: 0; }
.td-quest-row { display: grid; grid-template-columns: 26px minmax(0, 1fr) auto; gap: 10px;
                padding: 13px 0; border-bottom: .5px solid var(--divider); }
.td-quest-state { width: 26px; height: 26px; display: grid; place-items: center;
                  border-radius: var(--r-full); background: var(--accent-soft); color: var(--accent-deep);
                  font-size: 13px; font-weight: 700; }
.td-quest-row.is-completed .td-quest-state { background: var(--success-bg); color: var(--success-hover); }
.td-quest-row.is-completed .td-quest-copy { opacity: .65; }
.td-quest-row.is-expired .td-quest-copy, .td-quest-row.is-rerolled .td-quest-copy { opacity: .45; }
.td-quest-copy b { display: block; font-size: 13.5px; color: var(--text-primary); }
.td-quest-copy > span { display: block; margin-top: 3px; font-size: 12px; line-height: 1.35;
                        color: var(--text-muted); }
.td-quest-xp { white-space: nowrap; color: var(--accent-deep); font-size: 12px; font-weight: 700; }
.td-quest-actions { display: flex; flex-wrap: wrap; gap: 7px; margin-top: 8px; }
.td-quest-actions button { min-height: 44px; padding: 0 13px; border: 0; border-radius: var(--r-full);
                           background: var(--surface-recess); color: var(--text-primary);
                           font-family: var(--ff-body); font-size: 12px; font-weight: 600; cursor: pointer; }
.td-quest-actions button.is-primary { background: var(--text-primary); color: var(--surface-card); }
.td-quest-actions button:disabled { opacity: .45; cursor: default; }
.td-quest-foot { padding: 12px var(--sp-4) 4px; text-align: center;
                 font-size: 12px; color: var(--text-muted); }
.td-quest-empty { padding: 18px var(--sp-4) 24px; text-align: center;
                  font-size: 13px; color: var(--text-muted); }

/* ── MezoMessagesSheet ── */
.td-sheet-h { display: flex; align-items: center; padding: 4px 16px 12px;
              border-bottom: .5px solid var(--divider); }
.td-sheet-h h2 { font-family: var(--ff-body); font-size: 16.5px; font-weight: 700;
                 letter-spacing: -.02em; color: var(--text-primary); }
.td-sheet-h button { margin-left: auto; font-family: var(--ff-body); font-size: 15px; font-weight: 600;
                     color: var(--primary-hover); border: 0; background: none; cursor: pointer;
                     padding: 10px 0 10px 12px; }
.td-thread { padding: 14px 0 0; overflow-y: auto; max-height: 62vh; }
.td-daysep { text-align: center; font-family: var(--ff-body); font-size: 11px; font-weight: 700;
             letter-spacing: .07em; text-transform: uppercase; color: var(--text-disabled);
             margin: 2px 0 12px; }
.td-msg { display: flex; gap: 9px; align-items: flex-end; padding: 0 16px 14px; }
.td-msg .td-av { margin-bottom: 2px; }
.td-bub { flex: 1; min-width: 0; background: var(--surface-card); border: .5px solid var(--divider);
          border-radius: 20px; border-bottom-left-radius: 6px; padding: 11px 14px 12px;
          box-shadow: 0 1px 2px rgba(43, 33, 24, .05); }
.td-bub-h { display: flex; align-items: baseline; gap: 6px; margin-bottom: 5px; }
.td-bub-n { font-family: var(--ff-body); font-size: 12.5px; font-weight: 700;
            color: var(--primary-deep); letter-spacing: -.005em; }
.td-bub-t { font-family: var(--ff-body); font-size: 11.5px; color: var(--text-muted);
            font-variant-numeric: tabular-nums; }
.td-bub-x { font-family: var(--ff-body); font-size: 14.5px; line-height: 1.47;
            color: var(--text-primary); margin: 0; letter-spacing: -.005em; }
.td-bub-x + .td-bub-x { margin-top: 9px; }
.td-bub-refs { display: flex; flex-wrap: wrap; gap: 5px; margin-top: 10px; }
.td-bub-meta { font-family: var(--ff-body); font-size: 10.5px; font-weight: 700; letter-spacing: .06em;
               text-transform: uppercase; color: var(--text-disabled); margin-top: 9px; }

/* ── Értesítés-feed oldal (mezo-nol0) ────────────────────────────────────────
   A /me/ertesitesek teljes oldala. A családi tint-paletta (.nf-ico.*) és a .nf-dot
   fentebb, a törölt dropdown-panelből kiskópolva él — itt csak a sor-recept van. */
.nf-page .nf-daylabel {
  font: 800 10.5px/1 var(--ff-body); letter-spacing: .6px; text-transform: uppercase;
  color: var(--text-muted); padding: 14px 2px 6px;
}
.nf-page .nf-group { display: flex; flex-direction: column; }
.nf-page .nf-row {
  display: flex; gap: 10px; align-items: flex-start; position: relative;
  width: 100%; padding: 11px 12px 11px 18px; text-align: left; cursor: pointer;
  background: var(--surface-card); border: 1px solid var(--divider); border-radius: var(--r-lg);
}
.nf-page .nf-row + .nf-row { margin-top: 7px; }
/* A kiemelés a KÁRTYÁRA komponál, nem a semmire. A szabály a törölt dropdown-panelből jött, ahol
   egy átlátszatlan kártya-hátterű panel fölött ült; egy `MozaikPage`-en a `transparent` alap az
   oldal-vásznat engedte át, így az olvasatlan sor a kártyák oszlopában LYUKNAK látszott — pont
   fordítva, mint amit a nyitáskori pillanatkép egész gépezete meg akar őrizni. */
.nf-page .nf-row.unread { background: color-mix(in srgb, var(--primary-base) 8%, var(--surface-card)); }
.nf-page .nf-txt { min-width: 0; flex: 1; display: block; }
.nf-page .nf-t { display: block; font: 700 12.5px/1.25 var(--ff-body); color: var(--text-primary); }
.nf-page .nf-x {
  display: -webkit-box; -webkit-line-clamp: 2; -webkit-box-orient: vertical; overflow: hidden;
  font: 400 11.5px/1.4 var(--ff-body); color: var(--text-secondary); margin-top: 2px;
}
.nf-page .nf-time { font: 600 10px/1 var(--ff-body); color: var(--text-muted); flex-shrink: 0; margin-top: 2px; white-space: nowrap; }

/* ── Receptműhely (mezo-92pb) ────────────────────────────────────────────────
   A /fuel/recipes/muhely vászon-first oldal saját recept-nyelve
   (docs/design_2.0/prototypes/receptmuhely.html). Csak az a néhány szabály él itt,
   amit inline stílussal nem lehet: az arany diff-villanás keyframe-je, a kcal-forrás
   csík és a dokkolt chat sáv. A többi a Mozaik/logflow osztályokból jön. */
.wsh-ing { position: relative; overflow: hidden; }
.wsh-ing.diff::after {
  content: ''; position: absolute; inset: 0; border-radius: inherit; pointer-events: none;
  background: linear-gradient(150deg, color-mix(in srgb, var(--dv-amber) 32%, transparent),
                                      color-mix(in srgb, var(--dv-amber) 10%, transparent));
  box-shadow: inset 0 0 0 1.2px color-mix(in srgb, var(--dv-amber) 55%, transparent);
  animation: wsh-difffade 2.6s ease-out forwards;
}
@keyframes wsh-difffade { 0%, 55% { opacity: 1; } 100% { opacity: 0; } }

.wsh-kbar { display: flex; height: 9px; border-radius: 999px; overflow: hidden; margin-top: 9px; }
.wsh-kbar i { display: block; transition: width 0.5s cubic-bezier(0.25, 0.8, 0.35, 1); }
.wsh-kbar .kp { background: var(--coral); }
.wsh-kbar .kc { background: var(--dv-amber); }
.wsh-kbar .kf { background: var(--lav); }
.wsh-klegend { display: flex; gap: 10px; margin-top: 5px; font-size: 8.5px; color: var(--text-tertiary); }
.wsh-klegend b { font-variant-numeric: tabular-nums; font-weight: 700; color: var(--text-secondary); }
.wsh-klegend .sw { display: inline-block; width: 7px; height: 7px; border-radius: 3px; margin-right: 3px; vertical-align: -1px; }

/* A mentés-sáv + a dokk a telefon-képernyőre portálódik (a .recipe-save-bar rendje),
   nem a görgő tartalomba: a chat és a mentés mindig kéznél van, akármeddig nő a vászon. */
.wsh-bottom {
  position: absolute; left: 0; right: 0;
  bottom: 92px;   /* a lebegő tab-bar kapszula fölött */
  z-index: 45;    /* tab-bar (40) fölött, sheet-ek (200+) alatt */
  display: flex; flex-direction: column; gap: 8px;
  padding: 10px 14px 10px;
  background: var(--canvas);
  border-top: 1px solid var(--border-subtle);
}
@media (max-width: 519px), (display-mode: standalone), (display-mode: fullscreen), (display-mode: minimal-ui) {
  .wsh-bottom { bottom: calc(88px + env(safe-area-inset-bottom)); }
}
.wsh-dock { display: flex; flex-direction: column; gap: 6px; }
.wsh-presets { display: flex; gap: 5px; overflow-x: auto; scrollbar-width: none; padding: 2px; }
.wsh-presets::-webkit-scrollbar { display: none; }
.wsh-pchip {
  flex: none; cursor: pointer; font-family: inherit; font-size: 9px; font-weight: 700;
  color: var(--lav-deep); background: var(--surface-card); border-radius: 999px; padding: 6px 11px;
  border: 1px solid color-mix(in srgb, var(--lav) 30%, transparent);
}
.wsh-pchip.on { background: var(--mz-tone-lav); box-shadow: inset 0 0 0 1.2px var(--lav-deep); }
.wsh-last {
  display: flex; align-items: center; gap: 7px; width: 100%; text-align: left; cursor: pointer;
  background: var(--surface-card); border: 1px solid var(--border-subtle); border-radius: 13px; padding: 7px 10px;
}
.wsh-last .tx {
  flex: 1; min-width: 0; font-size: 10.5px; color: var(--text-secondary);
  display: -webkit-box; -webkit-line-clamp: 2; -webkit-box-orient: vertical; overflow: hidden;
}
.wsh-cfield {
  flex: 1; display: flex; align-items: center; gap: 6px; background: var(--surface-card);
  border-radius: 999px; padding: 5px 6px 5px 13px; border: 1px solid var(--border-subtle);
}
.wsh-cfield input { flex: 1; min-width: 0; border: none; background: none; font-family: inherit; font-size: 12px; color: var(--text-primary); }
.wsh-cbtn {
  width: 34px; height: 34px; border-radius: 50%; flex: none; display: grid; place-items: center;
  background: var(--surface-2); border: 1px solid var(--border-subtle); cursor: pointer;
}
.wsh-cbtn.send { background: var(--coral); color: var(--text-inverse); border-color: transparent; }
.wsh-cbtn:disabled { opacity: 0.45; cursor: default; }

@media (prefers-reduced-motion: reduce) {
  .wsh-ing.diff::after { animation: none; opacity: 0.5; }
  .wsh-kbar i { transition: none; }
}

/* Rutin hub — framework badge + strength bar + new-recipe highlight (mezo-3zue.3),
   docs/design_2.0/prototypes/src/rutin-epito-head.html .fw/.strength/.hrow.new ×1.18. */
.rt-hrow {
  display: grid; grid-template-columns: 1fr auto; grid-template-areas: "n f" "b b";
  column-gap: 8.3px; row-gap: 3.5px; align-items: center;
  width: 100%; padding: 8px 2px; cursor: pointer; text-align: left;
  border: none; background: none; font-family: inherit; color: var(--text-primary);
}
/* SortableList wraps each row in `[data-sortable-row]` (grip + `.col` > our `.row` > `.rt-hrow`
   + the ▲▼ `.row`) — the `.rt-hrow` buttons are never siblings, so the separator has to anchor
   on the sortable wrappers themselves (frontend/src/shared/ui/SortableList.tsx:124-182). */
[data-sortable-row] + [data-sortable-row] .rt-hrow { border-top: 0.5px solid var(--mz-line-soft); }
.rt-nm { grid-area: n; font-size: 13px; font-weight: 600; overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }
.rt-hrow .rt-fw { grid-area: f; }
.rt-bar { grid-area: b; display: flex; align-items: center; gap: 7px; }
.rt-tick {
  width: 16.5px; height: 16.5px; border-radius: 50%; flex: none; display: grid; place-items: center;
  font-size: 9.5px; border: 1.4px solid var(--mz-line); color: transparent;
}
.rt-done .rt-tick { background: var(--gradient-sage); border-color: transparent; color: #fff; }
.rt-done .rt-strength div { background: var(--gradient-sage); }
.rt-fw {
  font-size: 8px; font-weight: 800; letter-spacing: 0.08em; border-radius: 6px;
  padding: 2px 7px; flex: none; text-transform: uppercase; font-variant-numeric: tabular-nums;
}
.rt-fw-fogg { color: var(--mz-cell-sage-ink); background: var(--mz-cell-sage-bg); }
.rt-fw-clear { color: var(--mz-cell-lav-ink); background: var(--mz-cell-lav-bg); }
.rt-fw-none { color: var(--mz-ink-mut); background: var(--surface-recess); }
.rt-strength {
  flex: 1; height: 5px; border-radius: 2px; background: var(--mz-line-soft); overflow: hidden;
}
.rt-strength div { height: 100%; border-radius: 2px; background: var(--mz-strength); transition: width 0.6s cubic-bezier(0.22, 0.9, 0.32, 1); }
/* The number beside the bar (spec §5, restored from the retired GrowthRutinPage): the bar alone
   is a silent graphic, and the exact standing is the thing a user actually reads. */
.rt-strength-n {
  flex: none; min-width: 30px; text-align: right;
  font-size: 10px; font-weight: 700; font-variant-numeric: tabular-nums; color: var(--faint);
}
.rt-row-new {
  background: linear-gradient(90deg, color-mix(in srgb, var(--primary-soft) 55%, transparent), transparent);
  border-radius: 12px;
}
/* A paused chain stays VISIBLE and merely dims — the toggle that un-pauses it lives on this
   card, so hiding it would strand the chain (`.is-inert` is otherwise scoped to .card/.row). */
.gr-chain.is-inert { opacity: 0.55; }

/* A ▲▼ átrendező gombok a11y-affordanciák: a prototípus .hrow-ján nincsenek, ezért
   alapból nem foglalnak helyet, és csak billentyű-fókuszra jelennek meg. Rejtve is az
   a11y fában maradnak (nincs display:none / visibility:hidden). */
.srt-chev-focus { width: 0; overflow: hidden; opacity: 0; transition: opacity 0.15s ease; }
.srt-chev-focus:focus-within { width: auto; overflow: visible; opacity: 1; }

/* ===== Rutin wizard — /me/rutin/uj (mezo-3zue.4) =====
   docs/design_2.0/prototypes/src/rutin-epito-head.html `.sentence` / `.fwcard` / `.tip` /
   `.commit` + the form language (`.fcard`/`.flabel`/`.fin`/`.chips`/`.stepin`/`.lifegrid`),
   ×1.18 (330 → 390px frame). Every prototype hex is substituted by the nearest existing
   token: the gold sentence wash → --mz-wash-gold, its label ink → --accent-deep, the Fogg
   sage → --mz-cell-sage-ink, the Clear lavender → --mz-cell-lav-ink, the gold accent →
   --accent-base, the muted ink → --mz-ink-mut. */
.rt-wtitle { font-size: 17.5px; font-weight: 700; text-align: center; padding: 8px 16px 2px; color: var(--text-primary); }
.rt-wsub { font-size: 11px; color: var(--text-secondary); text-align: center; padding: 0 26px 10px; line-height: 1.45; }

/* the live recipe card — the thesis of the wizard */
.rt-sentence {
  border-radius: 19px; padding: 12px 15px 13px; margin-bottom: 12px;
  background: var(--mz-wash-gold); border: 0.5px solid var(--mz-line-soft);
  box-shadow: var(--mz-shadow-gold);
}
.rt-sentence-lb {
  display: flex; gap: 7px; align-items: center; font-size: 8.5px; font-weight: 800;
  letter-spacing: 0.16em; text-transform: uppercase; color: var(--accent-deep); margin-bottom: 5px;
}
.rt-sentence-lb-sub { color: var(--text-tertiary); }
.rt-sentence-tx {
  margin: 0; font-family: var(--ff-serif); font-style: italic; font-size: 15px;
  line-height: 1.45; color: var(--text-primary);
}
/* step 4 reads the finished recipe back — the prototype's `.sentence.big` (15px → 17.7px). */
.rt-sentence.is-big .rt-sentence-tx { font-size: 17.7px; line-height: 1.4; }
.rt-blank {
  display: inline; padding: 0 2.5px; color: var(--mz-ink-mut);
  border-bottom: 1.5px dashed var(--divider);
}
.rt-blank.is-filled {
  border-bottom-color: transparent; color: var(--text-primary); font-weight: 500; border-radius: 5px;
  background: color-mix(in srgb, var(--mz-cell-sage-ink) 20%, transparent);
}
.rt-sentence.is-clear .rt-blank.is-filled { background: color-mix(in srgb, var(--mz-cell-lav-ink) 18%, transparent); }

/* framework cards */
.rt-fwcard {
  display: flex; gap: 12px; align-items: flex-start; width: 100%; text-align: left;
  border-radius: 19px; padding: 13px 14px; margin-bottom: 9.5px;
  background: var(--surface-card); border: 1.5px solid var(--border-subtle);
  color: var(--text-primary); font-family: inherit; cursor: pointer; box-shadow: var(--mz-shadow);
}
.rt-fwsgn {
  width: 42px; height: 42px; border-radius: 14px; flex: none; display: grid; place-items: center;
  font-size: 19px; font-weight: 300; background: var(--surface-recess);
}
.rt-fwbody { flex: 1; min-width: 0; }
.rt-fwcard b { font-size: 14px; display: block; }
.rt-fwcard small { font-size: 10.5px; color: var(--text-secondary); display: block; margin-top: 2px; line-height: 1.4; }
.rt-fwwho {
  display: block; margin-top: 5px; font-size: 8.5px; font-weight: 800;
  letter-spacing: 0.12em; text-transform: uppercase; color: var(--mz-ink-mut);
}
.rt-fwloop { display: flex; gap: 5px; margin-top: 7px; flex-wrap: wrap; align-items: center; }
.rt-fwloop span {
  font-size: 8.5px; font-weight: 800; letter-spacing: 0.08em; text-transform: uppercase;
  color: var(--text-secondary); background: var(--surface-recess); border-radius: 6px; padding: 2px 7px;
}
.rt-fwloop i { font-style: normal; color: var(--mz-ink-mut); font-size: 9.5px; }
.rt-fwcard.is-fogg.on {
  border-color: var(--mz-cell-sage-ink); background: var(--mz-wash-sage); box-shadow: var(--mz-shadow-sage);
}
.rt-fwcard.is-fogg.on .rt-fwsgn { background: var(--surface-card); color: var(--mz-cell-sage-ink); }
.rt-fwcard.is-clear.on {
  border-color: var(--mz-cell-lav-ink); background: var(--mz-wash-lav); box-shadow: var(--mz-shadow-lav);
}
.rt-fwcard.is-clear.on .rt-fwsgn { background: var(--surface-card); color: var(--mz-cell-lav-ink); }

/* tip band */
.rt-tip {
  display: flex; gap: 8px; align-items: flex-start; border-radius: 14px; padding: 9.5px 12px;
  margin: 7px 0 9.5px; font-size: 11px; line-height: 1.45; font-weight: 500;
  color: var(--mz-cell-sage-ink); background: color-mix(in srgb, var(--mz-cell-sage-ink) 13%, transparent);
}
.rt-tip.is-lav { color: var(--mz-cell-lav-ink); background: color-mix(in srgb, var(--mz-cell-lav-ink) 12%, transparent); }
.rt-tip.is-warn { color: var(--accent-deep); background: color-mix(in srgb, var(--accent-base) 14%, transparent); }
.rt-tip b { font-weight: 700; }

/* form language */
.rt-fcard {
  background: var(--surface-card); border-radius: 16.5px; padding: 11px 13px 12px; margin-bottom: 9.5px;
  border: 0.5px solid var(--mz-line-soft); box-shadow: var(--mz-shadow);
}
.rt-flabel {
  display: flex; gap: 7px; align-items: baseline; margin-bottom: 5px;
  font-size: 9px; font-weight: 700; letter-spacing: 0.16em; text-transform: uppercase; color: var(--mz-ink-mut);
}
.rt-opt { font-weight: 600; letter-spacing: 0.04em; text-transform: none; color: var(--text-tertiary); }
.rt-fin {
  width: 100%; margin-top: 8px; border: 1px solid var(--border-subtle); border-radius: 12px;
  padding: 8px 12px; font-family: inherit; font-size: 13px;
  background: var(--surface-page); color: var(--text-primary);
}
.rt-fin::placeholder { color: var(--mz-ink-mut); }
.rt-fin:focus { outline: 2px solid color-mix(in srgb, var(--accent-base) 55%, transparent); outline-offset: 1px; border-color: transparent; }
.rt-chips { display: flex; gap: 6px; flex-wrap: wrap; }
.rt-chips button {
  border: 1px solid var(--border-subtle); background: var(--surface-card); border-radius: 999px;
  padding: 5px 13px; font-size: 10.5px; font-weight: 700; color: var(--text-secondary);
  font-family: inherit; cursor: pointer; display: inline-flex; align-items: center; gap: 5px;
}
.rt-chips button.on { background: var(--mz-cell-lav-bg); border-color: var(--mz-cell-lav-ink); color: var(--mz-cell-lav-ink); }
.rt-chips.is-sage button.on { background: var(--mz-cell-sage-bg); border-color: var(--mz-cell-sage-ink); color: var(--mz-cell-sage-ink); }
.rt-chips.is-gold button.on { background: var(--mz-cell-gold-bg); border-color: var(--accent-base); color: var(--accent-deep); }
.rt-chip-src { font-size: 8px; font-weight: 800; letter-spacing: 0.08em; color: var(--mz-ink-mut); }
.rt-chips button.on .rt-chip-src { color: inherit; opacity: 0.7; }
.rt-stepin { display: inline-flex; align-items: center; gap: 5px; }
.rt-stepin button {
  width: 28px; height: 28px; border-radius: 9px; border: 1px solid var(--border-subtle);
  background: var(--surface-card); font-size: 14px; color: var(--text-secondary);
  cursor: pointer; font-family: inherit; padding: 0;
}
.rt-stepin b { min-width: 52px; text-align: center; font-size: 12.5px; font-variant-numeric: tabular-nums; }
.rt-hint { font-size: 9.5px; color: var(--mz-ink-mut); margin-top: 7px; }
.rt-lifegrid { display: grid; grid-template-columns: repeat(4, 1fr); gap: 6px; }
.rt-lifegrid button {
  border: 1px solid var(--border-subtle); background: var(--surface-card); border-radius: 13px;
  padding: 7px 2px 5px; display: grid; justify-items: center; gap: 2px; cursor: pointer; font-family: inherit;
}
.rt-lifegrid button small { font-size: 8.5px; font-weight: 700; color: var(--text-secondary); }
.rt-lifegrid button.on { background: var(--mz-cell-gold-bg); border-color: var(--accent-base); }
.rt-lifegrid button.on small { color: var(--accent-deep); }

/* the commitment tick — gates the terminal save, never a habit tick */
.rt-commit {
  display: flex; gap: 12px; align-items: center; width: 100%; text-align: left;
  border-radius: 16.5px; padding: 12px 14px; margin: 9.5px 0 5px; cursor: pointer;
  background: var(--surface-card); border: 1.5px solid var(--border-subtle);
  font-family: inherit; color: var(--text-primary);
}
.rt-commit-box {
  width: 26px; height: 26px; border-radius: 8px; flex: none; display: grid; place-items: center;
  border: 1.5px solid var(--divider); font-size: 14px; color: var(--text-inverse);
}
.rt-commit.on { border-color: var(--mz-cell-sage-ink); background: var(--mz-wash-sage); }
.rt-commit.on .rt-commit-box { border-color: transparent; background: var(--gradient-sage); }
.rt-commit b { font-size: 13px; display: block; }
.rt-commit small { font-size: 10px; color: var(--text-secondary); }

.rt-wnav { display: flex; gap: 9.5px; margin-top: 12px; }
.rt-wnav .cta-primary, .rt-wnav .cta-ghost { justify-content: center; padding: 12px 0; }
.rt-wnav .cta-primary:disabled { opacity: 0.4; pointer-events: none; }

/* ===== Szokás-oldal — /me/rutin/szokas/:habitKey (mezo-3zue.4) =====
   docs/design_2.0/prototypes/src/rutin-epito-head.html `.fwband` / `.hist` / `.danger`,
   ×1.18 (330 → 390px frame). The prototype's per-framework wash+shadow pair (set inline by
   `openEdit`) becomes three modifier classes on tokens: sage for Fogg, lavender for Clear,
   sand for the frameworkless legacy row. The form language itself is the wizard's
   (`.rt-fcard`/`.rt-flabel`/`.rt-fin`/`.rt-chips`/`.rt-stepin`), reused verbatim. */
.rt-fwband {
  display: flex; gap: 10.6px; align-items: center; border-radius: 17.7px;
  padding: 10.6px 14px; margin-bottom: 10.6px;
}
.rt-fwband.is-fogg { background: var(--mz-wash-sage); box-shadow: var(--mz-shadow-sage); }
.rt-fwband.is-clear { background: var(--mz-wash-lav); box-shadow: var(--mz-shadow-lav); }
.rt-fwband.is-none { background: var(--mz-wash-sand); box-shadow: var(--mz-shadow-gold); }
.rt-fwband-sgn { font-size: 19px; line-height: 1; flex: none; }
.rt-fwband-t { font-size: 13px; font-weight: 700; color: var(--text-primary); }
.rt-fwband-s { font-size: 10px; color: var(--text-secondary); line-height: 1.35; }
.rt-fwband-sw {
  margin-left: auto; flex: none; cursor: pointer; font-family: inherit;
  font-size: 10px; font-weight: 700; color: var(--coral-deep);
  background: var(--surface-card); border: none; border-radius: 999px; padding: 4.7px 10.6px;
}

/* The 28-day strip visualises the summary's COUNTS (done28 / missed28) — the summary carries
   no per-day bitset, so this is a proportion bar, and the caption under it says so. */
.rt-hist { display: flex; gap: 3.5px; margin-top: 7px; }
/* Three states must READ as three: an empty cell is the faintest, a missed day is visibly
   darker than it, and a pipa is sage. The first pass had `is-miss` on --surface-recess
   (rgba .05) over an empty --mz-line-soft (rgba .07) — the legend was inverted. */
.rt-hist i { flex: 1; height: 16.5px; border-radius: 3.5px; background: var(--mz-line-soft); }
.rt-hist i.is-done { background: var(--gradient-sage); }
.rt-hist i.is-miss { background: color-mix(in srgb, var(--text-primary) 20%, transparent); }

/* ===== Formálódás-nézet (mezo-08zl) =====
   docs/design_2.0/prototypes/rutin-formalodas.html `.poster` / `.msrail` / `.etaband` /
   `.ctxgrid` / `.cal` / `.wdbars`, ×1.18 (330 -> 390px frame). Poster anatomy: one visual
   anchor (the ring), one big line, one range. The gold wash turns sage once the habit is past
   the threshold - the only state change on the card, and it is a reward, never a warning. */
.rt-poster {
  border-radius: 23.6px; padding: 14px 15.3px 13px; margin-bottom: 11.8px;
  background: var(--mz-wash-sand); box-shadow: var(--mz-shadow-gold);
}
.rt-poster.is-settled { background: var(--mz-wash-sage); box-shadow: var(--mz-shadow-sage); }
.rt-poster-top { display: flex; align-items: center; gap: 14px; }
.rt-poster-meta { min-width: 0; }
.rt-poster-eb {
  font-size: 9px; font-weight: 800; letter-spacing: 0.18em; text-transform: uppercase;
  color: var(--text-tertiary);
}
.rt-poster-big { font-size: 17.7px; font-weight: 700; line-height: 1.2; margin-top: 2px; color: var(--text-primary); }
.rt-poster-sub { margin: 4px 0 0; font-size: 10.6px; color: var(--text-secondary); line-height: 1.4; }
.rt-poster-note { margin: 9.5px 0 0; font-size: 9.5px; color: var(--text-tertiary); line-height: 1.45; }

/* The curve: solid = done, dashed = projection, band = the uncertainty of k. */
.rt-curve { display: block; width: 100%; height: auto; margin-top: 9.5px; }
.rt-curve-band { fill: color-mix(in srgb, var(--amber) 16%, transparent); stroke: none; }
.rt-curve-fill { fill: url(#rt-curve-fill); stroke: none; }
.rt-curve-past { fill: none; stroke: var(--amber); stroke-width: 2.4; stroke-linecap: round; }
.rt-curve-next { fill: none; stroke: var(--amber); stroke-width: 2; stroke-dasharray: 4 4; opacity: 0.7; }
.rt-curve-thr { stroke: color-mix(in srgb, var(--sage-deep) 55%, transparent); stroke-width: 1.2; stroke-dasharray: 3 4; }
.rt-curve-thrlb {
  font-size: 7.5px; font-weight: 800; letter-spacing: 0.1em; text-transform: uppercase;
  fill: var(--sage-deep);
}
.rt-curve-dot { fill: var(--surface-card); stroke: var(--amber); stroke-width: 2.4; }
.rt-curve-ax { font-size: 7.5px; fill: var(--text-tertiary); letter-spacing: 0.06em; }

/* Milestone rail: the four stages as a path, the current one breathing. */
.rt-msrail { display: flex; position: relative; margin: 14px 2px 2px; padding: 0; list-style: none; }
.rt-msrail::before {
  content: ''; position: absolute; left: 8%; right: 8%; top: 5.9px; height: 2.4px;
  border-radius: 2px; background: var(--mz-line-soft);
}
.rt-msrail li { flex: 1; display: grid; justify-items: center; gap: 5.9px; position: relative; }
.rt-msrail li i {
  width: 14px; height: 14px; border-radius: 50%; background: var(--surface-card); z-index: 1;
  box-shadow: inset 0 0 0 2.4px var(--mz-line-soft);
}
.rt-msrail li.is-past i { background: var(--gradient-sage); box-shadow: none; }
.rt-msrail li.is-now i {
  background: var(--surface-card);
  box-shadow: 0 0 0 3.5px var(--amber), 0 0 0 8px color-mix(in srgb, var(--amber) 22%, transparent);
  animation: rt-mspulse 2.4s ease-in-out infinite;
}
@keyframes rt-mspulse {
  0%, 100% { box-shadow: 0 0 0 3.5px var(--amber), 0 0 0 8px color-mix(in srgb, var(--amber) 22%, transparent); }
  50% { box-shadow: 0 0 0 3.5px var(--amber), 0 0 0 11.8px color-mix(in srgb, var(--amber) 8%, transparent); }
}
.rt-msrail li span {
  font-size: 7.8px; font-weight: 800; letter-spacing: 0.05em; text-transform: uppercase;
  color: var(--text-tertiary); text-align: center; line-height: 1.25;
}
.rt-msrail li.is-past span { color: var(--sage-deep); }
.rt-msrail li.is-now span { color: var(--text-primary); }

/* The estimate itself - a RANGE, never a point. */
.rt-etaband {
  display: flex; align-items: center; gap: 10.6px; border-radius: 16.5px;
  padding: 10.6px 13px; margin-top: 13px; background: var(--surface-card);
  box-shadow: var(--np-shadow-row);
}
.rt-etaband-n {
  flex: none; font: 300 20px/1 var(--ff-display); letter-spacing: -0.02em;
  color: var(--text-primary); font-variant-numeric: tabular-nums;
}
.rt-etaband-l { font-size: 10px; color: var(--text-secondary); line-height: 1.4; }
.rt-etaband-l b {
  display: block; font-size: 10.6px; font-weight: 800; letter-spacing: 0.12em;
  text-transform: uppercase; color: var(--text-tertiary);
}

/* Context rings - a signal we cannot measure shows a dash, never a fabricated zero. */
.rt-ctxgrid { display: grid; grid-template-columns: repeat(3, 1fr); gap: 9.5px; }
.rt-ctxcell {
  border-radius: 17.7px; padding: 10.6px 5.9px 9.5px; text-align: center;
  background: var(--surface-card); box-shadow: var(--np-shadow-row);
  display: grid; justify-items: center; gap: 2px;
}
.rt-ctxcell b { font-size: 9.5px; font-weight: 700; color: var(--text-primary); margin-top: 4px; }
.rt-ctxcell small { font-size: 8.3px; color: var(--text-tertiary); }

/* Lifetime calendar: a column per week, so it scales instead of truncating at 28 days. */
.rt-cal { display: flex; gap: 2.4px; overflow-x: auto; padding-bottom: 4px; }
.rt-cal-col { display: grid; grid-template-rows: repeat(7, 1fr); gap: 2.4px; flex: none; }
.rt-cal i { width: 11.8px; height: 11.8px; border-radius: 3.5px; background: var(--mz-line-soft); }
.rt-cal i.is-done { background: var(--gradient-sage); }
.rt-cal i.is-miss { background: color-mix(in srgb, var(--text-primary) 20%, transparent); }
.rt-cal-lg { display: flex; gap: 11.8px; margin-top: 7px; font-size: 8.3px; color: var(--text-tertiary); }
.rt-cal-lg span { display: flex; align-items: center; gap: 4.7px; }
.rt-cal-lg em { width: 9.5px; height: 9.5px; border-radius: 3px; background: var(--mz-line-soft); }
.rt-cal-lg em.is-done { background: var(--gradient-sage); }
.rt-cal-lg em.is-miss { background: color-mix(in srgb, var(--text-primary) 20%, transparent); }

/* "Melyik napokon megy" - the day-of-week regularity signal, made visible. */
.rt-wdays { display: grid; grid-template-columns: repeat(7, 1fr); gap: 5.9px; margin-top: 13px; }
.rt-wday { display: grid; justify-items: center; gap: 4.7px; }
.rt-wday-bar {
  width: 100%; height: 41px; border-radius: 7px; background: var(--surface-recess);
  display: flex; align-items: flex-end; overflow: hidden;
}
.rt-wday-bar i { width: 100%; border-radius: 7px; background: var(--gradient-sage); min-height: 2px; }
.rt-wday span { font-size: 8.3px; font-weight: 700; color: var(--text-tertiary); }

/* Pausing is the prominent way out; deleting (.is-hard) sits below it, quieter and two-tap. */
.rt-danger {
  width: 100%; margin-top: 9.5px; cursor: pointer; font-family: inherit;
  border: 1.4px dashed color-mix(in srgb, var(--coral-deep) 40%, transparent);
  background: none; border-radius: 13px; padding: 9.5px 0;
  font-size: 11.2px; font-weight: 700; color: var(--coral-deep);
}
/* A chip-linked anchor is shown, not edited (the API has no unlink) — it must LOOK inert. */
.rt-fin.is-locked { background: var(--surface-recess); color: var(--text-secondary); cursor: default; }
.rt-danger.is-hard { border-color: var(--mz-line-soft); color: var(--text-tertiary); font-weight: 600; }
.rt-danger.is-hard.is-armed { border-color: var(--error); color: var(--error); font-weight: 700; }
.rt-danger:disabled { opacity: 0.45; cursor: default; }

/* ===== Szerkesztő-oldal + horgony-választó (mezo-bk26) =====
   rutin-formalodas.html `pg-edit` `.swseg`/`.pickrow`/`.lockline`/`.warn` + the anchor
   sheet's `.optgrp`/`.optrow`, ×1.18 (330 → 390px frame), on the app's tokens. */
.rt-swseg { display: flex; gap: 6px; }
.rt-swseg button {
  flex: 1; border: 1.5px solid var(--border-subtle); background: var(--surface-card);
  border-radius: 13px; padding: 8px 5px; font-family: inherit; font-size: 10.6px;
  font-weight: 700; color: var(--text-secondary); cursor: pointer;
  display: grid; gap: 2px; justify-items: center;
}
.rt-swseg button span { font-size: 15px; }
.rt-swseg button.on {
  border-color: var(--mz-cell-sage-ink); color: var(--mz-cell-sage-ink);
  background: linear-gradient(140deg, var(--mz-cell-sage-bg), var(--surface-card) 70%);
}
.rt-swseg button.on.is-clear {
  border-color: var(--mz-cell-lav-ink); color: var(--mz-cell-lav-ink);
  background: linear-gradient(140deg, var(--mz-cell-lav-bg), var(--surface-card) 70%);
}
.rt-pickrow {
  width: 100%; display: flex; align-items: center; gap: 9px; border: 1px solid var(--border-subtle);
  background: var(--surface-page); border-radius: 12px; padding: 9px 12px; margin-top: 8px;
  font-family: inherit; font-size: 13px; color: var(--text-primary); cursor: pointer; text-align: left;
}
.rt-pickrow-gr { flex: 1; min-width: 0; overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }
.rt-pickrow-cv { color: var(--mz-ink-mut); font-size: 14px; flex: none; }
.rt-lockline { display: flex; gap: 6px; font-size: 9.4px; color: var(--mz-ink-mut); margin-top: 6px; line-height: 1.4; }
.rt-lockline b { color: var(--text-secondary); font-weight: 700; }
.rt-warn {
  display: flex; gap: 8px; border-radius: 13px; padding: 9.5px 12px; margin-top: 9.5px;
  font-size: 10px; line-height: 1.45; font-weight: 500;
  color: var(--accent-deep); background: color-mix(in srgb, var(--accent-base) 16%, transparent);
}
.rt-warn b { font-weight: 800; }
.rt-optgrp {
  font-size: 8.3px; font-weight: 800; letter-spacing: 0.16em; text-transform: uppercase;
  color: var(--mz-ink-mut); margin: 10.6px 2px 6px;
}
.rt-optrow {
  width: 100%; display: flex; align-items: center; gap: 10.6px; border: 1px solid var(--mz-line-soft);
  background: var(--surface-card); border-radius: 14px; padding: 10.6px 13px; margin-bottom: 7px;
  font-family: inherit; text-align: left; color: var(--text-primary); cursor: pointer;
}
.rt-optrow-nm { flex: 1; min-width: 0; font-size: 13px; font-weight: 600; }
.rt-optrow-nm small { display: block; font-size: 9.4px; font-weight: 400; color: var(--mz-ink-mut); }
.rt-optrow-rad {
  width: 17.7px; height: 17.7px; border-radius: 50%; border: 1.5px solid var(--divider); flex: none;
}
.rt-optrow.on {
  border-color: var(--mz-cell-sage-ink);
  background: linear-gradient(140deg, var(--mz-cell-sage-bg), var(--surface-card) 72%);
}
.rt-optrow.on .rt-optrow-rad {
  border-color: var(--mz-cell-sage-ink);
  background: radial-gradient(circle, var(--mz-cell-sage-ink) 42%, transparent 46%);
}
.rt-optrow.is-unlink { border-style: dashed; border-color: color-mix(in srgb, var(--coral-deep) 40%, transparent); }
.rt-optrow.is-unlink .rt-optrow-nm { color: var(--coral-deep); }

/* ===== Rutin hub 2.0 + Szokásaid (mezo-mgpr) =====
   rutin-formalodas.html `.nextcard`/`.bigtick`/`.chaintile`/`.chdots` + `pg-lista`'s
   `.fgrid`/`.ftile`/`.hgrid`/`.htile` ×1.18, on the app's tokens. */
.rt-nextcard {
  display: flex; align-items: center; gap: 11.8px; border-radius: 21px; padding: 13px 14px;
  margin-bottom: 10.6px; background: var(--mz-wash-sand);
  border: 0.5px solid var(--mz-line-soft); box-shadow: var(--mz-shadow-gold);
}
.rt-nextcard-tx { flex: 1; min-width: 0; }
.rt-nextcard-eb { font-size: 8.8px; font-weight: 800; letter-spacing: 0.18em; text-transform: uppercase; color: var(--accent-deep); }
.rt-nextcard-nm { font-size: 14.7px; font-weight: 700; margin-top: 1px; overflow: hidden; text-overflow: ellipsis; white-space: nowrap; color: var(--text-primary); }
.rt-nextcard-cue { font-size: 10px; color: var(--text-secondary); }
.rt-bigtick {
  width: 52px; height: 52px; border-radius: 50%; flex: none; border: none; cursor: pointer;
  font-size: 20px; color: var(--text-inverse); background: var(--gradient-sage);
  box-shadow: 0 11.8px 23.6px -9.4px color-mix(in srgb, var(--mz-cell-sage-ink) 70%, transparent),
    inset 0 1px 0 color-mix(in srgb, var(--surface-card) 35%, transparent);
  display: grid; place-items: center;
}
.rt-bigtick.is-allon { background: var(--gradient-gold); box-shadow: 0 11.8px 23.6px -9.4px color-mix(in srgb, var(--accent-base) 60%, transparent); }
.rt-chaintile {
  display: flex; align-items: center; gap: 13px; width: 100%; font-family: inherit; text-align: left;
  cursor: pointer; border-radius: 21px; padding: 13px 15.3px; margin-bottom: 10.6px;
  color: var(--text-primary); background: var(--mz-wash-lav);
  border: 0.5px solid var(--mz-line-soft); box-shadow: var(--mz-shadow-lav);
}
.rt-chaintile-eb { display: block; font-size: 8.8px; font-weight: 800; letter-spacing: 0.18em; text-transform: uppercase; color: var(--mz-cell-lav-ink); }
.rt-chaintile-dg { display: block; font-size: 16px; font-weight: 700; font-variant-numeric: tabular-nums; margin-top: 1px; }
.rt-chaintile-dg small { font-size: 10.6px; font-weight: 400; color: var(--text-secondary); margin-left: 6px; }
.rt-chdots { display: flex; gap: 4.7px; margin-top: 6px; }
.rt-chdots i { height: 4.7px; border-radius: 2.5px; background: color-mix(in srgb, var(--text-primary) 10%, transparent); flex: 1; }
.rt-chdots i.is-d { background: var(--gradient-sage); }
.rt-chdots i.is-now { background: var(--gradient-gold); box-shadow: 0 0 0 2px color-mix(in srgb, var(--accent-base) 20%, transparent); }
.rt-chaintile-cv { color: var(--mz-cell-lav-ink); font-size: 17.7px; flex: none; }
.rt-fgrid { display: grid; grid-template-columns: 1fr 1fr; gap: 9.5px; margin-bottom: 13px; }
.rt-ftile {
  display: block; width: 100%; border-radius: 19px; padding: 10.6px 11.8px; cursor: pointer;
  font-family: inherit; text-align: left; color: var(--text-primary);
  background: var(--surface-card); border: 1px solid var(--mz-line-soft);
  box-shadow: var(--mz-shadow);
}
.rt-fdots { display: flex; gap: 3.5px; margin-bottom: 8px; }
.rt-fdots i { flex: 1; height: 3.5px; border-radius: 2.5px; background: color-mix(in srgb, var(--text-primary) 10%, transparent); }
.rt-fdots i.on { background: var(--fc); }
.rt-ftile b { display: block; font-size: 23.6px; font-weight: 200; line-height: 1; letter-spacing: -0.02em; font-variant-numeric: tabular-nums; }
.rt-ftile small { display: block; margin-top: 4.7px; font-size: 9.4px; font-weight: 700; line-height: 1.25; color: var(--text-secondary); }
.rt-ftile.on { background: linear-gradient(150deg, var(--fw), var(--surface-card) 78%); border-color: var(--fc); }
.rt-ftile.on small { color: var(--fc); }
.rt-ftile.is-zero { opacity: 0.45; }
.rt-hgrid { display: grid; gap: 11.8px; }
.rt-htile {
  display: block; width: 100%; border-radius: 21px; padding: 14px 15.3px 13px; cursor: pointer;
  background: linear-gradient(150deg, var(--hw, var(--surface-recess)), var(--surface-card) 76%);
  border: 0.5px solid var(--mz-line-soft); font-family: inherit; text-align: left; color: var(--text-primary);
  box-shadow: 0 18.9px 35.4px -20px var(--hs, rgba(0, 0, 0, 0.3)),
    inset 0 1px 0 color-mix(in srgb, var(--surface-card) 80%, transparent);
}
.rt-htop { display: flex; align-items: flex-start; gap: 14px; }
.rt-hleft { flex: 1; min-width: 0; display: block; }
.rt-hnm { font-size: 15.3px; font-weight: 700; line-height: 1.25; display: block; }
.rt-hstage {
  display: block; margin-top: 4.7px; font-size: 8.8px; font-weight: 800; letter-spacing: 0.14em;
  text-transform: uppercase; color: var(--hc, var(--accent-deep));
}
.rt-hreps { display: block; margin-top: 7px; font-size: 26px; font-weight: 200; letter-spacing: -0.02em; line-height: 1; font-variant-numeric: tabular-nums; }
.rt-hreps small { font-size: 10px; font-weight: 600; color: var(--text-secondary); margin-left: 6px; letter-spacing: 0; }
.rt-hright { flex: none; width: 73px; text-align: center; display: block; }
.rt-harc { width: 61px; height: 61px; display: block; margin: 0 auto; }
.rt-heta {
  display: flex; align-items: baseline; gap: 7px; margin-top: 11.8px; padding-top: 10.6px;
  border-top: 0.5px solid color-mix(in srgb, var(--text-primary) 8%, transparent);
}
.rt-heta b { font-size: 14px; font-weight: 700; color: var(--hc, var(--accent-deep)); }
.rt-heta span { font-size: 10px; color: var(--text-secondary); }

/* ===== Lánc-oldal — a stacking kirajzolva (mezo-vxd8) =====
   rutin-formalodas.html `pg-lanc` `.stackrow`/`.srail`/`.snode`/`.achip`/`.smove`/`.macard`
   ×1.18, on the app's tokens. The rope is the chain ORDER; the badge is the real anchor. */
.rt-macard {
  border-radius: 21px; padding: 13px 14px 12px; margin-bottom: 10.6px;
  background: var(--mz-wash-sand); border: 0.5px solid var(--mz-line-soft);
  box-shadow: var(--mz-shadow-gold);
}
.rt-macard-head { display: flex; align-items: center; gap: 8px; margin-bottom: 8px; }
.rt-macard-t {
  font-size: 10px; font-weight: 800; letter-spacing: 0.14em; text-transform: uppercase;
  color: var(--accent-deep);
}
.rt-macard-c { margin-left: auto; font-size: 10.6px; font-weight: 700; color: var(--text-secondary); font-variant-numeric: tabular-nums; }
.rt-stackrow { display: grid; grid-template-columns: 28px 1fr auto; column-gap: 10.6px; align-items: center; padding: 5px 0; }
.rt-stackrow.is-inert .rt-sbody { opacity: 0.5; }
.rt-srail { position: relative; height: 54px; display: grid; place-items: center; }
.rt-srail::before, .rt-srail::after {
  content: ''; position: absolute; left: 50%; width: 2px; transform: translateX(-50%);
  background: color-mix(in srgb, var(--text-primary) 12%, transparent);
}
.rt-srail::before { top: 0; height: 15px; }
.rt-srail::after { bottom: 0; height: 15px; }
.rt-stackrow:first-of-type .rt-srail::before, .rt-stackrow:last-of-type .rt-srail::after { display: none; }
.rt-srail.is-linked::before { background: linear-gradient(180deg, color-mix(in srgb, var(--mz-cell-sage-ink) 20%, transparent), var(--mz-cell-sage-ink)); }
.rt-srail.is-broken::before { background: repeating-linear-gradient(180deg, color-mix(in srgb, var(--accent-base) 70%, transparent) 0 3.5px, transparent 3.5px 7px); }
.rt-snode {
  width: 23.6px; height: 23.6px; border-radius: 50%; display: grid; place-items: center;
  font-size: 10.6px; color: var(--text-inverse); border: 1.5px solid var(--divider);
  background: var(--surface-card); position: relative; z-index: 1;
}
.rt-snode.on { border-color: transparent; background: var(--gradient-sage); }
.rt-snode.next { border-color: var(--accent-base); color: var(--accent-deep); box-shadow: 0 0 0 3.5px color-mix(in srgb, var(--accent-base) 16%, transparent); }
.rt-sbody { min-width: 0; border: none; background: none; font-family: inherit; text-align: left; color: var(--text-primary); cursor: pointer; padding: 0; }
.rt-sbody-nm { font-size: 13px; font-weight: 600; display: block; }
.rt-achip {
  display: inline-flex; align-items: center; gap: 3.5px; margin-top: 3.5px; font-size: 8px;
  font-weight: 800; letter-spacing: 0.08em; text-transform: uppercase; border-radius: 6px; padding: 2px 7px;
}
.rt-achip.is-linked { background: color-mix(in srgb, var(--mz-cell-sage-ink) 18%, transparent); color: var(--mz-cell-sage-ink); }
.rt-achip.is-foreign { background: color-mix(in srgb, var(--accent-base) 20%, transparent); color: var(--accent-deep); }
.rt-achip.is-free { background: var(--surface-recess); color: var(--text-secondary); }
.rt-smove { display: flex; flex-direction: column; gap: 2px; }
.rt-smove button {
  width: 26px; height: 21px; border-radius: 7px; border: 1px solid var(--border-subtle);
  background: var(--surface-card); font-size: 10.6px; color: var(--text-secondary);
  cursor: pointer; font-family: inherit; padding: 0; line-height: 1;
}
.rt-smove button:disabled { opacity: 0.3; cursor: default; }
.rt-smini { width: 40px; height: 4.7px; border-radius: 2.5px; background: var(--surface-recess); overflow: hidden; display: block; }
.rt-smini span { display: block; height: 100%; border-radius: 2.5px; background: var(--gradient-gold); }
.rt-addrow {
  width: 100%; border: 1.5px dashed color-mix(in srgb, var(--mz-cell-sage-ink) 45%, transparent);
  background: color-mix(in srgb, var(--mz-cell-sage-bg) 55%, transparent); border-radius: 14px;
  padding: 10.6px; font-family: inherit; font-size: 11.8px; font-weight: 700;
  color: var(--mz-cell-sage-ink); cursor: pointer; margin-bottom: 9.5px;
}

/* ===== Fogg ability-faktorok → XP (mezo-9k99) =====
   rutin-formalodas.html `.effrow`/`.seg3`/`.effout` ×1.18, on the app's tokens. */
.rt-effrow { padding: 9.5px 0; }
.rt-effrow + .rt-effrow { border-top: 0.5px solid var(--mz-line-soft); }
.rt-effrow-h { display: flex; align-items: center; gap: 7px; margin-bottom: 7px; }
.rt-effrow-h b { font-size: 11.8px; font-weight: 700; color: var(--text-primary); }
.rt-effrow-h small { margin-left: auto; font-size: 9.4px; color: var(--mz-ink-mut); }
.rt-seg3 { display: flex; gap: 5px; }
.rt-seg3 button {
  flex: 1; border: 1px solid var(--border-subtle); background: var(--surface-card);
  border-radius: 10.6px; padding: 7px 3.5px; font-family: inherit; font-size: 10px;
  font-weight: 600; color: var(--text-secondary); cursor: pointer; line-height: 1.25;
}
.rt-seg3 button.is-sage.on { border-color: var(--mz-cell-sage-ink); background: var(--mz-cell-sage-bg); color: var(--mz-cell-sage-ink); font-weight: 700; }
.rt-seg3 button.is-gold.on { border-color: var(--accent-base); background: var(--mz-cell-gold-bg); color: var(--accent-deep); font-weight: 700; }
.rt-seg3 button.is-coral.on { border-color: var(--coral-deep); background: color-mix(in srgb, var(--coral-deep) 14%, transparent); color: var(--coral-deep); font-weight: 700; }
.rt-effout {
  display: flex; align-items: center; gap: 11.8px; border-radius: 16.5px; padding: 11.8px 13px;
  margin-top: 10.6px; background: var(--mz-wash-sand);
  box-shadow: inset 0 1px 0 color-mix(in srgb, var(--surface-card) 90%, transparent);
}
.rt-effout-lvl { font-size: 14px; font-weight: 700; color: var(--text-primary); }
.rt-effout-lvl small { display: block; font-size: 9.4px; font-weight: 400; color: var(--text-secondary); margin-top: 1px; }
.rt-effout-xp { margin-left: auto; text-align: right; flex: none; }
.rt-effout-xp b { display: block; font-size: 21px; font-weight: 200; letter-spacing: -0.02em; font-variant-numeric: tabular-nums; color: var(--text-primary); }
.rt-effout-xp small { font-size: 8.3px; font-weight: 800; letter-spacing: 0.14em; text-transform: uppercase; color: var(--mz-ink-mut); }

/* ===== Fuel beállítások · önálló Mozaik 2.0 oldal (mezo-2xzf) ===== */
.fset-page { min-width: 0; overflow-x: clip; }
.fset-title {
  margin: 0; min-width: 0; overflow: hidden; text-overflow: ellipsis; white-space: nowrap;
  font: 700 15px/1.2 var(--ff-display); color: var(--text-primary);
}
.fset-body {
  display: flex; flex-direction: column; gap: 13px;
  padding-top: 10px; padding-bottom: 112px;
}
.fset-hero {
  position: relative; overflow: hidden; min-height: 220px; padding: 19px 19px 14px;
  border: 1px solid var(--border-subtle); border-radius: var(--r-2xl);
  background: var(--mz-wash-sage); box-shadow: var(--mz-shadow-sage);
}
.fset-hero::after {
  content: ""; position: absolute; width: 150px; height: 150px; right: -55px; top: -64px;
  border-radius: var(--r-full); background: var(--accent-soft); opacity: .28; filter: blur(12px);
  pointer-events: none;
}
.fset-eyebrow,
.fset-card > h2,
.fset-card > span:first-child,
.fset-row > span:first-child,
.fset-selectrow > span:first-child {
  font-size: 10px; font-weight: 800; letter-spacing: .08em; text-transform: uppercase;
  color: var(--text-muted);
}
.fset-hero-head {
  position: relative; z-index: 1; display: flex; align-items: center; justify-content: space-between;
  gap: 12px; margin-top: 5px;
}
.fset-hero-head strong {
  font: 300 36px/1 var(--ff-display); letter-spacing: -.04em; color: var(--text-primary);
}
.fset-cutoff-pill {
  flex: none; padding: 6px 10px; border-radius: var(--r-full);
  background: var(--mz-cell-gold-bg); color: var(--mz-cell-gold-ink);
  font-size: 9px; font-weight: 800; letter-spacing: .03em;
}
.fset-summary { position: absolute; width: 1px; height: 1px; overflow: hidden; clip-path: inset(50%); }
.fset-arc-wrap { position: relative; z-index: 1; margin-top: 9px; }
.fset-dayarc { display: block; width: 100%; height: 104px; overflow: visible; }
.fset-arc-track,
.fset-arc-glow { fill: none; stroke-linecap: round; }
.fset-arc-track { stroke: var(--divider); stroke-width: 5; }
.fset-arc-glow {
  stroke: var(--success-base); stroke-width: 2.5; stroke-dasharray: 410; stroke-dashoffset: 410;
  animation: fset-draw 700ms var(--ease-out) 120ms forwards;
}
.fset-meal-dot {
  fill: var(--surface-card); stroke: var(--success-hover); stroke-width: 3;
  filter: drop-shadow(0 3px 3px var(--divider));
}
.fset-cutoff-line { stroke: var(--accent-hover); stroke-width: 2; stroke-linecap: round; }
.fset-cutoff-dot { fill: var(--accent-base); stroke: var(--surface-card); stroke-width: 2; }
.fset-axis { display: flex; justify-content: space-between; margin: -10px 5px 0; }
.fset-axis span { font-size: 8px; font-weight: 700; color: var(--text-muted); }
.fset-principle { margin: 8px 0 0; text-align: center; font-size: 10px; color: var(--text-secondary); }

.fset-card {
  min-width: 0; margin: 0; padding: 15px 16px; border: 1px solid var(--border-subtle);
  border-radius: var(--r-xl); background: var(--surface-card); color: var(--text-primary);
  box-shadow: var(--mz-shadow); font-family: inherit;
}
.fset-card > h2 { margin: 0 0 8px; }
.fset-card p { margin: 8px 0 0; font-size: 10px; line-height: 1.45; color: var(--text-muted); }
.fset-row,
.fset-selectrow {
  display: flex; align-items: center; justify-content: space-between; gap: 12px;
  min-height: 48px; border-top: 1px solid var(--divider);
}
.fset-card h2 + .fset-row,
.fset-card h2 + .fset-selectrow { border-top: 0; }
.fset-stepper { display: flex; align-items: center; gap: 9px; flex: none; }
.fset-stepper .chip {
  display: grid; place-items: center; width: 44px; height: 44px; padding: 0;
  border: 1px solid var(--border-subtle); background: var(--surface-page);
}
.fset-stepper .chip:disabled { opacity: .38; }
.fset-stepper > span {
  min-width: 52px; text-align: center; font-size: 16px; font-weight: 750;
  font-variant-numeric: tabular-nums; color: var(--text-primary);
}
.fset-row input,
.fset-selectrow select,
.fset-goalgrid input,
.fset-custom input {
  min-height: 44px; border: 1px solid var(--border-subtle); border-radius: var(--r-md);
  background: var(--surface-page); color: var(--text-primary); font: 650 14px/1 var(--ff-body);
}
.fset-row input { width: 112px; padding: 0 10px; text-align: right; color-scheme: light dark; }
.fset-selectrow { align-items: stretch; flex-direction: column; padding: 3px 0 12px; gap: 7px; }
.fset-selectrow > span { align-self: flex-start; }
.fset-selectrow select { width: 100%; padding: 0 38px 0 12px; cursor: pointer; }

@keyframes fset-draw { to { stroke-dashoffset: 0; } }

.fset-target-preview {
  display: grid; gap: 10px; padding: 12px; border-radius: var(--r-lg);
  background: var(--surface-page); border: 1px solid var(--border-subtle);
}
.fset-target-label { font-size: 10px; font-weight: 800; letter-spacing: .07em; text-transform: uppercase; }
.fset-macro-preview-body { display: grid; grid-template-columns: 112px minmax(0, 1fr); align-items: center; gap: 14px; }
.fset-donut {
  width: 108px; aspect-ratio: 1; padding: 10px; border-radius: var(--r-full);
  background: conic-gradient(
    var(--macro-protein) 0 var(--protein-pct),
    var(--macro-carbs) var(--protein-pct) var(--carbs-end),
    var(--macro-fat) var(--carbs-end) 100%
  );
  box-shadow: var(--shadow-sm);
}
.fset-donut > span {
  width: 100%; height: 100%; display: grid; place-content: center; justify-items: center;
  border-radius: var(--r-full); background: var(--surface-card); text-align: center;
}
.fset-donut strong { font-size: 13px; font-weight: 750; color: var(--text-primary); }
.fset-donut small { margin-top: 2px; font-size: 8px; color: var(--text-muted); }
.fset-macro-rows { display: grid; min-width: 0; }
.fset-macro-rows > div {
  position: relative; display: flex; align-items: center; justify-content: space-between;
  gap: 7px; min-height: 31px; padding-left: 15px; border-bottom: 1px solid var(--divider);
}
.fset-macro-rows > div:last-child { border-bottom: 0; }
.fset-macro-rows > div::before {
  content: ""; position: absolute; left: 0; width: 8px; height: 8px; border-radius: var(--r-full);
  background: var(--macro-protein);
}
.fset-macro-rows > div:nth-child(2)::before { background: var(--macro-carbs); }
