.fkk-searching { display: grid; justify-items: center; gap: 8px; padding: 22px 16px; border-radius: 18px; text-align: center; }
.fkk-searching strong { display: inline-flex; align-items: center; gap: 8px; font-family: var(--ff-display); font-size: 17px;
  font-weight: 600; color: var(--text-primary); }
