.fkx-rdetail .fkx-actions { display: grid; grid-template-columns: repeat(3, minmax(0, 1fr)); gap: 8px; margin: 12px 0 6px; }
.fkx-rdetail .fkx-actions > button { justify-content: center; min-height: 48px; padding: 10px 8px;
  border-radius: 16px; font-size: 13px; color: var(--text-secondary);
  background: rgba(245, 239, 230, 0.05); box-shadow: inset 0 0 0 1px var(--divider); }
.fkx-rdetail .fkx-actions > button .t-ico { width: 22px; height: 22px; filter: none; }
.fkx-rdetail .fkx-actions > button.fkx-del { margin-left: 0; color: #FFB39C;
