.fkx-rsheet-head > .t-ico { width: 44px; height: 44px; }
.fkx-rsheet { display: grid; grid-template-columns: minmax(0, 1fr); gap: 6px; }
.fkx-rsheet > * { min-width: 0; }
.fkx-rlogs { display: grid; gap: 6px; }
.fkx-rlog { padding: 10px 12px; border-radius: 14px; }
.fkx-rlog-top { display: flex; align-items: center; gap: 12px; }
.fkx-rlog-when { flex: 1; min-width: 0; }
.fkx-rlog-when strong { display: block; font-size: 14px; font-weight: 600; }
.fkx-rlog-when small { display: block; margin-top: 2px; font-size: 11.5px; color: var(--text-secondary); }
.fkx-rlog-score { display: flex; flex-direction: column; align-items: flex-end; gap: 3px; }
