.fkx-rlog-empty.uv-empty { --c: var(--dv-amber); display: grid; justify-items: center; gap: 8px;
  padding: 18px 16px; border-radius: 18px; text-align: center; }
.fkx-rlog-empty strong { font-size: 14px; font-weight: 600; }
.fkx-rlog-empty p { margin: 0; font-size: 12px; line-height: 1.5; color: var(--text-secondary); }
.fkx-search-row { display: flex; align-items: center; gap: 8px; margin-bottom: 10px; }
.fkx-search-field { flex: 1; min-width: 0; display: flex; align-items: center; gap: 10px; padding: 9px 14px;
  border-radius: 16px; background: rgba(245, 239, 230, 0.05); box-shadow: inset 0 0 0 1px var(--divider); }
.fkx-search-field .t-ico { width: 22px; height: 22px; filter: none; }
.fkx-search-field input { flex: 1; min-width: 0; border: 0; background: none; font: inherit;
  font-size: 13.5px; color: var(--text-primary); outline: none; }
