.fkx-pick-list { max-height: 420px; overflow-y: auto; }
.fkx-pick { padding: 11px 12px; border-radius: 14px;
  box-shadow: inset 3px 0 0 var(--c), inset 0 0 0 1px var(--divider); }
.fkx-pick-top { display: flex; align-items: center; gap: 10px; }
.fkx-pick-copy { flex: 1; min-width: 0; }
.fkx-pick-name { display: flex; flex-wrap: wrap; align-items: center; gap: 6px; }
.fkx-pick-name strong { font-size: 14px; font-weight: 600; overflow-wrap: anywhere; }
.fkx-pick-star { display: inline-grid; }
.fkx-pick-star .t-ico { width: 15px; height: 15px; filter: none; }
.fkx-pick-copy > small { display: block; margin-top: 3px; font-size: 11.5px; color: var(--text-secondary); overflow-wrap: anywhere; }
.fkx-pick-kcal { flex: 0 0 auto; text-align: right; }
.fkx-pick-kcal b { display: block; font-size: 16px; font-weight: 600; font-variant-numeric: tabular-nums; }
.fkx-pick-kcal small { font-size: 10px; color: var(--text-muted); }
.fkx-pick-add { --c: var(--dv-coral); width: 34px; height: 34px; flex: 0 0 auto; display: grid; place-items: center;
  border: 0; border-radius: 50%; color: var(--page, #191614); background: var(--c);
  box-shadow: 0 0 12px color-mix(in srgb, var(--c) 50%, transparent); }
.fkx-pick-add.is-gold { --c: var(--dv-amber); }
.fkx-pick-add.is-added { color: var(--text-secondary); background: rgba(245, 239, 230, 0.06);
  box-shadow: inset 0 0 0 1px var(--divider); opacity: 0.7; }
.fkx-pick-macros { margin-top: 8px; }
.fkx-pick-none.uv-empty { --c: var(--dv-coral); margin: 4px 0; padding: 16px 8px; border-radius: 14px;
  text-align: center; font-size: 12px; color: var(--text-secondary); }
.fkx-thread { max-height: 420px; overflow-y: auto; }
.fkx-bubble { max-width: 92%; justify-self: start; padding: 9px 12px; border-radius: 14px; }
.fkx-bubble.is-user { justify-self: end; background: color-mix(in srgb, var(--dv-coral) 12%, transparent);
  box-shadow: inset 0 0 0 1px color-mix(in srgb, var(--dv-coral) 30%, transparent); }
.fkx-bubble p { margin: 3px 0 0; font-size: 13px; line-height: 1.5; color: var(--text-primary); }

/* Recept szerkesztő — one sage glass form card, a lavender glass total, glass line cards. */
.fkx-fcard.glass { display: grid; gap: 14px; padding: 14px; border-radius: 22px; }
.fkx-field { display: grid; gap: 7px; min-width: 0; }
.fkx-field > span { font-size: 9.5px; font-weight: 600; letter-spacing: 1.3px; color: var(--text-muted); }
.fkx-hint { margin: 0; font-size: 11.5px; line-height: 1.4; color: var(--text-secondary); }
.fkx-two { display: grid; grid-template-columns: repeat(2, minmax(0, 1fr)); gap: 10px; }
