.fkx-stat b { display: block; font-size: 22px; font-weight: 600; letter-spacing: -0.8px;
  font-variant-numeric: tabular-nums; color: color-mix(in srgb, var(--c) 80%, var(--text-primary)); }
.fkx-stat small { font-size: 10px; color: var(--text-muted); }
.fkx-other { margin: 0; font-size: 11px; color: var(--text-muted); font-variant-numeric: tabular-nums; }
