.fkx-lcard-kcal { flex: 0 0 auto; text-align: right; }
.fkx-lcard-kcal b { font-size: 18px; font-weight: 600; font-variant-numeric: tabular-nums;
  color: color-mix(in srgb, var(--c) 78%, var(--text-primary)); }
.fkx-lcard-kcal small { margin-left: 3px; font-size: 10.5px; color: var(--text-muted); }
.fkx-lcard-kcal.is-null b { color: var(--text-muted); }
.fkx-lcard-line { display: flex; flex-wrap: wrap; align-items: center; gap: 8px; }
.fkx-lines-empty.uv-empty { --c: var(--dv-sage); margin: 0; padding: 14px; border-radius: 18px;
  text-align: center; font-size: 12px; color: var(--text-secondary); }
.fkx-addline.uv-empty { --c: var(--dv-sage); display: flex; align-items: center; justify-content: center; gap: 8px;
  min-height: 48px; padding: 12px; border-radius: 20px; font-family: inherit; font-size: 14px; font-weight: 600;
  color: var(--text-primary); }
.fkx-addline .t-ico { width: 24px; height: 24px; filter: none; }
.fkx-tags { align-items: center; }
/* the portaled save bar — a frosted dock, not a card (prototype `.savebar`) */
.recipe-save-bar.fkx-savebar { display: grid; grid-template-columns: 1fr 1.6fr; gap: 10px;
  left: 12px; right: 12px; padding: 10px; border: 0; border-radius: 24px;
  background: rgba(25, 22, 20, 0.82); -webkit-backdrop-filter: blur(14px); backdrop-filter: blur(14px);
  box-shadow: inset 0 0 0 1px var(--divider); }
.fkx-btn { --c: var(--dv-sage); display: flex; align-items: center; justify-content: center; gap: 8px;
  min-height: 48px; padding: 12px 16px; border: 0; border-radius: 18px; font-family: inherit;
  font-size: 14.5px; font-weight: 600; color: var(--text-primary); text-align: center; }
.fkx-btn.is-flat { color: var(--text-secondary); background: rgba(245, 239, 230, 0.05);
  box-shadow: inset 0 0 0 1px var(--divider); }
.fkx-btn:disabled { opacity: 0.45; }

/* Receptműhely — the empty canvas is a frameless lavender halo; the dock is ONE glass card. */
.fkx-workshop .fkx-ws-empty { padding: 24px 22px 8px; background: none; }
.fkx-workshop .fkx-ws-art .t-ico { width: 104px; height: 104px; margin: 0 auto;
  filter: drop-shadow(0 12px 14px rgba(0, 0, 0, 0.5)) drop-shadow(0 0 20px rgba(171, 159, 210, 0.45)); }
.fkx-workshop .fkx-ws-empty strong { font-family: var(--ff-serif); font-style: italic; font-size: 28px;
  font-weight: 500; letter-spacing: 0; }
.fkx-workshop .fkx-ws-empty p { font-size: 13.5px; line-height: 1.5; color: var(--text-secondary); }
.fkx-workshop .fkx-ws-empty small { font-size: 11.5px; color: var(--text-muted); }
.fkx-ws-name { display: grid; gap: 8px; margin: 0 0 6px; }
.fkx-ws-name .fkx-inp { font-family: var(--ff-display); font-size: 16px; }
.fkx-workshop .fkx-stepper { padding: 0; border: 0; background: none; box-shadow: none; }
.fkx-workshop .fkx-stepper button { width: 38px; height: 38px; font-size: 18px; color: var(--text-primary);
  background: rgba(245, 239, 230, 0.06); box-shadow: inset 0 0 0 1px var(--divider); }
.fkx-workshop .fkx-stepper strong { font-size: 22px; font-weight: 600; }
.fkx-workshop .fkx-stepper small { font-size: 11px; color: var(--text-secondary); }
.fkx-workshop .fkx-basis { margin: 0; }
.fkx-callout { margin: 8px 0 0; padding: 12px 14px; border-radius: 18px; font-size: 13px; line-height: 1.45;
  color: var(--text-secondary); background: color-mix(in srgb, var(--dv-amber) 8%, transparent);
  box-shadow: inset 3px 0 0 var(--dv-amber); }
.fkx-workshop .fkx-lines-empty.uv-empty { padding: 14px; }
/* the diff flash rides on ::after, which glass also uses for its sheen: restate the overlay */
.fkx-workshop .wsh-ing.glass.diff::after { top: 0; bottom: 0; left: 0; width: auto; right: 0; z-index: 3;
  transform: none; opacity: 1; animation: wsh-difffade 2.6s ease-out forwards; }
@media (prefers-reduced-motion: reduce) {
  .fkx-workshop .wsh-ing.glass.diff::after { animation: none; opacity: 0.5; }
}
.fkx-ws-steps { margin-top: 12px; }
.fkx-ws-steps .mz-colstrip.glass { --c: var(--dv-sage); border: 0; border-radius: 20px; }
.fkx-ws-steps .mz-colhead { padding: 13px 14px; }
.fkx-steps { display: grid; gap: 8px; margin: 0; padding: 0; list-style: none; }
.fkx-steps li { display: flex; gap: 8px; font-size: 13px; line-height: 1.45; color: var(--text-primary); }
.fkx-steps b { min-width: 16px; font-weight: 600; color: var(--dv-coral); }
.fkx-principle { margin: 18px 4px 0; font-size: 11.5px; line-height: 1.5; text-align: center; color: var(--text-muted); }
.wsh-bottom.fkx-wsbottom { left: 10px; right: 10px; gap: 10px; padding: 8px 2px 10px; border-top: 0;
  background: linear-gradient(180deg, transparent, rgba(25, 22, 20, 0.86) 28%); }
.fkx-gate { display: flex; align-items: center; justify-content: center; gap: 6px; margin: 0 0 8px;
  font-size: 11.5px; line-height: 1.4; text-align: center; color: var(--text-muted); }
.fkx-gate .t-ico { filter: none; }
.fkx-wsbottom .fkx-btn { width: 100%; }
.fkx-wsbottom .wsh-dock.glass { gap: 8px; padding: 12px; border-radius: 22px; }
.fkx-wsbottom .wsh-pchip { display: inline-flex; align-items: center; gap: 6px; padding: 7px 12px;
  border: 0; border-radius: 999px; font-size: 12px; font-weight: 600; color: var(--text-secondary);
  background: rgba(245, 239, 230, 0.05); box-shadow: inset 0 0 0 1px var(--divider); }
.fkx-wsbottom .wsh-pchip .t-ico { width: 18px; height: 18px; filter: none; }
.fkx-wsbottom .wsh-pchip.on { color: var(--page, #191614); background: var(--dv-lav);
  box-shadow: 0 0 12px color-mix(in srgb, var(--dv-lav) 50%, transparent); }
.fkx-wsbottom .wsh-busy { margin: 0; padding: 0 4px; font-size: 11px; color: var(--text-muted); }
.fkx-wsbottom .wsh-last { gap: 8px; padding: 8px 12px; border: 0; border-radius: 14px;
  background: rgba(245, 239, 230, 0.04); box-shadow: inset 0 0 0 1px var(--divider); }
.fkx-wsbottom .wsh-last .t-ico { filter: none; }
.fkx-wsbottom .wsh-last .tx { font-size: 12px; }
.fkx-wsbottom .wsh-last-chev { font-size: 10px; color: var(--text-muted); }
.fkx-wsbottom .wsh-composer { display: flex; align-items: center; gap: 8px; }
.fkx-wsbottom .wsh-cfield { padding: 4px 6px 4px 14px; border: 0; background: rgba(245, 239, 230, 0.05);
  box-shadow: inset 0 0 0 1px var(--divider); }
.fkx-wsbottom .wsh-cfield input { font-size: 13.5px; }
.fkx-wsbottom .wsh-cbtn { width: 40px; height: 40px; border: 0; background: rgba(245, 239, 230, 0.06);
  box-shadow: inset 0 0 0 1px var(--divider); }
.fkx-wsbottom .wsh-cbtn .t-ico { filter: none; }
.fkx-wsbottom .wsh-cbtn.send { color: var(--page, #191614); background: var(--dv-lav);
  box-shadow: 0 0 14px color-mix(in srgb, var(--dv-lav) 55%, transparent); }

@media (max-width: 360px) {
  .fkx-rdetail .fkx-actions { grid-template-columns: minmax(0, 1fr) minmax(0, 1fr); }
  .fkx-rdetail .fkx-actions > button.fkx-del { grid-column: 1 / -1; }
  .fkx-stats { grid-template-columns: repeat(2, minmax(0, 1fr)); }
  .fkx-two { grid-template-columns: minmax(0, 1fr); }
}
/* the 340px kit halo is wider than a 320px screen: clip it sideways, never scroll */
.fkx-ws-empty.uv-halo { overflow-x: clip; }
/* ── /uveg fuel receptek ── */

/* ── uveg fuel log (mezo-me75u.2) ── /fuel/log/uj, composer, pick/víz/energia sheets ── */
/* The approved look: prototypes/src/uveg-fuel-tobbi-body.html `log()` (incl. the fail state),
   `SH.kamrapick`, `SH.water`, `SH.energy` (+ its `.logh/.daychip/.modes/.mode/.viewf/.micbtn/
   .aipanel/.srcs/.lcard/.tagf/.total/.daybar/.failart/.eq/.eblk/.etile` rules). Ranking (bible
   §3.4): the mode bar, viewfinder, mic, source tiles, AI panel, line cards, usual rows and the
   total card are `.glass` in their own hue; everything inside them is flat; empty and failed
   states are dashed. The composer is scoped to `.logflow-composer`, because `.logflow-lntag`,
   `.logflow-stepbtn` and `.logflow-amtinput` are shared with the recipe Műhely, and the Kamra
   picker to `.flp-kpick`, because `.fkp-*` is shared with the Recept picker. */

/* ─ /fuel/log/uj page: the page lets the aurora through; header art is frameless (rank 1) ─ */
.flognew-page.mz-page {
  background: radial-gradient(120% 40% at 50% 0%, color-mix(in srgb, var(--dv-coral) 14%, transparent), transparent 70%); }
.flognew-page.mz-p-gold {
  background: radial-gradient(120% 40% at 50% 0%, color-mix(in srgb, var(--dv-amber) 14%, transparent), transparent 70%); }
.flognew-page .mz-backbtn {
  padding: 7px 12px; font-size: 12px; font-weight: 600; color: var(--text-secondary);
  background: rgba(245, 239, 230, 0.05); box-shadow: inset 0 0 0 1px var(--divider); }
/* The 14px inset is the page head's own (`.mz-page` children carry their own gutters). */
.flognew-head { --c: var(--dv-coral); display: flex; align-items: center; gap: 12px; padding: 8px 14px 10px; }
.flognew-head.is-past { --c: var(--dv-amber); }
.flognew-ic { flex: 0 0 auto; width: 48px; height: 48px; display: grid; place-items: center; }
.flognew-ic .t-ico {
  filter: drop-shadow(0 6px 7px rgba(0, 0, 0, 0.55)) drop-shadow(0 0 12px color-mix(in srgb, var(--c) 40%, transparent)); }
.flognew-txt { flex: 1; min-width: 0; }
.flognew-eyebrow { font: 600 9.5px/1.2 var(--ff-body); letter-spacing: 1.3px; text-transform: uppercase;
  color: var(--text-muted); }
.flognew-head.is-past .flognew-eyebrow { color: color-mix(in srgb, var(--dv-amber) 80%, var(--text-primary)); }
.flognew-title { margin-top: 2px; font-size: 22px; font-weight: 600; letter-spacing: -0.7px; line-height: 1.15;
  color: var(--text-primary); overflow-wrap: anywhere; }
.flognew-sub { margin-top: 2px; font-size: 12px; color: var(--text-secondary); font-variant-numeric: tabular-nums; }
.flognew-daychip { flex: 0 0 auto; margin-left: auto; padding: 7px 12px; border-radius: 14px; text-align: center;
  background: rgba(245, 239, 230, 0.05); box-shadow: inset 0 0 0 1px var(--divider); }
.flognew-daychip b { display: block; font-size: 14px; font-weight: 600; line-height: 1.2; color: var(--text-primary); }
.flognew-daychip small { display: block; font-size: 10.5px; color: var(--text-muted); }
.flognew-head.is-past .flognew-daychip { box-shadow: inset 0 0 0 1px color-mix(in srgb, var(--dv-amber) 45%, transparent); }
.flognew-head.is-past .flognew-daychip b { color: color-mix(in srgb, var(--dv-amber) 80%, var(--text-primary)); }
.flognew-pastnote { display: flex; gap: 8px; align-items: center; margin: 0 14px 8px; padding: 9px 12px;
  border-radius: 14px; font-size: 12px; line-height: 1.4; color: var(--text-secondary);
  background: color-mix(in srgb, var(--dv-amber) 8%, rgba(245, 239, 230, 0.03));
  box-shadow: inset 0 0 0 1px color-mix(in srgb, var(--dv-amber) 30%, transparent); }
.flognew-pastnote b { margin: 0 3px; color: color-mix(in srgb, var(--dv-amber) 80%, var(--text-primary)); }
.flognew-pastnote i { flex: none; width: 7px; height: 7px; border-radius: 50%;
  background: var(--dv-amber); box-shadow: 0 0 6px var(--dv-amber); }
/* Sticky save bar (prototype `.savebar`): the composer's action row sticks above the floating
   glass tab bar (14 + 64 + 8px air = 86px), as a blurred strip — not a card, so the glass CTA
   inside it is not glass-in-glass. */
.flognew-page .logflow-actions {
  position: sticky; bottom: 86px; z-index: 5;
  padding: 10px; border-radius: 24px;
  background: rgba(25, 22, 20, 0.82);
  -webkit-backdrop-filter: blur(14px); backdrop-filter: blur(14px);
  box-shadow: inset 0 0 0 1px var(--divider); }

/* ─ The four ways in (FuelLogModes) ─ */
.fmx-logmodes { margin: 0 0 14px; }
.fmx-modes.glass { --c: var(--dv-coral); display: grid; grid-template-columns: repeat(4, minmax(0, 1fr));
  gap: 6px; margin: 2px 0 14px; padding: 6px; border-radius: 22px; }
.fmx-mode { display: flex; flex-direction: column; align-items: center; gap: 4px; min-width: 0;
  padding: 8px 0 7px; border: 0; border-radius: 16px; background: transparent;
  font-family: inherit; font-size: 11px; font-weight: 600; color: var(--text-muted); }
.fmx-modes .fmx-mode .t-ico { filter: grayscale(0.45) brightness(0.8); }
.fmx-mode.is-active { color: var(--text-primary);
  background: radial-gradient(80% 90% at 50% 20%, color-mix(in srgb, var(--c) 26%, transparent), transparent 70%);
  box-shadow: inset 0 0 0 1px color-mix(in srgb, var(--c) 40%, transparent); }
.fmx-modes .fmx-mode.is-active .t-ico {
  filter: drop-shadow(0 4px 6px rgba(0, 0, 0, 0.5)) drop-shadow(0 0 10px color-mix(in srgb, var(--c) 55%, transparent)); }
.fmx-mode:focus-visible { outline: 2px solid var(--c); outline-offset: -2px; }

.fmx-mode-hint { margin: 12px 6px 4px; font-size: 12.5px; line-height: 1.5; color: var(--text-secondary); text-align: center; }
.fmx-inline-ico { display: inline-block; vertical-align: -3px; }
.fmx-mode-error { margin: 6px 0 0; font-size: 12px; color: var(--dv-coral); text-align: center; }
.fmx-mode-empty.uv-empty { --c: var(--dv-amber); margin: 10px 0 4px; padding: 14px; border-radius: 20px;
  font-size: 12.5px; line-height: 1.55; color: var(--text-secondary); text-align: center; }

/* Fotó: the viewfinder IS the camera input (label → hidden file input). */
.fmx-camera { text-align: center; }
.fmx-finder.glass { --c: var(--dv-coral); display: grid; place-items: center; align-content: center; gap: 6px;
  height: 230px; margin: 0; padding: 16px; border-radius: 26px; cursor: pointer; text-align: center; }
.fmx-finder.glass > .t-ico {
  filter: drop-shadow(0 12px 14px rgba(0, 0, 0, 0.5)) drop-shadow(0 0 20px color-mix(in srgb, var(--c) 35%, transparent)); }
.fmx-finder.glass > span { position: absolute; z-index: 1; width: 26px; height: 26px;
  border: 2.5px solid color-mix(in srgb, var(--c) 75%, #fff); filter: drop-shadow(0 0 6px var(--c)); }
.fmx-finder.glass > span:nth-child(1) { top: 18px; left: 18px; border-right: 0; border-bottom: 0; border-radius: 10px 0 0 0; }
.fmx-finder.glass > span:nth-child(2) { top: 18px; right: 18px; border-left: 0; border-bottom: 0; border-radius: 0 10px 0 0; }
.fmx-finder.glass > span:nth-child(3) { bottom: 18px; left: 18px; border-right: 0; border-top: 0; border-radius: 0 0 0 10px; }
.fmx-finder.glass > span:nth-child(4) { bottom: 18px; right: 18px; border-left: 0; border-top: 0; border-radius: 0 0 10px 0; }
.fmx-finder b { margin-top: 6px; font-size: 16px; font-weight: 600; color: var(--text-primary); }
.fmx-finder.glass > input { position: absolute; width: 1px; height: 1px; opacity: 0; pointer-events: none; }
.fmx-finder:focus-within { outline: 2px solid var(--c); outline-offset: 2px; }

/* Hang: one big glass disc — a real recorder, no sample sentences. Live = coral. */
.fmx-voice { text-align: center; }
.fmx-mic.glass { --c: var(--dv-lav); width: 120px; height: 120px; margin: 26px auto 0; padding: 0; border: 0;
  border-radius: 50%; display: grid; place-items: center; }
.fmx-mic.glass.is-live { --c: var(--dv-coral); }
.fmx-mic.glass:disabled { opacity: 0.45; }

/* Szokásosak: glass rows in amber, the plate in a lit well. */
.fmx-usuals { display: grid; gap: 10px; margin-top: 12px; }
.fmx-usual.glass { --c: var(--dv-amber); display: flex; align-items: center; gap: 12px; width: 100%;
  padding: 12px 14px 12px 12px; border: 0; border-radius: 20px; font-family: inherit;
  text-align: left; color: var(--text-primary); }
.fmx-usual-art.uv-well { --c: var(--dv-amber); }
.fmx-usual-copy { flex: 1; min-width: 0; }
.fmx-usual-copy strong { display: block; font-size: 15.5px; font-weight: 600; letter-spacing: -0.3px; overflow-wrap: anywhere; }
.fmx-usual-copy small { display: block; margin-top: 2px; font-size: 11.5px; line-height: 1.35; color: var(--text-secondary); }
.fmx-usual > b { flex: 0 0 auto; margin-left: auto; font-size: 20px; font-weight: 600; letter-spacing: -0.6px;
  font-variant-numeric: tabular-nums; text-align: right; color: var(--text-primary); }
.fmx-usual > b small { margin-left: 2px; font-size: 10.5px; font-weight: 500; letter-spacing: 0; color: var(--text-muted); }

/* A felismerés kudarca: amber and dashed — never red, never an error (prototype `log(fail)`). */
.fmx-failed.uv-empty { --c: var(--dv-amber); margin: 0; padding: 16px 14px 14px; border-radius: 20px; text-align: center; }
.fmx-failed-art { position: relative; display: block; width: 62px; height: 62px; margin: 0 auto; }
.fmx-failed-art .t-ico { filter: drop-shadow(0 6px 7px rgba(0, 0, 0, 0.55)); }
.fmx-failed-art i { position: absolute; right: -6px; top: -4px; width: 24px; height: 24px;
  display: grid; place-items: center; border-radius: 50%; font-style: normal; font-weight: 700; font-size: 14px;
  color: var(--page, #191614); background: var(--dv-amber); box-shadow: 0 0 10px var(--dv-amber); }
.fmx-failed small { display: block; margin-top: 10px; font: 600 9.5px/1.2 var(--ff-body); letter-spacing: 1.3px;
  text-transform: uppercase; color: var(--text-muted); }
.fmx-failed strong { display: block; margin-top: 4px; font-size: 17px; font-weight: 600; letter-spacing: -0.3px;
  line-height: 1.3; color: var(--text-primary); }
.fmx-failed p { margin: 8px 0 12px; font-size: 13.5px; line-height: 1.5; color: var(--text-secondary); }
.fmx-failed-cta { display: flex; align-items: center; justify-content: center; width: 100%; margin: 0 0 8px;
  padding: 13px 16px; border: 0; border-radius: 18px; font-family: inherit; font-size: 14.5px; font-weight: 600;
  color: var(--text-secondary); background: rgba(245, 239, 230, 0.05); box-shadow: inset 0 0 0 1px var(--divider); }
.fmx-failed-cta:last-child { margin-bottom: 0; }

/* ─ LogFlowPage: the full-page overlay (other entry points) ─ z 60: above the tab bar (40), below
   the sheets (200+) it hosts. Opaque, so it carries its own aurora wash. */
.logflow-page {
  position: absolute; inset: 0; z-index: 60; overflow-y: auto; overscroll-behavior: contain;
  color: var(--text-primary);
  background:
    radial-gradient(260px 260px at 0% 14%, rgba(94, 138, 103, 0.22), transparent 70%),
    radial-gradient(240px 240px at 100% 0%, rgba(201, 138, 58, 0.18), transparent 70%),
    radial-gradient(260px 260px at 20% 80%, rgba(109, 95, 168, 0.18), transparent 70%),
    var(--surface-page); }
.logflow-head { position: sticky; top: 0; z-index: 4; display: flex; align-items: center; gap: 8px;
  padding: 14px 20px 8px; background: rgba(25, 22, 20, 0.82);
  -webkit-backdrop-filter: blur(14px); backdrop-filter: blur(14px); }
.logflow-back.chip { padding: 7px 12px; border: 0; font-size: 12px; font-weight: 600; color: var(--text-secondary);
  background: rgba(245, 239, 230, 0.05); box-shadow: inset 0 0 0 1px var(--divider); }
.logflow-time { margin-left: auto; font-size: 11px; color: var(--text-muted); font-variant-numeric: tabular-nums; }
.logflow-body { padding: 4px 20px calc(20px + env(safe-area-inset-bottom)); }
.logflow-body > .h-display { font-size: 22px; font-weight: 600; letter-spacing: -0.7px; }

/* ─ MealComposer ─ */
.logflow-composer .logflow-eyebrow { display: block; margin: 12px 2px 8px; }
.logflow-composer .logflow-seg { display: grid; grid-template-columns: repeat(4, minmax(0, 1fr)); gap: 4px;
  margin: 0 0 6px; padding: 4px; border-radius: 16px; }
.logflow-composer .logflow-segbtn { min-width: 0; padding: 9px 0; border: 0; border-radius: 12px; background: transparent;
  font-family: inherit; font-size: 11px; font-weight: 600; letter-spacing: 0.6px; text-transform: uppercase;
  color: var(--text-muted); }
.logflow-composer .logflow-segbtn.is-on { color: var(--page, #191614); background: var(--dv-sage);
  box-shadow: 0 0 12px color-mix(in srgb, var(--dv-sage) 50%, transparent); }

/* Source tiles (prototype `.srcs` / `.cap`): glass in their own hue; 2 or 3 per row. */
.logflow-composer .logflow-srctiles { display: flex; gap: 10px; margin: 0 0 4px; }
.logflow-composer .logflow-srct.glass { display: flex; flex-direction: column; align-items: flex-start; gap: 6px;
  flex: 1 1 0; min-width: 0; min-height: 44px; padding: 13px 12px; border: 0; border-radius: 20px; cursor: pointer;
  font-family: inherit; text-align: left; color: var(--text-primary);
  transition: transform 0.15s cubic-bezier(0.3, 0.8, 0.4, 1.4); }
.logflow-composer .logflow-srct:active { transform: scale(0.96); }
.logflow-composer .logflow-srct b { font-size: 15px; font-weight: 600; letter-spacing: -0.3px; }
.logflow-composer .logflow-srct small { font-size: 11.5px; line-height: 1.35; color: var(--text-secondary); }
.logflow-composer .logflow-srct.glass.on {
  box-shadow: 0 16px 30px -16px rgba(0, 0, 0, 0.75), 0 0 26px -2px color-mix(in srgb, var(--c) 55%, transparent),
    inset 0 0 0 1.5px color-mix(in srgb, var(--c) 70%, transparent); }

/* The AI panel (prototype `.aipanel`): lavender glass; its field and chips are flat. */
.logflow-composer .logflow-aipanel.glass { --c: var(--dv-lav); display: grid; gap: 10px; margin-top: 12px;
  padding: 12px; border-radius: 22px; }
.logflow-composer .logflow-aipanel textarea { width: 100%; min-height: 64px; padding: 11px 13px; border: 0;
  border-radius: 13px; resize: none; font-family: inherit; font-size: 14px; color: var(--text-primary);
  background: rgba(245, 239, 230, 0.05); box-shadow: inset 0 0 0 1px var(--divider); }
.logflow-composer .logflow-aipanel textarea::placeholder { color: var(--text-muted); }
.logflow-composer .logflow-airow { display: flex; flex-wrap: wrap; align-items: center; gap: 8px; }
.logflow-composer .logflow-aichip { --c: var(--dv-lav); display: inline-flex; align-items: center; gap: 6px;
  padding: 7px 12px; border: 0; border-radius: 999px; cursor: pointer; font-family: inherit;
  font-size: 12px; font-weight: 600; white-space: nowrap; color: var(--text-secondary);
  background: rgba(245, 239, 230, 0.05); box-shadow: inset 0 0 0 1px var(--divider); }
.logflow-composer .logflow-aichip .t-ico { filter: none; }
.logflow-composer .logflow-aichip:disabled { opacity: 0.45; cursor: default; }
.logflow-composer .logflow-aichip.is-live { --c: var(--dv-coral); color: var(--page, #191614); background: var(--c);
  box-shadow: 0 0 12px color-mix(in srgb, var(--c) 50%, transparent); }
.logflow-composer .logflow-airun { margin-left: auto; color: var(--page, #191614); background: var(--c);
  box-shadow: 0 0 12px color-mix(in srgb, var(--c) 50%, transparent); }
.logflow-composer .logflow-aiphoto { display: inline-flex; align-items: center; gap: 6px; min-width: 0;
  padding: 4px 8px 4px 4px; border-radius: 999px; font-size: 12px; color: var(--text-secondary);
  background: rgba(245, 239, 230, 0.05); box-shadow: inset 0 0 0 1px var(--divider); overflow-wrap: anywhere; }
.logflow-composer .logflow-aiphoto img { width: 26px; height: 26px; object-fit: cover; border-radius: 50%; flex: none; }
.logflow-composer .logflow-aiphoto button { display: grid; place-items: center; padding: 2px; border: 0;
  background: none; color: var(--text-muted); }
.logflow-composer .logflow-aierr { margin: 0; font-size: 12px; color: var(--dv-coral); }
.logflow-composer .logflow-aihint { margin: 0; font-size: 11px; line-height: 1.4; color: var(--text-muted); }
.logflow-composer .logflow-aibusy.glass { display: flex; align-items: center; justify-content: center; gap: 9px;
  font-size: 13px; font-weight: 600; color: color-mix(in srgb, var(--c) 78%, var(--text-primary)); }
.logflow-composer .logflow-aibusy .np-twinkle { flex: none; width: 10px; height: 10px; border-radius: 50%;
  background: var(--dv-lav); box-shadow: 0 0 10px var(--dv-lav); }

/* TÉTELEK header + the empty state (dashed, rank 4). */
.logflow-composer .logflow-sec { display: flex; align-items: center; gap: 9px; margin: 18px 2px 10px; }
.logflow-composer .logflow-sec-n { font-size: 12px; font-weight: 600; font-variant-numeric: tabular-nums;
  color: var(--text-secondary); }
.logflow-composer .logflow-sec-rule { flex: 1; height: 1px; background: linear-gradient(90deg, var(--divider), transparent); }
.logflow-composer .logflow-empty.uv-empty { padding: 14px; border-radius: 20px; text-align: center;
  font-size: 12.5px; line-height: 1.5; color: var(--text-secondary); }

/* Line cards (prototype `.lcard`): glass in the line's dominant-macro hue. */
.logflow-composer .logflow-lines { display: grid; grid-template-columns: minmax(0, 1fr); gap: 10px; }
.logflow-composer .logflow-lines > * { min-width: 0; }
.logflow-composer .logflow-lncard.glass { padding: 12px 14px; border-radius: 20px; }
.logflow-composer .logflow-lntop { display: flex; align-items: center; gap: 8px; }
.logflow-composer .logflow-lnname { flex: 1; min-width: 0; display: flex; flex-wrap: wrap; align-items: center; gap: 6px 8px; }
.logflow-composer .logflow-lnlabel { font-size: 15px; font-weight: 600; letter-spacing: -0.2px; color: var(--text-primary);
  overflow-wrap: anywhere; }
.logflow-composer .logflow-lntag { display: inline-flex; align-items: center; gap: 4px; flex: none;
  padding: 3px 9px 3px 5px; border-radius: 999px; font-size: 10.5px; font-weight: 500; letter-spacing: 0;
  text-transform: none; color: var(--text-secondary);
  background: rgba(245, 239, 230, 0.05); box-shadow: inset 0 0 0 1px var(--divider); }
.logflow-composer .logflow-lntag .t-ico { filter: none; }
.logflow-composer .logflow-lntag .logflow-lntag-ai { margin-left: 1px; }
.logflow-composer .logflow-lnx { flex: none; width: 28px; height: 28px; display: grid; place-items: center;
  padding: 0; border: 0; border-radius: 50%; color: var(--text-secondary);
  background: rgba(245, 239, 230, 0.06); box-shadow: inset 0 0 0 1px var(--divider); }
.logflow-composer .logflow-lnstep { display: flex; align-items: center; gap: 8px; margin-top: 8px; }
.logflow-composer .logflow-stepbtn { flex: none; width: 34px; height: 34px; min-width: 34px; border: 0; border-radius: 50%;
  display: grid; place-items: center; font-size: 18px; color: var(--text-primary); cursor: pointer;
  background: rgba(245, 239, 230, 0.06); box-shadow: inset 0 0 0 1px var(--divider); }
.logflow-composer .logflow-amtinput { width: 58px; padding: 6px 2px; border: 0; border-radius: 10px; text-align: center;
  font-family: inherit; font-size: 18px; font-weight: 600; font-variant-numeric: tabular-nums; color: var(--text-primary);
  background: transparent; box-shadow: inset 0 0 0 1px var(--divider); }
.logflow-composer .logflow-lnunit { font-size: 12px; color: var(--text-secondary); }
.logflow-composer .logflow-lnkcal { margin-left: auto; flex: none; text-align: right; white-space: nowrap; }
.logflow-composer .logflow-lnkcal b { font-size: 18px; font-weight: 600; letter-spacing: -0.4px; font-variant-numeric: tabular-nums; }
.logflow-composer .logflow-lnkcal small { margin-left: 3px; font-size: 10.5px; color: var(--text-muted); }
/* the macro strip (prototype `.mm`): three flat cells, each in its macro's hue */
.logflow-composer .logflow-lnmac { display: flex; gap: 6px; margin-top: 8px; }
.logflow-composer .logflow-lnmac span { flex: 1; min-width: 0; padding: 4px 2px 3px; border-radius: 10px; text-align: center;
  background: rgba(245, 239, 230, 0.04); box-shadow: inset 0 0 0 1px var(--divider); }
.logflow-composer .logflow-lnmac b { display: block; font-size: 12px; font-weight: 600; font-variant-numeric: tabular-nums; }
.logflow-composer .logflow-lnmac .mz-c-coral b { color: var(--macro-protein); }
.logflow-composer .logflow-lnmac .mz-c-gold b { color: var(--macro-carbs); }
.logflow-composer .logflow-lnmac .mz-c-lav b { color: var(--macro-fat); }
.logflow-composer .logflow-lnmac small { font-size: 10px; color: var(--text-muted); }
.logflow-composer .logflow-lnnutri { margin-top: 6px; }
.logflow-composer .logflow-lnnote { display: flex; align-items: flex-start; gap: 6px; margin: 8px 0 0;
  font-size: 11.5px; line-height: 1.4; color: var(--text-secondary); }
.logflow-composer .logflow-lnnote .t-ico { flex: none; margin-top: 1px; filter: none; }

/* Recipe fine-tuning inside a line card — flat (RecipeOverrideRow). */
.logflow-composer .logflow-tune { margin-top: 10px; padding-top: 8px; border-top: 1px solid var(--divider); }
.logflow-composer .logflow-tune-head { display: flex; align-items: center; justify-content: space-between; width: 100%;
  padding: 2px 0; border: 0; background: none; font-family: inherit; cursor: pointer; }
.logflow-composer .logflow-tune-toggle { font-size: 11.5px; font-weight: 600; color: var(--dv-coral); }
.logflow-composer .logflow-tune-note { margin-top: 5px; font-size: 11px; color: var(--text-muted); }
.logflow-composer .logflow-tune-reset { margin-top: 8px; padding: 6px 12px; border: 0; border-radius: 999px;
  font-family: inherit; font-size: 11.5px; font-weight: 600; color: var(--dv-coral);
  background: rgba(245, 239, 230, 0.05); box-shadow: inset 0 0 0 1px var(--divider); }
.flp-ovr { display: flex; align-items: center; gap: 8px; margin-top: 6px; padding: 7px 8px; border-radius: 12px;
  background: rgba(245, 239, 230, 0.03); }
.flp-ovr.is-changed { background: color-mix(in srgb, var(--dv-amber) 9%, rgba(245, 239, 230, 0.03));
  box-shadow: inset 0 0 0 1px color-mix(in srgb, var(--dv-amber) 30%, transparent); }
.flp-ovr-name { flex: 1; min-width: 0; font-size: 12.5px; color: var(--text-secondary); overflow-wrap: anywhere; }
.flp-ovr.is-changed .flp-ovr-name { font-weight: 600; color: var(--text-primary); }
.flp-ovr-mod { margin-left: 6px; padding: 1px 6px; border-radius: 999px; font-size: 9.5px; font-weight: 700;
  letter-spacing: 0.8px; color: var(--page, #191614); background: var(--dv-amber); }
.flp-ovr-was { margin-left: 6px; font-size: 11px; color: var(--text-muted); text-decoration: line-through; }
.flp-ovr-step { display: inline-flex; align-items: center; flex: none; border-radius: 999px;
  background: rgba(245, 239, 230, 0.05); box-shadow: inset 0 0 0 1px var(--divider); }
.flp-ovr-step > button { min-width: 28px; height: 28px; padding: 0 4px; border: 0; background: none;
  display: grid; place-items: center; font-family: inherit; font-size: 15px; color: var(--text-primary); }
.flp-ovr-step > button.flp-ovr-amt { min-width: 30px; font-size: 12.5px; font-weight: 600; font-variant-numeric: tabular-nums; }
.flp-ovr-step input { width: 42px; padding: 3px 0; border: 0; border-radius: 8px; text-align: center; font-family: inherit;
  font-size: 12.5px; font-weight: 600; color: var(--text-primary); background: rgba(245, 239, 230, 0.06);
  box-shadow: inset 0 0 0 1px var(--dv-amber); }
.flp-ovr-unit { padding: 0 8px 0 1px; font-size: 10.5px; color: var(--text-muted); }
.flp-ovr-kcal { flex: none; min-width: 34px; text-align: right; font-size: 12px; font-variant-numeric: tabular-nums;
  color: var(--text-muted); }
.flp-ovr-reset { flex: none; display: grid; place-items: center; padding: 3px; border: 0; background: none;
  color: var(--text-muted); }

/* EZ AZ ÉTKEZÉS (prototype `.total`): lavender glass; the cells are flat, numerals in their hue. */
.logflow-composer .logflow-total.glass { --c: var(--dv-lav); margin-top: 14px; padding: 16px; border-radius: 22px; }
.logflow-composer .logflow-total-head { display: flex; align-items: baseline; justify-content: space-between; }
.logflow-composer .logflow-totname { margin-top: 4px; font-size: 17px; font-weight: 600; letter-spacing: -0.3px;
  color: var(--text-primary); display: -webkit-box; -webkit-line-clamp: 1; -webkit-box-orient: vertical; overflow: hidden; }
.logflow-composer .logflow-total-cells.mz-mcells { display: grid; grid-template-columns: repeat(4, minmax(0, 1fr));
  gap: 8px; margin: 12px 0; }
.logflow-composer .logflow-total-cells span { padding: 0; border-radius: 0; background: none; box-shadow: none; text-align: center; }
.logflow-composer .logflow-total-cells b { font-size: 22px; font-weight: 600; letter-spacing: -0.8px; }
.logflow-composer .logflow-total-cells small { font-size: 10px; font-weight: 500; letter-spacing: 0; text-transform: none;
  color: var(--text-muted); opacity: 1; }
.logflow-composer .logflow-total-cells .mz-c-sage b { color: color-mix(in srgb, var(--dv-amber) 80%, var(--text-primary)); }
.logflow-composer .logflow-total-cells .mz-c-coral b { color: color-mix(in srgb, var(--macro-protein) 80%, var(--text-primary)); }
.logflow-composer .logflow-total-cells .mz-c-gold b { color: color-mix(in srgb, var(--macro-carbs) 80%, var(--text-primary)); }
.logflow-composer .logflow-total-cells .mz-c-lav b { color: color-mix(in srgb, var(--macro-fat) 80%, var(--text-primary)); }
.logflow-composer .logflow-total-nutri { margin-top: 6px; }
.logflow-composer .logflow-total-day { margin-top: 10px; padding-top: 10px; border-top: 1px solid var(--divider); }
.logflow-composer .logflow-total-dayline { display: flex; justify-content: space-between; gap: 8px; flex-wrap: wrap;
  font-size: 12px; font-variant-numeric: tabular-nums; color: var(--text-secondary); }
.logflow-composer .logflow-total-dayline b { font-weight: 600; color: var(--text-primary); }
.logflow-composer .logflow-total-add { color: color-mix(in srgb, var(--dv-lav) 80%, var(--text-primary)); }
.logflow-composer .logflow-daybar { display: flex; height: 7px; margin-top: 8px; border-radius: 4px; overflow: hidden;
  background: rgba(245, 239, 230, 0.07); }
.logflow-composer .logflow-daybar b { background: var(--dv-sage); box-shadow: 0 0 8px var(--dv-sage); }
.logflow-composer .logflow-daybar i { background: var(--dv-lav); box-shadow: 0 0 8px var(--dv-lav); }

/* Actions: Mégse flat, the log CTA sage glass (prototype `.savebar`). */
.logflow-composer .logflow-actions .cta-ghost { padding: 13px 16px; border: 0; border-radius: 18px;
  font-size: 14.5px; font-weight: 600; color: var(--text-secondary);
  background: rgba(245, 239, 230, 0.05); box-shadow: inset 0 0 0 1px var(--divider); }
.logflow-composer .logflow-save.glass { --c: var(--dv-sage); width: 100%; padding: 13px 16px; border: 0; border-radius: 18px;
  gap: 8px; font-size: 14.5px; font-weight: 600; color: var(--text-primary); }
.logflow-composer .logflow-save.glass:disabled { opacity: 0.45; }

/* A8 · A9: the edit time field and the two-step delete. */
.logflow-composer .fmx-edit-time.uv-flat { display: flex; align-items: center; justify-content: space-between; gap: 10px;
  margin: 12px 0 0; padding: 10px 12px; border-radius: 16px; }
.logflow-composer .fmx-edit-time .label-mono { font: 600 9.5px/1.2 var(--ff-body); letter-spacing: 1.3px; color: var(--text-muted); }
.logflow-composer .fmx-edit-time input { padding: 7px 10px; border: 0; border-radius: 11px; font-family: inherit; font-size: 14px;
  color: var(--text-primary); background: rgba(245, 239, 230, 0.06); box-shadow: inset 0 0 0 1px var(--divider);
  color-scheme: dark; }
.logflow-composer .fmx-delete { margin: 14px 0 4px; padding-top: 12px; border-top: 1px solid var(--divider); text-align: center; }
.logflow-composer .fmx-delete > button { padding: 10px 16px; border: 0; border-radius: 14px; font-family: inherit;
  font-size: 12.5px; color: var(--text-secondary); background: rgba(245, 239, 230, 0.05); box-shadow: inset 0 0 0 1px var(--divider); }
.logflow-composer .fmx-delete p { margin: 0 0 10px; font-size: 12.5px; color: var(--text-secondary); }
.logflow-composer .fmx-delete .fmx-delete-yes { margin-right: 8px; font-weight: 600; color: #FFB39C;
  background: rgba(255, 126, 92, 0.07); box-shadow: inset 0 0 0 1px rgba(255, 126, 92, 0.35); }

/* ─ Shared sheet bits of this block: the round close button ─ */
.flp-x { flex: none; width: 34px; height: 34px; display: grid; place-items: center; padding: 0; border: 0;
  border-radius: 50%; color: var(--text-secondary);
  background: rgba(245, 239, 230, 0.06); box-shadow: inset 0 0 0 1px var(--divider); }

/* ─ KamraPickSheet (prototype `SH.kamrapick`) — flat rows with the category spine ─ */
.flp-kpick { --c: var(--dv-amber); }
.flp-kpick .flp-kpick-head { align-items: flex-start; gap: 12px; margin-bottom: 12px; }
.flp-kpick .flp-kpick-head > .t-ico {
  filter: drop-shadow(0 6px 7px rgba(0, 0, 0, 0.55)) drop-shadow(0 0 10px color-mix(in srgb, var(--c) 40%, transparent)); }
.flp-kpick .flp-search { align-items: center; margin-bottom: 10px; padding: 11px 14px; border-radius: 16px;
  background: rgba(245, 239, 230, 0.05); box-shadow: inset 0 0 0 1px var(--divider); }
.flp-kpick .flp-search input { flex: 1; min-width: 0; border: 0; background: none; font-family: inherit;
  font-size: 13.5px; color: var(--text-primary); }
.flp-kpick .flp-search input::placeholder { color: var(--text-muted); }
.flp-kpick .fkp-chip { min-height: 32px; padding: 6px 12px; border: 0; font-size: 12px; font-weight: 600;
  color: var(--text-secondary); background: rgba(245, 239, 230, 0.05); box-shadow: inset 0 0 0 1px var(--divider); }
.flp-kpick .fkp-cdot { box-shadow: 0 0 6px var(--cc); }
.flp-kpick .fkp-chip.is-on { color: var(--page, #191614); background: var(--cc);
  box-shadow: 0 0 12px color-mix(in srgb, var(--cc) 50%, transparent); }
.flp-kpick .fkp-chip.is-on .fkp-cdot { background: var(--page, #191614); box-shadow: none; }
/* flex: none stays (layout.spec: rows must not squash inside the max-height list, mezo-bq2t). */
.flp-kpick .fkp-item { flex: none; position: relative; overflow: hidden; padding: 10px 12px 10px 14px; border-radius: 14px;
  background: rgba(245, 239, 230, 0.04);
  box-shadow: inset 3px 0 0 var(--kc), inset 0 0 0 1px var(--divider); }
.flp-kpick .fkp-item::before { content: none; }
.flp-kpick .fkp-name { font-size: 14px; font-weight: 600; color: var(--text-primary); overflow-wrap: anywhere; }
.flp-kpick .fkp-meta { margin-top: 3px; align-items: center; font-size: 10px; color: var(--text-muted); }
.flp-kpick .fkp-kcell { padding: 0 2px; border-radius: 0; background: none; box-shadow: none; text-align: right; }
.flp-kpick .fkp-kcell b { font-size: 16px; font-weight: 600; letter-spacing: -0.4px; }
.flp-kpick .fkp-kcell small { font-size: 9.5px; font-weight: 500; letter-spacing: 0; text-transform: none; color: var(--text-muted); }
.flp-kpick .fkp-add { flex: none; width: 34px; height: 34px; display: grid; place-items: center; padding: 0; border: 0;
  border-radius: 999px; color: var(--page, #191614); background: var(--c);
  box-shadow: 0 0 12px color-mix(in srgb, var(--c) 50%, transparent); }
.flp-kpick .fkp-add.is-added { color: color-mix(in srgb, var(--c) 80%, var(--text-primary)); cursor: default;
  background: rgba(245, 239, 230, 0.05); box-shadow: inset 0 0 0 1px var(--divider); }
.flp-kpick .fkp-none.uv-empty { margin: 4px 0; padding: 18px 12px; border-radius: 16px; text-align: center;
  font-size: 12px; color: var(--text-secondary); }

/* ─ WaterLogSheet (prototype `SH.water`) — only its own chips + field; the capture header and
   hero are the shared capture system's (slice U3). ─ */
.flp-wchip { --c: var(--dv-sky); display: inline-flex; align-items: center; padding: 9px 16px; border: 0;
  border-radius: 999px; font-family: inherit; font-size: 13px; font-weight: 600; white-space: nowrap;
  color: var(--text-secondary); background: rgba(245, 239, 230, 0.05); box-shadow: inset 0 0 0 1px var(--divider); }
.flp-wchip.is-on { color: var(--page, #191614); background: var(--c);
  box-shadow: 0 0 12px color-mix(in srgb, var(--c) 50%, transparent); }
.flp-winput { width: 120px; padding: 11px 13px; border: 0; border-radius: 13px; text-align: right;
  font-family: inherit; font-size: 14px; font-weight: 600; font-variant-numeric: tabular-nums; color: var(--text-primary);
  background: rgba(245, 239, 230, 0.05); box-shadow: inset 0 0 0 1px var(--divider); }
.flp-winput::placeholder { color: var(--text-muted); font-weight: 400; }
.flp-wunit { font-size: 11.5px; font-weight: 600; color: var(--text-muted); }

/* ─ EnergyBreakdownSheet (prototype `SH.energy`) — no glass in the sheet: a flat equation cell,
   hue-tinted section blocks (the opened one lit), flat tiles with 3D icons. ─ */
.flp-eh { display: flex; align-items: flex-start; gap: 12px; margin-bottom: 8px; }
.flp-eh > .t-ico {
  filter: drop-shadow(0 6px 7px rgba(0, 0, 0, 0.55)) drop-shadow(0 0 10px color-mix(in srgb, var(--dv-sage) 40%, transparent)); }
.flp-eh h2 { margin: 2px 0 0; font-size: 21px; font-weight: 600; letter-spacing: -0.6px; line-height: 1.2; color: var(--text-primary); }
.flp-elead { margin: 0 0 12px; font-size: 13px; line-height: 1.45; color: var(--text-secondary); }
.flp-eq { display: flex; align-items: center; justify-content: space-between; gap: 4px; flex-wrap: wrap;
  margin: 0 0 4px; padding: 12px; border-radius: 16px; text-align: center; font-size: 12px; color: var(--text-muted);
  background: rgba(245, 239, 230, 0.04); box-shadow: inset 0 0 0 1px var(--divider); }
.flp-eq .t .v { font-size: 17px; font-weight: 600; font-variant-numeric: tabular-nums; color: var(--text-primary); }
.flp-eq .t .k { font-size: 11px; color: var(--text-muted); }
.flp-eq .t.res .v { color: var(--dv-sage); text-shadow: 0 0 12px color-mix(in srgb, var(--dv-sage) 60%, transparent); }
.flp-eq .op { color: var(--text-muted); font-size: 15px; }
.flp-eblk { margin-top: 12px; padding: 12px; border-radius: 18px;
  background: color-mix(in srgb, var(--c) 7%, rgba(245, 239, 230, 0.02));
  box-shadow: inset 0 0 0 1px color-mix(in srgb, var(--c) 30%, transparent); }
.flp-eblk.is-hl { box-shadow: inset 0 0 0 1.5px var(--c), 0 0 18px -6px var(--c); }
.flp-esh { display: flex; align-items: baseline; gap: 8px; margin-bottom: 8px; }
.flp-estit { font: 600 9.5px/1.3 var(--ff-body); letter-spacing: 1.3px; text-transform: uppercase;
  color: color-mix(in srgb, var(--c) 80%, var(--text-primary)); }
.flp-esamt { margin-left: auto; font-size: 17px; font-weight: 600; letter-spacing: -0.4px; font-variant-numeric: tabular-nums;
  color: color-mix(in srgb, var(--c) 80%, var(--text-primary)); }
.flp-etiles { display: flex; flex-wrap: wrap; align-items: center; gap: 6px; }
.flp-etiles .op { color: var(--text-muted); font-size: 16px; }
.flp-etile { flex: 1 1 84px; min-width: 84px; display: flex; flex-direction: column; align-items: center; gap: 3px;
  padding: 8px 4px; border-radius: 13px; text-align: center; font-size: 10.5px; color: var(--text-secondary);
  background: rgba(245, 239, 230, 0.04); }
.flp-etile .t-ico { filter: drop-shadow(0 4px 5px rgba(0, 0, 0, 0.5)); }
.flp-etile-val { font-size: 14px; font-weight: 600; font-variant-numeric: tabular-nums; color: var(--text-primary); }
.flp-etile-val .u { margin-left: 2px; font-size: 10px; font-weight: 500; color: var(--text-muted); }
.flp-etile-nm { font-size: 10.5px; color: var(--text-secondary); overflow-wrap: anywhere; }
.flp-etile-sub { font-size: 9.5px; color: var(--text-muted); }
.flp-etile.is-result { background: none; box-shadow: inset 0 0 0 1.5px color-mix(in srgb, var(--c) 45%, transparent); }
.flp-etile.is-result .flp-etile-val { font-size: 18px; color: color-mix(in srgb, var(--c) 80%, var(--text-primary)); }
.flp-ewhy { margin: 8px 0 0; font-size: 12px; line-height: 1.45; color: var(--text-secondary); }
.flp-ewhy b { font-weight: 600; color: var(--text-primary); }

/* ─ Motion: the live mic breathes (feedback, not decoration); reduced motion = still ─ */
@keyframes flp-mic-breathe {
  0%, 100% { box-shadow: 0 16px 30px -16px rgba(0, 0, 0, 0.75), 0 0 26px -6px color-mix(in srgb, var(--dv-coral) 40%, transparent),
    inset 0 1px 0 rgba(255, 244, 230, 0.10); }
  50% { box-shadow: 0 16px 30px -16px rgba(0, 0, 0, 0.75), 0 0 34px 2px color-mix(in srgb, var(--dv-coral) 55%, transparent),
    inset 0 1px 0 rgba(255, 244, 230, 0.10); }
}
@media (prefers-reduced-motion: no-preference) {
  .fmx-mic.glass.is-live { animation: flp-mic-breathe 2.6s ease-in-out infinite; }
}
@media (prefers-reduced-motion: reduce) {
  .fmx-mic.glass, .fmx-mic.glass.is-live { animation: none; }
  .logflow-composer .logflow-srct { transition: none; }
  .fmx-finder.glass > .t-ico { animation: none; }
}
/* ── /uveg fuel log ── */

/* ── uveg fuel stack (mezo-me75u.2) ── Kiegészítők, protokoll, új elem, gyógyszer, stack sheets ── */
/* Reference: prototypes/uveg-fuel-tobbi.html — `stack()`, `openItem()`, `protokoll()`, `stackUj()`,
   `gyogyszer()`, `SH.stackitem`, `SH.dose`, `SH.medform` (owner OK 2026-09-23). The older
   `── fuel-stack (` and `.fmd-*` blocks stay underneath as the fallback their guards pin; every
   rule here out-ranks them (U1 rule 1: `.glass` wins ties, so geometry is restated on
   `.<thing>.glass`). Ranking (bible §3.4): the ring is a frameless halo; KÖVETKEZIK, the time
   bands, the zone groups, the doors, the medication card and the item box are glass, ONE
   accent each via `--c`; rows, chips, ticks and fields inside them are flat; empty/free
   states are dashed. The sheets are one glass surface each, nothing glass inside. */

/* the aurora shows through: the Kiegészítők family drops the opaque tone ground */
.fsx-page.mz-page, .stk-detail-page.mz-page, .fmd-page.mz-page { background: transparent; }
.fsx-page .fsx-note, .stk-detail-body .fsx-note { font-size: 11.5px; color: var(--text-muted); }

/* ── Kiegészítők hub: the frameless ring halo + KÖVETKEZIK glass ── */
.fsx-page .fsx-hero { display: grid; gap: 14px; padding: 0; border-radius: 0; background: none; overflow: visible; }
.fsx-hero-halo { --c: var(--dv-sage); --c2: var(--dv-lav); display: grid; justify-items: center; gap: 4px; padding: 8px 0 0; text-align: center; }
.fsx-hero-halo .fsx-overline { font: 600 9.5px/1.2 var(--ff-body); letter-spacing: 1.3px; color: var(--text-muted); }
.fsx-gauge.fsx-ring { width: 170px; height: 170px; flex: none; margin: 4px auto 0; }
.fsx-gauge.fsx-ring svg { width: 100%; height: 100%; }
.fsx-gauge.fsx-ring circle { stroke-width: 8; }
.fsx-gauge .fsx-ring-track.uv-ring-track { stroke: rgba(245, 239, 230, 0.07); }
.fsx-gauge .fsx-ring-progress.uv-ring-prog { --c: var(--dv-sage); stroke: var(--c); stroke-dasharray: var(--fsx-progress) 100; }
.fsx-gauge > .fsx-gauge-inner {
  position: absolute; inset: 20px; z-index: 0; border-radius: 50%;
  background: radial-gradient(circle at 35% 30%, #3A332D, #1E1B18);
  box-shadow: inset 0 1px 0 rgba(255, 244, 230, 0.08),
    inset 0 -10px 20px -10px color-mix(in srgb, var(--dv-sage) 45%, transparent),
    0 12px 24px -12px #000;
}
.fsx-gauge.fsx-ring strong { font-family: var(--ff-display); font-size: 46px; font-weight: 300; letter-spacing: -2.5px; color: var(--text-primary); }
.fsx-gauge.fsx-ring strong small { font-size: 18px; font-weight: 300; letter-spacing: -0.5px; color: var(--text-muted); }
.fsx-gauge.fsx-ring b { margin-top: 4px; font-size: 9.5px; font-weight: 600; letter-spacing: 1.3px; color: var(--text-muted); }
.fsx-next.glass {
  display: flex; align-items: center; gap: 12px; width: 100%; min-height: 64px; margin: 0;
  padding: 12px 12px 12px 14px; border: 0; border-radius: 22px; text-align: left; color: var(--text-primary);
}
.fsx-next.glass .fsx-next-copy small { font-size: 9.5px; font-weight: 600; letter-spacing: 1.3px; color: color-mix(in srgb, var(--c) 75%, var(--text-primary)); }
.fsx-next.glass .fsx-next-copy strong { margin-top: 2px; font-size: 17px; font-weight: 600; letter-spacing: -0.4px; }
.fsx-next.glass .fsx-next-copy em { font-size: 11.5px; color: var(--text-secondary); }
.fsx-next.glass > b {
  flex: 0 0 auto; padding: 10px 14px; border-radius: 14px;
  font-size: 12px; font-weight: 700; letter-spacing: 0.8px; color: #191614;
  background: var(--c); box-shadow: 0 0 14px color-mix(in srgb, var(--c) 60%, transparent);
}
.fsx-done.uv-empty {
  --c: var(--dv-sage); display: flex; flex-direction: column; align-items: center; gap: 6px;
  margin: 0; padding: 14px 16px; border-radius: 20px; text-align: center;
  font-size: 13px; line-height: 1.5; color: var(--text-secondary);
}

/* the time bands: glass in the band's own hue; the due one glows harder, a finished one dims */
.fsx-band.glass { margin: 0; padding: 12px 12px 6px; border: 0; border-radius: 22px; }
.fsx-band.glass.is-due {
  border: 0;
  background:
    radial-gradient(120% 90% at 0% 0%, color-mix(in srgb, var(--c) 28%, transparent), transparent 62%),
    linear-gradient(160deg, rgba(52, 46, 41, 0.72), rgba(30, 27, 24, 0.60));
  box-shadow: 0 16px 30px -16px rgba(0, 0, 0, 0.75),
    0 0 34px -4px color-mix(in srgb, var(--c) 45%, transparent),
    inset 0 1px 0 rgba(255, 244, 230, 0.10),
    inset 0 -14px 26px -18px color-mix(in srgb, var(--c) 55%, transparent);
}
.fsx-band.glass.is-complete { opacity: 0.72; }
.fsx-band.glass .fsx-band-head { gap: 10px; padding: 0 2px 6px; }
.fsx-band.glass .fsx-band-head strong { flex: 1; min-width: 0; font-family: var(--ff-body); font-size: 16px; font-weight: 600; letter-spacing: 0; }
.fsx-band.glass .fsx-band-count { font-size: 13px; color: color-mix(in srgb, var(--c) 75%, var(--text-primary)); }
.fsx-band.glass .fsx-row { gap: 8px; min-height: 52px; padding: 4px 2px; border-top: 1px solid var(--divider); }
/* 44px hit area, a 30px round tick inside it (layout.spec keeps the 44px floor) */
.fsx-band.glass .fsx-check, .fsx-band.glass .fsx-row.is-done .fsx-check {
  width: 44px; height: 44px; margin-left: -6px; background: none; box-shadow: none; color: transparent;
}
.fsx-band.glass .fsx-check > span {
  width: 30px; height: 30px; border-radius: 50%; display: grid; place-items: center;
  font-size: 14px; font-weight: 700; color: #191614;
  box-shadow: inset 0 0 0 1.5px color-mix(in srgb, var(--c) 55%, transparent);
  transition: background 0.2s, box-shadow 0.2s;
}
.fsx-band.glass .fsx-row.is-done .fsx-check > span { background: var(--c); box-shadow: 0 0 10px color-mix(in srgb, var(--c) 60%, transparent); }
.fsx-band.glass .fsx-check:focus-visible { outline: none; }
.fsx-band.glass .fsx-check:focus-visible > span { outline: 2px solid var(--c); outline-offset: 2px; }
.fsx-band.glass .fsx-row-main { gap: 10px; color: var(--text-primary); }
.fsx-band.glass .fsx-row-copy strong { font-size: 14px; font-weight: 600; }
.fsx-band.glass .fsx-row-copy small { margin-top: 1px; font-size: 11px; color: var(--text-secondary); }
.fsx-band.glass .fsx-row.is-done .fsx-row-copy strong { color: var(--text-secondary); }
.fsx-band.glass .fsx-row-main > b { font-size: 20px; color: var(--text-muted); }

.fsx-empty.uv-empty { --c: var(--dv-sage); border-radius: 22px; box-shadow: none; }
.fsx-empty.uv-empty strong { font-family: var(--ff-display); font-size: 20px; font-weight: 600; letter-spacing: -0.4px; }
.fsx-empty.uv-empty p { font-size: 13px; line-height: 1.5; color: var(--text-secondary); }

/* the two doors (prototype `.cap.glass`) and the Gyógyszer row */
.fsx-posters { display: grid; grid-template-columns: repeat(2, minmax(0, 1fr)); gap: 10px; min-width: 0; }
.fsx-posters > * { min-width: 0; }
.fsx-poster.glass {
  display: flex; flex-direction: column; align-items: flex-start; gap: 8px; width: 100%; min-height: 44px;
  padding: 14px; border: 0; border-radius: 20px; text-align: left; color: var(--text-primary);
}
.fsx-poster.glass.is-protocol { --c: var(--dv-amber); }
.fsx-poster.glass.is-setup { --c: var(--dv-lav); }
.fsx-poster.glass > .fsx-poster-go {
  position: absolute; top: 12px; right: 12px; width: 24px; height: 24px; border-radius: 50%;
  display: grid; place-items: center; font-size: 14px; font-weight: 500;
  background: rgba(245, 239, 230, 0.07); color: color-mix(in srgb, var(--c) 70%, #fff);
}
.fsx-poster.glass > strong { font-size: 15px; font-weight: 600; letter-spacing: -0.3px; line-height: 1.25; }
.fsx-poster.glass > small { font-size: 11.5px; line-height: 1.35; color: var(--text-secondary); }
.fsx-poster.glass.is-row { flex-direction: row; align-items: center; gap: 12px; padding: 12px 14px 12px 12px; }
.fsx-poster.glass.is-row .fsx-poster-copy { flex: 1; min-width: 0; }
.fsx-poster.glass.is-row .fsx-poster-copy strong { font-family: var(--ff-body); font-size: 15.5px; font-weight: 600; letter-spacing: -0.3px; }
.fsx-poster.glass.is-row .fsx-poster-copy small { font-size: 11.5px; color: var(--text-secondary); }
.fsx-poster.glass.is-row > b { font-size: 18px; color: var(--text-muted); }
.fsx-quiet.glass {
  --c: var(--dv-sky); gap: 12px; padding: 12px 14px 12px 12px; border: 0; border-radius: 20px; color: var(--text-primary);
}
.fsx-quiet.glass strong { font-size: 15.5px; font-weight: 600; letter-spacing: -0.3px; }
.fsx-quiet.glass small { font-size: 11.5px; color: var(--text-secondary); }
.fsx-quiet.glass > b { font-size: 18px; color: var(--text-muted); }

/* ── the item box (GlassBox): the ONE glass; everything inside is flat ── */
.fmx-glass.fsx-glass { --c: var(--dv-sage); width: min(88%, 352px); padding: 18px 16px 16px; border: 0; border-radius: 28px; }
.fsx-glass .fsx-glass-hero { gap: 12px; padding: 0 0 2px; border-bottom: 0; }
.fsx-glass .fsx-glass-hero strong { font-family: var(--ff-display); font-size: 40px; font-weight: 300; letter-spacing: -2px; color: var(--text-primary); }
.fsx-glass .fsx-glass-hero small { font-size: 12px; color: var(--text-secondary); }
.fsx-glass .fsx-glass-chips span {
  padding: 6px 11px; font-size: 12px; font-weight: 600; color: var(--text-secondary);
  background: rgba(245, 239, 230, 0.05); box-shadow: inset 0 0 0 1px var(--divider);
}
.fsx-glass .fsx-glass-chips span.is-on { color: #191614; background: var(--c); box-shadow: 0 0 12px color-mix(in srgb, var(--c) 50%, transparent); }
.fsx-glass .fsx-glass-tick {
  justify-content: center; min-height: 48px; margin-top: 14px; padding: 12px 16px; border: 0; border-radius: 18px;
  font-size: 14.5px; font-weight: 600; color: var(--text-primary);
  background: color-mix(in srgb, var(--c) 20%, rgba(245, 239, 230, 0.03));
  box-shadow: inset 0 0 0 1px color-mix(in srgb, var(--c) 55%, transparent), 0 0 18px -6px color-mix(in srgb, var(--c) 65%, transparent);
}
.fsx-glass .fsx-glass-tick span:nth-child(2) { flex: 0 1 auto; }
.fsx-glass .fsx-glass-tick.is-done { border: 0; color: var(--text-secondary); background: rgba(245, 239, 230, 0.05); box-shadow: inset 0 0 0 1px var(--divider); }
.fsx-glass .fsx-glass-block { margin: 16px 0 0; padding: 0; border: 0; border-radius: 0; background: none; box-shadow: none; }
.fsx-glass .fsx-glass-block-head { gap: 8px; margin: 0 0 8px; }
.fsx-glass .fsx-glass-block-head .t-ico { filter: none; }
.fsx-glass .fsx-glass-block-head strong { font-size: 12px; font-weight: 600; letter-spacing: 1.2px; color: var(--text-muted); }
.fsx-glass .fsx-glass-rows { grid-template-columns: repeat(2, minmax(0, 1fr)); gap: 6px; }
.fsx-glass .fsx-glass-rows > div, .fsx-glass .fsx-glass-rows > div:last-child {
  display: block; padding: 10px 12px; border: 0; border-radius: 14px;
  background: rgba(245, 239, 230, 0.04); box-shadow: inset 0 0 0 1px var(--divider);
}
.fsx-glass .fsx-glass-rows dt { font-size: 10px; color: var(--text-muted); }
.fsx-glass .fsx-glass-rows dd { margin-top: 2px; text-align: left; font-size: 14px; font-weight: 600; color: var(--text-primary); overflow-wrap: anywhere; }
.fsx-glass .fsx-glass-block.is-why p { font-family: var(--ff-serif); font-style: italic; font-size: 14.5px; line-height: 1.45; color: var(--text-primary); }
.fsx-glass .fsx-glass-block.is-quiet {
  padding: 12px 13px; border: 1.5px dashed color-mix(in srgb, var(--c) 45%, transparent); border-radius: 18px;
  background: rgba(245, 239, 230, 0.025); box-shadow: none;
}
.fsx-glass .fsx-glass-block p { font-size: 12.5px; line-height: 1.5; color: var(--text-secondary); }
.fsx-glass .fsx-glass-link {
  min-height: 48px; margin-top: 10px; padding: 11px 13px; border: 0; border-radius: 18px; color: var(--text-primary);
  background: rgba(245, 239, 230, 0.05); box-shadow: inset 0 0 0 1px var(--divider);
}
.fsx-glass .fsx-glass-link.is-shelf {
  --c: var(--dv-amber); margin-top: 14px;
  background: color-mix(in srgb, var(--c) 12%, rgba(245, 239, 230, 0.03));
  box-shadow: inset 0 0 0 1px color-mix(in srgb, var(--c) 40%, transparent), 0 0 16px -6px color-mix(in srgb, var(--c) 50%, transparent);
}
.fsx-glass .fsx-glass-link strong { font-size: 14px; font-weight: 600; }
.fsx-glass .fsx-glass-link small { font-size: 11px; color: var(--text-secondary); }
.fsx-glass .fsx-glass-link b { color: var(--text-muted); }
.fsx-glass .fsx-note { margin-top: 14px; color: var(--text-muted); }
.fsx-glass .fsx-glass-close {
  margin-top: 10px; border-radius: 18px; font-size: 14px; font-weight: 600; color: var(--text-secondary);
  background: rgba(245, 239, 230, 0.05); box-shadow: inset 0 0 0 1px var(--divider);
}

/* ── Protokoll + Új elem: the shared scaffold (round glass back + eyebrow + title, halo hero) ── */
.fsx-subhead { display: flex; align-items: center; gap: 12px; padding: 8px 17px 10px; }
.fsx-subhead > button.glass {
  --c: var(--text-muted); flex: 0 0 auto; width: 44px; height: 44px; padding: 0; border: 0;
  display: grid; place-items: center; font-family: inherit; font-size: 22px; line-height: 1; color: var(--text-secondary);
}
.fsx-subhead > span:not(.fsx-subhead-num) { flex: 1; min-width: 0; }
.fsx-subhead small { display: block; font-size: 10px; font-weight: 600; letter-spacing: 1.6px; text-transform: uppercase; color: var(--text-muted); }
.fsx-subhead strong {
  display: block; margin-top: 3px; font-family: var(--ff-display); font-size: 23px; font-weight: 600; letter-spacing: -0.8px;
  white-space: nowrap; overflow: hidden; text-overflow: ellipsis; color: var(--text-primary);
}
.fsx-subhead-num { flex: 0 0 auto; font-family: var(--ff-display); font-size: 30px; font-weight: 300; letter-spacing: -1.5px; font-variant-numeric: tabular-nums; color: var(--text-primary); }
.stk-page-hero.fsx-halo-hero { overflow-x: clip; display: grid; justify-items: center; gap: 2px; padding: 4px 17px 14px; border-radius: 0; background: none; text-align: center; }
.fsx-halo-art, .fmd-hero-art, .fsx-advice-art { display: block; }
.fsx-halo-art .t-ico, .fmd-hero-art .t-ico {
  filter: drop-shadow(0 12px 14px rgba(0, 0, 0, 0.5)) drop-shadow(0 0 18px color-mix(in srgb, var(--c) 45%, transparent));
}
.fsx-halo-num { margin-top: 4px; font-family: var(--ff-display); font-size: 54px; font-weight: 300; letter-spacing: -3px; line-height: 1; font-variant-numeric: tabular-nums; color: var(--text-primary); overflow-wrap: anywhere; }
.fsx-halo-sub { font-size: 12px; color: var(--text-secondary); }
.stk-detail-body .stk-detail-state.uv-empty { --c: var(--dv-sage); padding: 22px 16px; border-radius: 18px; font-size: 12.5px; color: var(--text-muted); }

/* Protokoll: the flat number strip, the zone glasses with flat hairline rows */
.stk-detail-body .fsx-summary { gap: 8px; margin: 0; padding: 0; border: 0; border-radius: 0; background: none; box-shadow: none; }
.stk-detail-body .fsx-summary > div {
  padding: 10px 6px; border-radius: 14px; text-align: center;
  background: rgba(245, 239, 230, 0.04); box-shadow: inset 0 0 0 1px var(--divider);
}
.stk-detail-body .fsx-summary strong { font-family: var(--ff-body); font-size: 20px; font-weight: 600; letter-spacing: -0.4px; }
.stk-detail-body .fsx-summary small { margin-top: 2px; font-size: 10.5px; font-weight: 500; letter-spacing: 0; text-transform: none; color: var(--text-muted); }
.fsx-proto-group.glass { margin: 0; padding: 12px 12px 4px; border: 0; border-radius: 22px; }
.fsx-proto-group.glass .fsx-proto-title { gap: 10px; padding: 0 2px 6px; }
.fsx-proto-group.glass .fsx-proto-title strong { font-family: var(--ff-body); font-size: 16px; font-weight: 600; letter-spacing: 0; }
.fsx-proto-group.glass .fsx-proto-title time { margin-left: auto; font-size: 13px; color: color-mix(in srgb, var(--c) 75%, var(--text-primary)); }
.fsx-proto-group.glass .fsx-proto-title b { margin-left: 0; font-size: 13px; font-weight: 600; color: color-mix(in srgb, var(--c) 75%, var(--text-primary)); }
.fsx-proto-group.glass .fsx-proto-title time + b { margin-left: -6px; }
.fsx-proto-group.glass .fsx-proto-title time + b::before { content: '· '; }
.fsx-proto-group.glass .fsx-proto-list { gap: 0; }
.fsx-proto-group.glass .fsx-proto-line {
  align-items: flex-start; gap: 10px; min-height: 56px; padding: 10px 2px; border: 0; border-top: 1px solid var(--divider);
  border-radius: 0; background: none; box-shadow: none; color: var(--text-primary);
}
.fsx-proto-group.glass .fsx-proto-line-copy strong { font-size: 14px; font-weight: 600; }
.fsx-proto-group.glass .fsx-proto-line-copy small { font-size: 11px; color: var(--text-secondary); }
.fsx-proto-group.glass .fsx-proto-line-copy em { margin-top: 3px; font-family: var(--ff-serif); font-style: italic; font-size: 12.5px; line-height: 1.35; color: var(--text-secondary); }
.fsx-proto-group.glass .fsx-proto-line-end b { font-size: 13px; font-weight: 600; color: var(--text-primary); }
.fsx-proto-group.glass .fsx-proto-line-end small { font-size: 10px; font-weight: 500; letter-spacing: 0; text-transform: none; color: var(--text-muted); }
.stk-detail-body .fsx-proto-meals { margin: 6px 0 0; padding: 0; border: 0; border-radius: 0; background: none; box-shadow: none; }
.stk-detail-body .fsx-proto-meals .fsx-proto-title { padding: 0 4px 8px; }
.stk-detail-body .fsx-proto-meals .fsx-proto-title strong { font-family: var(--ff-body); font-size: 15px; font-weight: 600; letter-spacing: -0.2px; }
.stk-detail-body .fsx-proto-meals .fsx-proto-title b {
  margin-left: 6px; padding: 2px 8px; border-radius: 999px; font-size: 11px; font-weight: 600; color: var(--text-secondary);
  background: rgba(245, 239, 230, 0.05); box-shadow: inset 0 0 0 1px var(--divider);
}
.fsx-proto-quiet.uv-flat { padding: 12px 14px; border-radius: 14px; font-size: 12.5px; line-height: 1.5; color: var(--text-secondary); }
/* StackMealMatch: ONE flat cell; the tick is the 3D tick, a short meal a warning-tinted marker */
.fsx-mm.uv-flat { display: grid; padding: 10px 12px 4px; border-radius: 14px; }
.fsx-mm-eyebrow { display: block; margin-bottom: 2px; }
.fsx-mm-row { display: flex; align-items: flex-start; gap: 10px; padding: 9px 0; border-top: 1px solid var(--divider); }
.fsx-mm-eyebrow + .fsx-mm-row { border-top: 0; }
.fsx-mm-art, .fsx-mm-mark { flex: 0 0 auto; width: 28px; height: 28px; display: grid; place-items: center; }
.fsx-mm-mark.is-warn {
  border-radius: 50%; font-size: 15px; font-weight: 800; color: var(--dv-amber);
  background: color-mix(in srgb, var(--dv-amber) 14%, transparent);
  box-shadow: inset 0 0 0 1.5px color-mix(in srgb, var(--dv-amber) 55%, transparent);
}
.fsx-mm-copy { flex: 1; min-width: 0; display: grid; gap: 2px; font-size: 13px; line-height: 1.4; color: var(--text-primary); }
.fsx-mm-when b, .fsx-mm-title { font-weight: 600; }
.fsx-mm-when time { font-variant-numeric: tabular-nums; color: var(--text-secondary); }
.fsx-mm-link { font-weight: 600; color: var(--dv-sage); text-decoration: none; overflow-wrap: anywhere; }
.fsx-mm-day { font-weight: 400; color: var(--text-muted); }
.fsx-mm-copy small { font-size: 11.5px; color: var(--text-secondary); }
.fsx-mm-copy small.fsx-mm-advice { color: color-mix(in srgb, var(--dv-amber) 80%, var(--text-primary)); }

/* Új elem: flat step pills, lav glass picks + form, the lav advice halo, the tune glass */
.stk-detail-body .fsx-steps { gap: 6px; margin: 0 0 2px; }
.stk-detail-body .fsx-steps li {
  padding: 7px 0; font-size: 11.5px; font-weight: 600; letter-spacing: 0; text-transform: none; color: var(--text-muted);
  background: rgba(245, 239, 230, 0.04); box-shadow: inset 0 0 0 1px var(--divider);
}
.stk-detail-body .fsx-steps li.is-done { color: var(--text-secondary); background: rgba(245, 239, 230, 0.04); box-shadow: inset 0 0 0 1px color-mix(in srgb, var(--dv-lav) 45%, transparent); }
.stk-detail-body .fsx-steps li.is-on { color: #191614; background: var(--dv-lav); box-shadow: 0 0 12px color-mix(in srgb, var(--dv-lav) 50%, transparent); }
.stk-detail-body .fsx-lead { font-size: 13.5px; line-height: 1.5; color: var(--text-secondary); }
.stk-detail-body .fsx-lead.is-quiet { color: var(--text-muted); }
.stk-detail-body .fsx-section { font-size: 9.5px; font-weight: 600; letter-spacing: 1.3px; color: var(--text-muted); }
.stk-detail-body .fsx-search { gap: 10px; padding: 0 14px; border-radius: 16px; color: var(--text-muted); background: rgba(245, 239, 230, 0.05); box-shadow: inset 0 0 0 1px var(--divider); }
.stk-detail-body .fsx-search input { font-size: 14px; color: var(--text-primary); }
.fsx-pick.glass { --c: var(--dv-lav); gap: 12px; min-height: 60px; padding: 12px 14px 12px 12px; border: 0; border-radius: 20px; color: var(--text-primary); }
.stk-detail-body .fsx-pick.is-wide.uv-flat { border: 0; border-radius: 18px; background: rgba(245, 239, 230, 0.04); box-shadow: inset 0 0 0 1px var(--divider); color: var(--text-primary); }
.stk-detail-body .fsx-pick strong { font-size: 15.5px; font-weight: 600; letter-spacing: -0.3px; }
.stk-detail-body .fsx-pick small { font-size: 11.5px; line-height: 1.35; color: var(--text-secondary); }
.stk-detail-body .fsx-pick > b { font-size: 20px; color: var(--text-muted); }
.stk-detail-body .fsx-pick-flag.uv-flat { padding: 5px 10px; border-radius: 999px; font-size: 11px; font-weight: 600; letter-spacing: 0; text-transform: none; color: var(--text-secondary); }
.stk-detail-body .fsx-arm { --c: var(--dv-lav); border: 1.5px dashed color-mix(in srgb, var(--c) 45%, transparent); border-radius: 18px; background: rgba(245, 239, 230, 0.025); }
.fsx-form.glass { --c: var(--dv-lav); gap: 12px; padding: 14px; border-radius: 22px; }
.stk-detail-body .fsx-field { font-size: 9.5px; font-weight: 600; letter-spacing: 1.3px; color: var(--text-muted); }
.stk-detail-body .fsx-field input, .stk-detail-body .fsx-field select {
  min-height: 44px; padding: 11px 13px; border-radius: 13px; font-size: 14px; color: var(--text-primary);
  background: rgba(245, 239, 230, 0.05); box-shadow: inset 0 0 0 1px var(--divider); color-scheme: dark;
}
.stk-detail-body .fsx-field input:focus, .stk-detail-body .fsx-field select:focus { box-shadow: inset 0 0 0 1.5px var(--dv-lav); }
.stk-detail-body .fsx-primary { justify-content: center; gap: 8px; min-height: 48px; padding: 13px 16px; border: 0; border-radius: 18px; font-size: 14.5px; font-weight: 600; color: var(--text-primary); }
.stk-detail-body .fsx-primary span:nth-child(2) { flex: 0 1 auto; }
.stk-detail-body .fsx-primary b { color: var(--text-muted); }
.fsx-primary.glass { --c: var(--dv-lav); }
.fsx-primary.glass.is-save { --c: var(--dv-sage); }
.stk-detail-body .fsx-primary.is-lit {
  --c: var(--dv-lav);
  background: color-mix(in srgb, var(--c) 20%, rgba(245, 239, 230, 0.03));
  box-shadow: inset 0 0 0 1px color-mix(in srgb, var(--c) 55%, transparent), 0 0 18px -6px color-mix(in srgb, var(--c) 65%, transparent);
}
.stk-detail-body .fsx-back-step {
  justify-self: stretch; width: 100%; min-height: 46px; padding: 12px 16px; border-radius: 18px;
  font-size: 14px; font-weight: 600; color: var(--text-secondary);
  background: rgba(245, 239, 230, 0.05); box-shadow: inset 0 0 0 1px var(--divider);
}
.stk-detail-body .fsx-callout {
  --c: var(--dv-lav); gap: 10px; padding: 12px 14px; border: 0; border-radius: 18px;
  background: color-mix(in srgb, var(--c) 8%, transparent); box-shadow: inset 3px 0 0 var(--c);
}
.stk-detail-body .fsx-callout.is-warn { --c: var(--dv-amber); background: color-mix(in srgb, var(--c) 8%, transparent); box-shadow: inset 3px 0 0 var(--c); }
.stk-detail-body .fsx-callout p { font-size: 13px; line-height: 1.45; color: var(--text-secondary); }
.stk-detail-body .fsx-callout small { font-size: 9.5px; font-weight: 600; letter-spacing: 1.3px; color: color-mix(in srgb, var(--c) 80%, var(--text-primary)); }
.fsx-advice.uv-halo { --c: var(--dv-lav); --c2: var(--dv-sky); padding: 10px 20px 4px; border-radius: 0; background: none; overflow: visible; }
.fsx-advice.uv-halo > strong { font-family: var(--ff-display); font-size: 46px; font-weight: 300; letter-spacing: -3px; color: var(--text-primary); }
.fsx-advice.uv-halo > em { font-size: 14px; font-weight: 400; letter-spacing: 0; text-transform: none; color: var(--text-secondary); }
.fsx-advice.uv-halo p { font-size: 13px; color: var(--text-secondary); }
.fsx-advice.uv-halo p b { color: var(--text-primary); }
.fsx-advice.uv-halo .fsx-advice-days { margin-top: 4px; padding: 0; background: none; font-size: 12px; font-weight: 400; color: var(--text-muted); }
.stk-detail-body .fsx-dose-why.uv-flat { --c: var(--dv-amber); align-items: center; gap: 10px; padding: 12px 14px; border: 0; border-radius: 14px; background: rgba(245, 239, 230, 0.04); box-shadow: inset 0 0 0 1px var(--divider); }
.stk-detail-body .fsx-dose-why p { font-family: var(--ff-serif); font-style: italic; font-size: 14px; line-height: 1.4; color: var(--text-primary); }
.fsx-tunecard.glass { --c: var(--dv-lav); display: grid; gap: 14px; padding: 14px; border-radius: 22px; }
.fsx-tunecard .fsx-overline { font-size: 9.5px; font-weight: 600; letter-spacing: 1.3px; color: var(--text-muted); }
.fsx-tunecard .fsx-stepper { justify-content: flex-start; gap: 12px; padding: 0; border: 0; border-radius: 0; background: none; box-shadow: none; }
.fsx-tunecard .fsx-stepper button { border-radius: 50%; font-size: 18px; color: var(--text-primary); background: rgba(245, 239, 230, 0.06); box-shadow: inset 0 0 0 1px var(--divider); }
.fsx-tunecard .fsx-stepper strong { font-family: var(--ff-body); font-size: 20px; font-weight: 600; letter-spacing: -0.4px; color: var(--text-primary); }
.fsx-tunecard .fsx-stepper small { font-size: 12px; font-weight: 400; letter-spacing: 0; text-transform: none; color: var(--text-secondary); }
.fsx-tunecard .fsx-zones button {
  min-height: 36px; padding: 7px 12px; font-size: 12px; font-weight: 600; color: var(--text-secondary);
  background: rgba(245, 239, 230, 0.05); box-shadow: inset 0 0 0 1px var(--divider);
}
.fsx-tunecard .fsx-zones button[aria-pressed="true"] { color: #191614; background: var(--c); box-shadow: 0 0 12px color-mix(in srgb, var(--c) 50%, transparent); }

/* ── Gyógyszer: sky halo hero, ONE sky glass card, flat dose rows ── */
.fmd-page .mz-backbtn { font-size: 12.5px; color: var(--text-secondary); background: rgba(245, 239, 230, 0.05); box-shadow: inset 0 0 0 1px var(--divider); }
.fmd-page .pgact.fmd-act {
  --c: var(--dv-sky); margin-left: auto; min-height: 40px; padding: 0 14px; font-size: 12.5px; font-weight: 600; color: #191614;
  background: var(--c); box-shadow: 0 0 12px color-mix(in srgb, var(--c) 50%, transparent);
}
.fmd-hero.uv-halo { overflow-x: clip; --c: var(--dv-sky); --c2: var(--dv-lav); display: grid; justify-items: center; gap: 2px; padding: 6px 17px 12px; text-align: center; }
.fmd-hero-num { font-family: var(--ff-display); font-size: 64px; font-weight: 300; letter-spacing: -3px; line-height: 1; font-variant-numeric: tabular-nums; color: var(--text-primary); }
.fmd-hero-eb, .fmd-eyebrow { font-size: 9.5px; font-weight: 600; letter-spacing: 1.3px; text-transform: uppercase; color: var(--text-muted); }
.fmd-medcard.glass { --c: var(--dv-sky); display: grid; gap: 8px; margin: 0 0 12px; padding: 14px; border-radius: 22px; }
.fmd-medcard.glass::before { width: auto; }
.fmd-medcard-head { display: flex; align-items: baseline; justify-content: space-between; gap: 10px; }
.fmd-medcard-head strong { min-width: 0; font-size: 18px; font-weight: 600; letter-spacing: -0.3px; color: var(--text-primary); overflow-wrap: anywhere; }
.fmd-medcard-head b { flex: 0 0 auto; font-size: 18px; font-weight: 600; font-variant-numeric: tabular-nums; color: color-mix(in srgb, var(--c) 78%, var(--text-primary)); }
.fmd-medcard-sub { margin-top: -4px; font-size: 12px; color: var(--text-secondary); }
.fmd-medcard .fmd-eyebrow { margin-top: 4px; }
.fmd-phase { font-size: 12.5px; color: var(--text-secondary); }
.fmd-phase b { color: var(--text-primary); }
/* the cycle strip (page + the medform preview): flat cells, today lit sky */
.fmd-cyc { display: grid; grid-template-columns: repeat(7, minmax(0, 1fr)); gap: 5px; margin: 0; padding: 0; list-style: none; }
.fmd-cyc > li, .fmd-cyc > span {
  height: auto; padding: 7px 0 6px; border-radius: 11px; display: flex; flex-direction: column; align-items: center; gap: 1px;
  background: rgba(245, 239, 230, 0.04); box-shadow: inset 0 0 0 1px var(--divider); color: var(--text-secondary);
}
.fmd-cyc > li.peak, .fmd-cyc > span.peak { background: rgba(245, 239, 230, 0.04); color: color-mix(in srgb, var(--dv-coral) 60%, var(--text-primary)); }
.fmd-cyc > li.stable, .fmd-cyc > span.stable { background: rgba(245, 239, 230, 0.04); color: var(--dv-sky); }
.fmd-cyc > li.trough, .fmd-cyc > span.trough { background: rgba(245, 239, 230, 0.04); color: var(--dv-lav); }
.fmd-cyc > li.cur { background: color-mix(in srgb, var(--dv-sky) 20%, transparent); box-shadow: inset 0 0 0 1.5px var(--dv-sky), 0 0 12px -2px var(--dv-sky); }
.fmd-cyc > li.cur::after { content: none; }
.fmd-cyc .fmd-cyc-glyph { font-size: 12px; font-weight: 700; }
.fmd-cyc .fmd-cyc-day { font-size: 9.5px; font-weight: 500; color: var(--text-muted); }
.fmd-sec { display: flex; align-items: center; gap: 8px; margin: 18px 4px 10px; }
.fmd-sec b { padding: 2px 8px; border-radius: 999px; font-size: 11px; font-weight: 600; color: var(--text-secondary); background: rgba(245, 239, 230, 0.05); box-shadow: inset 0 0 0 1px var(--divider); }
.fmd-doselist { display: grid; gap: 8px; margin: 0; padding: 0; list-style: none; }
.fmd-doselist .fmd-doserow.uv-flat { --c: var(--dv-sky); display: flex; align-items: center; gap: 12px; padding: 10px 14px 10px 10px; border: 0; border-radius: 18px; font-size: 14px; }
.fmd-dose-copy { flex: 1; min-width: 0; }
.fmd-dose-copy strong { display: block; font-size: 15px; font-weight: 600; color: var(--text-primary); }
.fmd-doselist .fmd-doserow .nt { display: block; margin-top: 2px; font-family: var(--ff-serif); font-style: italic; font-size: 12px; color: var(--text-secondary); }
.fmd-doselist .fmd-doserow .dd { flex: 0 0 auto; font-size: 18px; font-weight: 600; color: var(--text-primary); }
.fmd-nodose.uv-empty { --c: var(--dv-sky); padding: 16px; border-radius: 18px; text-align: center; font-size: 12.5px; color: var(--text-muted); }
.fmd-pair { display: grid; grid-template-columns: repeat(2, minmax(0, 1fr)); gap: 10px; margin-top: 12px; }
.fmd-btn {
  display: flex; align-items: center; justify-content: center; gap: 8px; width: 100%; min-height: 46px; padding: 12px 16px;
  border: 0; border-radius: 18px; font: inherit; font-size: 14.5px; font-weight: 600; color: var(--text-secondary); cursor: pointer;
}
.fmd-btn.is-warn { color: #FFB39C; background: rgba(255, 126, 92, 0.07); box-shadow: inset 0 0 0 1px rgba(255, 126, 92, 0.35); }
.fmd-btn.glass.is-primary { --c: var(--dv-sky); margin-top: 14px; color: var(--text-primary); }
.fmd-empty.uv-empty {
  --c: var(--dv-sky); display: flex; flex-direction: column; align-items: center; gap: 6px;
  margin: 10px 0; padding: 26px 18px; border-radius: 20px; text-align: center;
}
.fmd-empty.uv-empty strong { margin-top: 6px; font-size: 17px; font-weight: 600; color: var(--text-primary); }
.fmd-empty-lead { font-size: 13.5px; line-height: 1.5; color: var(--text-secondary); }
.fmd-stop.uv-empty { --c: var(--dv-coral); margin-top: 10px; padding: 12px 14px; border-radius: 16px; font-size: 12.5px; line-height: 1.5; color: var(--text-secondary); }

/* ── the stack sheets: ONE glass surface each (StackItemSheet gold, dose + medform sky) ── */
.sheet.glass.fsx-sheet {
  position: absolute; left: 10px; right: 10px; bottom: calc(10px + env(safe-area-inset-bottom)); overflow-x: hidden; overflow-y: auto;
  border: 0; border-radius: 30px; padding-bottom: 18px;
}
.sheet.fsx-sheet.is-gold { --c: var(--dv-amber); }
.sheet.fsx-sheet.is-sky { --c: var(--dv-sky); }
.sheet.glass.fsx-sheet .sheet-handle { background: rgba(245, 239, 230, 0.22); }
.fsx-shh { display: flex; align-items: flex-start; gap: 12px; margin-bottom: 12px; }
.fsx-shh-art { flex: 0 0 auto; }
.fsx-shh-copy { flex: 1; min-width: 0; }
.fsx-shh-title strong { display: block; margin-top: 2px; font-family: var(--ff-display); font-size: 21px; font-weight: 600; letter-spacing: -0.6px; color: var(--text-primary); overflow-wrap: anywhere; }
.fsx-shh-copy small { display: block; margin-top: 2px; font-size: 12px; color: var(--text-secondary); }
.fsx-shh-x {
  flex: 0 0 auto; width: 36px; height: 36px; padding: 0; border: 0; border-radius: 50%; display: grid; place-items: center;
  color: var(--text-secondary); background: rgba(245, 239, 230, 0.06); box-shadow: inset 0 0 0 1px var(--divider);
}
.fsx-sh-cell.uv-flat { display: flex; align-items: center; gap: 10px; padding: 10px 12px; border-radius: 14px; }
.fsx-sh-cell p { flex: 1; min-width: 0; margin: 0; font-size: 13px; line-height: 1.45; color: var(--text-secondary); }
.fsx-sh-cell p.uv-voice { font-size: 13.5px; color: var(--text-primary); }
.fsx-sh-field { display: grid; gap: 6px; min-width: 0; margin-top: 14px; }
.fsx-sheet .fsx-sh-input {
  display: block; width: 100%; min-width: 0; min-height: 44px; padding: 11px 13px; border: 0; border-radius: 13px;
  font: inherit; font-size: 14px; color: var(--text-primary); color-scheme: dark; outline: none;
  background: rgba(245, 239, 230, 0.05); box-shadow: inset 0 0 0 1px var(--divider);
}
.fsx-sheet .fsx-sh-input:focus { box-shadow: inset 0 0 0 1.5px var(--c); }
.fsx-chips { display: flex; flex-wrap: wrap; gap: 6px; }
.fsx-sheet .fsx-chip {
  display: inline-flex; align-items: center; gap: 6px; min-height: 36px; padding: 7px 12px; border: 0; border-radius: 999px;
  font: inherit; font-size: 12px; font-weight: 600; white-space: nowrap; color: var(--text-secondary); cursor: pointer;
  background: rgba(245, 239, 230, 0.05); box-shadow: inset 0 0 0 1px var(--divider);
}
.fsx-sheet .fsx-chip.is-on { color: #191614; background: var(--c); box-shadow: 0 0 12px color-mix(in srgb, var(--c) 50%, transparent); }
.fsx-sheet .fsx-chip:disabled { opacity: 0.5; cursor: default; }
.fsx-chips.is-coral, .fsx-sh-addrow.is-coral { --c: var(--dv-coral); }
.fsx-sh-addrow { display: flex; align-items: center; gap: 8px; margin-top: 8px; }
.fsx-sh-addrow .fsx-sh-input { flex: 1; }
.fsx-sh-hint { display: block; margin: 10px 0 0; font-size: 11px; line-height: 1.5; color: var(--text-muted); }
.fsx-sh-sec { display: block; margin: 14px 0 6px; }
.fsx-sh-two { display: grid; grid-template-columns: repeat(2, minmax(0, 1fr)); gap: 10px; }
.fsx-sh-two > .fsx-sh-field { margin-top: 0; }
.fsx-sh-two.is-dose { grid-template-columns: minmax(0, 2fr) minmax(0, 1fr); margin-top: 14px; }
.fsx-sh-unitrow { display: flex; align-items: center; gap: 8px; }
.fsx-sh-unit { flex: 0 0 auto; font-size: 12px; font-weight: 600; color: var(--text-muted); }
.fsx-sheet .fmd-cyc.is-preview { margin-top: 2px; }
.fsx-sh-btn {
  display: flex; align-items: center; justify-content: center; gap: 8px; width: 100%; min-height: 46px; margin-top: 16px;
  padding: 12px 16px; border: 0; border-radius: 18px; font: inherit; font-size: 14.5px; font-weight: 600; color: var(--text-secondary); cursor: pointer;
}
.fsx-sh-btn.is-warn { color: #FFB39C; background: rgba(255, 126, 92, 0.07); box-shadow: inset 0 0 0 1px rgba(255, 126, 92, 0.35); }
.fsx-sh-btn.is-lit {
  color: var(--text-primary); background: color-mix(in srgb, var(--c) 22%, rgba(245, 239, 230, 0.03));
  box-shadow: inset 0 0 0 1px color-mix(in srgb, var(--c) 55%, transparent), 0 0 18px -6px color-mix(in srgb, var(--c) 65%, transparent);
}
.fsx-sh-btn:disabled { opacity: 0.45; cursor: default; }
.fsx-sh-pair { display: grid; grid-template-columns: repeat(2, minmax(0, 1fr)); gap: 10px; margin-top: 16px; }
.fsx-sh-pair .fsx-sh-btn { margin-top: 0; }

/* §6 motion: the hero art floats, the due band keeps its entrance but drops the old coral pulse */
@media (prefers-reduced-motion: no-preference) {
  .fsx-halo-art, .fmd-hero-art, .fsx-advice-art { animation: uv-float 5s ease-in-out 1s infinite; }
  .fsx-band.glass.is-due { animation: fsx-band-in 0.45s cubic-bezier(0.2, 0.8, 0.3, 1.1) both; }
}
@media (prefers-reduced-motion: reduce) {
  .fsx-halo-art, .fmd-hero-art, .fsx-advice-art, .fsx-band.glass.is-due { animation: none; }
}
/* 320px: the ring shrinks, the doors keep two columns with wrapped copy */
@media (max-width: 360px) {
  .fsx-gauge.fsx-ring { width: 150px; height: 150px; }
  .fsx-gauge.fsx-ring strong { font-size: 40px; }
  .fsx-poster.glass { padding: 12px; }
  .fsx-subhead strong { font-size: 20px; }
  .fsx-halo-num { font-size: 46px; }
  .fsx-advice.uv-halo > strong { font-size: 40px; }
  .fmd-hero-num { font-size: 54px; }
}
/* ── /uveg fuel stack ── */

/* ── uveg fuel trendek (mezo-me75u.2) ── Trendek, day card, Fuel beállítások, étkezési ablakok ── */
/* Reference: docs/design_2.0/prototypes/src/uveg-fuel-tobbi-body.html `trendek()`, `openDay()`,
   `beallitas()`, `ablakok()`. The restored-world `fuel-trendek` block and the `fset-` block stay
   in place underneath (their DOM hooks are unchanged); this block re-dresses them in the üveg
   ranking (bible §3.4): the week picture and the day arc are frameless halos, the primary
   objects are .glass in ONE hue, chips/cells inside a card are flat, empty is dashed. */

/* ─ Trendek ─ the halo's 340px ellipse must never become a sideways scroll on a 320px phone */
.ftx-body, .fset-body, .fsl-page .mz-page-body { overflow-x: hidden; }

/* the WEEK PICTURE — frameless on a sage/gold halo (bible §5) */
.ftx-hero.uv-halo { --c: var(--dv-sage); --c2: var(--dv-amber); overflow: visible;
  padding: 4px 2px 6px; border-radius: 0; background: none; }
.ftx-hero.uv-halo::before { top: 58%; width: 380px; height: 360px; }
.ftx-week { margin: 0; font-size: 14px; font-weight: 600; letter-spacing: 0; text-transform: none;
  color: var(--text-primary); }
.ftx-weeknav button.uv-flat { padding: 7px 12px; border: 0; border-radius: 999px;
  background: rgba(245, 239, 230, 0.05); box-shadow: inset 0 0 0 1px var(--divider);
  font-size: 12px; font-weight: 600; color: var(--text-secondary); }
.ftx-weeknav button.uv-flat[aria-pressed="true"] { background: rgba(245, 239, 230, 0.05);
  color: color-mix(in srgb, var(--dv-sage) 78%, var(--text-primary));
  box-shadow: inset 0 0 0 1px color-mix(in srgb, var(--dv-sage) 40%, transparent); }
.ftx-weeknav button.uv-flat:disabled { opacity: 0.45; }
.ftx-weeknav-note { color: var(--text-muted); }
.ftx-big { justify-content: center; margin: 16px 0 2px; }
.ftx-big strong { font-size: 64px; font-weight: 300; letter-spacing: -3px; color: var(--text-primary); }
.ftx-big b { font-size: 14px; font-weight: 400; color: var(--text-secondary); }
.ftx-big small { font-size: 9.5px; font-weight: 600; letter-spacing: 1.3px; color: var(--text-muted); }
/* the 7 day bars: a recessed column, a glowing fill, a dashed target line */
.ftx-bars { gap: 8px; margin: 14px 2px 2px; }
.ftx-day { display: flex; flex-direction: column; align-items: center; justify-content: flex-end;
  gap: 6px; padding: 0 0 4px; }
.ftx-day-score { order: -1; font-size: 11px; font-weight: 600;
  color: color-mix(in srgb, var(--dv-lav) 70%, var(--text-primary)); }
.ftx-day.is-empty .ftx-day-score { color: var(--text-muted); }
.ftx-col { height: 124px; border-radius: 10px; background: rgba(245, 239, 230, 0.05); }
.ftx-target { z-index: 1; justify-self: center; width: calc(100% + 6px);
  border-top: 1.5px dashed rgba(245, 239, 230, 0.35); }
.ftx-fill { width: 100%; border-radius: 10px;
  background: linear-gradient(180deg, var(--dv-sage), color-mix(in srgb, var(--dv-sage) 45%, transparent));
  box-shadow: 0 0 12px -2px color-mix(in srgb, var(--dv-sage) 70%, transparent); }
/* shame-free: over the target is GOLD, never an error hue */
.ftx-day.is-over .ftx-fill {
  background: linear-gradient(180deg, var(--dv-amber), color-mix(in srgb, var(--dv-amber) 45%, transparent));
  box-shadow: 0 0 12px -2px color-mix(in srgb, var(--dv-amber) 70%, transparent); }
/* honest gap: the whole column hatched, not a zero-height bar */
.ftx-day.is-empty .ftx-col { background: none; }
.ftx-gap { width: 100%; height: 100%; border-radius: 10px;
  background: repeating-linear-gradient(135deg, rgba(245, 239, 230, 0.05) 0 5px, transparent 5px 10px);
  box-shadow: inset 0 0 0 1px var(--divider); }
.ftx-day-name { font-size: 11px; font-weight: 600; letter-spacing: 0.4px; color: var(--text-muted); }
.ftx-day.is-weekend .ftx-day-name { color: color-mix(in srgb, var(--dv-amber) 70%, var(--text-muted)); }
/* a training day: the day name underlined in coral (the dot is kept for the DOM, not drawn) */
.ftx-train { display: none; }
.ftx-day.is-train .ftx-day-name { color: var(--text-primary); text-decoration: underline;
  text-decoration-color: var(--dv-coral); text-decoration-thickness: 2px; text-underline-offset: 3px; }
.ftx-read.uv-voice { margin: 14px 4px 0; font-size: 14.5px; line-height: 1.5; text-align: center;
  color: var(--text-secondary); }
.ftx-hint { font-size: 9.5px; font-weight: 600; letter-spacing: 1.3px; color: var(--text-muted); }
.ftx-section { margin: 10px 0 0; font-size: 19px; font-weight: 600; letter-spacing: -0.3px; }
/* three glass stat tiles, each in its own hue */
.ftx-tiles { gap: 8px; }
.ftx-tile.glass { gap: 4px; padding: 12px 10px; border: 0; border-radius: 20px; color: var(--text-primary); }
.ftx-tile.glass strong { margin-top: 4px; font-family: var(--ff-body); font-size: 22px; font-weight: 600;
  letter-spacing: -0.8px; color: color-mix(in srgb, var(--c) 75%, var(--text-primary)); }
.ftx-tile.glass strong small { font-size: 10.5px; font-weight: 500; color: var(--text-muted); }
.ftx-tile.glass .ftx-tile-label { font-size: 11px; font-weight: 400; letter-spacing: 0; text-transform: none;
  color: var(--text-secondary); }
.ftx-tile.glass .ftx-delta { font-size: 10.5px; color: var(--text-muted); }
/* weekday vs weekend: one gold glass card, two glowing bars on flat rows */
.ftx-split.glass { gap: 4px; padding: 12px 14px 14px; border-radius: 22px; }
.ftx-split .ftx-splitrow { min-height: 44px; padding: 6px 0; border-radius: 0; background: none; box-shadow: none; }
.ftx-split-copy strong { font-size: 13px; font-weight: 600; color: var(--text-primary); }
.ftx-split-copy i { height: 7px; background: rgba(245, 239, 230, 0.07); }
.ftx-split-copy i b { background: linear-gradient(90deg, color-mix(in srgb, var(--ftx-split-color) 55%, #fff), var(--ftx-split-color));
  box-shadow: 0 0 8px color-mix(in srgb, var(--ftx-split-color) 60%, transparent); }
.ftx-splitrow > b { font-size: 15px; font-weight: 600;
  color: color-mix(in srgb, var(--ftx-split-color) 78%, var(--text-primary)); }
.ftx-split-note { margin-top: 8px; font-size: 12.5px; color: var(--text-secondary); }
.ftx-split-note b { color: var(--text-primary); }
/* the longer horizon: a sage glass card, the kcal line glows, weight in sky with lit dots */
.ftx-horizon.glass { gap: 6px; padding: 14px; border: 0; border-radius: 22px; }
.ftx-horizon-grid { stroke: rgba(245, 239, 230, 0.07); }
.ftx-horizon-kcal { stroke: var(--dv-sage); stroke-width: 2.4;
  filter: drop-shadow(0 0 5px color-mix(in srgb, var(--dv-sage) 70%, transparent)); }
.ftx-horizon-weight { stroke: var(--dv-sky); stroke-width: 2; stroke-dasharray: none; }
.ftx-horizon-dot { fill: var(--dv-sky); filter: drop-shadow(0 0 5px var(--dv-sky)); }
.ftx-horizon-axis { font-size: 10px; fill: var(--text-muted); }
.ftx-horizon-legend em { font-size: 12px; font-weight: 400; letter-spacing: 0; text-transform: none;
  color: var(--text-secondary); }
.ftx-horizon-legend .is-kcal::before { background: var(--dv-sage); box-shadow: 0 0 6px var(--dv-sage); }
.ftx-horizon-legend .is-weight::before { background: var(--dv-sky); box-shadow: 0 0 6px var(--dv-sky); }
.ftx-horizon-lead { font-size: 12.5px; line-height: 1.45; color: var(--text-secondary); }
.ftx-horizon-gapnote { font-size: 11px; color: var(--text-muted); }
/* fewer than two weeks: free space, dashed — no glass, no glow */
.ftx-horizon.uv-empty.is-waiting { --c: var(--dv-sage); padding: 14px; border-radius: 22px;
  border: 1.5px dashed color-mix(in srgb, var(--dv-sage) 45%, transparent);
  background: rgba(245, 239, 230, 0.025); box-shadow: none; }
.ftx-horizon-wait { font-size: 12.5px; color: var(--text-secondary); }
/* pattern references: lavender glass rows */
.ftx-pattern.glass { gap: 12px; padding: 12px 14px 12px 12px; border: 0; border-radius: 20px; color: var(--text-primary); }
.ftx-pattern-copy strong { font-size: 14px; font-weight: 600; }
.ftx-pattern-copy small { font-size: 11.5px; color: var(--text-secondary); }
.ftx-pattern.glass > b { font-size: 16px; color: var(--text-muted); }
.ftx-note { font-size: 11.5px; line-height: 1.5; text-align: center; color: var(--text-muted); }

/* ─ the day card (FuelWeekDayGlass inside the kit GlassBox): cells inside are flat (U1 rule 5) */
.ftx-glass-hero strong { font-size: 40px; font-weight: 300; letter-spacing: -2.4px; color: var(--text-primary); }
.ftx-glass-hero small { margin-top: 3px; font-size: 12px; font-weight: 400; letter-spacing: 0;
  text-transform: none; color: var(--text-secondary); }
.ftx-glass-chips span { padding: 7px 12px; background: rgba(245, 239, 230, 0.05);
  box-shadow: inset 0 0 0 1px var(--divider); font-size: 12px; color: var(--text-secondary); }
.ftx-glass-bar { height: 6px; background: rgba(245, 239, 230, 0.07); }
.ftx-glass-bar i { background: linear-gradient(90deg, color-mix(in srgb, var(--dv-sage) 55%, #fff), var(--dv-sage));
  box-shadow: 0 0 8px color-mix(in srgb, var(--dv-sage) 60%, transparent); }
.ftx-glass.is-over .ftx-glass-bar i { background: linear-gradient(90deg, color-mix(in srgb, var(--dv-amber) 55%, #fff), var(--dv-amber));
  box-shadow: 0 0 8px color-mix(in srgb, var(--dv-amber) 60%, transparent); }
.ftx-glass-fact { font-size: 13px; line-height: 1.45; color: var(--text-secondary); }
.ftx-glass-fact b { color: var(--text-primary); }
/* ŐSZINTÉN: an amber-lit callout, flat */
.ftx-glass-honest { display: block; padding: 12px 14px; border: 0; border-radius: 18px;
  background: color-mix(in srgb, var(--c) 8%, transparent); box-shadow: inset 3px 0 0 var(--c);
  font-size: 13px; line-height: 1.45; color: var(--text-secondary); }
.ftx-glass-honest > span:first-child { line-height: inherit; }
.ftx-glass-honest small { font-size: 9.5px; font-weight: 600; letter-spacing: 1.3px;
  color: color-mix(in srgb, var(--c) 80%, var(--text-primary)); }
.ftx-dim { padding: 11px 12px; border: 0; border-radius: 16px; background: rgba(245, 239, 230, 0.04);
  box-shadow: inset 0 0 0 1px var(--divider); }
.ftx-dim.is-degraded { border: 1.5px dashed color-mix(in srgb, var(--ftx-dim-color) 45%, transparent);
  background: rgba(245, 239, 230, 0.025); box-shadow: none; }
.ftx-dim .t-ico { filter: none; }
.ftx-dim-head strong { font-size: 14px; font-weight: 600; color: var(--text-primary); }
.ftx-dim-head small { font-size: 9.5px; font-weight: 600; letter-spacing: 1.2px; color: var(--text-muted); }
.ftx-dim-head > b { font-family: var(--ff-body); font-size: 22px; font-weight: 600; letter-spacing: -0.8px;
  color: color-mix(in srgb, var(--ftx-dim-color) 78%, var(--text-primary)); }
.ftx-dim-bar { height: 5px; background: rgba(245, 239, 230, 0.07); }
.ftx-dim-bar b { background: linear-gradient(90deg, color-mix(in srgb, var(--ftx-dim-color) 55%, #fff), var(--ftx-dim-color));
  box-shadow: 0 0 8px color-mix(in srgb, var(--ftx-dim-color) 60%, transparent); }
.ftx-dim-note { font-size: 12px; color: var(--text-secondary); }
.ftx-rows span { font-size: 12px; color: var(--text-secondary); }
.ftx-rows b { font-size: 14px; font-weight: 600; color: var(--text-primary); }
.ftx-meal { gap: 12px; margin-bottom: 6px; padding: 10px 12px; border: 0; border-radius: 14px;
  background: rgba(245, 239, 230, 0.04); box-shadow: inset 0 0 0 1px var(--divider); color: var(--text-primary); }
.ftx-meals li:last-child .ftx-meal { border-bottom: 0; }
.ftx-meal .t-ico { filter: none; }
.ftx-meal-copy strong { font-size: 14px; font-weight: 600; }
.ftx-meal-copy small { font-size: 11.5px; color: var(--text-secondary); }
/* the meal's score: the lavender-lit pill (fuel-uveg.html `.spill`) — flat, inside the glass box */
.ftx-meal-score { display: inline-flex; align-items: center; gap: 5px; padding: 4px 10px 4px 4px;
  border-radius: 999px; font-size: 13px; font-weight: 600; color: var(--text-primary);
  background: radial-gradient(90% 120% at 20% 20%, color-mix(in srgb, var(--dv-lav) 26%, transparent), rgba(245, 239, 230, 0.04));
  box-shadow: inset 0 0 0 1px color-mix(in srgb, var(--dv-lav) 40%, transparent); }
.ftx-meals-note { font-size: 12px; color: var(--text-muted); }
/* the door to the day: a lit flat row in the box's hue (never glass in glass) */
.ftx-glass-link { gap: 12px; padding: 12px 14px 12px 12px; border-radius: 18px; color: var(--text-primary);
  background: color-mix(in srgb, var(--c) 12%, rgba(245, 239, 230, 0.03));
  box-shadow: inset 0 0 0 1px color-mix(in srgb, var(--c) 40%, transparent), 0 0 14px -6px var(--c); }
.ftx-glass-link strong { font-size: 14px; font-weight: 600; }
.ftx-glass-link small { font-size: 11.5px; color: var(--text-secondary); }
.ftx-glass-link > b { font-size: 18px; color: var(--text-muted); }
.ftx-glass-close { border-radius: 18px; background: rgba(245, 239, 230, 0.05);
  box-shadow: inset 0 0 0 1px var(--divider); font-size: 14px; color: var(--text-secondary); }
.ftx-glass .ftx-section { font-size: 12px; font-weight: 600; letter-spacing: 1.2px; text-transform: uppercase;
  color: var(--text-muted); margin: 4px 0 0; }

/* ─ Fuel beállítások (/settings/fuel) ─ the day arc is the hero, frameless on an amber/sage halo */
.fset-hero.uv-halo { overflow: visible; min-height: 0; padding: 6px 4px 4px; border: 0; border-radius: 0;
  background: none; box-shadow: none; }
.fset-hero.uv-halo::after { display: none; }
.fset-hero .fset-eyebrow { font-size: 9.5px; font-weight: 600; letter-spacing: 1.3px; color: var(--text-muted); }
.fset-hero-head strong { font: 600 22px/1.15 var(--ff-body); letter-spacing: -0.4px; }
.fset-cutoff-pill.uv-flat { display: inline-flex; align-items: center; gap: 6px; padding: 5px 12px 5px 6px;
  border-radius: 999px; background: rgba(245, 239, 230, 0.05); font-size: 12px; font-weight: 600; letter-spacing: 0;
  color: color-mix(in srgb, var(--dv-coral) 78%, var(--text-primary));
  box-shadow: inset 0 0 0 1px color-mix(in srgb, var(--dv-coral) 35%, transparent); }
.fset-arc-track { stroke: rgba(245, 239, 230, 0.08); stroke-width: 8; }
.fset-arc-glow { stroke: url(#fset-arc-grad); stroke-width: 3;
  filter: drop-shadow(0 0 6px rgba(255, 190, 96, 0.6)); }
.fset-meal-dot { fill: var(--surface-card); stroke: var(--dv-amber); stroke-width: 2.4;
  filter: drop-shadow(0 0 6px rgba(255, 190, 96, 0.8)); }
.fset-cutoff-line { stroke: var(--dv-coral); stroke-width: 2.4; filter: drop-shadow(0 0 5px var(--dv-coral)); }
.fset-cutoff-dot { fill: var(--dv-coral); stroke: var(--surface-card); }
.fset-axis span { font-size: 10px; font-weight: 500; color: var(--text-muted); }
.fset-principle { font-size: 11.5px; color: var(--text-muted); }
/* the cards: glass, one hue each (Ritmus amber, Makrók protein, Finomhangolás lavender) */
.fset-card.glass { border: 0; padding: 14px; }
.fset-card.glass > h2 { color: color-mix(in srgb, var(--c) 78%, var(--text-primary)); }
.fset-card.glass p { font-size: 11.5px; color: var(--text-secondary); }
.fset-card.glass .fset-row > span:first-child { font-size: 14px; font-weight: 600; letter-spacing: 0;
  text-transform: none; color: var(--text-primary); }
.fset-card.glass .fset-selectrow > span:first-child { font-size: 9.5px; font-weight: 600; letter-spacing: 1.3px;
  color: var(--text-muted); }
/* flat fields inside a glass card */
.fset-row input, .fset-selectrow select, .fset-custom input, .fset-goal input {
  border: 0; border-radius: 13px; background: rgba(245, 239, 230, 0.05);
  box-shadow: inset 0 0 0 1px var(--divider); color: var(--text-primary); color-scheme: dark; }
.fset-stepper .chip { width: 44px; height: 44px; border: 0; border-radius: 50%;
  background: rgba(245, 239, 230, 0.06); box-shadow: inset 0 0 0 1px var(--divider); color: var(--text-primary); }
.fset-stepper > span { font-size: 20px; font-weight: 600; }
.fset-segments .chip { border: 0; border-radius: 999px; background: rgba(245, 239, 230, 0.05);
  box-shadow: inset 0 0 0 1px var(--divider); font-size: 12.5px; font-weight: 600; color: var(--text-secondary); }
.fset-segments .chip[aria-pressed="true"] { border: 0; background: var(--c); color: #191614; font-weight: 700;
  box-shadow: 0 0 12px color-mix(in srgb, var(--c) 45%, transparent); }
/* the macro preview: no box of its own; the donut glows and sits on a lit inner disc */
.fset-preview .fset-target-preview { padding: 0; border: 0; border-radius: 0; background: none; }
.fset-preview .fset-target-preview .fset-target-label { font-size: 9.5px; font-weight: 600; letter-spacing: 1.3px; color: var(--text-muted); }
.fset-donut { padding: 12px; box-shadow: 0 0 22px -6px rgba(240, 126, 120, 0.5); }
.fset-donut > span { background: radial-gradient(circle at 35% 30%, #3A332D, #1E1B18);
  box-shadow: inset 0 1px 0 rgba(255, 244, 230, 0.08); }
.fset-donut strong { font-size: 15px; font-weight: 600; }
.fset-donut small { font-size: 9.5px; }
.fset-macro-rows > div { border-bottom-color: var(--divider); }
.fset-macro-rows > div::before { width: 9px; height: 9px; box-shadow: 0 0 6px var(--macro-protein); }
.fset-macro-rows > div:nth-child(2)::before { box-shadow: 0 0 6px var(--macro-carbs); }
.fset-macro-rows > div:nth-child(3)::before { box-shadow: 0 0 6px var(--macro-fat); }
.fset-preview .fset-target-preview span { font-size: 13px; color: var(--text-primary); }
.fset-preview .fset-target-preview b { font-size: 13px; font-weight: 600; color: var(--text-secondary); }
.fset-preview .fset-target-preview .fset-donut small { font-size: 9.5px; color: var(--text-muted); }
.fset-card .fset-refresh-note { background: rgba(255, 190, 96, 0.1); color: color-mix(in srgb, var(--dv-amber) 80%, var(--text-primary));
  box-shadow: inset 0 0 0 1px rgba(255, 190, 96, 0.3); }
.fset-card .fset-error { color: color-mix(in srgb, var(--dv-coral) 80%, var(--text-primary)); }
.fset-custom label { font-size: 9.5px; font-weight: 600; letter-spacing: 1px; color: var(--text-muted); }
/* water / fiber goals: two glass tiles side by side */
.fset-goalgrid { grid-template-columns: repeat(2, minmax(0, 1fr)); gap: 10px; padding: 0; border-radius: 0; background: none; }
.fset-goal.glass { display: grid; align-content: start; gap: 6px; min-width: 0; padding: 12px; border-radius: 20px; }
.fset-goal > span { font-size: 11px; color: var(--text-secondary); }
.fset-goal input { width: 100%; min-height: 44px; padding: 0 10px; text-align: left; font: 600 20px/1 var(--ff-body);
  letter-spacing: -0.6px; font-variant-numeric: tabular-nums; color: color-mix(in srgb, var(--c) 78%, var(--text-primary)); }
/* the meal-window door: an amber glass row with the 3D clock */
.fset-slots.glass { justify-content: flex-start; gap: 12px; min-height: 66px; padding: 12px 14px 12px 12px;
  border-radius: 20px; color: var(--text-primary); }
.fset-slots-copy { flex: 1; min-width: 0; }
.fset-slots-copy > span { display: block; font-size: 15.5px; font-weight: 600; letter-spacing: -0.3px; }
.fset-slots-copy > small { display: block; margin-top: 2px; font-size: 11.5px; color: var(--text-secondary); }
.fset-slots.glass > b { font-size: 20px; color: var(--text-muted); }
.fset-closing.uv-voice { font-size: 13.5px; color: var(--text-muted); }
/* the save bar: a blurred FLAT bar (not glass), the save button in sage glass */
.fset-savebar, .fsl-savebar { left: 12px; right: 12px; gap: 10px; padding: 10px; border-top: 0; border-radius: 24px;
  background: rgba(25, 22, 20, 0.82); box-shadow: inset 0 0 0 1px var(--divider);
  -webkit-backdrop-filter: blur(14px); backdrop-filter: blur(14px); }
.fset-savebar .fset-save.glass { border-radius: 18px; color: var(--text-primary); font-size: 14.5px; font-weight: 600; }
.fsl-savebar .fsl-cancel { flex: 1; border: 0; border-radius: 18px; background: rgba(245, 239, 230, 0.05);
  box-shadow: inset 0 0 0 1px var(--divider); font-size: 14px; font-weight: 600; color: var(--text-secondary); }
.fsl-savebar .fsl-save.glass { flex: 1.6; width: auto; padding: 13px 16px; border-radius: 18px;
  color: var(--text-primary); font-size: 14.5px; font-weight: 600; }
.fsl-savebar .fsl-save:disabled { opacity: 0.45; }

/* ─ Étkezési ablakok (/settings/fuel/slots) ─ */
.fsl-seg { display: flex; margin: 0 0 14px; padding: 3px; border-radius: 999px;
  background: rgba(245, 239, 230, 0.05); box-shadow: inset 0 0 0 1px var(--divider); }
.fsl-seg-btn { flex: 1; min-width: 0; min-height: 36px; padding: 7px 6px; border-radius: 999px; white-space: nowrap;
  font-size: 12.5px; font-weight: 600; color: var(--text-secondary); }
.fsl-seg-btn.is-on { background: var(--dv-amber); color: #191614;
  box-shadow: 0 0 12px color-mix(in srgb, var(--dv-amber) 45%, transparent); }
.fsl-list { display: grid; gap: 10px; margin-bottom: 12px; }
/* recommended: glass rows in the slot's hue with its 3D icon */
.fsl-slotrow.glass { display: flex; align-items: center; gap: 12px; padding: 12px 14px; border-radius: 20px; }
.fsl-slot-time { width: 62px; flex: 0 0 auto; font-size: 20px; font-weight: 600; letter-spacing: -0.6px;
  font-variant-numeric: tabular-nums; color: var(--text-primary); }
.fsl-slot-label { flex: 1; min-width: 0; font-size: 15px; font-weight: 600; color: var(--text-primary); }
.fsl-slot-kcal { flex: 0 0 auto; font-size: 17px; font-weight: 600; font-variant-numeric: tabular-nums; }
.fsl-slot-kcal small { font-size: 10.5px; font-weight: 500; color: var(--text-muted); }
.fsl-cta.glass { width: 100%; gap: 8px; padding: 13px 16px; border-radius: 18px; color: var(--text-primary);
  font-size: 14.5px; font-weight: 600; }
/* editable: a glass card per slot, flat fields and chips inside */
.fsl-edit.glass { display: grid; grid-template-columns: minmax(0, 1fr); gap: 10px; padding: 14px; border-radius: 22px; }
.fsl-edit-head { display: flex; align-items: center; gap: 10px; }
.fsl-inp { min-width: 0; padding: 10px 12px; border: 0; border-radius: 13px; background: rgba(245, 239, 230, 0.05);
  box-shadow: inset 0 0 0 1px var(--divider); font: 500 14px/1.2 var(--ff-body); color: var(--text-primary);
  color-scheme: dark; }
.fsl-edit-head .fsl-inp { flex: 1 1 0; width: 0; }
.fsl-remove { display: grid; place-items: center; flex: 0 0 auto; width: 36px; height: 36px; border-radius: 50%;
  color: var(--text-secondary); }
.fsl-chips { display: flex; flex-wrap: wrap; gap: 6px; }
.fsl-chip { min-height: 32px; padding: 6px 12px; border-radius: 999px; background: rgba(245, 239, 230, 0.05);
  box-shadow: inset 0 0 0 1px var(--divider); font-size: 12px; font-weight: 600; color: var(--text-secondary); }
.fsl-chip.is-on { background: var(--c); color: #191614; box-shadow: 0 0 12px color-mix(in srgb, var(--c) 50%, transparent); }
.fsl-anchor { display: flex; flex-wrap: wrap; align-items: center; gap: 8px; }
.fsl-anchor select.fsl-inp { font-size: 13px; }
.fsl-time { font-variant-numeric: tabular-nums; }
.fsl-stepper { display: inline-flex; align-items: center; gap: 2px; padding: 2px; border-radius: 999px;
  background: rgba(245, 239, 230, 0.05); box-shadow: inset 0 0 0 1px var(--divider); }
.fsl-stepper button { display: grid; place-items: center; width: 32px; height: 32px; border-radius: 50%;
  background: rgba(245, 239, 230, 0.06); font-size: 16px; color: var(--text-primary); }
.fsl-num { padding: 6px 0; border: 0; background: transparent; text-align: center; font-size: 13px; font-weight: 600;
  font-variant-numeric: tabular-nums; color: var(--text-primary); }
.fsl-pct { display: inline-flex; align-items: center; gap: 4px; margin-left: auto; padding: 2px 10px 2px 4px;
  border-radius: 999px; background: rgba(245, 239, 230, 0.05); box-shadow: inset 0 0 0 1px var(--divider); }
.fsl-pct > span { font-size: 11px; color: var(--text-muted); }
.fsl-add.uv-empty { display: flex; align-items: center; justify-content: center; gap: 7px; width: 100%;
  margin-bottom: 12px; padding: 14px; border-radius: 20px; font-size: 13px; font-weight: 600;
  color: color-mix(in srgb, var(--c) 78%, var(--text-primary)); }
.fsl-sum { display: flex; align-items: center; justify-content: space-between; margin: 4px 2px 10px; }
/* Σ BUDGET: a lit pill — sage when it adds up, coral when it does not */
.fsl-pillsum { display: inline-flex; padding: 6px 12px; border-radius: 999px; font-size: 12px; font-weight: 700;
  color: #191614; background: var(--dv-sage); box-shadow: 0 0 12px color-mix(in srgb, var(--dv-sage) 50%, transparent); }
.fsl-pillsum.is-off { background: var(--dv-coral); box-shadow: 0 0 12px color-mix(in srgb, var(--dv-coral) 50%, transparent); }
.fsl-compiled { display: grid; gap: 6px; margin-bottom: 9px; }
.fsl-compiled-row { padding: 9px 12px; border-radius: 14px; font-size: 12px; font-variant-numeric: tabular-nums;
  color: var(--text-secondary); }
.fsl-note { margin-top: 6px; padding: 9px 12px; border-radius: 14px; font-size: 12px; font-weight: 500; line-height: 1.45; }
.fsl-note.is-error { color: color-mix(in srgb, var(--dv-coral) 75%, var(--text-primary));
  background: color-mix(in srgb, var(--dv-coral) 9%, transparent); box-shadow: inset 3px 0 0 var(--dv-coral); }
.fsl-note.is-warn { color: color-mix(in srgb, var(--dv-amber) 75%, var(--text-primary));
  background: color-mix(in srgb, var(--dv-amber) 8%, transparent); box-shadow: inset 3px 0 0 var(--dv-amber); }
/* Mezo's reading: a lavender flat pill to ask, a lavender glass card for the answer */
.fsl-eval.uv-flat { display: flex; align-items: center; justify-content: center; gap: 8px; width: 100%;
  margin-top: 14px; min-height: 44px; padding: 8px 16px; border-radius: 999px; font-size: 13px; font-weight: 600;
  color: color-mix(in srgb, var(--c) 78%, var(--text-primary));
  box-shadow: inset 0 0 0 1px color-mix(in srgb, var(--c) 40%, transparent); }
.fsl-eval:disabled { opacity: 0.45; }
.fsl-eval-pending { display: flex; align-items: center; justify-content: center; gap: 6px; margin: 10px 2px 0;
  font-size: 11.5px; color: var(--text-muted); }
.fsl-verdict.glass { display: grid; gap: 8px; margin-top: 10px; padding: 14px; border-radius: 20px; }
.fsl-verdict-head { display: flex; align-items: center; gap: 8px; }
.fsl-verdict-chip { margin-left: auto; padding: 4px 10px; border-radius: 999px; font-size: 11px; font-weight: 600;
  color: color-mix(in srgb, var(--dv-sage) 80%, var(--text-primary)); background: rgba(245, 239, 230, 0.05);
  box-shadow: inset 0 0 0 1px color-mix(in srgb, var(--dv-sage) 40%, transparent); }
.fsl-verdict-chip.is-adjust { color: color-mix(in srgb, var(--dv-amber) 80%, var(--text-primary));
  box-shadow: inset 0 0 0 1px color-mix(in srgb, var(--dv-amber) 40%, transparent); }
.fsl-verdict-summary { font-size: 14px; line-height: 1.5; color: var(--text-primary); }
.fsl-verdict-tips { display: grid; gap: 4px; }
.fsl-verdict-tips p { font-size: 12px; line-height: 1.5; color: var(--text-secondary); }
.fsl-eval-degraded { margin: 10px 2px 0; font-size: 11.5px; color: var(--text-muted); }
.fsl-reset { width: 100%; margin-top: 14px; padding: 12px 16px; border: 0; background: rgba(245, 239, 230, 0.05);
  box-shadow: inset 0 0 0 1px var(--divider); font-size: 13px; font-weight: 600; color: var(--text-secondary); }
@media (max-width: 360px) {
  .fsl-seg-btn { font-size: 11px; padding-inline: 4px; }
  .fsl-slot-time { width: 54px; font-size: 18px; }
  .ftx-tile.glass { padding: 11px 8px; }
  .ftx-tile.glass strong { font-size: 19px; }
  .fset-goal input { font-size: 18px; }
}
/* ── /uveg fuel trendek ── */

/* ── uveg nap mai (mezo-me75u.3) ── /nap: heading, orbit, fuel card, Mezo observation, Mai pillanatok ── */
/* Reference: prototypes/uveg-nap.html#mai (`mai()`, `reactor()`, `obsCard()`; CSS `.hubhead`,
   `.orbit`, `.companion`, `.node`, `.fuelc`, `.reactor`, `.rcore`, `.mchip`, `.obs`, `.tlrow`).
   Ranking (bible §3.4): the heading is flat type; the orbit is the frameless HERO (gold +
   lavender halo, a tilted faint ring, the living Boop over the need-colour halo, five bare 3D
   icons that float); the Fuel card (amber) and the Mezo observation (lavender) are the two
   `.glass` objects; everything inside them is flat (macro chips, reply pills, evidence chips —
   U1 rule 5); an empty Fuel day or a missing observation is dashed (`.uv-empty`, rule 6); the
   Mai pillanatok rows stay flat with hairlines and a small 3D icon per kind.
   Geometry lives in NapHubPage.css / NapFuelGraphic.css / NapPersonalInsight.css; everything
   here is scoped to `.nap-hub` (the page root) so the shared `nap-*` names never leak. */

/* one-shot entrance stagger: 70ms per item (--i), on the house `.rise` idiom */
.nap-hub .rise { --d: calc(var(--i, 0) * 70ms); }

/* ── heading: flat type — gold eyebrow, lavender second line ── */
.nap-hub .nap-center-heading p { color: color-mix(in srgb, var(--dv-amber) 80%, var(--text-primary)); }
.nap-hub .nap-center-heading h1 { color: var(--text-primary); }
.nap-hub .nap-center-heading h1 span { color: #C9BDF0; }

/* ── orbit: the frameless hero ── */
/* U2 rule 12: the 380px halo must not scroll a 320px screen sideways */
.nap-hub .nap-center-orbit { background: none; overflow-x: clip; }
.nap-hub .nap-center-orbit::before {
  content: ''; position: absolute; left: 50%; top: 50%; width: 380px; height: 330px; z-index: -1;
  transform: translate(-50%, -50%); pointer-events: none; border: 0; border-radius: 0; box-shadow: none;
  background: radial-gradient(ellipse at 50% 50%,
    color-mix(in srgb, var(--dv-amber) 30%, transparent),
    color-mix(in srgb, var(--dv-lav) 16%, transparent) 40%, transparent 68%);
}
.nap-hub .nap-center-orbit::after {
  content: ''; position: absolute; left: 50%; top: 50%; width: 300px; height: 150px; z-index: 0;
  border-radius: 50%; transform: translate(-50%, -50%) rotate(-14deg); pointer-events: none;
  border: 1px solid rgba(255, 220, 170, 0.16);
  box-shadow: 0 0 22px -6px color-mix(in srgb, var(--dv-amber) 35%, transparent);
}
/* the need-colour halo keeps its meaning (NapCompanion's --aura-*), softened into a glow */
.nap-hub .nap-companion-halo { inset: 0; filter: blur(6px); }
.nap-hub .nap-companion-mark .boop {
  filter: drop-shadow(0 14px 16px rgba(0, 0, 0, 0.55))
          drop-shadow(0 0 22px color-mix(in srgb, var(--dv-lav) 45%, transparent));
}
/* the five nodes: bare 3D icons with an accent halo (--c per node) */
.nap-hub .nap-center-node .t-ico {
  width: 62px; height: 62px;
  filter: drop-shadow(0 10px 10px rgba(0, 0, 0, 0.55))
          drop-shadow(0 0 14px color-mix(in srgb, var(--c) 45%, transparent));
}
.nap-hub .nap-center-node small { color: var(--text-muted); }
.nap-hub .nap-center-read-error { color: var(--text-secondary); }
.nap-hub .nap-center-read-error button { color: #C9BDF0; background: none; border: 0; }
@media (max-width: 360px) {
  .nap-hub .nap-center-node .t-ico { width: 54px; height: 54px; }
}
/* §6 float: the hero icons drift, staggered per node; the reduced branch sits still */
@media (prefers-reduced-motion: no-preference) {
  .nap-hub .nap-center-node .t-ico { animation: uv-float 6s ease-in-out infinite; animation-delay: calc(var(--i, 0) * 0.7s); }
}

/* ── Fuel card: amber glass ── */
.nap-hub .nap-fuel.glass { --c: var(--dv-amber); border: 0; border-radius: 22px; color: var(--text-primary); }
.nap-hub .nap-fuel.uv-empty { --c: var(--dv-amber); position: relative; border-radius: 22px; color: var(--text-primary); }
.nap-hub .nap-fuel-heading h2 { color: var(--text-primary); text-transform: none; letter-spacing: -0.5px; }
/* the "Fuel · ma" tag: a flat chip (rank 3) */
.nap-hub .nap-fuel-tag {
  display: inline-flex; align-items: center; gap: 6px; padding: 6px 11px 6px 8px; border-radius: 999px;
  font-size: 12px; font-weight: 600; white-space: nowrap; color: var(--text-secondary);
  background: rgba(245, 239, 230, 0.05); box-shadow: inset 0 0 0 1px var(--divider);
}
.nap-hub .nap-fuel-tag .t-ico { width: 18px; height: 18px; filter: none; }
/* the reactor arcs: macro colour with its glow (bible §5 ring; --c is set per arc group) */
.nap-hub .nap-fuel-reactor .uv-ring-prog { filter: drop-shadow(0 0 6px color-mix(in srgb, var(--c) 60%, transparent)); }
/* the core: a lit inner disc, not a card */
.nap-hub .nap-fuel-core {
  color: var(--text-primary);
  background: radial-gradient(circle at 35% 30%, #3A332D, #1E1B18);
  box-shadow: inset 0 1px 0 rgba(255, 244, 230, 0.08),
    inset 0 -10px 20px -10px color-mix(in srgb, var(--dv-amber) 40%, transparent),
    0 12px 24px -12px #000;
}
.nap-hub .nap-fuel-core span { color: var(--text-secondary); }
.nap-hub .nap-fuel-core small { color: var(--text-muted); }
.nap-hub .nap-fuel-remaining { color: #FFD99A; font-weight: 600; }
/* the macro chips: FLAT cells inside the glass (U1 rule 5); the pressed one is lit */
.nap-hub .nap-fuel-macro {
  color: var(--text-primary);
  background: rgba(245, 239, 230, 0.04); box-shadow: inset 0 0 0 1px var(--divider);
}
.nap-hub .nap-fuel-macro[aria-pressed=true] {
  background: radial-gradient(90% 100% at 50% 0%, color-mix(in srgb, var(--c) 22%, transparent), rgba(245, 239, 230, 0.03));
  box-shadow: inset 0 0 0 1px color-mix(in srgb, var(--c) 55%, transparent), 0 0 14px -4px var(--c);
}
.nap-hub .nap-fuel-macro > span { color: var(--text-secondary); }
.nap-hub .nap-fuel-macro strong { color: color-mix(in srgb, var(--c) 80%, var(--text-primary)); }
.nap-hub .nap-fuel-macro small { color: var(--text-muted); }
.nap-hub .nap-fuel-macro .t-ico { filter: drop-shadow(0 3px 4px rgba(0, 0, 0, 0.5)); }
.nap-hub .nap-fuel-detail, .nap-hub .nap-fuel-state { color: var(--text-secondary); }
/* the retry: a lit flat pill inside the glass, never glass (rule 5) */
.nap-hub .nap-fuel-state button {
  color: #191614; background: var(--dv-amber);
  box-shadow: 0 0 14px color-mix(in srgb, var(--dv-amber) 55%, transparent);
}

/* ── Mezo observation: lavender glass ── */
.nap-hub .nap-personal.glass { --c: var(--dv-lav); border: 0; border-radius: 22px; color: var(--text-primary); }
.nap-hub .nap-personal.uv-empty { --c: var(--dv-lav); position: relative; border-radius: 22px; color: var(--text-primary); }
/* U1 rule 2: `.glass > *` would drop the 3D art into the flow */
.nap-hub .nap-personal > .nap-personal-art { position: absolute; top: 12px; right: 12px; z-index: 1; }
.nap-hub .nap-personal-heading > span, .nap-hub .nap-personal-eyebrow { color: color-mix(in srgb, var(--dv-lav) 85%, var(--text-primary)); }
.nap-hub .nap-personal-heading a { color: #C9BDF0; }
.nap-hub .nap-personal h2 { color: var(--text-primary); }
.nap-hub .nap-personal-copy { color: var(--text-secondary); }
.nap-hub .nap-personal-copy strong { color: var(--text-primary); }
/* the question is Mezo's own sentence: the voice type (§5) */
.nap-hub .nap-personal-question { font-family: var(--ff-serif); font-style: italic; color: var(--text-primary); }
.nap-hub .nap-personal-evidence { color: var(--text-secondary); border: 0; padding: 0; }
.nap-hub .nap-personal-evidence summary { color: #C9BDF0; }
/* the evidence list: flat chips (rank 3) */
.nap-hub .nap-personal-evidence li { color: var(--text-secondary); background: rgba(245, 239, 230, 0.05); box-shadow: inset 0 0 0 1px var(--divider); }
.nap-hub .nap-personal-evidence li + li { margin-top: 0; }
/* reply pills + the chat link: flat ghost pills; the first answer is the lit one */
.nap-hub .nap-personal-actions button, .nap-hub .nap-personal-chat {
  color: var(--text-secondary); background: rgba(245, 239, 230, 0.05); box-shadow: inset 0 0 0 1px var(--divider);
}
.nap-hub .nap-personal-actions button.is-primary {
  color: #191614; background: var(--dv-lav);
  box-shadow: 0 0 14px color-mix(in srgb, var(--dv-lav) 55%, transparent);
}
.nap-hub .nap-personal-ack { color: #C9BDF0; }
.nap-hub .nap-personal > p[role=status], .nap-hub .nap-personal > p[role=alert] { color: var(--text-secondary); font-size: 13px; }

/* ── Mai pillanatok: flat rows, hairlines, a small 3D icon per kind ── */
.nap-hub .nap-center-timeline header p { color: var(--text-muted); }
.nap-hub .nap-center-timeline h2 { color: var(--text-primary); }
.nap-hub .nap-center-timeline > p { color: var(--text-secondary); }
.nap-hub .nap-center-timeline li { border-top: 1px solid var(--divider); border-bottom: 0; }
.nap-hub .nap-center-timeline time { color: var(--text-muted); }
.nap-hub .nap-center-timeline .nap-moment-ico { width: 30px; height: 30px; filter: drop-shadow(0 3px 4px rgba(0, 0, 0, 0.5)); }
.nap-hub .nap-moment-text { color: var(--text-secondary); }
.nap-hub .nap-center-timeline li button > span[aria-hidden] { color: var(--text-muted); }
/* ── /uveg nap mai ── */

/* ── uveg nap oldalak (mezo-me75u.3) ── /nap/checkin, /nap/eletjel, /nap/kuldetesek, /nap/rutin + intention/reflect sheets ── */
/* Reference: docs/design_2.0/prototypes/src/uveg-nap-body.html `checkin()`, `eletjel()`,
   `kuldetesek()`, `rutin()`, `SH.reflect` + the shared `.backrow/.nhero/.principle/.tickc/.pillx`
   (owner OK 2026-09-23). Every rule is scoped to a page root (`.nap-oldal` = the four pages;
   `.nck-page`, `.ej-page`, `.nap-quest-page`, `.nr-page`) or to `.nap-glass-sheet`, so the shared
   Mozaik scaffold (.mz-page/.mz-backbtn/.mz-principle/.mz-statcell/.mz-mcells) keeps its skin
   everywhere else (bible rule 13). Ranking (§3.4): heroes are frameless halos; the check-in card,
   the six need tiles, the quest cards and the rutin groups are `.glass` (ONE `--c` each); rows,
   ticks, cells, pills inside them are flat; the lit "next"/"Most jön" rows glow INSIDE the card;
   the empty quest state is dashed. */

/* ── the four pages: the aurora shows through; the back control is a small glass pill ── */
.nap-oldal.mz-page { background: transparent; }
.nap-oldal .nap-backrow { padding: 4px 16px 0; }
.nap-oldal .mz-backbtn.glass.nap-back {
  --c: #8A7A6A; display: inline-flex; align-items: center; gap: 6px; height: 38px; padding: 0 14px 0 11px;
  border: 0; border-radius: 999px; font-size: 13.5px; font-weight: 600; color: var(--text-secondary);
}
.nap-oldal .nap-back b { font-size: 19px; font-weight: 400; line-height: 1; margin-top: -2px; }
.nap-oldal .nap-back:focus-visible { outline: 2px solid var(--dv-amber); outline-offset: 2px; }

/* the frameless halo hero (prototype `.nhero`): big 3D art, big numeral with a small "/n" */
.nap-oldal .nap-hero {
  overflow-x: clip; display: grid; justify-items: center; text-align: center;
  padding: 10px 20px 14px;
}
.nap-oldal .nap-hero.uv-halo::before { top: 48%; height: 270px; }
.nap-oldal .nap-hero-art {
  margin: 0 auto 2px;
  filter: drop-shadow(0 12px 14px rgba(0, 0, 0, 0.5)) drop-shadow(0 0 18px color-mix(in srgb, var(--c) 42%, transparent));
}
.nap-oldal .nap-hero-num {
  font-family: var(--ff-display); font-size: 60px; font-weight: 300; letter-spacing: -3px; line-height: 1;
  font-variant-numeric: tabular-nums; color: var(--text-primary);
}
.nap-oldal .nap-hero-num small { font-size: 22px; font-weight: 300; letter-spacing: -1px; margin-left: 2px; color: var(--text-muted); }
.nap-oldal .nap-hero-nm { margin-top: 6px; font-size: 22px; font-weight: 600; letter-spacing: -0.6px; color: var(--text-primary); }
.nap-oldal .nap-hero-sb { margin-top: 3px; font-size: 12.5px; color: var(--text-secondary); }
/* the principle footnote: flat, centred, quiet */
.nap-oldal .mz-principle {
  margin: 22px 10px 0; font-size: 12px; font-weight: 400; line-height: 1.55; text-align: center; color: var(--text-muted);
}
.nap-oldal .mz-page-body { padding: 2px 16px 20px; }

/* the round tick (prototype `.tickc`): ring → lit disc with the 3D t-tick → dashed (future) */
.nap-oldal .nck-tick, .nap-oldal .nr-tick {
  --c: var(--dv-amber);
  width: 40px; height: 40px; border-radius: 50%; flex: 0 0 auto; display: grid; place-items: center;
  border: 0; font-size: 0; color: transparent;
  background: rgba(245, 239, 230, 0.03);
  box-shadow: inset 0 0 0 1.5px color-mix(in srgb, var(--c) 50%, transparent);
}
.nap-oldal .nck-tick.f, .nap-oldal .nr-tick.f {
  background: radial-gradient(circle at 35% 30%, color-mix(in srgb, var(--c) 40%, #3A332D), color-mix(in srgb, var(--c) 14%, #1E1B18));
  box-shadow: 0 0 14px -2px color-mix(in srgb, var(--c) 70%, transparent),
    inset 0 0 0 1.5px color-mix(in srgb, var(--c) 70%, transparent);
}
.nap-oldal .nck-tick.f .t-ico, .nap-oldal .nr-tick.f .t-ico { filter: drop-shadow(0 3px 4px rgba(0, 0, 0, 0.5)); }
.nap-oldal .nck-tick.is-dash {
  box-shadow: none; background: none; border: 1.5px dashed color-mix(in srgb, var(--c) 40%, transparent);
}

/* ── Check-in: ONE rose glass of flat rows with hairlines ── */
.nck-page .nck-card.glass { --c: var(--dv-rose); margin: 4px 0 0; padding: 6px 14px; border: 0; border-radius: 22px; }
.nck-page .nck-row { display: flex; align-items: center; gap: 12px; padding: 13px 0; border-top: 1px solid var(--divider); }
.nck-page .nck-row:first-child { border-top: 0; }
.nck-page .nck-grow { flex: 1; min-width: 0; }
.nck-page .nck-t { font-size: 15px; font-weight: 600; letter-spacing: -0.3px; color: var(--text-primary); }
.nck-page .nck-sub { margin-top: 2px; font-size: 11.5px; color: var(--text-secondary); }
.nck-page .nck-row .nck-tick.f { --c: var(--dv-sage); }
.nck-page .nck-row .nck-tick { --c: var(--dv-rose); }
/* the next fillable row lights up INSIDE the card — a radial wash + inset ring, not a glass */
.nck-page .nck-row.nck-hot {
  margin: 0 -8px; padding: 13px 8px; border-radius: 16px; border-top-color: transparent;
  background: radial-gradient(90% 120% at 0% 50%, color-mix(in srgb, var(--dv-rose) 20%, transparent), transparent 70%);
  box-shadow: inset 0 0 0 1px color-mix(in srgb, var(--dv-rose) 40%, transparent);
}
.nck-page .nck-row.nck-hot + .nck-row { border-top-color: transparent; }
.nck-page .nck-rose { color: var(--text-primary); }
.nck-page .nck-row.nck-dim { opacity: 0.6; }
/* the solid rose "Kitöltöm" pill (prototype `.pillx`), 44px touch floor */
.nck-page .nck-fill {
  flex: 0 0 auto; min-height: 44px; padding: 0 16px; border: 0; border-radius: 999px; cursor: pointer;
  font: inherit; font-size: 12.5px; font-weight: 700; white-space: nowrap; color: #191614;
  background: var(--dv-rose); box-shadow: 0 0 14px color-mix(in srgb, var(--dv-rose) 55%, transparent);
  transition: transform 0.12s ease;
}
.nck-page .nck-fill:active { transform: scale(0.95); }
.nck-page .nck-fill:focus-visible { outline: 2px solid var(--dv-rose); outline-offset: 2px; }
/* the four mini cells: flat, tinted per dimension (prototype `.mcell`) */
.nck-page .nck-cells.mz-mcells { display: grid; grid-template-columns: repeat(4, minmax(0, 1fr)); gap: 5px; max-width: none; margin-top: 8px; }
.nck-page .nck-cells .mz-c-coral { --c: var(--dv-coral); }
.nck-page .nck-cells .mz-c-amber { --c: var(--dv-amber); }
.nck-page .nck-cells .mz-c-rose  { --c: var(--dv-rose); }
.nck-page .nck-cells .mz-c-sky   { --c: var(--dv-sky); }
.nck-page .nck-cells.mz-mcells span {
  padding: 5px 0 4px; border-radius: 10px; text-align: center; min-width: 0;
  background: color-mix(in srgb, var(--c) 10%, rgba(245, 239, 230, 0.03));
  box-shadow: inset 0 0 0 1px color-mix(in srgb, var(--c) 28%, transparent);
}
.nck-page .nck-cells.mz-mcells b { font-size: 14px; font-weight: 600; color: color-mix(in srgb, var(--c) 85%, var(--text-primary)); }
.nck-page .nck-cells.mz-mcells small {
  display: block; font-size: 9px; font-weight: 500; letter-spacing: 0; text-transform: none; opacity: 1; color: var(--text-muted);
  overflow: hidden; text-overflow: ellipsis; white-space: nowrap;
}

/* ── Életjel: the six-arc ring hero, six need glasses ── */
.ej-page .ej-hero { padding-top: 4px; min-height: 40px; }
.ej-page .ej-bigring { position: relative; width: 196px; height: 196px; margin: 4px auto 0; }
.ej-page .ej-bigring > svg { position: absolute; inset: 0; width: 100%; height: 100%; overflow: visible; transform: rotate(-90deg); }
.ej-page .ej-seg-track { fill: none; stroke: rgba(245, 239, 230, 0.07); stroke-width: 13; stroke-linecap: round; }
.ej-page .ej-seg {
  fill: none; stroke: var(--c); stroke-width: 13; stroke-linecap: round;
  filter: drop-shadow(0 0 6px color-mix(in srgb, var(--c) 60%, transparent));
}
.ej-page .ej-core {
  position: absolute; inset: 34px; border-radius: 50%; display: grid; place-content: center; justify-items: center; text-align: center;
  background: radial-gradient(circle at 35% 30%, #3A332D, #1E1B18);
  box-shadow: inset 0 1px 0 rgba(255, 244, 230, 0.08),
    inset 0 -10px 20px -10px color-mix(in srgb, var(--dv-rose) 45%, transparent), 0 12px 24px -12px #000;
}
.ej-page .ej-core .t-ico { filter: drop-shadow(0 4px 6px rgba(0, 0, 0, 0.5)) drop-shadow(0 0 10px color-mix(in srgb, var(--dv-rose) 45%, transparent)); }
.ej-page .ej-avg { display: block; font-family: var(--ff-display); font-size: 34px; font-weight: 300; letter-spacing: -1.8px; line-height: 1; font-variant-numeric: tabular-nums; color: var(--text-primary); }
.ej-page .ej-core small { font-size: 9.5px; font-weight: 600; letter-spacing: 1.2px; color: var(--text-muted); }
.ej-page .ej-mosaic.mz-mosaic { grid-template-columns: repeat(2, minmax(0, 1fr)); gap: 10px; padding-top: 14px; }
.ej-page .ej-tile.glass {
  display: flex; flex-direction: column; gap: 8px; width: 100%; min-width: 0; min-height: 136px; margin: 0;
  padding: 14px; border: 0; border-radius: 21px; text-align: left; font: inherit; color: var(--text-primary);
}
.ej-page button.ej-tile.glass { cursor: pointer; transition: transform 0.25s var(--uv-ease, ease); }
.ej-page button.ej-tile.glass:active { transform: scale(0.985); }
.ej-page button.ej-tile.glass:focus-visible { outline: 2px solid var(--c); outline-offset: 2px; }
.ej-page .ej-tile.is-static { cursor: default; }
.ej-page .ej-eb {
  display: block; font-size: 9.5px; font-weight: 600; letter-spacing: 1.3px; text-transform: uppercase;
  color: color-mix(in srgb, var(--c) 85%, var(--text-primary));
}
.ej-page .ej-trow { display: flex; align-items: center; justify-content: space-between; gap: 6px; margin-top: auto; }
.ej-page .ej-mring { position: relative; width: 54px; height: 54px; flex: 0 0 auto; display: grid; place-items: center; }
.ej-page .ej-mring svg { position: absolute; inset: 0; width: 100%; height: 100%; transform: rotate(-90deg); }
.ej-page .ej-mring circle { stroke-width: 6; }
.ej-page .ej-pct { position: relative; font-size: 14px; font-weight: 600; font-variant-numeric: tabular-nums; color: color-mix(in srgb, var(--c) 80%, var(--text-primary)); }
/* an attention tile: coral (set inline as --c) with a stronger glow — terracotta, never alarm red */
.ej-page .ej-tile.glass.ej-warn {
  box-shadow: 0 16px 30px -16px rgba(0, 0, 0, 0.75),
    0 0 34px -4px color-mix(in srgb, var(--c) 48%, transparent),
    inset 0 1px 0 rgba(255, 244, 230, 0.10),
    inset 0 -14px 26px -18px color-mix(in srgb, var(--c) 60%, transparent);
}
.ej-page .ej-warn .ej-eb::after { content: ' · figyelmet kér'; color: var(--text-muted); letter-spacing: 0.6px; }

/* ── Küldetések: one glass per quest in its slot hue ── */
.nap-quest-page .nq-list { display: grid; gap: 10px; }
.nap-quest-page .nq-card.glass { padding: 14px 14px 12px; border: 0; border-radius: 22px; }
.nap-quest-page .nq-top { display: flex; align-items: flex-start; gap: 12px; }
.nap-quest-page .nq-well { width: 52px; height: 52px; }
.nap-quest-page .nq-grow { flex: 1; min-width: 0; }
.nap-quest-page .nq-title { font-size: 15.5px; font-weight: 600; letter-spacing: -0.3px; line-height: 1.3; color: var(--text-primary); overflow-wrap: anywhere; }
.nap-quest-page .nq-why { margin-top: 5px; font-size: 13px; line-height: 1.4; color: var(--text-secondary); }
.nap-quest-page .nq-why:empty { display: none; }
/* the XP pill: flat, gold-lit (never glass in glass) */
.nap-quest-page .nq-xp {
  flex: 0 0 auto; padding: 5px 10px; border-radius: 999px; font-size: 12px; font-weight: 700; white-space: nowrap; color: #FFD99A;
  background: radial-gradient(90% 120% at 20% 20%, color-mix(in srgb, var(--dv-amber) 22%, transparent), rgba(245, 239, 230, 0.04));
  box-shadow: inset 0 0 0 1px color-mix(in srgb, var(--dv-amber) 40%, transparent), 0 0 12px -4px color-mix(in srgb, var(--dv-amber) 60%, transparent);
}
.nap-quest-page .nq-foot {
  display: flex; flex-wrap: wrap; align-items: center; gap: 8px; margin-top: 12px; padding-top: 10px; border-top: 1px solid var(--divider);
}
.nap-quest-page .nq-state { flex: 1 1 150px; min-width: 0; display: flex; align-items: center; gap: 6px; font-size: 11.5px; color: var(--text-muted); }
.nap-quest-page .nq-state.f { color: var(--text-secondary); font-weight: 600; }
.nap-quest-page .nq-state .t-ico { filter: none; }
.nap-quest-page .nq-state-dot { width: 7px; height: 7px; flex: 0 0 auto; border-radius: 50%; background: var(--c); box-shadow: 0 0 6px var(--c); }
.nap-quest-page .nq-btn {
  flex: 0 0 auto; min-height: 44px; padding: 0 14px; border: 0; border-radius: 999px; cursor: pointer;
  font: inherit; font-size: 12.5px; font-weight: 600; white-space: nowrap; color: var(--text-secondary);
  background: rgba(245, 239, 230, 0.05); box-shadow: inset 0 0 0 1px var(--divider);
}
.nap-quest-page .nq-btn.primary { font-weight: 700; color: #191614; background: var(--c); box-shadow: 0 0 14px color-mix(in srgb, var(--c) 55%, transparent); }
.nap-quest-page .nq-btn:disabled { opacity: 0.45; cursor: default; }
.nap-quest-page .nq-btn:focus-visible { outline: 2px solid var(--c); outline-offset: 2px; }
.nap-quest-page .nq-card.glass.done { opacity: 0.74; }
.nap-quest-page .nq-card.done .nq-title { color: var(--text-secondary); }
.nap-quest-page .nq-empty.uv-empty {
  --c: var(--dv-amber); margin: 6px 0 0; padding: 14px; border-radius: 20px; text-align: center; font-size: 13.5px; color: var(--text-secondary);
}

/* ── Rutin: flat day arrows, flat stat cells, one amber glass per chain group ── */
/* DayNavigator is shared and styles itself inline — the scoped !important is the only way to
   re-dress it here without touching its markup (only on this page). */
.nr-page .nr-daynav { padding: 0 16px; }
.nr-page .nr-daynav > div { justify-content: center !important; }
.nr-page .nr-daynav > div > button {
  width: 34px !important; height: 34px !important; border: 0 !important; border-radius: 50% !important;
  color: var(--text-secondary) !important; background: rgba(245, 239, 230, 0.05) !important;
  box-shadow: inset 0 0 0 1px var(--divider);
}
.nr-page .nr-daynav > div > button:disabled { opacity: 0.35 !important; }
.nr-page .nr-daynav button[aria-label="Dátum kiválasztása"] {
  min-width: 110px; font-size: 14px !important; font-weight: 600 !important; color: var(--text-primary) !important;
}
.nr-page .nr-stats.mz-statstrip { display: grid; grid-template-columns: repeat(auto-fit, minmax(0, 1fr)); gap: 8px; margin-bottom: 0; }
.nr-page .nr-stats .mz-statcell {
  min-width: 0; padding: 10px 6px; border: 0; border-radius: 16px; text-align: center;
  background: rgba(245, 239, 230, 0.05); box-shadow: inset 0 0 0 1px var(--divider);
}
.nr-page .nr-stats .mz-statcell b { font-size: 19px; font-weight: 600; letter-spacing: -0.6px; color: #FFD99A; }
.nr-page .nr-stats .mz-statcell small { display: block; margin-top: 2px; font-size: 10px; line-height: 1.3; color: var(--text-muted); }
.nr-page .nr-group { display: flex; justify-content: space-between; align-items: baseline; gap: 8px; margin: 20px 4px 0; }
.nr-page .nr-group .mz-eyebrow { font-size: 9.5px; font-weight: 600; letter-spacing: 1.3px; color: var(--text-muted); }
.nr-page .nr-groupcount { font-size: 12px; font-weight: 700; font-variant-numeric: tabular-nums; color: var(--text-muted); }
.nr-page .nr-vcard.glass { --c: var(--dv-amber); margin: 12px 0 0; padding: 4px 12px; border: 0; border-radius: 22px; }
.nr-page .nr-row { display: flex; align-items: center; gap: 10px; padding: 11px 0; border-top: 1px solid var(--divider); }
.nr-page .nr-row:first-child { border-top: 0; }
/* the "Most jön" chained row lights up INSIDE the card (never a nested glass) */
.nr-page .nr-row.now {
  margin: 0 -6px; padding: 11px 6px; border-radius: 16px; border-top-color: transparent;
  background: radial-gradient(90% 120% at 0% 50%, color-mix(in srgb, var(--dv-amber) 18%, transparent), transparent 70%);
  box-shadow: inset 0 0 0 1px color-mix(in srgb, var(--dv-amber) 38%, transparent);
}
.nr-page .nr-row.now + .nr-row { border-top-color: transparent; }
.nr-page .nr-nowtag.mz-eyebrow { display: block; margin-bottom: 2px; font-size: 9.5px; font-weight: 700; letter-spacing: 1.2px; color: #FFD99A; }
/* 44px hit area, the 40px round tick inside it */
.nr-page .nr-tickbtn {
  width: 44px; height: 44px; flex: 0 0 auto; margin-left: -2px; padding: 0; border: 0; background: none;
  display: grid; place-items: center; font: inherit; cursor: default;
}
.nr-page button.nr-tickbtn { cursor: pointer; }
.nr-page button.nr-tickbtn:disabled { cursor: default; opacity: 0.6; }
.nr-page button.nr-tickbtn:focus-visible { outline: 2px solid var(--dv-amber); outline-offset: 1px; border-radius: 50%; }
.nr-page .nr-tick { transition: transform 0.12s ease; }
.nr-page button.nr-tickbtn:active .nr-tick { transform: scale(0.9); }
.nr-page .nr-ic { flex: 0 0 auto; display: grid; place-items: center; width: 30px; height: 30px; }
.nr-page .nr-grow { flex: 1; min-width: 0; padding: 0; }
.nr-page .nr-nm { display: block; font-size: 14.5px; font-weight: 600; letter-spacing: -0.2px; color: var(--text-primary); overflow-wrap: anywhere; }
.nr-page a.nr-nm { color: var(--text-primary); text-decoration: none; }
.nr-page a.nr-nm:focus-visible { outline: 2px solid var(--dv-amber); outline-offset: 2px; }
.nr-page .nr-nm.done { font-weight: 600; color: var(--text-secondary); text-decoration: line-through; text-decoration-color: rgba(245, 239, 230, 0.3); }
.nr-page .nr-anchor { margin-top: 1px; font-size: 11px; font-weight: 400; color: var(--text-secondary); }
/* the gold strength bar (kit `.uv-bar` recipe); the width transition stays the base rule's */
.nr-page .nr-str { height: 4px; max-width: 150px; margin-top: 6px; border-radius: 3px; overflow: visible; background: rgba(245, 239, 230, 0.07); }
.nr-page .nr-str > div {
