}
.nr-page .nr-pct { flex: 0 0 auto; width: 36px; text-align: right; font-size: 12.5px; font-weight: 700; font-variant-numeric: tabular-nums; color: #FFD99A; }

/* ── Intention / Reflect sheets: ONE floating amber glass each (bible U2 rule 15) ── */
.sheet.glass.nap-glass-sheet {
  --c: var(--dv-amber);
  position: absolute; left: 10px; right: 10px; bottom: calc(10px + env(safe-area-inset-bottom));
  overflow-x: hidden; overflow-y: auto; border: 0; border-radius: 30px; padding-bottom: 18px;
}
.sheet.glass.nap-glass-sheet .sheet-handle { background: rgba(245, 239, 230, 0.22); }
.nap-glass-sheet .h-display { color: var(--text-primary); }
.nap-glass-sheet .shcreed {
