  background: rgba(245, 239, 230, 0.05); box-shadow: inset 0 0 0 1px var(--divider);
}
.nap-glass-sheet .shta {
  border: 0; border-radius: 14px; color: var(--text-primary); color-scheme: dark;
  background: rgba(245, 239, 230, 0.05); box-shadow: inset 0 0 0 1px var(--divider);
}
.nap-glass-sheet .shta:focus-visible { outline: none; box-shadow: inset 0 0 0 1.5px var(--c); }
/* the save: a lit flat pill in the sheet's hue, not glass */
.nap-glass-sheet .cta-primary {
  padding: 13px 16px; border: 0; border-radius: 999px; font-size: 14.5px; font-weight: 700; color: #FFD99A;
  background: radial-gradient(90% 140% at 20% 20%, color-mix(in srgb, var(--c) 28%, transparent), rgba(245, 239, 230, 0.04));
  box-shadow: inset 0 0 0 1px color-mix(in srgb, var(--c) 45%, transparent), 0 0 16px -4px color-mix(in srgb, var(--c) 60%, transparent);
}
