}
@media (prefers-reduced-motion: reduce) {
  .nck-page .nck-fill, .nr-page .nr-tick, .ej-page button.ej-tile.glass { transition: none; }
}
/* ── /uveg nap oldalak ── */

/* ── uveg nap rogzites (mezo-me75u.3) ── /nap/gyors, quick-log sheet, capture header + capture sheet bodies ── */
/* The approved look: docs/design_2.0/prototypes/src/uveg-nap-body.html `gyors()`, `qsurface()`,
   `capH()`, `saveRow()`, `scale()` + SH.quick/naplopick/water/weight/sleep/sport/journal/activity/
   checkin (CSS "Gyors logolás" + "Rögzítő lapok"). This block replaces the old skin that lived in
   shared/ui/capture.css and features/quickinput/QuickLogSurface.css (§2.2 A wash heroes, the
   --gradient-cta primaries, the white-edged wash tiles). Ranking (bible §3.4), per surface:
     /nap/gyors   the chat row = lavender `.glass`; the nine tiles = `.glass` each in its OWN hue
                  (restored bible rule 27: coloured raised tiles → a glass tile with --c = its hue).
     the sheets   ONE glass surface (floating 10px off the edges, 30px radius — U2 rule 15) in the
                  sheet's accent; inside it everything is flat (U1 rule 5): the quick-log rows and
                  tiles flat-lit, the one loud value a frameless radial wash with a 64px/200 glowing
                  numeral, scales as recess → tinted → solid cells, chips/segments flat with the
                  active one solid + glow, fields flat, Mentés the same lit primary everywhere
                  (restored bible rule 34), Mégse a flat pill. */

/* the sheet accent, published on the element that wears the glass (U1 rule 4) */
.capture-tone-food, .capture-tone-training, .capture-tone-quick { --capture-accent: var(--dv-coral); }
.capture-tone-water, .capture-tone-weight { --capture-accent: var(--dv-sky); }
.capture-tone-stack { --capture-accent: var(--dv-amber); }
.capture-tone-chat, .capture-tone-sleep { --capture-accent: var(--dv-lav); }
.capture-tone-journal { --capture-accent: var(--dv-sage); }
.capture-tone-sport, .capture-tone-checkin { --capture-accent: var(--dv-rose); }

/* ─ the sheet: one floating glass surface (U1 rules 1 + 3: restate the anchor and the scroll) ─ */
.sheet.capture-sheet.glass {
  --c: var(--capture-accent, var(--dv-sage));
  position: absolute; left: 10px; right: 10px; bottom: calc(10px + env(safe-area-inset-bottom));
  max-height: calc(100% - 70px); overflow-x: hidden; overflow-y: auto;
  padding: 4px 18px 22px; border: 0; border-radius: 30px;
}
.sheet.capture-sheet .sheet-handle-zone { margin: 0 -18px 4px; }
.sheet.capture-sheet .sheet-handle { width: 40px; height: 5px; background: rgba(245, 239, 230, 0.18); }
.capture-sheet p { margin: 0; }

/* ─ capture header (`capH`): back · centred eyebrow · close, then the 68px art + title + sub ─ */
.capture-header { width: 100%; margin-bottom: 14px; text-align: left; }
.capture-toolbar { display: grid; grid-template-columns: 44px minmax(0, 1fr) 44px; align-items: center; gap: 8px; margin-bottom: 8px; }
.capture-eyebrow { font: 600 9.5px/1.2 var(--ff-body); letter-spacing: 1.3px; text-transform: uppercase; text-align: center;
  color: color-mix(in srgb, var(--c, var(--capture-accent)) 80%, var(--text-primary));
  overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }
.capture-dismiss { display: grid; place-items: center; width: 44px; height: 44px; padding: 0; border: 0; border-radius: 50%;
  cursor: pointer; font-family: inherit; color: var(--text-secondary);
  background: rgba(245, 239, 230, 0.06); box-shadow: inset 0 0 0 1px var(--divider); }
.capture-dismiss:focus-visible { outline: 2px solid color-mix(in srgb, var(--c) 70%, var(--text-primary)); outline-offset: 2px; }
.capture-heading { display: flex; align-items: center; gap: 14px; }
.capture-heading > div { min-width: 0; }
.capture-heading .capture-art, .quicklog-head .quicklog-head-art {
  flex: 0 0 auto; width: 68px; height: 68px;
  filter: drop-shadow(0 10px 12px rgba(0, 0, 0, 0.5)) drop-shadow(0 0 16px color-mix(in srgb, var(--c, var(--dv-sage)) 45%, transparent)); }
.capture-heading h2 { margin: 0; font: 600 22px/1.2 var(--ff-display); letter-spacing: -0.7px; color: var(--text-primary); overflow-wrap: anywhere; }
.capture-heading p { margin: 2px 0 0; font-size: 12.5px; line-height: 1.45; color: var(--text-secondary); }

/* ─ the one loud value: a frameless radial wash in the sheet accent + the glowing numeral ─ */
.capture-sheet .capture-hero {
  position: relative; margin: 0 -4px 4px; padding: 14px 0 12px; border: 0; border-radius: 22px; text-align: center;
  background: radial-gradient(ellipse at 50% 40%, color-mix(in srgb, var(--c) 26%, transparent), transparent 70%);
  box-shadow: none;
}
.capture-hero-value, .capture-check-value {
  font: 200 64px/1 var(--ff-display); letter-spacing: -3px; font-variant-numeric: tabular-nums;
  color: color-mix(in srgb, var(--c) 45%, #fff);
  text-shadow: 0 0 24px color-mix(in srgb, var(--c) 55%, transparent); }
.capture-hero-unit, .capture-hero-value small, .capture-check-value small {
  margin-left: 4px; font: 400 20px/1 var(--ff-display); letter-spacing: 0; color: var(--text-secondary); text-shadow: none; }
.capture-hero-sub { display: block; margin-top: 6px; font-size: 12px; color: var(--text-secondary); }
.capture-water-hero { display: grid; place-items: center; min-height: 120px; }
/* the scale ruler under the kg value, with a lit accent needle */
.capture-ruler { position: relative; height: 26px; margin: 10px 18px 0;
  background: repeating-linear-gradient(90deg, rgba(245, 239, 230, 0.25) 0 1px, transparent 1px 10px);
  -webkit-mask: linear-gradient(90deg, transparent, #000 20%, #000 80%, transparent);
  mask: linear-gradient(90deg, transparent, #000 20%, #000 80%, transparent); }
.capture-ruler::after { content: ''; position: absolute; left: 50%; top: -4px; bottom: -4px; width: 2px; margin-left: -1px;
  border-radius: 2px; background: var(--c); box-shadow: 0 0 10px var(--c); }
/* the night arc under the hours */
.capture-night-arc { display: block; width: 220px; max-width: 100%; height: 70px; margin: 4px auto 8px; overflow: visible; }
.capture-night-arc-track, .capture-night-arc-fill { fill: none; stroke-width: 4; stroke-linecap: round; }
.capture-night-arc-track { stroke: rgba(245, 239, 230, 0.1); }
.capture-night-arc-fill { stroke: var(--c); stroke-dasharray: 190 999; filter: drop-shadow(0 0 6px var(--c)); }

/* ─ chips + segments: flat pills; the active one solid in the accent with a glow ─ */
.capture-chiprow { display: flex; flex-wrap: wrap; justify-content: center; gap: 6px; margin: 10px 0 4px; }
.capture-segs, .capture-chips { display: flex; flex-wrap: wrap; gap: 6px; margin: 0 0 12px; }
.capture-segs > .capture-seg { flex: 1 1 0; justify-content: center; }
.capture-sheet :is(.chip, .capture-seg) {
  display: inline-flex; align-items: center; gap: 6px; min-width: 0; min-height: 40px; padding: 8px 14px;
  border: 0; border-radius: 999px; clip-path: none; cursor: pointer;
  font: 600 12.5px/1.2 var(--ff-body); letter-spacing: 0; text-transform: none; color: var(--text-secondary);
  background: rgba(245, 239, 230, 0.05); box-shadow: inset 0 0 0 1px var(--divider); }
.capture-sheet :is(.chip, .capture-seg)[aria-pressed="true"] {
  color: var(--page, #191614); font-weight: 700; background: var(--c);
  box-shadow: 0 0 12px color-mix(in srgb, var(--c) 50%, transparent); }
.capture-sheet :is(.chip, .capture-seg):focus-visible { outline: 2px solid color-mix(in srgb, var(--c) 70%, var(--text-primary)); outline-offset: 2px; }

/* ─ 1–10 scales (`scale()`): recess → tinted filled → solid active with glow; data-state kept ─ */
.capture-rating-scale { display: grid; grid-template-columns: repeat(10, minmax(0, 1fr)); gap: 4px; }
.capture-scale-cell {
  height: 38px; min-height: 38px; padding: 0; border: 0; border-radius: 10px; cursor: pointer;
  display: grid; place-items: center; font: 600 13px/1 var(--ff-display); font-variant-numeric: tabular-nums;
  color: var(--text-muted); background: rgba(245, 239, 230, 0.04); box-shadow: inset 0 0 0 1px var(--divider);
  transition: background var(--duration-fast) var(--ease-out), color var(--duration-fast) var(--ease-out); }
.capture-scale-cell[data-state="filled"] {
  color: color-mix(in srgb, var(--cell-hue) 85%, var(--text-primary));
  background: color-mix(in srgb, var(--cell-hue) 16%, transparent);
  box-shadow: inset 0 0 0 1px color-mix(in srgb, var(--cell-hue) 30%, transparent); }
.capture-scale-cell[data-state="active"] {
  color: var(--page, #191614); font-weight: 700; background: var(--cell-hue);
  box-shadow: 0 0 12px color-mix(in srgb, var(--cell-hue) 60%, transparent); }
.capture-scale-l { display: flex; justify-content: space-between; margin-top: 6px; font-size: 11px; color: var(--text-muted); }

/* ─ fields: flat (the sheet is the one glass surface) ─ */
.capture-sheet .card { border: 0; border-radius: 14px; clip-path: none; filter: none;
  background: rgba(245, 239, 230, 0.05); box-shadow: inset 0 0 0 1px var(--divider); }
.capture-sheet :is(input, textarea, select) { font-size: 16px !important; color: var(--text-primary); }
.capture-sheet textarea { min-height: 100px !important; resize: vertical !important; line-height: 1.5 !important;
  border: 0; border-radius: 13px; padding: 11px 13px; background: rgba(245, 239, 230, 0.05); box-shadow: inset 0 0 0 1px var(--divider); }
.capture-sheet textarea::placeholder, .capture-sheet input::placeholder { color: var(--text-muted); }
.capture-sheet .card textarea { background: transparent; box-shadow: none; padding: 4px 6px; }
.capture-sheet :is(input, textarea):focus-visible { outline: 2px solid color-mix(in srgb, var(--c) 70%, var(--text-primary)); outline-offset: 3px; }
.capture-sheet input[type="range"] { accent-color: var(--c); }
.capture-sheet .capture-field-row { border-radius: 13px; background: rgba(245, 239, 230, 0.05); box-shadow: inset 0 0 0 1px var(--divider); }
.capture-sheet .stepper { border-radius: 14px; background: rgba(245, 239, 230, 0.04); box-shadow: inset 0 0 0 1px var(--divider); }
.capture-sheet .stepper button { border-radius: 50%; color: color-mix(in srgb, var(--c) 70%, var(--text-primary)); }
.capture-sheet .stepper-display { font-weight: 300; }
/* the TimePicker's style is inline and shared with the Én sleep page, hence the !important */
.capture-sheet .capture-hero select { border: 0 !important; border-radius: 12px; min-height: 40px;
  background: rgba(245, 239, 230, 0.06) !important; box-shadow: inset 0 0 0 1px var(--divider); }
.capture-section { margin-top: 14px; }
.capture-warn { font-size: 11px; line-height: 1.45; color: var(--warning); }
/* a Mezo-side hint (the night trace): a flat cell in the sheet accent */
.capture-note { align-items: flex-start; padding: 10px 12px; border-radius: 14px;
  background: color-mix(in srgb, var(--c) 8%, rgba(245, 239, 230, 0.02)); box-shadow: inset 0 0 0 1px color-mix(in srgb, var(--c) 26%, transparent); }
.capture-note-text { flex: 1; font-size: 12px; line-height: 1.5; color: var(--text-secondary); }
.capture-sheet .capture-shot-pick { justify-content: center; min-height: 52px; font-size: 13px;
  color: color-mix(in srgb, var(--c) 80%, var(--text-primary));
  box-shadow: inset 0 0 0 1px color-mix(in srgb, var(--c) 40%, transparent); }
.capture-drafting { margin-bottom: 14px; padding: 22px 16px; border-radius: 18px; text-align: center; display: grid; justify-items: center; gap: 8px;
  background: radial-gradient(ellipse at 50% 30%, color-mix(in srgb, var(--c) 22%, transparent), transparent 72%); }
.capture-drafting-title { font: 600 17px/1.3 var(--ff-display); color: var(--text-primary); }
.capture-drafting-dot { width: 12px; height: 12px; border-radius: 50%; border: 1.5px solid var(--c); box-shadow: 0 0 8px var(--c); }
.capture-sheet .capture-mic { position: absolute; top: 8px; right: 8px; min-height: 0; padding: 8px; }
.capture-sheet .capture-mic.is-live { color: var(--page, #191614); background: var(--dv-coral);
  box-shadow: 0 0 12px color-mix(in srgb, var(--dv-coral) 55%, transparent); }

/* ─ the actions (`saveRow()`): Mégse flat · Mentés the lit primary in the sheet accent ─ */
.capture-actions { display: grid; grid-template-columns: 1fr 1.6fr; gap: 10px; margin-top: 18px; }
.capture-actions.is-single { grid-template-columns: 1fr; }
.capture-sheet .cta-primary {
  display: inline-flex; align-items: center; justify-content: center; gap: 8px; width: 100%; min-height: 52px;
  padding: 14px 16px; border: 0; border-radius: 18px; clip-path: none;
  font: 700 15px/1.2 var(--ff-body); color: var(--page, #191614);
  background: linear-gradient(135deg, color-mix(in srgb, var(--c) 70%, #fff), var(--c));
  box-shadow: 0 0 18px -2px color-mix(in srgb, var(--c) 60%, transparent), inset 0 1px 0 rgba(255, 255, 255, 0.45); }
.capture-sheet .cta-primary .t-ico { width: 22px; height: 22px; filter: none; }
.capture-sheet .cta-primary:disabled { opacity: 0.45; box-shadow: none; }
.capture-sheet .cta-ghost {
  min-height: 52px; padding: 13px 16px; border: 0; border-radius: 18px; clip-path: none;
  font: 600 14.5px/1.2 var(--ff-body); color: var(--text-secondary);
  background: rgba(245, 239, 230, 0.05); box-shadow: inset 0 0 0 1px var(--divider); }
.capture-sheet :is(.cta-primary, .cta-ghost):focus-visible { outline: 2px solid color-mix(in srgb, var(--c) 70%, var(--text-primary)); outline-offset: 3px; }
/* the journal's delete pair keeps its warning colour, on the flat material */
.capture-sheet .cta-primary.capture-danger { color: #fff; background: var(--error); box-shadow: 0 0 16px -4px color-mix(in srgb, var(--error) 60%, transparent); }
.capture-sheet .cta-ghost.capture-danger-ghost { color: var(--error); background: color-mix(in srgb, var(--error) 7%, transparent);
  box-shadow: inset 0 0 0 1px color-mix(in srgb, var(--error) 35%, transparent); }

/* ─ check-in (`SH.checkin`): progress, step label, orbit number, nav, summary ─ */
.capture-prog { display: grid; grid-template-columns: repeat(5, 1fr); gap: 5px; margin: 0 0 14px; }
.capture-prog i { height: 5px; border-radius: 3px; background: rgba(245, 239, 230, 0.08); }
.capture-prog i.on { background: var(--c); box-shadow: 0 0 8px var(--c); }
.capture-step { gap: 10px; }
.capture-stepl { font: 700 10.5px/1.2 var(--ff-body); letter-spacing: 1.4px; text-transform: uppercase;
  color: color-mix(in srgb, var(--c) 85%, var(--text-primary)); }
.capture-stepq { margin-top: 3px; font-size: 12px; letter-spacing: 0.8px; text-transform: uppercase; color: var(--text-secondary); }
.capture-check-orbit { position: relative; isolation: isolate; display: flex; align-items: center; justify-content: center; gap: 16px;
  padding: 16px 0 12px; overflow-x: clip; }
.capture-check-orbit::before { content: ''; position: absolute; left: 50%; top: 50%; z-index: -1; width: 260px; height: 170px;
  max-width: 100%; transform: translate(-50%, -50%); pointer-events: none;
  background: radial-gradient(ellipse, color-mix(in srgb, var(--c) 30%, transparent), transparent 68%); }
.capture-check-orbit > .capture-art { flex: 0 0 auto; width: 58px; height: 58px;
  filter: drop-shadow(0 8px 10px rgba(0, 0, 0, 0.5)) drop-shadow(0 0 14px color-mix(in srgb, var(--c) 45%, transparent)); }
.capture-check-value { font-size: 60px; line-height: 1; }
.capture-check-value small { font-size: 18px; }
.capture-stepnav { display: flex; justify-content: space-between; margin-top: 4px; }
.capture-stepnav button { min-height: 44px; padding: 8px 4px; border: 0; background: none; cursor: pointer;
  font: 600 13px/1 var(--ff-body); color: var(--text-secondary); }
.capture-sum-eyebrow { font: 600 9.5px/1.2 var(--ff-body); letter-spacing: 1.3px; text-transform: uppercase; color: var(--text-muted); }
.capture-sum-title { margin-top: 4px; font: 600 19px/1.25 var(--ff-display); letter-spacing: -0.4px; color: var(--text-primary); }
.capture-sum4 { display: grid; grid-template-columns: 1fr 1fr; gap: 8px; }
.capture-sum { display: block; padding: 10px 12px; border: 0; border-radius: 14px; text-align: left; cursor: pointer; font-family: inherit;
  background: rgba(245, 239, 230, 0.04); box-shadow: inset 0 0 0 1px var(--divider); }
.capture-sum small { display: block; font-size: 10.5px; color: var(--text-muted); }
.capture-sum > b { display: block; margin: 2px 0 6px; font: 600 20px/1.1 var(--ff-display); font-variant-numeric: tabular-nums;
  color: color-mix(in srgb, var(--c) 85%, var(--text-primary)); }
.capture-sum .uv-bar { height: 4px; }

/* ─ activity (`SH.activity`): the quest callout, the skill chips, the done phase ─ */
.capture-quest { --c: var(--dv-amber); display: flex; align-items: flex-start; gap: 10px; margin: 0 0 12px; padding: 12px 14px;
  border-radius: 18px; background: color-mix(in srgb, var(--c) 8%, transparent); box-shadow: inset 3px 0 0 var(--c); }
.capture-quest-title { font-size: 14px; font-weight: 600; line-height: 1.4; color: var(--text-primary); }
.capture-quest-xp { font-size: 12px; color: color-mix(in srgb, var(--c) 80%, var(--text-primary)); }
.capture-skillchips { display: grid; grid-template-columns: 1fr 1fr; gap: 8px; margin-top: 4px; }
.capture-skillchip { display: flex; align-items: center; gap: 8px; min-width: 0; min-height: 44px; padding: 10px; border: 0; border-radius: 14px;
  cursor: pointer; font: 600 13px/1.2 var(--ff-body); color: var(--text-primary); text-align: left;
  background: rgba(245, 239, 230, 0.04); box-shadow: inset 0 0 0 1px var(--divider); }
.capture-skillchip:disabled { opacity: 0.5; cursor: default; }
.capture-gotit { display: grid; justify-items: center; gap: 6px; padding: 8px 0 4px; text-align: center; }
.capture-gotit-art { width: 70px; height: 70px;
  filter: drop-shadow(0 10px 12px rgba(0, 0, 0, 0.5)) drop-shadow(0 0 18px rgba(255, 190, 96, 0.5)); }
.capture-gotit-skill { display: inline-flex; align-items: center; gap: 6px; max-width: 100%; padding: 7px 12px; border-radius: 999px;
  font-size: 12.5px; font-weight: 600; color: var(--text-secondary);
  background: rgba(245, 239, 230, 0.05); box-shadow: inset 0 0 0 1px var(--divider); }
.capture-xp { display: block; font: 300 30px/1.1 var(--ff-display); letter-spacing: -1.4px; color: #FFD99A;
  text-shadow: 0 0 18px rgba(255, 190, 96, 0.45); }
.capture-gotit-quest { display: flex; align-items: center; gap: 6px; font-size: 12px; line-height: 1.45; color: var(--text-secondary); }

/* ─ the quick-log surface (`gyors()` / `qsurface()` / `SH.quick` / `SH.naplopick`) ─ */
.nap-gyors.mz-page { background: transparent; }
.nap-gyors .mz-backbtn.glass { --c: var(--text-muted); height: 38px; padding: 0 14px 0 11px; border-radius: 999px;
  font-size: 13.5px; font-weight: 600; color: var(--text-secondary); }
.nap-gyors .rise { --d: calc(var(--i, 0) * 70ms); }
.quicklog { padding: 4px 0 12px; }
.quicklog h2 { margin: 0; font: 600 28px/1.15 var(--ff-display); letter-spacing: -1px; color: var(--text-primary); }
.quicklog .quicklog-sub { margin: 3px 0 0; font-size: 13px; line-height: 1.45; color: var(--text-secondary); }
.quicklog-page-head { padding: 6px 4px 12px; }
.quicklog-eyebrow { display: block; margin-bottom: 8px; text-align: center; font: 600 9.5px/1.2 var(--ff-body); letter-spacing: 1.3px;
  text-transform: uppercase; color: color-mix(in srgb, var(--c, var(--dv-coral)) 80%, var(--text-primary)); }
.quicklog-tool { display: grid; grid-template-columns: 44px minmax(0, 1fr) 44px; align-items: center; gap: 8px; margin-bottom: 8px; }
.quicklog-tool .quicklog-eyebrow { margin: 0; --c: var(--dv-sage); }
.quicklog-back { display: grid; place-items: center; width: 44px; height: 44px; padding: 0; border: 0; border-radius: 50%; cursor: pointer;
  color: var(--text-secondary); background: rgba(245, 239, 230, 0.06); box-shadow: inset 0 0 0 1px var(--divider); }
.quicklog-head { display: flex; align-items: center; gap: 14px; margin-bottom: 12px; }
.quicklog-head > div { min-width: 0; }
.quicklog-head h2 { font-size: 22px; letter-spacing: -0.7px; }
.quicklog-tool + .quicklog-head { --c: var(--dv-sage); }
.quicklog-head .quicklog-sub { font-size: 12.5px; margin-top: 2px; }
/* the Mezo chat row: Boop in a lit well, label, hint, chevron */
.quicklog .quicklog-chat {
  --c: var(--dv-lav); display: flex; align-items: center; gap: 12px; width: 100%; margin: 0 0 12px;
  padding: 10px 14px 10px 10px; border: 0; border-radius: 22px; cursor: pointer; text-align: left;
  font-family: inherit; color: var(--text-primary); }
.quicklog .quicklog-chat.glass { position: relative; }
.quicklog[data-variant="sheet"] .quicklog-chat {
  background: radial-gradient(90% 120% at 0% 50%, color-mix(in srgb, var(--dv-lav) 22%, transparent), rgba(245, 239, 230, 0.03));
  box-shadow: inset 0 0 0 1px color-mix(in srgb, var(--dv-lav) 40%, transparent); }
.quicklog .quicklog-chat-mark {
  display: grid; place-items: center; width: 54px; height: 54px; flex: 0 0 auto; border-radius: 50%;
  background: radial-gradient(circle at 35% 28%, #3A332D, color-mix(in srgb, var(--c) 14%, #1E1B18));
  box-shadow: inset 0 1px 0 rgba(255, 244, 230, 0.08), inset 0 -6px 12px -8px color-mix(in srgb, var(--c) 70%, transparent),
    0 0 14px -4px color-mix(in srgb, var(--c) 50%, transparent); }
.quicklog .quicklog-chat-text { flex: 1; min-width: 0; display: flex; flex-direction: column; gap: 1px; }
.quicklog .quicklog-chat-label { font-size: 15.5px; font-weight: 600; line-height: 1.3; }
.quicklog .quicklog-chat-hint { font-size: 11.5px; font-weight: 400; line-height: 1.4; color: var(--text-secondary); opacity: 1; }
.quicklog .quicklog-chat > svg:last-child { flex: 0 0 auto; color: var(--text-muted); }
/* the nine doors: 3 across; a glass tile each in its own hue on the page, flat-lit in the sheet */
.quicklog .quicklog-grid { display: grid; grid-template-columns: repeat(3, minmax(0, 1fr)); gap: 10px; margin: 0; }
.quicklog .quicklog-tile {
  --c: var(--dv-lav); display: flex; flex-direction: column; align-items: center; justify-content: center; gap: 8px;
  width: 100%; min-width: 0; min-height: 112px; padding: 16px 4px 13px; border: 0; border-radius: 22px;
  cursor: pointer; text-align: center; font-family: inherit;
  background: radial-gradient(90% 100% at 50% 0%, color-mix(in srgb, var(--c) 22%, transparent), rgba(245, 239, 230, 0.03));
  box-shadow: inset 0 0 0 1px color-mix(in srgb, var(--c) 40%, transparent);
  transition: transform 0.2s var(--ease-out); }
.quicklog .quicklog-tile.glass { position: relative; }
.quicklog .quicklog-tile.tone-coral { --c: var(--dv-coral); }
.quicklog .quicklog-tile.tone-sky   { --c: var(--dv-sky); }
.quicklog .quicklog-tile.tone-gold  { --c: var(--dv-amber); }
.quicklog .quicklog-tile.tone-rose  { --c: var(--dv-rose); }
.quicklog .quicklog-tile.tone-sage  { --c: var(--dv-sage); }
.quicklog .quicklog-tile.tone-lav   { --c: var(--dv-lav); }
/* the glass tile's own body (U2 rule 11: the flat-lit rule above would outrank `.glass`) */
.quicklog .quicklog-tile.glass, .quicklog .quicklog-chat.glass {
  background:
    radial-gradient(120% 90% at 0% 0%, color-mix(in srgb, var(--c) 22%, transparent), transparent 62%),
    linear-gradient(160deg, rgba(52, 46, 41, 0.72), rgba(30, 27, 24, 0.60));
  box-shadow:
    0 16px 30px -16px rgba(0, 0, 0, 0.75),
    0 0 26px -6px color-mix(in srgb, var(--c) 30%, transparent),
    inset 0 1px 0 rgba(255, 244, 230, 0.10),
    inset 0 -14px 26px -18px color-mix(in srgb, var(--c) 55%, transparent); }
.quicklog .quicklog-art { flex: 0 0 auto; width: 54px; height: 54px; }
.quicklog:not([data-variant="page"]) .quicklog-art, .quicklog .quicklog-tile:not(.glass) .quicklog-art {
  filter: drop-shadow(0 6px 7px rgba(0, 0, 0, 0.5)) drop-shadow(0 0 10px color-mix(in srgb, var(--c) 35%, transparent)); }
.quicklog .quicklog-label { font-size: 13px; font-weight: 600; letter-spacing: -0.2px; color: var(--text-primary); }
.quicklog :is(.quicklog-tile, .quicklog-chat, .quicklog-back):focus-visible { outline: 2px solid color-mix(in srgb, var(--c, var(--dv-lav)) 70%, var(--text-primary)); outline-offset: 3px; }
@media (hover: hover) { .quicklog .quicklog-tile:hover { transform: translateY(-2px); } }

/* 320px step-down */
@media (max-width: 360px) {
  .sheet.capture-sheet.glass { padding-inline: 14px; }
  .sheet.capture-sheet .sheet-handle-zone { margin-inline: -14px; }
  .capture-heading { gap: 12px; }
  .capture-heading .capture-art, .quicklog-head .quicklog-head-art { width: 56px; height: 56px; }
  .capture-hero-value { font-size: 56px; }
  .capture-rating-scale { gap: 3px; }
  .quicklog .quicklog-grid { gap: 8px; }
  .quicklog .quicklog-tile { min-height: 104px; border-radius: 18px; }
  .quicklog .quicklog-art { width: 46px; height: 46px; }
  .quicklog h2 { font-size: 25px; }
  .quicklog .quicklog-chat { gap: 10px; padding-right: 10px; }
}
@media (prefers-reduced-motion: reduce) { .quicklog .quicklog-tile, .capture-scale-cell { transition: none; } }
/* ── /uveg nap rogzites ── */

/* ── uveg nap uzenetek (mezo-me75u.3) ── /nap/uzenetek (Üzenetek, Életjelek, Észrevételek) + the header notification panel ── */
/* Source: prototypes/uveg-nap.html#uzenetek (+ /eletjelek, /eszrevetelek, the bell). Ranking
   (§3.4): the hero is a frameless halo; the newest message, a nudge, the Életjel strip, an
   observation and the chat CTA are glass; tabs, older rows, chips and cells are flat; error /
   empty are dashed. The old light skin of these classes was removed with this block. */
.nap-mzpage.mz-page {
  background: radial-gradient(120% 40% at 50% 0%, color-mix(in srgb, var(--dv-lav) 12%, transparent), transparent 70%);
}
/* back pill: the house .mz-backbtn as a small still glass (rule 11: geometry restated here) */
.nap-mzpage .mz-backbtn.glass {
  --c: #8A7A6A; height: 38px; padding: 0 14px 0 11px; border: 0; border-radius: 999px;
  font-size: 13.5px; font-weight: 600; color: var(--text-secondary);
}
/* hero (rank 1): no card, a lavender + gold halo around the living Mezo Boop; 320px-safe (rule 12) */
.nap-mzpage .nap-mzhero { --c: var(--dv-lav); --c2: var(--dv-amber); overflow-x: clip; padding: 10px 20px 14px; gap: 0; }
.nap-mzhero .boop {
  width: 90px; height: 90px;
  filter: drop-shadow(0 12px 14px rgba(0, 0, 0, 0.5)) drop-shadow(0 0 18px color-mix(in srgb, var(--c) 42%, transparent));
}
.nap-mzhero .mz-hero-nm { margin-top: 6px; font-size: 22px; font-weight: 600; letter-spacing: -0.6px; color: var(--text-primary); }
.nap-mzhero .mz-hero-sb { margin-top: 3px; font-size: 12.5px; color: var(--text-secondary); }

/* tabs: ONE flat segmented control; active = solid lavender with a glow, unread dot coral */
.nap-mzseg.uv-flat { display: flex; gap: 0; padding: 3px; margin-bottom: 12px; border-radius: 999px; }
.nap-mzseg button {
  position: relative; flex: 1; min-width: 0; min-height: 44px; border: 0; background: none; border-radius: 999px;
  display: flex; align-items: center; justify-content: center;
  font-family: inherit; font-size: 12.5px; font-weight: 600; color: var(--text-secondary); cursor: pointer;
}
.nap-mzseg button.on { background: var(--dv-lav); color: #191614; box-shadow: 0 0 12px rgba(171, 159, 210, 0.45); }
.nap-mzdot {
  position: absolute; top: 8px; right: 12px; width: 6px; height: 6px; border-radius: 50%;
  background: var(--dv-coral); box-shadow: 0 0 6px var(--dv-coral);
}

/* the message card (rank 2): lavender glass; a nudge publishes its need hue on the same element */
.nap-mzmsg.glass { margin-bottom: 12px; padding: 14px 14px 12px; border-radius: 22px; }
.nap-mzmsg-h { display: flex; align-items: center; gap: 10px; }
.nap-mzmsg-art.uv-well { width: 44px; height: 44px; }
.nap-mzmsg .t { min-width: 0; font-size: 14px; font-weight: 600; letter-spacing: -0.2px; color: var(--text-primary); }
.nap-mzmsg-collapse {
  margin-left: auto; flex: none; min-width: 44px; min-height: 44px;
  display: flex; align-items: center; justify-content: center;
  border: 0; background: none; font-family: inherit; color: var(--text-muted); cursor: pointer;
}
.nap-mzmsg .txt { margin: 10px 0 0; font-size: 14px; line-height: 1.55; color: var(--text-primary); }
.nap-mzmsg .txt + .txt { margin-top: 8px; }
.nap-mzmsg-meta { margin-top: 8px; font-size: 11px; color: var(--text-muted); }
.nap-mzmsg-meta.is-eb {
  margin: 12px 0 6px; font: 600 9.5px/1.2 var(--ff-body); letter-spacing: 1.3px; text-transform: uppercase;
}
/* "AMIRE ÉPÜLT": the shared RefChips, worn flat inside the card (never glass in glass) */
.nap-mzmsg .mzc-reffoot { margin-top: 12px; padding-top: 0; border-top: 0; }
.nap-mzmsg .mzc-refeb {
  display: block; font: 600 9.5px/1.2 var(--ff-body); letter-spacing: 1.3px; color: var(--text-muted);
}
.nap-mzmsg .mzc-refrow { gap: 6px; }
.nap-mzmsg .mzc-refch, .nap-mzmsg .mzc-refg {
  padding: 5px 10px 5px 5px; border: 0; border-radius: 999px; font-size: 11px; font-weight: 600;
  color: var(--text-secondary); background: rgba(245, 239, 230, 0.05); box-shadow: inset 0 0 0 1px var(--divider);
}
.nap-mzmsg .mzc-refg.on { color: #191614; background: var(--c); box-shadow: 0 0 12px color-mix(in srgb, var(--c) 50%, transparent); }
.nap-mzmsg .mzc-refch .mzc-refk { color: var(--text-primary); font-weight: 700; }
.nap-mzmsg .mzc-refic { background: rgba(245, 239, 230, 0.06); }
/* suggestions + "Miből gondolom" facts (small lavender dots) */
.nap-mzmsg-sug { margin: 8px 0 0; padding-left: 18px; font-size: 13.5px; line-height: 1.5; color: var(--text-primary); }
.nap-mzmsg-sug li { margin-top: 4px; }
.nap-mzmsg-sug li::marker { color: var(--c); }
.nap-mzmsg-facts { display: grid; gap: 5px; margin: 0; padding: 0; list-style: none; }
.nap-mzmsg-facts li { position: relative; padding-left: 12px; font-size: 12px; line-height: 1.45; color: var(--text-secondary); }
.nap-mzmsg-facts li::before {
  content: ''; position: absolute; left: 0; top: 6px; width: 5px; height: 5px; border-radius: 50%;
  background: var(--dv-lav); box-shadow: 0 0 5px var(--dv-lav);
}
/* advice actions: flat-lit pills; the applied line carries the 3D tick */
.nap-mzmsg-actions { display: flex; flex-wrap: wrap; align-items: center; gap: 6px; margin-top: 12px; }
.nap-mzmsg .nap-mzmsg-actions .chip {
  min-height: 36px; padding: 8px 14px; border: 0; border-radius: 999px;
  font-size: 12.5px; font-weight: 600; color: color-mix(in srgb, var(--c) 78%, var(--text-primary));
  background: color-mix(in srgb, var(--c) 16%, transparent);
  box-shadow: inset 0 0 0 1px color-mix(in srgb, var(--c) 45%, transparent), 0 0 12px -4px color-mix(in srgb, var(--c) 55%, transparent);
  cursor: pointer;
}
.nap-mzmsg .nap-mzmsg-actions .chip:disabled { opacity: 0.5; cursor: default; }
.nap-mzmsg .nap-mzmsg-actionerr { color: #FFB39C; }
.nap-mzmsg .nap-mzmsg-applied { margin-top: 12px; gap: 8px; font-size: 13px; color: var(--text-primary); }
/* feedback row: flat pills on a hairline; the voted one lit in the card hue */
.nap-mzmsg-fb { margin-top: 12px; padding-top: 10px; border-top: 1px solid var(--divider); }
.nap-mzmsg-fb .nap-mzmsg-meta.is-eb { margin-top: 0; }
.nap-mzmsg-fb .chip {
  border: 0; border-radius: 999px; font-size: 12px; font-weight: 600; color: var(--text-secondary);
  background: rgba(245, 239, 230, 0.05); box-shadow: inset 0 0 0 1px var(--divider); cursor: pointer;
}
.nap-mzmsg-fb .chip.brand, .nap-mzmsg-fb .chip[aria-pressed='true'] {
  color: #191614; background: var(--c); box-shadow: 0 0 12px color-mix(in srgb, var(--c) 50%, transparent);
}

/* older messages (rank 3): flat one-line cells, not glass */
.nap-mzrow.uv-flat {
  width: 100%; box-sizing: border-box; display: flex; align-items: center; gap: 10px;
  min-height: 44px; margin-bottom: 8px; padding: 11px 12px; border: 0; border-radius: 14px;
  text-align: left; font-family: inherit; color: var(--text-primary); cursor: pointer;
}
.nap-mzrow .t-ico { filter: drop-shadow(0 3px 4px rgba(0, 0, 0, 0.5)); }
.nap-mzrow .grow { flex: 1; min-width: 0; }
.nap-mzrow .hd { display: flex; align-items: baseline; gap: 6px; min-width: 0; }
.nap-mzrow .t { min-width: 0; font-size: 10.5px; color: var(--text-muted); white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
.nap-mzrow .mt { flex: none; font-size: 10.5px; color: var(--text-muted); white-space: nowrap; }
.nap-mzrow .pv { display: block; font-size: 13px; color: var(--text-secondary); white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
.nap-mzrow .chev { flex: none; color: var(--text-muted); }
/* "Beszélgess Mezóval ›" — a lavender glass button with the Mezo Boop */
.nap-mz-cta.glass {
  display: flex; align-items: center; justify-content: center; gap: 10px;
  width: 100%; min-height: 48px; margin-top: 14px; padding: 12px 16px; border: 0; border-radius: 20px;
  font-family: inherit; font-size: 14.5px; font-weight: 600; color: var(--text-primary); cursor: pointer;
}
.nap-mz-cta .boop { flex: none; filter: drop-shadow(0 0 10px color-mix(in srgb, var(--c) 45%, transparent)); }

/* Életjelek: the strip is ONE rose glass button of six flat mini cells with mini rings */
.nap-ejstrip.glass {
  display: grid; grid-template-columns: repeat(6, minmax(0, 1fr)); gap: 5px;
  width: 100%; box-sizing: border-box; margin-bottom: 12px; padding: 12px 10px; border: 0; border-radius: 22px;
  font-family: inherit; color: var(--text-primary); cursor: pointer;
}
.nap-ejcell {
  display: flex; flex-direction: column; align-items: center; gap: 4px; min-width: 0;
  padding: 6px 0; border-radius: 12px; background: rgba(245, 239, 230, 0.03);
}
.nap-ejcell .eb {
  max-width: 100%; overflow: hidden; text-overflow: ellipsis; white-space: nowrap;
  font-size: 8.5px; font-weight: 600; letter-spacing: 0.6px; text-transform: uppercase; color: var(--text-muted);
}
.nap-ejring { display: block; width: 32px; height: 32px; }
.nap-ejcell .pct { font-size: 10.5px; font-weight: 600; font-variant-numeric: tabular-nums; color: color-mix(in srgb, var(--c) 70%, var(--text-primary)); }
.nap-ejcell.warn { box-shadow: inset 0 0 0 1px rgba(255, 126, 92, 0.45); }
/* the ok / warn lines: flat, with a 3D icon */
.nap-ejok {
  display: flex; align-items: center; justify-content: center; gap: 8px; margin: 12px 0 10px;
  font-size: 12.5px; font-weight: 500; line-height: 1.4; color: var(--text-secondary); text-align: left;
}
.nap-ejok .t-ico { filter: drop-shadow(0 3px 4px rgba(0, 0, 0, 0.5)); }
.nap-ejok.warn { color: #FFB39C; }

/* Észrevételek: the observation card is glass (fresh/return lavender, watching sky, confirmed sage) */
.nap-obs.glass { margin-bottom: 12px; padding: 16px 16px 14px; border-radius: 22px; }
.nap-obs-top { display: flex; align-items: flex-start; gap: 12px; }
.nap-obs-top > div { flex: 1; min-width: 0; }
.nap-obs-disc.uv-well { width: 46px; height: 46px; }
.nap-obs .eb {
  font: 600 9.5px/1.2 var(--ff-body); letter-spacing: 1.3px; text-transform: uppercase;
  color: color-mix(in srgb, var(--c) 85%, var(--text-primary));
}
.nap-obs .ttl { margin-top: 4px; font-size: 17px; font-weight: 600; letter-spacing: -0.35px; line-height: 1.28; color: var(--text-primary); }
.nap-obs-pill {
  margin-left: auto; margin-top: 2px; flex: none; padding: 4px 10px; border-radius: 999px;
  font-size: 9px; font-weight: 700; letter-spacing: 1px; color: color-mix(in srgb, var(--c) 85%, var(--text-primary));
  background: color-mix(in srgb, var(--c) 14%, transparent); box-shadow: inset 0 0 0 1px color-mix(in srgb, var(--c) 40%, transparent);
}
/* Mezo's sentence: upright Geist, paragraph measure (bible U3/23 — no italic serif on prose) */
.nap-obs-say { margin: 12px 0 0; font-size: 15px; line-height: 1.55; letter-spacing: -0.1px; color: var(--text-primary); }
.nap-obs-say b, .nap-obs-say strong { font-weight: 600; color: color-mix(in srgb, var(--c) 55%, var(--text-primary)); }
.nap-obs-ask { margin: 8px 0 0; font-size: 13.5px; line-height: 1.5; color: var(--text-secondary); }
.nap-obs-ask b, .nap-obs-ask strong { color: var(--text-primary); font-weight: 600; }
/* the question sits right above its reply pills, split from the evidence by a hairline */
.nap-obs-q { margin-top: 16px; padding-top: 14px; border-top: 1px solid var(--divider); }
.nap-obs-qeb {
  display: flex; align-items: center; gap: 6px; font: 600 9.5px/1.2 var(--ff-body); letter-spacing: 1.3px;
  text-transform: uppercase; color: color-mix(in srgb, var(--c) 85%, var(--text-primary));
}
.nap-obs-q .nap-obs-ask { margin-top: 6px; font-size: 15px; font-weight: 500; line-height: 1.45; color: var(--text-primary); }
/* evidence ("Miből látom"): a hairline eyebrow with its toggle, then FLAT rows (never glass in glass) */
.nap-obs-evh {
  display: flex; align-items: center; gap: 8px; margin-top: 16px;
  font: 600 9.5px/1.2 var(--ff-body); letter-spacing: 1.3px; text-transform: uppercase; color: var(--text-muted);
}
.nap-obs-evh::after { content: ''; flex: 1; height: 1px; background: var(--divider); }
.nap-obs-evh button {
  order: 2; min-height: 32px; padding: 0; border: 0; background: none; cursor: pointer;
  font: 600 11.5px var(--ff-body); letter-spacing: 0; text-transform: none; color: color-mix(in srgb, var(--c) 80%, var(--text-primary));
}
.nap-obs-evid { display: grid; gap: 8px; margin-top: 8px; }
.nap-ev-row { padding: 11px 12px 12px; border-radius: 16px; background: rgba(245, 239, 230, 0.04); box-shadow: inset 0 0 0 1px var(--divider); }
.nap-ev-h { display: flex; align-items: center; gap: 9px; }
.nap-ev-h .t-ico { flex: none; filter: drop-shadow(0 3px 4px rgba(0, 0, 0, 0.5)); }
.nap-ev-src { display: flex; flex-direction: column; min-width: 0; }
.nap-ev-src strong, .nap-ev-h time { white-space: nowrap; }
.nap-ev-src strong { font-size: 13.5px; font-weight: 600; line-height: 1.2; color: var(--text-primary); }
.nap-ev-src small { margin-top: 1px; font-size: 10.5px; color: var(--text-muted); }
.nap-ev-h time { margin-left: auto; font-size: 11.5px; font-weight: 500; color: var(--text-secondary); font-variant-numeric: tabular-nums; text-align: right; }
.nap-ev-vals { display: flex; flex-wrap: wrap; gap: 5px; margin-top: 9px; }
.nap-ev-vals span {
  display: inline-flex; align-items: baseline; gap: 4px; min-width: 0; padding: 5px 10px; border-radius: 999px;
  font-size: 12px; color: var(--text-secondary); background: rgba(245, 239, 230, 0.05); box-shadow: inset 0 0 0 1px var(--divider);
}
.nap-ev-vals b { font-size: 13px; font-weight: 600; color: var(--text-primary); font-variant-numeric: tabular-nums; }
.nap-ev-vals i { font-style: normal; font-size: 10.5px; font-weight: 600; color: var(--text-muted); }
.nap-ev-vals span.hot { background: color-mix(in srgb, var(--c) 14%, transparent); box-shadow: inset 0 0 0 1px color-mix(in srgb, var(--c) 45%, transparent); }
.nap-ev-vals span.hot b { color: color-mix(in srgb, var(--c) 70%, var(--text-primary)); }
.nap-ev-cells { display: grid; grid-template-columns: repeat(4, 1fr); gap: 5px; margin-top: 9px; }
.nap-ev-cells span {
  padding: 6px 0 5px; border-radius: 11px; text-align: center;
  background: color-mix(in srgb, var(--k) 9%, rgba(245, 239, 230, 0.03)); box-shadow: inset 0 0 0 1px color-mix(in srgb, var(--k) 26%, transparent);
}
.nap-ev-cells b { display: block; font-size: 16px; font-weight: 600; font-variant-numeric: tabular-nums; color: color-mix(in srgb, var(--k) 80%, var(--text-primary)); }
.nap-ev-cells small { display: block; margin-top: 1px; font-size: 9.5px; color: var(--text-muted); }
.nap-ev-quote {
  margin: 9px 0 0; padding: 1px 0 1px 10px; border-left: 2px solid color-mix(in srgb, var(--c) 55%, transparent);
  font-size: 13.5px; line-height: 1.5; color: var(--text-primary); overflow-wrap: anywhere;
}
.nap-ev-quote.clip { display: -webkit-box; -webkit-line-clamp: 3; -webkit-box-orient: vertical; overflow: hidden; }
.nap-ev-tags { display: flex; flex-wrap: wrap; gap: 6px; }
.nap-ev-tags span {
  padding: 5px 10px; border-radius: 999px; font-size: 11px; font-weight: 600; color: var(--text-secondary);
  background: rgba(245, 239, 230, 0.05); box-shadow: inset 0 0 0 1px var(--divider);
}
/* two+ check-ins in a row: ONE shared change graphic — a 1–10 track per dimension,
   hollow ring = the earlier entry, lit dot = the later one, the segment glows in the dimension hue */
.nap-ev-shift { padding: 12px 12px 8px; border-radius: 16px; background: rgba(245, 239, 230, 0.04); box-shadow: inset 0 0 0 1px var(--divider); }
.nap-sh-h { display: flex; align-items: center; gap: 8px; font: 600 9.5px/1.2 var(--ff-body); letter-spacing: 1.3px; text-transform: uppercase; color: var(--text-muted); }
.nap-sh-t {
  margin-left: auto; display: inline-flex; align-items: center; gap: 5px; letter-spacing: 0; text-transform: none;
  font-size: 11.5px; font-weight: 500; color: var(--text-secondary); font-variant-numeric: tabular-nums;
}
.nap-sh-t b { margin: 0 2px; font-weight: 500; color: var(--text-muted); }
.nap-sh-t i { width: 8px; height: 8px; border-radius: 50%; }
.nap-sh-t i.o { box-shadow: inset 0 0 0 1.5px var(--text-secondary); }
.nap-sh-t i.f { background: var(--text-primary); }
.nap-sh-row, .nap-sh-sc { display: grid; grid-template-columns: 62px 1fr 50px 30px; align-items: center; gap: 8px; }
.nap-sh-row { padding-top: 9px; }
.nap-sh-l { font-size: 12px; font-weight: 600; color: color-mix(in srgb, var(--k) 70%, var(--text-primary)); }
.nap-sh-tr { position: relative; height: 10px; border-radius: 5px; background: rgba(245, 239, 230, 0.06); }
.nap-sh-tr .seg {
  position: absolute; top: 3px; height: 4px; border-radius: 2px;
  background: linear-gradient(90deg, color-mix(in srgb, var(--k) 35%, transparent), var(--k));
  box-shadow: 0 0 8px color-mix(in srgb, var(--k) 50%, transparent);
}
.nap-sh-tr .seg.dn { background: linear-gradient(90deg, var(--k), color-mix(in srgb, var(--k) 35%, transparent)); }
.nap-sh-tr i { position: absolute; top: 50%; width: 12px; height: 12px; margin: -6px 0 0 -6px; border-radius: 50%; }
.nap-sh-tr i.o { background: var(--surface-card); box-shadow: inset 0 0 0 2px color-mix(in srgb, var(--k) 55%, transparent); }
.nap-sh-tr i.f { background: var(--k); box-shadow: 0 0 10px color-mix(in srgb, var(--k) 70%, transparent), inset 0 1px 0 rgba(255, 255, 255, 0.35); }
.nap-sh-n { font-size: 12px; color: var(--text-secondary); font-variant-numeric: tabular-nums; text-align: right; white-space: nowrap; }
.nap-sh-n b { margin: 0 3px; font-weight: 400; color: var(--text-muted); }
.nap-sh-n strong { font-size: 14px; font-weight: 600; color: var(--text-primary); }
.nap-sh-d { justify-self: end; font-size: 11px; font-weight: 700; font-variant-numeric: tabular-nums; color: color-mix(in srgb, var(--k) 80%, var(--text-primary)); }
.nap-sh-d.z { color: var(--text-muted); }
.nap-sh-sc { margin-top: 3px; font-size: 9.5px; color: var(--text-muted); }
.nap-sh-sc .r { grid-column: 2; display: flex; justify-content: space-between; }
.nap-sh-sc i { font-style: normal; }
@media (max-width: 360px) {
  .nap-sh-row, .nap-sh-sc { grid-template-columns: 54px 1fr 46px 26px; gap: 6px; }
  /* the day label drops under the title instead of squeezing it („Check-/in”) */
  .nap-ev-h { flex-wrap: wrap; row-gap: 2px; }
  .nap-ev-h time { flex-basis: 100%; margin-left: 35px; text-align: left; font-size: 11px; }
}
/* reply pills: flat; the "yes" one lit in the card hue */
.nap-obs-chips { display: flex; flex-wrap: wrap; gap: 6px; margin-top: 12px; }
.nap-obs-chips .chip {
  flex: 1 1 auto; justify-content: center; min-height: 44px; padding: 8px 12px; border: 0; border-radius: 999px;
  font-family: inherit; font-size: 12.5px; font-weight: 600; white-space: normal; cursor: pointer;
  color: var(--text-secondary); background: rgba(245, 239, 230, 0.05); box-shadow: inset 0 0 0 1px var(--divider);
}
.nap-obs-chips .chip.yes { color: #191614; font-weight: 700; background: var(--c); box-shadow: 0 0 14px color-mix(in srgb, var(--c) 55%, transparent); }
.nap-obs-chips .chip.talk { color: color-mix(in srgb, var(--c) 80%, var(--text-primary)); }
.nap-obs-chips .chip:disabled { opacity: 0.5; cursor: default; }
.nap-obs-ack {
  display: flex; align-items: center; gap: 10px; margin-top: 16px; padding-top: 14px; border-top: 1px solid var(--divider);
  font-size: 13.5px; line-height: 1.45; color: var(--text-secondary);
}
.nap-obs-err { margin-top: 10px; font-size: 12px; font-weight: 600; color: #FFB39C; }
/* the watching card's tally: 3D tick (hit) / skip (miss) marks, a flat dot for a day not yet in */
.nap-obs-tally { display: flex; flex-wrap: wrap; gap: 5px; margin-top: 10px; }
.nap-obs-tally i {
  width: 22px; height: 22px; border-radius: 7px; display: grid; place-items: center; font-style: normal;
  background: rgba(245, 239, 230, 0.05); box-shadow: inset 0 0 0 1px var(--divider);
}
.nap-obs-tally i.hit { background: color-mix(in srgb, var(--dv-sage) 16%, transparent); box-shadow: inset 0 0 0 1px color-mix(in srgb, var(--dv-sage) 45%, transparent); }
.nap-obs-tally i.miss { background: color-mix(in srgb, var(--dv-coral) 14%, transparent); box-shadow: inset 0 0 0 1px color-mix(in srgb, var(--dv-coral) 40%, transparent); }
.nap-obs-tally i.none::before { content: ''; width: 5px; height: 5px; border-radius: 50%; background: rgba(245, 239, 230, 0.22); }
.nap-obs-tally .t-ico { filter: drop-shadow(0 2px 3px rgba(0, 0, 0, 0.5)); }
.nap-obs-progcopy { display: flex; align-items: center; margin-top: 12px; font-size: 11px; font-weight: 600; color: var(--text-muted); }
.nap-obs-progcopy strong { margin-left: auto; font-variant-numeric: tabular-nums; color: color-mix(in srgb, var(--c) 80%, var(--text-primary)); }
/* the §5 bar recipe */
.nap-obs-prog { height: 6px; margin-top: 6px; border-radius: 3px; background: rgba(245, 239, 230, 0.07); }
.nap-obs-prog i {
  display: block; width: var(--w); height: 100%; border-radius: 3px;
  background: linear-gradient(90deg, color-mix(in srgb, var(--c) 55%, #fff), var(--c));
  box-shadow: 0 0 8px color-mix(in srgb, var(--c) 60%, transparent);
}
.nap-obs-more {
  display: block; min-height: 44px; margin-top: 6px; line-height: 44px; text-align: right;
  font-size: 12px; font-weight: 600; color: color-mix(in srgb, var(--c) 80%, var(--text-primary)); text-decoration: none;
}
/* states: error + empty/off are dashed (rank 4), the budget footer is a flat line with the moon */
.nap-mzpage .nap-obs-ghost > .card {
  --c: var(--dv-lav); border: 1.5px dashed color-mix(in srgb, var(--c) 45%, transparent); border-radius: 20px;
  background: rgba(245, 239, 230, 0.025); box-shadow: none;
}
.nap-obs-empty.uv-empty {
  --c: var(--dv-lav); margin: 4px 0 10px; padding: 14px; border-radius: 20px; text-align: center;
  font-size: 13px; line-height: 1.5; color: var(--text-secondary);
}
.nap-obs-quiet { display: flex; align-items: center; gap: 8px; margin-top: 12px; font-size: 12.5px; line-height: 1.4; color: var(--text-secondary); }
.nap-obs-quiet .t-ico { flex: none; filter: drop-shadow(0 3px 4px rgba(0, 0, 0, 0.5)); }

/* the header notification panel's CONTENT (§7.1; the panel glass itself is the chrome block's):
   3D chip icons at 17px with no halo, 3D row icons at 28px with a plain drop, no tint tile */
.app-head .nap-ntfpanel.glass .nap-ntfico { width: 30px; height: 30px; border-radius: 0; background: none; box-shadow: none; }
.nap-ntfpanel.glass .nap-ntfico .t-ico { filter: drop-shadow(0 3px 4px rgba(0, 0, 0, 0.5)); }
.nap-ntfpanel.glass .nap-ntftabs button .t-ico { filter: none; }
/* ── /uveg nap uzenetek ── */

/* ── uveg nap napzaras (mezo-me75u.3) ── /ritual: the six acts ── */
/* Reference: docs/design_2.0/prototypes/uveg-nap.html#napzaras/1…6 (owner OK 2026-09-23).
   Chrome-less full screen on the warm-graphite ground + the aurora; the six acts wear the uveg
   kit (.glass, .uv-flat, .uv-bar, .uv-ring-*, .t-ico). One-shot reveals run outside a media query
   and settle to their final state under reduce; every loop (twinkle, float, breathing glow) is
   opt-in under no-preference (bible §6; features/ritual/reducedMotionGuard.test.ts). */
.rz-screen { position: absolute; inset: 0; z-index: var(--z-bottomnav); isolation: isolate;
  display: flex; flex-direction: column; overflow-y: auto;
  background: var(--rz-sky-1); color: var(--text-primary); transition: background .9s ease; }
.rz-screen[data-act="1"] { background: var(--rz-sky-1); }
.rz-screen[data-act="2"] { background: var(--rz-sky-2); }
.rz-screen[data-act="3"] { background: var(--rz-sky-3); }
.rz-screen[data-act="4"] { background: var(--rz-sky-4); }
.rz-screen[data-act="5"] { background: var(--rz-sky-5); }
.rz-screen[data-act="6"] { background: var(--rz-sky-6); }
.rz-screen > .rz-aurora { z-index: 0; }
/* stars: index-derived positions (RitualPage), twinkle only when motion is welcome */
.rz-stars { position: absolute; inset: 0; z-index: 0; overflow: hidden; pointer-events: none; }
.rz-stars i { position: absolute; width: 2px; height: 2px; border-radius: 50%; opacity: .5;
  background: var(--text-primary); box-shadow: 0 0 6px rgba(255, 255, 255, .9); }
@keyframes rz-twinkle { 0%, 100% { opacity: .15; } 50% { opacity: .7; } }
.rz-top, .rz-act { position: relative; z-index: 1; }
.rz-top { display: flex; align-items: center; justify-content: space-between; gap: 12px;
  padding: calc(16px + env(safe-area-inset-top)) 20px 0; margin-bottom: 22px; }
.rz-dots { display: flex; align-items: center; gap: 6px; }
.rz-dot { width: 8px; height: 8px; border-radius: 50%; background: rgba(245, 239, 230, .12);
  transition: width .3s var(--uv-ease), background .3s ease; }
.rz-dot.on { background: color-mix(in srgb, var(--dv-amber) 55%, transparent); }
.rz-dot.cur { width: 22px; border-radius: 4px; background: var(--dv-amber); box-shadow: 0 0 10px var(--dv-amber); }
.rz-exit { min-height: 34px; padding: 7px 13px; border: 0; border-radius: 999px; cursor: pointer;
  font: 600 12.5px/1 var(--ff-body); color: var(--text-muted);
  background: rgba(245, 239, 230, .05); box-shadow: inset 0 0 0 1px var(--divider); }
.rz-act { flex: 1; display: flex; flex-direction: column; padding: 0 20px calc(32px + env(safe-area-inset-bottom)); text-align: center; }
.rz-story-eyebrow { display: block; font: 600 10px/1.2 var(--ff-body); letter-spacing: 1.4px; text-transform: uppercase;
  color: color-mix(in srgb, var(--dv-amber) 80%, var(--text-primary)); }
/* the lit primary (prototype .primary): amber through act 5, lavender for the release */
.rz-cta, .rz-handoff-cta { --c: var(--dv-amber);
  display: flex; align-items: center; justify-content: center; gap: 8px; width: 100%; min-height: 48px;
  margin: 26px 0 0; padding: 14px 16px; border: 0; border-radius: 18px; cursor: pointer;
  font: 700 15px/1.2 var(--ff-body); color: #191614;
  background: linear-gradient(135deg, color-mix(in srgb, var(--c) 70%, #fff), var(--c));
  box-shadow: 0 0 18px -2px color-mix(in srgb, var(--c) 60%, transparent), inset 0 1px 0 rgba(255, 255, 255, .45); }
.rz-handoff-cta { --c: var(--dv-lav); }
.rz-skip { display: block; margin: 12px auto 0; padding: 10px 16px; border: 0; background: none; cursor: pointer;
  font: 600 13px/1.2 var(--ff-body); color: var(--text-muted); }

/* act 1 — the floating 3D moon over a lavender/amber halo, the CTA at the bottom */
.rz-moon { position: relative; width: 170px; height: 170px; margin: auto auto 18px; display: grid; place-items: center; }
.rz-moon::before { content: ''; position: absolute; inset: -30px; border-radius: 50%; pointer-events: none;
  background: radial-gradient(circle, color-mix(in srgb, var(--dv-lav) 34%, transparent),
    color-mix(in srgb, var(--dv-amber) 12%, transparent) 45%, transparent 70%); }
.rz-moon .t-ico { position: relative;
  filter: drop-shadow(0 14px 16px rgba(0, 0, 0, .55)) drop-shadow(0 0 26px color-mix(in srgb, var(--dv-lav) 55%, transparent)); }
.rz-line1, .rz-line2, .rz-end { font-family: var(--ff-display); font-size: 30px; line-height: 1.15; letter-spacing: -1.1px; }
.rz-line1 { font-weight: 600; margin-top: 6px; }
.rz-line2 { font-weight: 300; color: var(--text-secondary); }
.rz-arrival .rz-cta { margin-top: auto; }
.rz-arrival .rz-line2 { margin-bottom: 30px; }

/* act 2 — the glowing amber → lavender arc, check-in dots, flat recap rows */
.rz-arc { display: block; width: 100%; height: auto; margin: 14px 0 6px; overflow: visible; }
.rz-arc-track { fill: none; stroke: rgba(245, 239, 230, .1); stroke-width: 3; }
.rz-arc-path { fill: none; stroke-width: 3; stroke-linecap: round;
  filter: drop-shadow(0 0 6px color-mix(in srgb, var(--dv-amber) 60%, transparent));
  stroke-dasharray: 400; stroke-dashoffset: 400; animation: np-draw 1.4s var(--np-ease-ios) .2s forwards; }
.rz-arc-dot { transform-box: fill-box; transform-origin: center; opacity: 0;
  animation: np-pop .5s var(--np-ease-spring) forwards; }
.rz-arc-checkin-done { fill: var(--dv-rose); filter: drop-shadow(0 0 6px var(--dv-rose)); }
.rz-arc-checkin-now { fill: #191614; stroke: var(--dv-amber); stroke-width: 2.5;
  filter: drop-shadow(0 0 6px color-mix(in srgb, var(--dv-amber) 70%, transparent)); }
.rz-arc-checkin-pending { fill: none; stroke: rgba(245, 239, 230, .35); stroke-width: 1.5; stroke-dasharray: 3 3; }
.rz-arc-workout { fill: #191614; stroke: var(--dv-coral); stroke-width: 2.5; }
.rz-arc-sleep { fill: #191614; stroke: var(--dv-lav); stroke-width: 2.5; }
.rz-thin { margin: 10px 6px 0; font: italic 500 14px/1.5 var(--ff-serif); color: var(--text-secondary); }
.rz-events { display: grid; gap: 8px; margin-top: 10px; text-align: left; }
.rz-ev { display: flex; align-items: center; gap: 12px; padding: 11px 12px; border-radius: 16px; }
.rz-ev-icon { display: grid; place-items: center; flex: none; }
.rz-ev-label { flex: 1; min-width: 0; font: 600 14px/1.3 var(--ff-body); overflow-wrap: anywhere; }
.rz-ev-meta { display: flex; align-items: center; gap: 4px; flex: none; font: 500 12px/1.2 var(--ff-body); color: var(--text-secondary); }

/* act 3 — prose in a lavender glass box, gratitude in an amber one; inputs + chips flat */
.rz-reflect-title { margin-top: 6px; font: 600 26px/1.18 var(--ff-display); letter-spacing: -1px; }
.rz-reflect-box.glass, .rz-reflect-gratitude.glass { margin-top: 16px; padding: 14px; text-align: left; }
.rz-reflect-box.glass { --c: var(--dv-lav); }
.rz-reflect-gratitude.glass { --c: var(--dv-amber); display: flex; flex-direction: column; gap: 8px; }
.rz-reflect-input { display: block; width: 100%; min-height: 120px; resize: none; padding: 11px 13px;
  border: 0; border-radius: 13px; background: rgba(245, 239, 230, .05); box-shadow: inset 0 0 0 1px var(--divider);
  color: var(--text-primary); font: 400 16px/1.45 var(--ff-body); }
.rz-reflect-input::placeholder, .rz-reflect-gratitude textarea::placeholder { color: var(--text-muted); }
.rz-screen .rz-reflect-mic.chip { margin-top: 8px; padding: 6px 10px; border: 0; border-radius: 999px;
  color: var(--text-secondary); background: rgba(245, 239, 230, .05); box-shadow: inset 0 0 0 1px var(--divider); }
.rz-screen .rz-reflect-mic.chip[aria-pressed='true'] { color: #191614; background: var(--dv-lav);
  box-shadow: 0 0 12px color-mix(in srgb, var(--dv-lav) 50%, transparent); }
.rz-reflect-hint, .rz-reflect-gratitude .text-tertiary { margin: 6px 2px 0; font: 400 11px/1.4 var(--ff-body); color: var(--text-muted); }
/* the shared GratitudeRows, restyled only under the ritual root */
.rz-reflect-gratitude .card { border: 0; border-radius: 13px; background: rgba(245, 239, 230, .05); box-shadow: inset 0 0 0 1px var(--divider); }
.rz-reflect-gratitude .card textarea { border: 0; background: transparent; color: var(--text-primary); outline: none; }
.rz-reflect-gratitude .chip { border: 0; color: var(--text-secondary);
  background: rgba(245, 239, 230, .05); box-shadow: inset 0 0 0 1px var(--divider); }
.rz-reflect-gratitude .chip[aria-pressed='true'] { color: #191614; background: var(--dv-amber);
  box-shadow: 0 0 12px color-mix(in srgb, var(--dv-amber) 50%, transparent); }
.rz-reflect-gratitude .cta-ghost { align-self: flex-start; border: 0; background: none; color: var(--dv-amber); }
.rz-gratitude-saved { list-style: none; margin: 0; padding: 0; display: grid; gap: 6px; }
.rz-gratitude-saved li { padding: 9px 11px; border-radius: 12px; font: 400 13px/1.4 var(--ff-body); color: var(--text-secondary);
  background: rgba(245, 239, 230, .05); box-shadow: inset 0 0 0 1px var(--divider); }

/* act 4 — each loop a glass row in its own hue; lit/flat pill actions; closed loops dimmed */
.rz-loops-sub { margin-top: 8px; font: 400 15px/1.45 var(--ff-body); color: var(--text-secondary); }
.rz-loop.glass { --c: var(--dv-amber); display: flex; align-items: center; flex-wrap: wrap; gap: 12px;
  margin-top: 10px; padding: 12px 14px; border-radius: 20px; text-align: left; font: 600 14.5px/1.35 var(--ff-body); }
.rz-loop.glass[data-hue="rose"] { --c: var(--dv-rose); }
.rz-loop.glass[data-hue="sage"] { --c: var(--dv-sage); }
.rz-loop-text { flex: 1; min-width: 0; }
.rz-loop-act { flex: none; min-height: 36px; padding: 8px 14px; border: 0; border-radius: 999px; cursor: pointer; white-space: nowrap;
  font: 700 12.5px/1 var(--ff-body); color: #191614; background: var(--c);
  box-shadow: 0 0 14px color-mix(in srgb, var(--c) 55%, transparent); }
.rz-loop.glass[data-hue="sage"] .rz-loop-act { font-weight: 600; color: var(--text-secondary);
  background: rgba(245, 239, 230, .05); box-shadow: inset 0 0 0 1px var(--divider); }
.rz-loop-chips { display: flex; gap: 6px; width: 100%; padding-left: 50px; }
.rz-loop-chip { min-height: 34px; padding: 7px 13px; border: 0; border-radius: 999px; cursor: pointer;
  font: 600 12.5px/1 var(--ff-body); color: var(--text-secondary);
  background: rgba(245, 239, 230, .05); box-shadow: inset 0 0 0 1px var(--divider); }
/* the first open loop glows a little louder (the breathing is opt-in, below) */
.rz-loop.glass.glow { box-shadow: 0 16px 30px -16px rgba(0, 0, 0, .75), 0 0 28px -2px color-mix(in srgb, var(--c) 50%, transparent),
  inset 0 1px 0 rgba(255, 244, 230, .10), inset 0 -14px 26px -18px color-mix(in srgb, var(--c) 55%, transparent); }
@keyframes rz-loopbreath {
  0%, 100% { box-shadow: 0 16px 30px -16px rgba(0, 0, 0, .75), 0 0 22px -6px color-mix(in srgb, var(--c) 40%, transparent), inset 0 1px 0 rgba(255, 244, 230, .10); }
  50% { box-shadow: 0 16px 30px -16px rgba(0, 0, 0, .75), 0 0 30px 0 color-mix(in srgb, var(--c) 58%, transparent), inset 0 1px 0 rgba(255, 244, 230, .10); } }
/* closed: the content dims (never the row itself — np-anim owns its opacity), the hue glow goes */
.rz-loop.glass.rz-loop-done { box-shadow: 0 16px 30px -16px rgba(0, 0, 0, .75), inset 0 1px 0 rgba(255, 244, 230, .08); }
.rz-loop-done > * { opacity: .72; }
.rz-loop-beat { justify-content: center; font: italic 500 15px/1.5 var(--ff-serif); }
.rz-loop-beat .rz-loop-text { flex: 0 1 auto; }

/* act 5 — the harvest: frameless gold + lavender halo, gradient reward numeral, flat chips */
.rz-harvest { position: relative; overflow-x: clip; }
.rz-harvest-body { position: relative; z-index: 1; display: flex; flex-direction: column; margin-block: auto; }
.rz-harvest .rz-conf { z-index: 2; }
.rz-xp-wrap { position: relative; isolation: isolate; display: flex; flex-direction: column; align-items: center; padding-top: 10px; }
.rz-glow { position: absolute; left: 50%; top: 70px; z-index: -1; width: 380px; height: 320px; pointer-events: none;
  transform: translate(-50%, -50%); opacity: 0; animation: rz-glowin 1.4s ease-out .25s forwards;
  background: radial-gradient(ellipse, color-mix(in srgb, var(--dv-amber) 36%, transparent),
    color-mix(in srgb, var(--dv-lav) 14%, transparent) 42%, transparent 68%); }
@keyframes rz-glowin { to { opacity: 1; } }
.rz-harvest-spot .t-ico { filter: drop-shadow(0 12px 14px rgba(0, 0, 0, .5)) drop-shadow(0 0 22px color-mix(in srgb, var(--dv-amber) 50%, transparent)); }
.rz-xp-wrap .rz-story-eyebrow { margin-top: 6px; }
.rz-xp-num { display: block; margin-top: 4px; font: 300 84px/1.02 var(--ff-display); letter-spacing: -4.5px; font-variant-numeric: tabular-nums;
  background: linear-gradient(135deg, #FFE3B0 0%, var(--dv-amber) 45%, #C9BDF0 100%);
  -webkit-background-clip: text; background-clip: text; color: transparent;
  filter: drop-shadow(0 6px 18px color-mix(in srgb, var(--dv-amber) 35%, transparent)); }
@keyframes rz-xpglow {
  0%, 100% { filter: drop-shadow(0 6px 14px color-mix(in srgb, var(--dv-amber) 28%, transparent)); }
  50% { filter: drop-shadow(0 6px 28px color-mix(in srgb, var(--dv-amber) 60%, transparent)); } }
.rz-xp-unit { font: 500 13px/1.3 var(--ff-body); color: var(--text-secondary); }
.rz-src-row, .rz-coin-row { display: flex; flex-wrap: wrap; justify-content: center; gap: 6px; }
.rz-src-row { margin-top: 14px; }
.rz-coin-row { margin-top: 6px; }
.rz-chip, .rz-coin-chip { display: inline-flex; align-items: center; gap: 6px; min-width: 0; padding: 7px 12px; border-radius: 999px;
  font: 600 12px/1.2 var(--ff-body); color: var(--text-secondary); }
.rz-chip-xp, .rz-coin-chip { font-weight: 700; color: #FFD99A; font-variant-numeric: tabular-nums; }
.rz-pop { opacity: 0; animation: np-pop .5s var(--np-ease-spring) forwards; }
.rz-skill-row.glass { --c: var(--dv-amber); margin-top: 16px; padding: 12px 14px; text-align: left; }
.rz-skill-head { display: flex; align-items: center; justify-content: space-between; gap: 10px; font: 600 13.5px/1.3 var(--ff-body); }
.rz-skill-lv { color: color-mix(in srgb, var(--dv-amber) 78%, var(--text-primary)); }
.rz-skill-pct { color: #FFD99A; font-variant-numeric: tabular-nums; }
.rz-skill-bar.uv-bar { --c: var(--dv-amber); height: 6px; margin-top: 8px; }
.rz-skill-bar > b { animation: rz-bargrow 1s var(--uv-ease) .2s both; }
@keyframes rz-bargrow { from { width: 0; } }
.rz-streak { display: flex; align-items: center; gap: 12px; margin-top: 8px; padding: 11px 12px; border-radius: 16px;
  text-align: left; font: 600 14px/1.3 var(--ff-body); color: var(--text-primary); }
.rz-skill-row + .rz-streak, .rz-src-row + .rz-streak, .rz-coin-row + .rz-streak, .rz-xp-wrap + .rz-streak { margin-top: 14px; }
.rz-streak.dim { color: var(--text-muted); }
.rz-streak.dim .t-ico { opacity: .45; filter: grayscale(1); }
.rz-conf { position: absolute; inset: 0; pointer-events: none; }
.rz-conf i { position: absolute; top: -8px; width: 6px; height: 10px; border-radius: 2px; opacity: 0;
  animation: rz-fall 2.6s ease-in forwards; }
@keyframes rz-fall { 0% { opacity: 0; transform: translateY(0) rotate(0); } 8% { opacity: 1; }
  100% { opacity: 0; transform: translateY(520px) rotate(560deg); } }

/* act 6 — the drawn lavender ring round the moon, Mezo's note + the handoff in lavender glass */
.rz-release { overflow-x: clip; }
.rz-circle { position: relative; width: 180px; height: 180px; margin: 8px auto 14px; display: grid; place-items: center; }
.rz-circle-svg { position: absolute; inset: 0; width: 100%; height: 100%; transform: rotate(-90deg); }
.rz-circle-svg .uv-ring-track { stroke-width: 3.4; }
.rz-ring { fill: none; stroke: var(--dv-lav); stroke-width: 3.4; stroke-linecap: round;
  filter: drop-shadow(0 0 5px color-mix(in srgb, var(--dv-lav) 55%, transparent));
  stroke-dasharray: 100; stroke-dashoffset: 100; animation: np-draw 2s var(--np-ease-ios) .3s forwards; }
.rz-circle-moon { position: relative;
  filter: drop-shadow(0 10px 12px rgba(0, 0, 0, .5)) drop-shadow(0 0 20px color-mix(in srgb, var(--dv-lav) 50%, transparent)); }
.rz-end { font-weight: 600; }
.rz-end-soft { display: block; font-weight: 300; color: var(--text-secondary); }
.rz-note.glass, .rz-handoff.glass { --c: var(--dv-lav); text-align: left; }
.rz-note.glass { display: flex; flex-direction: column; gap: 6px; margin-top: 16px; padding: 14px; }
.rz-note-eyebrow, .rz-handoff-eyebrow { display: block; font: 600 10px/1.2 var(--ff-body); letter-spacing: 1.4px; text-transform: uppercase;
  color: color-mix(in srgb, var(--dv-lav) 80%, var(--text-primary)); }
.rz-note-quote { font-size: 16px; line-height: 1.5; color: var(--text-primary); }
.rz-handoff.glass { margin-top: 18px; padding: 12px 14px; }
.rz-handoff-eyebrow { margin-bottom: 4px; }
.rz-handoff-steps { display: flex; flex-direction: column; }
.rz-handoff-step { display: flex; align-items: center; gap: 12px; padding: 9px 0; border-top: 1px solid var(--divider); }
.rz-handoff-step:first-child { border-top: 0; }
.rz-handoff-label { flex: 1; min-width: 0; font: 500 14px/1.35 var(--ff-body); }
.rz-handoff-time { font: 600 15px/1 var(--ff-body); font-variant-numeric: tabular-nums; color: #C9BDF0; }

@media (max-width: 360px) {
  .rz-xp-num { font-size: 70px; }
  .rz-loop-chips { padding-left: 0; }
}
@media (prefers-reduced-motion: no-preference) {
  .rz-stars i { animation: rz-twinkle 4s ease-in-out infinite; animation-delay: var(--tw); }
  .rz-moon .t-ico, .rz-circle-moon { animation: uv-float 5s ease-in-out 1s infinite; }
  .rz-xp-num { animation: rz-xpglow 5s ease-in-out 1s infinite; }
  .rz-loop.glass.glow.np-anim { animation: np-rise .55s var(--np-ease-ios) forwards, rz-loopbreath 3s ease-in-out .6s infinite; }
}
@media (prefers-reduced-motion: reduce) {
  .rz-screen, .rz-dot { transition: none; }
  /* one-shot reveals settle at their final state, never stuck hidden */
  .rz-arc-path, .rz-arc-dot, .rz-ring, .rz-pop, .rz-glow, .rz-skill-bar > b { animation: none; }
  .rz-arc-path, .rz-ring { stroke-dashoffset: 0; }
  .rz-arc-dot { opacity: 1; transform: none; }
  .rz-pop, .rz-glow { opacity: 1; }
  .rz-conf { display: none; } /* decorative burst only — no motion, no point showing it static */
}
/* ── /uveg nap napzaras ── */

/* ── uveg edzes mai (mezo-me75u.4) ── /train/mai: day strip, today hero, session cards, energy + muscle-impact cards, alt pair, rows ── */
/* Reference: prototypes/uveg-edzes.html#mai (+ #mai/pihen, #mai/ures) — `mai()`, `dstrip()`,
   `thero()`; CSS `.dstrip .dday .thero .stpill .start .sess .energy .mus .musrow .dtrack .alt
   .lrow .dashadd .ghost .mchp`. Ranking (bible §3.4): the day strip is FLAT cells (the selected
   day lit coral: radial wash + inset ring); the gym poster is the FRAMELESS hero (coral halo,
   big 3D dumbbell, big title) whose ONE glass object is the CTA row `.trm-start`; the other
   sessions, the energy card (amber), the muscle-impact card (coral) and the „Vagy inkább”
   tiles are `.glass`; everything inside them is flat (fact pills, done bar, tracks — U1 rule
   5); the nav rows are flat; every one-off-workout entry and the no-meso state are dashed
   (`.uv-empty`, rule 6); the rest day is a lavender PageHero halo. Everything is scoped to the
   page root `.trm` (TrainTodayPage / TrainTodaySkeleton) — U2 rule 13. */

/* the section rail: the scroller pays --screen-gutter (12px); +4px lands on the prototype's 16px */
.trm .trm-sec { padding: 0 4px; margin-bottom: 12px; }

/* ── day strip: seven flat cells in one row ── */
.trm .trm-daystrip { display: grid; grid-template-columns: repeat(7, minmax(0, 1fr)); gap: 5px; padding: 2px 2px 8px; }
.trm .trm-day {
  display: flex; flex-direction: column; align-items: center; gap: 3px; min-width: 0;
  padding: 8px 0 7px; border: 0; border-radius: 15px; font: inherit; cursor: pointer;
  color: var(--text-primary); background: rgba(245, 239, 230, 0.04); box-shadow: inset 0 0 0 1px var(--divider);
}
.trm .trm-day-dl { font-size: 9.5px; font-weight: 600; letter-spacing: 1px; text-transform: uppercase; color: var(--text-muted); max-width: 100%; overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }
.trm .trm-day-dn { font-size: 16px; font-weight: 600; letter-spacing: -0.4px; line-height: 1.2; font-variant-numeric: tabular-nums; }
.trm .trm-day-dots { display: flex; gap: 3px; justify-content: center; min-height: 5px; }
.trm .trm-day-dots .dot { width: 5px; height: 5px; border-radius: 50%; box-shadow: 0 0 5px currentColor; }
.trm .trm-day-dots .dot-gym { background: var(--dv-coral); color: var(--dv-coral); }
.trm .trm-day-dots .dot-sport { background: var(--dv-rose); color: var(--dv-rose); }
.trm .trm-day-dots .dot-cross { background: var(--dv-amber); color: var(--dv-amber); }
.trm .trm-day-dots .dot-trx { background: var(--dv-lav); color: var(--dv-lav); }
.trm .trm-day-dots .dot-run { background: var(--dv-sky); color: var(--dv-sky); }
.trm .trm-day-ck { display: flex; align-items: center; justify-content: center; height: 14px; font-size: 9.5px; color: var(--text-muted); }
.trm .trm-day-ck .t-ico { width: 14px; height: 14px; filter: none; }
.trm .trm-day-ck .t-ico + .t-ico { margin-left: -4px; }
.trm .trm-day.rest { opacity: 0.62; }
.trm .trm-day.today .trm-day-dl { color: #FFB39C; }
.trm .trm-day.today:not(.sel) { box-shadow: inset 0 0 0 1px color-mix(in srgb, var(--dv-coral) 30%, transparent); }
.trm .trm-day.sel {
  opacity: 1;
  background: radial-gradient(90% 80% at 50% 20%, color-mix(in srgb, var(--dv-coral) 28%, transparent), rgba(245, 239, 230, 0.04));
  box-shadow: inset 0 0 0 1px color-mix(in srgb, var(--dv-coral) 45%, transparent), 0 0 16px -4px color-mix(in srgb, var(--dv-coral) 55%, transparent);
}
.trm .trm-day.sel .trm-day-dl { color: #FFB39C; }
.trm .trm-day:focus-visible { outline: 2px solid var(--dv-coral); outline-offset: 2px; }

/* ── the gym poster: the frameless coral halo hero ── */
.trm .trm-hero {
  position: relative; isolation: isolate; overflow-x: clip;  /* U2 rule 12: the halo is wider than 320px */
  display: flex; flex-direction: column; align-items: center; text-align: center;
  /* bleed to the screen edges (the scroller's 12px gutter + the 4px rail) so the clip lands on
     the screen edge, not as a hard vertical seam 16px inside it */
  margin-inline: -16px; padding: 14px 20px 6px;
}
.trm .trm-hero::before {
  content: ''; position: absolute; left: 50%; top: 44%; width: 360px; height: 320px; z-index: -1;
  transform: translate(-50%, -50%); pointer-events: none;
  background: radial-gradient(ellipse at 50% 42%,
    color-mix(in srgb, var(--dv-coral) 34%, transparent),
    color-mix(in srgb, var(--dv-amber) 12%, transparent) 42%, transparent 68%);
}
.trm .trm-hero.is-done::before {
  background: radial-gradient(ellipse at 50% 42%,
    color-mix(in srgb, var(--dv-sage) 30%, transparent),
    color-mix(in srgb, var(--dv-coral) 10%, transparent) 42%, transparent 68%);
}
.trm .trm-stpill {
  display: inline-flex; align-items: center; gap: 6px; align-self: center;
  padding: 5px 11px; border-radius: 999px; font-size: 10px; font-weight: 700; letter-spacing: 1.2px; text-transform: uppercase;
  color: #FFB39C; background: color-mix(in srgb, var(--dv-coral) 12%, transparent);
  box-shadow: inset 0 0 0 1px color-mix(in srgb, var(--dv-coral) 40%, transparent);
}
.trm .trm-stpill i { width: 6px; height: 6px; border-radius: 50%; background: var(--dv-coral); box-shadow: 0 0 8px var(--dv-coral); }
.trm .trm-stpill.is-done { color: #BFE0A8; background: color-mix(in srgb, var(--dv-sage) 12%, transparent); box-shadow: inset 0 0 0 1px color-mix(in srgb, var(--dv-sage) 45%, transparent); }
.trm .trm-stpill.is-done i { background: var(--dv-sage); box-shadow: 0 0 8px var(--dv-sage); }
.trm .trm-stpill.is-plan { color: var(--text-secondary); background: rgba(245, 239, 230, 0.05); box-shadow: inset 0 0 0 1px var(--divider); }
.trm .trm-stpill.is-plan i { background: var(--text-muted); box-shadow: none; }
.trm .trm-hero-art {
  width: 98px; height: 98px; margin: 4px auto 0;
  filter: drop-shadow(0 14px 14px rgba(0, 0, 0, 0.55)) drop-shadow(0 0 22px color-mix(in srgb, var(--dv-coral) 45%, transparent));
}
.trm .trm-hero-eb { display: block; margin-top: 10px; font-size: 9.5px; font-weight: 600; letter-spacing: 1.3px; text-transform: uppercase; color: #FFB39C; }
.trm .trm-hero-title {
  margin: 4px 0 0; max-width: 100%; overflow-wrap: anywhere;
  font-family: var(--ff-display); font-size: 38px; font-weight: 600; letter-spacing: -1.4px; line-height: 1.05; color: var(--text-primary);
}
.trm .trm-hero-sub { margin: 4px 0 0; font-size: 12.5px; color: var(--text-secondary); }
.trm .trm-hero-mchips { display: flex; flex-wrap: wrap; justify-content: center; gap: 6px; margin-top: 12px; }
.trm .trm-hero-pills { display: flex; flex-wrap: wrap; justify-content: center; gap: 6px; margin-top: 12px; max-width: 100%; }

/* a muscle chip in a lit round well (prototype `.mchp`) — the real anatomy, never an icon */
.trm .trm-mchp {
  --c: var(--dv-coral);
  width: 28px; height: 28px; border-radius: 50%; flex: 0 0 auto; display: grid; place-items: center; overflow: hidden;
  background: radial-gradient(circle at 35% 28%, #3A332D, color-mix(in srgb, var(--c) 16%, #1E1B18));
  box-shadow: inset 0 1px 0 rgba(255, 244, 230, 0.08), inset 0 -6px 12px -8px color-mix(in srgb, var(--c) 70%, transparent),
    0 0 12px -4px color-mix(in srgb, var(--c) 55%, transparent);
}
.trm .trm-mchp .muscle-chip { width: 100%; height: 100%; }

/* flat fact pill (rank 3) — the hero's and the session cards' facts */
.trm .trm-fact {
  display: inline-flex; align-items: center; min-width: 0; max-width: 100%;
  padding: 7px 12px; border-radius: 999px; font-size: 12px; font-weight: 600; color: var(--text-secondary);
  background: rgba(245, 239, 230, 0.05); box-shadow: inset 0 0 0 1px var(--divider);
  overflow: hidden; text-overflow: ellipsis; white-space: nowrap;
}

/* the hero's ONE glass object: the CTA row (U2 rule 11: restate geometry on `.x.glass`) */
.trm .trm-start.glass {
  display: flex; align-items: center; gap: 12px; width: 100%; max-width: 330px; margin: 16px auto 0;
  padding: 12px 14px 12px 12px; border: 0; border-radius: 22px; font: inherit; text-align: left; cursor: pointer;
  color: var(--text-primary);
}
.trm .trm-start .trm-start-art { width: 46px; height: 46px; }
.trm .trm-start-tx { flex: 1; min-width: 0; }
.trm .trm-start-tx strong { display: block; font-size: 19px; font-weight: 600; letter-spacing: -0.4px; }
.trm .trm-start-tx small { display: block; margin-top: 1px; font-size: 11.5px; color: var(--text-secondary); }
.trm .trm-start-go {
  flex: 0 0 auto; width: 42px; height: 42px; border-radius: 50%; display: grid; place-items: center;
  font-style: normal; font-size: 20px; color: #191614; background: var(--c);
  box-shadow: 0 0 16px color-mix(in srgb, var(--c) 60%, transparent);
}
.trm .trm-start:focus-visible { outline: 2px solid var(--c); outline-offset: 3px; }

/* ── the other sessions: one glass card each (TodaySessionCard + the rest-day resume card) ── */
.trm .trm-sess.glass { display: block; width: 100%; padding: 13px 14px; border-radius: 22px; }
.trm .trm-sess-top { display: flex; align-items: center; gap: 12px; }
.trm .trm-sess-well .t-ico { width: 34px; height: 34px; }
.trm .trm-sess-grow { flex: 1; min-width: 0; }
.trm .trm-sess-tagl { display: flex; align-items: center; gap: 8px; min-width: 0; }
.trm .trm-tag { font-size: 9.5px; font-weight: 600; letter-spacing: 1.2px; text-transform: uppercase; color: color-mix(in srgb, var(--c) 75%, var(--text-primary)); white-space: nowrap; }
.trm .trm-sess-time { font-style: normal; font-size: 9.5px; font-weight: 600; letter-spacing: 1px; color: var(--text-muted); white-space: nowrap; }
.trm .trm-sess-state {
  margin-left: auto; padding: 3px 8px; border-radius: 999px; font-size: 9.5px; font-weight: 600; letter-spacing: 1px;
  color: var(--text-secondary); background: rgba(245, 239, 230, 0.06); white-space: nowrap;
}
.trm .trm-sess-title { margin: 3px 0 0; font-size: 17px; font-weight: 600; letter-spacing: -0.4px; line-height: 1.25; color: var(--text-primary); overflow-wrap: anywhere; }
.trm .trm-sess .trm-stpill { padding: 3px 9px; font-size: 9.5px; }
.trm .trm-facts { display: flex; flex-wrap: wrap; gap: 6px; margin-top: 10px; }
.trm .trm-sess-cta { display: flex; justify-content: flex-end; margin-top: 10px; }
/* the lit pill CTA (a flat lit pill inside glass — never glass in glass) */
.trm .trm-pill {
  --c-pill: var(--c, var(--dv-coral));
  display: inline-flex; align-items: center; gap: 6px; max-width: 100%; min-height: 36px;
  padding: 8px 14px; border: 0; border-radius: 999px; font: inherit; font-size: 12.5px; font-weight: 700; cursor: pointer;
  color: #191614; background: var(--c-pill); box-shadow: 0 0 14px color-mix(in srgb, var(--c-pill) 55%, transparent);
}
.trm .trm-pill:focus-visible { outline: 2px solid var(--c-pill); outline-offset: 2px; }
/* the done bar: a flat cell inside the card, the 3D tick */
.trm .donebar {
  display: flex; align-items: center; gap: 8px; width: 100%; margin-top: 10px; padding: 8px 10px;
  border: 0; border-radius: 12px; font: inherit; text-align: left;
  background: rgba(245, 239, 230, 0.04); box-shadow: none; color: var(--text-secondary);
}
.trm .donebar-check { flex: 0 0 auto; width: 22px; height: 22px; display: grid; place-items: center; background: none; }
.trm .donebar-check .t-ico { width: 22px; height: 22px; filter: none; }
.trm .donebar-txt { font-size: 12.5px; font-weight: 600; color: var(--text-primary); }
.trm .donebar-detail { display: block; margin-top: 1px; font-size: 11.5px; font-weight: 500; color: var(--text-secondary); }
.trm button.donebar { cursor: pointer; }

/* ── energy: amber glass, t-flame, the big lit numeral, the split bar ── */
.trm .trm-energy.glass, .trm .trm-mus.glass { padding: 15px 16px; border-radius: 22px; }
.trm .trm-chead { display: flex; align-items: center; gap: 10px; }
.trm .trm-chead .t-ico { width: 40px; height: 40px; }
.trm .trm-chead-eb { display: block; font-size: 9.5px; font-weight: 600; letter-spacing: 1.3px; color: color-mix(in srgb, var(--c) 75%, var(--text-primary)); }
.trm .trm-chead h3 { margin: 1px 0 0; font-size: 16px; font-weight: 600; letter-spacing: -0.3px; color: var(--text-primary); }
.trm .trm-energy-main { display: flex; align-items: baseline; gap: 1px; margin-top: 8px; color: #FFD08A; text-shadow: 0 0 20px color-mix(in srgb, var(--dv-amber) 35%, transparent); }
.trm .trm-energy-main b { font-size: 30px; font-weight: 300; }
.trm .trm-energy-main strong { font-family: var(--ff-display); font-size: 46px; font-weight: 300; letter-spacing: -2.4px; line-height: 1; font-variant-numeric: tabular-nums; }
.trm .trm-energy-main small { margin-left: 4px; font-size: 14px; font-weight: 400; color: var(--text-secondary); text-shadow: none; }
.trm .trm-esplit { display: flex; height: 8px; margin: 10px 0 8px; border-radius: 4px; overflow: hidden; background: rgba(245, 239, 230, 0.07); }
.trm .trm-esplit b { background: linear-gradient(90deg, #FFE0AE, var(--dv-amber)); box-shadow: 0 0 8px var(--dv-amber); }
.trm .trm-esplit i { flex: 1; background: color-mix(in srgb, var(--dv-amber) 30%, transparent); }
.trm .trm-energy-split { display: flex; flex-wrap: wrap; justify-content: space-between; gap: 4px 10px; font-size: 11.5px; color: var(--text-secondary); }
.trm .trm-energy-split span { display: inline-flex; align-items: center; gap: 6px; }
.trm .trm-energy-split i { width: 8px; height: 8px; border-radius: 3px; }
.trm .trm-energy-split i.done { background: var(--dv-amber); box-shadow: 0 0 6px var(--dv-amber); }
.trm .trm-energy-split i.plan { background: color-mix(in srgb, var(--dv-amber) 30%, transparent); }
.trm .trm-energy-split b { font-weight: 600; color: var(--text-primary); }
.trm .trm-energy-empty { margin: 10px 0 0; font-size: 13px; line-height: 1.55; color: var(--text-secondary); }
.trm .trm-energy-note, .trm .trm-mus-note { margin: 10px 0 0; font-size: 11px; line-height: 1.45; color: var(--text-muted); }

/* ── muscle impact: coral glass, rows in the region hue ── */
.trm .trm-mus-row { display: grid; grid-template-columns: 28px minmax(0, 64px) minmax(0, 1fr) auto; align-items: center; gap: 10px; margin-top: 10px; }
.trm .trm-mus-name { font-size: 13px; font-weight: 500; color: var(--text-primary); overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }
.trm .trm-mus-track { position: relative; height: 7px; border-radius: 4px; background: rgba(245, 239, 230, 0.07); }
.trm .trm-mus-track i { position: absolute; inset: 0 auto 0 0; width: var(--w); border-radius: 4px; }
.trm .trm-mus-track i.plan { background: color-mix(in srgb, var(--c) 38%, transparent); }
.trm .trm-mus-track i.done {
  background: linear-gradient(90deg, color-mix(in srgb, var(--c) 55%, #fff), var(--c));
  box-shadow: 0 0 8px color-mix(in srgb, var(--c) 60%, transparent);
}
.trm .trm-mus-word { min-width: 52px; font-size: 11px; color: var(--text-secondary); text-align: right; }

/* ── „Vagy inkább”: two small glass tiles ── */
.trm .trm-alt { display: grid; grid-template-columns: 1fr 1fr; gap: 10px; }
.trm .trm-alt-tile.glass {
  display: flex; flex-direction: column; align-items: flex-start; gap: 6px; width: 100%; min-width: 0;
  padding: 13px; border: 0; border-radius: 20px; font: inherit; text-align: left; cursor: pointer; color: var(--text-primary);
}
.trm .trm-alt-tile .t-ico { width: 44px; height: 44px; }
.trm .trm-alt-tile small { display: block; font-size: 9.5px; font-weight: 600; letter-spacing: 1.2px; text-transform: uppercase; color: var(--text-muted); }
.trm .trm-alt-tile strong { display: block; margin-top: 6px; font-size: 14.5px; font-weight: 600; }
.trm .trm-alt-tile:focus-visible { outline: 2px solid var(--c); outline-offset: 2px; }

/* ── nav rows: flat, 3D icon, chevron ── */
.trm .trm-row {
  display: flex; align-items: center; gap: 12px; width: 100%; min-height: 52px; padding: 11px 14px;
  border: 0; border-radius: 18px; font: inherit; text-align: left; cursor: pointer;
  color: var(--text-primary); background: rgba(245, 239, 230, 0.04); box-shadow: inset 0 0 0 1px var(--divider);
}
.trm .trm-row .t-ico { width: 30px; height: 30px; filter: drop-shadow(0 4px 5px rgba(0, 0, 0, 0.5)); }
.trm .trm-row-tx { flex: 1; min-width: 0; font-size: 13.5px; font-weight: 500; overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }
.trm .trm-row-chev { font-size: 18px; font-weight: 400; color: var(--text-muted); }
.trm .trm-row:focus-visible { outline: 2px solid var(--dv-coral); outline-offset: 2px; }

/* ── free space: the dashed one-off-workout entry + the no-meso ghost ── */
.trm .trm-add.uv-empty {
  --c: var(--dv-coral);
  display: flex; align-items: center; justify-content: center; gap: 8px; width: 100%; min-height: 48px;
  padding: 14px; border-radius: 20px; font: inherit; font-size: 14px; font-weight: 600; cursor: pointer;
  color: color-mix(in srgb, var(--c) 70%, var(--text-primary));
}
.trm .trm-add:focus-visible { outline: 2px solid var(--c); outline-offset: 2px; }
.trm-nomeso { padding: 0 4px; display: grid; gap: 12px; }
.trm-nomeso .trm-head { padding: 4px 2px 0; }
.trm-nomeso .trm-head-eb { display: block; font-size: 9.5px; font-weight: 600; letter-spacing: 1.3px; text-transform: uppercase; color: #FFB39C; }
.trm-nomeso .trm-head h1 { margin: 2px 0 0; font-size: 28px; font-weight: 600; letter-spacing: -0.8px; color: var(--text-primary); }
.trm .trm-ghost.uv-empty { --c: var(--dv-coral); display: grid; justify-items: center; gap: 6px; padding: 22px 18px; border-radius: 22px; text-align: center; }
.trm .trm-ghost-art { width: 70px; height: 70px; opacity: 0.9; }
.trm .trm-ghost p { margin: 0; font-size: 14px; line-height: 1.5; color: var(--text-secondary); }
.trm .trm-ghost .trm-pill { margin-top: 8px; }

/* ── rest day: the lavender PageHero halo (sky second hue), the dashed entry under it ── */
.trm .trm-rest { --c2: var(--dv-sky); padding: 0 4px; margin-bottom: 12px; display: grid; gap: 12px; }

/* ── the morning-training nudge: one sage glass card ── */
.trm .mtr.glass {
  --c: var(--dv-sage);
  display: flex; flex-direction: column; gap: 7px; margin: 0 4px 12px; padding: 15px 16px; border: 0; border-radius: 22px;
}
.trm .mtr-head { display: flex; align-items: center; gap: 10px; }
.trm .mtr-well { width: 42px; height: 42px; }
.trm .mtr-eye { font-size: 9.5px; font-weight: 600; letter-spacing: 1.3px; text-transform: uppercase; color: color-mix(in srgb, var(--c) 80%, var(--text-primary)); }
.trm .mtr-lead { margin: 0; font-size: 13.5px; font-weight: 500; line-height: 1.5; color: var(--text-primary); }
.trm .mtr-body { margin: 0; font-size: 12.5px; line-height: 1.6; color: var(--text-secondary); }
.trm .mtr-actions { display: flex; flex-wrap: wrap; gap: 10px; align-items: center; margin-top: 4px; }
.trm .mtr-cta {
  padding: 9px 14px; border: 0; border-radius: 999px; font: inherit; font-size: 12.5px; font-weight: 700; cursor: pointer;
  color: #191614; background: var(--c); box-shadow: 0 0 14px color-mix(in srgb, var(--c) 55%, transparent);
}
.trm .mtr-quiet {
  padding: 9px 14px; border: 0; border-radius: 999px; font: inherit; font-size: 12px; font-weight: 600; cursor: pointer;
  color: var(--text-secondary); background: rgba(245, 239, 230, 0.05); box-shadow: inset 0 0 0 1px var(--divider);
}

/* ── the loading skeleton: same rail, same geometry ── */
.trm-sk .trm-sk-hero { display: grid; justify-items: center; gap: 8px; padding: 14px 4px 18px; }
.trm-sk .trm-sk-row { display: flex; justify-content: center; gap: 6px; }

/* 320px: the title and the tiles shrink before anything overflows (U1 rule 8, U2 rule 14) */
@media (max-width: 360px) {
  .trm .trm-daystrip { gap: 3px; }
  .trm .trm-day-dl { font-size: 8.5px; letter-spacing: 0.4px; }
  .trm .trm-hero-title { font-size: 32px; letter-spacing: -1.1px; }
  .trm .trm-alt { gap: 8px; }
  .trm .trm-alt-tile.glass { padding: 11px; }
  .trm .trm-mus-row { grid-template-columns: 28px minmax(0, 52px) minmax(0, 1fr) auto; gap: 8px; }
}
/* ── /uveg edzes mai ── */

/* ── uveg edzes session (mezo-me75u.4) ── /train/session: header, progress, banners, workout cards + set rows, dock, GlassBox dialogs, session sheets ── */
/* Reference: prototypes/uveg-edzes.html#session (+ #session/uj) — `session()`, `wset()`, `dock()`,
   `GB.menu|recs|fin|chal`, `SH.set|rp|extra|note`; CSS `.wtop .pbar .warn .ovl .fresh .wcard
   .wc-head .wpills .progl .prog2 .wset .wofin .dock .gbox .mrows .kgrow .recbar .fin-list .chc
   .pillx .primary .stepper2 .choice`. Ranking (bible §3.4): the header, progress bar, callouts,
   the finish button and everything INSIDE a card are FLAT; each exercise card is ONE glass with
   `--c` = its muscle color (a skipped card is the dashed free state); the start-of-workout quest
   row is a coral glass row; the dock is ONE glass bar with no sheen (like the TabBar); every
   GlassBox dialog body is ONE glass (`.wos-gb.glass.is-still`) — GlassBox takes no className, so
   `.gl-card:has(> .wos-gb)` scopes the shared primitive to THIS page's dialogs only and turns
   the card itself into a bare positioner; sheets are floating glass (U2 rule 15) with lit flat
   pills. Page content is scoped to `.wos` (ActiveWorkoutPage root); the portalled dock, dialogs,
   sheets and the medal toast carry their own `wo-`/`wos-` roots. */

/* ── header: sticky, flat, full-bleed over the scroller's gutter ── */
.wos .wk-top.wos-top {
  position: sticky; top: 0; z-index: 20; display: flex; align-items: center; gap: 8px;
  margin-inline: calc(-1 * var(--screen-gutter)); padding: 14px 16px 10px;
  background: linear-gradient(180deg, rgba(25, 22, 20, 0.95) 65%, rgba(25, 22, 20, 0));
}
.wos .wos-top .wos-rb {
  flex: 0 0 auto; width: 38px; height: 38px; margin: 0; border: 0; border-radius: 50%;
  display: grid; place-items: center; font-size: 18px; line-height: 1; color: var(--text-secondary);
  background: rgba(245, 239, 230, 0.06); box-shadow: inset 0 0 0 1px var(--divider);
}
.wos .wos-top .wos-rb:disabled { opacity: 0.45; }
.wos .wos-top .wos-q { color: #FFD99A; font-weight: 700; }
.wos .wos-top .tt { flex: 1; min-width: 0; display: flex; align-items: baseline; gap: 8px; }
.wos .wos-top .tt .t1 {
  flex: 1; min-width: 0; font-family: var(--ff-body); font-size: 17px; font-weight: 600; letter-spacing: -0.4px;
  color: var(--text-primary); white-space: nowrap; overflow: hidden; text-overflow: ellipsis;
}
.wos .wos-top .tt .t2 {
  flex: 0 0 auto; font-size: 12px; font-weight: 500; letter-spacing: 0; text-transform: none;
  color: var(--text-secondary); white-space: nowrap; font-variant-numeric: tabular-nums;
}
.wos .wos-top .tt .t2 b { font-size: 15px; font-weight: 700; color: #FFB39C; text-shadow: 0 0 10px rgba(255, 126, 92, 0.45); }

/* ── segmented progress: a muscle-tinted track per exercise, lit fill with glow ── */
.wos .wkx-progressbar.wos-pbar { display: flex; gap: 3px; height: 6px; margin: 0 4px 10px; border-radius: 0; overflow: visible; }
.wos .wos-pbar span {
  position: relative; display: block; height: 6px; border-radius: 3px; overflow: hidden;
  background: color-mix(in srgb, var(--c) 22%, rgba(245, 239, 230, 0.06));
}
.wos .wos-pbar span b {
  position: absolute; inset: 0 auto 0 0; border-radius: 3px;
  background: var(--c); box-shadow: 0 0 8px var(--c); transition: width 0.4s var(--uv-ease);
}

/* ── the injury callout: amber, led by the 3D bandage ── */
.wos .wos-warn-wrap { padding: 0 4px 8px; }
.wos .warmstrip.wos-warn {
  --c: var(--dv-amber); display: flex; align-items: center; gap: 10px; margin: 0; padding: 9px 12px;
  border: 0; border-radius: 16px; font: 500 12.5px/1.45 var(--ff-body); color: var(--text-secondary);
  background: color-mix(in srgb, var(--c) 8%, transparent); box-shadow: inset 3px 0 0 var(--c);
}
.wos .wos-warn .t-ico { filter: drop-shadow(0 3px 5px rgba(0, 0, 0, 0.45)); }
.wos .wos-warn b { color: #FFD08A; font-weight: 600; }

/* ── the card list rail: the scroller pays 12px, +4px lands on the prototype's 16px ── */
.wos .wo-list { padding: 4px 4px 112px; }

/* the owner-approved start-of-workout quest row: ONE coral glass row */
.wos .wos-fresh.glass {
  --c: var(--dv-coral); display: flex; align-items: center; gap: 12px; width: 100%;
  margin: 0 0 12px; padding: 12px 14px; border: 0; border-radius: 20px; cursor: pointer;
  font: inherit; color: var(--text-primary); text-align: left;
}
.wos .wos-fresh-copy { flex: 1; min-width: 0; }
.wos .wos-fresh-copy strong { display: block; font-size: 14.5px; font-weight: 600; }
.wos .wos-fresh-copy small { display: block; margin-top: 2px; font-size: 11.5px; color: var(--text-secondary); }
.wos .wos-chev, .gl-card .wos-gb .wo-menu-row b { flex: 0 0 auto; font-size: 20px; font-weight: 400; color: var(--text-muted); }

/* the day's overload tally: one flat cell led by the 3D direction mark */
.wos .wo-overload.wos-ovl {
  flex-direction: row; align-items: center; gap: 10px; margin: 0 0 12px; padding: 10px 12px;
  border: 0; border-radius: 16px; background: rgba(245, 239, 230, 0.04); box-shadow: inset 0 0 0 1px var(--divider);
}
.wos .wos-ovl .t-ico { filter: drop-shadow(0 3px 5px rgba(0, 0, 0, 0.45)); }
.wos .wos-ovl-copy { min-width: 0; display: grid; gap: 1px; }
.wos .wos-ovl .wo-overload-title { font-size: 13px; font-weight: 600; color: var(--text-primary); }
.wos .wos-ovl .wo-overload-why { font-size: 11px; line-height: 1.4; color: var(--text-muted); }
/* the failed-start alert: a coral callout with a lit retry pill */
.wos .wo-overload[role="alert"] {
  --c: var(--dv-coral); margin: 0 0 12px; padding: 10px 12px; border: 0; border-radius: 16px;
  background: color-mix(in srgb, var(--c) 8%, transparent); box-shadow: inset 3px 0 0 var(--c);
}
.wos .wo-overload[role="alert"] .wo-overload-title { color: #FFB39C; }
.wos .wo-overload[role="alert"] .wo-overload-why { color: var(--text-secondary); }
.wos .wo-overload-retry {
  padding: 7px 14px; border: 0; border-radius: 999px; font-size: 12px; font-weight: 700; color: #191614;
  background: var(--dv-coral); box-shadow: 0 0 14px color-mix(in srgb, var(--dv-coral) 55%, transparent);
}

/* ── one exercise = ONE glass card, `--c` = its muscle color (set inline on the card) ── */
.wos .wo-card.glass {
  margin: 0 0 12px; padding: 13px 13px 12px; border: 0; border-radius: 22px;
  background:
    radial-gradient(120% 90% at 0% 0%, color-mix(in srgb, var(--c) 22%, transparent), transparent 62%),
    linear-gradient(160deg, rgba(52, 46, 41, 0.72), rgba(30, 27, 24, 0.60));
  box-shadow:
    0 16px 30px -16px rgba(0, 0, 0, 0.75),
    0 0 26px -6px color-mix(in srgb, var(--c) 30%, transparent),
    inset 0 1px 0 rgba(255, 244, 230, 0.10),
    inset 0 -14px 26px -18px color-mix(in srgb, var(--c) 55%, transparent);
}
/* done cards step back a notch (§3.4: what is left of the work stays loud) */
.wos .wo-card.glass.is-complete { opacity: 0.8; }
/* skipped = the dashed free state, no glass, no glow (U1 rule 6) */
.wos .wo-card.is-skipped.uv-empty {
  margin: 0 0 12px; padding: 13px; border-radius: 22px; box-shadow: none; opacity: 1;
  border: 1.5px dashed color-mix(in srgb, var(--c) 45%, transparent); background: rgba(245, 239, 230, 0.025);
}
.wos .wo-card-head { display: flex; align-items: center; gap: 11px; }
.wos .wo-card-art, .gl-card .wos-gb-recs .wo-glass-head .wo-card-art {
  flex: 0 0 auto; width: 44px; height: 44px; border: 0; border-radius: 50%; overflow: hidden;
  display: grid; place-items: center;
  background: radial-gradient(circle at 35% 28%, #3A332D, color-mix(in srgb, var(--c) 16%, #1E1B18));
  box-shadow: inset 0 1px 0 rgba(255, 244, 230, 0.08),
    inset 0 -6px 12px -8px color-mix(in srgb, var(--c) 70%, transparent),
    0 0 12px -4px color-mix(in srgb, var(--c) 55%, transparent);
}
.wos .wo-card-copy { flex: 1; min-width: 0; }
.wos .wo-card-copy strong { display: block; font-size: 16px; font-weight: 600; letter-spacing: -0.3px; line-height: 1.2; color: var(--text-primary); }
.wos .wo-card-copy small.is-skip { display: block; margin-top: 2px; font-size: 10px; font-weight: 700; letter-spacing: 1px; color: #FFB39C; }
.wos .wo-card-head .wo-card-log, .wos .wo-card-head .wo-card-menu {
  flex: 0 0 auto; width: 34px; height: 34px; margin: 0; border: 0; border-radius: 50%;
  display: grid; place-items: center; font-size: 17px; line-height: 1; color: var(--text-secondary);
  background: rgba(245, 239, 230, 0.05); box-shadow: inset 0 0 0 1px var(--divider);
}
.wos .wo-card-head .wo-card-log .t-ico { filter: none; }

/* flat pills: accepted challenge (amber-lit), note, coaching cue */
.wos .wos-pills { display: flex; flex-wrap: wrap; gap: 6px; margin-top: 10px; }
.wos .wos-pills .wo-note, .wos .wos-pills .wo-cue {
  display: inline-flex; align-items: center; gap: 6px; width: auto; max-width: 100%; min-width: 0; margin: 0;
  padding: 7px 12px; border: 0; border-radius: 999px; cursor: default;
  font: 600 12px/1.35 var(--ff-body); color: var(--text-secondary); text-align: left; white-space: normal;
  background: rgba(245, 239, 230, 0.05); box-shadow: inset 0 0 0 1px var(--divider);
}
.wos .wos-pills button.wo-note { cursor: pointer; }
.wos .wos-pills .wo-cue p { margin: 0; font: inherit; color: inherit; }
.wos .wos-pills .t-ico { filter: none; }
.wos .wos-pills .wos-pill-quest {
  color: #FFD08A; background: color-mix(in srgb, var(--dv-amber) 10%, transparent);
  box-shadow: inset 0 0 0 1px color-mix(in srgb, var(--dv-amber) 38%, transparent);
}

/* progression: a t-bolt label + two flat cells, the goal cell accent-lit */
.wos .wo-card .pobanner { margin: 10px 0 0; padding: 0; border: 0; border-radius: 0; background: none; box-shadow: none; }
.wos .wo-card .pobanner .pobanner-lab { display: flex; align-items: center; gap: 6px; margin: 0; }
.wos .wo-card .pobanner .pobanner-lab .txt {
  gap: 6px; font-size: 11px; font-weight: 600; letter-spacing: 1px;
  color: color-mix(in srgb, var(--c) 70%, var(--text-primary));
}
.wos .wo-card .pobanner .pobanner-lab .txt .t-ico { width: 20px; height: 20px; filter: none; }
.wos .wo-card .pobanner .pobanner-lab .delta {
  margin: 0; padding: 0; border-radius: 0; background: none; box-shadow: none;
  font-size: 11px; font-weight: 500; letter-spacing: 0; color: var(--text-secondary);
}
.wos .wo-card .pobanner .pobanner-lab .delta::before { content: '· '; }
.wos .wo-card .pobanner .pobanner-cells { display: grid; grid-template-columns: repeat(2, minmax(0, 1fr)); gap: 8px; margin-top: 10px; }
.wos .wo-card .pobanner .pobanner-cells .cell {
  margin: 0; padding: 10px 12px; border: 0; border-radius: 14px;
  background: rgba(245, 239, 230, 0.04); box-shadow: inset 0 0 0 1px var(--divider);
}
.wos .wo-card .pobanner .pobanner-cells .cell.now {
  margin: 0; padding: 10px 12px; border: 0;
  background: color-mix(in srgb, var(--c) 10%, transparent);
  box-shadow: inset 0 0 0 1px color-mix(in srgb, var(--c) 38%, transparent);
}
.wos .wo-card .pobanner .pobanner-cells .clab { font-size: 9.5px; font-weight: 600; letter-spacing: 1.1px; color: var(--text-muted); }
.wos .wo-card .pobanner .pobanner-cells .cval { margin-top: 3px; font-size: 14.5px; font-weight: 600; color: var(--text-primary); white-space: normal; }
.wos .wo-card .pobanner .pobanner-cells .cell.now .cval { font-size: 14.5px; color: color-mix(in srgb, var(--c) 55%, #fff); }

/* ── set rows: flat; done = lit tick disc + 3D verdict, current = accent-lit, upcoming muted ── */
.wos .wo-rows { margin-top: 10px; }
.wos .wo-rows-head, .wos .wo-row { grid-template-columns: 22px 1fr 1fr 44px 38px 28px; gap: 6px; }
.wos .wo-rows-head { padding: 0 6px 4px; font-size: 9px; font-weight: 600; letter-spacing: 1.1px; color: var(--text-muted); }
.wos .wo-row {
  margin: 0 0 5px; padding: 6px; border: 0; border-radius: 12px; background: transparent; box-shadow: none;
  font-size: 14px; font-variant-numeric: tabular-nums; text-align: center; color: var(--text-muted);
}
.wos .wo-row .wo-idx { font-size: 12px; color: var(--text-muted); }
.wos .wo-row.is-done { color: var(--text-primary); background: rgba(245, 239, 230, 0.035); }
.wos .wo-row.is-done .wo-field.num { font-weight: 600; }
.wos .wo-row.is-done .wo-field.small { font-weight: 400; color: var(--text-secondary); }
.wos .wo-row.is-done:disabled { opacity: 0.7; }
.wos form.wo-row.is-current {
  color: var(--text-primary);
  background: color-mix(in srgb, var(--c) 9%, transparent);
  box-shadow: inset 0 0 0 1px color-mix(in srgb, var(--c) 40%, transparent);
}
.wos .wo-row .wo-field input {
  min-height: 40px; padding: 6px 0; border: 0; border-radius: 10px;
  font-size: 14px; font-weight: 600; color: var(--text-primary); color-scheme: dark;
  background: rgba(245, 239, 230, 0.07); box-shadow: inset 0 0 0 1px var(--divider);
}
.wos .wo-row .wo-field input:disabled { opacity: 0.5; }
.wos .wo-row .wo-field input:focus-visible { outline: none; box-shadow: inset 0 0 0 1.5px var(--c); }
/* the tick column: a hollow ring (upcoming), the lit disc (done), and the current row's submit —
   a STRONGER hollow ring, never lit: a filled disc holding the t-tick read as "already done"
   before the set was ever logged (owner bug report 2026-09-25). Only a logged row lights up
   (prototype `.tickc` / `.tickc.on`). */
.wos .wo-row > .wo-check {
  width: 32px; height: 32px; margin: 0 auto; padding: 0; border: 0; border-radius: 50%;
  display: grid; place-items: center; background: transparent;
  box-shadow: inset 0 0 0 1.5px color-mix(in srgb, var(--c) 50%, transparent);
}
.wos .wo-row > .wo-check.is-checked {
  background: radial-gradient(circle at 35% 30%, color-mix(in srgb, var(--c) 40%, #3A332D), color-mix(in srgb, var(--c) 14%, #1E1B18));
  box-shadow: 0 0 10px -2px color-mix(in srgb, var(--c) 60%, transparent);
}
.wos .wo-row > .wo-check.is-submit {
  width: 34px; height: 34px; cursor: pointer;
  background: rgba(245, 239, 230, 0.03);
  box-shadow: inset 0 0 0 2px var(--c), 0 0 12px -2px color-mix(in srgb, var(--c) 55%, transparent);
}
.wos .wo-row > .wo-check.is-submit .t-ico { opacity: 0; transform: scale(0.6); transition: opacity 0.2s, transform 0.2s; }
@media (hover: hover) {
  .wos .wo-row > .wo-check.is-submit:not(:disabled):hover .t-ico { opacity: 0.35; transform: none; }
}
.wos .wo-row > .wo-check.is-submit:disabled { opacity: 0.45; cursor: default; }
.wos .wo-row > .wo-check .t-ico { filter: none; }
.wos .wo-row .wo-verdict { width: 28px; height: 28px; overflow: visible; }
.wos .wo-row .wo-verdict .t-ico { filter: drop-shadow(0 2px 3px rgba(0, 0, 0, 0.5)); }
.wos .wo-row .wo-verdict-mark:not(:only-child) .t-ico { width: 20px; height: 20px; }
/* the side picker under an isolation row: flat pills, the chosen one lit */
.wos .wo-pick .wo-pick-key { font-size: 9px; font-weight: 600; letter-spacing: 1.1px; color: var(--text-muted); }
.wos .wo-pick > .wo-check {
  min-height: 36px; border: 0; border-radius: 999px; font-size: 13px; font-weight: 700; color: var(--text-secondary);
  background: rgba(245, 239, 230, 0.05); box-shadow: inset 0 0 0 1px var(--divider);
}
.wos .wo-pick > .wo-check[aria-pressed="true"] { color: #191614; background: var(--c); box-shadow: 0 0 12px color-mix(in srgb, var(--c) 50%, transparent); }

/* ── the one way out: a FLAT button in three states ── */
.wos .wo-finish {
  --c: var(--dv-coral); display: flex; align-items: center; justify-content: center; gap: 8px;
  width: 100%; margin: 6px 0 0; padding: 13px; border: 0; border-radius: 18px; overflow: visible;
  font: 600 14.5px/1.2 var(--ff-body); color: var(--text-secondary);
  background: rgba(245, 239, 230, 0.05); box-shadow: inset 0 0 0 1px var(--divider);
}
.wos .wo-finish strong { font: inherit; letter-spacing: 0; }
.wos .wo-finish .wo-finish-art .t-ico { filter: drop-shadow(0 2px 4px rgba(0, 0, 0, 0.45)); }
.wos .wo-finish.is-full {
  color: #FFB39C; background: color-mix(in srgb, var(--c) 9%, transparent);
  box-shadow: inset 0 0 0 1px color-mix(in srgb, var(--c) 42%, transparent), 0 0 16px -6px var(--c);
}
.wos .wo-finish:disabled { opacity: 0.45; }

/* ── the dock: ONE fixed glass bar, no sheen; coral idle, sky resting ── */
.wo-dock.glass {
  --c: var(--dv-coral);
  position: absolute; left: 10px; right: 10px; bottom: calc(12px + env(safe-area-inset-bottom)); z-index: 40;
  width: auto; max-width: 408px; height: auto; margin: 0 auto;
  display: flex; align-items: center; gap: 12px; padding: 10px 12px 10px 10px;
  border: 0; border-radius: 26px;
}
.wo-dock.glass.is-resting { --c: var(--dv-sky); }
.wo-dock.glass .wo-dock-ring { position: relative; width: 48px; height: 48px; flex: 0 0 auto; }
.wo-dock.glass .wo-dock-ring svg { width: 48px; height: 48px; transform: rotate(-90deg); overflow: visible; }
.wo-dock.glass .wo-dock-ring .track { stroke: rgba(245, 239, 230, 0.07); stroke-width: 4; }
.wo-dock.glass .wo-dock-ring .fill {
  stroke: var(--c); stroke-width: 4; stroke-linecap: round;
  filter: drop-shadow(0 0 5px color-mix(in srgb, var(--c) 55%, transparent));
}
.wo-dock.glass .wo-dock-ring b { font-size: 15px; font-weight: 600; color: var(--text-primary); }
.wo-dock.glass .wo-dock-ring .wo-dock-clock { position: absolute; left: 7px; top: 7px; filter: drop-shadow(0 3px 4px rgba(0, 0, 0, 0.5)); }
.wo-dock.glass .wo-dock-copy { flex: 1; min-width: 0; display: block; }
.wo-dock.glass .wo-dock-copy small {
  display: block; font-size: 9.5px; font-weight: 600; letter-spacing: 1.2px; color: var(--text-muted);
  white-space: nowrap; overflow: hidden; text-overflow: ellipsis;
}
.wo-dock.glass .wo-dock-copy strong {
  display: block; font-family: var(--ff-body); font-size: 17px; font-weight: 600; letter-spacing: -0.3px; color: var(--text-primary);
}
.wo-dock.glass.is-resting .wo-dock-copy small { color: color-mix(in srgb, var(--c) 70%, var(--text-primary)); }
.wo-dock.glass.is-resting .wo-dock-copy strong {
  font-family: var(--ff-display); font-size: 26px; font-weight: 300; letter-spacing: -1px; line-height: 1.1;
  font-variant-numeric: tabular-nums; color: #CFE6FA; text-shadow: 0 0 14px rgba(127, 178, 222, 0.5);
}
.wo-dock.glass .wo-dock-acts { margin: 0; display: flex; gap: 7px; flex: 0 0 auto; }
.wo-dock.glass .wo-dock-finish, .wo-dock.glass .wo-dock-acts .wo-dock-go {
  flex: 0 0 auto; margin: 0; padding: 11px 14px; border: 0; border-radius: 15px; white-space: nowrap;
  font-size: 13px; font-weight: 700; color: #191614;
  background: var(--c); box-shadow: 0 0 14px color-mix(in srgb, var(--c) 55%, transparent);
}
.wo-dock.glass .wo-dock-finish:disabled { opacity: 0.45; box-shadow: none; }
.wo-dock.glass .wo-dock-acts .wo-dock-ghost {
  padding: 10px 12px; border: 0; border-radius: 14px; font-size: 13px; font-weight: 600; color: var(--text-secondary);
  background: rgba(245, 239, 230, 0.06); box-shadow: inset 0 0 0 1px var(--divider);
}

/* ── GlassBox dialogs: the card is a bare centred positioner, the body is ONE glass ── */
.gl-card:has(> .wos-gb) {
  --c: var(--dv-coral);
  position: absolute; left: 0; right: 0; top: 50%; bottom: auto; transform: translateY(-50%);
  width: 100%; max-width: 428px; max-height: 84%; margin: 0 auto; overflow-x: hidden; overflow-y: auto;
  padding: 10px 12px; border: 0; border-radius: 0; background: none; box-shadow: none; text-align: left;
}
.gl-card:has(> .wos-gb-recs) { --c: var(--dv-amber); }
.gl-card > .wos-gb.glass { --c: inherit; padding: 74px 16px 16px; border-radius: 26px; }
.gl-card > .wos-gb-recs.glass, .gl-card > .wos-gb-fin.glass { padding-top: 54px; }
.gl-card > .wos-gb-chal.glass { padding-top: 82px; }
.gl-card:has(> .wos-gb) > .gl-head {
  position: absolute; top: 24px; left: 28px; right: 28px; z-index: 5; margin: 0; gap: 12px; align-items: center;
}
.gl-card:has(> .wos-gb) .gl-head-title small {
  font: 600 9.5px/1.2 var(--ff-body); letter-spacing: 1.3px; text-transform: uppercase;
  color: color-mix(in srgb, var(--c) 75%, var(--text-primary));
}
.gl-card:has(> .wos-gb) .gl-head-title strong {
  display: block; margin-top: 2px; font: 600 19px/1.2 var(--ff-body); letter-spacing: -0.5px; color: var(--text-primary);
}
/* the records + finish glasses lead with an eyebrow, their own body carries the title */
.gl-card:has(> .wos-gb-recs) .gl-head-title strong, .gl-card:has(> .wos-gb-fin) .gl-head-title strong {
  margin: 0; font: 600 9.5px/1.3 var(--ff-body); letter-spacing: 1.3px; text-transform: uppercase;
  color: color-mix(in srgb, var(--c) 75%, var(--text-primary));
  white-space: nowrap; overflow: hidden; text-overflow: ellipsis;
}
.gl-card:has(> .wos-gb) .gl-x {
  flex: 0 0 auto; width: 32px; height: 32px; border: 0; border-radius: 50%; font-size: 14px; color: var(--text-secondary);
  background: rgba(245, 239, 230, 0.06); box-shadow: inset 0 0 0 1px var(--divider);
}
.gl-card:has(> .wos-gb) .wos-gb-art {
  flex: 0 0 auto; width: 44px; height: 44px; border-radius: 50%; overflow: hidden; display: grid; place-items: center;
  --c: var(--dv-coral);
  background: radial-gradient(circle at 35% 28%, #3A332D, color-mix(in srgb, var(--c) 16%, #1E1B18));
  box-shadow: inset 0 1px 0 rgba(255, 244, 230, 0.08), 0 0 12px -4px color-mix(in srgb, var(--c) 55%, transparent);
}
.gl-card:has(> .wos-gb) .wos-gb-art3d {
  filter: drop-shadow(0 6px 7px rgba(0, 0, 0, 0.55)) drop-shadow(0 0 10px color-mix(in srgb, var(--c) 40%, transparent));
}
@media (prefers-reduced-motion: no-preference) {
  .gl-card.gl-anim:has(> .wos-gb) { animation: wos-gb-in 0.28s var(--uv-ease) both; }
}
@keyframes wos-gb-in {
  from { opacity: 0; transform: translateY(-46%) scale(0.96); }
  to { opacity: 1; transform: translateY(-50%) scale(1); }
}
.gl-card .wos-gb .wos-gb-sub { margin: 0 0 12px; font-size: 12px; color: var(--text-secondary); }
.gl-card .wos-gb .wos-gb-note { margin: 12px 0 0; font-size: 11px; line-height: 1.45; color: var(--text-muted); }
.gl-card .wos-gb .wos-gb-empty { margin: 0; padding: 14px; border-radius: 16px; font-size: 13px; color: var(--text-secondary); text-align: center; }

/* menu: flat rows with 3D icons */
.gl-card .wos-gb-menu.wo-menu { display: grid; gap: 6px; }
.gl-card .wos-gb-menu .wo-menu-row {
  display: flex; align-items: center; gap: 12px; width: 100%; padding: 10px 12px; border: 0; border-radius: 14px;
  font: inherit; color: var(--text-primary); text-align: left; cursor: pointer;
  background: rgba(245, 239, 230, 0.04); box-shadow: inset 0 0 0 1px var(--divider);
}
.gl-card .wos-gb-menu .wo-menu-row > span { flex: 1; min-width: 0; }
.gl-card .wos-gb-menu .wo-menu-row strong { display: block; font-size: 14px; font-weight: 600; }
.gl-card .wos-gb-menu .wo-menu-row small { display: block; margin-top: 1px; font-size: 11px; color: var(--text-muted); }
.gl-card .wos-gb-menu .wo-menu-row.is-warn strong { color: #FFB39C; }
.gl-card .wos-gb-menu .wo-menu-row:disabled { opacity: 0.34; cursor: default; }

/* video: the embed frame (a dashed free frame when there is nothing to play) */
.gl-card .wos-gb-video .wo-video-frame { border: 0; border-radius: 16px; overflow: hidden; background: rgba(245, 239, 230, 0.04); }
.gl-card .wos-gb-video .wo-video-frame.uv-empty {
  display: grid; place-items: center; gap: 8px; padding: 26px 14px; font-size: 12px; color: var(--text-secondary);
  border: 1.5px dashed color-mix(in srgb, var(--c) 45%, transparent); background: rgba(245, 239, 230, 0.025);
}
.gl-card .wos-gb-video .wo-video-frame .t-ico { filter: drop-shadow(0 6px 7px rgba(0, 0, 0, 0.55)); }

/* records: flat KG/REP/RIR cells + flat record bars, the beaten one amber-lit */
.gl-card .wos-gb-recs .wo-glass-head { display: flex; align-items: center; gap: 12px; margin: 0 0 12px; }
.gl-card .wos-gb-recs .wo-glass-head small { display: block; font-size: 9.5px; font-weight: 600; letter-spacing: 1.3px; color: var(--text-muted); }
.gl-card .wos-gb-recs .wo-glass-head strong { display: block; margin-top: 2px; font-size: 19px; font-weight: 600; letter-spacing: -0.5px; color: var(--text-primary); }
.gl-card .wos-gb-recs .wo-glass-title {
  display: block; margin: 14px 0 6px; font-size: 9.5px; font-weight: 600; letter-spacing: 1.3px; text-transform: uppercase; color: var(--text-muted);
}
.gl-card .wos-gb-recs .wo-glass-title span { margin-top: 2px; font-size: 11px; font-weight: 400; letter-spacing: 0; text-transform: none; color: var(--text-muted); }
.gl-card .wos-gb-recs .wo-glass-head + .wo-glass-title { margin-top: 4px; }
.gl-card .wos-gb-recs .wos-kgrow { padding: 0; border: 0; background: none; }
.gl-card .wos-gb-recs .wos-kgrow .wo-last-row { display: grid; grid-template-columns: repeat(3, minmax(0, 1fr)); gap: 8px; padding: 0; border: 0; }
.gl-card .wos-gb-recs .wos-kgcell {
  display: block; padding: 10px 12px; border-radius: 14px; text-align: center;
  background: rgba(245, 239, 230, 0.04); box-shadow: inset 0 0 0 1px var(--divider);
}
.gl-card .wos-gb-recs .wos-kgrow .wo-last-row .wos-kgcell small { display: block; font-size: 9.5px; font-weight: 600; letter-spacing: 1.1px; color: var(--text-muted); }
.gl-card .wos-gb-recs .wos-kgrow .wo-last-row .wos-kgcell strong { display: block; margin-top: 2px; font-size: 18px; font-weight: 600; color: var(--text-primary); }
/* the rep-record list keeps its table, as flat rows */
.gl-card .wos-gb-recs .wo-last:not(.wos-kgrow) { padding: 2px 12px 6px; border: 0; border-radius: 14px; background: rgba(245, 239, 230, 0.04); box-shadow: inset 0 0 0 1px var(--divider); }
.gl-card .wos-gb-recs .wo-last-head { font-size: 9px; font-weight: 600; letter-spacing: 1.1px; color: var(--text-muted); }
.gl-card .wos-gb-recs .wo-last-row { border-top-color: var(--divider); }
.gl-card .wos-gb-recs .wo-last-row strong { color: var(--text-primary); font-weight: 600; }
.gl-card .wos-gb-recs .wo-rec-empty { margin: 0 0 8px; font-size: 11.5px; color: var(--text-secondary); }
.gl-card .wos-gb-recs .wo-recs { display: grid; gap: 8px; }
.gl-card .wos-gb-recs .wo-rec {
  grid-template-columns: 24px minmax(0, 1fr) auto; column-gap: 8px; row-gap: 5px; padding: 10px 12px;
  border: 0; border-radius: 14px; background: rgba(245, 239, 230, 0.04); box-shadow: inset 0 0 0 1px var(--divider);
}
.gl-card .wos-gb-recs .wo-rec-art { grid-row: 1; align-self: start; }
.gl-card .wos-gb-recs .wo-rec-art .t-ico { filter: none; }
.gl-card .wos-gb-recs .wo-rec-head small { font-size: 10px; font-weight: 600; letter-spacing: 1.1px; color: var(--text-muted); }
.gl-card .wos-gb-recs .wo-rec-head strong { margin-top: 4px; font-size: 20px; font-weight: 600; letter-spacing: -0.5px; color: var(--text-primary); }
.gl-card .wos-gb-recs .wo-rec-since { font-size: 10.5px; color: var(--text-muted); }
.gl-card .wos-gb-recs .wo-rec-track { grid-column: 1 / -1; height: 5px; overflow: visible; background: rgba(245, 239, 230, 0.07); }
.gl-card .wos-gb-recs .wo-rec-now { grid-column: 1 / -1; font-size: 10.5px; color: var(--text-muted); }
.gl-card .wos-gb-recs .wo-rec.is-beaten {
  background: rgba(255, 190, 96, 0.08);
  box-shadow: inset 0 0 0 1px rgba(255, 190, 96, 0.4), 0 0 14px -4px rgba(255, 190, 96, 0.5);
}
.gl-card .wos-gb-recs .wo-rec-now b { font-size: 10px; font-weight: 600; letter-spacing: 1.1px; color: #FFD08A; }
.gl-card .wos-gb-recs .wo-glass-note { margin: 12px 0 0; font-size: 11px; line-height: 1.45; color: var(--text-muted); }

/* finish confirm: flat rows, ONE lit coral primary with its sub-count on its own line */
.gl-card .wos-gb-fin h2 { margin: 0 0 8px; font-size: 20px; font-weight: 600; letter-spacing: -0.5px; line-height: 1.25; color: var(--text-primary); text-align: left; }
.gl-card .wos-gb-fin p { margin: 0 0 12px; font-size: 12.5px; line-height: 1.55; color: var(--text-secondary); text-align: left; }
.gl-card .wos-gb-fin p strong { color: #FFB39C; font-weight: 600; }
.gl-card .wos-gb-fin .wo-confirm-list { display: grid; gap: 6px; margin: 4px 0 12px; }
.gl-card .wos-gb-fin .wo-confirm-list > span {
  display: flex; align-items: center; gap: 10px; padding: 8px 10px; border: 0; border-radius: 12px;
  background: rgba(245, 239, 230, 0.04); box-shadow: inset 0 0 0 1px var(--divider);
}
.gl-card .wos-gb-fin .wos-fin-art {
  flex: 0 0 auto; padding: 0; border: 0; width: 28px; height: 28px; border-radius: 50%; overflow: hidden; display: grid; place-items: center;
  background: radial-gradient(circle at 35% 28%, #3A332D, #1E1B18);
}
.gl-card .wos-gb-fin .wo-confirm-list strong { flex: 1; min-width: 0; font-size: 13.5px; font-weight: 500; color: var(--text-primary); }
.gl-card .wos-gb-fin .wo-confirm-list b { flex: 0 0 auto; font-size: 12px; font-weight: 500; color: var(--text-muted); }

/* ── shared pills of this page: the lit primary + flat pills ── */
.wos-primary {
  --c: var(--dv-coral); display: flex; align-items: center; justify-content: center; gap: 8px;
  width: 100%; margin: 0; padding: 14px 16px; border: 0; border-radius: 18px; cursor: pointer;
  font: 700 15px/1.2 var(--ff-body); color: #191614; text-align: left;
  background: linear-gradient(135deg, color-mix(in srgb, var(--c) 70%, #fff), var(--c));
  box-shadow: 0 0 18px -2px color-mix(in srgb, var(--c) 60%, transparent), inset 0 1px 0 rgba(255, 255, 255, 0.45);
}
.wos-primary:disabled { opacity: 0.45; cursor: default; }
.wos-primary .t-ico, .glass .wos-primary .t-ico { filter: none; }
.wos-primary-copy { display: flex; flex-direction: column; line-height: 1.2; }
.wos-primary-copy small { margin-top: 2px; font-size: 11.5px; font-weight: 600; opacity: 0.7; }
.wos-pill {
  display: inline-flex; align-items: center; justify-content: center; gap: 6px; padding: 8px 14px;
  border: 0; border-radius: 999px; cursor: pointer; white-space: nowrap;
  font: 600 12.5px/1.2 var(--ff-body); color: var(--text-secondary);
  background: rgba(245, 239, 230, 0.05); box-shadow: inset 0 0 0 1px var(--divider);
}
.wos-pill.is-block { width: 100%; margin-top: 8px; padding: 13px 16px; border-radius: 18px; font-size: 14.5px; }
.wos-pill.is-lit, .wos-pill.is-on, .wos-pill[aria-pressed="true"] {
  --c: var(--dv-coral); color: #191614; font-weight: 700;
  background: var(--c); box-shadow: 0 0 14px color-mix(in srgb, var(--c) 55%, transparent);
}
.wos-pill.is-warn { color: #FFB39C; background: rgba(255, 126, 92, 0.07); box-shadow: inset 0 0 0 1px rgba(255, 126, 92, 0.35); }
.wos-pill:disabled { opacity: 0.45; cursor: default; }
.wos-pill .t-ico, .glass .wos-pill .t-ico { filter: none; }

/* challenges: flat cards, the accepted one coral-lit */
.gl-card .wos-gb-chal .wos-chlist { display: grid; gap: 10px; }
.wos-chc { padding: 13px; border-radius: 18px; background: rgba(245, 239, 230, 0.04); box-shadow: inset 0 0 0 1px var(--divider); }
.wos-chc.is-accepted {
  background: color-mix(in srgb, var(--dv-coral) 9%, transparent);
  box-shadow: inset 0 0 0 1px color-mix(in srgb, var(--dv-coral) 45%, transparent), 0 0 16px -6px var(--dv-coral);
}
.wos-chc-head { display: flex; align-items: center; justify-content: space-between; gap: 10px; }
.wos-chc-type { min-width: 0; font-size: 11.5px; font-weight: 700; color: #FFB39C; }
.wos-chc-risk { flex: 0 0 auto; font-size: 9.5px; font-weight: 600; letter-spacing: 1px; text-transform: uppercase; color: var(--text-muted); }
.wos-chc-outcome {
  flex: 0 0 auto; display: inline-flex; align-items: center; gap: 5px; padding: 3px 9px; border-radius: 999px;
  font-size: 10.5px; font-weight: 600; color: var(--text-secondary);
  background: rgba(245, 239, 230, 0.05); box-shadow: inset 0 0 0 1px var(--divider);
}
.wos-chc-outcome.is-hit { color: #BFE0A8; box-shadow: inset 0 0 0 1px color-mix(in srgb, var(--dv-sage) 45%, transparent); }
.wos-chc-outcome .t-ico, .glass .wos-chc-outcome .t-ico { filter: none; }
.wos-chc-target { margin-top: 6px; font-size: 21px; font-weight: 600; letter-spacing: -0.4px; line-height: 1.15; color: var(--text-primary); }
.wos-chc-conf { display: block; margin-top: 3px; font-size: 9.5px; font-weight: 600; letter-spacing: 1px; text-transform: uppercase; color: var(--text-muted); }
.wos-chc-why { margin: 8px 0 0; font-size: 12px; line-height: 1.5; color: var(--text-secondary); }
.wos-chc-why b { color: #FFB39C; font-weight: 600; }
.wos-chc-refs { display: flex; flex-wrap: wrap; gap: 5px; margin-top: 8px; }
.wos-chc-refs .toolchip {
  max-width: 100%; overflow: hidden; text-overflow: ellipsis; padding: 4px 9px; border: 0; border-radius: 999px;
  font-size: 10.5px; color: var(--text-secondary);
  background: rgba(245, 239, 230, 0.05); box-shadow: inset 0 0 0 1px var(--divider);
}
.wos-chc-outline { margin: 10px 0 0; font-size: 12px; line-height: 1.45; color: var(--text-muted); }
.wos-chc-outline.is-hit { color: #BFE0A8; }
.wos-chc-acts { display: flex; align-items: center; gap: 8px; margin-top: 12px; padding-top: 10px; border-top: 1px solid var(--divider); }
.wos-chc-acts .wos-pill { flex: 1; height: 40px; }
/* the generation loader, in the glass's coral */
.gl-card .wos-gb-chal .mz-chload-line { color: var(--text-secondary); }
.gl-card .wos-gb-chal .mz-chload-bar { background: rgba(245, 239, 230, 0.07); }
.gl-card .wos-gb-chal .mz-chload-fill {
  background: linear-gradient(90deg, color-mix(in srgb, var(--c) 55%, #fff), var(--c));
  box-shadow: 0 0 8px color-mix(in srgb, var(--c) 60%, transparent);
}

/* ── session sheets: floating glass (U2 rule 15), lit flat pills inside ── */
.sheet.glass.wos-sheet {
  --c: var(--dv-coral);
  position: absolute; left: 10px; right: 10px; bottom: calc(10px + env(safe-area-inset-bottom));
  overflow-x: hidden; overflow-y: auto; border: 0; border-radius: 30px; padding: 4px 18px 18px;
}
.sheet.glass.wos-sheet.is-lav { --c: var(--dv-lav); }
.sheet.glass.wos-sheet .sheet-handle-zone { margin: 0 -18px 4px; }
.sheet.glass.wos-sheet .sheet-handle { width: 40px; height: 5px; background: rgba(245, 239, 230, 0.22); }
.wos-sheet .wos-sheet-head { display: flex; align-items: center; gap: 14px; margin-bottom: 14px; }
.wos-sheet .wos-sheet-art {
  flex: 0 0 auto; width: 56px; height: 56px; border-radius: 50%; overflow: hidden; display: grid; place-items: center;
  background: radial-gradient(circle at 35% 28%, #3A332D, color-mix(in srgb, var(--c) 16%, #1E1B18));
  box-shadow: inset 0 1px 0 rgba(255, 244, 230, 0.08), 0 0 12px -4px color-mix(in srgb, var(--c) 55%, transparent);
}
.wos-sheet .wos-sheet-title { min-width: 0; }
.wos-sheet .wos-sheet-eb {
  display: block; font: 600 9.5px/1.3 var(--ff-body); letter-spacing: 1.3px; text-transform: uppercase;
  color: color-mix(in srgb, var(--c) 80%, var(--text-primary));
}
.wos-sheet h3 { margin: 3px 0 0; font: 600 21px/1.2 var(--ff-body); letter-spacing: -0.6px; color: var(--text-primary); }
.wos-sheet .wos-sheet-lead { margin: 0 0 14px; font-size: 13px; line-height: 1.5; color: var(--text-secondary); }
.wos-sheet .wos-sheet-hint { margin: 8px 0 0; font-size: 11px; line-height: 1.5; color: var(--text-muted); }
.wos-sheet .wos-sheet-two { display: grid; grid-template-columns: 1fr 1.6fr; gap: 10px; align-items: stretch; margin-top: 16px; }
.wos-sheet .wos-sheet-two .wos-pill.is-block { margin: 0; }
.wos-sheet .wos-sheet-ta {
  display: block; width: 100%; min-height: 96px; padding: 11px 13px; border: 0; border-radius: 13px; resize: none;
  font: 14px/1.5 var(--ff-body); color: var(--text-primary); color-scheme: dark;
  background: rgba(245, 239, 230, 0.05); box-shadow: inset 0 0 0 1px var(--divider);
}
.wos-sheet .wos-sheet-ta:focus-visible, .wos-sheet .setnote:focus-visible { outline: none; box-shadow: inset 0 0 0 1.5px var(--c); }
/* set edit: flat steppers, flat RIR / side pills (the chosen one lit), a flat note field */
.wos-sheet .steprow { gap: 10px; margin-top: 0; }
.wos-sheet .steprow .stepper {
  padding: 10px 12px; border: 0; border-radius: 14px;
  background: rgba(245, 239, 230, 0.04); box-shadow: inset 0 0 0 1px var(--divider);
}
.wos-sheet .steprow .stepper .k { font-size: 9.5px; font-weight: 600; letter-spacing: 1.3px; color: var(--text-muted); }
.wos-sheet .steprow .stepper .n { font-family: var(--ff-body); font-size: 22px; font-weight: 600; color: var(--text-primary); }
.wos-sheet .steprow .stepper .n small { color: var(--text-muted); font-weight: 600; }
.wos-sheet .steprow .stepper .b {
  flex-basis: 36px; width: 36px; height: 36px; font-size: 18px; font-weight: 600; color: var(--text-primary);
  background: rgba(245, 239, 230, 0.06); box-shadow: inset 0 0 0 1px var(--divider);
}
.wos-sheet .rirrow { gap: 6px; margin-top: 14px; }
.wos-sheet .rirrow .rk { font-size: 9.5px; font-weight: 600; letter-spacing: 1.3px; color: var(--text-muted); }
.wos-sheet .rirrow button {
  padding: 8px 0; border: 0; border-radius: 999px; font-family: var(--ff-body); font-size: 13px; font-weight: 700;
  color: var(--text-secondary); background: rgba(245, 239, 230, 0.05); box-shadow: inset 0 0 0 1px var(--divider);
}
.wos-sheet .rirrow button[aria-pressed="true"] {
  color: #191614; background: var(--c); box-shadow: 0 0 12px color-mix(in srgb, var(--c) 50%, transparent);
}
.wos-sheet .setnote {
  margin-top: 14px; padding: 11px 13px; border: 0; border-radius: 13px; font-size: 14px;
  color: var(--text-primary); color-scheme: dark; background: rgba(245, 239, 230, 0.05); box-shadow: inset 0 0 0 1px var(--divider);
}
.wos-sheet .setnote::placeholder, .wos-sheet .wos-sheet-ta::placeholder { color: var(--text-muted); }
.wos-sheet > .wos-primary { margin-top: 16px; }
/* the RP debrief: three questions, flat pill options */
.wos-sheet .wos-choices { display: grid; gap: 14px; }
.wos-sheet .wos-choice { display: grid; gap: 6px; }
.wos-sheet .wos-choice-q { font-size: 13px; font-weight: 600; color: var(--text-primary); }
.wos-sheet .wos-choice-opts { display: flex; flex-wrap: wrap; gap: 6px; }
.wos-sheet .wos-choice-opts .wos-pill { flex: 1 1 auto; min-width: 0; }

/* ── the record toast: ONE amber glass (`.glass` would otherwise pull it into the flow) ── */
.toast-solo.glass.wos-medal-toast {
  --c: var(--dv-amber);
  position: absolute; left: auto; right: 14px; top: 70px; z-index: 300;
  display: flex; align-items: center; gap: 12px; width: calc(100% - 28px); max-width: 296px;
  padding: 12px 14px; border-radius: 20px; color: var(--text-primary);
}
.wos-medal-toast .wos-medal-copy { min-width: 0; display: grid; gap: 2px; }
.wos-medal-toast .wos-medal-eb { font: 600 9.5px/1.2 var(--ff-body); letter-spacing: 1.3px; color: #FFD08A; }
.wos-medal-toast strong { font-family: var(--ff-display); font-size: 22px; font-weight: 400; letter-spacing: -0.5px; color: var(--text-primary); }
.wos-medal-toast small { font-size: 12px; line-height: 1.4; color: var(--text-secondary); }

/* ── 320px: the header, the rows and the dock must fit ── */
@media (max-width: 360px) {
  .wos .wos-top .wos-rb { width: 34px; height: 34px; }
  .wos .wos-top .tt .t1 { font-size: 15.5px; }
  .wos .wo-rows-head, .wos .wo-row { grid-template-columns: 20px 1fr 1fr 38px 34px 24px; gap: 5px; }
  .wos .wo-row .wo-field input { font-size: 13px; }
  .wo-dock.glass { gap: 9px; }
  .wo-dock.glass .wo-dock-finish, .wo-dock.glass .wo-dock-acts .wo-dock-go { padding: 10px 11px; }
  .wo-dock.glass.is-resting .wo-dock-copy strong { font-size: 22px; }
  .wos-sheet .wos-sheet-two { grid-template-columns: 1fr 1.3fr; }
}
@media (prefers-reduced-motion: reduce) {
  .wos .wos-pbar span b { transition: none; }
}
/* ── /uveg edzes session ── */

/* ── uveg edzes zaras (mezo-me75u.4) ── the closing ceremony (WorkoutCeremony, 2 steps) + /train/review/:id (WorkoutSummary, ExerciseReview) ── */
/* Reference: docs/design_2.0/prototypes/src/uveg-edzes-body.html `cer()`/`runCer()` (#cer,
   #cer/reszletek) and `review()` (#review, #review/gyak), owner OK 2026-09-24. Scopes: `.uv-cer`
   = both ceremony steps (SportCeremony shares the `.cer-*` family and keeps its skin), `.uv-rev`
   = the review shell + the exercise view (`.wsum-*`/`.wr-*`). Ranking (§3.4): the star hero and
   the kcal hero are frameless halos; the records card, the stats card, the muscle card, the CTAs,
   the comparison, medal/target/challenge cards, exercise tiles and the note are `.glass` (ONE
   `--c` each); cells, chips, set rows inside/around them are flat; empty = dashed. The rAF pass
   still toggles `is-b1/2/3` + `is-told`; every transition sits in the no-preference branch. */

/* ── ceremony · shared ground ── */
.cer-screen.uv-cer, .cer-details-screen.uv-cer { background: none; }

/* ── step 1 · the star hero (frameless gold halo that warms with --p) ── */
.cer-screen.is-staged.uv-cer { padding: 0; }
.cer-screen.is-staged.uv-cer .cer { margin-top: 0; padding: 40px 16px 8px; gap: 0; overflow: visible; }
.cer-screen.is-staged.uv-cer .cer-sky {
  top: 40%; width: 420px; height: 380px; translate: -50% -50%; border-radius: 0; opacity: 1;
  background: radial-gradient(ellipse at 50% 45%, rgba(255, 190, 96, calc(0.12 + var(--p, 0) * 0.26)),
    rgba(255, 126, 92, calc(var(--p, 0) * 0.14)) 42%, transparent 68%);
}
.cer-screen.uv-cer .cer-eyebrow {
  font-size: 9.5px; font-weight: 600; letter-spacing: 1.6px;
  color: color-mix(in srgb, var(--dv-amber) 60%, #fff);
}
.cer-screen.uv-cer .cer-stars { display: block; position: relative; width: 300px; max-width: 100%; height: 118px; margin: 14px auto 0; gap: 0; }
.cer-screen.uv-cer .cer-stars i {
  position: absolute; bottom: 6px; left: 14%; width: 52px; height: 52px; margin: 0;
  display: grid; place-items: center; transform: translateX(-50%);
}
.cer-screen.uv-cer .cer-stars i:nth-child(2) { left: 32%; bottom: 34px; width: 62px; height: 62px; margin: 0; }
.cer-screen.uv-cer .cer-stars i:nth-child(3) { left: 50%; bottom: 46px; width: 78px; height: 78px; margin: 0; }
.cer-screen.uv-cer .cer-stars i:nth-child(4) { left: 68%; bottom: 34px; width: 62px; height: 62px; margin: 0; }
.cer-screen.uv-cer .cer-stars i:nth-child(5) { left: 86%; bottom: 6px; width: 52px; height: 52px; margin: 0; }
.cer-screen.uv-cer .cer-stars .t-ico { position: absolute; inset: 0; width: 100%; height: 100%; }
/* unlit = the empty star, dimmed; half = the half star; lit = the gold star with a glow */
.cer-screen.uv-cer .cer-stars .cer-star-off { opacity: 0.55; }
.cer-screen.uv-cer .cer-stars .cer-star-half,
.cer-screen.uv-cer .cer-stars .cer-star-on { opacity: 0; transform: scale(0.6); }
.cer-screen.uv-cer .cer-stars i.is-lit .cer-star-off,
.cer-screen.uv-cer .cer-stars i.is-half .cer-star-off { opacity: 0; }
.cer-screen.uv-cer .cer-stars i.is-lit .cer-star-on {
  opacity: 1; transform: none;
  filter: drop-shadow(0 8px 10px rgba(0, 0, 0, 0.5)) drop-shadow(0 0 16px color-mix(in srgb, var(--dv-amber) 75%, transparent));
}
.cer-screen.uv-cer .cer-stars i.is-half .cer-star-half {
  opacity: 1; transform: none;
  filter: drop-shadow(0 0 12px color-mix(in srgb, var(--dv-amber) 55%, transparent));
}
/* the fuse: a recessed track, the gold gradient fill, the comet orb, four segment ticks */
.cer-screen.uv-cer .cer-bar {
  align-self: stretch; width: auto; max-width: none; height: 12px; margin: 22px 26px 0; border-radius: 6px;
  background: rgba(245, 239, 230, 0.06);
  box-shadow: inset 0 2px 4px rgba(0, 0, 0, 0.55), inset 0 0 0 1px var(--divider);
}
.cer-screen.uv-cer .cer-fill {
  border-radius: 6px;
  background: linear-gradient(90deg, color-mix(in srgb, var(--dv-amber) 50%, #000), var(--dv-amber) 70%, color-mix(in srgb, var(--dv-amber) 35%, #fff));
  box-shadow: 0 0 12px color-mix(in srgb, var(--dv-amber) 60%, transparent);
}
.cer-screen.uv-cer .cer-comet {
  z-index: 2; width: 20px; height: 20px; border-radius: 50%;
  background: radial-gradient(circle at 40% 35%, #fff, color-mix(in srgb, var(--dv-amber) 60%, #fff) 45%, transparent 72%);
  box-shadow: 0 0 18px 4px color-mix(in srgb, var(--dv-amber) 70%, transparent);
}
.cer-screen.uv-cer .cer-bar u { top: 2px; bottom: 2px; width: 1.5px; margin-left: 0; background: rgba(25, 22, 20, 0.7); }

/* ── step 1 · the verdict + the two glass cards ── */
.cer-screen.is-staged.uv-cer .cer-result { padding: 6px 16px 0; text-align: center; }
.cer-screen.uv-cer .cer-verdict {
  margin: 18px 0 14px; font-family: var(--ff-body); font-size: 34px; font-weight: 600; letter-spacing: -1.2px; line-height: 1.1;
  background: linear-gradient(90deg, var(--text-primary), color-mix(in srgb, var(--dv-amber) 45%, #fff) 55%, var(--dv-amber));
  -webkit-background-clip: text; background-clip: text; color: transparent;
  filter: drop-shadow(0 0 14px color-mix(in srgb, var(--dv-amber) 35%, transparent));
}
.cer-screen.uv-cer .cer-card.glass {
  --c: var(--dv-amber); margin: 0; padding: 14px; border: 0; border-radius: 24px; text-align: left;
}
.cer-screen.uv-cer .cer-card.cer-records + .cer-card.cer-sum { margin-top: 12px; }
/* the records card: header row — t-record in a lit well, eyebrow, "<n> új rekord" */
.cer-screen.is-staged.uv-cer .cer-card .cer-record {
  display: flex; align-items: center; gap: 12px; margin: 0; padding: 0 0 10px;
  border: 0; border-radius: 0; background: none; box-shadow: none; opacity: 1; scale: none;
}
.cer-screen.uv-cer .cer-record .uv-well .t-ico { width: 40px; height: 40px; }
.cer-screen.uv-cer .cer-record .uv-eyebrow { display: block; color: color-mix(in srgb, var(--dv-amber) 60%, #fff); }
.cer-screen.uv-cer .cer-record strong {
  display: block; margin-top: 1px; font-size: 19px; font-weight: 600; letter-spacing: -0.4px;
  color: color-mix(in srgb, var(--dv-amber) 45%, #fff);
}
.cer-screen.uv-cer .cer-rec-row { display: grid; gap: 5px; padding: 11px 0; border-top: 1px solid var(--divider); }
.cer-screen.uv-cer .cer-rec-row > strong { font-size: 15px; font-weight: 600; color: var(--text-primary); }
/* ONE wrapping chip line: the type chip (amber, 3D icon) + the plain value pills */
.cer-screen.uv-cer .cer-vals { display: flex; flex-wrap: wrap; align-items: center; justify-content: flex-start; gap: 5px; min-width: 0; margin-top: 3px; }
.cer-screen.uv-cer .cer-vals > b {
  padding: 5px 11px; border-radius: 999px; font-size: 12.5px; font-weight: 600; white-space: nowrap; color: var(--text-primary);
  background: rgba(245, 239, 230, 0.06); box-shadow: inset 0 0 0 1px var(--divider);
}
.cer-screen.uv-cer .cer-vals > b.is-lit {
  color: var(--surface-card);
  background: linear-gradient(135deg, color-mix(in srgb, var(--dv-amber) 45%, #fff), var(--dv-amber));
  box-shadow: 0 0 12px color-mix(in srgb, var(--dv-amber) 50%, transparent);
}
.cer-screen.uv-cer .cer-tchip {
  display: inline-flex; align-items: center; gap: 6px; min-width: 0; padding: 3px 11px 3px 4px; border-radius: 999px;
  font-size: 12.5px; font-weight: 600; white-space: nowrap; color: color-mix(in srgb, var(--dv-amber) 45%, #fff);
  background: radial-gradient(90% 120% at 20% 20%, color-mix(in srgb, var(--dv-amber) 22%, transparent), rgba(245, 239, 230, 0.04));
  box-shadow: inset 0 0 0 1px color-mix(in srgb, var(--dv-amber) 45%, transparent), 0 0 12px -4px color-mix(in srgb, var(--dv-amber) 55%, transparent);
}
.cer-screen.uv-cer .cer-tchip.is-coral {
  color: color-mix(in srgb, var(--dv-coral) 40%, #fff);
  background: radial-gradient(90% 120% at 20% 20%, color-mix(in srgb, var(--dv-coral) 22%, transparent), rgba(245, 239, 230, 0.04));
  box-shadow: inset 0 0 0 1px color-mix(in srgb, var(--dv-coral) 45%, transparent), 0 0 12px -4px color-mix(in srgb, var(--dv-coral) 55%, transparent);
}
.cer-screen.uv-cer .glass .cer-tchip .t-ico { width: 24px; height: 24px; filter: drop-shadow(0 2px 3px rgba(0, 0, 0, 0.5)); }
/* the stats card: minutes + XP as two flat cells */
.cer-screen.uv-cer .cer-card .cer-stats { display: grid; grid-template-columns: 1fr 1fr; gap: 8px; margin: 0; padding: 0; }
.cer-screen.uv-cer .cer-card .cer-stats > span {
  display: flex; align-items: center; gap: 8px; min-width: 0; padding: 9px 10px; border: 0; border-radius: 14px;
  background: rgba(245, 239, 230, 0.04); box-shadow: inset 0 0 0 1px var(--divider);
}
.cer-screen.uv-cer .cer-card .cer-stats > span > span { display: block; min-width: 0; padding: 0; border-radius: 0; background: none; box-shadow: none; }
.cer-screen.uv-cer .cer-card .cer-stats .t-ico { flex: 0 0 auto; width: 32px; height: 32px; }
.cer-screen.uv-cer .cer-card .cer-stats strong {
  display: block; font-family: var(--ff-body); font-size: 20px; font-weight: 600; line-height: 1.2; letter-spacing: -0.5px; color: var(--text-primary);
}
.cer-screen.uv-cer .cer-card .cer-stats strong i { font-size: inherit; color: var(--text-muted); }
.cer-screen.uv-cer .cer-card .cer-stats small {
  display: block; margin: 0; font-size: 10.5px; font-weight: 400; letter-spacing: 0; text-transform: none; color: var(--text-muted);
}
/* the tally row */
.cer-screen.uv-cer .cer-tally { display: grid; grid-template-columns: repeat(3, 1fr); gap: 6px; margin: 10px 0 0; padding: 0; box-shadow: none; }
.cer-screen.uv-cer .cer-card .cer-stats + .cer-tally { box-shadow: none; }
.cer-screen.uv-cer .cer-tally > span { display: flex; flex-direction: column; align-items: center; gap: 2px; min-width: 0; padding: 8px 4px; }
.cer-screen.uv-cer .glass .cer-tally .t-ico { width: 24px; height: 24px; filter: none; }
.cer-screen.uv-cer .cer-tally b {
  font-family: var(--ff-body); font-size: 19px; font-weight: 600; letter-spacing: 0; font-variant-numeric: tabular-nums; color: var(--text-primary);
}
.cer-screen.uv-cer .cer-tally small { font-size: 10px; font-weight: 400; letter-spacing: 0; text-transform: none; color: var(--text-muted); }
/* KÜLDETÉSEK · hit / total — revealed on beat b3; a miss only dims (the report never punishes) */
.cer-screen.uv-cer .cer-quests { margin-top: 12px; padding-top: 10px; border-top: 1px solid var(--divider); opacity: 0.3; }
.cer-screen.uv-cer.is-b3 .cer-quests { opacity: 1; }
.cer-screen.uv-cer .cer-quests > .uv-eyebrow { display: block; margin-bottom: 6px; }
.cer-screen.uv-cer .cer-quest { position: relative; display: flex; align-items: flex-start; gap: 10px; padding: 9px 0; }
.cer-screen.uv-cer .cer-quest + .cer-quest { border-top: 1px solid var(--divider); }
.cer-screen.uv-cer .cer-quest-body { flex: 1; min-width: 0; display: grid; gap: 5px; }
.cer-screen.uv-cer .cer-quest-body > strong {
  display: flex; align-items: center; min-height: 26px; padding-right: 46px;
  font-size: 13.5px; font-weight: 600; color: var(--text-primary);
}
.cer-screen.uv-cer .cer-quest-res {
  position: absolute; right: 0; top: 6px; width: 40px; height: 40px; border-radius: 50%;
  display: grid; place-items: center; background: rgba(245, 239, 230, 0.04); box-shadow: inset 0 0 0 1px var(--divider);
}
.cer-screen.uv-cer .cer-quest-res .t-ico { width: 30px; height: 30px; }
.cer-screen.uv-cer .cer-quest.is-hit .cer-quest-res {
  background: radial-gradient(circle at 35% 30%, color-mix(in srgb, var(--dv-sage) 35%, transparent), rgba(30, 27, 24, 0.6));
  box-shadow: inset 0 0 0 1.5px color-mix(in srgb, var(--dv-sage) 55%, transparent), 0 0 14px -2px color-mix(in srgb, var(--dv-sage) 60%, transparent);
}
.cer-screen.uv-cer .cer-quest.is-hit .cer-vals > b:first-of-type {
  color: var(--surface-card);
  background: linear-gradient(135deg, color-mix(in srgb, var(--dv-sage) 45%, #fff), var(--dv-sage));
  box-shadow: 0 0 10px color-mix(in srgb, var(--dv-sage) 45%, transparent);
}
.cer-screen.uv-cer .cer-quest.is-miss, .cer-screen.uv-cer .cer-quest.is-inconclusive { opacity: 0.62; }
.cer-screen.uv-cer .cer-quest.is-miss .cer-quest-res .t-ico,
.cer-screen.uv-cer .cer-quest.is-inconclusive .cer-quest-res .t-ico { opacity: 0.75; }
.cer-screen.is-staged.uv-cer .cer-result > .cer-recap-note { margin: 10px 0 0; font-size: 11.5px; line-height: 1.45; color: var(--text-muted); }

/* ── the CTA rows (step 1 `Részletek` amber, step 2 `Vissza a mai napra` sage) ── */
.cer-screen.uv-cer .cer-foot { padding: 18px 16px 14px; }
.uv-cer .cer-cta { padding-top: 0; }
.uv-cer .cer-go.glass {
  --c: var(--dv-amber); display: flex; align-items: center; gap: 12px; width: 100%;
  padding: 12px 14px 12px 12px; border: 0; border-radius: 22px; text-align: left; cursor: pointer;
  font: inherit; color: var(--text-primary);
}
.uv-cer .cer-go.glass.is-done { --c: var(--dv-sage); }
.uv-cer .cer-go > .t-ico { width: 44px; height: 44px; }
.uv-cer .cer-go > span { flex: 1; min-width: 0; }
.uv-cer .cer-go strong { display: block; font-size: 17px; font-weight: 600; }
.uv-cer .cer-go small { display: block; margin-top: 1px; font-size: 11.5px; color: var(--text-secondary); }
.uv-cer .cer-go em {
  flex: 0 0 auto; width: 40px; height: 40px; border-radius: 50%; display: grid; place-items: center;
  font-style: normal; font-size: 19px; color: var(--surface-card); background: var(--c);
  box-shadow: 0 0 16px color-mix(in srgb, var(--c) 60%, transparent);
}
.uv-cer .cer-go:focus-visible { outline: 2px solid var(--c); outline-offset: 2px; }
.uv-cer .cer-back.uv-flat {
  display: block; width: 100%; margin-top: 8px; padding: 12px; border: 0; border-radius: 16px; cursor: pointer;
  font: inherit; font-size: 13px; font-weight: 600; color: var(--text-secondary);
}

/* ── step 2 · recap pill, kcal halo, the coral muscle card, the flat note ── */
.cer-details-screen.uv-cer { padding: 24px 16px 16px; }
.cer-details-screen.uv-cer .cer-recap-chip.uv-flat {
  display: flex; align-items: center; gap: 8px; width: fit-content; max-width: 100%; margin: 4px auto 0;
  padding: 6px 14px 6px 10px; border-radius: 999px; font-size: 12px; font-weight: 600; color: var(--text-primary);
}
.uv-cer .cer-starrow.mini { display: inline-flex; gap: 2px; flex: 0 0 auto; }
.uv-cer .cer-starrow.mini i { width: 16px; height: 16px; }
.uv-cer .cer-starrow.mini .t-ico { width: 100%; height: 100%; }
.uv-cer .glass .cer-starrow.mini .t-ico { filter: none; }
.cer-details-screen.uv-cer .cer-kcal.uv-halo {
  --c: var(--dv-sage); --c2: var(--dv-amber);
  position: relative; overflow-x: clip; display: block; width: 100%; margin: 6px 0 0; padding: 18px 16px 10px;
  border: 0; border-radius: 0; background: none; box-shadow: none; text-align: center; color: var(--text-primary);
}
.cer-details-screen.uv-cer .cer-kcal-line { display: flex; align-items: center; justify-content: center; gap: 4px; }
.cer-details-screen.uv-cer .cer-kcal-line .cer-kcal-art {
  width: 66px; height: 66px; margin-right: 6px;
  filter: drop-shadow(0 10px 12px rgba(0, 0, 0, 0.5)) drop-shadow(0 0 16px color-mix(in srgb, var(--dv-sage) 45%, transparent));
}
.cer-details-screen.uv-cer .cer-kcal-line b,
.cer-details-screen.uv-cer .cer-kcal-line strong {
  font-family: var(--ff-display); font-size: 60px; font-weight: 300; line-height: 1; letter-spacing: -3px;
  color: color-mix(in srgb, var(--dv-sage) 40%, #fff);
  text-shadow: 0 0 20px color-mix(in srgb, var(--dv-sage) 45%, transparent);
}
.cer-details-screen.uv-cer .cer-kcal-line b { letter-spacing: 0; }
.cer-details-screen.uv-cer .cer-kcal-line small { align-self: flex-end; padding-bottom: 8px; margin-left: 4px; font-size: 18px; font-weight: 400; color: var(--text-secondary); }
.cer-details-screen.uv-cer .cer-kcal-copy { display: block; margin-top: 2px; font-size: 13.5px; color: var(--text-primary); }
.cer-details-screen.uv-cer .cer-kcal .cer-recap-note { display: block; margin: 4px 0 0; font-size: 11.5px; color: var(--text-muted); }
.cer-details-screen.uv-cer .cer-kcal-go { top: 50%; right: 22px; font-size: 22px; color: var(--text-muted); }
.cer-details-screen.uv-cer .cer-section { margin: 18px 2px 8px; }
.cer-details-screen.uv-cer .cer-section strong { font-family: var(--ff-body); font-size: 19px; font-weight: 600; letter-spacing: -0.5px; }
.cer-details-screen.uv-cer .cer-mstars.glass {
  --c: var(--dv-coral); display: block; margin: 0; padding: 8px 14px; border: 0; border-radius: 22px;
}
.cer-details-screen.uv-cer .cer-mstar {
  grid-template-columns: 40px 1fr auto; grid-template-rows: auto auto; column-gap: 10px; row-gap: 6px; padding: 10px 0;
}
.cer-details-screen.uv-cer .cer-mstar-art {
  grid-row: 1 / 3; width: 40px; height: 40px; border-radius: 50%; overflow: hidden;
  background: radial-gradient(circle at 35% 28%, #3A332D, color-mix(in srgb, var(--c) 16%, #1E1B18));
  box-shadow: inset 0 1px 0 rgba(255, 244, 230, 0.08), inset 0 -6px 12px -8px color-mix(in srgb, var(--c) 70%, transparent),
    0 0 12px -4px color-mix(in srgb, var(--c) 55%, transparent);
}
