.uv-rev .wr-set .band {
  display: inline-block; margin-left: 6px; padding: 3px 8px; border-radius: 999px; font-size: 11px; font-weight: 500;
  letter-spacing: 0; text-transform: none; background: rgba(245, 239, 230, 0.06); color: var(--text-secondary);
}
.uv-rev .wr-set .band.in { background: color-mix(in srgb, var(--dv-sage) 12%, transparent); color: color-mix(in srgb, var(--dv-sage) 50%, #fff); }
.uv-rev .wr-set .note { margin-top: 2px; font-size: 11px; color: var(--text-muted); }
.uv-rev .wr-set .vol { font-size: 12px; font-weight: 500; color: var(--text-secondary); }
.uv-rev .wr-set.rec {
  background: color-mix(in srgb, var(--dv-amber) 9%, transparent); box-shadow: inset 0 0 0 1px color-mix(in srgb, var(--dv-amber) 38%, transparent);
}
.uv-rev .wr-set.rec .vol { color: color-mix(in srgb, var(--dv-amber) 50%, #fff); }
.uv-rev .wr-set.ghost { background: none; box-shadow: none; border: 1.2px dashed rgba(245, 239, 230, 0.14); color: var(--text-muted); }
.uv-rev .wr-set.ghost .ix { background: none; border: 1.2px dashed rgba(245, 239, 230, 0.14); color: var(--text-muted); }
.uv-rev .wr-set.ghost .load { font-size: 12px; color: var(--text-muted); }
@media (max-width: 360px) {
  .uv-rev .wsum-num { font-size: 62px; }
  .uv-rev .wsum-stripwrap .v { font-size: 17px; }
  .uv-rev .wr-cmp-cell.uv-flat { padding: 9px 8px; }
  .uv-rev .wr-cmp-cell .v { font-size: 15px; }
}
/* ── /uveg edzes zaras ── */

/* ── uveg edzes terheles (mezo-me75u.4) ── /train/gym = /train/week: BodyMap hero, map card, muscle-group tiles + detail glass, sport/movement cards ── */
/* Ranking (bible §3.4, prototype uveg-edzes.html#gym): the hero is a FRAMELESS coral→lavender
   halo; the map doorway (lav), every group tile (its muscle hue, `--c` set on the tile), the
   sport card (rose) and the movement doorway (amber) are glass; chips/rows/tags inside are
   flat; „+ Saját edzés" is dashed. Everything scoped to `.tw-load` (the page root) or
   `.tw-glass` (the GlassBox body, portalled outside the page): the `ld-` family is shared
   with the week sub-pages (U5), whose older rules above stay untouched. */
.tw-load { --c: var(--dv-coral); }

/* — the hero: a halo, no box — */
.tw-load .ld-hero {
  position: relative; isolation: isolate; overflow: visible; overflow-x: clip;
  display: grid; grid-template-columns: 112px minmax(0, 1fr); gap: 12px; align-items: center;
  padding: 8px 18px 6px; background: none;
}
.tw-load .ld-hero::before {
  content: ''; position: absolute; left: 30%; top: 50%; z-index: -1; pointer-events: none;
  width: 340px; height: 300px; transform: translate(-50%, -50%);
  background: radial-gradient(ellipse at 50% 45%,
    color-mix(in srgb, var(--dv-coral) 30%, transparent),
    color-mix(in srgb, var(--dv-lav) 12%, transparent) 42%, transparent 68%);
}
.tw-load .ld-hero-art { position: relative; inset: auto; right: auto; top: auto; width: 112px; height: 210px; }
.tw-load .ld-hero-body { position: absolute; inset: 0; }
.tw-load .ld-hero-body .body-map-figure { filter: drop-shadow(0 12px 16px rgba(0, 0, 0, 0.5)); }
.tw-hero-main { min-width: 0; }
.tw-load .ld-hero .ld-eyebrow {
  font-size: 9.5px; font-weight: 600; letter-spacing: 1.3px;
  color: color-mix(in srgb, var(--dv-coral) 62%, var(--text-primary));
}
.tw-load .ld-hero-pct { margin: 4px 0 0; }
.tw-load .ld-hero-pct b {
  font-family: var(--ff-display); font-size: 64px; font-weight: 300; letter-spacing: -3.5px; line-height: 1;
  color: var(--text-primary);
}
.tw-load .ld-hero-pct em { font-size: 22px; font-weight: 400; letter-spacing: -1px; color: var(--text-muted); }
.tw-load .ld-hero-sub { margin: 4px 0 0; max-width: none; font-size: 12px; line-height: 1.45; color: var(--text-secondary); }
.tw-load .ld-hero-sub b { color: var(--text-primary); font-weight: 600; }
.tw-load .ld-hero-bar {
  height: 6px; margin: 10px 0 8px; max-width: none; border-radius: 3px; overflow: visible;
  background: rgba(245, 239, 230, 0.07);
}
.tw-load .ld-hero-bar i {
  border-radius: 3px;
  background: linear-gradient(90deg, color-mix(in srgb, var(--dv-coral) 55%, #fff), var(--dv-coral));
  box-shadow: 0 0 8px color-mix(in srgb, var(--dv-coral) 60%, transparent);
}
.tw-load .ld-hero-say {
  display: flex; align-items: flex-start; gap: 6px; max-width: none;
  font-size: 12.5px; line-height: 1.45; color: var(--text-primary);
}
.tw-load .ld-hero-say > span { flex: 1; min-width: 0; }
.tw-load .ld-hero-chips { display: flex; flex-wrap: wrap; gap: 6px; margin-top: 10px; }
/* flat chips (§3 rank 3) — never glass in a halo row */
.tw-load .tw-chip {
  display: inline-flex; align-items: center; gap: 6px; min-width: 0; max-width: 100%;
  height: auto; min-height: 36px; margin-left: 0; padding: 7px 12px; border: 0; border-radius: 999px;
  font: 600 12px/1.2 var(--ff-body); color: var(--text-secondary);
  background: rgba(245, 239, 230, 0.05); box-shadow: inset 0 0 0 1px var(--divider);
  white-space: nowrap; overflow: hidden; text-overflow: ellipsis;
}
.tw-load .tw-chip .t-ico { filter: none; }

/* — the ⓘ: a small flat round button with the 3D t-info (hit area ::after untouched) — */
.tw-load .pl-info {
  width: 22px; height: 22px; border-radius: 50%; display: grid; place-items: center; opacity: 1;
  background: rgba(245, 239, 230, 0.06); box-shadow: inset 0 0 0 1px var(--divider);
}
.tw-load .pl-info .icon, .tw-load .pl-info svg { width: 16px; height: 16px; filter: none; }

/* — section heads — */
.tw-load .ld-h3 { margin: 20px 2px 10px; font-size: 19px; font-weight: 600; letter-spacing: -0.5px; color: var(--text-primary); }
.tw-load .tw-eb { display: block; color: color-mix(in srgb, var(--c) 75%, var(--text-primary)); }

/* — the two doorways + the sport card: glass (geometry restated, rule 1/11) — */
.tw-load .ld-map-card.glass, .tw-load .ld-move-card.glass, .tw-load .ld-sport.glass {
  position: relative; overflow: hidden; display: flex; align-items: center; gap: 12px; width: 100%;
  padding: 12px 14px; border: 0; border-radius: 22px; text-align: left; color: var(--text-primary);
}
.tw-load .ld-map-card.glass { --c: var(--dv-lav); margin-top: 10px; }
.tw-load .ld-sport.glass { --c: var(--dv-rose); margin-top: 20px; padding: 14px; }
.tw-load .ld-move-card.glass { --c: var(--dv-amber); margin-top: 12px; padding: 14px; }
.tw-load .ld-map-mini { width: auto; max-width: 42%; height: 96px; flex: 0 1 auto; overflow: visible; }
.tw-load .ld-map-card .ld-map-copy { flex: 1 1 auto; min-width: 0; }
.tw-load .ld-map-copy strong, .tw-load .ld-sport-copy strong {
  display: block; margin-top: 2px; font-size: 15.5px; font-weight: 600; letter-spacing: -0.3px; color: var(--text-primary);
}
.tw-load .ld-map-copy small, .tw-load .ld-sport-copy small {
  display: block; margin-top: 2px; font-size: 11.5px; line-height: 1.45; color: var(--text-secondary);
}
.tw-load .ld-sport-copy em { margin-top: 6px; font-size: 11px; color: var(--text-muted); }
.tw-load .ld-map-card > b, .tw-load .ld-move-card > b { color: var(--text-muted); font-size: 20px; font-weight: 400; }
/* card art: the 3D icon, frameless (the halo comes from `.glass .t-ico`) */
.tw-load .ld-sport-art { width: 44px; height: 44px; border-radius: 0; background: none; box-shadow: none; }

/* — the muscle groups: 2-col glass tiles, each in its own muscle hue — */
.tw-load .ld-groups { display: grid; grid-template-columns: minmax(0, 1fr) minmax(0, 1fr); gap: 10px; }
.tw-load .ld-group.glass {
  position: relative; overflow: hidden; display: flex; flex-direction: column; gap: 7px; min-width: 0;
  width: 100%; padding: 12px; border: 0; border-radius: 20px; text-align: left; color: var(--text-primary);
}
.tw-load .ld-group-head { display: flex; align-items: center; gap: 8px; min-width: 0; }
.tw-load .ld-group-head strong {
  flex: 1; min-width: 0; font-size: 14px; font-weight: 600; color: var(--text-primary);
  white-space: nowrap; overflow: hidden; text-overflow: ellipsis;
}
/* MuscleChip is real anatomy, not an icon: it sits in a lit round well (prototype `.mchp`) */
.tw-load .tw-well, .tw-glass .tw-well {
  width: 28px; height: 28px; border-radius: 50%; flex: 0 0 auto; display: grid; place-items: center; overflow: hidden;
  background: radial-gradient(circle at 35% 28%, #3A332D, color-mix(in srgb, var(--c) 16%, #1E1B18));
  box-shadow: inset 0 1px 0 rgba(255, 244, 230, 0.08),
    inset 0 -6px 12px -8px color-mix(in srgb, var(--c) 70%, transparent),
    0 0 12px -4px color-mix(in srgb, var(--c) 55%, transparent);
}
.tw-load .tw-well .muscle-chip, .tw-glass .tw-well .muscle-chip { width: 100%; height: 100%; }
/* „sok": a flat amber tag, never red */
.tw-load .ld-group-much {
  flex: 0 0 auto; padding: 2px 7px; border-radius: 999px; font-size: 9px; font-weight: 700; letter-spacing: 1px;
  color: #FFD08A; background: rgba(255, 190, 96, 0.12); box-shadow: inset 0 0 0 1px rgba(255, 190, 96, 0.4);
}
.tw-load .tw-group-num {
  font-size: 22px; font-weight: 600; letter-spacing: -0.6px; line-height: 1.1;
  font-variant-numeric: tabular-nums; color: var(--text-primary);
}
.tw-load .tw-group-num small { margin-left: 3px; font-size: 11px; font-weight: 500; letter-spacing: 0; color: var(--text-muted); }
.tw-load .ld-group-bar { height: 5px; border-radius: 3px; overflow: visible; background: rgba(245, 239, 230, 0.07); }
.tw-load .ld-group-bar i {
  border-radius: 3px;
  background: linear-gradient(90deg, color-mix(in srgb, var(--c) 55%, #fff), var(--c));
  box-shadow: 0 0 8px color-mix(in srgb, var(--c) 60%, transparent);
}
.tw-load .ld-group-note { font-size: 11px; line-height: 1.35; color: var(--text-secondary); }

/* — the free state + the quiet note — */
.tw-load .tw-custom {
  --c: var(--dv-coral);
  display: flex; align-items: center; justify-content: center; gap: 8px; width: 100%;
  margin-top: 12px; padding: 14px; border-radius: 20px; cursor: pointer;
  font: 600 14px/1.2 var(--ff-body); color: color-mix(in srgb, var(--dv-coral) 70%, var(--text-primary));
}
.tw-load .ld-note { margin: 16px 0 0; padding: 0 8px; border-radius: 0; background: none; box-shadow: none; }
.tw-load .ld-note p { font-size: 11.5px; line-height: 1.55; color: var(--text-muted); text-align: center; }

/* — the group detail (inside the GlassBox card, which is the only glass here) — */
.tw-glass .ld-glass-hero strong { font-weight: 300; letter-spacing: -1.5px; color: var(--text-primary); }
.tw-glass .ld-glass-hero small, .tw-glass .ld-glass-word { color: var(--text-secondary); }
.tw-glass .ld-glass-rows { gap: 6px; }
.tw-glass .ld-glass-row {
  grid-template-columns: 28px minmax(0, 1fr) auto; padding: 9px 10px; border-radius: 12px;
  background: rgba(245, 239, 230, 0.04);
}
.tw-glass .ld-glass-name strong { font-weight: 600; color: var(--text-primary); }
.tw-glass .ld-glass-name small { color: var(--text-muted); }
.tw-glass .ld-glass-chips span {
  color: var(--text-secondary); background: rgba(245, 239, 230, 0.05); box-shadow: inset 0 0 0 1px var(--divider);
}
.tw-glass .ld-glass-xp {
  display: inline-flex; align-items: center; gap: 4px; padding: 3px 9px 3px 3px; border-radius: 999px;
  font-size: 12px; font-weight: 700; color: #FFD08A; white-space: nowrap;
  background: rgba(255, 190, 96, 0.1); box-shadow: inset 0 0 0 1px rgba(255, 190, 96, 0.35);
}
.tw-glass .ld-glass-xp .t-ico { filter: none; }
.tw-glass .ld-glass-foot { color: var(--text-muted); }
.tw-glass .ld-glass-empty {
  padding: 12px; border-radius: 12px; color: var(--text-secondary);
  border: 1.5px dashed color-mix(in srgb, var(--c) 45%, transparent);
}

@media (max-width: 360px) {
  .tw-load .ld-hero { grid-template-columns: 92px minmax(0, 1fr); padding: 8px 14px 6px; }
  .tw-load .ld-hero-art { width: 92px; height: 176px; }
  .tw-load .ld-hero-pct b { font-size: 50px; }
  .tw-load .ld-map-mini { height: 78px; }
  .tw-load .tw-group-num { font-size: 19px; }
}
/* ── /uveg edzes terheles ── */

/* ── uveg edzes sport (mezo-me75u.4) ── /train/sport, /train/sport/log, /train/futas, /train/futas/:id + sport/run log sheets ── */
/* Reference: docs/design_2.0/prototypes/src/uveg-edzes-body.html `sport()`, `sportlog()`, `futas()`,
   `futasterv()` + SH.sportlog / SH.runlog / SH.blkmenu (owner OK, mezo-me75u.4). Every rule is scoped
   to a page root — `.uvs-page` (SportPage `.uvs-sport`, RunningPage `.uvs-futas`, the block builder
   `.uvs-rbb`), `.uvs-log` (the chrome-less /train/sport/log flow), `.uvs-sheet` / `.capture-tone-run`
   (the schedule/event/run sheets on the shared capture sheet) and `.uvs-skel` — so the shared Mozaik
   scaffold, `.stag`, `.segtab` and the `sp-*` / `wo-close-cta` rules keep their skin elsewhere
   (bible rule 13). Ranking (§3.4): heroes are frameless halos (PageHero `art`); day rows with a slot,
   session cards, the block/HR/cross-load cards, the sport tiles, the log form and the kcal door are
   `.glass` (ONE `--c` each); stat cells, the segmented control, chips, week cells, event rows, archived
   plans and everything inside a glass are flat; free days and empty states dashed (`.uv-empty`). */

/* ── the page shell: the dark ground shows through; the halo's second hue per page ── */
.uvs-page.mz-page { background: transparent; }
.uvs-page .mz-page-body { padding: 2px 16px 24px; }
.uvs-sport .uv-hero { --c2: var(--dv-amber); }
.uvs-futas .uv-hero { --c2: var(--dv-lav); }
.uvs-page .mz-principle {
  margin: 22px 10px 0; font-size: 12px; font-weight: 400; line-height: 1.55; text-align: center; color: var(--text-muted);
}
/* the header action (`＋ Log` / `＋ Új terv`): a lit pill in the page accent */
.uvs-page .mz-page-head .mz-pgact.uvs-act {
  margin-left: auto; min-height: 40px; padding: 8px 15px; border: 0; border-radius: 999px;
  font: 700 12.5px/1.2 var(--ff-body); color: var(--page, #191614); background: var(--c);
  box-shadow: 0 0 14px color-mix(in srgb, var(--c) 55%, transparent);
}
.uvs-page .mz-pgact.uvs-act:focus-visible { outline: 2px solid var(--c); outline-offset: 3px; }

/* the stat strip: three flat cells */
.uvs-page .mz-statstrip.uvs-strip { display: grid; grid-template-columns: repeat(3, minmax(0, 1fr)); gap: 8px; }
.uvs-page .uvs-strip .mz-statcell {
  min-width: 0; padding: 10px 6px; border: 0; border-radius: 14px; text-align: center;
  background: rgba(245, 239, 230, 0.04); box-shadow: inset 0 0 0 1px var(--divider);
}
.uvs-page .uvs-strip .mz-statcell b {
  font: 600 20px/1.15 var(--ff-display); letter-spacing: -0.6px; color: var(--text-primary);
  overflow: hidden; text-overflow: ellipsis; white-space: nowrap;
}
.uvs-page .uvs-strip .mz-statcell small { display: block; margin-top: 2px; font-size: 10px; line-height: 1.3; color: var(--text-muted); }

/* the segmented control: one flat pill; the active segment filled in the page accent + glow */
.uvs-page .segtabs.uvs-seg {
  display: flex; gap: 0; width: fit-content; max-width: 100%; margin: 14px auto 4px; padding: 3px;
  border-radius: 999px; background: rgba(245, 239, 230, 0.05); box-shadow: inset 0 0 0 1px var(--divider);
}
.uvs-page .uvs-seg .segtab {
  flex: 0 1 auto; min-width: 0; min-height: 40px; padding: 8px 15px; border: 0; border-radius: 999px;
  background: none; font: 600 12.5px/1.2 var(--ff-body); color: var(--text-secondary);
  overflow: hidden; text-overflow: ellipsis; white-space: nowrap;
}
.uvs-page .uvs-seg .segtab[aria-pressed='true'] {
  font-weight: 700; color: var(--page, #191614); background: var(--c);
  box-shadow: 0 0 12px color-mix(in srgb, var(--c) 45%, transparent);
}
.uvs-page .uvs-seg .segtab:focus-visible { outline: 2px solid var(--c); outline-offset: 2px; }

/* sections, eyebrows, lists */
.uvs-page .uvs-sec { padding-top: 10px; }
.uvs-page .uvs-sechead { display: flex; align-items: center; justify-content: space-between; gap: 10px; padding: 8px 2px; }
.uvs-page .uvs-list { display: grid; gap: 8px; }
.uvs-page .uvs-flatbtn {
  min-height: 36px; padding: 6px 12px; border: 0; border-radius: 999px; cursor: pointer;
  font: 600 12px/1.2 var(--ff-body); color: var(--text-secondary);
  background: rgba(245, 239, 230, 0.05); box-shadow: inset 0 0 0 1px var(--divider);
}

/* the type tag (`.stag`) on the glass: a small flat pill tinted by the sport */
:is(.uvs-page, .uvs-log) .stag {
  --tc: var(--dv-rose);
  display: inline-flex; align-items: center; padding: 2px 7px; border-radius: 999px;
  font: 700 9px/1.2 var(--ff-body); letter-spacing: 0.8px; text-transform: uppercase;
  color: color-mix(in srgb, var(--tc) 78%, var(--text-primary));
  background: color-mix(in srgb, var(--tc) 16%, transparent);
  box-shadow: inset 0 0 0 1px color-mix(in srgb, var(--tc) 30%, transparent);
}
:is(.uvs-page, .uvs-log) .stag-run { --tc: var(--dv-sky); }
:is(.uvs-page, .uvs-log) .stag-cross { --tc: var(--dv-coral); }
:is(.uvs-page, .uvs-log) .stag-trx { --tc: var(--dv-lav); }

/* lit pill (Logold/Naplózd/Pótold, the empty-state CTA) + the lit primary */
.uvs-pill {
  display: inline-flex; align-items: center; justify-content: center; gap: 6px; min-height: 40px; padding: 8px 15px;
  border: 0; border-radius: 999px; cursor: pointer; white-space: nowrap;
  font: 700 12.5px/1.2 var(--ff-body); color: var(--page, #191614); background: var(--c, var(--dv-rose));
  box-shadow: 0 0 14px color-mix(in srgb, var(--c, var(--dv-rose)) 55%, transparent);
}
.uvs-primary {
  display: flex; align-items: center; justify-content: center; gap: 8px; width: 100%; min-height: 52px;
  padding: 14px 16px; border: 0; border-radius: 18px; cursor: pointer;
  font: 700 15px/1.2 var(--ff-body); color: var(--page, #191614);
  background: linear-gradient(135deg, color-mix(in srgb, var(--c) 70%, #fff), var(--c));
  box-shadow: 0 0 18px -2px color-mix(in srgb, var(--c) 60%, transparent), inset 0 1px 0 rgba(255, 255, 255, 0.45);
}
.uvs-primary .t-ico { filter: none; }
.uvs-primary:disabled { opacity: 0.45; box-shadow: none; }
/* closing a block ends it — the warning tone stays (flat, coral outline), never the lit primary */
.uvs-primary.is-warn { color: #FFB39C; background: rgba(255, 126, 92, 0.07); box-shadow: inset 0 0 0 1px rgba(255, 126, 92, 0.35); }
:is(.uvs-pill, .uvs-primary):focus-visible { outline: 2px solid color-mix(in srgb, var(--c) 70%, var(--text-primary)); outline-offset: 3px; }
/* a flat field (builder inputs, sheet fields) */
.uvs-inp {
  display: block; width: 100%; min-width: 0; padding: 11px 13px; border: 0; border-radius: 13px;
  font: 400 16px/1.3 var(--ff-body); color: var(--text-primary); color-scheme: dark;
  background: rgba(245, 239, 230, 0.05); box-shadow: inset 0 0 0 1px var(--divider);
}
.uvs-inp::placeholder { color: var(--text-muted); }
.uvs-inp:focus-visible { outline: 2px solid color-mix(in srgb, var(--c, var(--dv-sky)) 70%, var(--text-primary)); outline-offset: 2px; }

/* empty/free states: dashed, no glass */
:is(.uvs-page, .uvs-log) .uvs-ghost {
  display: grid; justify-items: center; gap: 8px; margin: 12px 0 0; padding: 22px 18px; border-radius: 22px; text-align: center;
}
:is(.uvs-page, .uvs-log) .uvs-ghost p { margin: 0; font-size: 14px; line-height: 1.5; color: var(--text-secondary); }
:is(.uvs-page, .uvs-log) .uvs-ghost .t-ico { opacity: 0.9; }
.uvs-page p.uvs-ghost { display: block; margin: 16px; font-size: 14px; color: var(--text-secondary); }
.uvs-page .uvs-dashadd {
  display: flex; align-items: center; justify-content: center; width: 100%; min-height: 48px; margin-top: 12px; padding: 14px;
  border-radius: 20px; cursor: pointer; font: 600 14px/1.2 var(--ff-body);
  color: color-mix(in srgb, var(--c) 70%, var(--text-primary));
}
.uvs-page .uvs-dashadd:focus-visible { outline: 2px solid var(--c); outline-offset: 2px; }

/* ── Sport · Heti terv: rose glass day rows; a free day dashed ── */
.uvs-sport .spw-day { display: flex; align-items: flex-start; gap: 12px; margin: 0; padding: 11px 12px; border-radius: 20px; }
/* `.spw-day.today` (two classes) outranks `.glass` on body and shadow, and its ::before stripe
   would replace the gradient frame — restate both (bible rules 1 + 11). */
.uvs-sport .spw-day.has.glass {
  --c: var(--dv-rose);
  position: relative; overflow: hidden;
  background:
    radial-gradient(120% 90% at 0% 0%, color-mix(in srgb, var(--c) 22%, transparent), transparent 62%),
    linear-gradient(160deg, rgba(52, 46, 41, 0.72), rgba(30, 27, 24, 0.60));
  box-shadow:
    0 16px 30px -16px rgba(0, 0, 0, 0.75),
    0 0 26px -6px color-mix(in srgb, var(--c) 30%, transparent),
    inset 0 1px 0 rgba(255, 244, 230, 0.10),
    inset 0 -14px 26px -18px color-mix(in srgb, var(--c) 55%, transparent);
}
.uvs-sport .spw-day.has.glass.today::before {
  inset: 0; width: auto;
  background: linear-gradient(145deg,
    color-mix(in srgb, var(--c) 80%, transparent) 0%,
