.uvs-sport .spw-l2 { margin-top: 2px; font-size: 11.5px; line-height: 1.4; color: var(--text-secondary); overflow-wrap: anywhere; }
.uvs-sport .spw-ma, .uvs-sport .spw-one {
  padding: 2px 7px; border-radius: 999px; font: 700 9px/1.2 var(--ff-body); letter-spacing: 0.8px;
}
.uvs-sport .spw-ma { color: var(--page, #191614); background: var(--c); box-shadow: 0 0 10px color-mix(in srgb, var(--c) 50%, transparent); }
.uvs-sport .spw-one { color: var(--text-secondary); background: rgba(245, 239, 230, 0.1); }
.uvs-sport .spw-logbtn {
  flex: none; min-height: 40px; margin: 0; padding: 8px 4px 8px 10px; border: 0; background: none; cursor: pointer; white-space: nowrap;
  font: 600 12.5px/1.2 var(--ff-body); color: color-mix(in srgb, var(--c) 70%, var(--text-primary));
}
.uvs-sport .spw-logbtn:focus-visible { outline: 2px solid var(--c); outline-offset: 2px; border-radius: 10px; }
/* the independence note: a flat cell */
.uvs-sport .uvs-note { display: flex; align-items: flex-start; gap: 10px; margin-top: 12px; padding: 11px 12px; border-radius: 16px; }
.uvs-sport .uvs-note p { margin: 4px 0 0; font-size: 12.5px; line-height: 1.5; color: var(--text-secondary); }
/* one-off events: flat rows with a flat delete chip */
.uvs-page .uvs-evl { display: grid; gap: 6px; }
.uvs-page .uvs-ev { display: flex; align-items: center; gap: 10px; padding: 10px 12px; border-radius: 14px; }
.uvs-page .uvs-ev-copy { flex: 1; min-width: 0; }
.uvs-page .uvs-ev-copy strong { display: block; font-size: 13.5px; font-weight: 600; color: var(--text-primary); }
.uvs-page .uvs-ev-copy small { display: block; margin-top: 1px; font-size: 11px; color: var(--text-muted); overflow-wrap: anywhere; }
.uvs-page .uvs-evdel {
  flex: none; min-height: 36px; padding: 4px 11px; border: 0; border-radius: 999px; cursor: pointer;
  font: 600 11px/1.2 var(--ff-body); color: var(--text-muted);
  background: rgba(245, 239, 230, 0.05); box-shadow: inset 0 0 0 1px var(--divider);
}

/* ── Sport · Napló: the rose session glass card ── */
.uvs-page .uvs-ssc.glass { padding: 13px 14px; border-radius: 22px; }
.uvs-page .uvs-ssc-top { display: flex; align-items: flex-start; justify-content: space-between; gap: 10px; }
.uvs-page .uvs-ssc-l { min-width: 0; }
.uvs-page .uvs-tagl {
  display: flex; flex-wrap: wrap; align-items: center; gap: 6px 8px;
  font: 600 9.5px/1.2 var(--ff-body); letter-spacing: 1.2px; color: color-mix(in srgb, var(--c) 75%, var(--text-primary));
}
.uvs-page .uvs-tagl em { font-style: normal; color: var(--text-muted); }
.uvs-page .uvs-skv { display: flex; flex-wrap: wrap; gap: 4px 14px; margin-top: 6px; font-size: 12px; color: var(--text-secondary); font-variant-numeric: tabular-nums; }
.uvs-page .uvs-skv b { font-weight: 600; color: var(--text-primary); }
.uvs-page .uvs-rpe { flex: none; text-align: right; }
.uvs-page .uvs-rpe b {
  display: block; font: 300 34px/1 var(--ff-display); letter-spacing: -1.5px; font-variant-numeric: tabular-nums;
  color: var(--rc); text-shadow: 0 0 14px color-mix(in srgb, var(--rc) 45%, transparent);
}
.uvs-page .uvs-rpe small { font-size: 9.5px; letter-spacing: 1px; color: var(--text-muted); }
.uvs-page .uvs-mbs { display: grid; gap: 8px; margin-top: 10px; }
.uvs-page .uvs-mb { display: grid; grid-template-columns: 90px minmax(0, 1fr) 26px; align-items: center; gap: 8px; font-size: 11.5px; color: var(--text-secondary); }
.uvs-page .uvs-mb em { font-style: normal; font-weight: 600; text-align: right; color: var(--text-primary); font-variant-numeric: tabular-nums; }
.uvs-page .uvs-q { margin: 10px 0 0; font-size: 14px; line-height: 1.45; color: var(--text-primary); overflow-wrap: anywhere; }

/* ── the cross-load glass card (Sport lavender, Futás sky): flat lines inside ── */
.uvs-page .uvs-xl.glass { padding: 14px; border-radius: 22px; }
.uvs-page .uvs-chead { display: flex; align-items: center; gap: 10px; }
.uvs-page .uvs-chead > div { min-width: 0; }
.uvs-page .uvs-chead .uv-eyebrow { color: color-mix(in srgb, var(--c) 75%, var(--text-primary)); }
.uvs-page .uvs-xl-intro { margin: 4px 0 0; font-size: 13px; line-height: 1.5; color: var(--text-secondary); }
.uvs-page .uvs-xl-tools { margin-top: 10px; }
.uvs-page .uvs-xl-tools .toolchip { max-width: 100%; overflow: hidden; text-overflow: ellipsis; }
.uvs-page .uvs-xl-lines { display: grid; gap: 6px; margin-top: 10px; }
.uvs-page .uvs-xrow {
  display: flex; align-items: flex-start; gap: 10px; padding: 9px 10px; border-radius: 12px;
  font-size: 12.5px; line-height: 1.4; background: rgba(245, 239, 230, 0.04);
}
.uvs-page .uvs-xrow.is-warn {
  background: color-mix(in srgb, var(--dv-amber) 8%, rgba(245, 239, 230, 0.02));
  box-shadow: inset 2px 0 0 var(--dv-amber);
}
.uvs-page .uvs-xrow-body { flex: 1; min-width: 0; }
.uvs-page .uvs-xrow-top { display: flex; align-items: baseline; justify-content: space-between; gap: 8px; }
.uvs-page .uvs-xrow-sys { font: 600 9.5px/1.2 var(--ff-body); letter-spacing: 1.2px; color: var(--text-muted); }
.uvs-page .uvs-xrow-imp { font-size: 11.5px; font-weight: 700; white-space: nowrap; color: var(--dv-coral); }
.uvs-page .uvs-xrow.is-warn .uvs-xrow-imp { color: var(--dv-amber); }
.uvs-page .uvs-xrow strong { display: block; margin-top: 2px; font-size: 13px; font-weight: 600; color: var(--text-primary); }
.uvs-page .uvs-xrow p { margin: 4px 0 0; color: var(--text-secondary); }
.uvs-page .uvs-xrow-body > p:first-child { margin-top: 0; }
.uvs-page .uvs-xrow p strong { display: inline; margin: 0; }

/* ── Futás · E heti edzés: the sky block card + its week strip ── */
.uvs-page .uvs-blk.glass { display: block; padding: 14px; border-radius: 22px; }
.uvs-page .uvs-blk strong { display: block; margin-top: 2px; font-size: 18px; font-weight: 600; letter-spacing: -0.4px; color: var(--text-primary); }
.uvs-page .uvs-blk small { display: block; margin-top: 2px; font-size: 12px; color: var(--text-secondary); }
.uvs-page .uvs-wkstrip { display: grid; gap: 4px; margin-top: 12px; }
.uvs-page .uvs-wkstrip i {
  min-width: 0; height: 30px; border-radius: 8px; display: grid; place-items: center;
  font: 600 10.5px/1 var(--ff-body); font-style: normal; font-variant-numeric: tabular-nums; color: var(--text-muted);
  background: rgba(245, 239, 230, 0.05); box-shadow: inset 0 0 0 1px var(--divider);
}
.uvs-page .uvs-wkstrip i.is-past {
  color: color-mix(in srgb, var(--dv-sky) 45%, #fff);
  background: color-mix(in srgb, var(--dv-sky) 22%, transparent);
  box-shadow: inset 0 0 0 1px color-mix(in srgb, var(--dv-sky) 40%, transparent);
}
.uvs-page .uvs-wkstrip i.is-now {
  color: var(--page, #191614); background: var(--dv-sky);
  box-shadow: 0 0 12px color-mix(in srgb, var(--dv-sky) 60%, transparent);
}
/* the prescribed / logged run glass card */
.uvs-page .uvs-rsc.glass { display: block; padding: 13px 14px; border-radius: 22px; }
.uvs-page .uvs-rsc-top { display: flex; flex-wrap: wrap; align-items: center; justify-content: space-between; gap: 8px; }
.uvs-page .uvs-rsc-name { display: flex; flex-wrap: wrap; align-items: center; gap: 8px; margin-top: 4px; }
.uvs-page .uvs-rsc-name strong { font-size: 16.5px; font-weight: 600; color: var(--text-primary); }
.uvs-page .uvs-rsc .uvs-tagl strong { font: 600 13px/1.2 var(--ff-body); letter-spacing: 0; color: var(--text-primary); }
.uvs-page .uvs-tag { padding: 2px 7px; border-radius: 999px; font: 700 9px/1.2 var(--ff-body); letter-spacing: 0.8px; }
.uvs-page .uvs-tag.is-lit { color: var(--page, #191614); background: var(--c); box-shadow: 0 0 10px color-mix(in srgb, var(--c) 50%, transparent); }
.uvs-page .uvs-chips { display: flex; flex-wrap: wrap; gap: 6px; margin-top: 10px; }
.uvs-page .uvs-chip {
  display: inline-flex; align-items: center; gap: 5px; min-width: 0; max-width: 100%; padding: 6px 11px; border: 0; border-radius: 999px;
  font: 600 12px/1.2 var(--ff-body); color: var(--text-secondary); overflow-wrap: anywhere;
  background: rgba(245, 239, 230, 0.05); box-shadow: inset 0 0 0 1px var(--divider);
}
.uvs-page .uvs-chip .t-ico { width: 16px; height: 16px; filter: none; }
.uvs-page .uvs-chip.is-work {
  color: color-mix(in srgb, var(--dv-sky) 75%, var(--text-primary));
  background: color-mix(in srgb, var(--dv-sky) 12%, transparent);
  box-shadow: inset 0 0 0 1px color-mix(in srgb, var(--dv-sky) 30%, transparent);
}
.uvs-page .uvs-chip.is-warm {
  color: color-mix(in srgb, var(--dv-amber) 80%, var(--text-primary));
  box-shadow: inset 0 0 0 1px color-mix(in srgb, var(--dv-amber) 28%, transparent);
}
.uvs-page .uvs-chip.is-rpe {
  padding: 3px 9px; font-size: 10.5px; letter-spacing: 0.4px; font-variant-numeric: tabular-nums;
  color: color-mix(in srgb, var(--dv-amber) 80%, var(--text-primary));
  box-shadow: inset 0 0 0 1px color-mix(in srgb, var(--dv-amber) 35%, transparent);
}
.uvs-page .uvs-chip.is-rpe.is-hot {
  color: color-mix(in srgb, var(--dv-coral) 80%, var(--text-primary));
  background: color-mix(in srgb, var(--dv-coral) 10%, transparent);
  box-shadow: inset 0 0 0 1px color-mix(in srgb, var(--dv-coral) 35%, transparent);
}
.uvs-page .uvs-rsc-cta { display: flex; justify-content: flex-end; margin-top: 10px; }
.uvs-page .uvs-ok {
  display: inline-flex; align-items: center; gap: 4px;
  font: 700 10px/1 var(--ff-body); letter-spacing: 1px; color: color-mix(in srgb, var(--dv-sage) 60%, #fff);
}
.uvs-page .uvs-ok .t-ico { filter: none; }
.uvs-page .uvs-later { font: 600 11px/1.2 var(--ff-body); letter-spacing: 1px; text-transform: uppercase; color: var(--text-muted); }
.uvs-page .uvs-rsc-note { margin: 8px 0 0; font-size: 13px; line-height: 1.5; color: var(--text-secondary); overflow-wrap: anywhere; }

/* ── Futás · Napló: the heart-rate recovery glass card (lower = better) ── */
.uvs-page .uvs-hrc.glass { display: block; margin-bottom: 4px; padding: 14px; border-radius: 22px; }
.uvs-page .uvs-hr-delta b { display: block; margin-top: 8px; font: 600 26px/1.1 var(--ff-display); letter-spacing: -0.5px; font-variant-numeric: tabular-nums; }
.uvs-page .uvs-hr-delta.is-better b { color: color-mix(in srgb, var(--dv-sky) 45%, #fff); }
.uvs-page .uvs-hr-delta.is-worse b { color: var(--dv-amber); }
.uvs-page .uvs-hr-line { display: block; width: 100%; height: auto; margin-top: 6px; overflow: visible; }
.uvs-page .uvs-hr-line path {
  fill: none; stroke: var(--c); stroke-width: 3; stroke-linecap: round; stroke-linejoin: round;
  filter: drop-shadow(0 0 6px var(--c));
}
.uvs-page .uvs-hr-line circle { fill: var(--c); }
.uvs-page .uvs-hr-line circle.is-last { fill: color-mix(in srgb, var(--dv-sky) 45%, #fff); }
.uvs-page .uvs-hr-cols { display: flex; justify-content: space-between; gap: 4px; margin-top: 6px; text-align: center; }
.uvs-page .uvs-hr-cols > div { min-width: 0; flex: 0 1 auto; }
.uvs-page .uvs-hr-cols b { display: block; font: 600 12px/1.2 var(--ff-body); font-variant-numeric: tabular-nums; color: color-mix(in srgb, var(--c) 70%, var(--text-primary)); }
.uvs-page .uvs-hr-cols small { display: block; margin-top: 1px; font-size: 9.5px; color: var(--text-muted); overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }
.uvs-page .uvs-fnote { margin: 10px 0 0; font-size: 11px; line-height: 1.45; color: var(--text-muted); }

/* ── Futás · Tervek: glass plan cards (active sky, planned lavender), archived flat rows ── */
.uvs-page .uvs-plan.glass { display: block; padding: 13px 14px; border-radius: 22px; cursor: pointer; }
.uvs-page .uvs-plan-top { display: flex; align-items: flex-start; justify-content: space-between; gap: 10px; }
.uvs-page .uvs-plan-copy { flex: 1; min-width: 0; }
.uvs-page .uvs-plan-copy strong { display: block; margin-top: 2px; font-size: 16.5px; font-weight: 600; color: var(--text-primary); overflow-wrap: anywhere; }
.uvs-page .uvs-plan-copy small { display: block; margin-top: 2px; font-size: 12px; color: var(--text-secondary); }
.uvs-page .uvs-plan-foot { display: flex; align-items: center; justify-content: space-between; gap: 8px; margin-top: 10px; }
.uvs-page .uvs-plan-go { font: 600 12px/1.2 var(--ff-body); color: color-mix(in srgb, var(--c) 70%, var(--text-primary)); }
.uvs-page .uvs-status {
  flex: none; padding: 3px 9px; border-radius: 999px;
  font: 700 9.5px/1.2 var(--ff-body); letter-spacing: 1px; text-transform: uppercase; color: var(--text-secondary);
  background: rgba(245, 239, 230, 0.06); box-shadow: inset 0 0 0 1px var(--divider);
}
.uvs-page .uvs-status.is-active { color: var(--page, #191614); background: var(--dv-sky); box-shadow: 0 0 10px color-mix(in srgb, var(--dv-sky) 50%, transparent); }
.uvs-page .uvs-status.is-planned {
  color: color-mix(in srgb, var(--dv-lav) 80%, var(--text-primary));
  box-shadow: inset 0 0 0 1px color-mix(in srgb, var(--dv-lav) 40%, transparent);
}
.uvs-page .uvs-arch { display: block; padding: 11px 14px; border-radius: 18px; cursor: pointer; }
.uvs-page .uvs-arch .uvs-plan-top { align-items: center; }
.uvs-page .uvs-arch .uvs-plan-copy strong { font-size: 13.5px; font-weight: 500; }
.uvs-page .uvs-arch-sum { margin: 8px 0 0; font-size: 12.5px; line-height: 1.5; color: var(--text-secondary); }
.uvs-page :is(.uvs-plan, .uvs-arch):focus-visible { outline: 2px solid var(--dv-sky); outline-offset: 2px; }

/* ── Futás block builder: glass back + ⋯, the sky glass form, flat rows inside, lit primary ── */
.uvs-rbb .uvs-rbb-head { padding: 10px 20px; }
.uvs-rbb .uvs-rbb-head p { display: flex; flex-wrap: wrap; align-items: center; gap: 6px 10px; margin: 4px 0 0; font-size: 13px; color: var(--text-secondary); }
.uvs-rbb .uvs-save { display: inline-flex; align-items: center; gap: 4px; font-size: 11px; color: var(--text-muted); }
.uvs-rbb .uvs-save.is-saved { color: color-mix(in srgb, var(--dv-sage) 60%, #fff); }
.uvs-rbb .uvs-save .t-ico { filter: none; }
.uvs-rbb .uvs-bform.glass { display: grid; gap: 12px; margin: 0 16px; padding: 14px; border-radius: 22px; }
.uvs-rbb .uvs-field { display: grid; gap: 6px; min-width: 0; }
.uvs-rbb .uvs-inp.is-title { font: 600 20px/1.2 var(--ff-display); letter-spacing: -0.4px; }
.uvs-rbb .uvs-weeks { display: flex; flex-wrap: wrap; gap: 6px; }
.uvs-rbb .uvs-wk {
  min-width: 40px; min-height: 40px; padding: 8px 10px; border: 0; border-radius: 12px; cursor: pointer;
  font: 600 12px/1 var(--ff-body); font-variant-numeric: tabular-nums; color: var(--text-secondary);
  background: rgba(245, 239, 230, 0.05); box-shadow: inset 0 0 0 1px var(--divider);
}
.uvs-rbb .uvs-wk[aria-pressed='true'] { color: var(--page, #191614); background: var(--c); box-shadow: 0 0 12px color-mix(in srgb, var(--c) 50%, transparent); }
.uvs-rbb .uvs-wk.is-add {
  background: transparent; box-shadow: none; border: 1.5px dashed color-mix(in srgb, var(--c) 45%, transparent);
  color: color-mix(in srgb, var(--c) 70%, var(--text-primary));
}
.uvs-rbb .uvs-wk:focus-visible { outline: 2px solid var(--c); outline-offset: 2px; }
.uvs-rbb .uvs-wked { display: grid; gap: 8px; }
.uvs-rbb .uvs-wked-none { margin: 0; padding: 14px; border-radius: 14px; text-align: center; font-size: 13px; color: var(--text-secondary); }
.uvs-rbb .uvs-wkrow {
  display: grid; gap: 8px; min-width: 0; padding: 10px 12px; border-radius: 14px;
  background: rgba(245, 239, 230, 0.04); box-shadow: inset 0 0 0 1px var(--divider);
}
.uvs-rbb .uvs-wkrow-title { font: 600 13px/1.2 var(--ff-body); color: var(--text-primary); }
.uvs-rbb .uvs-hint { font: 600 9.5px/1.2 var(--ff-body); letter-spacing: 1.2px; text-transform: uppercase; color: var(--text-muted); }
.uvs-rbb .uvs-wkrow-time { display: flex; align-items: center; justify-content: space-between; gap: 10px; }
.uvs-rbb .uvs-wkrow-time .uvs-inp {
  width: auto; padding: 7px 10px; font-size: 15px; font-weight: 600; font-variant-numeric: tabular-nums;
  color: color-mix(in srgb, var(--c) 75%, var(--text-primary));
}
.uvs-rbb .uvs-wkrow-rule { height: 1px; margin: 2px 0; background: var(--divider); }
/* two ± steppers never fit side by side in the glass at phone width — stack them */
.uvs-rbb .uvs-wked-steps { display: grid; grid-template-columns: minmax(0, 1fr); gap: 8px; }
.uvs-rbb .uvs-chips { margin-top: 0; }
.uvs-rbb .uvs-chip button { padding: 0; border: 0; background: none; font: inherit; color: inherit; cursor: pointer; min-height: 28px; }
.uvs-rbb .uvs-chip .uvs-chip-x { color: var(--text-muted); opacity: 0.8; }
.uvs-rbb .uvs-chip.is-add {
  cursor: pointer; background: transparent; box-shadow: none;
  border: 1.5px dashed color-mix(in srgb, var(--c) 45%, transparent); color: color-mix(in srgb, var(--c) 70%, var(--text-primary));
}
/* WeekdayGrid + CompactStepper are shared train components that carry INLINE styles, so the
   flat skin inside the builder needs !important to reach them (scoped to `.uvs-rbb` only). */
.uvs-rbb [role='group'][aria-label='Nap'] button {
  min-height: 36px; border: 0 !important; border-radius: 10px;
  color: var(--text-muted) !important; background: rgba(245, 239, 230, 0.04) !important;
  box-shadow: inset 0 0 0 1px var(--divider);
}
.uvs-rbb [role='group'][aria-label='Nap'] button[aria-pressed='true'] {
  color: var(--page, #191614) !important; background: var(--c) !important;
  box-shadow: 0 0 12px color-mix(in srgb, var(--c) 50%, transparent);
}
.uvs-rbb .uvs-wked-steps > div {
  min-width: 0; border-radius: 14px; clip-path: none !important;
  background: rgba(245, 239, 230, 0.04) !important; box-shadow: inset 0 0 0 1px var(--divider);
}
.uvs-rbb .uvs-wked-steps > div > button {
  border: 0 !important; border-radius: 50%; color: color-mix(in srgb, var(--c) 70%, var(--text-primary)) !important;
  background: rgba(245, 239, 230, 0.06) !important; box-shadow: inset 0 0 0 1px var(--divider);
}
.uvs-rbb .uvs-wked-steps input { color: var(--text-primary) !important; font-weight: 300 !important; }
/* the ⋯ menu: a glass round button over a glass menu card (rule 1: restate the anchor) */
.uvs-rbb .uvs-menu { position: relative; margin-left: auto; }
.uvs-rbb .uvs-menubtn.glass.is-round {
  --c: var(--text-muted);
  width: 40px; height: 40px; padding: 0; border: 0; display: grid; place-items: center; cursor: pointer;
  font-size: 18px; line-height: 1; color: var(--text-secondary);
}
.uvs-rbb .uvs-menubtn:focus-visible { outline: 2px solid var(--dv-sky); outline-offset: 2px; }
.uvs-rbb .uvs-menucard.glass {
  position: absolute; right: 0; top: 48px; z-index: 20; min-width: 200px;
  display: grid; gap: 6px; padding: 8px; border-radius: 20px;
}
.uvs-rbb .uvs-menucard button {
  display: flex; align-items: center; gap: 12px; min-height: 48px; padding: 8px 12px; border: 0; border-radius: 14px; cursor: pointer;
  text-align: left; font: 600 14px/1.2 var(--ff-body); color: var(--text-primary);
  background: rgba(245, 239, 230, 0.04); box-shadow: inset 0 0 0 1px var(--divider);
}
.uvs-rbb .uvs-menucard button .t-ico { filter: none; }
.uvs-rbb .uvs-menucard button.is-warn strong { color: color-mix(in srgb, var(--dv-coral) 60%, #fff); }
.uvs-rbb .uvs-menucard button:focus-visible { outline: 2px solid var(--dv-sky); outline-offset: 2px; }
.uvs-rbb .uvs-rbb-cta { display: grid; gap: 8px; padding: 16px 16px 32px; }

/* ── /train/sport/log: glass tiles → the rose glass form, sage kcal door, sticky lit save ── */
.sp-page.uvs-log { --c: var(--dv-rose); padding: calc(12px + env(safe-area-inset-top)) 16px calc(16px + env(safe-area-inset-bottom)); }
.uvs-log .sp-head { gap: 12px; margin-bottom: 12px; }
/* `.sp-head > button` outranks `.glass` on body and shadow — restate the glass (rule 11) */
.uvs-log .sp-head > button.glass.is-round {
  --c: var(--text-muted);
  width: 38px; height: 38px; padding: 0; border: 0; display: grid; place-items: center;
  font-size: 22px; line-height: 1; color: var(--text-secondary);
  background:
    radial-gradient(120% 90% at 0% 0%, color-mix(in srgb, var(--c) 22%, transparent), transparent 62%),
    linear-gradient(160deg, rgba(52, 46, 41, 0.72), rgba(30, 27, 24, 0.60));
  box-shadow: 0 16px 30px -16px rgba(0, 0, 0, 0.75), inset 0 1px 0 rgba(255, 244, 230, 0.10);
}
.uvs-log .sp-head > button:focus-visible { outline: 2px solid var(--dv-rose); outline-offset: 2px; }
.uvs-log .sp-head small { font: 600 9.5px/1.2 var(--ff-body); letter-spacing: 1.4px; color: color-mix(in srgb, var(--c) 75%, var(--text-primary)); }
.uvs-log .sp-head strong { margin-top: 2px; font: 600 26px/1.15 var(--ff-display); letter-spacing: -0.9px; color: var(--text-primary); overflow-wrap: anywhere; }
.uvs-log .sp-head-art {
  width: auto; height: auto; border-radius: 0; background: none; box-shadow: none;
  filter: drop-shadow(0 8px 10px rgba(0, 0, 0, 0.5)) drop-shadow(0 0 14px color-mix(in srgb, var(--c) 45%, transparent));
}
.uvs-log .sp-lead { font-size: 13.5px; line-height: 1.5; color: var(--text-secondary); }
.uvs-log .sp-grid { gap: 10px; }
.uvs-log .sp-tile.glass {
  display: flex; flex-direction: column; align-items: center; gap: 6px; min-width: 0;
  padding: 14px 6px 12px; border: 0; border-radius: 20px; cursor: pointer;
}
.uvs-log .sp-tile strong { font: 600 12.5px/1.25 var(--ff-body); text-align: center; color: var(--text-primary); overflow-wrap: anywhere; }
.uvs-log .sp-tile small { color: var(--text-muted); }
.uvs-log .sp-tile:focus-visible { outline: 2px solid var(--c); outline-offset: 2px; }
.uvs-log .sp-modes {
  align-self: center; display: flex; gap: 0; max-width: 100%; margin: 0 auto 14px; padding: 3px;
  border-radius: 999px; background: rgba(245, 239, 230, 0.05); box-shadow: inset 0 0 0 1px var(--divider);
}
.uvs-log .sp-modes button {
  flex: 0 1 auto; min-width: 0; min-height: 40px; padding: 8px 18px; border-radius: 999px;
  font: 600 12.5px/1.2 var(--ff-body); color: var(--text-secondary); background: none; box-shadow: none;
}
.uvs-log .sp-modes button[aria-pressed='true'] {
  font-weight: 700; color: var(--page, #191614); background: var(--c);
  box-shadow: 0 0 12px color-mix(in srgb, var(--c) 45%, transparent);
}
.uvs-log .sp-form.glass { display: grid; gap: 14px; padding: 14px; border-radius: 22px; }
.uvs-log .sp-field label {
  margin-bottom: 7px; font: 600 9.5px/1.2 var(--ff-body); letter-spacing: 1.3px; text-transform: uppercase; color: var(--text-muted);
}
.uvs-log .sp-field label b {
  font: 600 14px/1 var(--ff-body); letter-spacing: 0; text-transform: none; color: color-mix(in srgb, var(--c) 60%, var(--text-primary));
}
.uvs-log .sp-number,
.uvs-log .sp-field[data-sp-key='minutes'] .sp-number {
  grid-template-columns: 40px 1fr auto 40px; padding: 6px; border: 0; border-radius: 14px;
  background: rgba(245, 239, 230, 0.04); box-shadow: inset 0 0 0 1px var(--divider);
}
.uvs-log .sp-field[data-sp-key='minutes'] .sp-number { box-shadow: inset 0 0 0 1px color-mix(in srgb, var(--c) 32%, transparent); }
.uvs-log .sp-number button {
  width: 40px; height: 40px; border-radius: 50%; font-size: 18px;
  color: color-mix(in srgb, var(--c) 70%, var(--text-primary));
  background: rgba(245, 239, 230, 0.06); box-shadow: inset 0 0 0 1px var(--divider);
}
.uvs-log .sp-number input { font-weight: 300; color: var(--text-primary); color-scheme: dark; }
.uvs-log .sp-number > span { color: var(--text-muted); }
.uvs-log .sp-chips button {
  min-height: 40px; padding: 8px 14px; border-radius: 999px; font: 600 12.5px/1.2 var(--ff-body);
  color: var(--text-secondary); background: rgba(245, 239, 230, 0.05); box-shadow: inset 0 0 0 1px var(--divider);
}
.uvs-log .sp-chips button[aria-pressed='true'] {
  font-weight: 700; color: var(--page, #191614); background: var(--c);
  box-shadow: 0 0 12px color-mix(in srgb, var(--c) 50%, transparent);
}
.uvs-log .sp-text {
  border-radius: 13px; font-size: 16px; color: var(--text-primary); color-scheme: dark;
  background: rgba(245, 239, 230, 0.05); box-shadow: inset 0 0 0 1px var(--divider);
}
.uvs-log .sp-text::placeholder { color: var(--text-muted); }
.uvs-log .sp-range { accent-color: var(--dv-coral); }
.uvs-log :is(.sp-modes, .sp-chips, .sp-number) button:focus-visible,
.uvs-log :is(.sp-text, .sp-range, .sp-number input):focus-visible { outline: 2px solid color-mix(in srgb, var(--c) 70%, var(--text-primary)); outline-offset: 2px; }
.uvs-log .sp-kcal.glass {
  grid-template-columns: 40px 1fr auto; gap: 4px 12px; margin: 14px 0 16px; padding: 12px 14px; border: 0; border-radius: 20px;
}
.uvs-log .sp-kcal-copy { grid-area: 1 / 2 / 3 / 3; align-self: center; }
.uvs-log .sp-kcal-copy strong { font-size: 13px; color: var(--text-primary); }
.uvs-log .sp-kcal-copy small { font-size: 11px; color: var(--text-muted); }
.uvs-log .sp-kcal > b {
  align-self: center; padding: 7px 12px; border-radius: 999px; white-space: nowrap; text-align: center;
  font: 600 12px/1.2 var(--ff-body); color: var(--text-secondary);
  background: rgba(245, 239, 230, 0.05); box-shadow: inset 0 0 0 1px var(--divider);
}
.uvs-log .sp-kcal:focus-visible { outline: 2px solid var(--dv-sage); outline-offset: 2px; }
.uvs-log .sp-note { color: var(--text-secondary); }
.uvs-log .sp-note.is-error { color: color-mix(in srgb, var(--dv-coral) 70%, #fff); }
.uvs-log .sp-note-clear { color: var(--text-muted); }
/* the sticky blurred foot bar with the lit rose primary (`.sp-foot .wo-close-cta` is shared with
   the ceremonies, so the override is `.uvs-log`-scoped) */
.uvs-log .sp-foot {
  position: sticky; bottom: calc(10px + env(safe-area-inset-bottom)); z-index: 5;
  margin-top: auto; padding: 10px; border-radius: 24px;
  background: color-mix(in srgb, var(--page, #191614) 84%, transparent);
  -webkit-backdrop-filter: blur(14px); backdrop-filter: blur(14px);
  box-shadow: inset 0 0 0 1px var(--divider);
}
.uvs-log .sp-foot .wo-close-cta {
  justify-content: center; gap: 8px; min-height: 52px; margin: 0; padding: 14px 16px; border-radius: 18px;
  text-align: center; color: var(--page, #191614);
  background: linear-gradient(135deg, color-mix(in srgb, var(--c) 70%, #fff), var(--c));
  box-shadow: 0 0 18px -2px color-mix(in srgb, var(--c) 60%, transparent), inset 0 1px 0 rgba(255, 255, 255, 0.45);
}
.uvs-log .sp-foot .wo-close-cta > span:not(.wo-close-art) { display: flex; align-items: baseline; gap: 6px; }
.uvs-log .sp-foot .wo-close-cta strong { display: inline; font-size: 15px; font-weight: 700; }
.uvs-log .sp-foot .wo-close-cta small { display: inline; margin: 0; font-size: 12px; font-weight: 600; opacity: 0.7; }
.uvs-log .sp-foot .wo-close-art .t-ico { width: 26px; height: 26px; filter: none; }
.uvs-log .sp-foot .wo-close-cta:disabled { opacity: 0.45; box-shadow: none; }
.uvs-log .sp-foot .wo-close-cta:focus-visible { outline: 2px solid color-mix(in srgb, var(--c) 70%, var(--text-primary)); outline-offset: 3px; }

/* ── the sheets: the shared floating capture sheet (uveg nap rogzites) + what it lacks ── */
.capture-tone-run { --capture-accent: var(--dv-sky); }
.uvs-sheet .uvs-day { padding: 10px; }
.uvs-sheet .uvs-day-lbl { font: 700 11px/1.2 var(--ff-body); letter-spacing: 1px; text-transform: uppercase; color: var(--text-muted); }
.uvs-sheet .uvs-day.has .uvs-day-lbl { color: color-mix(in srgb, var(--c) 80%, var(--text-primary)); }
.uvs-sheet .uvs-slot { padding: 10px; border-radius: 12px; background: rgba(245, 239, 230, 0.03); box-shadow: inset 0 0 0 1px var(--divider); }
.uvs-sheet .uvs-addslot {
  min-height: 40px; padding: 8px 12px; border-radius: 999px; cursor: pointer;
  font: 600 12.5px/1.2 var(--ff-body); color: color-mix(in srgb, var(--c) 75%, var(--text-primary));
}
.uvs-sheet .uvs-inp.is-time { width: 118px; flex: none; }
.uvs-sheet .uvs-inp.is-date { flex: 1; }

/* ── the Sport loading skeleton, in the page's new shape ── */
.uvs-skel { padding: 4px 16px 16px; }
.uvs-skel-head { display: flex; justify-content: space-between; }
.uvs-skel-hero { display: grid; justify-items: center; gap: 8px; padding: 14px 0; }
.uvs-skel-row { display: flex; gap: 8px; }
.uvs-skel-seg { display: flex; justify-content: center; margin-top: 14px; }
.uvs-skel-seg > * { max-width: 100%; }

/* ── 320px: the segments, tiles and rows shrink instead of pushing the page wide (rule 14) ── */
@media (max-width: 360px) {
  .uvs-page .uvs-seg .segtab { padding: 8px 10px; font-size: 12px; }
  .uvs-sport .spw-dlbl { width: 36px; }
  .uvs-page .uvs-mb { grid-template-columns: 76px minmax(0, 1fr) 22px; }
  .uvs-log .sp-grid { gap: 8px; grid-template-columns: repeat(2, minmax(0, 1fr)); }
  .uvs-log .sp-tile-art .t-ico { width: 42px; height: 42px; }
  .uvs-log .sp-kcal.glass { grid-template-columns: 34px 1fr; }
  .uvs-log .sp-kcal > b { grid-area: auto; grid-column: 1 / -1; justify-self: start; }
}
/* mezo-i6q2b (merged from main): today's slot once logged — a lit sage done pill with the 3D tick, no CTA */
.uvs-sport .spw-done {
  display: inline-flex; align-items: center; gap: 5px; margin-left: auto; flex: none; padding: 5px 11px 5px 7px;
  border-radius: 999px; font-size: 12px; font-weight: 700; color: #D6EDC7;
  background: color-mix(in srgb, var(--dv-sage) 14%, transparent);
  box-shadow: inset 0 0 0 1px color-mix(in srgb, var(--dv-sage) 45%, transparent), 0 0 12px -4px var(--dv-sage);
}
.uvs-sport .spw-done .t-ico { filter: none; }
/* ── /uveg edzes sport ── */

/* ── uveg edzes gyakorlatok (mezo-me75u.4) ── /train/medals, /train/exercises, /train/exercises/:key ── */
/* Reference: docs/design_2.0/prototypes/src/uveg-edzes-body.html `medals()`, `exercises()`,
   `exercise()` + the shared `.pagehero/.gyhero/.medr/.gyc/.recs3/.curve/.lrow/.callout/.ghost/
   .dashadd/.flat/.search/.mchp` (owner OK 2026-09-24). Every rule is scoped to a page root
   (`.gyx-page` = the three pages; `.gyx-medals`, `.gyx-catalog`, `.gyx-story`) or to `.gyx-sheet`
   (CatalogExerciseSheet), because `.pl-*` / `.mz-facttile` are shared (bible rule 13). The older
   `── train gyakorlatok (` skin (`.gy-*`) is overridden here, not deleted. Ranking (§3.4): heroes
   are frameless halos; medal rows, exercise cards, record tiles, the curve and the story's medal
   rows are `.glass` (ONE `--c` each — amber, sage for a target, the muscle color on a card);
   chips, search, the chip count, the "Hol szerepel"/"kezelése" rows are flat; empties are dashed. */

/* ── the three pages: the ground shows through ── */
.gyx-page.mz-page { background: transparent; }
.gyx-page .mz-page-body { padding: 2px 16px 22px; }

/* ── Medálok ── */
.gyx-medals .gyx-chiprow { display: flex; justify-content: center; padding: 4px 0 0; }
.gyx-medals .gyx-count {
  --c: var(--dv-amber);
  display: inline-flex; align-items: center; gap: 6px; padding: 6px 12px 6px 8px; border-radius: 999px;
  font-size: 12px; font-weight: 600; color: color-mix(in srgb, var(--c) 60%, var(--text-primary));
  background: color-mix(in srgb, var(--c) 10%, rgba(245, 239, 230, 0.04));
  box-shadow: inset 0 0 0 1px color-mix(in srgb, var(--c) 35%, transparent), 0 0 12px -4px color-mix(in srgb, var(--c) 50%, transparent);
}
.gyx-medals .gyx-note {
  margin: 10px 8px 4px; font-size: 11.5px; line-height: 1.55; text-align: center; color: var(--text-muted);
}
.gyx-medals .gyx-groups { display: grid; gap: 4px; }
.gyx-medals .gyx-date { display: block; padding: 14px 2px 7px; }
.gyx-medals .gyx-list { display: grid; gap: 9px; }
.gyx-medals .mz-facttile.gyx-medal.glass {
  display: flex; align-items: center; gap: 12px; padding: 11px 13px 11px 11px;
  border: 0; border-radius: 20px;
}
/* bible rule 11: `.mz-facttile.mz-w-gold` (box-shadow) and `.gy-rec:first-child` /
   `.gy-rec:nth-child(n + 2)` (background + box-shadow) outrank `.glass` — restate the glass body. */
.gyx-medals .mz-facttile.mz-w-gold.gyx-medal.glass,
.gyx-story .gy-rec.glass:first-child,
.gyx-story .gy-rec.glass:nth-child(n + 2) {
  background:
    radial-gradient(120% 90% at 0% 0%, color-mix(in srgb, var(--c) 22%, transparent), transparent 62%),
    linear-gradient(160deg, rgba(52, 46, 41, 0.72), rgba(30, 27, 24, 0.60));
  box-shadow:
    0 16px 30px -16px rgba(0, 0, 0, 0.75),
    0 0 26px -6px color-mix(in srgb, var(--c) 30%, transparent),
    inset 0 1px 0 rgba(255, 244, 230, 0.10),
    inset 0 -14px 26px -18px color-mix(in srgb, var(--c) 55%, transparent);
}
.gyx-page .gyx-well { width: 52px; height: 52px; }
.gyx-page .gyx-grow { flex: 1; min-width: 0; display: block; }
.gyx-page .gyx-type {
  display: block; font-size: 9.5px; font-weight: 600; letter-spacing: 1.2px; text-transform: uppercase;
  color: color-mix(in srgb, var(--c) 70%, var(--text-primary));
}
.gyx-medals .gyx-name {
  display: block; margin-top: 2px; font-size: 14.5px; font-weight: 600; line-height: 1.25; color: var(--text-primary);
  overflow-wrap: anywhere;
}
.gyx-medals .gyx-prev { display: block; margin-top: 2px; font-size: 11px; line-height: 1.4; color: var(--text-muted); }
.gyx-medals .gyx-end { flex: 0 0 auto; display: grid; justify-items: end; gap: 3px; text-align: right; max-width: 45%; }
.gyx-medals .gyx-tag {
  display: inline-block; padding: 2px 7px; border-radius: 999px;
  font-size: 9px; font-weight: 700; letter-spacing: 1px; color: #191614;
  background: var(--c); box-shadow: 0 0 8px color-mix(in srgb, var(--c) 55%, transparent);
}
.gyx-page .gyx-val {
  display: block; font-size: 18px; font-weight: 600; letter-spacing: -0.4px; line-height: 1.15;
  font-variant-numeric: tabular-nums; color: color-mix(in srgb, var(--c) 42%, var(--text-primary));
}
.gyx-page .gyx-empty.uv-empty {
  --c: var(--dv-amber);
  display: grid; justify-items: center; gap: 6px; margin: 14px 0 0; padding: 22px 18px;
  border-radius: 22px; text-align: center; font-size: 14px; line-height: 1.5; color: var(--text-secondary);
}
.gyx-page .gyx-empty p { margin: 0; }

/* ── the halo hero (Gyakorlatok + one exercise): art left, copy right, no box ── */
.gyx-page .gyx-hero {
  position: relative; overflow-x: clip; display: flex; align-items: center; gap: 14px;
  padding: 14px 18px 12px; background: none; border: 0; box-shadow: none; min-height: 0;
}
/* closest-side: the halo fades to nothing INSIDE its own box, so the header above never cuts it
   into a hard edge (the kit's farthest-corner ellipse is still ~50% lit at its top edge). */
.gyx-page .gyx-hero.uv-halo::before {
  left: 30%; top: 54%; width: 340px; height: 180px;
  background: radial-gradient(closest-side,
    color-mix(in srgb, var(--c) 32%, transparent),
    color-mix(in srgb, var(--dv-amber) 11%, transparent) 55%, transparent);
}
.gyx-page .gyx-hero-art {
  flex: 0 0 auto;
  filter: drop-shadow(0 12px 14px rgba(0, 0, 0, 0.5)) drop-shadow(0 0 18px color-mix(in srgb, var(--c) 42%, transparent));
}
.gyx-page .gyx-hero-copy { flex: 1; min-width: 0; display: block; }
.gyx-page .gyx-hero-tagrow { display: flex; flex-wrap: wrap; align-items: baseline; gap: 4px 8px; }
.gyx-page .gyx-hero-tag { color: color-mix(in srgb, var(--c) 70%, var(--text-primary)); }
.gyx-page .gyx-stamp { font-size: 11px; font-weight: 600; color: var(--text-muted); }
.gyx-page .gyx-hero h2 {
  margin: 2px 0 0; font-family: var(--ff-display); font-size: 26px; font-weight: 600; letter-spacing: -0.8px;
  line-height: 1.1; color: var(--text-primary); overflow-wrap: anywhere;
}
.gyx-page .gyx-say { margin: 4px 0 0; font-size: 12px; line-height: 1.45; color: var(--text-secondary); }
.gyx-page .gyx-foot { display: flex; flex-wrap: wrap; align-items: center; margin-top: 6px; font-size: 11.5px; color: var(--text-muted); }
.gyx-page .gyx-foot > * + *::before { content: '·'; margin: 0 6px; color: var(--text-muted); }
.gyx-page .gyx-foot-link {
  padding: 0; border: 0; background: none; font: inherit; cursor: pointer;
  color: color-mix(in srgb, var(--dv-amber) 70%, var(--text-primary));
}
.gyx-page .gyx-foot-link:focus-visible { outline: 2px solid var(--dv-amber); outline-offset: 2px; border-radius: 4px; }

/* the anatomy in a lit round well (prototype `.mchp`) — the real MuscleChip, never an icon */
.gyx-page .gyx-mchp {
  width: 40px; height: 40px; border-radius: 50%; flex: 0 0 auto; display: grid; place-items: center; overflow: hidden;
  background: radial-gradient(circle at 35% 28%, #3A332D, color-mix(in srgb, var(--c) 16%, #1E1B18));
  box-shadow: inset 0 1px 0 rgba(255, 244, 230, 0.08),
    inset 0 -6px 12px -8px color-mix(in srgb, var(--c) 70%, transparent),
    0 0 12px -4px color-mix(in srgb, var(--c) 55%, transparent);
}
.gyx-page .gyx-mchp .muscle-chip { width: 100% !important; height: 100% !important; }
.gyx-page .gyx-mchp.is-lg { width: 68px; height: 68px; }

/* ── Gyakorlatok: flat search + chips, glass cards, dashed add ── */
.gyx-catalog .gy-search { display: block; margin: 4px 0 10px; }
.gyx-catalog .gyx-search {
  display: flex; align-items: center; gap: 10px; padding: 0 14px; min-height: 46px; border-radius: 16px;
}
.gyx-catalog .gyx-search input {
  flex: 1; min-width: 0; height: 44px; border: 0; outline: none; background: transparent;
  font: inherit; font-size: 13.5px; color: var(--text-primary); color-scheme: dark;
}
.gyx-catalog .gyx-search input::placeholder { color: var(--text-muted); }
.gyx-catalog .gyx-search:focus-within { box-shadow: inset 0 0 0 1.5px var(--dv-amber); }
.gyx-page .gyx-chips {
  display: flex; gap: 6px; min-width: 0; overflow-x: auto; scrollbar-width: none; margin: 0 0 10px; padding: 2px 0 4px;
}
.gyx-page .gyx-chips::-webkit-scrollbar { display: none; }
.gyx-page .gyx-chip, .gyx-sheet .gyx-chip {
  --c: var(--dv-amber);
  flex: 0 0 auto; display: inline-flex; align-items: center; justify-content: center; gap: 6px;
  min-height: 36px; padding: 7px 13px; border: 0; border-radius: 999px; cursor: pointer;
  font: inherit; font-size: 12px; font-weight: 600; white-space: nowrap; color: var(--text-secondary);
  background: rgba(245, 239, 230, 0.05); box-shadow: inset 0 0 0 1px var(--divider);
}
.gyx-page .gyx-chip.is-on, .gyx-sheet .gyx-chip.is-on {
  color: #191614; background: var(--c); box-shadow: 0 0 12px color-mix(in srgb, var(--c) 50%, transparent);
}
.gyx-catalog .gy-list { display: grid; gap: 9px; }
.gyx-catalog .gy-card.glass {
  display: flex; align-items: center; gap: 12px; width: 100%; padding: 11px 12px;
  border: 0; border-radius: 20px; cursor: pointer; text-align: left; color: inherit;
}
.gyx-catalog .gy-card-name { flex: 1; min-width: 0; }
.gyx-catalog .gy-card-name strong {
  display: block; font-size: 15px; font-weight: 600; letter-spacing: -0.2px; line-height: 1.25; color: var(--text-primary);
  overflow-wrap: anywhere;
}
.gyx-catalog .gy-card-name small { display: block; margin-top: 2px; font-size: 11.5px; color: var(--text-secondary); }
.gyx-catalog .gy-card-best { display: grid; justify-items: end; gap: 1px; text-align: right; flex: 0 0 auto; }
.gyx-catalog .gy-card-best b {
  font-size: 17px; font-weight: 600; font-variant-numeric: tabular-nums; color: var(--text-primary);
}
.gyx-catalog .gy-card-best small { font-size: 10px; color: var(--text-muted); }
.gyx-catalog .gy-medals {
  display: inline-flex; align-items: center; gap: 3px; margin-top: 3px; font-size: 11px; font-weight: 600;
  color: color-mix(in srgb, var(--dv-amber) 70%, var(--text-primary));
}
.gyx-catalog .gy-medals .t-ico { filter: none; }
.gyx-catalog .gy-card-empty { flex: 0 0 auto; font-size: 11px; color: var(--text-muted); }
.gyx-catalog .gy-card-go { flex: 0 0 auto; font-size: 18px; font-weight: 400; color: var(--text-muted); }
.gyx-catalog .gyx-empty.uv-empty { display: block; margin: 4px 0 0; padding: 18px; font-size: 13px; }
.gyx-catalog .gyx-add {
  --c: var(--dv-amber);
  display: flex; align-items: center; justify-content: center; gap: 8px; width: 100%; margin: 12px 0 0; padding: 14px;
  border-radius: 20px; border: 1.5px dashed color-mix(in srgb, var(--c) 45%, transparent); cursor: pointer;
  font: inherit; font-size: 14px; font-weight: 600; color: color-mix(in srgb, var(--c) 70%, var(--text-primary));
  background: rgba(245, 239, 230, 0.02);
}

/* ── one exercise's story ── */
.gyx-story .pl-h3 {
  margin: 20px 2px 8px; display: flex; align-items: center; justify-content: space-between; gap: 7px;
  font: 600 9.5px/1.2 var(--ff-body); letter-spacing: 1.4px; text-transform: uppercase; color: var(--text-muted);
}
.gyx-story .pl-foot-say { margin: 4px 2px 0; font-size: 12.5px; line-height: 1.55; color: var(--text-secondary); }
/* Rekordjaid: three amber glass tiles, pale-gold values */
.gyx-story .gy-recs { display: grid; grid-template-columns: repeat(3, minmax(0, 1fr)); gap: 8px; }
.gyx-story .gy-rec.glass,
.gyx-story .gy-rec.glass:first-child,
.gyx-story .gy-rec.glass:nth-child(n + 2) {
  --c: var(--dv-amber);
  grid-column: auto; display: flex; flex-direction: column; gap: 4px; min-width: 0;
  padding: 12px 10px; border: 0; border-radius: 18px; text-align: left;
}
.gyx-story .gy-rec .tr-eyebrow {
  font-size: 9px; font-weight: 600; letter-spacing: 1px; text-transform: uppercase; color: var(--text-muted);
}
.gyx-story .gy-rec.glass strong,
.gyx-story .gy-rec.glass:first-child strong,
.gyx-story .gy-rec.glass:nth-child(n + 2) strong {
  font-family: var(--ff-body); font-size: 19px; font-weight: 600; letter-spacing: -0.5px; line-height: 1.15;
  font-variant-numeric: tabular-nums; overflow-wrap: anywhere;
  color: color-mix(in srgb, var(--dv-amber) 42%, var(--text-primary));
}
.gyx-story .gy-rec.glass strong small { font-size: 11px; font-weight: 500; letter-spacing: 0; color: var(--text-muted); }
.gyx-story .gy-rec > small { font-size: 10px; line-height: 1.3; color: var(--text-muted); }
.gyx-story .gy-rec-bar.uv-bar { height: 5px; margin: 3px 0 1px; overflow: visible; background: rgba(245, 239, 230, 0.07); box-shadow: none; }
.gyx-story .gy-rec-bar.uv-bar b { height: auto; }
@media (max-width: 360px) {
  .gyx-story .gy-recs { grid-template-columns: minmax(0, 1fr); }
  .gyx-medals .gyx-val { font-size: 16px; }
}
/* a long value ("22 kg × 12") wraps inside its column instead of clipping at the glass edge */
.gyx-medals .gyx-end .gyx-val { white-space: normal; overflow-wrap: anywhere; }
/* the next target: an amber callout (flat, a lit left edge) */
.gyx-story .gy-next {
  --c: var(--dv-amber);
  display: flex; align-items: center; gap: 10px; margin: 12px 0 0; padding: 12px 14px; border-radius: 18px;
  font-size: 13px; line-height: 1.45; color: var(--text-secondary);
  background: color-mix(in srgb, var(--c) 8%, transparent); box-shadow: inset 3px 0 0 var(--c);
}
.gyx-story .gy-next b { font-weight: 700; color: color-mix(in srgb, var(--c) 55%, var(--text-primary)); }
/* Az erőd íve: ONE glass card in the muscle color, the line glowing */
.gyx-story .gy-curve-box.glass {
  --c: var(--mus-color, var(--dv-coral));
  position: relative; padding: 14px 14px 12px; border: 0; border-radius: 22px;
}
.gyx-story .gy-curve-box.glass > .gy-curve-val { position: absolute; right: 14px; top: 12px; z-index: 1; text-align: right; }
.gyx-story .gy-curve-val b {
  font-family: var(--ff-display); font-size: 28px; font-weight: 300; letter-spacing: -1.2px; color: var(--text-primary);
}
.gyx-story .gy-curve-val small { display: block; font-size: 10px; color: var(--text-muted); }
.gyx-story .gy-curve { display: block; width: 100%; height: auto; margin-top: 42px; overflow: visible; }
.gyx-story .gy-curve-was {
  fill: none; stroke: var(--c); stroke-width: 3; stroke-linecap: round; stroke-linejoin: round;
  filter: drop-shadow(0 0 6px color-mix(in srgb, var(--c) 70%, transparent));
}
.gyx-story .gy-curve-now {
  fill: var(--c); stroke: none;
  filter: drop-shadow(0 0 6px color-mix(in srgb, var(--c) 70%, transparent));
}
.gyx-story .gy-curve-cap { display: flex; flex-wrap: wrap; justify-content: space-between; gap: 2px 10px; margin-top: 8px; }
.gyx-story .gy-curve-cap i { font-style: normal; font-size: 11px; line-height: 1.45; color: var(--text-muted); }
/* Medáljaid: amber glass rows with a t-record well */
.gyx-story .gy-medal-rows { display: grid; gap: 9px; }
.gyx-story .gy-medal.glass {
  --c: var(--dv-amber);
  display: flex; align-items: center; gap: 12px; padding: 11px 13px 11px 11px; border: 0; border-radius: 20px;
}
.gyx-story .gy-medal strong.gy-medal-date {
  display: block; margin: 2px 0 0; font-size: 14.5px; font-weight: 600; color: var(--text-primary);
}
.gyx-story .gy-medal .gyx-val { flex: 0 0 auto; max-width: 45%; text-align: right; }
/* Hol szerepel + Gyakorlat kezelése: flat rows with a 3D icon */
.gyx-story .pl-sub .pl-row, .gyx-story .pl-row {
  display: flex; align-items: center; gap: 12px; width: 100%; margin: 0 0 8px; padding: 11px 14px;
  border: 0; border-radius: 18px; text-align: left; cursor: pointer; color: inherit;
  background: rgba(245, 239, 230, 0.04); box-shadow: inset 0 0 0 1px var(--divider);
}
.gyx-story .pl-row > span { flex: 1; min-width: 0; }
.gyx-story .pl-row strong { display: block; font-size: 13.5px; font-weight: 600; color: var(--text-primary); }
.gyx-story .pl-row small { display: block; margin-top: 2px; font-size: 11px; color: var(--text-muted); }
.gyx-story .pl-row > b { margin-left: auto; font-size: 18px; font-weight: 400; color: var(--text-muted); }
.gyx-story .pl-row:focus-visible { outline: 2px solid var(--dv-amber); outline-offset: 2px; }

/* ── CatalogExerciseSheet: ONE floating amber glass sheet (bible rule 15) ── */
.sheet.glass.gyx-sheet {
  --c: var(--dv-amber);
  position: absolute; left: 10px; right: 10px; bottom: calc(10px + env(safe-area-inset-bottom));
  overflow-x: hidden; overflow-y: auto; border: 0; border-radius: 30px; padding: 4px 18px 18px;
}
.sheet.glass.gyx-sheet .sheet-handle { background: rgba(245, 239, 230, 0.22); }
.gyx-sheet .gyx-shh { display: flex; align-items: flex-start; gap: 12px; margin-bottom: 6px; }
.gyx-sheet .gyx-shh-copy { flex: 1; min-width: 0; }
.gyx-sheet .gyx-shh-copy h3 {
  margin: 2px 0 0; font-family: var(--ff-display); font-size: 21px; font-weight: 600; letter-spacing: -0.6px; color: var(--text-primary);
}
.gyx-sheet .gyx-shh-x {
  flex: 0 0 auto; width: 36px; height: 36px; padding: 0; border: 0; border-radius: 50%; display: grid; place-items: center;
  color: var(--text-secondary); background: rgba(245, 239, 230, 0.06); box-shadow: inset 0 0 0 1px var(--divider); cursor: pointer;
}
.gyx-sheet .gyx-sh-field { display: grid; gap: 7px; min-width: 0; margin-top: 14px; }
.gyx-sheet .gyx-sh-input {
  display: block; width: 100%; min-width: 0; min-height: 44px; padding: 11px 13px; border: 0; border-radius: 13px;
  font: inherit; font-size: 14px; color: var(--text-primary); color-scheme: dark; outline: none;
  background: rgba(245, 239, 230, 0.05); box-shadow: inset 0 0 0 1px var(--divider);
}
.gyx-sheet .gyx-sh-input:focus { box-shadow: inset 0 0 0 1.5px var(--c); }
.gyx-sheet .gyx-sh-groups { display: grid; gap: 10px; }
.gyx-sheet .gyx-sh-group { display: grid; gap: 6px; }
.gyx-sheet .gyx-sh-sub { font-size: 10px; font-weight: 600; color: var(--text-muted); }
.gyx-sheet .gyx-sh-chips { display: flex; flex-wrap: wrap; gap: 6px; }
.gyx-sheet .gyx-sh-chips .gyx-chip { min-height: 32px; padding: 5px 11px; font-size: 11.5px; }
.gyx-sheet .gyx-sh-types { display: grid; grid-template-columns: repeat(3, minmax(0, 1fr)); gap: 6px; }
.gyx-sheet .gyx-chip.gyx-sh-type { min-width: 0; font-size: 10.5px; letter-spacing: 1px; text-transform: uppercase; }
.gyx-sheet .gyx-sh-steps { display: grid; gap: 4px; }
.gyx-sheet .gyx-sh-steprow { display: flex; align-items: baseline; justify-content: space-between; }
.gyx-sheet .gyx-sh-num {
  font-family: var(--ff-display); font-size: 22px; font-weight: 300; line-height: 1; font-variant-numeric: tabular-nums;
  color: color-mix(in srgb, var(--c) 42%, var(--text-primary));
}
.gyx-sheet .gyx-sh-stepper { display: flex; align-items: center; justify-content: space-between; padding: 4px; border-radius: 14px; }
.gyx-sheet .gyx-sh-stepper button {
  width: 44px; height: 40px; border: 0; border-radius: 11px; display: grid; place-items: center; cursor: pointer;
  color: var(--text-primary); background: rgba(245, 239, 230, 0.06);
}
.gyx-sheet .gyx-sh-stepval { font-size: 13px; font-weight: 600; font-variant-numeric: tabular-nums; color: var(--text-secondary); }
.gyx-sheet .gyx-sh-del {
  display: flex; align-items: center; justify-content: center; gap: 6px; margin: 16px auto 0; min-height: 36px; padding: 6px 14px;
  border: 0; border-radius: 999px; cursor: pointer; font: inherit; font-size: 12.5px; font-weight: 600;
  color: var(--dv-coral); background: transparent;
}
.gyx-sheet .gyx-sh-del.is-armed { background: color-mix(in srgb, var(--dv-coral) 12%, transparent); box-shadow: inset 0 0 0 1px color-mix(in srgb, var(--dv-coral) 45%, transparent); }
.gyx-sheet .gyx-sh-two { display: grid; grid-template-columns: repeat(2, minmax(0, 1fr)); gap: 10px; margin-top: 16px; }
.gyx-sheet .gyx-sh-btn {
  display: flex; align-items: center; justify-content: center; gap: 6px; min-height: 46px; padding: 0 14px;
  border: 0; border-radius: 999px; cursor: pointer; font: inherit; font-size: 14px; font-weight: 600;
  color: var(--text-secondary); background: rgba(245, 239, 230, 0.05); box-shadow: inset 0 0 0 1px var(--divider);
}
.gyx-sheet .gyx-sh-btn.is-primary {
  color: #191614; background: var(--c); box-shadow: 0 0 14px -2px color-mix(in srgb, var(--c) 55%, transparent);
}
.gyx-sheet .gyx-sh-btn.is-primary .t-ico { filter: none; }
.gyx-sheet .gyx-sh-btn:disabled { opacity: 0.45; cursor: default; box-shadow: none; }
/* ── /uveg edzes gyakorlatok ── */

/* ── uveg napom (mezo-yjzhw.4) ── /nap/napom[/:date]: week strip, six-segment ring, reading, lead card, rows, review layers, tab dot ── */
/* Reference: docs/design_2.0/prototypes/src/uveg-napod-body.html `nap()`, `dayBody()`,
   `dimsToday()`, `dimsClosed()`, `segRing()`, `week()`, layout 2 (rows), owner OK 2026-09-24.
   Ranking (bible §3.4): the header row and the section titles are flat type; the hero is a
   FRAMELESS halo clipped with overflow-x: clip (rule 12); the lead card, the Mezo note, every row
   with data and the "tovább" button are the `.glass` objects; everything inside them is flat
   (highlight cells, fact chips, the chat button — rule 5); a row with no score, the no-data card,
   the future card and the loading rows are dashed with the glass layers off (rule 6).
   Owner 2026-09-24: NO italic serif anywhere — every Mezo sentence is upright Geist.
   Everything is scoped to `.napom-page` (rule 13), except the tab dot, which lives in the chrome. */

/* page root: clear the FAB and the floating bar (rule 9) */
.napom-page { padding-bottom: calc(var(--screen-bottom-pad) + 72px); font-style: normal; }

/* the block's tints, named once (mezo-yjzhw.7). Light inks of the --dv-* hues for type and
   marks on the dark ground, the lit-well gradient stops, and the dark ink on an accent button.
   Declared on every root this block styles: the page, the Mai napzárás card, the tab bar. */
.napom-page, .nap-center, .tab-bar {
  --napom-lav-ink: #C9BDF0;
  --napom-lav-hi: #E6DDFF;
  --napom-gold-ink: #E9C48A;
  --napom-gold-hi: #FFD99A;
  --napom-sage-ink: #A9CFA0;
  --napom-coral-ink: #FFB39C;
  --napom-well-hi: #3A332D;
  --napom-well-lo: #1E1B18;
  --napom-on-accent: #191614;
}
.napom-page .rise { --d: calc(var(--i, 0) * 70ms); }
.napom-page .uv-eyebrow { display: block; }

/* flat pill (rank 3) */
.napom-page .napom-flat {
  display: inline-flex; align-items: center; gap: 6px; min-width: 0; max-width: 100%;
  padding: 6px 11px; border: 0; border-radius: 999px;
  font: 600 11.5px/1.3 var(--ff-body); color: var(--text-secondary);
  background: var(--surface-recess); box-shadow: inset 0 0 0 1px var(--divider);
  overflow: hidden; text-overflow: ellipsis; white-space: nowrap;
}
.napom-page .napom-flat b { color: var(--text-primary); font-weight: 600; }

/* header row — the sticky app header's background runs an 18px tail past its 7px bottom
   margin, so the first ~11px of the page sit under it. The back-pill row on the other Nap pages
   is 38px tall and clears it; this row is a 12px eyebrow line, so it takes the same 38px box
   and centres the text below the tail. */
.napom-page .napom-head {
  display: flex; align-items: center; justify-content: space-between; gap: 10px;
  min-height: 38px; padding: 12px 16px 0;
}

/* week strip */
.napom-page .napom-week { display: grid; grid-template-columns: repeat(7, minmax(0, 1fr)); gap: 4px; padding: 12px 14px 2px; }
.napom-page .napom-wd {
  display: flex; flex-direction: column; align-items: center; gap: 4px; min-width: 0; min-height: 44px;
  padding: 7px 0 6px; border: 0; border-radius: 14px; background: none; cursor: pointer;
  font: 600 10px/1.2 var(--ff-body); color: var(--text-muted);
}
.napom-page .napom-wd b { font-size: 14px; font-weight: 600; letter-spacing: -0.3px; color: var(--text-secondary); }
.napom-page .napom-wd i { width: 22px; height: 4px; border-radius: 2px; background: color-mix(in srgb, var(--text-primary) 8%, transparent); }
.napom-page .napom-wd.is-sc i { background: linear-gradient(90deg, var(--napom-lav-ink), var(--napom-gold-ink)); box-shadow: 0 0 6px color-mix(in srgb, var(--napom-lav-ink) 50%, transparent); }
.napom-page .napom-wd.is-th i { background: repeating-linear-gradient(90deg, color-mix(in srgb, var(--text-primary) 35%, transparent) 0 3px, transparent 3px 6px); }
.napom-page .napom-wd.is-today i { background: var(--dv-coral); box-shadow: 0 0 8px var(--dv-coral); }
.napom-page .napom-wd.is-fut { opacity: 0.4; cursor: default; }
.napom-page .napom-wd.is-on {
  background: radial-gradient(80% 100% at 50% 0%, color-mix(in srgb, var(--text-primary) 10%, transparent), transparent 75%);
  box-shadow: inset 0 0 0 1px color-mix(in srgb, var(--text-primary) 14%, transparent);
}
.napom-page .napom-wd.is-on b { color: var(--text-primary); }
.napom-page .napom-wd:focus-visible { outline: 2px solid var(--dv-lav); outline-offset: -2px; }

/* hero: the frameless halo, clipped so a 320px screen never scrolls sideways (rule 12) */
.napom-page .napom-hero { overflow-x: clip; text-align: center; padding: 8px 18px 4px; }
.napom-page .napom-hero::before { top: 44%; width: 360px; height: 300px; }
.napom-page .napom-hero h1 { font: 600 22px/1.2 var(--ff-body); letter-spacing: -0.6px; color: var(--text-primary); margin: 0; }
.napom-page .napom-hero h1 span { color: var(--text-secondary); font-weight: 400; }
.napom-page .napom-sub { margin-top: 4px; font-size: 11px; }
.napom-page .napom-live { display: inline-flex; align-items: center; gap: 6px; color: var(--napom-coral-ink); }
.napom-page .napom-live i { width: 7px; height: 7px; border-radius: 50%; background: var(--dv-coral); box-shadow: 0 0 8px var(--dv-coral); }
@keyframes napom-pulse { 0%, 100% { opacity: 1; transform: scale(1); } 50% { opacity: 0.45; transform: scale(0.7); } }

/* the six-segment ring */
.napom-page .napom-segring { position: relative; width: 212px; height: 212px; margin: 10px auto 0; }
.napom-page .napom-segring svg { position: absolute; inset: 0; width: 100%; height: 100%; transform: rotate(-90deg); overflow: visible; }
.napom-page .napom-seg-t { fill: none; stroke: var(--divider); stroke-width: 12; stroke-linecap: round; }
.napom-page .napom-seg-p {
  fill: none; stroke: var(--c); stroke-width: 12; stroke-linecap: round;
  filter: drop-shadow(0 0 5px color-mix(in srgb, var(--c) 60%, transparent));
}
.napom-page .napom-core {
  position: absolute; inset: 36px; border-radius: 50%; display: grid; place-items: center; text-align: center;
  background: radial-gradient(circle at 35% 30%, var(--napom-well-hi), var(--napom-well-lo));
  box-shadow: inset 0 1px 0 rgba(255, 244, 230, 0.08),
    inset 0 -12px 22px -12px color-mix(in srgb, var(--c, var(--dv-coral)) 55%, transparent),
    0 14px 26px -14px #000;
}
.napom-page .napom-core strong { display: block; font: 300 46px/1 var(--ff-body); letter-spacing: -2.6px; color: var(--text-primary); }
.napom-page .napom-core strong small { font-size: 20px; color: var(--text-muted); letter-spacing: -0.5px; }
.napom-page .napom-core em {
  display: block; margin-top: 5px; font: normal 600 9.5px/1.2 var(--ff-body); letter-spacing: 1.3px;
  color: var(--text-muted); text-transform: uppercase; max-width: 120px;
}
.napom-page .napom-core .napom-grad {
  font-size: 64px; letter-spacing: -4px;
  background: linear-gradient(135deg, var(--napom-lav-ink) 0%, var(--napom-lav-hi) 45%, var(--napom-gold-ink) 100%);
  -webkit-background-clip: text; background-clip: text; color: transparent;
  filter: drop-shadow(0 6px 16px rgba(155, 143, 196, 0.35));
}
.napom-page .napom-core .napom-wait { font-size: 20px; font-weight: 500; letter-spacing: -0.4px; color: var(--text-secondary); }

/* base + the Mezo's correction: a flat pill, the reason one tap away */
.napom-page .napom-corr {
  display: inline-flex; align-items: center; gap: 6px; margin: 10px auto 0; padding: 6px 12px; min-height: 32px;
  border: 0; border-radius: 999px; cursor: pointer;
  font: 500 11.5px/1.3 var(--ff-body); color: var(--text-secondary);
  background: var(--surface-recess); box-shadow: inset 0 0 0 1px var(--divider);
}
.napom-page .napom-corr b { color: var(--napom-lav-ink); }
.napom-page .napom-corr i { font-style: normal; color: var(--text-muted); margin-left: 2px; }
.napom-page .napom-adjwhy { max-width: 320px; margin: 10px auto 0; font: 400 12.5px/1.5 var(--ff-body); color: var(--text-secondary); }

/* today: the rule-written reading, upright Geist 16/500 */
.napom-page .napom-reading {
  max-width: 320px; margin: 12px auto 0;
  font: normal 500 16px/1.45 var(--ff-body); letter-spacing: -0.2px; color: var(--text-primary);
}
.napom-page .napom-upd { display: block; margin-top: 8px; font-size: 10.5px; line-height: 1.45; color: var(--text-muted); }

/* the lead card ("most érdemes") */
.napom-page .napom-lead.glass { display: flex; gap: 12px; align-items: center; margin: 16px 16px 0; padding: 14px; border: 0; }
.napom-page .napom-lead-grow { flex: 1; min-width: 0; }
.napom-page .napom-lead .uv-eyebrow { color: color-mix(in srgb, var(--c) 80%, var(--text-primary)); }
.napom-page .napom-lead strong { display: block; margin-top: 3px; font: 600 15px/1.3 var(--ff-body); letter-spacing: -0.3px; color: var(--text-primary); }
.napom-page .napom-lead small { display: block; margin-top: 3px; font-size: 11.5px; line-height: 1.4; color: var(--text-secondary); }
.napom-page .napom-go {
  flex: 0 0 auto; min-height: 36px; padding: 8px 12px; border: 0; border-radius: 999px; cursor: pointer;
  font: 600 12px/1.2 var(--ff-body); color: color-mix(in srgb, var(--c) 60%, var(--text-primary));
  background: color-mix(in srgb, var(--c) 12%, transparent);
  box-shadow: inset 0 0 0 1px color-mix(in srgb, var(--c) 40%, transparent);
}

/* section titles */
.napom-page .napom-sec { display: flex; align-items: baseline; justify-content: space-between; gap: 10px; padding: 22px 18px 10px; }
.napom-page .napom-sec h2 { margin: 0; font: 600 18px/1.2 var(--ff-body); letter-spacing: -0.5px; color: var(--text-primary); }
.napom-page .napom-sec .uv-eyebrow { text-align: right; }

/* the six rows */
.napom-page .napom-rows { display: grid; gap: 10px; padding: 0 16px; }
.napom-page .napom-drow {
  display: grid; grid-template-columns: auto minmax(0, 1fr) auto; gap: 12px; align-items: center;
  width: 100%; min-width: 0; padding: 12px 14px 12px 12px; border: 0; border-radius: 20px;
  font-family: var(--ff-body); text-align: left; color: var(--text-primary);
}
.napom-page button.napom-drow { cursor: pointer; }
.napom-page .napom-drow.is-open {
  position: relative; overflow: visible;
  background: color-mix(in srgb, var(--text-primary) 2.5%, transparent);
  border: 1.5px dashed color-mix(in srgb, var(--c) 45%, transparent);
  box-shadow: none; -webkit-backdrop-filter: none; backdrop-filter: none;
}
.napom-page .napom-drow.is-open::before, .napom-page .napom-drow.is-open::after { display: none; }
.napom-page .napom-well {
  width: 48px; height: 48px; border-radius: 50%; flex: 0 0 auto; display: grid; place-items: center;
  background: radial-gradient(circle at 35% 28%, var(--napom-well-hi), color-mix(in srgb, var(--c) 14%, var(--napom-well-lo)));
  box-shadow: inset 0 1px 0 rgba(255, 244, 230, 0.08),
    inset 0 -6px 12px -8px color-mix(in srgb, var(--c) 70%, transparent),
    0 0 14px -4px color-mix(in srgb, var(--c) 50%, transparent);
}
.napom-page .napom-drow.is-open .napom-well { opacity: 0.7; }
.napom-page .napom-mid { display: block; min-width: 0; }
.napom-page .napom-mid strong { display: block; font-size: 15px; font-weight: 600; letter-spacing: -0.3px; }
.napom-page .napom-wt { font-style: normal; font-size: 9.5px; font-weight: 600; letter-spacing: 1px; color: var(--text-muted); margin-left: 4px; text-transform: uppercase; }
.napom-page .napom-mid small {
  display: block; min-height: 1.35em; margin: 2px 0 7px; font-size: 11px; color: var(--text-secondary);
  white-space: nowrap; overflow: hidden; text-overflow: ellipsis;
}
.napom-page .napom-bar { height: 6px; }
.napom-page .napom-bar u {
  position: absolute; top: -3px; bottom: -3px; left: var(--g); width: 2px; margin-left: -2px; border-radius: 1px;
  background: color-mix(in srgb, var(--text-primary) 55%, transparent);
}
.napom-page .napom-end { display: block; text-align: right; }
.napom-page .napom-end b { display: block; font-size: 22px; font-weight: 500; letter-spacing: -0.9px; color: color-mix(in srgb, var(--c) 75%, var(--text-primary)); }
.napom-page .napom-drow.is-open .napom-end b { color: var(--text-muted); }
.napom-page .napom-st { display: block; font-size: 9.5px; font-weight: 600; letter-spacing: 1px; color: var(--text-muted); white-space: nowrap; }
.napom-page .napom-st.is-ok, .napom-page button.napom-drow .napom-st { color: color-mix(in srgb, var(--c) 70%, var(--text-primary)); }
.napom-page .napom-dmore { grid-column: 1 / -1; display: block; padding-top: 10px; border-top: 1px solid var(--divider); }
.napom-page .napom-dchips { display: flex; flex-wrap: wrap; gap: 6px; }
.napom-page .napom-dchips .napom-flat { font-size: 11px; padding: 5px 10px; }
.napom-page .napom-dnote { display: block; margin-top: 10px; font: normal 400 14px/1.55 var(--ff-body); color: var(--text-secondary); }

/* the Mezo's note (closed, scored day) */
.napom-page .napom-note.glass { margin: 16px 16px 0; padding: 16px; border: 0; color: var(--text-primary); }
.napom-page .napom-note-head { display: flex; align-items: center; gap: 10px; }
.napom-page .napom-note-head .uv-eyebrow { color: var(--napom-lav-ink); }
.napom-page .napom-note p { margin: 10px 0 0; font: normal 400 15px/1.6 var(--ff-body); color: var(--text-primary); }
.napom-page .napom-hls { display: grid; grid-template-columns: repeat(2, minmax(0, 1fr)); gap: 8px; margin-top: 14px; }
.napom-page .napom-hl { min-width: 0; padding: 10px 12px; border-radius: 14px; }
.napom-page .napom-hl.is-key { grid-column: 1 / -1; }
.napom-page .napom-hl .uv-eyebrow { font-size: 9px; }
.napom-page .napom-hl strong { display: block; margin-top: 3px; font: 600 13.5px/1.3 var(--ff-body); overflow-wrap: anywhere; }
.napom-page .napom-hl.is-key .uv-eyebrow { color: var(--napom-lav-ink); }
.napom-page .napom-hl.is-pattern .uv-eyebrow { color: var(--napom-gold-hi); }
.napom-page .napom-hl.is-win .uv-eyebrow { color: var(--napom-sage-ink); }
.napom-page .napom-fb { margin-top: 14px; padding-top: 12px; border-top: 1px solid var(--divider); }
.napom-page .napom-talk {
  display: flex; align-items: center; gap: 10px; width: 100%; min-height: 44px; margin-top: 10px; padding: 10px 12px;
  border: 0; border-radius: 14px; cursor: pointer; text-align: left;
  font: 600 13.5px/1.3 var(--ff-body); color: var(--napom-lav-hi);
  background: color-mix(in srgb, var(--dv-lav) 10%, transparent);
  box-shadow: inset 0 0 0 1px color-mix(in srgb, var(--dv-lav) 30%, transparent);
}
.napom-page .napom-talk .t-ico { filter: none; }
.napom-page .napom-talk span { flex: 1; }

/* the day's context: flat chips that wrap (rule 14) */
.napom-page .napom-ctx { display: flex; flex-wrap: wrap; gap: 6px; padding: 0 16px; }
.napom-page .napom-foot { margin: 0; padding: 18px 26px 0; font-size: 11px; line-height: 1.5; color: var(--text-muted); text-align: center; }

/* no data / future / failed: dashed, never glass */
.napom-page .napom-nodata {
  --c: var(--dv-sky);
  display: grid; justify-items: center; gap: 6px; margin: 16px; padding: 18px; border-radius: 22px; text-align: center;
  border: 1.5px dashed color-mix(in srgb, var(--c) 45%, transparent); background: color-mix(in srgb, var(--text-primary) 2.5%, transparent);
}
.napom-page .napom-nodata .t-ico { opacity: 0.9; }
.napom-page .napom-nodata strong { font: 600 16px/1.3 var(--ff-body); color: var(--text-primary); }
.napom-page .napom-nodata p { margin: 0; font-size: 12.5px; line-height: 1.5; color: var(--text-secondary); }
.napom-page .napom-retry { min-height: 36px; cursor: pointer; }

/* morning mode: on to today */
.napom-page .napom-tonext.glass {
  display: flex; align-items: center; justify-content: space-between; gap: 10px;
  width: calc(100% - 32px); margin: 16px 16px 0; padding: 14px 16px; border: 0; border-radius: 20px;
  text-align: left; cursor: pointer; font-family: var(--ff-body); color: var(--text-primary);
}
.napom-page .napom-tonext .uv-eyebrow { color: var(--napom-coral-ink); }
.napom-page .napom-tonext strong { display: block; margin-top: 3px; font-size: 16px; font-weight: 600; }
.napom-page .napom-tonext b { font-size: 24px; font-weight: 300; color: var(--napom-coral-ink); }

@media (max-width: 360px) {
  .napom-page .napom-segring { width: 190px; height: 190px; }
  .napom-page .napom-core { inset: 32px; }
  .napom-page .napom-core .napom-grad { font-size: 54px; }
  /* 320px: the CTA pill would squeeze the text column — it drops below, under the text */
  .napom-page .napom-lead.glass { flex-wrap: wrap; }
  .napom-page .napom-lead-grow { flex: 1 1 calc(100% - 56px); }
  .napom-page .napom-go { margin-left: 56px; }
}

/* motion: the live dot pulses, the arcs/bars glide, and a changed value flashes once; the
   reduced branch sits still */
@media (prefers-reduced-motion: no-preference) {
  .napom-page .napom-live i { animation: napom-pulse 1.8s ease-in-out infinite; }
  .napom-page .napom-seg-p { transition: stroke-dasharray 0.9s var(--uv-ease); }
  .napom-page .napom-bar > b { transition: width 0.9s var(--uv-ease); }
}

/* the live pulse (mezo-yjzhw.6, prototype `@keyframes fresh`): when today's refetch moves a
   row's value (or the N/6 centre's), a coral ring + glow fades out over 1.6 s, once
   (`useChangedKeys`, FRESH_PULSE_MS). It is a dedicated overlay (`i.napom-fresh`), not the
   row's own box-shadow: the row's `animation` is the `.rise` entrance and its `box-shadow` is
   the `.glass` stack (rules 1–3) — neither may be replaced mid-pulse — and not `::after`,
   which is the sheen. The glass row clips (rule 3), so its ring is drawn INSIDE the edge; the
   centre does not clip, so its ring is the prototype's outer one. In a row it sits at
   z-index -1 of the row's own stacking context (`.glass` isolates; a dashed row is isolated
   here): over the fill, under the frame and the content. Reduced motion: never shown. */
.napom-page .napom-fresh { display: none; }
@media (prefers-reduced-motion: no-preference) {
  .napom-page .napom-drow.is-fresh { isolation: isolate; }
  .napom-page .napom-drow > .napom-fresh,
  .napom-page .napom-core > .napom-fresh {
    display: block; position: absolute; inset: 0; z-index: -1;
    border-radius: inherit; pointer-events: none;
    animation: napom-fresh-in 1.6s var(--uv-ease) both;
  }
  .napom-page .napom-core > .napom-fresh { z-index: 0; animation-name: napom-fresh; }
}
@keyframes napom-fresh {
  0% { box-shadow: 0 0 0 0 color-mix(in srgb, var(--dv-coral) 0%, transparent); }
  25% { box-shadow: 0 0 0 2px color-mix(in srgb, var(--dv-coral) 55%, transparent), 0 0 26px color-mix(in srgb, var(--dv-coral) 45%, transparent); }
  100% { box-shadow: 0 0 0 0 color-mix(in srgb, var(--dv-coral) 0%, transparent); }
}
@keyframes napom-fresh-in {
  0% { box-shadow: inset 0 0 0 0 color-mix(in srgb, var(--dv-coral) 0%, transparent); }
  25% { box-shadow: inset 0 0 0 2.5px color-mix(in srgb, var(--dv-coral) 55%, transparent), inset 0 0 26px color-mix(in srgb, var(--dv-coral) 45%, transparent); }
  100% { box-shadow: inset 0 0 0 0 color-mix(in srgb, var(--dv-coral) 0%, transparent); }
}

/* chrome: the A napom tab dot (8px lavender, glow, a canvas ring), top-right of the icon.
   The dot is decoration (aria-hidden); its meaning is the link's sr-only description. */
.tab-bar .tab-item .tab-ico { position: relative; }
.tab-bar.glass .tab-ico > .tb-dot {
  position: absolute; top: -2px; right: -5px; z-index: 2;
  width: 8px; height: 8px; border-radius: 50%;
  background: var(--napom-lav-ink); box-shadow: 0 0 8px var(--dv-lav), 0 0 0 2px var(--canvas);
}
/* rule 2: `.glass > *` would drop the sr-only description into the bar's flex row */
.tab-bar.glass > .sr-only { position: absolute; }

/* esti napzárás-kártya a Mai oldalon (owner 2026-09-24, mezo-yjzhw.4): from 20:00 local time a
   lavender glass card sits under the "A napod." heading; after closing it shrinks to a flat
   done row. Reference: uveg-napod-body.html `closeCard()`. Scoped to `.nap-center` (the page
   root also carries `.nap-hub`, whose flex `gap` already spaces top-level children — no extra
   margin here). `.glass` restates border-radius/overflow (§3), so only padding + the halo/type/
   chip geometry need restating (rule 12: `.glass > *` is already global). */
.nap-center .nap-zcard.glass { padding: 16px 14px 14px; }
.nap-center .nap-zhalo {
  position: absolute; right: -60px; top: -70px; width: 220px; height: 200px; z-index: 0; pointer-events: none;
  background: radial-gradient(circle, color-mix(in srgb, var(--c) 34%, transparent), color-mix(in srgb, var(--dv-amber) 10%, transparent) 45%, transparent 70%);
}
.nap-center .nap-ztop { display: flex; gap: 12px; align-items: center; }
.nap-center .nap-zart { flex: 0 0 auto; }
.nap-center .nap-zeb {
  display: block; font: 600 9.5px/1.2 var(--ff-body); letter-spacing: 1.3px; text-transform: uppercase;
  color: color-mix(in srgb, var(--c) 85%, var(--text-primary));
}
.nap-center .nap-ztop strong { display: block; font-size: 20px; font-weight: 600; letter-spacing: -0.5px; margin-top: 3px; color: var(--text-primary); }
.nap-center .nap-ztop small { display: block; font-size: 12.5px; color: var(--text-secondary); margin-top: 3px; line-height: 1.4; }
.nap-center .nap-zchips { display: flex; flex-wrap: wrap; gap: 6px; margin-top: 12px; }
.nap-center .nap-zchips span {
  display: inline-flex; align-items: center; gap: 5px;
  padding: 5px 10px; border-radius: 999px; font-size: 11px; font-weight: 600; color: var(--text-secondary);
  background: var(--surface-recess); box-shadow: inset 0 0 0 1px var(--divider);
}
.nap-center .nap-zgo {
  display: flex; align-items: center; justify-content: center; gap: 8px; width: 100%; margin-top: 14px;
  padding: 12px; border-radius: 16px; border: 0; font: 600 15px var(--ff-body); color: var(--napom-on-accent);
  background: linear-gradient(135deg, var(--dv-lav), color-mix(in srgb, var(--dv-lav) 78%, black));
  box-shadow: 0 0 18px color-mix(in srgb, var(--dv-lav) 45%, transparent);
}
.nap-center .nap-zchips .t-ico { flex: 0 0 auto; filter: none; }
.nap-center .nap-zgo .t-ico { filter: none; }
.nap-center .nap-zgo b { font-weight: 400; font-size: 18px; }
.nap-center .nap-zdone {
  display: flex; align-items: center; gap: 12px; padding: 12px 14px; border-radius: 18px;
}
.nap-center .nap-zdone .t-ico { filter: none; }
.nap-center .nap-zdone span { flex: 1; min-width: 0; }
.nap-center .nap-zdone strong { display: block; font-size: 14px; font-weight: 600; color: var(--text-primary); }
.nap-center .nap-zdone small { display: block; font-size: 11.5px; color: var(--text-secondary); margin-top: 2px; }
.nap-center .nap-zdone a { font-size: 12px; font-weight: 600; color: var(--napom-coral-ink); white-space: nowrap; }
/* ── /uveg napom ── */

/* ── uveg edzes2 terv (mezo-me75u.5) ── /train/mesocycles + /train/mesocycles/:id: the week's day cards ── */
/* Ranking (bible §3.4, prototype uveg-edzes2.html#terv): the card's ONE loud thing is WHAT you
   train — the body map and the title. The three fact boxes are deliberately equal and quiet, and
   the muscle chips are detail. State changes colour and volume, never structure:
     megvolt / részben → glass, calm     ma → glass + accent glow     jön → flat fill
   Everything is scoped to `.tv-day`; the older `.pl-day` rules above are untouched (they still
   serve nothing here, and the U5 sweep removes them once every `pl-day` consumer is migrated). */
.tv-day {
  --c: var(--dv-coral);
  position: relative; isolation: isolate; overflow: hidden;
  display: block; width: 100%; padding: 0; border-radius: 20px; text-align: left;
  background:
    radial-gradient(120% 90% at 0% 0%, color-mix(in srgb, var(--c) 22%, transparent), transparent 62%),
    linear-gradient(160deg, rgba(52, 46, 41, 0.72), rgba(30, 27, 24, 0.6));
  backdrop-filter: blur(16px) saturate(1.5);
  box-shadow:
    0 16px 30px -16px rgba(0, 0, 0, 0.75),
    0 0 26px -6px color-mix(in srgb, var(--c) 30%, transparent),
    inset 0 1px 0 rgba(255, 244, 230, 0.1),
    inset 0 -14px 26px -18px color-mix(in srgb, var(--c) 55%, transparent);
}
.tv-day::before {
  content: ''; position: absolute; inset: 0; border-radius: inherit; padding: 1.3px;
  pointer-events: none; z-index: 2;
  background: linear-gradient(145deg,
    color-mix(in srgb, var(--c) 80%, transparent) 0%,
    rgba(255, 244, 230, 0.16) 30%,
    color-mix(in srgb, var(--c) 18%, transparent) 62%,
    color-mix(in srgb, var(--c) 60%, transparent) 100%);
  -webkit-mask: linear-gradient(#000 0 0) content-box, linear-gradient(#000 0 0);
  -webkit-mask-composite: xor; mask-composite: exclude;
}
/* „jön": not glass. Not everything is glass (bible §3) — the quiet rank is a flat fill. */
.tv-day.is-next {
  background: rgba(245, 239, 230, 0.035);
  backdrop-filter: none;
  box-shadow: inset 0 0 0 1px var(--divider);
}
.tv-day.is-next::before { display: none; }
.tv-day.is-next .muscle-chip, .tv-day.is-next .body-map-figure { opacity: 0.72; }
.tv-day.is-next .tv-day-id strong { color: var(--text-secondary); }
/* „ma": the loudest card in the list. */
.tv-day.is-now {
  box-shadow:
    0 18px 34px -16px rgba(0, 0, 0, 0.8),
    0 0 30px -4px color-mix(in srgb, var(--c) 45%, transparent),
    inset 0 1px 0 rgba(255, 244, 230, 0.12),
    inset 0 -14px 26px -18px color-mix(in srgb, var(--c) 60%, transparent);
}

/* zone 1 — the header band: eyebrow over title, stamp + chevron on a shared right edge */
.tv-day-head { position: relative; z-index: 1; display: flex; align-items: center; gap: 10px; padding: 12px 14px 11px; }
.tv-day-id { flex: 1; min-width: 0; }
.tv-day-tag { display: block; font-size: 9.5px; font-weight: 600; letter-spacing: 1.3px; color: var(--text-muted); text-transform: uppercase; }
.tv-day-id strong { display: block; font-size: 17px; font-weight: 600; letter-spacing: -0.45px; color: var(--text-primary); margin-top: 2px; }
.tv-day-chev { flex: 0 0 auto; color: var(--text-muted); font-size: 19px; font-weight: 400; line-height: 1; }
.tv-day-stamp {
  flex: 0 0 auto; display: inline-flex; align-items: center; gap: 5px;
  padding: 5px 11px 5px 8px; border-radius: 999px;
  font-size: 12px; font-weight: 700; letter-spacing: 0.2px; white-space: nowrap;
}
.tv-day-stamp .t-ico { width: 17px; height: 17px; filter: none; }
.tv-day-stamp.is-done { color: #bfe0a8; background: rgba(134, 188, 99, 0.14); box-shadow: inset 0 0 0 1px rgba(134, 188, 99, 0.45); }
.tv-day-stamp.is-part { color: #ffd08a; background: rgba(255, 190, 96, 0.14); box-shadow: inset 0 0 0 1px rgba(255, 190, 96, 0.45); }
.tv-day-stamp.is-today { color: #191614; background: var(--c); box-shadow: 0 0 16px -2px color-mix(in srgb, var(--c) 75%, transparent); }
.tv-day-stamp.is-today .t-ico { filter: drop-shadow(0 1px 1px rgba(0, 0, 0, 0.35)); }
.tv-day-stamp.is-next { padding: 5px 11px; color: var(--text-muted); background: rgba(245, 239, 230, 0.05); box-shadow: inset 0 0 0 1px var(--divider); }

/* zone 2 — content: a fixed map column, then the data, on one shared left edge */
.tv-day-body {
  position: relative; z-index: 1;
  display: grid; grid-template-columns: 62px minmax(0, 1fr); gap: 13px; align-items: center;
  padding: 11px 14px 13px; border-top: 1px solid var(--divider);
}
.tv-day-map { width: 62px; height: 104px; display: grid; place-items: center; }
.tv-day-map .body-map-figure { width: 100%; height: 100%; overflow: visible; }
.tv-day-col { min-width: 0; }
/* three EQUAL boxes in a real grid — never "whatever width is left" */
.tv-day-facts { display: grid; grid-template-columns: repeat(3, 1fr); gap: 6px; }
.tv-day-facts i {
  min-width: 0; display: flex; flex-direction: column; align-items: center;
  padding: 6px 3px 5px; border-radius: 12px; font-style: normal;
  background: rgba(245, 239, 230, 0.04); box-shadow: inset 0 0 0 1px var(--divider);
}
.tv-day-facts .t-ico { width: 17px; height: 17px; }
.tv-day-facts b { font-size: 13.5px; font-weight: 600; letter-spacing: -0.3px; color: var(--text-primary); margin-top: 1px; }
.tv-day-facts small { font-size: 8px; font-weight: 600; letter-spacing: 0.4px; color: var(--text-muted); }
/* the muscle row shares the boxes' left edge and the one 9px rhythm */
.tv-day-chips { display: flex; gap: 7px; margin-top: 9px; }
.tv-day-chip { display: flex; flex-direction: column; align-items: center; gap: 2px; }
.tv-day-chip b { font-size: 10px; font-weight: 600; letter-spacing: -0.2px; color: var(--text-secondary); }
/* bible §4: row art sits in a lit well, tinted by the muscle's own hue — without it the
   chips read as bare silhouettes next to the body map (owner-approved prototype look). */
.tv-day-chip .muscle-chip {
  /* --mc comes from the chip span (MesoDayCard); the card accent is only the fallback. */
  --mc: var(--c);
  border-radius: 50%; overflow: hidden;
  background: radial-gradient(circle at 35% 28%, #3a332d, color-mix(in srgb, var(--mc) 16%, #1e1b18));
  box-shadow:
    inset 0 1px 0 rgba(255, 244, 230, 0.08),
    inset 0 -6px 12px -8px color-mix(in srgb, var(--mc) 70%, transparent),
    0 0 12px -4px color-mix(in srgb, var(--mc) 55%, transparent);
}

/* 320px is the hardest width (U1 rule 8): the map column and the rhythm shrink, nothing wraps out */
@media (max-width: 360px) {
  .tv-day-head { padding: 11px 12px 10px; }
  .tv-day-body { grid-template-columns: 52px minmax(0, 1fr); gap: 10px; padding: 10px 12px 12px; }
  .tv-day-map { width: 52px; height: 90px; }
  .tv-day-facts small { font-size: 7.5px; }
  .tv-day-stamp { font-size: 11px; padding: 4px 9px 4px 7px; }
  .tv-day-chips { gap: 5px; }
}
/* the off-day row: the SAME vocabulary as the cards (eyebrow, stamp, 3D icon), one rank quieter.
   A week is also its off days — they are a row, never a card (bible §3: not everything is glass). */
.tv-dayrest {
  display: flex; align-items: center; gap: 10px;
  padding: 11px 14px; border-radius: 17px;
  background: rgba(245, 239, 230, 0.035); box-shadow: inset 0 0 0 1px var(--divider);
}
.tv-dayrest em { flex: 1; min-width: 0; font-style: normal; font-size: 12.5px; color: var(--text-secondary); }
.tv-dayrest .t-ico { flex: 0 0 auto; }
.tv-dayrest .tv-day-tag { flex: 0 0 auto; }

/* ── /uveg edzes2 terv ── */

/* ── uveg edzes2 run (mezo-me75u.5) ── /train/mesocycles/:id: the running plan's own page ── */
/* Ranking (bible §3.4): the hero is the frameless halo the kit's `PageHero art=` already draws;
   the arc card, Mezo's sentence and the two tiles are glass; chips and bands inside them are
   flat. U2 rule 11 — the old house rules for `.mz-card`/`.mz-tile`/`.mz-coach` outrank `.glass`
   at equal specificity, so the glass body is restated HERE, scoped to the page root. */
.tv-run { --c: var(--dv-coral); }

.tv-run .mz-card.glass,
.tv-run .mz-coach.glass,
.tv-run .mz-tile.glass {
  background:
    radial-gradient(120% 90% at 0% 0%, color-mix(in srgb, var(--c) 20%, transparent), transparent 62%),
    linear-gradient(160deg, rgba(52, 46, 41, 0.72), rgba(30, 27, 24, 0.6));
  box-shadow:
    0 16px 30px -16px rgba(0, 0, 0, 0.75),
    0 0 26px -6px color-mix(in srgb, var(--c) 28%, transparent),
    inset 0 1px 0 rgba(255, 244, 230, 0.1),
    inset 0 -14px 26px -18px color-mix(in srgb, var(--c) 50%, transparent);
}
/* one accent per card (bible §2): the arc keeps the plan's coral, the tiles take their own */
.tv-run .mz-coach.glass { --c: var(--dv-lav); }
.tv-run .mz-tile.glass.mz-w-sage { --c: var(--dv-sage); }

/* Mezo's own sentence is a ONE-LINER: serif italic stays (bible §5), and rule 23 keeps it
   to a lead — this card never carries paragraph prose. */
.tv-run .mz-coach {
  display: flex; align-items: flex-start; gap: 10px;
  padding: 13px 15px; border-radius: 22px; margin-top: 11px;
  font-family: var(--ff-serif); font-style: italic; font-size: 15.5px; line-height: 1.5;
  color: var(--text-primary);
}
.tv-run .mz-coach .dot {
  flex: 0 0 auto; width: 8px; height: 8px; margin-top: 7px; border-radius: 50%;
  background: var(--c); box-shadow: 0 0 8px var(--c);
}

/* the week-arc card: the dots and the phase chip go flat inside the glass (never glass in glass) */
.tv-run .mz-phchip {
  padding: 5px 11px; border-radius: 999px; font-size: 11px; font-weight: 600;
  color: color-mix(in srgb, var(--c) 75%, #fff);
  background: rgba(245, 239, 230, 0.05); box-shadow: inset 0 0 0 1px var(--divider);
}
.tv-run .mz-wdots i.is-now { background: var(--c); box-shadow: 0 0 10px color-mix(in srgb, var(--c) 70%, transparent); }
.tv-run .mz-arcline b { color: color-mix(in srgb, var(--c) 70%, #fff); }

/* the two tiles: the mini bars and the rollover bands are flat, lit by their own muscle hue */
/* the mini cluster is a BAR chart, not a colour-block row: at tile width `flex: 1` gave five
   38px-wide slabs. Narrow, bottom-aligned bars with their own glow read as volume at a glance. */
.tv-run .mz-wmini { height: 38px; gap: 5px; justify-content: flex-start; }
.tv-run .mz-wmini b { flex: 0 0 13px; border-radius: 4px; box-shadow: 0 0 8px -2px currentColor; }
.tv-run .mz-mband {
  padding: 4px 9px; border-radius: 999px; font-size: 11px; font-weight: 600;
  color: var(--text-secondary); background: rgba(245, 239, 230, 0.05);
  box-shadow: inset 0 0 0 1px var(--divider);
}
.tv-run .mz-mband.up {
  color: #bfe0a8; background: rgba(134, 188, 99, 0.12);
  box-shadow: inset 0 0 0 1px rgba(134, 188, 99, 0.4);
}
/* „Hétfőn jön" is a forecast, not a door — it must not look tappable */
.tv-run .mz-tile.glass.mz-w-sage .mz-chev { display: none; }
/* ── /uveg edzes2 run ── */

/* ── uveg edzes2 nap (mezo-me75u.5) ── /train/mesocycles/:id/days/:day (+/edit) ── */
/* Ranking (bible §3.4, prototype uveg-edzes2.html#nap): the hero is a FRAMELESS halo carrying
   the day's body map and its one numeral; the exercise cells are the page's primary objects and
   wear glass; the per-muscle rows and the 4-cell prescription grid inside them stay flat. */
.tv-day-page { --c: var(--dv-coral); }

/* the hero loses its wash box and becomes a halo (U2 rule 12: clip it, a 340px halo
   scrolls a 320px screen sideways) */
.tv-day-page + .mz-page-body, .mz-page-body.tv-day-page { overflow-x: clip; }
.pl-dhero { position: relative; overflow-x: clip; }
.pl-dhero .pl-dhero-wash { display: none; }
.pl-dhero::before {
  content: ''; position: absolute; left: 50%; top: 50%; z-index: -1; pointer-events: none;
  width: 340px; height: 260px; transform: translate(-50%, -50%);
  background: radial-gradient(ellipse at 50% 45%,
    color-mix(in srgb, var(--mus-color, var(--dv-coral)) 30%, transparent), transparent 66%);
}
.pl-dhero-number strong {
  color: color-mix(in srgb, var(--mus-color, var(--dv-coral)) 42%, #fff);
  text-shadow: 0 0 22px color-mix(in srgb, var(--mus-color, var(--dv-coral)) 50%, transparent);
}
.pl-dhero-art .body-map-figure { filter: drop-shadow(0 12px 16px rgba(0, 0, 0, 0.5)); }

/* the exercise cell: glass, tinted by the exercise's own muscle */
.tv-day-page .pl-ex.glass {
  --c: var(--mus-color, var(--dv-coral));
  background:
    radial-gradient(120% 90% at 0% 0%, color-mix(in srgb, var(--c) 20%, transparent), transparent 62%),
    linear-gradient(160deg, rgba(52, 46, 41, 0.72), rgba(30, 27, 24, 0.6));
  box-shadow:
    0 16px 30px -16px rgba(0, 0, 0, 0.75),
    0 0 26px -6px color-mix(in srgb, var(--c) 26%, transparent),
    inset 0 1px 0 rgba(255, 244, 230, 0.1),
    inset 0 -14px 26px -18px color-mix(in srgb, var(--c) 50%, transparent);
}
/* the prescription grid is flat INSIDE the glass (U1 rule 5) */
.tv-day-page .pl-ex-grid > * {
  background: rgba(245, 239, 230, 0.04); box-shadow: inset 0 0 0 1px var(--divider);
}
/* „＋ Gyakorlat hozzáadása" is free space, so it is dashed — never glass (U2 rule 6) */
.tv-day-page .pl-add {
  --c: var(--dv-coral);
  border: 1.5px dashed color-mix(in srgb, var(--c) 45%, transparent);
  background: rgba(245, 239, 230, 0.025); box-shadow: none;
  color: color-mix(in srgb, var(--c) 72%, #fff);
}
.tv-day-page .pl-editlink { color: var(--text-secondary); }

/* the day's editor keeps the same ground; MesoExercises owns its own rows */
.tv-dayedit { --c: var(--dv-coral); }
/* ── /uveg edzes2 nap ── */

/* ── uveg edzes2 izmok (mezo-me75u.5) ── /…/week + /…/week/:muscle ── */
/* Ranking (bible §3.4, prototype uveg-edzes2.html#het + #izom): both pages open on the
   FRAMELESS halo hero the day page already uses (`.pl-dhero`, dressed in the nap block);
   the muscle rows and THE GAUGE are the primary objects and wear glass; the stat cells,
   the derivation steps and the versus rows inside stay flat. */
.tv-week { --c: var(--dv-coral); }
.tv-muscle { --c: var(--mus-color, var(--dv-coral)); }

/* one verdict row per muscle — glass, tinted by the muscle's own hue (U1 rule 4: the hue
   is published on the element that wears the glass, and `.pl-item` already carries it) */
.tv-week .pl-item.glass,
.tv-muscle .pl-scale-wrap.glass {
  --c: var(--mus-color, var(--dv-coral));
  background:
    radial-gradient(120% 90% at 0% 0%, color-mix(in srgb, var(--c) 20%, transparent), transparent 62%),
    linear-gradient(160deg, rgba(52, 46, 41, 0.72), rgba(30, 27, 24, 0.6));
  box-shadow:
    0 16px 30px -16px rgba(0, 0, 0, 0.75),
    0 0 26px -6px color-mix(in srgb, var(--c) 26%, transparent),
    inset 0 1px 0 rgba(255, 244, 230, 0.1),
    inset 0 -14px 26px -18px color-mix(in srgb, var(--c) 50%, transparent);
}
/* the room bar and its landmark tick, lit by the muscle (bible §5) */
.tv-week .pl-item-bar i { box-shadow: 0 0 7px -1px color-mix(in srgb, var(--c) 65%, transparent); }

/* THE GAUGE is this page's one graphic: the fill glows, the marks and captions stay quiet */
.tv-muscle .pl-scale-fill {
  background: linear-gradient(90deg, color-mix(in srgb, var(--c) 55%, #fff), var(--c));
  box-shadow: 0 0 10px color-mix(in srgb, var(--c) 60%, transparent);
}
.tv-muscle .pl-scale-mark { background: rgba(245, 239, 230, 0.45); }
/* U1 rule 3: `.glass` clips (overflow: hidden), and the gauge's „most" pin sits ABOVE the
   track — it was cut in half. The card says so explicitly, and turns the sheen off, since a
   light sweep with no clip would run off the card's edge. */
.tv-muscle .pl-scale-wrap.glass { overflow: visible; padding-top: 22px; }
.tv-muscle .pl-scale-wrap.glass::after { display: none; }
.tv-muscle .pl-scale-legend { color: var(--text-muted); }

/* flat cells inside the glass, everywhere (U1 rule 5) */
.tv-muscle .pl-mstats > *,
.tv-muscle .pl-deriv-step,
.tv-muscle .pl-versus-row {
  background: rgba(245, 239, 230, 0.04); box-shadow: inset 0 0 0 1px var(--divider);
}
/* „Most" never turns red on a down move — the muscle keeps its own colour (page rule) */
.tv-muscle .pl-versus-row.is-now .pl-versus-bar i { background: var(--c); opacity: 1; }
/* ── /uveg edzes2 izmok ── */

/* ── uveg edzes2 konyvtar (mezo-me75u.5) ── /…/konyvtar, /…/futamok, /…/:id/report, /…/compare ── */
/* Ranking (bible §3.4, prototype uveg-edzes2.html#konyvtar/#futamok/#riport/#osszevetes):
   the poster hero stays a frameless halo (`.pl-lhero` rides the `.pl-dhero` rules dressed in
   the nap block); every run/template CARD is glass; the fact cells, chips and footer actions
   inside them are flat; the one loud CTA („Új terv összeállítása") is a filled accent button.
   Each area keeps ONE accent, so the three lists never blur into each other. */
.tv-lib { --c: var(--dv-sage); }
.tv-runs { --c: var(--dv-gold, var(--dv-amber)); }
.tv-report { --c: var(--dv-gold, var(--dv-amber)); }
.tv-cmp { --c: var(--dv-sky); }

.tv-lib .pl-lib-card.glass,
.tv-runs .pl-lib-card.glass {
  background:
    radial-gradient(120% 90% at 0% 0%, color-mix(in srgb, var(--c) 20%, transparent), transparent 62%),
    linear-gradient(160deg, rgba(52, 46, 41, 0.72), rgba(30, 27, 24, 0.6));
  box-shadow:
    0 16px 30px -16px rgba(0, 0, 0, 0.75),
    0 0 26px -6px color-mix(in srgb, var(--c) 26%, transparent),
    inset 0 1px 0 rgba(255, 244, 230, 0.1),
    inset 0 -14px 26px -18px color-mix(in srgb, var(--c) 50%, transparent);
}
/* the running plan is the library's loudest row; a queued one is calm and takes the sky hue,
   so „most fut" and „következik" never read as the same thing */
.tv-lib .pl-lib-card.is-now.glass { --c: var(--dv-coral); }
.tv-lib .pl-lib-card.is-queued.glass { --c: var(--dv-sky); }

/* flat inside the glass (U1 rule 5): fact cells, status pills and the card's footer actions */
.tv-lib .pl-lib-card .pl-lib-facts > *,
.tv-runs .pl-lib-card .pl-lib-facts > *,
.tv-runs .pl-lib-foot > * {
  background: rgba(245, 239, 230, 0.04); box-shadow: inset 0 0 0 1px var(--divider);
}

/* the compare SELECTION is a state, not a second card: a lit ring, no extra chrome */
.tv-runs .pl-lib-card.is-picked.glass {
  box-shadow:
    0 16px 30px -16px rgba(0, 0, 0, 0.75),
    0 0 26px -6px color-mix(in srgb, var(--c) 45%, transparent),
    inset 0 0 0 1.5px color-mix(in srgb, var(--c) 70%, transparent);
}

/* the one loud CTA — filled, not glass (bible §3: glass is loud only next to what is not) */
.tv-lib .pl-lib-new,
.tv-runs .pl-lib-new {
  border: 0; color: #191614;
  background: var(--c);
  box-shadow:
    0 12px 26px -14px color-mix(in srgb, var(--c) 90%, transparent),
    0 0 18px -4px color-mix(in srgb, var(--c) 60%, transparent);
}
/* A filled CTA has to restate EVERY colour: the old skin's rules set the title, the sub-line
   and the art well for a dark card, and on an accent fill they read as dark-on-dark. */
.tv-lib .pl-lib-new strong, .tv-runs .pl-lib-new strong { color: #191614; }
.tv-lib .pl-lib-new small, .tv-runs .pl-lib-new small { color: rgba(25, 22, 20, 0.72); }
.tv-lib .pl-lib-new b, .tv-runs .pl-lib-new b { color: rgba(25, 22, 20, 0.8); }
.tv-lib .pl-lib-new-art, .tv-runs .pl-lib-new-art {
  background: rgba(255, 244, 230, 0.28); box-shadow: inset 0 0 0 1px rgba(255, 244, 230, 0.4);
  filter: drop-shadow(0 2px 3px rgba(0, 0, 0, 0.25));
}

/* the report's star hero keeps the gold glow; its blocks are glass, its rows flat */
.tv-report .pl-lhero-stars { filter: drop-shadow(0 0 14px rgba(255, 190, 96, 0.45)); }
.tv-report .pl-block,
.tv-cmp .pl-block {
  background:
    radial-gradient(120% 90% at 0% 0%, color-mix(in srgb, var(--c) 18%, transparent), transparent 62%),
    linear-gradient(160deg, rgba(52, 46, 41, 0.72), rgba(30, 27, 24, 0.6));
  box-shadow:
    0 16px 30px -16px rgba(0, 0, 0, 0.75),
    0 0 24px -8px color-mix(in srgb, var(--c) 24%, transparent),
    inset 0 1px 0 rgba(255, 244, 230, 0.1);
}
/* a hole is „–", never 0 — and the better side is sage, the weaker side is NOT red (page rule) */
.tv-cmp .pl-cmp-better { color: #bfe0a8; }
/* ── /uveg edzes2 konyvtar ── */

/* ── uveg edzes2 sablonok (mezo-me75u.5) ── /train/templates(+/:id), /…/templates/:id, /…/new, /train/custom ── */
/* Ranking (bible §3.4, prototype uveg-edzes2.html#sablonok/#sablon/#ujterv/#sajat): the template
   CARD is the primary object and wears glass; its fact cells, muscle chips and day rows are flat.
   The editors (template day plan, custom composer) are FORMS — a form is not a poster, so only
   its cards wear glass and every control stays flat, the way the U2 composer settled it. */
.tv-tpls { --c: var(--dv-sage); }
.tv-tpl { --c: var(--dv-sage); }
.tv-wizard { --c: var(--dv-lav); }
.tv-custom { --c: var(--dv-coral); }

.tv-tpls .pl-lib-card.glass {
  background:
    radial-gradient(120% 90% at 0% 0%, color-mix(in srgb, var(--c) 20%, transparent), transparent 62%),
    linear-gradient(160deg, rgba(52, 46, 41, 0.72), rgba(30, 27, 24, 0.6));
  box-shadow:
    0 16px 30px -16px rgba(0, 0, 0, 0.75),
    0 0 26px -6px color-mix(in srgb, var(--c) 26%, transparent),
    inset 0 1px 0 rgba(255, 244, 230, 0.1),
    inset 0 -14px 26px -18px color-mix(in srgb, var(--c) 50%, transparent);
}
.tv-tpls .pl-lib-card .pl-lib-facts > * {
  background: rgba(245, 239, 230, 0.04); box-shadow: inset 0 0 0 1px var(--divider);
}
/* the filled CTA restates every colour (the U2 rule 11 trap, paid for on the library page) */
.tv-tpls .pl-lib-new {
  border: 0; color: #191614; background: var(--c);
  box-shadow:
    0 12px 26px -14px color-mix(in srgb, var(--c) 90%, transparent),
    0 0 18px -4px color-mix(in srgb, var(--c) 60%, transparent);
}
.tv-tpls .pl-lib-new strong { color: #191614; }
.tv-tpls .pl-lib-new small { color: rgba(25, 22, 20, 0.72); }
.tv-tpls .pl-lib-new b { color: rgba(25, 22, 20, 0.8); }
.tv-tpls .pl-lib-new-art {
  background: rgba(255, 244, 230, 0.28); box-shadow: inset 0 0 0 1px rgba(255, 244, 230, 0.4);
  filter: drop-shadow(0 2px 3px rgba(0, 0, 0, 0.25));
}

/* the template's own page: the week's days are glass cards, the exercise rows flat inside */
.tv-tpl .pl-lib-card.is-open {
  background:
    radial-gradient(120% 90% at 0% 0%, color-mix(in srgb, var(--c) 18%, transparent), transparent 62%),
    linear-gradient(160deg, rgba(52, 46, 41, 0.72), rgba(30, 27, 24, 0.6));
  box-shadow:
    0 16px 30px -16px rgba(0, 0, 0, 0.75),
    0 0 24px -8px color-mix(in srgb, var(--c) 24%, transparent),
    inset 0 1px 0 rgba(255, 244, 230, 0.1);
}
/* an off day is a quiet row — a week is also its off days (page rule), not a card */
.tv-tpl .pl-row.is-quiet {
  background: rgba(245, 239, 230, 0.035); box-shadow: inset 0 0 0 1px var(--divider);
}
/* Törlés keeps its warning tone: a destructive action is never the page's lit primary
   (U4 rule 29) — it stays a flat coral outline */
.tv-tpl .pl-danger {
  color: #ffb39c; background: rgba(255, 126, 92, 0.07);
  box-shadow: inset 0 0 0 1px rgba(255, 126, 92, 0.35);
}

/* the wizard: one question per glass card, the answers as flat chips */
.tv-wizard .mz-card, .tv-wizard .pl-block {
  background:
    radial-gradient(120% 90% at 0% 0%, color-mix(in srgb, var(--c) 18%, transparent), transparent 62%),
    linear-gradient(160deg, rgba(52, 46, 41, 0.72), rgba(30, 27, 24, 0.6));
  box-shadow:
    0 16px 30px -16px rgba(0, 0, 0, 0.75),
    0 0 24px -8px color-mix(in srgb, var(--c) 24%, transparent),
    inset 0 1px 0 rgba(255, 244, 230, 0.1);
}

/* the custom composer is a FORM: its head and save bar sit on the app ground, its recipe
   rows are flat cells. The only lit control is „Indítás ma" — the one constructive CTA. */
.tv-custom .card {
  background: rgba(245, 239, 230, 0.04); box-shadow: inset 0 0 0 1px var(--divider);
}
.tv-custom .np-cta {
  color: #191614; background: var(--c); border: 0;
  box-shadow:
    0 12px 26px -14px color-mix(in srgb, var(--c) 90%, transparent),
    0 0 18px -4px color-mix(in srgb, var(--c) 60%, transparent);
}
/* ── /uveg edzes2 sablonok ── */

/* ── uveg edzes2 het (mezo-me75u.5) ── /train/week/terkep, /train/week/jelek, /train/week/mozgas ── */
/* The Terhelés LANDING (/train/week) was dressed in U4 (`.tw-load`); these are its three
   sub-pages, and they inherit the shared `ld-` family from it. Ranking (bible §3.4): the body
   map and the taxonomy grid ARE the page — they get the halo and no box; the legend, the
   untouched-muscle rows and the movement rows are flat; only the two movement SUMMARY cards
   (terem / sport) are glass, because they carry the page's two numbers. */
.tw-map { --c: var(--dv-coral); }
.tw-signals { --c: var(--dv-coral); }
.tw-move { --c: var(--dv-coral); }

/* the map is a frameless halo, like every other hero in this slice */
.tw-map .ld-map-page { position: relative; overflow-x: clip; }
.tw-map .ld-map-page::before {
  content: ''; position: absolute; left: 50%; top: 42%; z-index: -1; pointer-events: none;
  width: 350px; height: 300px; transform: translate(-50%, -50%);
  background: radial-gradient(ellipse, color-mix(in srgb, var(--c) 26%, transparent), transparent 66%);
}
.tw-map .ld-legend, .tw-map .ld-wait > * {
  background: rgba(245, 239, 230, 0.04); box-shadow: inset 0 0 0 1px var(--divider);
}

/* „Minden izomjel": the taxonomy drawn. A LIVE cell is lit by its own region hue; an unlit one
   stays flat — a muscle the week's log cannot speak for is never guessed lit (page rule). */
.tw-signals .mm-cell {
  background: rgba(245, 239, 230, 0.035); box-shadow: inset 0 0 0 1px var(--divider);
}
.tw-signals .mm-cell.is-live {
  background: radial-gradient(90% 100% at 50% 0%,
    color-mix(in srgb, var(--mm-color, var(--c)) 20%, transparent), rgba(245, 239, 230, 0.03));
  box-shadow:
    inset 0 0 0 1px color-mix(in srgb, var(--mm-color, var(--c)) 50%, transparent),
    0 0 13px -4px var(--mm-color, var(--c));
}

/* „Minden mozgásod": two summary cards, never merged into one number (page rule) */
.tw-move .ld-move-card {
  background:
    radial-gradient(120% 90% at 0% 0%, color-mix(in srgb, var(--c) 20%, transparent), transparent 62%),
    linear-gradient(160deg, rgba(52, 46, 41, 0.72), rgba(30, 27, 24, 0.6));
  box-shadow:
    0 16px 30px -16px rgba(0, 0, 0, 0.75),
    0 0 26px -6px color-mix(in srgb, var(--c) 26%, transparent),
    inset 0 1px 0 rgba(255, 244, 230, 0.1),
    inset 0 -14px 26px -18px color-mix(in srgb, var(--c) 50%, transparent);
}
/* the sport side keeps its own hue, so „becslés" and „mért" never look like one number */
.tw-move .ld-move-card.is-sport { --c: var(--dv-rose); }
.tw-move .ld-move-row {
  background: rgba(245, 239, 230, 0.04); box-shadow: inset 0 0 0 1px var(--divider);
}
/* ── /uveg edzes2 het ── */

/* ── uveg en hub (mezo-me75u.6) ── /me: identity hero, goal card, the tile mosaic ── */
/* Ranking (bible §3.4, prototype uveg-en.html#en): the identity hero is THE loud thing — no card,
   a frameless rose→gold halo, the XP ring glowing around the monogram, a lit Lv pill, a lit-gold
   flat title chip, flat stat pills with 3D icons. The goal card is ONE coral glass with flat
   dimension chips and three lit mini-cells inside; its empty door is dashed. Every mosaic tile is
   glass in its own accent. Everything is scoped to `.enh-hub` — `.mz-tile`/`.mz-mcells`/
   `.lg-goalchip` serve other surfaces (U2 rule 13). */
.enh-hub { --c: var(--dv-rose); }

/* the identity hero: frameless halo (kit .uv-halo), clipped at 320px (U2 rule 12) */
.enh-hub .enh-idhero.uv-halo {
  --c: var(--dv-rose); --c2: var(--dv-amber);
  overflow-x: clip; gap: 0; padding: 8px 20px 6px;
}
.enh-hub .enh-idhero.uv-halo::before { top: 40%; width: 360px; }
.enh-hub .enh-idring {
  position: relative; width: 128px; height: 128px; background: none;
}
.enh-hub .enh-idring svg {
  position: absolute; inset: 0; width: 128px; height: 128px; overflow: visible; transform: rotate(-90deg);
}
.enh-hub .enh-idring .uv-ring-track, .enh-hub .enh-idring .uv-ring-prog { stroke-width: 6; --c: var(--dv-rose); }
.enh-hub .enh-idring i {
  position: absolute; inset: 14px; width: auto; height: auto; border-radius: 50%;
  display: grid; place-items: center; font-style: normal;
  font-family: var(--ff-display); font-size: 44px; font-weight: 300; letter-spacing: -2px;
  color: var(--text-primary);
  background: radial-gradient(circle at 35% 28%, #3A332D, color-mix(in srgb, var(--dv-rose) 16%, #1E1B18));
  box-shadow: inset 0 1px 0 rgba(255, 244, 230, 0.1),
    inset 0 -10px 18px -10px color-mix(in srgb, var(--dv-rose) 70%, transparent);
}
.enh-hub .enh-lv {
  position: absolute; left: 50%; bottom: -8px; transform: translateX(-50%);
  padding: 3px 10px; border-radius: 999px; white-space: nowrap;
  font-size: 11px; font-weight: 700; color: var(--text-inverse); background: var(--dv-rose);
  box-shadow: 0 0 12px color-mix(in srgb, var(--dv-rose) 60%, transparent), 0 0 0 2px var(--canvas);
}
.enh-hub .enh-nm {
  margin-top: 16px; font-size: 28px; font-weight: 600; letter-spacing: -0.8px; color: var(--text-primary);
  max-width: 100%; overflow-wrap: anywhere;
}
/* the title chip: lit gold, FLAT (a chip, never glass) */
.enh-hub .enh-titlech, .enh-hub .enh-titlech.is-none {
  margin-top: 6px; display: inline-flex; align-items: center; gap: 6px; min-width: 0; max-width: 100%;
  padding: 5px 12px; border-radius: 999px;
  font-size: 12px; font-weight: 600; letter-spacing: 0; text-transform: none;
  color: color-mix(in srgb, var(--dv-amber) 72%, var(--text-primary));
  background: color-mix(in srgb, var(--dv-amber) 8%, transparent);
  box-shadow: inset 0 0 0 1px color-mix(in srgb, var(--dv-amber) 30%, transparent);
}
.enh-hub .enh-titlech.is-none { color: var(--text-secondary); background: rgba(245, 239, 230, 0.05); box-shadow: inset 0 0 0 1px var(--divider); }
.enh-hub .enh-titlech .t-ico { width: 18px; height: 18px; }
/* the stat row: flat pills, wrapping (U2 rule 14) */
.enh-hub .enh-idstats {
  display: flex; flex-wrap: wrap; justify-content: center; gap: 6px; margin-top: 12px;
  font-size: 12px; font-weight: 600; color: var(--text-secondary);
}
.enh-hub .enh-idstats .enh-flat, .enh-hub .enh-idstats button.enh-idstat.enh-flat {
  display: inline-flex; align-items: center; gap: 6px; min-width: 0;
  padding: 6px 11px; border-radius: 999px; white-space: nowrap;
  font: inherit; color: var(--text-secondary);
  background: rgba(245, 239, 230, 0.05); box-shadow: inset 0 0 0 1px var(--divider);
}
.enh-hub .enh-idstats .enh-flat.is-lv {
  color: color-mix(in srgb, var(--dv-rose) 78%, var(--text-primary));
  background: color-mix(in srgb, var(--dv-rose) 10%, transparent);
  box-shadow: inset 0 0 0 1px color-mix(in srgb, var(--dv-rose) 30%, transparent);
}
.enh-hub .enh-idstats .t-ico { width: 18px; height: 18px; }
.enh-hub .enh-bio { margin-top: 4px; font-size: 12.5px; color: var(--text-secondary); }

/* the goal card: ONE coral glass; restate the body over the old skin (U2 rule 11) */
.enh-hub .enh-goalcard.glass {
  --c: var(--dv-coral);
  border: 0; border-radius: 22px; padding: 14px 15px; margin-top: 6px;
  color: var(--text-primary);
  background:
    radial-gradient(120% 90% at 0% 0%, color-mix(in srgb, var(--c) 22%, transparent), transparent 62%),
    linear-gradient(160deg, rgba(52, 46, 41, 0.72), rgba(30, 27, 24, 0.6));
  box-shadow:
    0 16px 30px -16px rgba(0, 0, 0, 0.75),
    0 0 26px -6px color-mix(in srgb, var(--c) 30%, transparent),
    inset 0 1px 0 rgba(255, 244, 230, 0.1),
    inset 0 -14px 26px -18px color-mix(in srgb, var(--c) 55%, transparent);
}
.enh-hub .enh-goalhead { gap: 10px; }
.enh-hub .enh-goalttl { flex: 1; min-width: 0; font-size: 15.5px; font-weight: 600; letter-spacing: -0.3px; }
.enh-hub .enh-goalhead .enh-stch {
  font-size: 11px; font-weight: 600; letter-spacing: 0; border-radius: 999px; padding: 4px 9px;
  color: color-mix(in srgb, var(--c) 75%, var(--text-primary));
  background: color-mix(in srgb, var(--c) 11%, rgba(245, 239, 230, 0.03));
  box-shadow: inset 0 0 0 1px color-mix(in srgb, var(--c) 30%, transparent);
}
/* the dimension chips: flat, in their own dimension colour */
.enh-hub .enh-lgdims { gap: 6px; margin: 10px 0 0; }
.enh-hub .enh-lgdims .lg-goalchip {
  min-width: 0; max-width: 100%; overflow: hidden; text-overflow: ellipsis; white-space: nowrap;
  padding: 4px 9px; gap: 5px; font-size: 11px; font-weight: 600;
  color: color-mix(in srgb, var(--dc) 75%, var(--text-primary));
  background: color-mix(in srgb, var(--dc) 11%, rgba(245, 239, 230, 0.03));
  box-shadow: inset 0 0 0 1px color-mix(in srgb, var(--dc) 30%, transparent);
}
.enh-hub .enh-lgdims .lg-goalchip i { box-shadow: 0 0 6px var(--dc); }
/* the three mini-cells: lit flat cells (never glass inside glass, U1 rule 5) */
.enh-hub .enh-goalcard .mz-mcells { display: grid; grid-auto-flow: column; grid-auto-columns: minmax(0, 1fr); gap: 5px; margin-top: 12px; }
.enh-hub .enh-goalcard .mz-mcells span {
  padding: 5px 0 4px; border-radius: 10px; color: var(--text-secondary);
  background: color-mix(in srgb, var(--c) 10%, rgba(245, 239, 230, 0.03));
  box-shadow: inset 0 0 0 1px color-mix(in srgb, var(--c) 28%, transparent);
}
.enh-hub .enh-goalcard .mz-mcells .mz-c-sage  { --c: var(--dv-sage); }
.enh-hub .enh-goalcard .mz-mcells .mz-c-lav   { --c: var(--dv-lav); }
.enh-hub .enh-goalcard .mz-mcells .mz-c-coral { --c: var(--dv-coral); }
.enh-hub .enh-goalcard .mz-mcells b { font-size: 14px; font-weight: 600; color: color-mix(in srgb, var(--c) 85%, var(--text-primary)); }
.enh-hub .enh-goalcard .mz-mcells small {
  font-size: 9px; font-weight: 500; letter-spacing: 0; text-transform: none; opacity: 1; color: var(--text-muted);
}
/* no active goal: the ＋ Új cél door is free space — dashed, no glass (bible §3 rank 4) */
.enh-hub .enh-newgoal.uv-empty {
  --c: var(--dv-coral); margin-top: 6px; border-radius: 20px;
  border: 1.5px dashed color-mix(in srgb, var(--c) 45%, transparent);
  background: rgba(245, 239, 230, 0.025); box-shadow: none;
  font-size: 15px; font-weight: 600; color: color-mix(in srgb, var(--c) 75%, var(--text-primary));
}

/* the mosaic: every tile is glass in its own accent (--c on the tile itself, U1 rule 4) */
.enh-hub .mz-mosaic { gap: 10px; }
.enh-hub .enh-t-celok   { --c: var(--dv-coral); --i: 2; }
.enh-hub .enh-t-suly    { --c: var(--dv-sky);   --i: 3; }
.enh-hub .enh-t-alvas   { --c: var(--dv-lav);   --i: 4; }
.enh-hub .enh-t-growth  { --c: var(--dv-lav);   --i: 5; }
.enh-hub .enh-t-naplo   { --c: var(--text-secondary); --i: 6; }
.enh-hub .enh-t-emberek { --c: var(--dv-rose);  --i: 7; }
.enh-hub .enh-t-rutin   { --c: var(--dv-amber); --i: 8; }
.enh-hub .mz-tile.enh-tile.glass {
  border: 0; border-radius: 20px; padding: 13px 13px 12px; min-height: 128px; gap: 4px;
  align-items: flex-start; text-align: left; color: var(--text-primary);
  background:
    radial-gradient(120% 90% at 0% 0%, color-mix(in srgb, var(--c) 22%, transparent), transparent 62%),
    linear-gradient(160deg, rgba(52, 46, 41, 0.72), rgba(30, 27, 24, 0.6));
  box-shadow:
    0 16px 30px -16px rgba(0, 0, 0, 0.75),
    0 0 26px -6px color-mix(in srgb, var(--c) 30%, transparent),
    inset 0 1px 0 rgba(255, 244, 230, 0.1),
    inset 0 -14px 26px -18px color-mix(in srgb, var(--c) 55%, transparent);
}
.enh-hub .enh-tile .mz-spotwrap { order: -1; flex: none; padding: 0; margin-bottom: auto; place-items: start; }
.enh-hub .enh-tile .mz-tile-top { margin-top: 8px; }
.enh-hub .enh-tile .mz-eyebrow {
  font-size: 9.5px; font-weight: 600; letter-spacing: 1.3px;
  color: color-mix(in srgb, var(--c) 70%, var(--text-primary));
}
.enh-hub .enh-tile .mz-tile-line {
  text-align: left; font-size: 14px; font-weight: 600; letter-spacing: -0.2px; line-height: 1.3;
  color: var(--text-primary); overflow-wrap: anywhere;
}
/* Rutin: the wide row tile */
.enh-hub .mz-tile.enh-tile.mz-tile-row.glass { flex-direction: row; align-items: center; gap: 12px; min-height: 0; }
.enh-hub .enh-tile.mz-tile-row .mz-spotwrap { order: 0; margin: 0; }
.enh-hub .enh-tile.mz-tile-row .mz-tile-top { margin-top: 0; }
.enh-hub .enh-tile.mz-tile-row .mz-tile-line { margin-top: 2px; font-size: 14px; }
.enh-hub .enh-tile.mz-tile-row .mz-tile-line small {
  display: block; margin: 2px 0 0; font-size: 10.5px; font-weight: 500; color: var(--text-muted);
}
.enh-hub .enh-tile.mz-tile-row .mz-chev { font-size: 20px; color: var(--text-muted); }
.enh-hub .enh-tile:focus-visible, .enh-hub .enh-goalcard:focus-visible, .enh-hub .enh-newgoal:focus-visible {
  outline: 2px solid var(--c); outline-offset: 2px;
}

@media (prefers-reduced-motion: no-preference) {
  @keyframes enh-xp-fill { from { stroke-dasharray: 0 100; } }
  .enh-hub .enh-xpprog { animation: enh-xp-fill 1.1s var(--uv-ease) 0.2s both; }
}

/* ── /uveg en hub ── */

/* ── uveg en celok (mezo-me75u.6) ── /me/goals, /me/goals/:id, /me/goals/new, /me/goals/signals + pillar catalog sheet ── */
/* Ranking (bible §3.4, prototype uveg-en.html#celok/#cel/#celuj/#jelek, sheet `pillar`). Every rule
   is scoped to a page root (.enc-celok, .enc-cel, .enc-wiz, .enc-jelek, all four also .enc-page) or
   to the catalog sheet (.enc-pcat): the `lg-*` family is shared with the Heti goals card (rule 13).
   Célok: the hero is a frameless halo with the six-arc PERMAH ring; the dimension band is flat
   chips; each active goal is a glass tile in its dimension colour; „＋ Új cél" is dashed; parked and
   done rows are flat; Jelek + Súlycél are glass rows with a lit well. Cél: the halo PageHero, the
   pillar cards glass with flat chips/dots/heatmap inside, ONE glass „Miért" card with flat HA/AKKOR
   rows, status actions as outline pills. Wizard: a form, so its cards wear glass and every control
   stays flat (pressed chips + toggles lit), CTAs lit coral. Jelek: flat rows, a glowing live dot. */

/* the ground: the aurora shows through; quiet principle footnote; eyebrows in the kit recipe */
.enc-page.mz-page { background: transparent; }
.enc-page .mz-page-body { padding: 2px 16px 20px; }
.enc-page .mz-principle {
  margin: 22px 10px 0; font-size: 12px; font-weight: 400; line-height: 1.55; text-align: center; color: var(--text-muted);
}
.enc-page .mz-eyebrow { font-size: 9.5px; font-weight: 600; letter-spacing: 1.3px; color: var(--text-muted); }
.enc-page .enc-sec { display: block; padding: 18px 2px 8px; }

/* the six PERMAH dimensions publish their accent as `--c` on the element that carries the class
   (bible U1 rule 4): the glass tile, the ring arc, the chip, the parked row. */
.enc-page .lg-d-p, .enc-pcat .lg-d-p { --c: var(--dv-amber); }
.enc-page .lg-d-e, .enc-pcat .lg-d-e { --c: var(--dv-lav); }
.enc-page .lg-d-r, .enc-pcat .lg-d-r { --c: var(--dv-rose); }
.enc-page .lg-d-m, .enc-pcat .lg-d-m { --c: var(--dv-coral); }
.enc-page .lg-d-a, .enc-pcat .lg-d-a { --c: var(--dv-sky); }
.enc-page .lg-d-h, .enc-pcat .lg-d-h { --c: var(--dv-sage); }

/* the glass body restated where an old `lg-*` / `mz-*` rule would keep its light skin (rule 11) */
.enc-celok .enc-tile.glass, .enc-celok .enc-xrow.glass, .enc-cel .lg-pillar.glass, .enc-cel .lg-why.glass,
.enc-wiz .lg-fcard.glass, .enc-wiz .lg-frame.glass, .enc-wiz .lg-pilcard.glass, .enc-wiz .lg-plan.glass,
.sheet.glass.enc-pcat {
  border: 0;
  background:
    radial-gradient(120% 90% at 0% 0%, color-mix(in srgb, var(--c) 22%, transparent), transparent 62%),
    linear-gradient(160deg, rgba(52, 46, 41, 0.72), rgba(30, 27, 24, 0.6));
  box-shadow:
    0 16px 30px -16px rgba(0, 0, 0, 0.75),
    0 0 26px -6px color-mix(in srgb, var(--c) 30%, transparent),
    inset 0 1px 0 rgba(255, 244, 230, 0.1),
    inset 0 -14px 26px -18px color-mix(in srgb, var(--c) 55%, transparent);
}

/* the head's lit action pill („＋ Új cél", „＋ Pillér") — a constructive CTA restates every colour */
.enc-page .enc-pill {
  margin-left: auto; display: inline-flex; align-items: center; gap: 6px; min-height: 36px; padding: 0 14px;
  border: 0; border-radius: 999px; font: inherit; font-size: 12.5px; font-weight: 700; white-space: nowrap; cursor: pointer;
  color: #191614; background: var(--dv-sage);
  box-shadow: 0 0 14px color-mix(in srgb, var(--dv-sage) 55%, transparent);
}
.enc-page .enc-pill:disabled { opacity: 0.45; box-shadow: none; cursor: default; }
.enc-page .enc-pill:focus-visible { outline: 2px solid var(--text-primary); outline-offset: 2px; }

/* the arrow reads in the surface's accent; „—" (too little data) stays muted */
.enc-page .lg-arrow.up, .enc-page .lg-arrow.flat, .enc-page .lg-arrow.down { color: color-mix(in srgb, var(--c) 80%, var(--text-primary)); }
.enc-page .lg-arrow.none { color: var(--text-muted); }

/* the seven dots (goal tile + pillar card): flat cells, a hit glows in the accent */
.enc-page .lg-wk7 { flex-wrap: wrap; gap: 4px; margin-top: auto; padding-top: 6px; }
.enc-page .lg-wk7 i { width: 12px; height: 12px; border: 0; background: rgba(245, 239, 230, 0.07); box-shadow: inset 0 0 0 1px var(--divider); }
.enc-page .lg-wk7 i.h { background: var(--c); box-shadow: 0 0 6px color-mix(in srgb, var(--c) 70%, transparent); }
.enc-page .lg-wk7 i.p { background: linear-gradient(90deg, var(--c) 50%, rgba(245, 239, 230, 0.07) 50%); box-shadow: none; }
.enc-page .lg-wk7 i.m { background: transparent; box-shadow: inset 0 0 0 1.5px color-mix(in srgb, var(--c) 45%, transparent); }
.enc-page .lg-wk7 i.n { background: transparent; border: 1px dashed rgba(245, 239, 230, 0.18); box-shadow: none; }
.enc-page .lg-wk7 .lbl { flex-basis: 100%; margin: 3px 0 0; font-size: 10.5px; font-weight: 500; color: var(--text-muted); }

/* the dimension chips: flat, tinted by their own dimension; a dimension with no goal dims */
.enc-page .lg-dimband { display: flex; flex-wrap: wrap; gap: 6px; }
.enc-page .lg-dimchip {
  min-width: 0; max-width: 100%; gap: 5px; padding: 4px 10px 4px 6px; border: 0; border-radius: 999px;
  font: inherit; font-size: 11px; font-weight: 600; letter-spacing: 0; text-transform: none;
  white-space: nowrap; overflow: hidden; text-overflow: ellipsis;
  color: color-mix(in srgb, var(--c) 75%, var(--text-primary));
  background: color-mix(in srgb, var(--c) 11%, rgba(245, 239, 230, 0.03));
  box-shadow: inset 0 0 0 1px color-mix(in srgb, var(--c) 30%, transparent);
}
.enc-page .lg-dimchip .t-ico { width: 16px; height: 16px; filter: none; }
.enc-page .lg-dimchip b { font-weight: 700; opacity: 0.7; }
.enc-page .lg-dimchip.empty { opacity: 0.42; }

/* ── Célok ── */
.enc-celok .enc-title { padding: 6px 2px 2px; }
.enc-celok .enc-title .nm {
  display: block; font-family: var(--ff-display); font-size: 26px; font-weight: 600; letter-spacing: -0.7px; color: var(--text-primary);
}
.enc-celok .enc-title .mz-eyebrow { margin-top: 3px; }
.enc-celok .enc-hero {
  --c: var(--dv-sage); --c2: var(--dv-lav);
  overflow-x: clip; display: flex; align-items: center; gap: 14px; margin: 0 -16px; padding: 10px 18px 12px;
}
/* the hero spans the body's gutters (-16px each side), so its overflow-x clip (rule 12) falls on
   the SCREEN edge; the halo box fades to nothing vertically inside itself, so no edge shows */
.enc-celok .enc-hero.uv-halo::before {
  left: 0; width: 100%; height: 300px; transform: translateY(-50%);
  background: radial-gradient(ellipse 150px 140px at 84px 50%,
    color-mix(in srgb, var(--c) 26%, transparent),
    color-mix(in srgb, var(--c2) 12%, transparent) 45%, transparent 100%);
}
.enc-celok .enc-hero-copy { flex: 1; min-width: 0; font-size: 13px; line-height: 1.5; color: var(--text-secondary); }
.enc-celok .enc-hero-copy strong { font-weight: 600; color: var(--text-primary); }
/* the PERMAH ring: six arcs on a faint track, a live arc thicker and glowing in its own colour */
.enc-celok .lg-ring { width: 132px; height: 132px; }
.enc-celok .lg-ring svg { width: 132px; height: 132px; overflow: visible; }
.enc-celok .lg-ring .arc { stroke: rgba(245, 239, 230, 0.08); stroke-width: 3.6; opacity: 1; }
.enc-celok .lg-ring .arc.live {
  stroke: var(--c); stroke-width: 5.5;
  filter: drop-shadow(0 0 3px color-mix(in srgb, var(--c) 75%, transparent));
}
.enc-celok .lg-ring .c b { font-size: 40px; font-weight: 300; letter-spacing: -2px; color: var(--text-primary); }
.enc-celok .lg-ring .c small { margin-top: 3px; font-size: 10px; font-weight: 500; letter-spacing: 0; text-transform: none; color: var(--text-muted); }
.enc-celok .lg-dimband { padding: 2px 0 14px; }
/* the goal tiles: glass in the dimension colour */
.enc-celok .mz-mosaic { gap: 10px; margin-bottom: 6px; }
.enc-celok .enc-tile.glass {
  display: flex; flex-direction: column; gap: 5px; min-width: 0; min-height: 170px; padding: 13px;
  border-radius: 20px; text-align: left; color: var(--text-primary);
}
.enc-celok .enc-tile-top { display: flex; align-items: flex-start; justify-content: space-between; }
.enc-celok .enc-tile .lg-arrow .g { font-size: 24px; font-weight: 300; line-height: 1; }
.enc-celok .enc-tile .mz-eyebrow { margin-top: 4px; color: color-mix(in srgb, var(--c) 70%, var(--text-primary)); }
.enc-celok .enc-tile .nm { font-size: 15px; font-weight: 600; letter-spacing: -0.3px; line-height: 1.25; overflow-wrap: anywhere; }
.enc-celok .enc-newtile.uv-empty {
  --c: var(--dv-sage);
  display: flex; flex-direction: column; align-items: center; justify-content: center; gap: 5px;
  min-height: 170px; border-radius: 20px; text-align: center; color: var(--text-primary);
}
.enc-celok .enc-newtile b { font-size: 15px; font-weight: 600; }
.enc-celok .enc-newtile small { font-size: 10.5px; color: var(--text-muted); }
/* parked / draft / done rows: flat cells */
.enc-celok .lg-parkrow {
  display: flex; align-items: center; gap: 12px; margin-top: 8px; padding: 11px 13px 11px 11px;
  border: 0; border-radius: 20px; color: var(--text-primary);
  background: rgba(245, 239, 230, 0.04); box-shadow: inset 0 0 0 1px var(--divider);
}
.enc-celok .lg-parkrow-nav { gap: 12px; border: 0; background: none; color: inherit; font: inherit; cursor: pointer; }
.enc-celok .lg-parkrow .t-ico { opacity: 0.85; }
.enc-celok .lg-parkrow .grow { flex: 1; min-width: 0; }
.enc-celok .lg-parkrow .nm { font-size: 14.5px; font-weight: 600; letter-spacing: -0.2px; color: var(--text-primary); }
.enc-celok .lg-parkrow .sb { margin-top: 2px; font-size: 11.5px; color: var(--text-secondary); }
.enc-celok .lg-parkrow .act {
  flex: none; margin-left: auto; min-height: 32px; padding: 6px 12px; border: 0; border-radius: 999px;
  font: inherit; font-size: 12px; font-weight: 600; cursor: pointer;
  color: color-mix(in srgb, var(--c, var(--dv-sage)) 80%, var(--text-primary));
  background: rgba(245, 239, 230, 0.05);
  box-shadow: inset 0 0 0 1px color-mix(in srgb, var(--c, var(--dv-sage)) 35%, transparent);
}
.enc-celok .lg-donerow { opacity: 0.85; }
.enc-celok .lg-donetick { flex: none; margin-left: auto; display: grid; place-items: center; }
/* Jelek + Súlycél: glass rows with a lit well */
.enc-celok .enc-xrow.glass {
  display: flex; align-items: center; gap: 12px; width: 100%; margin-top: 8px; padding: 11px 13px 11px 11px;
  border-radius: 20px; text-align: left; font: inherit; color: var(--text-primary); cursor: pointer;
}
.enc-celok .enc-xrow .grow { flex: 1; min-width: 0; }
.enc-celok .enc-xrow .nm { font-size: 14.5px; font-weight: 600; letter-spacing: -0.2px; }
.enc-celok .enc-xrow .sb { margin-top: 2px; font-size: 11.5px; color: var(--text-secondary); }
.enc-celok .enc-xrow .chev { flex: none; font-size: 20px; color: var(--text-muted); }

/* ── Cél ── */
.enc-cel .uv-hero .lg-arrow { display: inline-flex; align-items: baseline; gap: 8px; }
.enc-cel .uv-hero .lg-arrow .g { font-size: 44px; font-weight: 300; }
.enc-cel .uv-hero .lg-arrow .v { font-size: 58px; font-weight: 300; letter-spacing: -3px; color: var(--text-primary); }
.enc-cel .uv-hero .lg-arrow .v small { font-size: 20px; letter-spacing: -1px; margin-left: 2px; color: var(--text-muted); }
/* Hét / Hónap: a flat segmented control, the chosen one lit */
.enc-cel .enc-seg.lg-chiprow {
  display: inline-flex; gap: 0; margin: 2px 0 2px; padding: 3px; border-radius: 999px;
  background: rgba(245, 239, 230, 0.05); box-shadow: inset 0 0 0 1px var(--divider);
}
.enc-cel .enc-seg .lg-fchip {
  min-height: 32px; padding: 6px 14px; border: 0; border-radius: 999px; background: transparent;
  font-size: 12.5px; font-weight: 600; color: var(--text-secondary);
}
.enc-cel .enc-seg .lg-fchip.on { color: #191614; background: var(--c); box-shadow: 0 0 12px color-mix(in srgb, var(--c) 45%, transparent); }
.enc-cel .enc-none { padding: 0 2px 10px; }
/* the pillar card: glass; the kind chip, dots and heatmap flat inside */
.enc-cel .lg-pillar.glass { display: block; margin: 0 0 9px; padding: 13px 14px; border-radius: 20px; }
.enc-cel .lg-pillar .ph { gap: 9px; }
.enc-cel .lg-pillar .ph .nm { flex: 1; min-width: 0; font-size: 14.5px; font-weight: 600; color: var(--text-primary); }
.enc-cel .lg-pillar .ph .lg-arrow .g { font-size: 20px; }
.enc-cel .lg-pillar .lg-kind {
  display: inline-flex; min-width: 0; max-width: 100%; margin-top: 7px; padding: 4px 9px; border-radius: 999px;
  font-size: 11px; font-weight: 600; letter-spacing: 0; text-transform: none;
  white-space: nowrap; overflow: hidden; text-overflow: ellipsis;
  color: color-mix(in srgb, var(--c) 75%, var(--text-primary));
  background: color-mix(in srgb, var(--c) 11%, rgba(245, 239, 230, 0.03));
  box-shadow: inset 0 0 0 1px color-mix(in srgb, var(--c) 30%, transparent);
}
.enc-cel .lg-pillar .lg-kind.link { --c: var(--dv-lav); }
.enc-cel .lg-pillar .val { flex-wrap: wrap; gap: 8px; margin-top: 9px; }
.enc-cel .lg-pillar .val b { font-size: 26px; font-weight: 300; letter-spacing: -1px; color: var(--text-primary); }
.enc-cel .lg-pillar .val.is-none b { color: var(--text-muted); }
.enc-cel .lg-pillar .val small { font-size: 11.5px; color: var(--text-muted); }
.enc-cel .lg-pillar .lg-wk7 { margin-top: 8px; }
.enc-cel .lg-hm { grid-template-columns: repeat(14, 1fr); gap: 3px; margin-top: 9px; }
.enc-cel .lg-hm i { height: auto; aspect-ratio: 1; border: 0; border-radius: 3px; background: rgba(245, 239, 230, 0.06); }
.enc-cel .lg-hm i.h { background: var(--c); box-shadow: 0 0 5px color-mix(in srgb, var(--c) 60%, transparent); }
.enc-cel .lg-hm i.p { background: color-mix(in srgb, var(--c) 45%, transparent); }
.enc-cel .lg-hm i.m { background: rgba(245, 239, 230, 0.06); box-shadow: inset 0 0 0 1px color-mix(in srgb, var(--c) 35%, transparent); }
.enc-cel .lg-hm i.n { background: transparent; box-shadow: inset 0 0 0 1px var(--divider); }
/* a goal conflict: a flat amber-edged cell with the info icon */
.enc-cel .lg-conflict {
  align-items: center; gap: 10px; margin: 0 0 8px; padding: 10px 12px; border-radius: 15px;
  font-size: 12.5px; line-height: 1.45; color: var(--text-secondary);
  background: color-mix(in srgb, var(--dv-amber) 7%, rgba(245, 239, 230, 0.03));
  box-shadow: inset 0 0 0 1px color-mix(in srgb, var(--dv-amber) 30%, transparent);
}
/* Miért · ha–akkor: ONE glass card, flat HA/AKKOR rows inside */
.enc-cel .lg-why.glass { margin: 0 0 10px; padding: 15px 15px 14px; border-radius: 22px; }
.enc-cel .lg-why .q { font-family: var(--ff-serif); font-style: italic; font-size: 15px; font-weight: 400; line-height: 1.5; color: var(--text-primary); }
.enc-cel .lg-why .enc-obst { margin-top: 6px; font-size: 10.5px; color: var(--text-muted); }
.enc-cel .enc-ifthens { display: grid; gap: 6px; margin-top: 10px; }
.enc-cel .enc-ifthens > div { display: grid; gap: 6px; }
.enc-cel .lg-why .lg-ifthen {
  display: grid; grid-template-columns: 54px 1fr; gap: 8px; align-items: baseline; padding: 9px 11px;
  border: 0; border-radius: 13px; font-size: 13px; line-height: 1.45; color: var(--text-primary);
  background: rgba(245, 239, 230, 0.04); box-shadow: inset 0 0 0 1px var(--divider);
}
.enc-cel .lg-why .lg-ifthen .ha {
  width: auto; margin: 0; padding: 0; border-radius: 0; background: none; text-align: left;
  font-size: 10px; font-weight: 700; letter-spacing: 1.2px; color: color-mix(in srgb, var(--c) 75%, var(--text-primary));
}
.enc-cel .lg-why em { font-style: normal; color: var(--text-muted); }
/* the status actions: outline pills — Lezárás / Archiválás end a goal, so nothing here is lit */
.enc-cel .lg-actrow { flex-wrap: wrap; gap: 8px; margin: 14px 0 10px; }
.enc-cel .lg-actrow button {
  --c: var(--dv-coral);
  flex: 0 1 auto; min-height: 38px; padding: 9px 15px; border: 0; border-radius: 999px;
  font: inherit; font-size: 12.5px; font-weight: 600; cursor: pointer;
  color: color-mix(in srgb, var(--c) 70%, var(--text-primary));
  background: color-mix(in srgb, var(--c) 6%, transparent);
  box-shadow: inset 0 0 0 1px color-mix(in srgb, var(--c) 40%, transparent);
}
.enc-cel .lg-actrow button.is-lav { --c: var(--dv-lav); }
.enc-cel .lg-actrow button.is-sage { --c: var(--dv-sage); }
.enc-cel .lg-actrow button:disabled { opacity: 0.45; cursor: default; }

/* ── Új cél varázsló ── */
.enc-wiz .enc-wizhead { padding: 6px 2px 0; }
.enc-wiz .lg-wprog { display: grid; grid-template-columns: repeat(5, 1fr); gap: 5px; margin: 0 0 10px; }
.enc-wiz .lg-wprog i { height: 5px; border-radius: 3px; background: rgba(245, 239, 230, 0.08); }
.enc-wiz .lg-wprog i.f { background: var(--dv-coral); box-shadow: 0 0 8px var(--dv-coral); }
.enc-wiz .enc-stepl { display: flex; justify-content: space-between; gap: 10px; }
.enc-wiz .enc-stepl .eyebrow { font-size: 11px; font-weight: 600; letter-spacing: 0.4px; color: var(--text-muted); }
.enc-wiz .enc-stepl .eyebrow.is-lit { color: color-mix(in srgb, var(--dv-coral) 80%, var(--text-primary)); }
.enc-wiz .enc-wiztitle { padding: 10px 2px 4px; }
.enc-wiz .enc-wiztitle h1 {
  margin: 4px 0 0; font-family: var(--ff-display); font-size: 25px; font-weight: 600; letter-spacing: -0.7px; color: var(--text-primary);
}
.enc-wiz .enc-wizbody { padding: 8px 0 0; }
.enc-wiz .enc-sec { padding: 14px 2px 8px; }
.enc-wiz .enc-gap { margin-top: 10px; }
.enc-wiz .enc-quiet { margin: 0; padding: 10px 2px 0; font-size: 12.5px; line-height: 1.5; color: var(--text-muted); }
/* every step's card is glass (coral by default, Mezo's reading lavender, the summary its dimension) */
.enc-wiz .lg-fcard.glass { --c: var(--dv-coral); margin: 0 0 10px; padding: 13px 14px 14px; border-radius: 20px; }
.enc-wiz .lg-fcard.glass.is-lav { --c: var(--dv-lav); }
.enc-wiz .lg-flabel { margin-bottom: 7px; font-size: 9.5px; font-weight: 600; letter-spacing: 1.3px; color: var(--text-muted); }
.enc-wiz .enc-fcopy { font-size: 13px; line-height: 1.5; color: var(--text-secondary); }
.enc-wiz .lg-fin {
  display: block; width: 100%; min-width: 0; padding: 11px 13px; border: 0; border-radius: 13px;
  font: inherit; font-size: 14px; color: var(--text-primary); color-scheme: dark; outline: none; resize: none;
  background: rgba(245, 239, 230, 0.05); box-shadow: inset 0 0 0 1px var(--divider);
}
.enc-wiz .lg-fin::placeholder { color: var(--text-muted); }
.enc-wiz .lg-fin:focus { box-shadow: inset 0 0 0 1.5px var(--c); }
.enc-wiz .lg-aiwait {
  margin: 0 0 10px; padding: 14px; border-radius: 15px; font-size: 12.5px; color: var(--text-secondary);
  background: rgba(245, 239, 230, 0.04); box-shadow: inset 0 0 0 1px var(--divider);
}
/* the frame card: amber with the info icon, sage with the tick once the inner frame is accepted */
.enc-wiz .lg-frame.glass { --c: var(--dv-amber); margin: 0 0 10px; padding: 13px 14px 14px; border-radius: 20px; }
.enc-wiz .lg-frame.glass.ok { --c: var(--dv-sage); }
.enc-wiz .lg-frame .lb, .enc-wiz .lg-frame.ok .lb {
  display: flex; align-items: center; gap: 9px; font-size: 14.5px; font-weight: 600; color: var(--text-primary);
}
.enc-wiz .enc-mark { flex: none; display: grid; place-items: center; }
.enc-wiz .lg-frame p { margin-top: 8px; font-size: 13px; line-height: 1.5; color: var(--text-secondary); }
.enc-wiz .lg-frame p b { font-weight: 600; color: var(--text-primary); }
/* chips: flat, the pressed one lit in the card's accent */
.enc-wiz .enc-chips { display: flex; flex-wrap: wrap; gap: 6px; margin-top: 10px; }
.enc-wiz .enc-chips .chip {
  min-width: 0; max-width: 100%; min-height: 34px; padding: 7px 12px; border: 0; border-radius: 999px;
  font: inherit; font-size: 12px; font-weight: 600; white-space: nowrap; overflow: hidden; text-overflow: ellipsis; cursor: pointer;
  color: var(--text-secondary); background: rgba(245, 239, 230, 0.05); box-shadow: inset 0 0 0 1px var(--divider);
}
.enc-wiz .enc-chips .chip[aria-pressed='true'] {
  color: #191614; background: var(--c); box-shadow: 0 0 12px color-mix(in srgb, var(--c) 50%, transparent);
}
.enc-wiz button.lg-dimchip { min-height: 32px; cursor: pointer; }
.enc-wiz .lg-dimchip.empty { opacity: 0.55; }
.enc-wiz .lg-dimchip[aria-pressed='true'] {
  opacity: 1; color: #191614; background: var(--c); box-shadow: 0 0 12px color-mix(in srgb, var(--c) 50%, transparent);
}
/* the proposed pillars: glass rows with a lit toggle */
.enc-wiz .lg-pilcard.glass { display: flex; align-items: center; gap: 12px; margin: 0 0 8px; padding: 11px 13px 11px 11px; border-radius: 20px; }
.enc-wiz .lg-pilcard.off { opacity: 0.55; }
.enc-wiz .lg-pilcard .grow { flex: 1; min-width: 0; }
.enc-wiz .lg-pilcard b { font-size: 14.5px; font-weight: 600; color: var(--text-primary); }
.enc-wiz .lg-pilcard small { margin-top: 2px; font-size: 11.5px; color: var(--text-secondary); }
.enc-wiz .lg-togg { flex: none; width: 40px; height: 24px; border-radius: 999px; background: rgba(245, 239, 230, 0.1); }
.enc-wiz .lg-togg::after { top: 3px; left: 3px; width: 18px; height: 18px; background: var(--text-secondary); }
.enc-wiz .lg-togg.on { background: color-mix(in srgb, var(--c) 70%, transparent); box-shadow: 0 0 10px color-mix(in srgb, var(--c) 50%, transparent); }
.enc-wiz .lg-togg.on::after { left: 19px; background: var(--text-primary); }
.enc-wiz .lg-addrow.uv-empty {
  --c: var(--dv-coral);
  display: flex; align-items: center; justify-content: center; width: 100%; min-height: 46px; margin-top: 4px; padding: 12px;
  border: 1.5px dashed color-mix(in srgb, var(--c) 45%, transparent); border-radius: 20px;
  font: inherit; font-size: 14px; font-weight: 600; color: var(--text-primary); cursor: pointer;
}
.enc-wiz .lg-addrow:disabled { opacity: 0.45; cursor: default; }
/* the if-then plan cards: glass, the HA/AKKOR tags flat, the text areas bare */
.enc-wiz .lg-plan.glass { --c: var(--dv-coral); margin: 0 0 8px; padding: 12px 13px 11px; border-radius: 20px; }
.enc-wiz .lg-prow { align-items: flex-start; gap: 8px; }
.enc-wiz .lg-prow + .lg-prow { margin-top: 6px; padding-top: 7px; border-top: 1px solid var(--divider); }
.enc-wiz .lg-ifthen.ha {
  display: block; flex: none; width: 54px; margin: 0; padding: 4px 0 0; border: 0; border-radius: 0; background: none;
  text-align: left; font-size: 10px; font-weight: 700; letter-spacing: 1.2px; color: color-mix(in srgb, var(--c) 75%, var(--text-primary));
}
.enc-wiz .lg-ptxt { font-size: 13px; line-height: 1.45; color: var(--text-primary); color-scheme: dark; background: transparent; }
.enc-wiz .lg-pfoot {
  flex-wrap: wrap; gap: 6px; margin-top: 8px; padding-top: 7px; border-top: 1px solid var(--divider);
  font-size: 11px; font-weight: 500; color: var(--text-muted);
}
.enc-wiz .enc-own { margin-left: auto; }
/* Összegzés: the goal card in its dimension colour, the measures + rules as flat rows */
.enc-wiz .enc-sumhead { display: flex; align-items: flex-start; gap: 12px; }
.enc-wiz .enc-sumhead .grow { flex: 1; min-width: 0; }
.enc-wiz .enc-sumhead b { display: block; font-size: 16px; font-weight: 600; letter-spacing: -0.3px; color: var(--text-primary); overflow-wrap: anywhere; }
.enc-wiz .enc-sumhead .lg-dimband { margin-top: 8px; }
.enc-wiz .enc-quote { margin-top: 10px; font-family: var(--ff-serif); font-style: italic; font-size: 14.5px; line-height: 1.5; color: var(--text-primary); }
.enc-wiz .lg-sumpil {
  display: flex; align-items: center; gap: 10px; margin: 0 0 6px; padding: 10px 12px; border: 0; border-radius: 15px;
  background: rgba(245, 239, 230, 0.04); box-shadow: inset 0 0 0 1px var(--divider);
}
.enc-wiz .lg-sumpil b { font-size: 13px; font-weight: 600; color: var(--text-primary); }
.enc-wiz .lg-sumpil small { margin-top: 2px; font-size: 11px; color: var(--text-muted); }
/* the CTAs: lit coral (every colour restated, rule 36), „Mentés tervezettként" a flat ghost */
.enc-wiz .enc-wizfoot { display: flex; flex-wrap: wrap; gap: 10px; padding: 10px 0 16px; }
.enc-wiz .enc-wizfoot > button { flex: 1 1 140px; min-width: 0; }
.enc-wiz .cta-primary {
  --c: var(--dv-coral);
  width: auto; display: inline-flex; align-items: center; justify-content: center; gap: 8px; min-height: 46px; padding: 12px 16px;
  border: 0; border-radius: 999px; font: inherit; font-size: 14.5px; font-weight: 700; white-space: nowrap; cursor: pointer;
  color: #191614; background: var(--c);
  box-shadow: 0 12px 26px -14px color-mix(in srgb, var(--c) 90%, transparent), 0 0 18px -4px color-mix(in srgb, var(--c) 60%, transparent);
}
.enc-wiz .cta-primary .t-ico { filter: none; }
.enc-wiz .cta-primary:disabled { opacity: 0.45; box-shadow: none; cursor: default; }
.enc-wiz .cta-primary.enc-retry { min-height: 40px; margin-top: 12px; }
.enc-wiz .cta-ghost {
  min-height: 46px; padding: 12px 16px; border: 0; border-radius: 999px; font: inherit; font-size: 14px; font-weight: 600; cursor: pointer;
  color: var(--text-secondary); background: rgba(245, 239, 230, 0.05); box-shadow: inset 0 0 0 1px var(--divider);
}
.enc-wiz .cta-ghost:disabled { opacity: 0.45; cursor: default; }

/* ── Jelek ── */
.enc-jelek .lg-sighint { margin: 0; padding: 2px 8px 4px; font-size: 12.5px; line-height: 1.5; text-align: center; color: var(--text-secondary); }
.enc-jelek .lg-sighead { margin: 18px 2px 8px; }
.enc-jelek .lg-sighead .cnt { font-size: 11px; color: var(--text-muted); }
.enc-jelek .lg-sig {
  display: grid; grid-template-columns: 40px minmax(0, 1fr) auto; gap: 10px; align-items: center;
  margin: 0 0 6px; padding: 10px 12px; border: 0; border-radius: 15px;
  background: rgba(245, 239, 230, 0.04); box-shadow: inset 0 0 0 1px var(--divider);
}
.enc-jelek .lg-sig b { font-size: 13.5px; font-weight: 600; color: var(--text-primary); }
.enc-jelek .lg-sig small { margin-top: 1px; font-size: 11px; color: var(--text-muted); }
.enc-jelek .lg-sig i.live { width: 9px; height: 9px; background: var(--dv-sage); box-shadow: 0 0 8px var(--dv-sage); }
.enc-jelek .lg-sig i.dead { width: 9px; height: 9px; background: transparent; box-shadow: inset 0 0 0 1.5px var(--text-muted); }
.enc-jelek .lg-sig.off { opacity: 0.5; }
.enc-jelek .lg-sig.off .t-ico { filter: grayscale(0.6); }
.enc-jelek .lg-sigchips { gap: 4px; margin-top: 5px; }
.enc-jelek .lg-sigchips span {
  min-width: 0; max-width: 100%; padding: 3px 8px; border-radius: 999px; white-space: nowrap; overflow: hidden; text-overflow: ellipsis;
  font-size: 10.5px; font-weight: 600; color: color-mix(in srgb, var(--dv-sage) 75%, var(--text-primary));
  background: color-mix(in srgb, var(--dv-sage) 11%, rgba(245, 239, 230, 0.03));
  box-shadow: inset 0 0 0 1px color-mix(in srgb, var(--dv-sage) 30%, transparent);
}

/* ── the pillar catalog: a floating glass sheet (U2 rule 15), its entries flat chips ── */
.sheet.glass.enc-pcat {
  --c: var(--dv-sage);
  position: absolute; left: 10px; right: 10px; bottom: calc(10px + env(safe-area-inset-bottom));
  overflow-x: hidden; overflow-y: auto; border-radius: 30px; padding: 4px 18px 18px;
}
.sheet.glass.enc-pcat .sheet-handle { background: rgba(245, 239, 230, 0.22); }
.enc-pcat .enc-pcat-head { display: flex; align-items: center; gap: 12px; margin: 4px 0 4px; }
.enc-pcat .enc-pcat-head h2 {
  flex: 1; min-width: 0; margin: 0; font-family: var(--ff-display); font-size: 21px; font-weight: 600; letter-spacing: -0.6px; color: var(--text-primary);
}
.enc-pcat .enc-pcat-x {
  flex: none; width: 36px; height: 36px; padding: 0; border: 0; border-radius: 50%; display: grid; place-items: center; cursor: pointer;
  color: var(--text-secondary); background: rgba(245, 239, 230, 0.06); box-shadow: inset 0 0 0 1px var(--divider);
}
.enc-pcat .enc-pcat-sec { margin-top: 14px; }
.enc-pcat .enc-pcat-sec .mz-eyebrow { display: block; font-size: 9.5px; font-weight: 600; letter-spacing: 1.3px; color: var(--text-muted); }
.enc-pcat .enc-pcat-chips { display: flex; flex-wrap: wrap; gap: 6px; margin-top: 7px; }
.enc-pcat .enc-pcat-chips .chip {
  min-width: 0; max-width: 100%; min-height: 34px; padding: 7px 12px; border: 0; border-radius: 999px;
  font: inherit; font-size: 12px; font-weight: 600; white-space: nowrap; overflow: hidden; text-overflow: ellipsis; cursor: pointer;
  color: var(--text-secondary); background: rgba(245, 239, 230, 0.05); box-shadow: inset 0 0 0 1px var(--divider);
}
.enc-pcat .enc-pcat-chips .chip:focus-visible, .enc-pcat .enc-pcat-chips .chip:hover {
  color: var(--text-primary); box-shadow: inset 0 0 0 1px color-mix(in srgb, var(--c) 45%, transparent);
}
.enc-pcat .enc-pcat-foot { margin-top: 16px; }
.enc-pcat .cta-ghost {
  width: 100%; min-height: 42px; padding: 10px 16px; border: 0; border-radius: 999px; font: inherit; font-size: 13.5px; font-weight: 600; cursor: pointer;
  color: var(--text-secondary); background: rgba(245, 239, 230, 0.05); box-shadow: inset 0 0 0 1px var(--divider);
}
/* ── /uveg en celok ── */

/* ── uveg en sulycel (mezo-me75u.6) ── /me/goals/weight(+/diet,/segment,/plans,/guards,/suggestions/:id,/new) + goal gate ── */
/* Ranking (bible §3.4, prototype uveg-en.html#sulycel / #sulyresz / #sulyuj): the course hero and
   every sub-page hero are FRAMELESS halos; the mosaic tiles and the sub-pages' content cards are
   glass, one accent each; cells, lanes, diff rows and chips inside are flat; empty is dashed.
   Scopes: `.goal-hub-page` (hub + empty), `.uv-goal` (the five sub-pages), `.goal-planner-page`,
   `.goal-gate`, `.goal-attach-sheet` — the old `goal-*` classes are shared with the goal
   settings page (not re-dressed yet), so nothing here is unscoped (U2 rule 13). */
.goal-hub-page.mz-page, .uv-goal.mz-page, .goal-planner-page.mz-page { background: transparent; }
.goal-hub-page, .goal-planner-page { --c: var(--dv-coral); }
.goal-detail-diet-page.uv-goal { --c: var(--dv-sage); }
.goal-detail-segment-page.uv-goal { --c: var(--dv-amber); }
.goal-detail-plans-page.uv-goal { --c: var(--dv-sky); }
.goal-detail-guards-page.uv-goal { --c: var(--dv-lav); }
.goal-suggestion-page.uv-goal { --c: var(--dv-coral); }

/* ── hub: head action + title ── */
.goal-hub-page .pgact.goal-new-pill {
  min-height: 38px; padding: 0 14px; font-size: 12.5px; font-weight: 700;
  color: #191614; background: var(--dv-coral);
  box-shadow: 0 0 14px color-mix(in srgb, var(--dv-coral) 55%, transparent);
}
.goal-hub-page .goal-hub-title .mz-eyebrow { font: 600 9.5px/1.3 var(--ff-body); letter-spacing: 1.4px; color: var(--text-muted); }
.goal-hub-page .goal-hub-title h2 { margin-top: 3px; font-size: 19px; font-weight: 600; letter-spacing: -0.5px; line-height: 1.2; color: var(--text-primary); }

/* ── hub: the course hero is a frameless coral halo (U2 rule 12: clip it at 320px) ── */
.goal-hub-page .goal-course-hero.uv-halo {
  --c: var(--dv-coral);
  overflow: visible; overflow-x: clip; min-height: 0; border: 0; border-radius: 0;
  background: none; box-shadow: none;
}
.goal-hub-page .goal-course-hero.uv-halo::before {
  left: 70%; top: 46%; width: 340px; height: 260px;
  background: radial-gradient(ellipse at 50% 50%,
    color-mix(in srgb, var(--dv-coral) 26%, transparent),
    color-mix(in srgb, var(--dv-sage) 14%, transparent) 42%, transparent 66%);
}
.goal-hub-page .goal-course-hero::after { display: none; }
.goal-hub-page .goal-course-open { padding: 4px 2px 6px; }
.goal-hub-page .goal-course-top { display: grid; grid-template-columns: minmax(0, 1fr) 112px; gap: 12px; align-items: center; }
.goal-hub-page .goal-course-message .mz-eyebrow {
  font: 600 9.5px/1.3 var(--ff-body); letter-spacing: 1.4px;
  color: color-mix(in srgb, var(--status, var(--dv-sage)) 78%, var(--text-primary));
}
.goal-hub-page .goal-course-hero.is-on_track { --status: var(--dv-sage); }
