  padding: 3px 8px; border-radius: 999px; font-size: 10.5px; color: var(--text-secondary);
  background: rgba(245, 239, 230, 0.05); box-shadow: inset 0 0 0 1px var(--divider);
}
.uv-goal .gs-reason-card .gs-reason-orb {
  position: relative; right: auto; top: auto; flex: 0 0 auto; width: 72px; height: 72px; padding: 8px;
  font-size: 12.5px; font-weight: 700; color: color-mix(in srgb, var(--c) 80%, var(--text-primary));
  background: radial-gradient(circle at 35% 28%, #3A332D, color-mix(in srgb, var(--c) 16%, #1E1B18));
  box-shadow: inset 0 1px 0 rgba(255, 244, 230, 0.08),
    inset 0 -8px 14px -8px color-mix(in srgb, var(--c) 70%, transparent),
    0 0 14px -4px color-mix(in srgb, var(--c) 55%, transparent);
}
.uv-goal .gs-section-head { font: 600 9.5px/1.3 var(--ff-body); letter-spacing: 1.4px; color: var(--text-muted); }
.uv-goal .gs-section-head b { color: var(--text-secondary); background: rgba(245, 239, 230, 0.05); box-shadow: inset 0 0 0 1px var(--divider); }
.uv-goal .gdiff-grid { gap: 6px; }
.uv-goal .gdiff-row {
  min-height: 0; grid-template-rows: auto auto auto; row-gap: 4px; padding: 11px 13px 10px;
  border: 0; border-radius: 16px; filter: none;
  background: rgba(245, 239, 230, 0.04); box-shadow: inset 0 0 0 1px var(--divider);
}
.uv-goal .gdiff-row.gdiff-unchanged { opacity: 0.62; }
.uv-goal .gdiff-label { font-weight: 600; letter-spacing: 1.2px; color: var(--text-muted); }
.uv-goal .gdiff-current small, .uv-goal .gdiff-proposed small { font-weight: 500; letter-spacing: 0.6px; color: var(--text-muted); }
.uv-goal .gdiff-current strong { color: var(--text-secondary); font-weight: 600; }
.uv-goal .gdiff-proposed strong { color: color-mix(in srgb, var(--dv-coral) 80%, var(--text-primary)); font-weight: 600; }
.uv-goal .gdiff-arrow { color: var(--text-muted); background: rgba(245, 239, 230, 0.05); box-shadow: inset 0 0 0 1px var(--divider); }
.uv-goal .gdiff-delta {
  font-size: 10.5px; font-weight: 600; color: color-mix(in srgb, var(--dv-coral) 80%, var(--text-primary));
  background: color-mix(in srgb, var(--dv-coral) 11%, rgba(245, 239, 230, 0.03));
  box-shadow: inset 0 0 0 1px color-mix(in srgb, var(--dv-coral) 30%, transparent);
}
.uv-goal .gdiff-unchanged .gdiff-delta { color: var(--text-muted); background: rgba(245, 239, 230, 0.05); box-shadow: inset 0 0 0 1px var(--divider); }
/* messages: flat, lit by their meaning (amber warns, coral blocks) */
.uv-goal .gs-message, .uv-goal .gs-history {
  --m: var(--dv-amber);
  border-radius: 16px; padding: 13px 14px;
  background: color-mix(in srgb, var(--m) 9%, rgba(245, 239, 230, 0.03));
  box-shadow: inset 0 0 0 1px color-mix(in srgb, var(--m) 35%, transparent);
}
.uv-goal .gs-message.gs-blocker, .uv-goal .gs-message.gs-stale { --m: var(--dv-coral); }
.uv-goal .gs-history { --m: var(--dv-sage); }
.uv-goal .gs-message strong, .uv-goal .gs-history strong { color: color-mix(in srgb, var(--m) 80%, var(--text-primary)); }
.uv-goal .gs-message p, .uv-goal .gs-history p { font-size: 12px; color: var(--text-secondary); }
.uv-goal .gs-history > span { color: var(--text-secondary); background: rgba(245, 239, 230, 0.05); box-shadow: inset 0 0 0 1px var(--divider); }
.uv-goal .gs-refresh {
  font-size: 12px; font-weight: 700; color: #191614; background: var(--dv-coral);
  box-shadow: 0 0 14px color-mix(in srgb, var(--dv-coral) 55%, transparent);
}
/* actions: apply lit coral (constructive) · „Most nem" ghost · „Javaslat elvetése" the flat
   coral outline (destructive, U4 rule 29 — never the page's lit primary) */
.uv-goal .gs-actions { grid-template-columns: 1fr 1fr; }
.uv-goal .gs-actions .gs-apply, .uv-goal .gs-actions .gs-dismiss-confirm { grid-column: 1 / -1; }
.uv-goal .gs-actions > button { min-height: 44px; border-radius: 999px; font-size: 13px; }
.uv-goal .gs-actions .gs-apply {
  display: inline-flex; align-items: center; justify-content: center; gap: 8px;
  border: 0; font-weight: 700; color: #191614; background: var(--dv-coral);
  box-shadow: 0 0 14px color-mix(in srgb, var(--dv-coral) 55%, transparent);
}
.uv-goal .gs-actions .gs-apply .t-ico { filter: drop-shadow(0 1px 2px rgba(0, 0, 0, 0.3)); }
.uv-goal .gs-actions .gs-apply:disabled { opacity: 0.42; box-shadow: none; }
.uv-goal .gs-actions .gs-later {
  border: 0; font-weight: 600; color: var(--text-secondary);
  background: rgba(245, 239, 230, 0.05); box-shadow: inset 0 0 0 1px var(--divider);
}
.uv-goal .gs-actions .gs-dismiss {
  border: 0; font-weight: 600; text-decoration: none;
  color: color-mix(in srgb, var(--dv-coral) 70%, var(--text-primary));
  background: color-mix(in srgb, var(--dv-coral) 6%, transparent);
  box-shadow: inset 0 0 0 1px color-mix(in srgb, var(--dv-coral) 40%, transparent);
}
.uv-goal .gs-dismiss-confirm {
  border-radius: 16px; padding: 9px 10px; font-size: 12px; color: var(--text-secondary);
  background: color-mix(in srgb, var(--dv-coral) 7%, rgba(245, 239, 230, 0.03));
  box-shadow: inset 0 0 0 1px color-mix(in srgb, var(--dv-coral) 30%, transparent);
}
.uv-goal .gs-dismiss-confirm button {
  padding: 8px 11px; font-size: 11.5px; font-weight: 600; color: var(--text-secondary);
  background: rgba(245, 239, 230, 0.05); box-shadow: inset 0 0 0 1px var(--divider);
}
.uv-goal .gs-dismiss-confirm button:first-of-type {
  color: color-mix(in srgb, var(--dv-coral) 70%, var(--text-primary));
  background: color-mix(in srgb, var(--dv-coral) 8%, transparent);
  box-shadow: inset 0 0 0 1px color-mix(in srgb, var(--dv-coral) 45%, transparent);
}

/* ── goal gate: a dimmed scrim, ONE coral glass card (not a GlassBox — the page's own overlay) ── */
.goal-gate {
  position: absolute; inset: 0; z-index: 60; display: grid; place-items: center; padding: 18px;
  background: rgba(12, 10, 9, 0.62);
  -webkit-backdrop-filter: blur(4px); backdrop-filter: blur(4px);
}
.goal-gate .goal-gate-card.glass { width: 100%; max-width: 380px; padding: 14px 16px 16px; border-radius: 26px; }
.goal-gate .goal-gate-card.glass::after { display: none; animation: none; }
.goal-gate .goal-gate-top { display: flex; align-items: center; justify-content: space-between; margin-bottom: 10px; }
.goal-gate .goal-gate-eb {
  font: 600 9.5px/1.3 var(--ff-body); letter-spacing: 1.4px; text-transform: uppercase;
  color: color-mix(in srgb, var(--c) 75%, var(--text-primary));
}
.goal-gate .goal-gate-x {
  width: 32px; height: 32px; border: 0; border-radius: 50%; display: grid; place-items: center; cursor: pointer;
  color: var(--text-secondary); background: rgba(245, 239, 230, 0.06); box-shadow: inset 0 0 0 1px var(--divider);
}
.goal-gate .goal-gate-title { display: flex; align-items: center; gap: 12px; margin-bottom: 10px; }
.goal-gate .goal-gate-title h3 { margin: 0; font-size: 19px; font-weight: 600; letter-spacing: -0.5px; color: var(--text-primary); }
.goal-gate .goal-gate-lead { margin: 0; font-size: 12.5px; line-height: 1.5; color: var(--text-secondary); }
.goal-gate .goal-gate-lead b { color: var(--text-primary); font-weight: 600; }
.goal-gate .goal-gate-chips { display: flex; flex-wrap: wrap; gap: 6px; margin-top: 12px; }
.goal-gate .goal-gate-chip {
  display: inline-flex; align-items: center; gap: 5px; min-width: 0; padding: 4px 9px; border-radius: 999px;
  font-size: 11px; font-weight: 600;
  color: color-mix(in srgb, var(--dv-amber) 75%, var(--text-primary));
  background: color-mix(in srgb, var(--dv-amber) 11%, rgba(245, 239, 230, 0.03));
  box-shadow: inset 0 0 0 1px color-mix(in srgb, var(--dv-amber) 30%, transparent);
}
.goal-gate .goal-gate-chip .t-ico { filter: none; }
.goal-gate .goal-gate-cta {
  width: 100%; height: 44px; margin-top: 14px; border: 0; border-radius: 999px; cursor: pointer;
  font: 700 13.5px/1 var(--ff-body); color: #191614; background: var(--c);
  box-shadow: 0 0 14px color-mix(in srgb, var(--c) 55%, transparent);
}
.goal-gate .goal-gate-hint { display: block; margin-top: 8px; text-align: center; font-size: 10.5px; color: var(--text-muted); }

/* ── planner (a FORM): the chosen trajectory is the one glass card, everything else flat ── */
.goal-planner-page .gp-steps { padding: 6px 2px 0; }
.goal-planner-page .gp-prog { display: grid; grid-template-columns: repeat(2, 1fr); gap: 5px; margin-bottom: 12px; }
.goal-planner-page .gp-prog button { height: 5px; padding: 0; border: 0; border-radius: 3px; background: rgba(245, 239, 230, 0.08); }
.goal-planner-page .gp-prog button.is-on { background: var(--c); box-shadow: 0 0 8px var(--c); }
.goal-planner-page .gp-count { font-size: 11px; font-weight: 600; letter-spacing: 1px; color: var(--text-muted); }
.goal-planner-page .gp-title { padding: 6px 2px 4px; }
.goal-planner-page .gp-title .mz-eyebrow { font: 600 9.5px/1.3 var(--ff-body); letter-spacing: 1.4px; color: color-mix(in srgb, var(--c) 70%, var(--text-primary)); }
.goal-planner-page .gp-title h1 { margin: 4px 0 0; font-size: 25px; font-weight: 600; letter-spacing: -0.7px; line-height: 1.15; color: var(--text-primary); }
.goal-planner-page .gp-step0 { padding: 4px 2px 0; }
.goal-planner-page .gp-label {
  display: block; margin: 14px 2px 8px; font: 600 9.5px/1.3 var(--ff-body); letter-spacing: 1.4px;
  text-transform: uppercase; color: var(--text-muted);
}
.goal-planner-page .gp-trajs { display: grid; gap: 8px; }
.goal-planner-page .gp-traj {
  display: flex; align-items: center; gap: 12px; width: 100%; padding: 13px; border: 0; border-radius: 18px;
  text-align: left; font: inherit; color: var(--text-primary); cursor: pointer;
  background: rgba(245, 239, 230, 0.04); box-shadow: inset 0 0 0 1px var(--divider);
}
.goal-planner-page .gp-traj .t-ico { filter: grayscale(0.3); opacity: 0.8; }
.goal-planner-page .gp-traj.glass {
  --c: var(--dv-coral);
  background:
    radial-gradient(120% 90% at 0% 0%, color-mix(in srgb, var(--c) 22%, transparent), transparent 62%),
    linear-gradient(160deg, rgba(52, 46, 41, 0.72), rgba(30, 27, 24, 0.6));
  box-shadow:
    0 16px 30px -16px rgba(0, 0, 0, 0.75),
    0 0 26px -6px color-mix(in srgb, var(--c) 30%, transparent),
    inset 0 1px 0 rgba(255, 244, 230, 0.1),
    inset 0 -14px 26px -18px color-mix(in srgb, var(--c) 55%, transparent);
}
.goal-planner-page .gp-traj.glass .t-ico {
  opacity: 1;
  filter: drop-shadow(0 6px 7px rgba(0, 0, 0, 0.55)) drop-shadow(0 0 10px color-mix(in srgb, var(--c) 40%, transparent));
}
.goal-planner-page .gp-traj-copy { min-width: 0; }
.goal-planner-page .gp-traj strong { display: block; font-size: 15px; font-weight: 600; }
.goal-planner-page .gp-traj small { display: block; margin-top: 1px; font-size: 11.5px; color: var(--text-secondary); }
.goal-planner-page .gp-guards { display: flex; flex-wrap: wrap; gap: 8px; }
.goal-planner-page .gp-guard {
  display: inline-flex; align-items: center; gap: 6px; min-width: 0; padding: 7px 12px; border: 0; border-radius: 999px;
  font: 600 12px/1.2 var(--ff-body); color: var(--text-secondary); cursor: pointer;
  background: rgba(245, 239, 230, 0.05); box-shadow: inset 0 0 0 1px var(--divider);
}
.goal-planner-page .gp-guard.is-on { color: #191614; background: var(--c); box-shadow: 0 0 12px color-mix(in srgb, var(--c) 50%, transparent); }
.goal-planner-page .gp-guard .t-ico { filter: none; }
.goal-planner-page .gp-step1 { padding: 4px 2px 0; }
.goal-planner-page .gp-fields { display: grid; gap: 12px; }
.goal-planner-page .gp-field { display: grid; gap: 6px; min-width: 0; }
.goal-planner-page .gp-field .gp-label { margin: 0 2px; }
.goal-planner-page .gp-two { display: flex; gap: 10px; }
.goal-planner-page .gp-two > * { min-width: 0; }
.goal-planner-page .gp-inp {
  padding: 10px 12px; border-radius: 14px;
  background: rgba(245, 239, 230, 0.05); box-shadow: inset 0 0 0 1px var(--divider);
}
.goal-planner-page .gp-inp:focus-within { box-shadow: inset 0 0 0 1.5px var(--c); }
.goal-planner-page .gp-inp input, .goal-planner-page .gp-inp textarea {
  width: 100%; min-width: 0; border: 0; outline: none; background: transparent;
  font: 14px/1.4 var(--ff-body); color: var(--text-primary); color-scheme: dark;
}
.goal-planner-page .gp-inp .gp-date { font-size: 13px; }
.goal-planner-page .gp-inp .gp-ta { min-height: 48px; resize: none; line-height: 1.45; }
.goal-planner-page .gp-hold {
  display: flex; align-items: center; gap: 10px; padding: 12px 13px; border-radius: 15px;
  font-size: 12.5px; color: var(--text-secondary);
  background: rgba(245, 239, 230, 0.04); box-shadow: inset 0 0 0 1px var(--divider);
}
.goal-planner-page .gp-hold .t-ico { filter: none; }
/* feasibility: flat lit — sage inside the safe band, amber above it; the sprite carries the verdict */
.goal-planner-page .gp-feas {
  --f: var(--dv-sage);
  padding: 13px 14px; border-radius: 15px;
  background: color-mix(in srgb, var(--f) 9%, rgba(245, 239, 230, 0.03));
  box-shadow: inset 0 0 0 1px color-mix(in srgb, var(--f) 35%, transparent);
}
.goal-planner-page .gp-feas.is-warn { --f: var(--dv-amber); }
.goal-planner-page .gp-feas-top { display: flex; align-items: baseline; gap: 7px; }
.goal-planner-page .gp-feas-num {
  font-family: var(--ff-display); font-size: 26px; font-weight: 300; line-height: 1; letter-spacing: -1px;
  font-variant-numeric: tabular-nums; color: color-mix(in srgb, var(--f) 80%, var(--text-primary));
}
.goal-planner-page .gp-feas-unit { font-size: 11px; font-weight: 600; color: var(--text-muted); }
.goal-planner-page .gp-feas-verdict {
  margin-left: auto; align-self: center; display: inline-flex; align-items: center; gap: 5px;
  font-size: 10.5px; font-weight: 700; letter-spacing: 0.08em; text-transform: uppercase;
  color: color-mix(in srgb, var(--f) 80%, var(--text-primary));
}
.goal-planner-page .gp-feas-verdict .t-ico { filter: none; }
.goal-planner-page .gp-feas-body { margin-top: 7px; font-size: 12px; line-height: 1.45; color: var(--text-secondary); }
.goal-planner-page .gp-feas-body b { color: var(--text-primary); }
.goal-planner-page .gp-feas-accept {
  width: 100%; margin-top: 11px; padding: 9px; border: 0; border-radius: 12px; cursor: pointer;
  font: 700 11.5px/1.3 var(--ff-body); letter-spacing: 0.02em;
  color: color-mix(in srgb, var(--dv-amber) 80%, var(--text-primary));
  background: color-mix(in srgb, var(--dv-amber) 10%, transparent);
  box-shadow: inset 0 0 0 1px color-mix(in srgb, var(--dv-amber) 45%, transparent);
}
.goal-planner-page .gp-foot { padding: 18px 2px 32px; }
.goal-planner-page .gp-foot-row { display: flex; gap: 10px; }
.goal-planner-page .gp-foot-col { display: grid; gap: 10px; }
/* the lit CTA restates every colour (U5 rule 36) */
.goal-planner-page .cta-primary.gp-cta {
  flex: 1; min-height: 46px; padding: 0 18px; gap: 8px; border: 0; border-radius: 999px;
  font-size: 14px; font-weight: 700; color: #191614; background: var(--c);
  box-shadow: 0 0 14px color-mix(in srgb, var(--c) 55%, transparent);
}
.goal-planner-page .cta-primary.gp-cta .t-ico { filter: drop-shadow(0 1px 2px rgba(0, 0, 0, 0.3)); }
.goal-planner-page .cta-primary.gp-cta:disabled { opacity: 0.42; box-shadow: none; cursor: default; }
.goal-planner-page .cta-ghost.gp-ghost {
  flex: 1; min-height: 44px; border: 0; border-radius: 999px; font-size: 13px; font-weight: 600;
  color: var(--text-secondary); background: rgba(245, 239, 230, 0.05); box-shadow: inset 0 0 0 1px var(--divider);
}
.goal-planner-page .cta-ghost.gp-ghost:disabled { opacity: 0.5; }

/* ── attach-plan sheet: ONE floating sky glass (U2 rule 15), flat rows, the lit CTA ── */
.sheet.glass.goal-attach-sheet {
  --c: var(--dv-sky);
  position: absolute; left: 10px; right: 10px; bottom: calc(10px + env(safe-area-inset-bottom));
  overflow-x: hidden; overflow-y: auto; border: 0; border-radius: 30px; padding: 4px 18px 18px;
}
.sheet.glass.goal-attach-sheet .sheet-handle { background: rgba(245, 239, 230, 0.22); }
.goal-attach-sheet .gas-head { display: flex; align-items: center; gap: 12px; margin-bottom: 14px; }
.goal-attach-sheet .gas-title { flex: 1; min-width: 0; }
.goal-attach-sheet .gas-eb {
  display: block; font: 600 9.5px/1.3 var(--ff-body); letter-spacing: 1.3px; text-transform: uppercase;
  color: color-mix(in srgb, var(--c) 80%, var(--text-primary));
}
.goal-attach-sheet .gas-title h1, .goal-attach-sheet .gas-title h2, .goal-attach-sheet .gas-title div { color: var(--text-primary); }
.goal-attach-sheet .gas-x {
  flex: none; width: 32px; height: 32px; border: 0; border-radius: 50%; display: grid; place-items: center; cursor: pointer;
  color: var(--text-secondary); background: rgba(245, 239, 230, 0.06); box-shadow: inset 0 0 0 1px var(--divider);
}
.goal-attach-sheet .gas-empty {
  margin: 0; padding: 14px 16px; border-radius: 16px; font-size: 12.5px; line-height: 1.5; color: var(--text-secondary);
  border: 1.5px dashed color-mix(in srgb, var(--c) 45%, transparent); background: rgba(245, 239, 230, 0.025);
}
.goal-attach-sheet .gas-list { display: grid; gap: 6px; }
.goal-attach-sheet .gas-label {
  display: block; margin: 0 2px 2px; font: 600 9.5px/1.3 var(--ff-body); letter-spacing: 1.4px;
  text-transform: uppercase; color: var(--text-muted);
}
.goal-attach-sheet .gas-row {
  display: flex; align-items: center; justify-content: space-between; gap: 10px; width: 100%;
  padding: 11px 14px; border: 0; border-radius: 14px; text-align: left; cursor: pointer; font: inherit;
  color: var(--text-primary); background: rgba(245, 239, 230, 0.04); box-shadow: inset 0 0 0 1px var(--divider);
}
.goal-attach-sheet .gas-row.is-on {
  background: color-mix(in srgb, var(--c) 14%, rgba(245, 239, 230, 0.03));
  box-shadow: inset 0 0 0 1.5px color-mix(in srgb, var(--c) 60%, transparent), 0 0 12px -4px var(--c);
}
.goal-attach-sheet .gas-row-nm { min-width: 0; font-size: 13.5px; overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }
.goal-attach-sheet .gas-row-wk { flex: none; font-size: 10px; font-weight: 700; letter-spacing: 0.04em; text-transform: uppercase; color: var(--text-muted); }
.goal-attach-sheet .gas-week { display: grid; gap: 6px; margin-top: 16px; }
.goal-attach-sheet .gas-inp {
  width: 96px; padding: 11px 14px; border: 0; border-radius: 13px; outline: none;
  font: 700 14px/1.2 var(--ff-body); font-variant-numeric: tabular-nums; color: var(--text-primary); color-scheme: dark;
  background: rgba(245, 239, 230, 0.05); box-shadow: inset 0 0 0 1px var(--divider);
}
.goal-attach-sheet .gas-inp:focus-visible { box-shadow: inset 0 0 0 1.5px var(--c); }
.goal-attach-sheet .gas-acts { display: flex; gap: 10px; margin-top: 18px; }
.goal-attach-sheet .cta-ghost.gas-ghost {
  flex: 1; min-height: 44px; border: 0; border-radius: 999px; font-size: 13px; font-weight: 600;
  color: var(--text-secondary); background: rgba(245, 239, 230, 0.05); box-shadow: inset 0 0 0 1px var(--divider);
}
.goal-attach-sheet .cta-primary.gas-cta {
  flex: 1; min-height: 44px; padding: 0 16px; gap: 7px; border: 0; border-radius: 999px;
  font-size: 13.5px; font-weight: 700; color: #191614; background: var(--c);
  box-shadow: 0 0 14px color-mix(in srgb, var(--c) 55%, transparent);
}
.goal-attach-sheet .cta-primary.gas-cta .t-ico { filter: drop-shadow(0 1px 2px rgba(0, 0, 0, 0.3)); }
.goal-attach-sheet .cta-primary.gas-cta:disabled { opacity: 0.42; box-shadow: none; }

@media (max-width: 360px) {
  .goal-hub-page .goal-course-top { grid-template-columns: minmax(0, 1fr) 92px; }
  .goal-hub-page .goal-course-ring, .goal-hub-page .goal-course-ring svg { width: 92px; height: 92px; }
  .goal-hub-page .goal-course-ring span { font-size: 25px; }
  .goal-hub-page .goal-course-weights b { font-size: 30px; }
  .goal-dhero .goal-dhero-num { font-size: 42px; }
  .goal-planner-page .gp-two { flex-direction: column; }
  .uv-goal .gs-actions { grid-template-columns: 1fr; }
}
/* ── /uveg en sulycel ── */

/* ── uveg en suly (mezo-me75u.6) ── /me/weight: hero, stat strip, trend chart, weekly history + weight log sheet ── */
/* Ranking (bible §3.4, prototype uveg-en `suly()`): the loud thing is the change since the start
   (a frameless t-weight halo hero, PageHero `art`). The trend chart and each week are the primary
   objects and wear sky glass; the stat cells, the period switch, the day rows, the legend and the
   „Régebbi hetek" pager are flat. The page CTA is the one lit sky pill. The weight log sheet is
   the shared capture sheet — already a floating glass sheet since U3 (`── uveg nap rogzites (`),
   so it is not restyled here (it also serves /nap/gyors). */
.wt-page { --c: var(--dv-sky); }

/* page head: the lit sky „＋ Súly naplózása" pill (a filled CTA restates every colour, rule 36) */
.wt-page .mz-pgact.wt-logbtn {
  min-width: 0; max-width: 60%; overflow: hidden; text-overflow: ellipsis;
  border: 0; padding: 8px 14px; min-height: 40px; border-radius: 999px;
  font: 700 12.5px/1.2 var(--ff-body); color: #191614; background: var(--dv-sky);
  box-shadow: 0 0 14px color-mix(in srgb, var(--dv-sky) 55%, transparent);
}
.wt-page .mz-pgact.wt-logbtn:focus-visible { outline: 2px solid var(--dv-sky); outline-offset: 3px; }

/* hero: the big change numeral + the two pills as ONE wrapping group (rule 8, 14) */
.wt-page .mz-page-hero.uv-hero { --c2: var(--dv-sage); }
.wt-page .wt-heropills {
  display: flex; flex-wrap: wrap; justify-content: center; gap: 8px; margin-top: 10px; max-width: 100%;
}
.wt-page .wt-heropills > * {
  min-width: 0; max-width: 100%; overflow: hidden; text-overflow: ellipsis; white-space: nowrap;
  display: inline-flex; align-items: center; gap: 5px; margin: 0; padding: 5px 11px; border-radius: 999px;
  font: 600 11.5px/1.25 var(--ff-body); text-align: center;
}
/* lit (the goal progress, sage — never red): a tinted wash, an accent ring, a soft glow */
.wt-page .wt-goalpill {
  --c: var(--dv-sage); padding-left: 6px;
  color: color-mix(in srgb, var(--c) 72%, var(--text-primary));
  background: radial-gradient(90% 120% at 20% 20%, color-mix(in srgb, var(--c) 26%, transparent), rgba(245, 239, 230, 0.04));
  box-shadow: inset 0 0 0 1px color-mix(in srgb, var(--c) 40%, transparent), 0 0 12px -4px color-mix(in srgb, var(--c) 60%, transparent);
}
.wt-page .wt-goalpill .t-ico { filter: none; }
/* flat (the 4-week tempo) */
.wt-page .wt-4wk {
  color: var(--text-secondary); background: rgba(245, 239, 230, 0.05); box-shadow: inset 0 0 0 1px var(--divider);
}

/* stat strip: flat cells; the 7-day delta keeps its inline sage/amber meaning */
.wt-page .wt-stats.mz-statstrip { display: grid; grid-template-columns: repeat(3, minmax(0, 1fr)); gap: 8px; }
.wt-page .wt-stats .mz-statcell {
  min-width: 0; padding: 10px 6px; border: 0; border-radius: 16px;
  background: rgba(245, 239, 230, 0.04); box-shadow: inset 0 0 0 1px var(--divider);
}
.wt-page .wt-stats .mz-statcell b { font-size: 18px; font-weight: 600; letter-spacing: -0.5px; color: var(--text-primary); }
.wt-page .wt-stats .mz-statcell small { display: block; margin-top: 2px; font-size: 10px; color: var(--text-muted); }

/* period switch: a flat segmented control, the active segment lit sky */
.wt-page .wt-seg {
  display: flex; width: fit-content; max-width: 100%; margin: 14px auto 12px; padding: 3px; gap: 2px;
  border-radius: 999px; background: rgba(245, 239, 230, 0.05); box-shadow: inset 0 0 0 1px var(--divider);
}
.wt-page .wt-seg-btn {
  min-width: 0; min-height: 36px; padding: 7px 15px; border: 0; border-radius: 999px; cursor: pointer;
  font: 600 12.5px/1 var(--ff-body); color: var(--text-secondary); background: none;
}
.wt-page .wt-seg-btn.is-on {
  color: #191614; background: var(--dv-sky);
  box-shadow: 0 0 12px color-mix(in srgb, var(--dv-sky) 45%, transparent);
}
.wt-page .wt-seg-btn:focus-visible { outline: 2px solid var(--dv-sky); outline-offset: 2px; }

/* the trend chart: ONE sky glass card (old `.wt-chart` wash outranks .glass — restate, rule 11) */
.wt-page .wt-chart.glass {
  --c: var(--dv-sky);
  margin-bottom: 12px; padding: 12px 12px 10px; border: 0; border-radius: 22px;
  background:
    radial-gradient(120% 90% at 0% 0%, color-mix(in srgb, var(--c) 22%, transparent), transparent 62%),
    linear-gradient(160deg, rgba(52, 46, 41, 0.72), rgba(30, 27, 24, 0.60));
  box-shadow:
    0 16px 30px -16px rgba(0, 0, 0, 0.75),
    0 0 26px -6px color-mix(in srgb, var(--c) 30%, transparent),
    inset 0 1px 0 rgba(255, 244, 230, 0.10),
    inset 0 -14px 26px -18px color-mix(in srgb, var(--c) 55%, transparent);
}
.wt-page .wt-chart .wtc-ma { filter: drop-shadow(0 0 5px color-mix(in srgb, var(--dv-sky) 60%, transparent)); }
.wt-page .wt-chart .wtc-dot { filter: drop-shadow(0 0 8px var(--dv-sky)); }
/* too few points: the dashed empty state, no glass */
.wt-page .wt-chart.wt-chart-empty {
  --c: var(--dv-sky); margin-bottom: 12px; padding: 24px 16px; border-radius: 22px; text-align: center;
}
.wt-page .wt-chart-emptytx {
  font: 600 10.5px/1.4 var(--ff-body); letter-spacing: 1.2px; text-transform: uppercase; color: var(--text-muted);
}
/* the legend is flat: a glowing sky stroke, a dashed sage plan, a sage band swatch */
.wt-page .wt-leg { justify-content: center; gap: 14px; margin-top: 6px; font-size: 11px; color: var(--text-secondary); }
.wt-page .wt-leg i { width: 14px; height: 3px; vertical-align: 3px; }
.wt-page .wt-leg i.is-actual { background: var(--dv-sky); box-shadow: 0 0 5px var(--dv-sky); }
.wt-page .wt-leg i.is-plan { height: 0; border-radius: 0; background: none; border-top: 2px dashed var(--dv-sage); }
.wt-page .wt-leg i.is-band { height: 9px; vertical-align: 0; background: color-mix(in srgb, var(--dv-sage) 22%, transparent); }

/* the weekly history section label */
.wt-page .wt-lsec .mz-eyebrow { font-size: 9.5px; font-weight: 600; letter-spacing: 1.4px; color: var(--text-muted); }
.wt-page .wt-cnt { font-size: 10.5px; font-weight: 600; color: var(--text-muted); }

/* a week: a sky glass card (old `.wt-week` wash outranks .glass — restate, rule 11) */
.wt-page .wt-week.glass {
  --c: var(--dv-sky);
  margin-bottom: 10px; padding: 12px 14px 13px; border: 0; border-radius: 20px;
  background:
    radial-gradient(120% 90% at 0% 0%, color-mix(in srgb, var(--c) 20%, transparent), transparent 62%),
    linear-gradient(160deg, rgba(52, 46, 41, 0.72), rgba(30, 27, 24, 0.60));
  box-shadow:
    0 16px 30px -16px rgba(0, 0, 0, 0.75),
    0 0 24px -8px color-mix(in srgb, var(--c) 28%, transparent),
    inset 0 1px 0 rgba(255, 244, 230, 0.10),
    inset 0 -14px 26px -18px color-mix(in srgb, var(--c) 50%, transparent);
}
.wt-page .wt-week-toggle { color: var(--text-secondary); }
.wt-page .wt-week-toggle:focus-visible { outline: 2px solid var(--dv-sky); outline-offset: 2px; border-radius: 12px; }
.wt-page .wt-dl { font-size: 14.5px; font-weight: 600; letter-spacing: -0.2px; color: var(--text-primary); }
/* the delta pill is lit: sage when it moves toward the goal, amber when not — never red */
.wt-page .wt-deltap {
  padding: 3px 9px; font-size: 11.5px; font-weight: 700; color: #191614; background: var(--dv-sage);
  box-shadow: 0 0 8px color-mix(in srgb, var(--dv-sage) 55%, transparent);
}
.wt-page .wt-deltap.is-up {
  color: #191614; background: var(--dv-amber);
  box-shadow: 0 0 8px color-mix(in srgb, var(--dv-amber) 55%, transparent);
}
.wt-page .wt-avg {
  font-family: var(--ff-display); font-size: 26px; font-weight: 300; letter-spacing: -1px;
  color: var(--text-primary); font-variant-numeric: tabular-nums;
}
.wt-page .wt-avgsub { min-width: 0; font-size: 11.5px; color: var(--text-secondary); }
.wt-page .wt-spark { filter: drop-shadow(0 0 4px color-mix(in srgb, var(--dv-sky) 60%, transparent)); }
.wt-page .wt-days { font-size: 10px; font-weight: 600; color: var(--text-muted); }
.wt-page .wt-dir { color: var(--dv-sage); }
.wt-page .wt-dir.is-warn { color: var(--dv-amber); }
/* expanded day rows: flat cells */
.wt-page .wt-dayrow {
  align-items: center; gap: 10px; padding: 8px 11px; border-radius: 12px;
  background: rgba(245, 239, 230, 0.04); box-shadow: inset 0 0 0 1px var(--divider);
}
.wt-page .wt-dayname { min-width: 0; font-size: 13px; color: var(--text-secondary); }
.wt-page .wt-dayval { font-family: var(--ff-display); font-size: 16px; font-weight: 600; color: var(--text-primary); font-variant-numeric: tabular-nums; }
.wt-page .wt-dayunit { font-size: 11px; color: var(--text-muted); }
.wt-page .wt-dod { min-width: 34px; text-align: right; font-weight: 600; color: var(--dv-sage); }
.wt-page .wt-dod.is-up { color: var(--dv-amber); }
.wt-page .wt-dod.is-flat { color: var(--text-muted); }
/* „Mi történt ezen a héten?": a lit lavender FLAT button (glass-in-glass is forbidden, rule 5) */
.wt-page .wt-ask {
  --c: var(--dv-lav);
  flex: 1; min-width: 0; min-height: 44px; display: flex; align-items: center; gap: 8px;
  padding: 9px 12px; border: 0; border-radius: 13px; cursor: pointer; text-align: left;
  font: 600 12.5px/1.3 var(--ff-body); color: color-mix(in srgb, var(--c) 80%, var(--text-primary));
  background: color-mix(in srgb, var(--c) 9%, transparent);
  box-shadow: inset 0 0 0 1px color-mix(in srgb, var(--c) 32%, transparent);
}
.wt-page .wt-ask .t-ico { filter: none; }
.wt-page .wt-ask:disabled { opacity: 0.55; cursor: default; }
.wt-page .wt-ask:focus-visible { outline: 2px solid var(--dv-lav); outline-offset: 2px; }
.wt-page .wt-asknote { margin-top: 6px; font-size: 11px; line-height: 1.45; color: var(--text-secondary); }
.wt-page .wt-askdemo { margin-top: 5px; font-size: 10px; text-align: center; color: var(--text-muted); }

/* „Régebbi hetek ⌄": a flat pager row (old `.mzp-new` dashed wash — restate) */
.wt-page .mzp-new.wt-more {
  margin-top: 4px; border: 0; border-radius: 17px;
  font: 600 13px/1.2 var(--ff-body); color: var(--text-secondary);
  background: rgba(245, 239, 230, 0.04); box-shadow: inset 0 0 0 1px var(--divider);
}
.wt-page .mzp-new.wt-more:focus-visible { outline: 2px solid var(--dv-sky); outline-offset: 2px; }

/* ── /uveg en suly ── */

/* ── uveg en alvas (mezo-me75u.6) ── /me/sleep + /me/sleep/night + sleep log / stats sheets ── */
/* Ranking (bible §3.4, prototype uveg-en.html#alvas / #ejszaka): the hero is the frameless
   t-sleep halo (PageHero art); the goal card, the two ring tiles, last night, the night arc,
   the phase average, the trend and the REM scatter are lavender `.glass` (the education card
   gold, the escalation card amber — it keeps its warning tone, the REM card sky). Chips, the
   phase reference bands and the 7-night log rows are FLAT; a short/poor night keeps a coral
   edge. Every rule is scoped to `.alv-page` / `.night` / `.sst-sheet` (U2 rule 13): `.phrail`,
   `.phref`, `.sstat` and `.night-*` keep their old skins wherever else they render. */
.alv-page { --c: var(--dv-lav); }
.alv-page.mz-page {
  background: radial-gradient(120% 40% at 50% 0%, color-mix(in srgb, var(--dv-lav) 14%, transparent), transparent 70%);
}
.alv-page .mz-page-body { overflow-x: hidden; padding: 2px 16px 22px; }
/* the header's lit lavender „＋ Log" — a filled CTA restates every colour (U5 rule 36) */
.alv-page .pgact.alv-log {
  --c: var(--dv-lav); margin-left: auto; min-height: 38px; padding: 0 14px; gap: 5px;
  font-size: 13px; font-weight: 600; color: #191614; background: var(--c);
  box-shadow: 0 0 14px color-mix(in srgb, var(--c) 50%, transparent);
}
.alv-page .pgact.alv-log span { font-size: 15px; line-height: 1; }

/* shared type + chips inside the page */
.alv-page .alv-eyebrow, .alv-page .mz-eyebrow {
  font: 600 9.5px/1.2 var(--ff-body); letter-spacing: 1.4px; text-transform: uppercase; color: var(--text-muted);
}
.alv-page .alv-sec { margin-top: 16px; }
.alv-page .alv-sec-head { display: flex; align-items: center; justify-content: space-between; gap: 10px; margin: 0 2px 9px; }
.alv-page .alv-sec-head .eyebrow { min-width: 0; white-space: normal; }
.alv-page .alv-chips { display: flex; flex-wrap: wrap; gap: 6px; margin-top: 12px; }
.alv-page .alv-chip {
  --tone: var(--text-secondary);
  display: inline-flex; align-items: center; gap: 4px; min-width: 0; max-width: 100%;
  padding: 4px 10px; border: 0; border-radius: 999px; font: 600 11.5px/1.3 var(--ff-body);
  color: var(--tone); background: rgba(245, 239, 230, 0.05); box-shadow: inset 0 0 0 1px var(--divider);
  font-variant-numeric: tabular-nums; overflow: hidden; text-overflow: ellipsis; white-space: nowrap;
}
.alv-page .alv-chip b { font-weight: 700; color: var(--text-primary); }
.alv-page .alv-chip[data-tone] {
  color: color-mix(in srgb, var(--tone) 80%, var(--text-primary));
  background: color-mix(in srgb, var(--tone) 11%, rgba(245, 239, 230, 0.03));
  box-shadow: inset 0 0 0 1px color-mix(in srgb, var(--tone) 32%, transparent);
}
.alv-page .alv-chip[data-tone="sage"] { --tone: var(--dv-sage); }
.alv-page .alv-chip[data-tone="coral"] { --tone: var(--dv-coral); }
.alv-page .alv-chip.is-lit, .alv-page .alv-chip.is-on {
  --tone: var(--dv-lav); cursor: pointer;
  color: color-mix(in srgb, var(--tone) 80%, var(--text-primary));
  background: color-mix(in srgb, var(--tone) 12%, rgba(245, 239, 230, 0.03));
  box-shadow: inset 0 0 0 1px color-mix(in srgb, var(--tone) 38%, transparent);
}
.alv-page .alv-chip.is-on {
  color: #191614; background: var(--dv-lav); box-shadow: 0 0 12px color-mix(in srgb, var(--dv-lav) 50%, transparent);
}
.alv-page .alv-seg { display: flex; flex-wrap: wrap; gap: 5px; min-width: 0; }
.alv-page .alv-seg .alv-chip { cursor: pointer; }

/* ─ the sleep-goal card: the bed rail as a lit glowing bar between two 3D ends ─ */
.alv-page .alv-goal.glass { --c: var(--dv-lav); padding: 14px 15px 14px; border-radius: 22px; }
.alv-page .alv-card-head { display: flex; align-items: center; gap: 9px; min-width: 0; }
.alv-page .alv-card-title { flex: 1; min-width: 0; font-size: 15px; font-weight: 600; letter-spacing: -0.2px; color: var(--text-primary); }
.alv-page .alv-unset { margin: 8px 0 0; font-size: 12px; line-height: 1.5; color: color-mix(in srgb, var(--dv-amber) 80%, var(--text-primary)); }
.alv-page .alv-bedrail { display: grid; grid-template-columns: auto minmax(0, 1fr) auto; align-items: center; gap: 10px; margin-top: 30px; }
.alv-page .alv-end { display: grid; justify-items: center; gap: 2px; }
.alv-page .alv-end b { font-size: 15px; font-weight: 600; font-variant-numeric: tabular-nums; color: var(--text-primary); }
.alv-page .alv-rail {
  position: relative; height: 10px; border-radius: 999px;
  background: linear-gradient(90deg, color-mix(in srgb, var(--c) 55%, #fff), var(--c));
  box-shadow: 0 0 12px color-mix(in srgb, var(--c) 55%, transparent);
}
.alv-page .alv-rail span {
  position: absolute; left: 50%; bottom: calc(100% + 6px); transform: translateX(-50%);
  font-size: 11px; font-weight: 600; color: var(--text-secondary); white-space: nowrap;
}
.alv-page .alv-goal-foot { display: flex; flex-wrap: wrap; align-items: center; gap: 8px; margin-top: 12px; }
.alv-page .alv-quote { font-family: var(--ff-serif); font-style: italic; font-size: 13px; color: var(--text-secondary); }

/* ─ the two ring tiles: glass, glowing rings (the svg must not clip the glow) ─ */
.alv-page .alv-rings { display: grid; grid-template-columns: repeat(2, minmax(0, 1fr)); gap: 10px; margin-top: 10px; }
.alv-page .alv-ring.glass {
  display: flex; flex-direction: column; align-items: center; gap: 4px; min-width: 0;
  padding: 14px 10px 12px; border-radius: 20px; text-align: center;
}
.alv-page .alv-ring svg { overflow: visible; }
.alv-page .alv-ring svg circle:first-child { stroke: rgba(245, 239, 230, 0.07); }
.alv-page .alv-ring svg circle + circle { filter: drop-shadow(0 0 5px color-mix(in srgb, var(--c) 55%, transparent)); }
.alv-page .alv-ring > div > span { font-weight: 300; letter-spacing: -0.8px; }
.alv-page .alv-ring strong { margin-top: 4px; font-size: 13.5px; font-weight: 600; color: var(--text-primary); }
.alv-page .alv-ring small { font-size: 10.5px; color: var(--text-muted); }

/* ─ the education card (gold glass) and the escalation card (amber glass, warning tone) ─ */
.alv-page .alv-edu { margin-top: 10px; }
.alv-page .sstat.glass, .alv-page .sesc.glass {
  display: flex; flex-direction: column; gap: 6px; width: 100%; margin-top: 0; padding: 14px 15px;
  border: 0; border-radius: 22px; text-align: left;
  background:
    radial-gradient(120% 90% at 0% 0%, color-mix(in srgb, var(--c) 20%, transparent), transparent 62%),
    linear-gradient(160deg, rgba(52, 46, 41, 0.72), rgba(30, 27, 24, 0.6));
  box-shadow:
    0 16px 30px -16px rgba(0, 0, 0, 0.75),
    0 0 26px -6px color-mix(in srgb, var(--c) 28%, transparent),
    inset 0 1px 0 rgba(255, 244, 230, 0.1),
    inset 0 -14px 26px -18px color-mix(in srgb, var(--c) 50%, transparent);
}
.alv-page .sstat.glass { --c: var(--dv-amber); cursor: pointer; }
.alv-page .sesc.glass { --c: var(--dv-amber); }
.alv-page .sstat-head { display: flex; align-items: center; gap: 9px; min-width: 0; }
.alv-page .sstat-eye { flex: 1; min-width: 0; font: 600 15px/1.25 var(--ff-body); letter-spacing: -0.2px; text-transform: none; color: var(--text-primary); }
.alv-page .sstat-chev { font-size: 20px; line-height: 1; color: color-mix(in srgb, var(--c) 70%, var(--text-muted)); }
.alv-page .sstat-title { font: 600 14px/1.35 var(--ff-body); color: var(--text-primary); }
.alv-page .sstat-text { font: 400 13px/1.55 var(--ff-body); color: var(--text-secondary); }
.alv-page .sstat-src { font: 500 10.5px/1.4 var(--ff-body); color: var(--text-muted); }
.alv-page .sesc-lead { margin: 0; font: 600 14px/1.5 var(--ff-body); color: var(--text-primary); }
.alv-page .sesc-body { margin: 0; font: 400 12.5px/1.6 var(--ff-body); color: var(--text-secondary); }
.alv-page .sesc-actions { display: flex; flex-wrap: wrap; gap: 10px; align-items: center; margin-top: 4px; }
.alv-page .sesc-cta {
  border: 0; padding: 10px 16px; border-radius: 999px; font: 600 12.5px/1 var(--ff-body);
  color: #191614; background: var(--c); box-shadow: 0 0 14px color-mix(in srgb, var(--c) 50%, transparent);
}
.alv-page .sesc-quiet { border: 0; background: none; padding: 10px 8px; font: 600 12px/1 var(--ff-body); color: var(--text-muted); }

/* ─ last night: big light numerals, flat chips, the lit phase rail ─ */
.alv-page .alv-last.glass { --c: var(--dv-lav); margin-top: 12px; padding: 15px; border-radius: 22px; }
.alv-page .alv-last-top { display: grid; grid-template-columns: minmax(0, 1fr) auto; align-items: end; gap: 10px; }
.alv-page .alv-last-dur, .alv-page .alv-last-q { display: flex; flex-direction: column; gap: 6px; min-width: 0; }
.alv-page .alv-last-q { align-items: flex-end; text-align: right; }
.alv-page .alv-last-num, .alv-page .alv-last-qnum {
  font-family: var(--ff-display); font-weight: 300; line-height: 1; font-variant-numeric: tabular-nums; color: var(--text-primary);
}
.alv-page .alv-last-num { font-size: 46px; letter-spacing: -2.2px; }
.alv-page .alv-last-qnum { font-size: 30px; letter-spacing: -1.2px; }
.alv-page .alv-last-q[data-good="true"] .alv-last-qnum { color: color-mix(in srgb, var(--dv-sage) 80%, var(--text-primary)); }
.alv-page .alv-last-q[data-good="false"] .alv-last-qnum { color: color-mix(in srgb, var(--dv-amber) 85%, var(--text-primary)); }
.alv-page .alv-last-num small, .alv-page .alv-last-qnum small { margin-left: 3px; font-size: 15px; letter-spacing: 0; color: var(--text-muted); }
.alv-page .alv-last-span { font-size: 12px; font-weight: 600; font-variant-numeric: tabular-nums; color: var(--text-secondary); }
.alv-page .alv-phases { margin-top: 14px; padding-top: 12px; border-top: 1px solid var(--divider); }
.alv-page .alv-phases-head { display: flex; align-items: center; justify-content: space-between; gap: 8px; margin-bottom: 8px; }
.alv-page .alv-src { font-size: 10.5px; font-weight: 600; color: var(--text-muted); }
.alv-page .alv-refs { display: grid; gap: 11px; margin-top: 12px; padding-top: 11px; border-top: 1px solid var(--divider); }
.alv-page .alv-note { margin: 12px 0 0; padding-top: 10px; border-top: 1px solid var(--divider); font-size: 13px; line-height: 1.5; font-style: italic; color: var(--text-secondary); }

/* the phase rail: lit (a soft glow under the segments); the legend and reference bands flat */
.alv-page .phrail {
  background: rgba(245, 239, 230, 0.07);
  box-shadow: inset 0 0 0 1px var(--divider), 0 0 12px -2px color-mix(in srgb, var(--dv-lav) 45%, transparent);
}
.alv-page .phleg-it { color: var(--text-secondary); font-weight: 600; }
.alv-page .phleg-v { color: var(--text-primary); font-weight: 700; }
.alv-page .phleg-p { color: var(--text-muted); font-weight: 600; }
.alv-page .phref-t { color: var(--text-secondary); font-weight: 600; }
.alv-page .phref-t b { font-weight: 600; color: var(--text-primary); }
.alv-page .phref-t em { font-weight: 600; color: var(--text-muted); }
.alv-page .phref-bar { background: rgba(245, 239, 230, 0.07); }
.alv-page .phref-band {
  top: -2px; bottom: -2px;
  background: color-mix(in srgb, var(--dv-sage) 22%, transparent);
  box-shadow: inset 0 0 0 1px color-mix(in srgb, var(--dv-sage) 42%, transparent);
}
.alv-page .phref-pin { top: -4px; height: 14px; box-shadow: 0 0 8px rgba(245, 239, 230, 0.35); }

/* ─ the night arc: the hypnogram silhouette glows ─ */
.alv-page .nac.glass { --c: var(--dv-lav); padding: 14px; border-radius: 22px; }
.alv-page .nac svg { overflow: visible; }
.alv-page .nac-bars { filter: drop-shadow(0 0 5px color-mix(in srgb, var(--dv-lav) 55%, transparent)); }
.alv-page .nac-halves { margin-top: 14px; padding-top: 12px; border-top: 1px solid var(--divider); }
.alv-page .nac-eb {
  display: block; margin-top: 12px; font: 600 9.5px/1.2 var(--ff-body); letter-spacing: 1.4px;
  text-transform: uppercase; color: var(--text-muted);
}
.alv-page .nac-eb:first-child { margin-top: 0; }
.alv-page .nac-rail { margin-top: 6px; }
.alv-page .nac-lead { margin: 13px 0 0; padding-top: 12px; border-top: 1px solid var(--divider); font-size: 13px; line-height: 1.55; color: var(--text-secondary); }
.alv-page .nac-lead b { color: var(--text-primary); }
.alv-page .nac-foot { margin: 10px 0 0; font-size: 11px; line-height: 1.5; color: var(--text-muted); }

/* ─ the phase average ─ */
.alv-page .pac-card.glass { --c: var(--dv-lav); padding: 14px; border-radius: 22px; }

/* ─ the trend: glowing columns + amber quality dots ─ */
.alv-page .sch.glass { --c: var(--dv-lav); padding: 14px; border-radius: 22px; }
.alv-page .sch svg { overflow: visible; }
.alv-page .sch svg rect { filter: drop-shadow(0 0 4px color-mix(in srgb, var(--dv-lav) 35%, transparent)); }
.alv-page .sch .sch-qline { filter: drop-shadow(0 0 4px color-mix(in srgb, var(--dv-amber) 60%, transparent)); }
.alv-page .sch .sch-qdot { filter: drop-shadow(0 0 5px var(--dv-amber)); }
.alv-page .sch-legend { display: flex; flex-wrap: wrap; justify-content: center; gap: 6px 14px; margin-top: 10px; }
.alv-page .sch-lg { display: inline-flex; align-items: center; gap: 5px; font-size: 11px; color: var(--text-secondary); }
.alv-page .sch-lg i { width: 10px; height: 4px; border-radius: 2px; }
.alv-page .sch-lg.is-q i { width: 8px; height: 8px; border-radius: 50%; box-shadow: 0 0 6px var(--dv-amber); }

/* ─ the REM scatter (sky) ─ */
.alv-page .rdc-card.glass { --c: var(--dv-sky); padding: 14px; border-radius: 22px; }
.alv-page .rdc-card svg { overflow: visible; }
.alv-page .rdc-dot { filter: drop-shadow(0 0 5px color-mix(in srgb, var(--ph-rem) 70%, transparent)); }
.alv-page .rdc-lead { margin: 11px 0 0; padding-top: 11px; border-top: 1px solid var(--divider); font-size: 13px; line-height: 1.55; color: var(--text-secondary); }
.alv-page .rdc-lead b { color: var(--text-primary); }

/* ─ the 7-night log: flat rows; a short/poor night keeps a coral warning edge ─ */
.alv-page .alv-log-list { display: grid; gap: 5px; }
.alv-page .slr {
  display: grid; grid-template-columns: 44px 76px minmax(0, 1fr); align-items: center; gap: 8px;
  padding: 9px 11px; border-radius: 14px; font-size: 12.5px;
  background: rgba(245, 239, 230, 0.04); box-shadow: inset 0 0 0 1px var(--divider);
}
.alv-page .slr-date { font-size: 11px; font-weight: 600; letter-spacing: 0.3px; color: var(--text-muted); font-variant-numeric: tabular-nums; white-space: nowrap; }
.alv-page .slr-dur { display: flex; flex-direction: column; gap: 2px; min-width: 0; }
.alv-page .slr-dur > b { font-family: var(--ff-display); font-size: 16px; font-weight: 600; line-height: 1; font-variant-numeric: tabular-nums; color: var(--text-primary); }
.alv-page .slr-dur > b small { margin-left: 2px; font-size: 10px; color: var(--text-muted); }
.alv-page .slr-span { font-size: 10.5px; color: var(--text-muted); font-variant-numeric: tabular-nums; white-space: nowrap; }
.alv-page .slr-q { display: flex; flex-direction: column; gap: 4px; min-width: 0; }
.alv-page .slr-q-row { display: flex; align-items: center; gap: 7px; }
.alv-page .slr-q-eb { font-size: 9.5px; font-weight: 600; letter-spacing: 1px; color: var(--text-muted); }
.alv-page .slr-bar { --c: var(--dv-lav); flex: 1; height: 4px; }
.alv-page .slr-q-num { min-width: 16px; text-align: right; font-weight: 700; font-variant-numeric: tabular-nums; color: color-mix(in srgb, var(--dv-lav) 80%, var(--text-primary)); }
.alv-page .slr-note { font-size: 11px; line-height: 1.4; font-style: italic; color: var(--text-muted); overflow-wrap: anywhere; }
.alv-page .slr.is-warn { box-shadow: inset 2px 0 0 #FFB39C, inset 0 0 0 1px rgba(255, 126, 92, 0.25); }
.alv-page .slr.is-warn .slr-dur > b, .alv-page .slr.is-warn .slr-q-num { color: #FFB39C; }
.alv-page .slr.is-warn .slr-bar { --c: var(--dv-coral); }

/* ─ empty log: dashed, no glass (rank 4) ─ */
.alv-page .alv-empty.uv-empty { margin-top: 12px; padding: 16px; border-radius: 18px; font-size: 13px; text-align: center; color: var(--text-muted); }

/* ─ the night-mode entry: a lavender glass row with the 3D moon ─ */
.alv-page .alv-night.glass {
  --c: var(--dv-lav); display: flex; align-items: center; gap: 12px; margin-top: 16px;
  padding: 14px; border-radius: 22px; text-decoration: none; color: inherit;
}
.alv-page .alv-night-tx { flex: 1; display: flex; flex-direction: column; gap: 3px; min-width: 0; }
.alv-page .alv-night-t1 { font-size: 15px; font-weight: 600; color: var(--text-primary); }
.alv-page .alv-night-t2 { font-size: 11.5px; line-height: 1.4; color: var(--text-secondary); }
.alv-page .alv-night-chev { font-size: 20px; color: color-mix(in srgb, var(--c) 70%, var(--text-muted)); }

/* ─ NightPage: the calm dark variant — no bright glass, faint lavender flat rows, a soft
     glowing orb, big light numerals/titles, 3D art at low intensity. Breathing motion lives
     ONLY in the no-preference branch (the labels' opacity cycle is the pacing and stays). ─ */
.night .night-back { font-size: 12.5px; font-weight: 500; color: #6D6488; }
.night .night-eye { font-weight: 600; letter-spacing: 1.6px; color: #8C84B3; }
.night .night-moon, .night .night-glow { display: grid; place-items: center; margin: 22px auto 16px; }
.night .night-moon .t-ico { opacity: 0.85; filter: drop-shadow(0 0 22px rgba(171, 159, 210, 0.28)); }
.night .night-glow .t-ico { opacity: 0.85; filter: drop-shadow(0 0 20px rgba(255, 190, 96, 0.22)); }
.night .night-title { font-weight: 300; font-size: 30px; letter-spacing: -1px; color: #D9D1EC; }
.night .night-title-sm { font-size: 25px; }
.night .night-tx { color: #8A7F9E; font-size: 14px; line-height: 1.6; }
.night .night-cta {
  color: #D9D1EC; font-weight: 600; font-size: 15px; border: 0;
  background: rgba(171, 159, 210, 0.1);
  box-shadow: inset 0 0 0 1px rgba(171, 159, 210, 0.35), 0 0 20px -6px rgba(171, 159, 210, 0.5);
}
.night .night-quiet { font-size: 12.5px; font-weight: 500; color: #6D6488; text-decoration: underline; text-underline-offset: 3px; }
.night .night-orb, .night .nb-orb { animation: none; }
.night .night-orb {
  width: 120px; height: 120px;
  background: radial-gradient(circle at 40% 35%, rgba(217, 209, 236, 0.35), rgba(109, 95, 168, 0.15) 60%, transparent 72%);
  box-shadow: 0 0 40px -6px rgba(171, 159, 210, 0.35);
}
.night .nb-orb {
  background: radial-gradient(circle, rgba(171, 159, 210, 0.28), rgba(109, 95, 168, 0.08) 62%, transparent 72%);
  box-shadow: 0 0 50px -10px rgba(171, 159, 210, 0.5);
}
.night .nb-labels span { font-weight: 300; font-size: 22px; color: #D9D1EC; }
.night .night-tools { gap: 8px; }
.night .night-tool {
  gap: 12px; padding: 12px 14px; border: 0; border-radius: 18px;
  background: rgba(171, 159, 210, 0.06); box-shadow: inset 0 0 0 1px rgba(171, 159, 210, 0.18);
}
.night .night-tool-art { display: grid; place-items: center; flex: 0 0 auto; opacity: 0.8; }
.night .night-tool-tx b { font-size: 14.5px; color: #D9D1EC; }
.night .night-tool-tx i { font-size: 11.5px; color: #8A7F9E; }
.night .night-tool-chev { font-size: 20px; color: #6D6488; }
.night .night-steps li { color: #B6ADCB; }
.night .night-steps li::before { background: rgba(171, 159, 210, 0.7); box-shadow: 0 0 6px rgba(171, 159, 210, 0.5); }
.night .night-steps b { color: #D9D1EC; }
.night .ns-card, .night .nw-stage {
  border: 0; background: rgba(171, 159, 210, 0.06); box-shadow: inset 0 0 0 1px rgba(171, 159, 210, 0.18);
}
.night .ns-part, .night .nw-t { font-weight: 300; color: #D9D1EC; }
.night .ns-tx, .night .nw-tx, .night .nw-rtx { color: #8A7F9E; }
.night .ns-dot.on { background: #AB9FD2; box-shadow: 0 0 6px rgba(171, 159, 210, 0.6); }
.night .nb-hint, .night .ns-hint, .night .nw-note { color: #6D6488; }
@media (prefers-reduced-motion: no-preference) {
  .night .night-orb, .night .nb-orb { animation: nb-breath 18s ease-in-out infinite; }
}

/* ─ the stats sheet: ONE floating gold glass (U2 rule 15); deck rows flat inside ─ */
.sheet.glass.sst-sheet {
  --c: var(--dv-amber);
  position: absolute; left: 10px; right: 10px; bottom: calc(10px + env(safe-area-inset-bottom));
  max-height: calc(100% - 70px); overflow-x: hidden; overflow-y: auto;
  padding: 4px 18px 22px; border: 0; border-radius: 30px;
}
.sheet.glass.sst-sheet .sheet-handle { width: 40px; height: 5px; background: rgba(245, 239, 230, 0.2); }
.sst-sheet .sst-body { display: flex; flex-direction: column; padding: 4px 0 6px; }
.sst-sheet .sst-head { display: flex; align-items: center; gap: 12px; margin-bottom: 14px; }
.sst-sheet .sst-head-tx { flex: 1; min-width: 0; display: flex; flex-direction: column; gap: 3px; }
.sst-sheet .sst-eye { font: 600 9.5px/1.2 var(--ff-body); letter-spacing: 1.4px; text-transform: uppercase; color: color-mix(in srgb, var(--c) 75%, var(--text-muted)); }
.sst-sheet .sst-title { font-size: 20px; font-weight: 600; letter-spacing: -0.4px; color: var(--text-primary); }
.sst-sheet .sst-x {
  width: 36px; height: 36px; flex: 0 0 auto; display: grid; place-items: center; border: 0; border-radius: 50%;
  color: var(--text-secondary); background: rgba(245, 239, 230, 0.06); box-shadow: inset 0 0 0 1px var(--divider);
}
.sst-sheet .sst-rows { display: grid; gap: 7px; }
.sst-sheet .sstat-row {
  display: flex; flex-direction: column; gap: 5px; padding: 12px 14px; border: 0; border-radius: 16px;
  background: rgba(245, 239, 230, 0.04); box-shadow: inset 0 0 0 1px var(--divider);
}
.sst-sheet .sstat-title { font: 600 14px/1.35 var(--ff-body); color: var(--text-primary); }
.sst-sheet .sstat-text { font: 400 12.5px/1.55 var(--ff-body); color: var(--text-secondary); }
.sst-sheet .sstat-src { font: 500 10.5px/1.4 var(--ff-body); color: var(--text-muted); }
.sst-sheet .sstat-foot { margin: 12px 0 0; font-size: 11px; line-height: 1.55; color: var(--text-muted); }
/* the escalation section stays amber — a flat tinted cell, never glass in glass (U1 rule 5) */
.sst-sheet .sesc-sheet {
  display: flex; flex-direction: column; gap: 8px; margin-bottom: 12px; padding: 13px 14px; border-radius: 16px;
  background: color-mix(in srgb, var(--dv-amber) 9%, rgba(245, 239, 230, 0.03));
  box-shadow: inset 2px 0 0 var(--dv-amber), inset 0 0 0 1px color-mix(in srgb, var(--dv-amber) 30%, transparent);
}
.sst-sheet .sstat-head { display: flex; align-items: center; gap: 8px; }
.sst-sheet .sstat-eye { font: 600 9.5px/1.2 var(--ff-body); letter-spacing: 1.4px; text-transform: uppercase; color: color-mix(in srgb, var(--dv-amber) 80%, var(--text-primary)); }
.sst-sheet .sesc-lead { margin: 0; font: 600 13.5px/1.5 var(--ff-body); color: var(--text-primary); }
.sst-sheet .sesc-body { margin: 0; font: 400 12.5px/1.6 var(--ff-body); color: var(--text-secondary); }
.sst-sheet .sesc-body b { color: var(--text-primary); }

/* ─ the sleep log sheet (already the U3 capture glass): its note box is flat, not a card ─ */
.sheet.capture-tone-sleep .card {
  padding: 10px; border: 0; border-radius: 14px;
  background: rgba(245, 239, 230, 0.05); box-shadow: inset 0 0 0 1px var(--divider);
}
.sheet.capture-tone-sleep textarea { color: var(--text-primary); background: transparent; border: 0; color-scheme: dark; }

/* ── /uveg en alvas ── */

/* ── uveg en het (mezo-me75u.6) ── /me/week(+/elemzes,/napok,/felfedezesek,/tanulsagok) ── */
/* Reference: docs/design_2.0/prototypes/src/uveg-en-body.html `het()`, `elemzes()`, `napok()`,
   `felfedezesek()`, `tanulsagok()` (owner OK). Every rule is scoped to a page root — `.wkh-page`
   (hub), `.wk-analysis-page`, `.wkd-page` (napok), `.wkf-page` (felfedezések), `.wkt-page`
   (tanulságok) — because `.wkd-tile` is BOTH the day tile and the discovery tile, and `.card`,
   `.chip`, `.mz-mcells` are shared everywhere (bible rule 13). Ranking (§3.4): the hub hero is a
   frameless lavender halo with the glowing score ring; the view tiles, the goal / next-week
   cards, the score-bar and review cards, the day and discovery tiles and the lessons card are
   `.glass` (ONE `--c` each); cells, chips, stamps and the feedback chips inside them are flat;
   a nincs-adat / future day, the quiet week and the error boxes are dashed `uv-empty`. */

.wkh-page.mz-page, .wk-analysis-page.mz-page, .wkd-page.mz-page, .wkf-page.mz-page,
.wkt-page.mz-page { background: transparent; }
.wkh-page { --c: var(--dv-lav); }
.wk-analysis-page { --c: var(--dv-lav); }
.wkd-page { --c: var(--dv-sage); }
.wkf-page { --c: var(--dv-sky); }
.wkt-page { --c: var(--dv-amber); }
.wka-headwk, .wkd-headtitle, .wkf-page .wkl-wk { color: var(--text-muted); }

/* ── the glass body, restated: the old wash / strip / card rules outrank `.glass` (rule 11) ── */
.wkh-page .wkh-wide.glass, .wkh-page .wkh-sm.glass, .wkh-page .lg-wcard.glass, .wkh-page .wkn-card.glass,
.wk-analysis-page .wka-card.glass, .wk-analysis-page .wka-rev.glass, .wk-analysis-page .wka-lessgo.glass,
.wkd-page .wkd-tile.glass, .wkf-page .wkd-tile.glass, .wkt-page .wkt-card.glass {
  border: 0; border-radius: 22px; color: var(--text-primary);
  background:
    radial-gradient(120% 90% at 0% 0%, color-mix(in srgb, var(--c) 22%, transparent), transparent 62%),
    linear-gradient(160deg, rgba(52, 46, 41, 0.72), rgba(30, 27, 24, 0.60));
  box-shadow:
    0 16px 30px -16px rgba(0, 0, 0, 0.75),
    0 0 26px -6px color-mix(in srgb, var(--c) 30%, transparent),
    inset 0 1px 0 rgba(255, 244, 230, 0.10),
    inset 0 -14px 26px -18px color-mix(in srgb, var(--c) 55%, transparent);
}
.wkh-page .wkh-wide:focus-visible, .wkh-page .wkh-sm:focus-visible, .wk-analysis-page .wka-lessgo:focus-visible,
.wkd-page .wkd-tile:focus-visible, .wkf-page .wkd-tile:focus-visible {
  outline: 2px solid var(--c); outline-offset: 2px;
}

/* ── the lit flat mini-cells (prototype `.mcell`): hub (8, two rows of 4) + napok (3) ── */
.wkh-page .wkh-cellstack { gap: 6px; }
.wkh-page .wkh-cells.mz-mcells, .wkd-page .wkd-cells.mz-mcells {
  display: grid; grid-template-columns: repeat(4, minmax(0, 1fr)); gap: 6px;
}
.wkd-page .wkd-cells.mz-mcells { grid-template-columns: repeat(3, minmax(0, 1fr)); margin-bottom: 12px; }
.wkh-page .mz-mcells .mz-c-lav, .wkd-page .mz-mcells .mz-c-lav { --c: var(--dv-lav); }
.wkh-page .mz-mcells .mz-c-sage, .wkd-page .mz-mcells .mz-c-sage { --c: var(--dv-sage); }
.wkh-page .mz-mcells .mz-c-sky, .wkd-page .mz-mcells .mz-c-sky { --c: var(--dv-sky); }
.wkh-page .mz-mcells .mz-c-coral, .wkd-page .mz-mcells .mz-c-coral { --c: var(--dv-coral); }
.wkh-page .mz-mcells .mz-c-amber, .wkd-page .mz-mcells .mz-c-amber { --c: var(--dv-amber); }
.wkh-page .mz-mcells .mz-c-rose, .wkd-page .mz-mcells .mz-c-rose { --c: var(--dv-rose); }
.wkh-page .wkh-cells.mz-mcells > span, .wkd-page .wkd-cells.mz-mcells > span {
  min-width: 0; padding: 7px 2px 6px; border-radius: 10px; text-align: center;
  background: color-mix(in srgb, var(--c) 10%, rgba(245, 239, 230, 0.03));
  box-shadow: inset 0 0 0 1px color-mix(in srgb, var(--c) 28%, transparent);
}
.wkh-page .wkh-cells.mz-mcells b, .wkd-page .wkd-cells.mz-mcells b {
  font-size: 13.5px; font-weight: 600; color: color-mix(in srgb, var(--c) 85%, var(--text-primary));
}
.wkh-page .wkh-cells.mz-mcells small, .wkd-page .wkd-cells.mz-mcells small {
  display: block; font-size: 9px; font-weight: 500; letter-spacing: 0; text-transform: none; opacity: 1;
  color: var(--text-muted); overflow: hidden; text-overflow: ellipsis; white-space: nowrap;
}
/* the unit sits INSIDE <b>, so the shared `.mz-mcells span` cell skin must not reach it */
.wkh-page .wkh-cells .wkh-cellunit {
  padding: 0; border-radius: 0; background: none; box-shadow: none;
  font-size: 9px; font-weight: 500; color: var(--text-muted);
}

/* ═══ Hub ═══ */
/* the week stepper: two round glass buttons; the ::after that was the sheen is the 44px hit area */
.wkh-page .wkh-nav { gap: 6px; }
.wkh-page .wkh-nav button.glass.is-round {
  --c: var(--dv-lav); width: 38px; height: 38px; padding: 0; border: 0; border-radius: 50%;
  display: grid; place-items: center; font-size: 18px; color: var(--text-secondary);
}
.wkh-page .wkh-nav button.glass.is-round::after {
  display: block; content: ''; position: absolute; inset: -3px; width: auto; border-radius: 50%;
  background: none; opacity: 1; transform: none; animation: none;
}
.wkh-page .wkh-nav button.glass.is-round:disabled { opacity: 0.35; cursor: default; }
.wkh-page .wkh-nav button.glass.is-round:disabled::after { display: none; }
.wkh-page .wkh-nav button:focus-visible { outline: 2px solid var(--dv-lav); outline-offset: 2px; }

/* the hero: a frameless lavender→gold halo, the week title, the ring, the sage delta pill */
.wkh-page .wkh-hero {
  --c: var(--dv-lav); --c2: var(--dv-amber);
  overflow-x: clip; display: flex; flex-direction: column; align-items: center; text-align: center;
  padding: 6px 18px 10px;
}
.wkh-page .wkh-hero.uv-halo::before { top: 52%; width: 360px; height: 300px; }
.wkh-page .wkh-title { font-size: 23px; font-weight: 600; letter-spacing: -0.6px; color: var(--text-primary); }
.wkh-page .wkh-herorow { display: flex; flex-direction: column; align-items: center; gap: 10px; margin-top: 12px; }
.wkh-page .wkh-heroside { width: auto; text-align: center; }
.wkh-page .wkh-deltarow { display: flex; align-items: center; justify-content: center; gap: 8px; }
.wkh-page .wk-delta {
  padding: 3px 9px; border-radius: 999px; font-size: 12px; font-weight: 700; color: var(--canvas);
  background: var(--dv-sage); box-shadow: 0 0 10px color-mix(in srgb, var(--dv-sage) 55%, transparent);
}
.wkh-page .wk-delta.is-down {
  background: var(--dv-amber); box-shadow: 0 0 10px color-mix(in srgb, var(--dv-amber) 55%, transparent);
}
.wkh-page .wk-delta.is-flat {
  color: var(--text-secondary); background: rgba(245, 239, 230, 0.05); box-shadow: inset 0 0 0 1px var(--divider);
}
.wkh-page .wkh-prev { margin-left: 0; font-size: 12px; color: var(--text-muted); }
.wkh-page .wkh-trendlbl { color: var(--text-muted); }
.wkh-page .wkh-sub { margin-top: 6px; font-size: 12.5px; line-height: 1.45; color: var(--text-secondary); }

/* the score ring (WeekScoreRing's svg): a lavender sweep with the kit glow; the numeral is the
   §5 score gradient (ink → pale lavender → warm gold) with the breathing glow */
.wkh-page .wk-ring { position: relative; width: 150px; height: 150px; background: none; }
.wkh-page .wk-ring-svg {
  position: absolute; inset: 0; width: 100%; height: 100%; overflow: visible; transform: rotate(-90deg);
}
.wkh-page .wk-ring .uv-ring-track, .wkh-page .wk-ring .uv-ring-prog { stroke-width: 5.5; }
.wkh-page .wk-ring .uv-ring-prog {
  stroke: var(--dv-lav); filter: drop-shadow(0 0 5px color-mix(in srgb, var(--dv-lav) 60%, transparent));
}
.wkh-page .wk-ring .in { position: relative; width: auto; height: auto; background: none; box-shadow: none; gap: 2px; }
.wkh-page .wk-ring b {
  font-family: var(--ff-display); font-size: 56px; font-weight: 300; letter-spacing: -3px; line-height: 1;
  background: linear-gradient(180deg, var(--text-primary), #CFC6EE 60%, #FFD08A);
  -webkit-background-clip: text; background-clip: text; color: transparent;
  filter: drop-shadow(0 0 12px rgba(171, 159, 210, 0.45));
}
.wkh-page .wk-ring b.is-learning {
  font-size: 22px; font-weight: 500; letter-spacing: -0.4px; background: none; color: var(--text-secondary); filter: none;
}
.wkh-page .wk-ring small {
  font-size: 11px; font-weight: 500; letter-spacing: 0; text-transform: none; color: var(--text-muted);
}
@media (prefers-reduced-motion: no-preference) {
  .wkh-page .wk-ring b:not(.is-learning) { animation: uv-glow 5s ease-in-out 1s infinite; }
}

/* section label + honesty footnote */
.wkh-page .wkh-lsec { padding: 10px 2px 0; }
.wkh-page .wkh-lsec-eb { font-size: 10px; letter-spacing: 1.4px; color: var(--text-muted); }
.wkh-page .wkh-foot {
  padding: 12px 10px 0; font-size: 11.5px; font-weight: 400; line-height: 1.5; text-align: center; color: var(--text-muted);
}

/* the four view tiles: analysis lav (wide), lessons gold + days sage (duo), discoveries sky (wide) */
.wkh-page .wkh-wide.glass { --c: var(--dv-lav); display: block; width: 100%; padding: 14px 15px; text-align: left; }
.wkh-page .wkh-wide.disc.glass { --c: var(--dv-sky); }
.wkh-page .wkh-row { gap: 10px; }
.wkh-page .wkh-tiletitle { font-size: 15px; font-weight: 600; letter-spacing: -0.3px; color: var(--text-primary); }
.wkh-page .wkh-chev { font-size: 16px; color: var(--text-muted); }
.wkh-page .wkh-stch {
  padding: 3px 9px; border-radius: 999px; font-size: 10.5px; font-weight: 600; letter-spacing: 0;
  color: color-mix(in srgb, var(--dv-lav) 80%, var(--text-primary));
  background: rgba(245, 239, 230, 0.05); box-shadow: inset 0 0 0 1px var(--divider);
}
.wkh-page .wkh-stch.warn {
  color: color-mix(in srgb, var(--dv-amber) 80%, var(--text-primary));
  box-shadow: inset 0 0 0 1px color-mix(in srgb, var(--dv-amber) 35%, transparent);
}
.wkh-page .wkh-snip { margin-top: 9px; font-size: 13px; font-weight: 400; line-height: 1.5; color: var(--text-secondary); }
.wkh-page .wk-minibars { gap: 6px; height: 46px; margin-top: 10px; }
.wkh-page .wk-minibars i {
  flex: 0 0 14px; border-radius: 4px 4px 2px 2px;
  background: linear-gradient(180deg, color-mix(in srgb, var(--c) 55%, #fff), var(--c));
  box-shadow: 0 0 8px color-mix(in srgb, var(--c) 45%, transparent);
}
.wkh-page .wk-minibars i.sc-non {
  background: transparent; box-shadow: inset 0 0 0 1.5px color-mix(in srgb, var(--c) 40%, transparent);
}
.wkh-page .wkh-widefoot { margin-top: 9px; gap: 8px; font-size: 11px; color: var(--text-muted); }
.wkh-page .wkh-open { font-size: 11px; font-weight: 600; color: color-mix(in srgb, var(--dv-lav) 80%, var(--text-primary)); }
.wkh-page .wkh-disceb { color: color-mix(in srgb, var(--dv-sky) 75%, var(--text-primary)); }
.wkh-page .wkh-disctitle { margin-top: 2px; font-size: 15px; font-weight: 600; letter-spacing: -0.3px; color: var(--text-primary); }
.wkh-page .wkh-discparts { min-width: 0; font-size: 12px; line-height: 1.4; color: var(--text-secondary); }
.wkh-page .wkh-discempty { margin-top: 8px; font-size: 12px; color: var(--text-secondary); }
.wkh-page .wkh-dots { gap: 5px; flex: none; }
.wkh-page .wkh-dots i { width: 9px; height: 9px; border-radius: 50%; background: var(--dc); box-shadow: 0 0 6px var(--dc); }
.wkh-page .wkh-dots i.pattern { --dc: var(--dv-lav); }
.wkh-page .wkh-dots i.fact { --dc: var(--dv-amber); }
.wkh-page .wkh-dots i.life { --dc: var(--dv-sky); }
.wkh-page .wkh-dots i.memoir { --dc: var(--dv-rose); }
.wkh-page .wkh-dots i.prediction { --dc: var(--dv-coral); }

/* „Készítsd el most": the lit lavender CTA with the t-score icon (every colour restated, rule 36) */
.wkh-page .wkh-genbtn {
  display: flex; align-items: center; justify-content: center; gap: 8px; margin: 0; min-height: 44px;
  padding: 10px 16px; border: 0; border-radius: 999px; font-size: 13px; font-weight: 700;
  color: var(--canvas); background: var(--dv-lav);
  box-shadow: 0 0 14px color-mix(in srgb, var(--dv-lav) 55%, transparent);
}
.wkh-page .wkh-genbtn .t-ico { filter: drop-shadow(0 2px 3px rgba(0, 0, 0, 0.35)); }
.wkh-page .wkh-genbtn:disabled { opacity: 0.55; }
.wkh-page .wkh-genbtn:focus-visible { outline: 2px solid var(--dv-lav); outline-offset: 2px; }

.wkh-page .wkh-duo { gap: 10px; }
.wkh-page .wkh-sm.glass {
  --c: var(--dv-amber); display: flex; flex-direction: column; gap: 4px; min-width: 0; min-height: 150px;
  padding: 14px 15px; text-align: left;
}
.wkh-page .wkh-sm.days.glass { --c: var(--dv-sage); }
.wkh-page .wkh-sm .big { margin-top: 4px; font-size: 24px; font-weight: 300; letter-spacing: -1px; color: var(--text-primary); }
.wkh-page .wkh-sm .big span { font-size: 12px; font-weight: 500; letter-spacing: 0; color: var(--text-muted); }
.wkh-page .wkh-sm .lb, .wkh-page .wkh-sm .lb.less, .wkh-page .wkh-sm .lb.days {
  font-size: 14px; font-weight: 600; color: var(--text-primary);
}
.wkh-page .wkh-sm .sub { font-size: 11px; line-height: 1.35; color: var(--text-muted); }
/* the days tile's 7-segment ring (prototype `seg7`): one arc per day in its band hue; a tanulom day
   in the muted hue; nincs adat / future as a bare track. The `i`s keep their titles + state classes. */
.wkh-page .wkh-miniring {
  position: relative; width: 44px; height: 44px; flex: none; gap: 0; margin-top: auto;
  filter: drop-shadow(0 0 3px color-mix(in srgb, var(--dv-sage) 45%, transparent));
}
.wkh-page .wkh-miniring i {
  position: absolute; inset: 0; width: auto; height: auto; border-radius: 50%; box-shadow: none; opacity: 1;
  background: conic-gradient(from calc(var(--k, 0) * 51.43deg + 4deg), var(--c) 0 43deg, transparent 0);
  -webkit-mask: radial-gradient(circle, transparent 16px, #000 16.5px);
  mask: radial-gradient(circle, transparent 16px, #000 16.5px);
}
.wkh-page .wkh-miniring i::after { display: none; }
.wkh-page .wkh-miniring i.is-nodata, .wkh-page .wkh-miniring i.is-future {
  background: conic-gradient(from calc(var(--k, 0) * 51.43deg + 4deg), rgba(245, 239, 230, 0.08) 0 43deg, transparent 0);
}

/* Célok · a hét iránya: one sage glass; the rows, the goal chip and the CTA inside are flat */
.wkh-page .lg-wcard.glass { --c: var(--dv-sage); margin-bottom: 0; padding: 4px 15px 14px; }
.wkh-page .lg-wcard-eb { color: var(--text-muted); }
.wkh-page .lg-wcard-cnt { font-size: 11px; color: var(--text-muted); }
.wkh-page .lg-wgrow + .lg-wgrow { border-top: 1px solid var(--divider); }
.wkh-page .lg-wgrow .nm { font-size: 13.5px; font-weight: 600; color: var(--text-primary); }
.wkh-page .lg-wgrow .x { font-size: 11.5px; line-height: 1.4; color: var(--text-secondary); }
.wkh-page .lg-goalchip {
  min-width: 0; padding: 3px 9px 3px 7px; font-size: 11px; font-weight: 600;
  color: color-mix(in srgb, var(--dc, var(--dv-sage)) 75%, var(--text-primary));
  background: color-mix(in srgb, var(--dc, var(--dv-sage)) 11%, rgba(245, 239, 230, 0.03));
  box-shadow: inset 0 0 0 1px color-mix(in srgb, var(--dc, var(--dv-sage)) 30%, transparent);
}
.wkh-page .lg-goalchip i { box-shadow: 0 0 5px var(--dc, var(--dv-sage)); }
.wkh-page .lg-wcard-cta {
  display: inline-flex; align-items: center; justify-content: center; width: auto; min-height: 44px;
  margin-top: 10px; padding: 0 14px; border: 0; border-radius: 999px; font-size: 12px; font-weight: 600;
  color: color-mix(in srgb, var(--dv-sage) 80%, var(--text-primary));
  background: color-mix(in srgb, var(--dv-sage) 11%, rgba(245, 239, 230, 0.03));
  box-shadow: inset 0 0 0 1px color-mix(in srgb, var(--dv-sage) 30%, transparent);
}

/* Mezo · a következő heted: a lavender glass, prose upright (rule 23) */
.wkh-page .wkn-card.glass { --c: var(--dv-lav); padding: 15px 15px 14px; }
.wkh-page .wkn-head { display: flex; align-items: center; gap: 10px; }
.wkh-page .wkn-eb {
  min-width: 0; font-size: 10px; letter-spacing: 1.4px; white-space: normal;
  color: color-mix(in srgb, var(--dv-lav) 75%, var(--text-primary));
}
.wkh-page .wkn-prose { margin-top: 9px; font-size: 14px; line-height: 1.55; color: var(--text-primary); }
.wkh-page .wkn-ghost { margin-top: 9px; font-size: 13px; line-height: 1.5; color: var(--text-secondary); }

/* the shared FeedbackChips, flat inside these two cards only (the component serves 15 surfaces) */
.wkh-page .wkn-fb .chip, .wk-analysis-page .wka-fb .chip {
  min-height: 36px; border: 0; border-radius: 999px; font-size: 12px; font-weight: 600;
  color: var(--text-secondary); background: rgba(245, 239, 230, 0.05); box-shadow: inset 0 0 0 1px var(--divider);
}
.wkh-page .wkn-fb .chip.brand, .wk-analysis-page .wka-fb .chip.brand {
  color: var(--canvas); background: var(--dv-lav); box-shadow: 0 0 12px color-mix(in srgb, var(--dv-lav) 50%, transparent);
}

/* the loading skeleton on the dark ground */
.wkh-page .wkh-skel, .wkd-page .wkd-skel {
  background: linear-gradient(100deg, rgba(245, 239, 230, 0.04) 30%, rgba(245, 239, 230, 0.09) 50%, rgba(245, 239, 230, 0.04) 70%);
  background-size: 300% 100%;
}
.wkh-page .wkh-skel.ring { width: 150px; height: 150px; margin: 12px auto 0; }

/* ═══ Heti elemzés ═══ */
.wk-analysis-page .wka-card.glass { --c: var(--dv-lav); margin-bottom: 10px; padding: 15px 15px 12px; }
.wk-analysis-page .wka-cardhead .mz-eyebrow {
  font-size: 15px; font-weight: 600; letter-spacing: -0.3px; text-transform: none; color: var(--text-primary);
}
.wk-analysis-page .wka-hint { font-size: 11px; color: var(--text-muted); }
.wk-analysis-page .wka-dcols { gap: 6px; margin-top: 12px; }
.wk-analysis-page .wka-col { min-width: 0; min-height: 44px; }
.wk-analysis-page .wka-col:focus-visible { outline: 2px solid var(--dv-lav); outline-offset: 2px; border-radius: 6px; }
.wk-analysis-page .wka-col .bar {
  max-width: 26px; border-radius: 6px 6px 3px 3px;
  background: linear-gradient(180deg, color-mix(in srgb, var(--bc) 55%, #fff), var(--bc));
  box-shadow: 0 0 10px color-mix(in srgb, var(--bc) 45%, transparent);
}
.wk-analysis-page .wka-col .bar.sc-hi { --bc: var(--dv-sage); }
.wk-analysis-page .wka-col .bar.sc-mid { --bc: var(--dv-amber); }
.wk-analysis-page .wka-col .bar.sc-low { --bc: var(--dv-coral); }
.wk-analysis-page .wka-col .bar.sc-non {
  background: transparent; box-shadow: inset 0 0 0 1.5px color-mix(in srgb, var(--dv-lav) 40%, transparent);
}
.wk-analysis-page .wka-col .vl { font-size: 11px; font-weight: 600; color: var(--text-secondary); }
.wk-analysis-page .wka-col .dw { font-size: 10.5px; font-weight: 500; letter-spacing: 0; color: var(--text-muted); }
.wk-analysis-page .wka-col.is-today .vl, .wk-analysis-page .wka-col.is-today .dw { color: var(--dv-coral); }

.wk-analysis-page .wka-rev.glass { --c: var(--dv-lav); margin-bottom: 10px; padding: 15px 15px 14px; }
.wk-analysis-page .wka-revhead { gap: 10px; }
.wk-analysis-page .wka-revlab {
  flex: 1; min-width: 0; font-size: 15px; font-weight: 600; letter-spacing: -0.3px; text-transform: none;
  color: var(--text-primary);
}
.wk-analysis-page .wka-stamp { font-size: 11px; color: var(--text-muted); }
/* rule 23: multi-sentence Mezo prose is upright Geist, never the italic serif */
.wk-analysis-page .wka-prose {
  margin-top: 10px; font-size: 15px; font-weight: 400; font-style: normal; line-height: 1.6; color: var(--text-primary);
}
.wk-analysis-page .wka-ghost {
  margin-top: 10px; font-size: 14px; font-weight: 400; font-style: normal; line-height: 1.55; color: var(--text-secondary);
}
.wk-analysis-page .wka-ghost b { font-weight: 600; color: var(--text-primary); }
.wk-analysis-page .wka-hlab {
  margin-top: 14px; padding-top: 12px; border-top: 1px solid var(--divider); font-size: 10px; letter-spacing: 1.4px;
  color: var(--text-muted);
}
.wk-analysis-page .wka-hlrow { margin-top: 10px; gap: 6px; }
.wk-analysis-page .wka-hlch.tone-lav { --hc: var(--dv-lav); }
.wk-analysis-page .wka-hlch.tone-gold { --hc: var(--dv-amber); }
.wk-analysis-page .wka-hlch.tone-sky { --hc: var(--dv-sky); }
.wk-analysis-page .wka-hlch.tone-rose { --hc: var(--dv-rose); }
.wk-analysis-page .wka-hlch {
  min-width: 0; max-width: 100%; min-height: 44px; padding: 6px 11px 6px 8px; border: 0; border-radius: 14px;
  font-size: 12px; font-weight: 600; color: var(--text-primary);
  background: color-mix(in srgb, var(--hc) 10%, rgba(245, 239, 230, 0.03));
  box-shadow: inset 0 0 0 1px color-mix(in srgb, var(--hc) 30%, transparent);
}
.wk-analysis-page .wka-hlch em {
  font-size: 9.5px; font-weight: 600; letter-spacing: 1.2px; color: color-mix(in srgb, var(--hc) 80%, var(--text-primary));
}
.wk-analysis-page .wka-hlch .t-ico, .wk-analysis-page .wka-chatch .t-ico {
  filter: drop-shadow(0 2px 3px rgba(0, 0, 0, 0.45));
}
.wk-analysis-page .wka-hlch:focus-visible { outline: 2px solid var(--hc); outline-offset: 2px; }
.wk-analysis-page .wka-revfoot { margin-top: 14px; gap: 8px; }
.wk-analysis-page .wka-chatch {
  min-height: 44px; padding: 6px 14px; border: 0; border-radius: 999px; font-size: 12.5px; font-weight: 600;
  color: var(--text-secondary); background: rgba(245, 239, 230, 0.05); box-shadow: inset 0 0 0 1px var(--divider);
}
.wk-analysis-page .wka-chatch.is-lit {
  color: var(--canvas); background: var(--dv-lav); box-shadow: 0 0 14px color-mix(in srgb, var(--dv-lav) 55%, transparent);
}
.wk-analysis-page .wka-chatch:focus-visible { outline: 2px solid var(--dv-lav); outline-offset: 2px; }
.wk-analysis-page .wka-fb { width: 100%; margin-left: 0; padding-top: 10px; border-top: 1px solid var(--divider); }

.wk-analysis-page .wka-lessgo.glass { --c: var(--dv-amber); gap: 12px; padding: 13px 14px; border-radius: 20px; }
.wk-analysis-page .wka-lessgo .lb { font-size: 15px; font-weight: 600; color: var(--text-primary); }
.wk-analysis-page .wka-lessgo .sub { font-size: 11.5px; color: var(--text-muted); }
.wk-analysis-page .wka-lessgo .chev { font-size: 18px; color: var(--text-muted); }

/* ═══ A hét napjai ═══ */
.wkd-page .wkd-grid { gap: 10px; }
.wkd-page .wkd-tile {
  display: flex; flex-direction: column; gap: 7px; min-width: 0; min-height: 176px; padding: 12px;
  border-radius: 20px; text-align: left; color: var(--text-primary);
}
/* the band hue lives on the tile that wears the glass (rule 4); a tanulom day is lavender */
.wkd-page .wkd-tile.glass { --c: var(--dv-lav); }
.wkd-page .wkd-tile.glass.is-hi { --c: var(--dv-sage); }
.wkd-page .wkd-tile.glass.is-mid { --c: var(--dv-amber); }
.wkd-page .wkd-tile.glass.is-low { --c: var(--dv-coral); }
/* nincs adat + future: dashed, no glass (§3 rank 4) */
.wkd-page .wkd-tile.uv-empty {
  --c: var(--dv-sage); background: rgba(245, 239, 230, 0.025); box-shadow: none; opacity: 1;
  border: 1.5px dashed color-mix(in srgb, var(--c) 45%, transparent);
}
.wkd-page .wkd-tile.is-future.uv-empty { opacity: 0.75; cursor: default; }
.wkd-page .wkd-trow { flex-wrap: wrap; row-gap: 4px; }
.wkd-page .wkd-dow { font-size: 13px; font-weight: 600; color: var(--text-primary); }
.wkd-page .wkd-dow.is-mut { color: var(--text-muted); }
.wkd-page .wkd-dte { font-size: 10.5px; font-weight: 400; letter-spacing: 0; text-transform: none; color: var(--text-muted); }
.wkd-page .wkd-chv { color: var(--text-muted); }
.wkd-page .wkd-ma {
  padding: 2px 6px; border-radius: 999px; font-size: 9.5px; font-weight: 700; letter-spacing: 0.8px;
  color: var(--canvas); background: var(--c); box-shadow: 0 0 8px var(--c);
}
.wkd-page .wkd-scnum { font-size: 30px; font-weight: 300; letter-spacing: -1.4px; }
.wkd-page .wkd-scnum small { font-size: 12px; font-weight: 400; letter-spacing: 0; color: var(--text-muted); }
/* „tanulom" / „nincs adat" must fit a 320px half tile beside the six sparks: smaller, and the
   score row wraps rather than overflow */
.wkd-page .wkd-scnum.is-dash { font-size: 18px; font-weight: 400; letter-spacing: -0.3px; color: var(--text-secondary); }
.wkd-page .wkd-sparks i.is-none { background: rgba(245, 239, 230, 0.08); }
.wkd-page .wkd-chips { gap: 4px; margin-top: auto; }
.wkd-page .wkd-chip {
  min-width: 0; gap: 3px; padding: 3px 7px 3px 4px; border-radius: 999px; font-size: 10.5px; font-weight: 600;
  color: color-mix(in srgb, var(--c) 75%, var(--text-primary));
  background: color-mix(in srgb, var(--c) 11%, rgba(245, 239, 230, 0.03));
  box-shadow: inset 0 0 0 1px color-mix(in srgb, var(--c) 30%, transparent);
}
.wkd-page .wkd-chip.is-mut { opacity: 0.55; }
.wkd-page .wkd-chip.is-note { --c: var(--dv-lav); }
.wkd-page .wkd-chip .t-ico { filter: drop-shadow(0 2px 2px rgba(0, 0, 0, 0.45)); }
.wkd-page .wkd-note { font-size: 11px; font-weight: 400; line-height: 1.4; color: var(--text-muted); }
.wkd-page .wkd-legend {
  justify-content: center; gap: 10px; margin-top: 14px; font-size: 11px; font-weight: 500; color: var(--text-secondary);
}
.wkd-page .wkd-legsep { background: var(--divider); opacity: 1; }
.wkd-page .wkd-foot {
  padding: 10px 10px 0; font-size: 11.5px; font-weight: 400; line-height: 1.5; text-align: center; color: var(--text-muted);
}
.wkd-page .wkd-empty.uv-empty, .wkd-page .wkd-errbox.uv-empty {
  --c: var(--dv-sage); border-radius: 20px; padding: 16px; font-size: 13px; color: var(--text-secondary);
}
.wkd-page .wkd-errbox p { font-size: 13px; color: var(--text-secondary); }
.wkd-page .wkd-retry {
  color: var(--canvas); background: var(--dv-sage); box-shadow: 0 0 14px color-mix(in srgb, var(--dv-sage) 55%, transparent);
}
@media (max-width: 360px) {
  .wkh-page .wkh-cells.mz-mcells { grid-template-columns: repeat(2, minmax(0, 1fr)); }
  .wkd-page .wkd-chip { font-size: 9.5px; }
}

/* ═══ Heti felfedezések ═══ */
/* the head card becomes the prototype's plain centred lead (not a lav card) */
.wkf-page .wkl-head {
  margin: 0 6px 14px; padding: 0; border: 0; border-radius: 0; background: none; box-shadow: none;
  font-size: 13px; font-weight: 400; line-height: 1.5; text-align: center; color: var(--text-secondary);
}
.wkf-page .wkl-head b { font-weight: 600; color: var(--text-primary); }
.wkf-page .wkd-grid { gap: 10px; }
.wkf-page .wkd-tile.glass {
  --c: var(--dv-lav); display: grid; gap: 6px; align-content: start; min-width: 0; min-height: 140px;
  padding: 13px; border-radius: 20px; text-decoration: none;
}
.wkf-page .wkd-tile.wide.glass { min-height: 0; }
.wkf-page .wkd-tile.gold.glass { --c: var(--dv-amber); }
.wkf-page .wkd-tile.sky.glass { --c: var(--dv-sky); }
.wkf-page .wkd-tile.rose.glass { --c: var(--dv-rose); }
.wkf-page .wkd-tile.pred.glass { --c: var(--dv-coral); }
.wkf-page .wkd-row { flex-wrap: wrap; gap: 10px; }
.wkf-page .wkd-grow { flex: 1 1 140px; }
.wkf-page .wkd-eb { font-size: 10px; font-weight: 600; letter-spacing: 1.4px; color: color-mix(in srgb, var(--c) 72%, var(--text-primary)); }
.wkf-page .wkd-tile b { display: block; margin-top: 2px; font-size: 14.5px; font-weight: 600; line-height: 1.35; }
.wkf-page .wkd-meta { font-size: 11px; color: var(--text-muted); }
.wkf-page .wkd-chev { font-size: 16px; color: var(--text-muted); }
/* the status chip: flat, its own hue, a 3D icon + the plain word (no ✓ ▲ ★ ◐ ✗ glyphs) */
.wkf-page .wkd-stch {
  display: inline-flex; align-items: center; gap: 4px; min-width: 0; max-width: 100%;
  padding: 3px 9px 3px 5px; border-radius: 999px; font-size: 11px; font-weight: 600; letter-spacing: 0;
  white-space: nowrap; overflow: hidden; text-overflow: ellipsis;
  color: color-mix(in srgb, var(--sc, var(--text-muted)) 75%, var(--text-primary));
  background: color-mix(in srgb, var(--sc, var(--text-muted)) 11%, rgba(245, 239, 230, 0.03));
  box-shadow: inset 0 0 0 1px color-mix(in srgb, var(--sc, var(--text-muted)) 30%, transparent);
}
.wkf-page .wkd-stch.ok { --sc: var(--dv-sage); }
.wkf-page .wkd-stch.lav { --sc: var(--dv-lav); }
.wkf-page .wkd-stch.warn { --sc: var(--dv-amber); }
.wkf-page .wkd-stch.mut { --sc: var(--text-muted); }
.wkf-page .wkd-stch .t-ico { filter: drop-shadow(0 2px 2px rgba(0, 0, 0, 0.45)); }
.wkf-page .wkl-ghost.uv-empty {
  --c: var(--dv-sky); margin-bottom: 12px; padding: 14px 16px; border-radius: 20px;
  background: rgba(245, 239, 230, 0.025); box-shadow: none;
  border: 1.5px dashed color-mix(in srgb, var(--c) 45%, transparent);
}
.wkf-page .wkl-ghost-tx { font-size: 13px; font-weight: 400; line-height: 1.5; color: var(--text-secondary); }
.wkf-page .wkl-btn.primary {
  color: var(--canvas); background: var(--dv-sky); box-shadow: 0 0 14px color-mix(in srgb, var(--dv-sky) 55%, transparent);
}

/* ═══ A hét tanulságai ═══ */
.wkt-page .wkt-card.glass { --c: var(--dv-amber); margin-bottom: 0; padding: 16px 15px; }
.wkt-page .wkt-card p { margin: 0; font-size: 14px; line-height: 1.55; color: var(--text-secondary); }
.wkt-page .wkt-links { display: flex; flex-wrap: wrap; gap: 6px; }
.wkt-page .wkt-link {
  display: inline-flex; align-items: center; min-width: 0; min-height: 44px; padding: 0 14px; border: 0;
  border-radius: 999px; font-size: 12.5px; font-weight: 600; text-decoration: none;
  color: var(--text-secondary); background: rgba(245, 239, 230, 0.05); box-shadow: inset 0 0 0 1px var(--divider);
}
.wkt-page .wkt-link.is-lit {
  color: var(--canvas); background: var(--dv-amber); box-shadow: 0 0 12px color-mix(in srgb, var(--dv-amber) 50%, transparent);
}
.wkt-page .wkt-link:focus-visible { outline: 2px solid var(--dv-amber); outline-offset: 2px; }
/* ── /uveg en het ── */

/* ── uveg mezo mibol (mezo-me75u.13) ── /mezo/patterns/:key, /mezo/predictions/:id, /mezo/experiments/:id ── */
/* The three „Miből látszik?" deep pages every team-wall post links to. Reference:
   docs/design_2.0/prototypes/uveg-uzenofal.html #minta/*, #elore/*, #kiserlet-oldal/* (owner OK
   2026-09-24). Replaces the Mozaik-wash `.pdt-*` blocks (mezo-0469 „Minta-részlet" + mezo-eq85.6
   „Laborfüzet"). Components: features/insights/components/DetailHero.tsx (frame, hero, pill, ring,
   decisions, dashed states) + the pattern/prediction/experiment parts. Ranking (bible §3.4):
   ONE `.glass` hero per page (`.pdt-hero`, one `--c`); everything else is a flat panel
   (`.pdt-flat`, `.pdt-fold`) with flat cells inside; empty / error / loading are dashed
   (`.pdt-state.uv-empty`); never glass in glass. Evidence-log text is upright (bible U23).
   The `.mzp-*` family stays for the lists (U8b); these pages no longer read it. */

.pdt-page.mz-page { background: transparent; }
.pdt-page .mz-page-head.uv-head { padding: 4px 16px 4px; }
.pdt-nav-eb {
  margin-left: auto; font-size: 9.5px; font-weight: 600; letter-spacing: 1.4px; text-transform: uppercase;
  color: var(--text-muted); text-align: right;
}
.pdt-page .mz-page-body { padding: 0 0 19px; overflow: visible; }
/* the last card scrolls clear of the glass bar + FAB (prototype `.endpad`) */
.pdt-body { display: flex; flex-direction: column; padding-bottom: 64px; }
.pdt-page .rise { --d: calc(var(--i, 0) * 70ms); }

/* one accent per surface — read per rule, never hoisted (bible C.2/20) */
.pdt-tone-lav { --c: var(--dv-lav); }
.pdt-tone-sage { --c: var(--dv-sage); }
.pdt-tone-sky { --c: var(--dv-sky); }
.pdt-tone-gold { --c: var(--dv-amber); }
.pdt-tone-coral { --c: var(--dv-coral); }
.pdt-tone-mute { --c: #8E86A3; }

/* section head (prototype `.sec`) */
.pdt-section-head { display: flex; align-items: center; justify-content: space-between; flex-wrap: wrap; gap: 4px 10px; padding: 24px 18px 12px; }
.pdt-section-head h2 { min-width: 0; font-size: 20px; font-weight: 600; letter-spacing: -0.6px; color: var(--text-primary); }
.pdt-section-head span {
  font-size: 9.5px; font-weight: 600; letter-spacing: 1.2px; text-transform: uppercase; color: var(--text-muted);
  text-align: right;
}

/* ── the ONE glass hero (prototype `.dhero`) ── */
.pdt-page .pdt-hero.glass { margin: 8px 16px 4px; padding: 15px 15px 13px; color: var(--text-primary); }
.pdt-hero-top { display: flex; align-items: center; gap: 11px; }
.pdt-well {
  width: 46px; height: 46px; border-radius: 50%; display: grid; place-items: center; flex: 0 0 auto;
  background: radial-gradient(circle at 35% 28%, #3A332D, color-mix(in srgb, var(--c) 14%, #1E1B18));
  box-shadow: inset 0 1px 0 rgba(255, 244, 230, 0.08), 0 0 14px -4px color-mix(in srgb, var(--c) 50%, transparent);
}
.pdt-domain { display: grid; place-items: center; }
.pdt-hero-t { flex: 1; min-width: 0; }
.pdt-hero-t small {
  display: block; font-size: 9.5px; font-weight: 600; letter-spacing: 1.2px; text-transform: uppercase; color: var(--text-muted);
}
.pdt-hero-t b { display: block; margin-top: 2px; font-size: 16px; font-weight: 650; letter-spacing: -0.3px; line-height: 1.25; }
/* state pill (prototype `.stp`): its OWN tone, lit flat — never glass inside the glass hero */
.pdt-pill {
  flex: 0 0 auto; align-self: flex-start; display: inline-flex; align-items: center; gap: 5px;
  padding: 5px 10px 5px 7px; border-radius: 999px; white-space: nowrap;
  font-size: 9.5px; font-weight: 700; letter-spacing: 0.9px; text-transform: uppercase;
  background: color-mix(in srgb, var(--c) 16%, transparent); color: color-mix(in srgb, var(--c) 80%, #fff);
  box-shadow: inset 0 0 0 1px color-mix(in srgb, var(--c) 38%, transparent);
}
.pdt-hypothesis { margin-top: 12px; font-size: 13px; line-height: 1.5; color: var(--text-secondary); }
.pdt-core { display: grid; grid-template-columns: auto minmax(0, 1fr); gap: 14px; align-items: center; margin-top: 12px; }
.pdt-answer h1 { font-size: 21px; font-weight: 700; letter-spacing: -0.6px; line-height: 1.2; color: var(--text-primary); }
.pdt-answer-sub { margin-top: 6px; font-size: 12.5px; line-height: 1.5; color: var(--text-secondary); }
.pdt-answer-sub b { color: var(--text-primary); font-weight: 650; }
.pdt-finding { margin-top: 6px; font-size: 13px; line-height: 1.5; color: var(--text-secondary); }
.pdt-finding b { color: var(--text-primary); font-weight: 650; }
.pdt-finding strong { font-size: 17px; font-weight: 650; color: color-mix(in srgb, var(--c) 80%, #fff); }
.pdt-finding small { display: block; margin-top: 4px; font-size: 11px; color: var(--text-muted); }
.pdt-hero-copy { margin-top: 12px; font-size: 14px; line-height: 1.55; color: var(--text-primary); }

/* the big day ring (prototype `.bring`); the svg keeps overflow visible so the glow never clips */
.pdt-ring {
  position: relative; width: 104px; height: 104px; display: grid; place-items: center; align-content: center;
  text-align: center;
}
.pdt-ring > svg { position: absolute; inset: 0; width: 100%; height: 100%; transform: rotate(-90deg); overflow: visible; }
.pdt-ring .uv-ring-track, .pdt-ring .uv-ring-prog { stroke-width: 6; }
.pdt-ring.is-unknown .uv-ring-track { stroke-dasharray: 3 4; }
.pdt-ring::before {
  content: ''; position: absolute; inset: 13px; border-radius: 50%;
  background: radial-gradient(circle at 35% 30%, #332D28, color-mix(in srgb, var(--c) 10%, #1E1B18));
  box-shadow: inset 0 1px 0 rgba(255, 244, 230, 0.08), 0 0 16px -4px color-mix(in srgb, var(--c) 45%, transparent);
}
.pdt-ring-n {
  position: relative; display: block; font-size: 40px; font-weight: 300; letter-spacing: -2px; line-height: 1;
  font-variant-numeric: tabular-nums; color: color-mix(in srgb, var(--c) 80%, #fff);
  filter: drop-shadow(0 0 12px color-mix(in srgb, var(--c) 45%, transparent));
}
.pdt-ring-n i { font-style: normal; font-size: 15px; letter-spacing: -0.3px; color: var(--text-secondary); margin-left: 1px; }
.pdt-ring-u { position: relative; display: block; margin-top: 4px; font-size: 7.5px; font-weight: 700; letter-spacing: 1px; color: var(--text-muted); }

/* belief strip inside the hero: a flat cell, big light numeral (prototype `.belief`) */
.pdt-belief {
  display: flex; align-items: center; gap: 11px; margin-top: 12px; padding: 10px 12px; border-radius: 14px;
  background: rgba(245, 239, 230, 0.05); box-shadow: inset 0 0 0 1px var(--divider);
}
.pdt-belief strong {
  flex: 0 0 auto; font-size: 24px; font-weight: 300; letter-spacing: -1px; line-height: 1;
  font-variant-numeric: tabular-nums; color: color-mix(in srgb, var(--c) 80%, #fff);
}
.pdt-belief strong small {
  display: block; margin-top: 3px; font-size: 7.5px; font-weight: 700; letter-spacing: 1px; text-transform: uppercase;
  color: var(--text-muted);
}
.pdt-belief p { font-size: 11px; line-height: 1.45; color: var(--text-secondary); }
.pdt-belief p b { color: var(--text-primary); font-weight: 600; }

/* decisions (prototype `.acts.dec`): three equal flat cells, icon over word; the „no" word warm gold */
.pdt-dec {
  display: grid; grid-template-columns: repeat(3, minmax(0, 1fr)); gap: 6px;
  margin-top: 12px; padding-top: 11px; border-top: 1px solid var(--divider);
}
.pdt-dec.is-two { grid-template-columns: 1fr 1fr; }
.pdt-dec button {
  display: flex; flex-direction: column; align-items: center; justify-content: center; gap: 5px;
  min-height: 62px; padding: 9px 4px 8px; border: 0; border-radius: 14px; cursor: pointer;
  font: 600 12px/1.2 var(--ff-body); color: var(--text-primary);
  background: rgba(245, 239, 230, 0.04); box-shadow: inset 0 0 0 1px var(--divider);
}
.pdt-dec button.is-no { color: #FFD99A; }
.pdt-dec button[aria-pressed='true'] {
  color: #CBC1EC; background: rgba(171, 159, 210, 0.14); box-shadow: inset 0 0 0 1px rgba(171, 159, 210, 0.3);
}
.pdt-dec button:disabled { opacity: 0.55; cursor: default; }
.pdt-dec button:focus-visible { outline: 2px solid var(--c); outline-offset: 2px; }
.pdt-decnote { margin-top: 9px; font-size: 11px; line-height: 1.5; color: var(--text-muted); }
.pdt-decnote b { color: var(--text-secondary); font-weight: 600; }

/* saved observation hero parts (prototype `.seen`, `.xpl`) */
.pdt-seen {
  margin-top: 11px; padding: 10px 12px; border-radius: 14px;
  background: rgba(245, 239, 230, 0.05); box-shadow: inset 0 0 0 1px var(--divider);
}
.pdt-seen small { display: block; font-size: 8.5px; font-weight: 700; letter-spacing: 1.2px; text-transform: uppercase; color: var(--text-muted); }
.pdt-seen p { margin-top: 4px; font-size: 13px; line-height: 1.5; color: var(--text-primary); }
.pdt-xpl { display: grid; gap: 4px; margin-top: 10px; font-size: 11.5px; line-height: 1.5; color: var(--text-secondary); }
.pdt-xpl b { color: var(--text-primary); font-weight: 600; }

/* prediction: expected vs happened (prototype `.vs`) — recessed flat wells inside the hero */
.pdt-vs { display: grid; grid-template-columns: 1fr 1fr; gap: 9px; margin: 12px 0 2px; }
.pdt-vs > div { padding: 11px 12px; border-radius: 16px; background: rgba(25, 22, 20, 0.45); box-shadow: inset 0 0 0 1px var(--divider); }
.pdt-vs small { display: block; margin-bottom: 5px; font-size: 8.5px; font-weight: 700; letter-spacing: 1px; text-transform: uppercase; color: var(--text-muted); }
.pdt-vs p { font-size: 12px; line-height: 1.5; color: var(--text-primary); }

/* experiment: question / outcome well + elapsed day cells (prototype `.outc`, `.xdays`, `.dcell`) */
.pdt-outc { margin-top: 12px; padding: 12px 13px; border-radius: 15px; background: rgba(25, 22, 20, 0.45); box-shadow: inset 0 0 0 1px var(--divider); }
.pdt-outc small { display: block; font-size: 8.5px; font-weight: 700; letter-spacing: 1.2px; text-transform: uppercase; color: var(--text-muted); }
.pdt-outc p { margin-top: 5px; font-size: 14px; line-height: 1.55; color: var(--text-primary); }
.pdt-xdays { margin-top: 12px; }
.pdt-xdays small { display: block; margin-bottom: 6px; font-size: 8.5px; font-weight: 700; letter-spacing: 1.2px; text-transform: uppercase; color: var(--text-muted); }
.pdt-dcells { display: flex; gap: 5px; }
.pdt-dcells span {
  flex: 1; min-width: 0; height: 30px; display: grid; place-items: center; border-radius: 9px;
  border: 1.5px dashed color-mix(in srgb, var(--c) 45%, transparent); font-size: 10px; color: var(--text-secondary);
}
.pdt-dcells span.is-done {
  border: 0; font-weight: 600; color: #191614; background: color-mix(in srgb, var(--c) 70%, transparent);
  box-shadow: 0 0 10px color-mix(in srgb, var(--c) 40%, transparent);
}

/* ── flat panels (prototype `.flatp`) — everything below the hero ── */
.pdt-flat {
  margin: 0 16px; padding: 13px 14px; border-radius: 20px; color: var(--text-primary);
  background: rgba(245, 239, 230, 0.035);
  box-shadow: inset 0 0 0 1px rgba(245, 239, 230, 0.10), 0 8px 18px -14px rgba(0, 0, 0, 0.6);
}
.pdt-prose { font-size: 13.5px; line-height: 1.55; color: var(--text-primary); }
.pdt-prose.is-mute { color: var(--text-secondary); }
.pdt-note { margin-top: 6px; font-size: 12.5px; line-height: 1.5; color: var(--text-secondary); }

/* test plan (prototype `.plan2`, `.ptile`, `.pstrip`) */
.pdt-plan-grid { display: grid; grid-template-columns: minmax(0, 1fr) auto minmax(0, 1fr); gap: 6px; align-items: stretch; }
.pdt-plan-tile {
  --c: var(--dv-lav); padding: 11px 11px 10px; border-radius: 15px;
  background: rgba(245, 239, 230, 0.05); box-shadow: inset 0 0 0 1px var(--divider);
}
.pdt-plan-tile .pdt-tile-label {
  margin-top: 7px; font-size: 8.5px; font-weight: 700; letter-spacing: 1.2px; text-transform: uppercase;
  color: color-mix(in srgb, var(--c) 75%, #fff);
}
.pdt-plan-src { display: block; }
.pdt-plan-nm { margin-top: 3px; font-size: 14px; font-weight: 650; letter-spacing: -0.2px; line-height: 1.25; overflow-wrap: anywhere; }
.pdt-plan-sb { margin-top: 3px; font-size: 10.5px; color: var(--text-muted); }
.pdt-plan-arrow { align-self: center; font-size: 15px; color: var(--text-muted); }
.pdt-plan-strip { display: grid; grid-template-columns: repeat(4, minmax(0, 1fr)); gap: 6px; margin-top: 9px; }
.pdt-plan-strip span {
  padding: 9px 3px 8px; border-radius: 13px; text-align: center;
  font-size: 8px; font-weight: 700; letter-spacing: 0.7px; line-height: 1.3; text-transform: uppercase; color: var(--text-muted);
  background: rgba(245, 239, 230, 0.035); box-shadow: inset 0 0 0 1px var(--divider);
}
.pdt-plan-strip b {
  display: block; margin-bottom: 4px; font-size: 20px; font-weight: 300; letter-spacing: -0.8px; line-height: 1.05;
  text-transform: none; font-variant-numeric: tabular-nums; color: var(--text-primary);
}
.pdt-plan-strip b i { font-style: normal; font-size: 10px; letter-spacing: 0; color: var(--text-secondary); }
.pdt-plan-strip .is-word b { font-size: 14px; letter-spacing: -0.2px; line-height: 21px; }
.pdt-plan-strip .is-key {
  --c: var(--dv-lav);
  background: radial-gradient(90% 90% at 50% 20%, color-mix(in srgb, var(--c) 16%, transparent), transparent 72%);
  box-shadow: inset 0 0 0 1px color-mix(in srgb, var(--c) 45%, transparent);
}
.pdt-plan-strip .is-key b { color: color-mix(in srgb, var(--c) 80%, #fff); filter: drop-shadow(0 0 8px color-mix(in srgb, var(--c) 45%, transparent)); }

/* the days card (prototype `.ctitle` + `.sc` + `.clegend` + `.dlist`) */
.pdt-days { --c: var(--dv-lav); }
.pdt-chart-title { display: flex; align-items: flex-end; justify-content: space-between; gap: 10px; margin-bottom: 2px; }
.pdt-chart-title > span { min-width: 0; }
.pdt-chart-title b { display: block; font-size: 9.5px; font-weight: 700; letter-spacing: 1.3px; text-transform: uppercase; color: var(--text-muted); }
.pdt-chart-sub { display: block; margin-top: 3px; font-size: 11px; color: var(--text-secondary); }
.pdt-chart-title strong {
  flex: 0 0 auto; font-size: 34px; font-weight: 300; letter-spacing: -1.6px; line-height: 1;
  font-variant-numeric: tabular-nums; color: color-mix(in srgb, var(--c) 80%, #fff);
  filter: drop-shadow(0 0 12px color-mix(in srgb, var(--c) 45%, transparent));
}
.pdt-chart-title strong i { font-style: normal; font-size: 12px; letter-spacing: 0; margin-left: 3px; color: var(--text-secondary); }
.pdt-chart { display: block; width: 100%; height: auto; margin-top: 4px; overflow: visible; }
.pdt-chart-grid { stroke: rgba(245, 239, 230, 0.09); stroke-width: 1; stroke-dasharray: 3 4; }
.pdt-chart-tick, .pdt-chart-caption { fill: var(--text-muted); font: 9.5px var(--ff-body); }
.pdt-axis-label { fill: var(--text-secondary); font: 600 10.5px var(--ff-body); }
.pdt-chart-col { fill: rgba(245, 239, 230, 0.035); stroke: rgba(245, 239, 230, 0.09); stroke-width: 1; }
.pdt-group-label { font: 650 10.5px var(--ff-body); }
.pdt-zero-label { fill: #9FC6E8; }
.pdt-one-label { fill: #CBC1EC; }
.pdt-dot-one, .pdt-dot-number { fill: #CBC1EC; filter: drop-shadow(0 0 4px rgba(171, 159, 210, 0.85)); }
.pdt-dot-zero { fill: #9FC6E8; filter: drop-shadow(0 0 4px rgba(127, 178, 222, 0.8)); }
.pdt-median-zero, .pdt-median-one { stroke-width: 2.6; stroke-linecap: round; }
.pdt-median-zero { stroke: var(--dv-sky); }
.pdt-median-one { stroke: var(--dv-lav); }
.pdt-trend { stroke: var(--dv-lav); stroke-width: 2.2; stroke-linecap: round; opacity: 0.8; filter: drop-shadow(0 0 5px rgba(171, 159, 210, 0.6)); }
.pdt-latest-ring { fill: none; stroke: var(--dv-amber); stroke-width: 2.2; filter: drop-shadow(0 0 6px rgba(255, 190, 96, 0.8)); }
.pdt-chart-legend { display: flex; align-items: center; flex-wrap: wrap; gap: 4px 8px; margin-top: 4px; font-size: 11.5px; color: var(--text-secondary); }
.pdt-chart-legend > i {
  flex: 0 0 auto; width: 11px; height: 11px; border-radius: 50%; border: 2px solid var(--dv-amber);
  box-shadow: 0 0 6px rgba(255, 190, 96, 0.7);
}
.pdt-chart-empty.uv-empty {
  margin-top: 4px; padding: 14px; border-radius: 14px; text-align: center; font-size: 11.5px; color: var(--text-secondary);
}
.pdt-days-fold { margin-top: 10px; padding-top: 9px; border-top: 1px solid var(--divider); }
.pdt-days-fold > summary { list-style: none; cursor: pointer; font-size: 12px; font-weight: 600; color: #CBC1EC; }
.pdt-days-fold > summary::-webkit-details-marker { display: none; }
.pdt-days-fold table { width: 100%; margin-top: 8px; border-collapse: collapse; font-size: 12px; font-variant-numeric: tabular-nums; }
.pdt-days-fold th {
  padding: 6px 4px; text-align: left; font-size: 8.5px; font-weight: 700; letter-spacing: 1px; text-transform: uppercase;
  color: var(--text-muted); border-bottom: 1px solid var(--divider);
}
.pdt-days-fold td { padding: 7px 4px; color: var(--text-primary); border-bottom: 1px solid var(--divider); }
.pdt-days-fold tr:last-child td { border-bottom: 0; }
.pdt-days-fold tr.is-last td { color: #FFD99A; }

/* catalog: the two group tiles (prototype `.cmp2 .evc`) — flat cells, one tone each */
.pdt-compare-grid { display: grid; grid-template-columns: 1fr 1fr; gap: 9px; padding: 0 16px; }
.pdt-compare-tile {
  padding: 14px 10px 12px; border-radius: 16px; text-align: center;
  background: rgba(245, 239, 230, 0.05);
  box-shadow: inset 0 0 0 1px var(--divider), inset 0 -14px 24px -16px color-mix(in srgb, var(--c) 50%, transparent);
}
.pdt-compare-tile .pdt-tile-label { font-size: 8.5px; font-weight: 700; letter-spacing: 1.1px; text-transform: uppercase; color: var(--text-muted); }
.pdt-day-count {
  margin: 7px 0 4px; font-size: 36px; font-weight: 300; letter-spacing: -1.8px; line-height: 1.05; font-variant-numeric: tabular-nums;
  color: color-mix(in srgb, var(--c) 82%, #fff); filter: drop-shadow(0 0 12px color-mix(in srgb, var(--c) 45%, transparent));
}
.pdt-day-count small { font-size: 14px; letter-spacing: 0; margin-left: 3px; }
.pdt-typical { margin-top: 8px; font-size: 10.5px; color: var(--text-secondary); }
.pdt-typical b { display: block; margin-top: 2px; font-size: 16px; font-weight: 600; color: var(--text-primary); font-variant-numeric: tabular-nums; }
.pdt-range { margin-top: 4px; font-size: 10.5px; color: var(--text-muted); }
.pdt-need-tag {
  display: inline-flex; margin-top: 8px; padding: 4px 10px; border-radius: 999px; font-size: 10.5px; font-weight: 600;
  color: #FFD99A; background: rgba(255, 190, 96, 0.12); box-shadow: inset 0 0 0 1px rgba(255, 190, 96, 0.35);
}
.pdt-compare-tile.pdt-compare-deficient { box-shadow: inset 0 0 0 1px var(--divider); }

/* catalog: strength over time */
.pdt-str { display: block; width: 100%; height: auto; overflow: visible; }
.pdt-str-guide { stroke: rgba(245, 239, 230, 0.09); stroke-width: 1; stroke-dasharray: 3 4; }
.pdt-str-note, .pdt-str-tick { fill: var(--text-muted); font: 9px var(--ff-body); }
.pdt-str-tick.is-accent { fill: var(--dv-amber); font-weight: 700; }
.pdt-str-line {
  fill: none; stroke: var(--dv-sage); stroke-width: 2.4; stroke-linejoin: round; stroke-linecap: round;
  filter: drop-shadow(0 0 5px rgba(143, 180, 154, 0.6));
}
.pdt-str-dot { fill: #A9D4B3; }
.pdt-str-ring { fill: none; stroke: var(--dv-amber); stroke-width: 2; filter: drop-shadow(0 0 6px rgba(255, 190, 96, 0.7)); }
.pdt-str-confirm { fill: var(--dv-amber); }

/* catalog: take-away tiles (prototype `.stile2`) */
.pdt-story-grid { display: grid; grid-template-columns: 1fr 1fr; gap: 9px; padding: 0 16px; }
.pdt-story-grid .pdt-flat { margin: 0; }
.pdt-story-tile h3 { margin-top: 7px; font-size: 14px; font-weight: 650; letter-spacing: -0.2px; }
.pdt-story-tile p { margin-top: 4px; font-size: 12px; line-height: 1.5; color: var(--text-secondary); }
.pdt-story-tile p b { color: var(--text-primary); font-weight: 600; }

/* folds (prototype `.fold`, `.dgrid`, `.srow`, `.tech`, `.tgrid`) — flat, never glass */
.pdt-fold {
  margin: 0 16px; border-radius: 20px; color: var(--text-primary);
  background: rgba(245, 239, 230, 0.035); box-shadow: inset 0 0 0 1px rgba(245, 239, 230, 0.10);
}
.pdt-fold + .pdt-fold, .pdt-fold + .pdt-flat, .pdt-flat + .pdt-fold { margin-top: 10px; }
.pdt-fold > summary { display: flex; align-items: center; gap: 11px; padding: 12px 14px; list-style: none; cursor: pointer; }
.pdt-fold > summary::-webkit-details-marker { display: none; }
.pdt-fold > summary > span { flex: 1; min-width: 0; }
.pdt-fold > summary b { display: block; font-size: 14px; font-weight: 600; }
.pdt-fold > summary small { display: block; margin-top: 1px; font-size: 11px; color: var(--text-secondary); }
.pdt-fold > summary::after { content: '›'; font-size: 18px; color: var(--text-muted); transition: transform 0.25s var(--uv-ease, ease); }
.pdt-fold[open] > summary::after { transform: rotate(90deg); }
.pdt-fold > summary:focus-visible { outline: 2px solid var(--dv-lav); outline-offset: 2px; border-radius: 20px; }
.pdt-fold-body { padding: 0 14px 14px; }
.pdt-diag-grid { display: grid; grid-template-columns: 1fr 1fr; gap: 7px; }
.pdt-diag-grid > div { padding: 9px 10px; border-radius: 12px; background: rgba(245, 239, 230, 0.04); box-shadow: inset 0 0 0 1px var(--divider); }
.pdt-diag-grid small { display: block; font-size: 8.5px; font-weight: 700; letter-spacing: 1px; text-transform: uppercase; color: var(--text-muted); }
.pdt-diag-grid b { display: block; margin-top: 3px; font-size: 15px; font-weight: 600; font-variant-numeric: tabular-nums; }
.pdt-source-row { display: flex; flex-wrap: wrap; gap: 6px; margin-top: 9px; }
.pdt-source-row span {
  padding: 5px 10px; border-radius: 999px; font-size: 11px; font-weight: 500; color: var(--text-secondary);
  background: rgba(245, 239, 230, 0.05); box-shadow: inset 0 0 0 1px var(--divider);
}
.pdt-tech { margin-top: 10px; }
.pdt-tech > summary { list-style: none; cursor: pointer; font-size: 12px; font-weight: 600; color: #CBC1EC; }
.pdt-tech > summary::-webkit-details-marker { display: none; }
.pdt-tech-grid { display: grid; grid-template-columns: repeat(3, 1fr); gap: 7px; margin-top: 8px; }
.pdt-tech-grid span {
  padding: 9px 6px; border-radius: 12px; text-align: center; font-size: 10px; color: var(--text-muted);
  background: rgba(245, 239, 230, 0.04); box-shadow: inset 0 0 0 1px var(--divider);
}
.pdt-tech-grid b { display: block; margin-bottom: 2px; font-size: 17px; font-weight: 500; color: var(--text-primary); font-variant-numeric: tabular-nums; }
.pdt-tech p { margin-top: 8px; font-size: 11.5px; color: var(--text-secondary); }

/* evidence log + history journal: one rail, tone dots, UPRIGHT text (prototype `.tl`, `.ev`; bible U23) */
.pdt-log { padding: 4px 14px 4px 34px; }
.pdt-timeline { position: relative; }
.pdt-log .pdt-timeline::before, .pdt-journal::before {
  content: ''; position: absolute; left: -16px; top: 14px; bottom: 14px; width: 1.5px; border-radius: 1px;
  background: rgba(245, 239, 230, 0.10);
}
.pdt-journal { padding-left: 20px; }
.pdt-journal::before { left: 4px; }
.pdt-event { --t: #8E86A3; position: relative; padding: 10px 0 11px; border-bottom: 1px solid var(--divider); }
.pdt-event:last-child { border-bottom: 0; }
.pdt-event::before {
  content: ''; position: absolute; left: -20px; top: 14px; width: 9px; height: 9px; border-radius: 50%;
  background: var(--t); box-shadow: 0 0 8px color-mix(in srgb, var(--t) 70%, transparent), 0 0 0 3px #221E1B;
}
.pdt-event-coral { --t: var(--dv-coral); }
.pdt-event-lav { --t: var(--dv-lav); }
.pdt-event-gold { --t: var(--dv-amber); }
.pdt-event-sage { --t: var(--dv-sage); }
.pdt-event-mute { --t: #8E86A3; }
.pdt-evh { display: flex; align-items: center; gap: 7px; flex-wrap: wrap; }
.pdt-evh time { font-size: 10px; font-weight: 600; letter-spacing: 0.6px; color: var(--text-muted); font-variant-numeric: tabular-nums; }
.pdt-evh em {
  font-style: normal; padding: 2px 8px; border-radius: 999px; font-size: 8.5px; font-weight: 700; letter-spacing: 0.9px;
  text-transform: uppercase; background: color-mix(in srgb, var(--t) 16%, transparent); color: color-mix(in srgb, var(--t) 80%, #fff);
}
.pdt-event p { margin-top: 5px; font-size: 13.5px; line-height: 1.55; color: var(--text-primary); font-style: normal; }
.pdt-event p b { font-weight: 650; }
.pdt-event-mute p { color: var(--text-secondary); }
.pdt-event-you p {
  padding: 8px 11px; border-radius: 12px; background: rgba(171, 159, 210, 0.08); box-shadow: inset 3px 0 0 rgba(171, 159, 210, 0.6);
}
.pdt-log-empty.uv-empty { --c: #8E86A3; margin: 0 16px; padding: 13px; border-radius: 20px; font-size: 11.5px; color: var(--text-secondary); }
/* a link out of a sentence (prototype `.srcl`) */
.pdt-srcl {
  display: inline-flex; align-items: center; gap: 6px; margin-top: 4px; padding: 5px 11px; border-radius: 999px;
  font-size: 11.5px; font-weight: 600; text-decoration: none; color: #CBC1EC;
  background: rgba(171, 159, 210, 0.10); box-shadow: inset 0 0 0 1px rgba(171, 159, 210, 0.28);
}

/* catalog: what the app does with it (prototype `.imp` + `.trow`) */
.pdt-impact { margin-top: 10px; }
.pdt-impact-eb { display: block; font-size: 9.5px; font-weight: 700; letter-spacing: 1.3px; text-transform: uppercase; color: var(--text-muted); }
.pdt-impact.is-judged .pdt-impact-eb { color: #A9D4B3; }
.pdt-impact-rows { margin-top: 4px; }
.pdt-impact-future { margin-top: 4px; font-size: 13px; line-height: 1.5; color: var(--text-secondary); }
.pdt-trow {
  display: flex; align-items: center; gap: 10px; width: 100%; padding: 11px 2px; text-decoration: none;
  border-bottom: 1px solid var(--divider);
}
.pdt-trow:last-child { border-bottom: 0; }
.pdt-trow:focus-visible { outline: 2px solid var(--dv-sage); outline-offset: 2px; border-radius: 10px; }
.pdt-trow-t { flex: 1; min-width: 0; }
.pdt-trow-t b { display: block; font-size: 12.5px; font-weight: 600; line-height: 1.35; color: var(--text-primary); }
.pdt-trow-t small { display: block; margin-top: 1px; font-size: 10px; color: var(--text-muted); }
.pdt-chev { flex: 0 0 auto; font-size: 16px; color: var(--text-muted); }

/* saved observation: what the app saw */
.pdt-artifact-mechanism { font-size: 13.5px; line-height: 1.55; color: var(--text-primary); }
.pdt-artifact-evidence { list-style: none; display: grid; gap: 7px; margin: 0; padding: 0; }
.pdt-artifact-mechanism + .pdt-artifact-evidence { margin-top: 9px; }
.pdt-artifact-evidence li { display: flex; align-items: flex-start; gap: 9px; font-size: 13px; line-height: 1.5; color: var(--text-primary); }
.pdt-artifact-evidence .t-ico { margin-top: 2px; }
.pdt-artifact-note { padding: 12px 20px 0; font-size: 12px; color: var(--text-muted); }

/* prediction: confidence strip + the feedback chips (FeedbackChips `.chip`, scoped — bible rule 13) */
.pdt-conf-head { display: flex; align-items: center; gap: 10px; flex-wrap: wrap; }
.pdt-conf-head strong {
  font-size: 30px; font-weight: 300; letter-spacing: -1.4px; line-height: 1; font-variant-numeric: tabular-nums;
  color: #9FC6E8; filter: drop-shadow(0 0 10px rgba(127, 178, 222, 0.5));
}
.pdt-conf-head span { flex: 1; font-size: 12.5px; color: var(--text-secondary); }
.pdt-conf .uv-bar { margin-top: 9px; }
.pdt-feedback .chip {
  display: inline-flex; align-items: center; gap: 6px; min-height: 36px; border: 0; border-radius: 14px;
  font: 600 11.5px/1.2 var(--ff-body); color: var(--text-secondary); cursor: pointer;
  background: rgba(245, 239, 230, 0.05); box-shadow: inset 0 0 0 1px var(--divider);
}
.pdt-feedback .chip[aria-pressed='true'], .pdt-feedback .chip.brand {
  color: #CBC1EC; background: rgba(171, 159, 210, 0.14); box-shadow: inset 0 0 0 1px rgba(171, 159, 210, 0.3);
}
.pdt-feedback .chip:focus-visible { outline: 2px solid var(--dv-lav); outline-offset: 2px; }

/* honest empty / error / loading (prototype `#minta/nincs` `.dash.free`) — dashed, no glass, no glow */
.pdt-state.uv-empty {
  --c: #8E86A3; display: flex; align-items: center; gap: 11px; margin: 8px 16px 0; padding: 13px; border-radius: 20px;
  font-size: 11.5px; line-height: 1.5; color: var(--text-secondary);
}
.pdt-state.uv-empty + .pdt-state { margin-top: 10px; }
.pdt-state.is-loading { border-style: dotted; }
.pdt-state-body { flex: 1; min-width: 0; display: flex; align-items: center; flex-wrap: wrap; gap: 8px 10px; }
.pdt-state-body > span { flex: 1 1 auto; }
.pdt-state b { color: var(--text-primary); }
.pdt-retry {
  flex: 0 0 auto; min-height: 36px; padding: 0 14px; border: 0; border-radius: 999px; cursor: pointer;
  font: 600 12px/1 var(--ff-body); color: #CBC1EC;
  background: rgba(171, 159, 210, 0.14); box-shadow: inset 0 0 0 1px rgba(171, 159, 210, 0.3);
}
.pdt-retry:focus-visible { outline: 2px solid var(--dv-lav); outline-offset: 2px; }

@media (max-width: 374px) {
  .pdt-hero-top { flex-wrap: wrap; }
  .pdt-hero-t { flex: 1 1 calc(100% - 60px); }
  .pdt-hero-top .pdt-pill { margin: 2px 0 0 57px; }
}
@media (max-width: 360px) {
  .pdt-story-grid, .pdt-compare-grid { grid-template-columns: 1fr; }
  .pdt-ring { width: 92px; height: 92px; }
  .pdt-ring-n { font-size: 34px; }
  .pdt-answer h1 { font-size: 19px; }
  .pdt-section-head h2 { font-size: 18px; }
  .pdt-plan-strip b { font-size: 17px; }
  .pdt-vs { grid-template-columns: 1fr; }
}

/* motion: one-shot on the kit's `.mz-play` arming (a back-pop arrives settled); calm after */
@keyframes pdt-ring { from { stroke-dasharray: 0 100; } }
@keyframes pdt-pop { from { opacity: 0; transform: scale(0.3); } }
@keyframes pdt-draw { from { stroke-dashoffset: 100; } }
@media (prefers-reduced-motion: no-preference) {
  .mz-play .pdt-ring .uv-ring-prog { animation: pdt-ring 1.1s var(--uv-ease, ease) 0.25s both; }
  .mz-play .pdt-chart circle[class^='pdt-dot'] { transform-box: fill-box; transform-origin: center; animation: pdt-pop 0.4s ease-out 0.5s both; }
  .mz-play .pdt-latest-ring { transform-box: fill-box; transform-origin: center; animation: pdt-pop 0.5s ease-out 1.1s both; }
  .pdt-well .t-ico { animation: uv-float 5s ease-in-out 1s infinite; }
}
@media (prefers-reduced-motion: reduce) {
  .pdt-fold > summary::after { transition: none; }
}
/* ── /uveg mezo mibol ── */
/* ── uveg en2 novekedes (mezo-me75u.7) ── /me/growth/skillek, /me/growth/naplo, /me/growth/kituntetesek ── */
/* Reference: docs/design_2.0/prototypes/src/uveg-en2-body.html `skillek()`, `gnaplo()`, `kitunt()`
   (owner OK). Every rule is scoped to a page root — `.grs-page` (Skillek), `.grn-page` (Napló),
   `.gra-page` (Kitüntetések) — because the `gr-*` family is shared with the Rutin hub (`gr-band`,
   `gr-band-top`, `gr-band-chip`; bible rule 13). Ranking (§3.4): each hero is a frameless halo
   (PageHero `art`); the streak is a second frameless coral halo with the big t-flame. Primary
   objects wear glass with ONE `--c`: the three skill bands (lav / sage / amber), the „Ez a hét" tile
   and each journal day (sky), the titles card and the perks card (amber). Everything inside them —
   chips, Lv plaques, mini-cells, the segment, the saver row, title/perk rows — is flat; the badge
   cells are flat with a glowing sage ring. The empty journal and the no-perk card are dashed. */
.grs-page.mz-page, .grn-page.mz-page, .gra-page.mz-page { background: transparent; }
.grs-page .mz-page-body, .grn-page .mz-page-body, .gra-page .mz-page-body { padding: 2px 16px 20px; }
.grs-page .mz-principle, .grn-page .mz-principle, .gra-page .mz-principle {
  margin: 22px 6px 0; padding-top: 12px; border-top: 1px solid var(--divider);
  font-size: 11.5px; font-weight: 400; line-height: 1.5; text-align: center; color: var(--text-muted);
}
.grs-page .mz-eyebrow, .grn-page .mz-eyebrow, .gra-page .mz-eyebrow {
  font-size: 9.5px; font-weight: 600; letter-spacing: 1.4px; color: var(--text-muted);
}
.grs-page .mz-page-hero.uv-hero { --c2: var(--dv-amber); }
.grn-page .mz-page-hero.uv-hero { --c2: var(--dv-lav); }
.gra-page .mz-page-hero.uv-hero { --c2: var(--dv-amber); }

/* ── the band card: the glass body restated (`.gr-band.lav|sage|amber|sky` outrank .glass, rule 11) ── */
.grs-page .gr-band.glass, .grn-page .gr-band.glass, .gra-page .gr-band.glass,
.grn-page .gr-day.glass {
  display: block; width: 100%; margin: 0 0 10px; padding: 14px 14px 12px; border: 0; border-radius: 22px;
  color: var(--text-primary);
  background:
    radial-gradient(120% 90% at 0% 0%, color-mix(in srgb, var(--c) 22%, transparent), transparent 62%),
    linear-gradient(160deg, rgba(52, 46, 41, 0.72), rgba(30, 27, 24, 0.60));
  box-shadow:
    0 16px 30px -16px rgba(0, 0, 0, 0.75),
    0 0 26px -6px color-mix(in srgb, var(--c) 30%, transparent),
    inset 0 1px 0 rgba(255, 244, 230, 0.10),
    inset 0 -14px 26px -18px color-mix(in srgb, var(--c) 55%, transparent);
}
.grs-page .gr-band-top, .grn-page .gr-band-top, .gra-page .gr-titcard .gr-titworn {
  display: flex; align-items: center; gap: 10px; min-width: 0; margin-bottom: 10px;
}
.grs-page .gr-band-art, .grn-page .gr-band-art { flex: 0 0 auto; }
.grs-page .gr-band-ttl, .grn-page .gr-band-ttl {
  flex: 1; min-width: 0; font-size: 15.5px; font-weight: 600; letter-spacing: -0.3px; color: var(--text-primary);
}
/* the band chip: a flat accent chip (prototype `.flatchip`), shrinkable (rule 14) */
.grs-page .gr-band-chip, .grn-page .gr-band-chip {
  flex: 0 1 auto; min-width: 0; margin-left: 0; overflow: hidden; text-overflow: ellipsis; white-space: nowrap;
  padding: 4px 9px; border-radius: 999px; font-size: 11px; font-weight: 600; letter-spacing: 0; text-transform: none;
  color: color-mix(in srgb, var(--c) 75%, var(--text-primary));
  background: color-mix(in srgb, var(--c) 11%, rgba(245, 239, 230, 0.03));
  box-shadow: inset 0 0 0 1px color-mix(in srgb, var(--c) 30%, transparent);
}
/* the foot line: label left, value right, over a hairline (prototype `.foot2`) */
.grs-page .gr-band.glass .gr-band-foot, .grn-page .gr-band.glass .gr-band-foot {
  display: flex; justify-content: space-between; gap: 10px; margin-top: 10px; padding: 10px 0 0;
  border-top: 1px solid var(--divider); font-size: 12px; font-weight: 400; color: var(--text-secondary);
}
.grs-page .gr-band.glass .gr-band-foot b, .grn-page .gr-band.glass .gr-band-foot b { font-weight: 600; color: var(--text-primary); }

/* ═══ Skillek ═══ */
/* stat strip: three flat cells; the muscle best lit gold (prototype `.sstrip4 .cell.gold`) */
.grs-page .grs-stats.mz-statstrip { display: grid; grid-template-columns: repeat(3, minmax(0, 1fr)); gap: 8px; margin-bottom: 14px; }
.grs-page .grs-stats .mz-statcell {
  min-width: 0; padding: 10px 6px; border: 0; border-radius: 16px; text-align: center;
  background: rgba(245, 239, 230, 0.04); box-shadow: inset 0 0 0 1px var(--divider);
}
.grs-page .grs-stats .mz-statcell b { display: block; font-size: 20px; font-weight: 600; letter-spacing: -0.6px; color: var(--text-primary); }
.grs-page .grs-stats .mz-statcell:nth-child(3) b {
  color: color-mix(in srgb, var(--dv-amber) 70%, var(--text-primary));
  text-shadow: 0 0 12px color-mix(in srgb, var(--dv-amber) 45%, transparent);
}
.grs-page .grs-stats .mz-statcell small { display: block; margin-top: 2px; font-size: 10px; line-height: 1.3; color: var(--text-muted); }

/* skill row: icon / monogram well · name + meter (+ perk hint, goal chip) · Lv plaque */
.grs-page .gr-skl { display: flex; align-items: center; gap: 11px; padding: 8px 0; }
.grs-page .gr-skl + .gr-skl { border-top: 1px solid var(--divider); }
.grs-page .gr-band:not(.expanded) .gr-skl.more { display: none; }
.grs-page .gr-skl-ic {
  width: 34px; height: 34px; flex: 0 0 auto; display: grid; place-items: center;
  border-radius: 50%; background: none; font: 700 12px/1 var(--ff-body);
}
.grs-page .gr-skl-ic.mono {
  color: color-mix(in srgb, var(--c) 85%, var(--text-primary));
  background: radial-gradient(circle at 35% 28%, #3A332D, color-mix(in srgb, var(--c) 16%, #1E1B18));
  box-shadow: inset 0 1px 0 rgba(255, 244, 230, 0.08), 0 0 10px -3px color-mix(in srgb, var(--c) 55%, transparent);
}
.grs-page .gr-skl-grow { flex: 1; min-width: 0; }
.grs-page .gr-skl-nm {
  display: block; width: auto; overflow: hidden; text-overflow: ellipsis; white-space: nowrap;
  font-size: 14px; font-weight: 600; color: var(--text-primary);
}
.grs-page .gr-skl .gr-tbar, .grs-page .gr-skl .gr-tbar i { overflow: visible; }
.grs-page .gr-skl .gr-tbar { display: block; height: 5px; margin-top: 6px; border-radius: 3px; background: rgba(245, 239, 230, 0.07); }
.grs-page .gr-skl .gr-tbar i {
  border-radius: 3px;
  background: linear-gradient(90deg, color-mix(in srgb, var(--c) 55%, #fff), var(--c));
  box-shadow: 0 0 8px color-mix(in srgb, var(--c) 60%, transparent);
}
.grs-page .gr-skl-perk { display: block; margin-top: 4px; font-size: 10.5px; font-weight: 500; color: var(--text-muted); }
.grs-page .gr-skl .lg-goalchip {
  max-width: 100%; margin-top: 5px; padding: 0; overflow: hidden; text-overflow: ellipsis; white-space: nowrap;
  font-size: 10.5px; font-weight: 500; color: var(--text-secondary); background: none;
}
.grs-page .gr-skl .lg-goalchip i { box-shadow: 0 0 5px var(--dc, var(--dv-coral)); }
/* the Lv plaque (prototype `.lvp`) */
.grs-page .gr-skl-lv {
  flex: 0 0 auto; min-width: 0; padding: 4px 9px; border-radius: 10px;
  font-size: 11.5px; font-weight: 700; font-variant-numeric: tabular-nums;
  color: color-mix(in srgb, var(--c) 85%, var(--text-primary));
  background: color-mix(in srgb, var(--c) 12%, rgba(245, 239, 230, 0.03));
  box-shadow: inset 0 0 0 1px color-mix(in srgb, var(--c) 32%, transparent);
}
/* „Mind a n ▸": a flat full-width button (prototype `.skmore`) */
.grs-page .gr-expand {
  display: block; width: 100%; min-height: 36px; margin-top: 8px; padding: 8px; border-radius: 12px;
  font-size: 12px; font-weight: 600; text-align: center; color: var(--text-secondary);
  background: rgba(245, 239, 230, 0.03);
}
.grs-page .gr-expand:focus-visible { outline: 2px solid var(--c); outline-offset: 2px; }

/* ═══ Napló ═══ */
.grn-page .gr-band.glass .mz-mcells { display: grid; grid-template-columns: repeat(4, minmax(0, 1fr)); gap: 5px; margin-top: 8px; }
.grn-page .gr-band.glass .mz-mcells .mz-c-sage  { --c: var(--dv-sage); }
.grn-page .gr-band.glass .mz-mcells .mz-c-amber { --c: var(--dv-amber); }
.grn-page .gr-band.glass .mz-mcells .mz-c-lav   { --c: var(--dv-lav); }
.grn-page .gr-band.glass .mz-mcells .mz-c-sky   { --c: var(--dv-sky); }
.grn-page .gr-band.glass .mz-mcells > span {
  min-width: 0; padding: 5px 2px 4px; border-radius: 10px; text-align: center;
  background: color-mix(in srgb, var(--c) 10%, rgba(245, 239, 230, 0.03));
  box-shadow: inset 0 0 0 1px color-mix(in srgb, var(--c) 28%, transparent);
}
.grn-page .gr-band.glass .mz-mcells b { display: block; font-size: 14px; font-weight: 600; color: color-mix(in srgb, var(--c) 85%, var(--text-primary)); }
.grn-page .gr-band.glass .mz-mcells small {
  display: block; margin: 0; font-size: 9px; font-weight: 500; letter-spacing: 0; text-transform: none; opacity: 1;
  color: var(--text-muted); overflow: hidden; text-overflow: ellipsis; white-space: nowrap;
}
/* day head over each day card (prototype `.dayh`) */
.grn-page .gr-dayhd { display: flex; align-items: baseline; gap: 8px; padding: 16px 2px 6px; }
.grn-page .gr-dayhd .dow { font-size: 14px; font-weight: 600; letter-spacing: 0; text-transform: none; color: var(--text-primary); }
.grn-page .gr-dayhd .dt { font-size: 11px; color: var(--text-muted); }
.grn-page .gr-dayhd .xp {
  margin-left: auto; font-size: 12px; font-weight: 700; color: color-mix(in srgb, var(--dv-lav) 70%, var(--text-primary));
}
.grn-page .gr-day.glass { padding: 4px 14px; }
.grn-page .gr-jrow { display: flex; align-items: flex-start; gap: 10px; padding: 9px 0; font-size: 13.5px; }
.grn-page .gr-jrow + .gr-jrow { border-top: 1px solid var(--divider); }
.grn-page .gr-jrow .gr-jk { width: 26px; height: 26px; margin-top: 1px; flex: 0 0 auto; }
.grn-page .gr-jrow .gr-jdot { display: grid; place-items: center; }
.grn-page .gr-jrow .gr-jdot i { width: 7px; height: 7px; border-radius: 50%; background: var(--text-muted); }
.grn-page .gr-jgrow { flex: 1; min-width: 0; }
.grn-page .gr-jrow .tx { display: block; font-size: 13.5px; font-weight: 600; line-height: 1.35; color: var(--text-primary); }
.grn-page .gr-jmeta {
  display: flex; flex-wrap: wrap; align-items: center; gap: 0 4px; margin-top: 3px;
  font-size: 11px; font-style: normal; color: var(--text-muted);
}
.grn-page .gr-jmeta .gr-jskill { width: 14px; height: 14px; filter: none; }
.grn-page .gr-jrow.gone { opacity: 0.5; }
.grn-page .gr-jrow.gone .tx { font-weight: 500; color: var(--text-primary); }
/* no entry yet: the dashed empty state, no glass */
.grn-page .gr-jempty.uv-empty {
  --c: var(--dv-sky); margin: 12px 0 0; padding: 18px 16px; border-radius: 22px;
  font-size: 12.5px; font-weight: 400; line-height: 1.5; text-align: center; color: var(--text-secondary);
}

/* ═══ Kitüntetések ═══ */
/* section heads (prototype `.h3`): eyebrow left, the count right */
.gra-page .gr-h3 { display: flex; align-items: baseline; justify-content: space-between; gap: 10px; padding: 18px 2px 8px; }
.gra-page .gr-h3-em { font-size: 11px; font-style: normal; font-weight: 500; color: var(--text-muted); }
.gra-page .gr-h3-em.gr-coins { display: inline-flex; align-items: center; gap: 4px; font-weight: 600; color: var(--text-secondary); }

/* the streak: a frameless coral halo, the big flame, the numeral, a glowing milestone bar */
.gra-page .gr-streak.gr-band {
  --c: var(--dv-coral);
  position: relative; isolation: isolate; overflow: visible;
  display: grid; grid-template-columns: auto minmax(0, 1fr); gap: 14px; align-items: center;
  margin: 0; padding: 14px 4px 8px; border: 0; border-radius: 0; background: none; box-shadow: none;
}
/* the halo overflows only to the LEFT (never scrollable) and stays below the scroller's top edge,
   which would otherwise cut it flat (the body scrolls, so it clips) */
.gra-page .gr-streak.gr-band::before {
  content: ''; position: absolute; left: 24%; top: 44%; z-index: -1; pointer-events: none;
  width: 320px; height: 220px; transform: translate(-50%, -50%);
  background: radial-gradient(ellipse at 50% 50%,
    color-mix(in srgb, var(--dv-coral) 30%, transparent),
    color-mix(in srgb, var(--dv-amber) 12%, transparent) 42%, transparent 66%);
}
.gra-page .gr-streak .gr-flame {
  width: 86px; height: 86px;
  filter: drop-shadow(0 10px 12px rgba(0, 0, 0, 0.5)) drop-shadow(0 0 16px color-mix(in srgb, var(--dv-coral) 45%, transparent));
}
.gra-page .gr-streak-body { min-width: 0; }
.gra-page .gr-streak-num { display: flex; flex-wrap: wrap; align-items: baseline; gap: 0 4px; }
.gra-page .gr-streak-n {
  font-family: var(--ff-display); font-size: 52px; font-weight: 300; letter-spacing: -3px; line-height: 1; color: var(--text-primary);
}
.gra-page .gr-streak-u { font-size: 14px; font-weight: 400; color: var(--text-secondary); }
.gra-page .gr-streak .gr-msbar { height: 5px; margin-top: 8px; border-radius: 3px; overflow: visible; background: rgba(245, 239, 230, 0.07); }
.gra-page .gr-streak .gr-msbar i {
  border-radius: 3px;
  background: linear-gradient(90deg, color-mix(in srgb, var(--dv-coral) 55%, #fff), var(--dv-coral));
  box-shadow: 0 0 8px color-mix(in srgb, var(--dv-coral) 60%, transparent);
}
.gra-page .gr-streak-next { margin-top: 6px; font-size: 12px; line-height: 1.45; color: var(--text-secondary); }
.gra-page .gr-streak-next b { font-weight: 600; color: var(--text-primary); }
.gra-page .gr-streak-p { margin-top: 4px; font-size: 11.5px; line-height: 1.45; color: var(--text-muted); }
/* the saver: a flat row (prototype `.saver`) — under the streak AND at the end of the shop list */
.gra-page .gr-saver {
  display: flex; align-items: center; gap: 11px; min-width: 0; padding: 11px 12px; border-radius: 18px;
  background: rgba(245, 239, 230, 0.04); box-shadow: inset 0 0 0 1px var(--divider);
}
.gra-page .gr-streak .gr-saver { grid-column: 1 / -1; margin-top: 6px; }
.gra-page .gr-titlist .gr-saver { margin-top: 8px; }
.gra-page .gr-saver-art { width: 34px; height: 34px; filter: none; }
.gra-page .gr-saver-grow { flex: 1; min-width: 0; }
.gra-page .gr-saver-nm { font-size: 13.5px; font-weight: 600; color: var(--text-primary); }
.gra-page .gr-saver-sub { display: flex; align-items: center; gap: 4px; margin-top: 2px; font-size: 11px; color: var(--text-muted); }
.gra-page .gr-coin { width: 14px; height: 14px; filter: none; }
.gra-page .gr-h3-em .gr-coin { width: 16px; height: 16px; }

/* action pills: constructive buys are lit (coral on the streak, gold in the titles card); Felvesz flat */
.gra-page .gr-titact {
  flex: 0 0 auto; min-height: 36px; padding: 7px 13px; border: 0; border-radius: 999px;
  font: 600 12px/1.2 var(--ff-body); color: var(--text-secondary);
  background: rgba(245, 239, 230, 0.05); box-shadow: inset 0 0 0 1px var(--divider);
}
.gra-page .gr-titact.buy {
  --c: var(--dv-amber); font-weight: 700; color: #191614; background: var(--c);
  box-shadow: 0 0 14px color-mix(in srgb, var(--c) 55%, transparent);
}
.gra-page .gr-streak .gr-titact.buy { --c: var(--dv-coral); }
.gra-page .gr-titact:disabled { opacity: 0.45; cursor: default; }
.gra-page .gr-titact:focus-visible { outline: 2px solid var(--c, var(--dv-amber)); outline-offset: 2px; }
.gra-page .gr-titact.worn {
  min-height: 0; padding: 0; font-size: 10px; font-weight: 700; letter-spacing: 0.8px; text-transform: uppercase;
  color: color-mix(in srgb, var(--dv-amber) 70%, var(--text-primary)); background: none; box-shadow: none;
}

/* titles: ONE amber glass card — worn title, a flat segment (the active one lit), flat rows */
.gra-page .gr-titcard.glass { margin: 0; }
.gra-page .gr-titcard .gr-titworn { margin-bottom: 0; font-size: 15.5px; font-weight: 600; letter-spacing: -0.3px; color: var(--text-primary); }
.gra-page .gr-titcard .gr-titworn b { font-weight: 600; color: color-mix(in srgb, var(--dv-amber) 70%, var(--text-primary)); }
.gra-page .gr-titcard .gr-seg {
  display: inline-flex; gap: 2px; margin: 12px 0 4px; padding: 3px; border-radius: 999px;
  background: rgba(245, 239, 230, 0.05); box-shadow: inset 0 0 0 1px var(--divider);
}
.gra-page .gr-titcard .gr-seg button {
  flex: 0 0 auto; min-height: 36px; padding: 7px 16px; border-radius: 999px;
  font-size: 12.5px; font-weight: 600; color: var(--text-secondary); background: none; box-shadow: none;
}
.gra-page .gr-titcard .gr-seg button.on {
  color: #191614; background: var(--dv-amber); box-shadow: 0 0 12px color-mix(in srgb, var(--dv-amber) 45%, transparent);
}
.gra-page .gr-titcard .gr-seg button:focus-visible { outline: 2px solid var(--dv-amber); outline-offset: 2px; }
.gra-page .gr-titcard .gr-titnote { margin-top: 8px; font-size: 12.5px; color: var(--text-secondary); }
.gra-page .gr-titrow { display: flex; align-items: center; gap: 10px; min-height: 44px; padding: 8px 0; }
.gra-page .gr-titrow + .gr-titrow { border-top: 1px solid var(--divider); }
.gra-page .gr-titrow .nm { flex: 1; min-width: 0; font-size: 14px; font-weight: 600; color: var(--text-primary); }
.gra-page .gr-titrow.lock .nm { font-weight: 500; color: var(--text-secondary); }
.gra-page .gr-titrow:has(.worn) .nm { color: color-mix(in srgb, var(--dv-amber) 70%, var(--text-primary)); }
.gra-page .gr-titrow .sub { display: inline-flex; align-items: center; gap: 4px; font-size: 11px; color: var(--text-muted); }
.gra-page .gr-lockmk { font-size: 10px; font-weight: 700; letter-spacing: 0.8px; color: var(--text-muted); }

/* badges: flat cells, each a glowing sage ring around its 3D art */
.gra-page .gr-bdggrid { display: grid; grid-template-columns: repeat(3, minmax(0, 1fr)); gap: 8px; }
.gra-page .gr-bdg {
  --c: var(--dv-sage);
  display: flex; flex-direction: column; align-items: center; gap: 5px; min-width: 0; padding: 10px 4px 9px;
  border: 0; border-radius: 16px; text-align: center;
  background: rgba(245, 239, 230, 0.035); box-shadow: inset 0 0 0 1px var(--divider);
}
.gra-page .gr-bdg:not(.done) { opacity: 0.72; }
.gra-page .gr-bdg .gr-ring {
  position: relative; width: 54px; height: 54px; display: grid; place-items: center; background: none;
}
.gra-page .gr-bdg .gr-ring::after { display: none; }
.gra-page .gr-bdg .gr-ring svg { position: absolute; inset: 0; width: 100%; height: 100%; transform: rotate(-90deg); }
.gra-page .gr-bdg .gr-ring .uv-ring-track, .gra-page .gr-bdg .gr-ring .uv-ring-prog { stroke-width: 5; }
.gra-page .gr-bdg .gr-bdg-art { position: relative; width: 28px; height: 28px; }
.gra-page .gr-bdg b { font-size: 11px; font-weight: 600; line-height: 1.25; color: var(--text-primary); overflow-wrap: anywhere; }
.gra-page .gr-bdg small {
  display: inline-flex; align-items: center; gap: 3px; font-size: 9.5px; font-weight: 500;
  font-variant-numeric: tabular-nums; color: var(--text-muted);
}
.gra-page .gr-bdg.done small { font-weight: 600; color: color-mix(in srgb, var(--dv-sage) 60%, var(--text-primary)); }
.gra-page .gr-bdg .gr-bdg-tick { width: 12px; height: 12px; filter: none; }

/* perks: ONE amber glass card of flat rows; none yet → dashed */
.gra-page .gr-perks.glass { margin: 0; padding: 4px 14px 12px; }
.gra-page .gr-perks.uv-empty { margin: 0; padding: 16px; border-radius: 22px; background: rgba(245, 239, 230, 0.025); box-shadow: none; }
.gra-page .gr-perks .gr-band-foot {
  margin: 0; padding: 10px 0 0; font-size: 12px; font-weight: 400; line-height: 1.5; color: var(--text-secondary);
}
.gra-page .gr-perks.glass .gr-band-foot { border-top: 1px solid var(--divider); }
.gra-page .gr-perks.uv-empty .gr-band-foot { padding: 0; text-align: center; }
.gra-page .gr-perkrow { display: flex; align-items: center; gap: 10px; padding: 9px 0; }
.gra-page .gr-perkrow + .gr-perkrow { border-top: 1px solid var(--divider); }
.gra-page .gr-perk-pi {
  flex: 0 0 auto; width: auto; height: auto; padding: 4px 9px; border-radius: 10px;
  font-size: 11.5px; font-weight: 700; color: color-mix(in srgb, var(--dv-amber) 85%, var(--text-primary));
  background: color-mix(in srgb, var(--dv-amber) 12%, rgba(245, 239, 230, 0.03));
  box-shadow: inset 0 0 0 1px color-mix(in srgb, var(--dv-amber) 32%, transparent);
}
.gra-page .gr-perk-grow { flex: 1; min-width: 0; }
.gra-page .gr-perkrow .pn { font-size: 13.5px; font-weight: 600; color: var(--text-primary); }
.gra-page .gr-perkrow .pe { font-size: 11px; font-weight: 400; color: var(--text-muted); }
.gra-page .gr-perkrow .pl { margin: 0; font-size: inherit; font-weight: 500; color: var(--text-secondary); }

/* motion: the hero flame drifts like every üveg hero icon; reduced motion shows it still */
@media (prefers-reduced-motion: no-preference) {
  .gra-page .gr-streak .gr-flame { animation: uv-float 5s ease-in-out 1s infinite; }
}
@media (prefers-reduced-motion: reduce) {
  .gra-page .gr-streak .gr-flame { animation: none; }
}
/* ── /uveg en2 novekedes ── */

/* ── uveg en2 rutin (mezo-me75u.7) ── /me/rutin(+/uj,/lanc/:key,/szokasok,/szokas/:key(+/szerkesztes)) + rutin sheets ── */
/* Ranking (bible §3.4, prototype uveg-en2.html #rutin/#lanc/#szokasok/#szokas/#szerk/#uj, sheets
   `ai`/`chain`/`anchor`). Every rule is scoped to a page root — `.rt-uv` plus one of `.rt-hub`,
   `.rt-lanc`, `.rt-szokasok`, `.rt-szokas`, `.rt-szerk`, `.rt-wiz` — or to the rutin sheets
   (`.rt-sheet`): the `rt-*` / `gr-*` families are old shared names (rule 13). /nap/rutin is U3's
   (`.nr-page`) and is not touched here.
   Hub: the halo hero, flat stat cells, a flat day pill, then ONE loud glass — „Következik" with its
   lit gold tick well — the gold active-chain glass, two glass doors, a flat „＋ Új lánc". Chain page
   (lavender): one glass stack card holding the rope rows (flat nodes, flat anchor chips). Szokásaid:
   flat stage filters, a 2-col grid of glass habit tiles tinted by their stage (rule 46). Szokás:
   glass poster / context rings / history / recipe, every inner row flat. Editor + wizard: forms, so
   the controls stay flat on the ground; the recipe sentence, the framework cards and the effort card
   are the glass objects. Danger buttons stay flat coral outlines (rule 29). */

/* the ground: the aurora shows through; quiet principle footnote; kit eyebrows */
.rt-uv.mz-page { background: transparent; }
.rt-uv .mz-page-body { padding: 2px 16px 24px; }
.rt-uv .uv-hero { --c2: var(--dv-lav); }
.rt-lanc .uv-hero { --c2: var(--dv-amber); }
.rt-uv .mz-principle {
  margin: 22px 10px 0; padding-top: 12px; border-top: 1px solid var(--divider);
  font-size: 11.5px; font-weight: 400; line-height: 1.5; text-align: center; color: var(--text-muted);
}
.rt-uv .mz-eyebrow { font-size: 9.5px; font-weight: 600; letter-spacing: 1.3px; color: var(--text-muted); }

/* the glass body restated where an old `rt-*` / `gr-*` / `mz-*` rule would keep its light skin
   (rule 11): washes, borders, coloured shadows and the `.is-fogg.on`-style modifiers. */
.rt-hub .rt-nextcard.glass, .rt-hub .rt-chaintile.glass, .rt-hub .mz-tile.glass.rt-door, .rt-hub .gr-chain.glass,
.rt-lanc .rt-macard.glass, .rt-szokasok .rt-htile.glass, .rt-szokas .rt-poster.glass, .rt-szokas .rt-ctxgrid.glass,
.rt-uv .rt-fcard.glass, .rt-uv .rt-sentence.glass, .rt-wiz .rt-fwcard.glass, .sheet.glass.rt-sheet {
  border: 0;
  background:
    radial-gradient(120% 90% at 0% 0%, color-mix(in srgb, var(--c) 22%, transparent), transparent 62%),
    linear-gradient(160deg, rgba(52, 46, 41, 0.72), rgba(30, 27, 24, 0.6));
  box-shadow:
    0 16px 30px -16px rgba(0, 0, 0, 0.75),
    0 0 26px -6px color-mix(in srgb, var(--c) 30%, transparent),
    inset 0 1px 0 rgba(255, 244, 230, 0.1),
    inset 0 -14px 26px -18px color-mix(in srgb, var(--c) 55%, transparent);
}

/* the head's lit action pill („AI javaslat", „Szerkesztés", „Mentés"): constructive → lit */
.rt-uv .mz-page-head .mz-pgact.rt-act {
  --c: var(--dv-amber);
  margin-left: auto; display: inline-flex; align-items: center; gap: 6px; min-height: 38px; padding: 0 14px;
  border: 0; border-radius: 999px; font: 700 12.5px/1.2 var(--ff-body); white-space: nowrap; cursor: pointer;
  color: var(--canvas); background: var(--c);
  box-shadow: 0 0 14px color-mix(in srgb, var(--c) 55%, transparent);
}
.rt-uv .mz-page-head .mz-pgact.rt-act.is-lav { --c: var(--dv-lav); }
.rt-uv .mz-pgact.rt-act .t-ico { filter: drop-shadow(0 1px 2px rgba(0, 0, 0, 0.3)); }
.rt-uv .mz-pgact.rt-act:disabled { opacity: 0.45; box-shadow: none; cursor: default; }
.rt-uv .mz-pgact.rt-act:focus-visible { outline: 2px solid var(--text-primary); outline-offset: 2px; }
/* ghost pills (the wizard's „Mégse" and „← Vissza") */
.rt-uv .rt-ghostpill {
  display: inline-flex; align-items: center; justify-content: center; min-height: 38px; padding: 0 14px;
  border: 0; border-radius: 999px; font: 600 12.5px/1.2 var(--ff-body); cursor: pointer;
  color: var(--text-secondary); background: rgba(245, 239, 230, 0.05); box-shadow: inset 0 0 0 1px var(--divider);
}
.rt-wiz .mz-page-head .pgact.rt-ghostpill { margin-left: auto; }
/* the lit CTA (wizard „Tovább / Mentés", sheet „Javasolj / Mentés") — every colour restated (rule 36) */
.rt-uv .cta-primary.rt-litpill, .rt-sheet .cta-primary.rt-litpill {
  --c: var(--dv-amber);
  width: 100%; min-height: 46px; display: inline-flex; align-items: center; justify-content: center; gap: 7px;
  padding: 0 16px; border: 0; border-radius: 999px; font: 700 14px/1.2 var(--ff-body);
  color: var(--canvas); background: var(--c);
  box-shadow: 0 0 14px color-mix(in srgb, var(--c) 55%, transparent);
}
.rt-sheet.is-lav .cta-primary.rt-litpill { --c: var(--dv-lav); }
.rt-uv .cta-primary.rt-litpill .t-ico, .rt-sheet .cta-primary.rt-litpill .t-ico { filter: drop-shadow(0 1px 2px rgba(0, 0, 0, 0.3)); }
.rt-uv .cta-primary.rt-litpill:disabled, .rt-sheet .cta-primary.rt-litpill:disabled { opacity: 0.42; box-shadow: none; }
/* flat full-width buttons („＋ Új lánc", „＋ Új habit ebbe a láncba") */
.rt-hub .cta-ghost.rt-flatbtn, .rt-lanc .rt-addrow {
  display: flex; align-items: center; justify-content: center; gap: 8px; width: 100%; min-height: 46px;
  margin: 10px 0 0; padding: 12px 16px; border: 0; border-radius: 18px; cursor: pointer;
  font: 600 14px/1.2 var(--ff-body); color: var(--text-secondary);
  background: rgba(245, 239, 230, 0.05); box-shadow: inset 0 0 0 1px var(--divider);
}
/* the dashed empty line (rank 4) */
.rt-uv .rt-emptyline, .rt-sheet .rt-emptyline {
  --c: var(--dv-amber);
  display: block; margin: 10px 0 0; padding: 14px 16px; border-radius: 16px;
  font-size: 12.5px; line-height: 1.5; text-align: center; color: var(--text-secondary);
}
.rt-sheet.is-lav .rt-emptyline { --c: var(--dv-lav); }
.rt-lanc .rt-emptyline { --c: var(--dv-lav); }

/* ── the form language (flat controls on the ground) ── */
.rt-uv .rt-fcard:not(.glass) { margin: 18px 0 0; padding: 0; border: 0; border-radius: 0; background: none; box-shadow: none; }
.rt-uv .rt-fcard.glass { --c: var(--dv-amber); margin: 16px 0 0; padding: 14px 15px; border-radius: 22px; }
.rt-uv .rt-flabel, .rt-sheet .rt-flabel {
  display: flex; align-items: baseline; gap: 7px; margin: 0 2px 7px;
  font: 600 9.5px/1.3 var(--ff-body); letter-spacing: 1.3px; text-transform: uppercase; color: var(--text-muted);
}
.rt-uv .rt-opt, .rt-sheet .rt-opt { font-weight: 500; letter-spacing: 0.2px; text-transform: none; color: var(--text-muted); }
.rt-uv .rt-fin, .rt-sheet .rt-fin {
  display: block; width: 100%; margin-top: 8px; padding: 11px 13px; border: 0; border-radius: 13px;
  font: 400 14px/1.3 var(--ff-body); color: var(--text-primary); color-scheme: dark;
  background: rgba(245, 239, 230, 0.05); box-shadow: inset 0 0 0 1px var(--divider);
}
.rt-uv .rt-flabel + .rt-fin, .rt-sheet .rt-flabel + .rt-fin { margin-top: 0; }
.rt-uv .rt-fin + .rt-flabel, .rt-uv .rt-hint + .rt-flabel { margin-top: 14px; }
.rt-uv .rt-fin::placeholder, .rt-sheet .rt-fin::placeholder { color: var(--text-muted); }
.rt-uv .rt-fin:focus, .rt-sheet .rt-fin:focus {
  outline: none; box-shadow: inset 0 0 0 1.5px color-mix(in srgb, var(--dv-amber) 70%, transparent);
}
.rt-uv .rt-hint, .rt-sheet .rt-hint { margin-top: 7px; font-size: 11.5px; line-height: 1.5; color: var(--text-muted); }
/* chips: flat, the picked one lit in its accent */
.rt-uv .rt-chips, .rt-sheet .rt-chips { display: flex; flex-wrap: wrap; gap: 6px; }
.rt-uv .rt-chips button, .rt-sheet .rt-chips button {
  --c: var(--dv-lav);
  display: inline-flex; align-items: center; gap: 6px; min-width: 0; max-width: 100%; min-height: 34px; padding: 7px 12px;
  border: 0; border-radius: 999px; font: 600 12px/1.2 var(--ff-body); cursor: pointer;
  white-space: nowrap; overflow: hidden; text-overflow: ellipsis;
  color: var(--text-secondary); background: rgba(245, 239, 230, 0.05); box-shadow: inset 0 0 0 1px var(--divider);
}
.rt-uv .rt-chips.is-gold button, .rt-sheet .rt-chips.is-gold button { --c: var(--dv-amber); }
.rt-uv .rt-chips.is-sage button, .rt-sheet .rt-chips.is-sage button { --c: var(--dv-sage); }
.rt-uv .rt-chips button.on, .rt-sheet .rt-chips button.on {
  color: var(--canvas); background: var(--c); box-shadow: 0 0 12px color-mix(in srgb, var(--c) 50%, transparent);
}
.rt-uv .rt-chips button .t-ico, .rt-sheet .rt-chips button .t-ico { width: 18px; height: 18px; filter: none; }
.rt-uv .rt-chip-src { font-size: 10px; font-weight: 700; letter-spacing: 0; color: inherit; opacity: 0.65; }
/* the two-way segmented pill (Keret, Hogyan pipálódik?) */
.rt-uv .rt-swseg {
  display: flex; gap: 0; padding: 3px; border-radius: 999px;
  background: rgba(245, 239, 230, 0.05); box-shadow: inset 0 0 0 1px var(--divider);
}
.rt-uv .rt-swseg button {
  --c: var(--dv-amber);
  flex: 1; min-width: 0; display: inline-flex; align-items: center; justify-content: center; gap: 6px;
  min-height: 38px; padding: 6px 10px; border: 0; border-radius: 999px; background: none; cursor: pointer;
  font: 600 12.5px/1.2 var(--ff-body); color: var(--text-secondary);
}
.rt-uv .rt-swseg button .t-ico { width: 20px; height: 20px; filter: none; }
.rt-uv .rt-swseg button.on, .rt-uv .rt-swseg button.on.is-clear {
  color: var(--canvas); background: var(--c); box-shadow: 0 0 12px color-mix(in srgb, var(--c) 45%, transparent);
}
/* tips + warnings: a faint accent cell with its 3D icon (💡 ⚓ ◈ ✂ ⏸ ⚠ → sprite symbols) */
.rt-uv .rt-tip, .rt-uv .rt-warn {
  --c: var(--dv-amber);
  display: flex; gap: 10px; align-items: flex-start; margin: 12px 0 0; padding: 11px 13px; border-radius: 16px;
  font-size: 12.5px; font-weight: 400; line-height: 1.5; color: var(--text-secondary);
  background: color-mix(in srgb, var(--c) 7%, transparent);
  box-shadow: inset 0 0 0 1px color-mix(in srgb, var(--c) 22%, transparent);
}
.rt-uv .rt-tip.is-lav { --c: var(--dv-lav); }
.rt-uv .rt-tip.is-warn, .rt-uv .rt-warn { --c: var(--dv-coral); }
.rt-uv .rt-tip .t-ico, .rt-uv .rt-warn .t-ico { flex: none; width: 26px; height: 26px; }
.rt-uv .rt-tip b, .rt-uv .rt-warn b { font-weight: 600; color: var(--text-primary); }
.rt-uv .rt-lockline { display: flex; gap: 7px; align-items: flex-start; margin-top: 8px; font-size: 11.5px; line-height: 1.45; color: var(--text-muted); }
.rt-uv .rt-lockline .t-ico { flex: none; width: 16px; height: 16px; margin-top: 1px; filter: none; }
.rt-uv .rt-lockline b { font-weight: 600; color: var(--text-secondary); }
/* the recipe sentence: ONE gold glass, the filled slots lit, the open ones dashed */
.rt-uv .rt-sentence.glass { --c: var(--dv-amber); display: block; margin: 12px 0 0; padding: 14px 15px 15px; border-radius: 22px; }
.rt-uv .rt-sentence-lb {
  display: flex; align-items: center; gap: 6px; margin-bottom: 8px;
  font: 600 9.5px/1.3 var(--ff-body); letter-spacing: 1.3px; text-transform: uppercase;
  color: color-mix(in srgb, var(--c) 75%, var(--text-primary));
}
.rt-uv .rt-sentence-lb .t-ico { width: 18px; height: 18px; filter: none; }
.rt-uv .rt-sentence-lb-sub { color: var(--text-muted); }
.rt-uv .rt-sentence-tx { margin: 0; font-family: var(--ff-body); font-style: normal; font-size: 15px; line-height: 1.6; color: var(--text-secondary); }
.rt-uv .rt-sentence.is-big .rt-sentence-tx { font-size: 16.5px; }
.rt-uv .rt-sentence .rt-blank {
  display: inline-block; min-width: 70px; padding: 0 2px; border-bottom: 1.5px dashed color-mix(in srgb, var(--c) 60%, transparent);
  color: var(--text-muted);
}
.rt-uv .rt-sentence .rt-blank.is-filled {
  display: inline; min-width: 0; padding: 0 4px; border-bottom: 0; border-radius: 6px; font-weight: 600;
  color: var(--text-primary); background: color-mix(in srgb, var(--c) 14%, transparent);
}
/* the effort grid (Fogg ability factors): flat 3-way pills, the grade colour carries the grade */
.rt-uv .rt-effrow { padding: 8px 0; }
.rt-uv .rt-effrow + .rt-effrow { border-top: 1px solid var(--divider); }
.rt-uv .rt-effrow-h { display: flex; align-items: baseline; gap: 8px; margin-bottom: 7px; }
.rt-uv .rt-effrow-h b { font-size: 12.5px; font-weight: 600; color: var(--text-primary); }
.rt-uv .rt-effrow-h small { margin-left: auto; font-size: 10.5px; color: var(--text-muted); text-align: right; }
.rt-uv .rt-seg3 {
  display: flex; gap: 0; padding: 3px; border-radius: 999px;
  background: rgba(245, 239, 230, 0.05); box-shadow: inset 0 0 0 1px var(--divider);
}
.rt-uv .rt-seg3 button {
  --c: var(--dv-amber);
  flex: 1; min-width: 0; min-height: 32px; padding: 5px 6px; border: 0; border-radius: 999px; background: none; cursor: pointer;
  font: 600 11px/1.2 var(--ff-body); color: var(--text-secondary);
}
.rt-uv .rt-seg3 button.is-sage { --c: var(--dv-sage); }
.rt-uv .rt-seg3 button.is-coral { --c: var(--dv-coral); }
.rt-uv .rt-seg3 button.is-sage.on, .rt-uv .rt-seg3 button.is-gold.on, .rt-uv .rt-seg3 button.is-coral.on {
  font-weight: 700; color: var(--canvas); background: var(--c);
  box-shadow: 0 0 12px color-mix(in srgb, var(--c) 45%, transparent);
}
.rt-uv .rt-effout {
  display: flex; align-items: baseline; gap: 10px; margin-top: 10px; padding: 11px 0 0; border-radius: 0;
  border-top: 1px solid var(--divider); background: none; box-shadow: none;
}
.rt-uv .rt-effout-lvl { font-size: 17px; font-weight: 600; color: color-mix(in srgb, var(--dv-amber) 70%, var(--text-primary)); }
.rt-uv .rt-effout-lvl small { font-size: 11px; font-weight: 400; color: var(--text-muted); }
.rt-uv .rt-effout-xp b { font: 300 22px/1 var(--ff-display); letter-spacing: -0.5px; color: var(--text-primary); }
.rt-uv .rt-effout-xp small { font: 600 9.5px/1.3 var(--ff-body); letter-spacing: 1.2px; color: var(--text-muted); }
.rt-uv .rt-fcard.glass > .rt-hint, .rt-uv .rt-fcard.glass > .rt-lockline { margin-top: 10px; }
/* destructive: flat coral outlines, never lit (rule 29); deleting is the quieter, two-tap one */
.rt-uv .rt-danger, .rt-sheet .rt-danger {
  display: flex; align-items: center; justify-content: flex-start; gap: 10px; width: 100%; min-height: 48px;
  margin: 8px 0 0; padding: 11px 16px; border: 0; border-radius: 18px; cursor: pointer; text-align: left;
  font: 600 14px/1.3 var(--ff-body); color: color-mix(in srgb, var(--dv-coral) 55%, var(--text-primary));
  background: color-mix(in srgb, var(--dv-coral) 7%, transparent);
  box-shadow: inset 0 0 0 1px color-mix(in srgb, var(--dv-coral) 35%, transparent);
}
.rt-uv .rt-danger .t-ico, .rt-sheet .rt-danger .t-ico { flex: none; width: 24px; height: 24px; }
.rt-uv .rt-fcard + .rt-danger, .rt-uv .rt-addrow + .rt-danger { margin-top: 18px; }
.rt-uv .rt-danger.is-hard { color: var(--text-secondary); background: none; box-shadow: inset 0 0 0 1px color-mix(in srgb, var(--dv-coral) 22%, transparent); }
.rt-uv .rt-danger.is-hard.is-armed {
  color: color-mix(in srgb, var(--dv-coral) 60%, var(--text-primary));
  background: color-mix(in srgb, var(--dv-coral) 10%, transparent); box-shadow: inset 0 0 0 1.5px var(--dv-coral);
}
.rt-uv .rt-danger:disabled, .rt-sheet .rt-danger:disabled { opacity: 0.45; cursor: default; }

/* ── Rutin hub ── */
.rt-hub .mz-statstrip.rt-strip { display: grid; grid-template-columns: repeat(3, minmax(0, 1fr)); gap: 8px; }
.rt-hub .rt-strip .mz-statcell {
  min-width: 0; padding: 10px 6px; border: 0; border-radius: 14px; text-align: center;
  background: rgba(245, 239, 230, 0.04); box-shadow: inset 0 0 0 1px var(--divider);
}
.rt-hub .rt-strip .mz-statcell b { font: 600 20px/1.15 var(--ff-display); letter-spacing: -0.6px; color: var(--text-primary); }
.rt-hub .rt-strip .mz-statcell:first-child b {
  color: color-mix(in srgb, var(--dv-amber) 70%, var(--text-primary));
  text-shadow: 0 0 12px color-mix(in srgb, var(--dv-amber) 45%, transparent);
}
.rt-hub .rt-strip .mz-statcell small { display: block; margin-top: 2px; font-size: 10px; line-height: 1.3; color: var(--text-muted); }
/* the day pill: DayNavigator styles itself inline — the scoped !important is U3's precedent
   (.nr-page .nr-daynav) and the only way to re-dress it without touching the shared markup */
.rt-hub .gr-daynav {
  margin: 12px 0 4px; padding: 4px; border-radius: 999px;
  background: rgba(245, 239, 230, 0.04); box-shadow: inset 0 0 0 1px var(--divider);
}
.rt-hub .gr-daynav > div { width: 100%; }
.rt-hub .gr-daynav > div > button {
  width: 34px !important; height: 34px !important; border: 0 !important; border-radius: 50% !important;
  color: var(--text-secondary) !important; background: transparent !important;
}
.rt-hub .gr-daynav > div > button:disabled { opacity: 0.3 !important; }
.rt-hub .gr-daynav button[aria-label="Dátum kiválasztása"] {
  font-size: 13px !important; font-weight: 600 !important; color: var(--text-primary) !important;
}
/* „Következik": the loudest thing on the hub — gold glass, big name, the lit gold tick well */
.rt-hub .rt-nextcard.glass {
  --c: var(--dv-amber);
  display: flex; align-items: center; gap: 14px; margin: 12px 0 10px; padding: 16px; border-radius: 24px;
}
.rt-hub .rt-nextcard-tx { flex: 1; min-width: 0; }
.rt-hub .rt-nextcard-eb {
  font: 600 9.5px/1.2 var(--ff-body); letter-spacing: 1.3px; text-transform: uppercase;
  color: color-mix(in srgb, var(--c) 80%, var(--text-primary));
}
.rt-hub .rt-nextcard-nm {
  margin-top: 3px; font-size: 19px; font-weight: 600; letter-spacing: -0.5px; line-height: 1.25; color: var(--text-primary);
  overflow: hidden; text-overflow: ellipsis; white-space: nowrap;
}
.rt-hub .rt-nextcard-cue { margin-top: 4px; font-size: 12px; line-height: 1.4; color: var(--text-secondary); }
.rt-hub .rt-nextcard .rt-bigtick, .rt-hub .rt-nextcard .rt-bigtick.is-allon {
  width: 62px; height: 62px; flex: none; padding: 0; border: 0; border-radius: 50%; cursor: pointer;
  display: grid; place-items: center; color: var(--text-primary);
  background: radial-gradient(circle at 35% 28%, #4A3F2F, color-mix(in srgb, var(--dv-amber) 22%, #1E1B18));
  box-shadow:
    inset 0 1px 0 rgba(255, 244, 230, 0.12),
    0 0 20px -2px color-mix(in srgb, var(--dv-amber) 55%, transparent),
    inset 0 0 0 1.5px color-mix(in srgb, var(--dv-amber) 55%, transparent);
}
.rt-hub .rt-bigtick:focus-visible { outline: 2px solid var(--dv-amber); outline-offset: 3px; }
/* the active chain: gold glass with the day's dots and the count on the right */
.rt-hub .rt-chaintile.glass {
  --c: var(--dv-amber);
  display: flex; align-items: center; gap: 12px; width: 100%; margin: 0 0 10px; padding: 13px 14px; border-radius: 20px;
  font: inherit; text-align: left; color: var(--text-primary); cursor: pointer;
}
.rt-hub .rt-chaintile-bd { flex: 1; min-width: 0; }
.rt-hub .rt-chaintile-eb {
  display: block; font: 600 9.5px/1.3 var(--ff-body); letter-spacing: 1.3px; text-transform: uppercase; color: var(--text-muted);
  overflow: hidden; text-overflow: ellipsis; white-space: nowrap;
}
.rt-hub .rt-chdots { display: flex; flex-wrap: wrap; gap: 5px; margin-top: 7px; }
.rt-hub .rt-chdots i { flex: 0 0 9px; width: 9px; height: 9px; border-radius: 50%; background: rgba(245, 239, 230, 0.1); box-shadow: none; }
.rt-hub .rt-chdots i.is-d { background: var(--c); box-shadow: 0 0 6px var(--c); }
.rt-hub .rt-chdots i.is-now {
  background: transparent;
  box-shadow: inset 0 0 0 2px var(--c), 0 0 8px color-mix(in srgb, var(--c) 60%, transparent);
}
.rt-hub .rt-chaintile-dg {
  flex: none; margin: 0; font: 600 20px/1 var(--ff-display); letter-spacing: -0.6px; font-variant-numeric: tabular-nums;
  color: var(--text-primary);
}
.rt-hub .rt-chaintile-dg small { margin-left: 3px; font-size: 10.5px; font-weight: 500; letter-spacing: 0; color: var(--text-muted); }
.rt-hub .rt-chaintile-cv { flex: none; font-size: 20px; color: var(--text-muted); }
/* the two doors: glass tiles, icon top-left, eyebrow, the line */
.rt-hub .mz-mosaic.rt-doors { gap: 10px; }
.rt-hub .mz-tile.glass.rt-door {
  display: flex; flex-direction: column; gap: 4px; min-width: 0; min-height: 128px; padding: 13px 13px 12px;
  border-radius: 20px; text-align: left; color: var(--text-primary);
}
.rt-hub .mz-tile.rt-door.is-lav { --c: var(--dv-lav); }
.rt-hub .mz-tile.rt-door.is-sage { --c: var(--dv-sage); }
.rt-hub .rt-door .mz-spotwrap { order: 1; flex: none; display: block; margin-bottom: auto; padding: 0; }
.rt-hub .rt-door .mz-tile-top { order: 2; margin-top: 8px; }
.rt-hub .rt-door .mz-eyebrow { color: color-mix(in srgb, var(--c) 70%, var(--text-primary)); }
.rt-hub .rt-door .mz-tile-line {
  order: 3; text-align: left; font-size: 14px; font-weight: 600; letter-spacing: -0.2px; line-height: 1.3; color: var(--text-primary);
}
/* a past day: the summary lead, lavender callouts, one gold glass per chain with flat rows */
.rt-hub .rt-pastsum { padding: 10px 2px 12px; }
.rt-hub .gr-daysum { font-size: 13.5px; font-weight: 400; line-height: 1.5; color: var(--text-secondary); }
.rt-hub .gr-daysum b { font-weight: 600; color: var(--text-primary); }
.rt-hub .gr-daysum .rt-xp { color: color-mix(in srgb, var(--dv-amber) 70%, var(--text-primary)); }
.rt-hub .gr-softnote {
  --c: var(--dv-lav);
  margin-top: 10px; padding: 12px 14px; border-radius: 18px; font-size: 13px; font-weight: 400; line-height: 1.45;
  color: var(--text-secondary); background: color-mix(in srgb, var(--c) 8%, transparent); box-shadow: inset 3px 0 0 var(--c);
}
.rt-hub .gr-chain.glass { --c: var(--dv-amber); margin: 0 0 10px; padding: 14px 15px 8px; border-radius: 22px; }
.rt-hub .gr-chain .gr-band-top { display: flex; align-items: center; gap: 10px; margin-bottom: 4px; }
.rt-hub .gr-chain .gr-band-top .mz-eyebrow {
  flex: 1; min-width: 0; font-size: 15px; font-weight: 600; letter-spacing: -0.3px; text-transform: none; color: var(--text-primary);
}
.rt-hub .gr-chain .gr-band-chip {
  flex: none; margin-left: auto; padding: 4px 9px; border-radius: 10px; font-size: 11.5px; font-weight: 700; letter-spacing: 0;
  color: color-mix(in srgb, var(--c) 85%, var(--text-primary));
  background: color-mix(in srgb, var(--c) 12%, rgba(245, 239, 230, 0.03));
  box-shadow: inset 0 0 0 1px color-mix(in srgb, var(--c) 32%, transparent);
}
.rt-hub .gr-chain .gr-chainrow { gap: 10px; padding: 9px 0; font-size: 13.5px; }
.rt-hub .gr-chain .gr-chainrow + .gr-chainrow { border-top: 1px solid var(--divider); }
.rt-hub .gr-chain .gr-chainrow .tx { font-weight: 600; color: var(--text-primary); }
.rt-hub .gr-chain .gr-chainrow.skip .tx { opacity: 0.5; color: var(--text-primary); }
.rt-hub .gr-chain .gr-chainrow .gr-ck, .rt-hub .gr-chain .gr-chainrow.done .gr-ck {
  width: 26px; height: 26px; border: 0; background: none; color: inherit;
}
.rt-hub .gr-chain .rt-dotgone { display: grid; place-items: center; }
.rt-hub .gr-chain .rt-dotgone i { width: 8px; height: 8px; border-radius: 50%; background: rgba(245, 239, 230, 0.18); }

/* ── Lánc (lavender) ── */
.rt-lanc .rt-fcard:not(.glass) { margin-top: 14px; }
.rt-lanc .rt-macard.glass { --c: var(--dv-lav); display: block; margin: 14px 0 0; padding: 12px 14px; border-radius: 22px; }
.rt-lanc .rt-macard-head { display: flex; align-items: center; justify-content: space-between; gap: 8px; margin: 0 0 2px; padding: 2px 0 4px; }
.rt-lanc .rt-macard-t { font: 600 9.5px/1.3 var(--ff-body); letter-spacing: 1.3px; text-transform: uppercase; color: var(--text-muted); }
.rt-lanc .rt-macard-c { margin-left: auto; font-size: 11px; font-weight: 600; color: var(--text-muted); }
.rt-lanc .rt-stackrow { grid-template-columns: 30px minmax(0, 1fr) auto; column-gap: 12px; padding: 0; }
.rt-lanc .rt-srail { height: 58px; }
.rt-lanc .rt-srail::before, .rt-lanc .rt-srail::after { width: 2px; height: 14px; background: color-mix(in srgb, var(--c) 40%, transparent); }
.rt-lanc .rt-srail.is-linked::before { background: color-mix(in srgb, var(--c) 55%, transparent); }
.rt-lanc .rt-srail.is-broken::before {
  background: repeating-linear-gradient(180deg, color-mix(in srgb, var(--c) 45%, transparent) 0 4px, transparent 4px 8px);
}
/* the rope starts at the first row: the head, not a row, is the card's first div */
.rt-lanc .rt-macard-head + .rt-stackrow .rt-srail::before { display: none; }
.rt-lanc .rt-snode {
  width: 30px; height: 30px; border: 0; border-radius: 50%; display: grid; place-items: center;
  font-size: 14px; color: var(--text-muted); background: rgba(245, 239, 230, 0.05); box-shadow: inset 0 0 0 1px var(--divider);
}
.rt-lanc .rt-snode .t-ico { width: 22px; height: 22px; }
.rt-lanc .rt-snode.on {
  background: color-mix(in srgb, var(--c) 18%, #1E1B18);
  box-shadow: inset 0 0 0 1.5px color-mix(in srgb, var(--c) 60%, transparent), 0 0 10px -2px var(--c);
}
.rt-lanc .rt-snode.next {
  color: color-mix(in srgb, var(--dv-amber) 70%, var(--text-primary)); background: transparent;
  box-shadow: inset 0 0 0 2px var(--dv-amber), 0 0 12px -2px var(--dv-amber);
}
.rt-lanc .rt-sbody { min-width: 0; }
.rt-lanc .rt-sbody-nm { font-size: 14px; font-weight: 600; color: var(--text-primary); }
.rt-lanc .rt-achip, .rt-lanc .rt-achip.is-linked, .rt-lanc .rt-achip.is-foreign, .rt-lanc .rt-achip.is-free {
  display: inline-flex; align-items: center; gap: 4px; max-width: 100%; margin-top: 4px; padding: 2px 8px 2px 4px;
  border-radius: 999px; font: 400 10.5px/1.3 var(--ff-body); letter-spacing: 0; text-transform: none;
  white-space: nowrap; overflow: hidden; text-overflow: ellipsis;
  color: var(--text-secondary); background: rgba(245, 239, 230, 0.05); box-shadow: inset 0 0 0 1px var(--divider);
}
.rt-lanc .rt-achip.is-foreign { box-shadow: inset 0 0 0 1px color-mix(in srgb, var(--dv-amber) 40%, transparent); }
.rt-lanc .rt-achip .t-ico { flex: none; width: 15px; height: 15px; filter: none; }
.rt-lanc .rt-smini.uv-bar { width: 46px; flex: none; overflow: visible; background: rgba(245, 239, 230, 0.07); }
.rt-lanc .rt-smove { gap: 2px; }
.rt-lanc .rt-smove button {
  width: 26px; height: 20px; border: 0; border-radius: 7px; font-size: 10px; color: var(--text-secondary);
  background: rgba(245, 239, 230, 0.05); box-shadow: inset 0 0 0 1px var(--divider);
}
.rt-lanc .rt-stackrow.is-inert .rt-sbody { opacity: 0.5; }

/* ── Szokásaid ── */
.rt-szokasok .rt-fgrid { display: grid; grid-template-columns: repeat(4, minmax(0, 1fr)); gap: 6px; margin: 4px 0 12px; }
.rt-szokasok .rt-ftile {
  display: flex; flex-direction: column; align-items: center; gap: 4px; min-width: 0; padding: 10px 4px 9px;
  border: 0; border-radius: 16px; text-align: center; font: inherit; color: var(--text-primary); cursor: pointer;
  background: rgba(245, 239, 230, 0.035); box-shadow: inset 0 0 0 1px var(--divider);
}
.rt-szokasok .rt-ftile b { font: 600 19px/1 var(--ff-display); letter-spacing: 0; color: var(--text-primary); }
.rt-szokasok .rt-ftile small { margin: 0; font-size: 9.5px; font-weight: 500; line-height: 1.25; color: var(--text-muted); overflow-wrap: anywhere; }
.rt-szokasok .rt-fdots { display: flex; gap: 3px; margin: 0; }
.rt-szokasok .rt-fdots i { flex: none; width: 5px; height: 5px; border-radius: 50%; background: rgba(245, 239, 230, 0.12); }
.rt-szokasok .rt-fdots i.on { background: var(--c); box-shadow: 0 0 4px var(--c); }
.rt-szokasok .rt-ftile.on {
  background: color-mix(in srgb, var(--c) 14%, rgba(245, 239, 230, 0.03));
  box-shadow: inset 0 0 0 1px color-mix(in srgb, var(--c) 50%, transparent), 0 0 12px -4px var(--c);
}
.rt-szokasok .rt-ftile.on small { color: var(--text-primary); }
.rt-szokasok .rt-ftile.is-zero { opacity: 0.45; }
.rt-szokasok .rt-ftile:focus-visible { outline: 2px solid var(--c); outline-offset: 2px; }
.rt-szokasok .rt-hgrid { display: grid; grid-template-columns: repeat(2, minmax(0, 1fr)); gap: 10px; }
.rt-szokasok .rt-htile.glass {
  display: flex; flex-direction: column; gap: 6px; min-width: 0; padding: 13px; border-radius: 20px;
  font: inherit; text-align: left; color: var(--text-primary); cursor: pointer;
}
.rt-szokasok .rt-htop { display: flex; align-items: flex-start; justify-content: space-between; gap: 8px; }
.rt-szokasok .rt-hleft { flex: 1; min-width: 0; }
.rt-szokasok .rt-hnm { font-size: 14px; font-weight: 600; line-height: 1.3; overflow-wrap: anywhere; }
.rt-szokasok .rt-hstage {
  margin-top: 3px; font: 500 10.5px/1.3 var(--ff-body); letter-spacing: 0; text-transform: none;
  color: color-mix(in srgb, var(--c) 75%, var(--text-primary));
}
.rt-szokasok .rt-hreps { margin-top: 10px; font: 300 26px/1 var(--ff-display); letter-spacing: -1px; color: var(--text-primary); }
.rt-szokasok .rt-hreps small { margin-left: 3px; font-size: 10.5px; font-weight: 400; letter-spacing: 0; color: var(--text-muted); }
.rt-szokasok .rt-hright { flex: none; width: auto; }
.rt-szokasok .rt-harc { width: 46px; height: 46px; }
.rt-szokasok .rt-harc text { font-size: 12px; font-weight: 600; fill: var(--text-primary); }
.rt-szokasok .rt-heta {
  display: flex; flex-direction: column; align-items: flex-start; gap: 2px; margin-top: auto; padding-top: 7px;
  border-top: 1px solid var(--divider);
}
.rt-szokasok .rt-heta b { font-size: 12px; font-weight: 600; color: color-mix(in srgb, var(--c) 70%, var(--text-primary)); }
.rt-szokasok .rt-heta span { font-size: 10.5px; line-height: 1.35; color: var(--text-muted); }

/* ── Szokás ── */
.rt-szokas .rt-flabel { margin: 18px 2px 8px; }
.rt-szokas .rt-flabel .rt-fwband-sw {
  margin-left: auto; padding: 0; border: 0; background: none; cursor: pointer;
  font: 600 12px/1.2 var(--ff-body); letter-spacing: 0; text-transform: none;
  color: color-mix(in srgb, var(--dv-amber) 70%, var(--text-primary));
}
.rt-szokas .rt-poster.glass { --c: var(--dv-amber); margin: 12px 0 0; padding: 15px 15px 14px; border-radius: 22px; }
.rt-szokas .rt-poster.glass.is-settled { --c: var(--dv-sage); }
.rt-szokas .rt-poster svg { overflow: visible; }
.rt-szokas .rt-poster-eb { font: 600 9.5px/1.3 var(--ff-body); letter-spacing: 1.3px; color: var(--text-muted); }
.rt-szokas .rt-poster-big { margin-top: 3px; font-size: 18px; font-weight: 600; color: var(--text-primary); }
.rt-szokas .rt-poster-sub { font-size: 11.5px; line-height: 1.45; color: var(--text-secondary); }
.rt-szokas .rt-poster-note { margin-top: 10px; font-size: 11.5px; line-height: 1.5; color: var(--text-muted); }
.rt-szokas .rt-curve-band { fill: color-mix(in srgb, var(--c) 16%, transparent); }
.rt-szokas .rt-curve-past { stroke: var(--c); filter: drop-shadow(0 0 4px color-mix(in srgb, var(--c) 55%, transparent)); }
.rt-szokas .rt-curve-next { stroke: var(--c); }
.rt-szokas .rt-curve-thr { stroke: color-mix(in srgb, var(--dv-sage) 55%, transparent); }
.rt-szokas .rt-curve-thrlb { fill: var(--dv-sage); }
.rt-szokas .rt-curve-dot { fill: var(--canvas); stroke: var(--c); }
.rt-szokas .rt-curve-ax { fill: var(--text-muted); }
.rt-szokas .rt-msrail::before { background: rgba(245, 239, 230, 0.08); }
.rt-szokas .rt-msrail li i { background: var(--canvas); box-shadow: inset 0 0 0 2px rgba(245, 239, 230, 0.14); }
.rt-szokas .rt-msrail li.is-past i { background: color-mix(in srgb, var(--c) 55%, transparent); box-shadow: none; }
.rt-szokas .rt-msrail li.is-now i { background: var(--canvas); box-shadow: 0 0 0 3px var(--c), 0 0 12px var(--c); animation: none; }
.rt-szokas .rt-msrail li span { font: 500 9.5px/1.25 var(--ff-body); letter-spacing: 0; text-transform: none; color: var(--text-muted); }
.rt-szokas .rt-msrail li.is-past span { color: var(--text-secondary); }
.rt-szokas .rt-msrail li.is-now span { font-weight: 600; color: var(--text-primary); }
@media (prefers-reduced-motion: no-preference) {
  .rt-szokas .rt-poster:not(.is-settled) .rt-msrail li.is-now i { animation: rt-mspulse 2.4s ease-in-out infinite; }
}
.rt-szokas .rt-etaband {
  gap: 12px; margin-top: 12px; padding: 10px 13px; border-radius: 16px;
  background: rgba(245, 239, 230, 0.04); box-shadow: inset 0 0 0 1px var(--divider);
}
.rt-szokas .rt-etaband-n {
  display: inline-flex; align-items: center; font: 300 24px/1 var(--ff-display);
  color: color-mix(in srgb, var(--c) 70%, var(--text-primary));
}
.rt-szokas .rt-etaband-n.is-dot i { display: block; width: 8px; height: 8px; border-radius: 50%; background: rgba(245, 239, 230, 0.25); }
.rt-szokas .rt-etaband-l { font-size: 11.5px; line-height: 1.45; color: var(--text-secondary); }
.rt-szokas .rt-etaband-l b { font: 600 9.5px/1.3 var(--ff-body); letter-spacing: 1.2px; color: var(--text-muted); }
/* the three context rings share ONE lavender glass; the cells inside are bare */
.rt-szokas .rt-ctxgrid.glass {
  --c: var(--dv-lav);
  display: grid; grid-template-columns: repeat(3, minmax(0, 1fr)); gap: 8px; padding: 14px 10px 12px; border-radius: 22px;
}
.rt-szokas .rt-ctxcell {
  display: flex; flex-direction: column; align-items: center; gap: 4px; min-width: 0; padding: 0;
  border-radius: 0; text-align: center; background: none; box-shadow: none;
}
.rt-szokas .rt-ctxcell svg { overflow: visible; }
.rt-szokas .rt-ctxcell b { margin-top: 4px; font-size: 12px; font-weight: 600; color: var(--text-primary); }
.rt-szokas .rt-ctxcell small { font-size: 10.5px; line-height: 1.3; color: var(--text-muted); }
/* the lifetime history: one gold glass; pipa lit gold, a missed day a coral ring, no row faint */
.rt-szokas .rt-fcard.rt-histcard.glass { margin: 0; padding: 14px 14px 12px; }
.rt-szokas .rt-cal i { width: 12px; height: 12px; border-radius: 3px; background: rgba(245, 239, 230, 0.05); }
.rt-szokas .rt-cal i.is-done, .rt-szokas .rt-cal-lg em.is-done {
  background: color-mix(in srgb, var(--c) 70%, transparent); box-shadow: 0 0 6px -1px var(--c);
}
/* a missed day is neutral, never failure-red (ADR 0010: no failure styling) */
.rt-szokas .rt-cal i.is-miss, .rt-szokas .rt-cal-lg em.is-miss {
  background: transparent; box-shadow: inset 0 0 0 1.5px rgba(245, 239, 230, 0.28);
}
.rt-szokas .rt-cal-lg { gap: 12px; margin-top: 9px; font-size: 10.5px; color: var(--text-muted); }
.rt-szokas .rt-cal-lg em { width: 9px; height: 9px; border-radius: 3px; background: rgba(245, 239, 230, 0.08); }
.rt-szokas .rt-wday-bar { height: 44px; border-radius: 7px; background: rgba(245, 239, 230, 0.05); }
.rt-szokas .rt-wday-bar i {
  background: linear-gradient(0deg, var(--c), color-mix(in srgb, var(--c) 55%, #fff));
  box-shadow: 0 0 8px color-mix(in srgb, var(--c) 50%, transparent);
}
.rt-szokas .rt-wday span { font-size: 10px; font-weight: 600; color: var(--text-muted); }
.rt-szokas .rt-histcard .rt-hint { margin-top: 10px; }

/* ── Szerkesztés ── */
.rt-szerk .uv-hero .uv-hero-art { order: 0; }
.rt-szerk .uv-hero .rt-hero-eb { order: 1; margin-top: 4px; color: color-mix(in srgb, var(--c) 70%, var(--text-primary)); }
.rt-szerk .uv-hero .mz-hero-nm { order: 2; margin-top: 2px; }
.rt-szerk .rt-pickrow {
  display: flex; align-items: center; gap: 11px; width: 100%; margin-top: 0; padding: 10px 12px; border: 0; border-radius: 14px;
  font: inherit; text-align: left; color: var(--text-primary); cursor: pointer;
  background: rgba(245, 239, 230, 0.04); box-shadow: inset 0 0 0 1px var(--divider);
}
.rt-szerk .rt-pickrow .t-ico { flex: none; width: 28px; height: 28px; }
.rt-szerk .rt-pickrow-gr { font-size: 13.5px; font-weight: 600; }
.rt-szerk .rt-pickrow-cv { color: var(--text-muted); }

/* ── Új szokás-recept (wizard) ── */
.rt-wiz .stepper-head { margin: 12px 2px 8px; }
.rt-wiz .stepper-title { font: 600 9.5px/1.3 var(--ff-body); letter-spacing: 1.3px; text-transform: uppercase; color: var(--text-muted); }
.rt-wiz .stepper-count { color: color-mix(in srgb, var(--dv-amber) 75%, var(--text-primary)); }
.rt-wiz .stepper-dots { gap: 6px; }
.rt-wiz .stepper-dot { flex: 1; width: auto; height: 6px; border: 0; border-radius: 999px; background: rgba(245, 239, 230, 0.07); }
.rt-wiz .stepper-dot.done { background: color-mix(in srgb, var(--dv-amber) 45%, transparent); }
.rt-wiz .stepper-dot.active { background: var(--dv-amber); box-shadow: 0 0 8px color-mix(in srgb, var(--dv-amber) 60%, transparent); }
.rt-wiz .stepper-label { flex: none; max-width: 45%; overflow: hidden; text-overflow: ellipsis; white-space: nowrap; font-size: 11.5px; color: var(--text-secondary); }
.rt-wiz .rt-wtitle { padding: 10px 2px 2px; text-align: left; font-size: 19px; font-weight: 600; letter-spacing: -0.5px; color: var(--text-primary); }
.rt-wiz .rt-wsub { padding: 0 2px 4px; text-align: left; font-size: 12.5px; line-height: 1.5; color: var(--text-secondary); }
/* the framework cards: gold glass; the picked one glows */
.rt-wiz .rt-fwcard.glass {
  --c: var(--dv-amber);
  display: flex; gap: 12px; align-items: flex-start; width: 100%; margin: 12px 0 0; padding: 14px; border-radius: 20px;
  font: inherit; text-align: left; color: var(--text-primary); cursor: pointer;
}
.rt-wiz .rt-fwcard.glass.on {
  background:
    radial-gradient(120% 90% at 0% 0%, color-mix(in srgb, var(--c) 30%, transparent), transparent 66%),
    linear-gradient(160deg, rgba(52, 46, 41, 0.72), rgba(30, 27, 24, 0.6));
  box-shadow:
    0 16px 30px -16px rgba(0, 0, 0, 0.75),
    0 0 30px -4px color-mix(in srgb, var(--c) 55%, transparent),
    inset 0 1px 0 rgba(255, 244, 230, 0.12);
}
.rt-wiz .rt-fwcard .rt-fwsgn, .rt-wiz .rt-fwcard.glass.on .rt-fwsgn {
  width: 44px; height: 44px; flex: none; display: grid; place-items: center; border-radius: 0; background: none; color: inherit;
}
.rt-wiz .rt-fwcard b { display: block; font-size: 15px; font-weight: 600; color: var(--text-primary); }
.rt-wiz .rt-fwcard small { display: block; margin-top: 3px; font-size: 12px; line-height: 1.45; color: var(--text-secondary); }
.rt-wiz .rt-fwwho { margin-top: 8px; font: 600 9.5px/1.3 var(--ff-body); letter-spacing: 1.2px; text-transform: uppercase; color: var(--text-muted); }
.rt-wiz .rt-fwloop { display: flex; flex-wrap: wrap; align-items: center; gap: 5px; margin-top: 10px; }
.rt-wiz .rt-fwloop span {
  padding: 3px 9px; border-radius: 999px; font: 500 11.5px/1.3 var(--ff-body); letter-spacing: 0; text-transform: none;
  color: var(--text-secondary); background: rgba(245, 239, 230, 0.05); box-shadow: inset 0 0 0 1px var(--divider);
}
.rt-wiz .rt-fwloop i { font-style: normal; font-size: 11px; color: var(--text-muted); }
/* life areas: flat cells with the 3D life icons, the picked one lavender-lit */
.rt-wiz .rt-lifegrid { display: grid; grid-template-columns: repeat(4, minmax(0, 1fr)); gap: 6px; }
.rt-wiz .rt-lifegrid button {
  display: flex; flex-direction: column; align-items: center; gap: 4px; min-width: 0; padding: 8px 2px;
  border: 0; border-radius: 14px; cursor: pointer;
  background: rgba(245, 239, 230, 0.035); box-shadow: inset 0 0 0 1px var(--divider);
}
.rt-wiz .rt-lifegrid button small {
  max-width: 100%; font-size: 10px; font-weight: 600; color: var(--text-secondary);
  overflow: hidden; text-overflow: ellipsis; white-space: nowrap;
}
.rt-wiz .rt-lifegrid button.on {
  background: color-mix(in srgb, var(--dv-lav) 14%, transparent);
  box-shadow: inset 0 0 0 1px color-mix(in srgb, var(--dv-lav) 55%, transparent);
}
.rt-wiz .rt-lifegrid button.on small { color: var(--text-primary); }
/* the commitment tick — gates the save, never a habit tick */
.rt-wiz .rt-commit {
  display: flex; align-items: center; gap: 12px; width: 100%; margin: 14px 0 0; padding: 12px 14px;
  border: 0; border-radius: 16px; font: inherit; text-align: left; color: var(--text-primary); cursor: pointer;
  background: rgba(245, 239, 230, 0.04); box-shadow: inset 0 0 0 1px var(--divider);
}
.rt-wiz .rt-commit.on {
  background: color-mix(in srgb, var(--dv-amber) 8%, rgba(245, 239, 230, 0.03));
  box-shadow: inset 0 0 0 1px color-mix(in srgb, var(--dv-amber) 45%, transparent);
}
.rt-wiz .rt-commit .rt-commit-box {
  width: 24px; height: 24px; flex: none; border: 0; border-radius: 7px; display: grid; place-items: center;
  background: none; box-shadow: inset 0 0 0 1.5px var(--dv-amber);
}
.rt-wiz .rt-commit.on .rt-commit-box { background: var(--dv-amber); box-shadow: 0 0 10px var(--dv-amber); }
.rt-wiz .rt-commit-box .t-ico { width: 20px; height: 20px; filter: none; }
.rt-wiz .rt-commit b { display: block; font-size: 13.5px; font-weight: 600; }
.rt-wiz .rt-commit small { display: block; font-size: 11.5px; line-height: 1.4; color: var(--text-secondary); }
.rt-wiz .rt-wnav { display: grid; grid-template-columns: minmax(0, 1fr) minmax(0, 1.4fr); gap: 10px; margin-top: 18px; }
.rt-wiz .rt-wnav > :only-child { grid-column: 1 / -1; }
.rt-wiz .rt-wnav .rt-ghostpill { min-height: 46px; font-size: 14px; }

/* ── the rutin sheets (AI javaslat, Új rutin, Mihez kötöd?): ONE floating glass (U2 rule 15) ── */
.sheet.glass.rt-sheet {
  --c: var(--dv-amber);
  position: absolute; left: 10px; right: 10px; bottom: calc(10px + env(safe-area-inset-bottom));
  overflow-x: hidden; overflow-y: auto; border-radius: 30px; padding: 4px 18px 18px;
}
.sheet.glass.rt-sheet.is-lav { --c: var(--dv-lav); }
.sheet.glass.rt-sheet .sheet-handle { background: rgba(245, 239, 230, 0.22); }
.rt-sheet .rt-shh { display: flex; align-items: flex-start; gap: 12px; margin: 4px 0 8px; }
.rt-sheet .rt-shh > .t-ico { flex: none; }
.rt-sheet .rt-shh-t { flex: 1; min-width: 0; }
.rt-sheet .rt-shh-eb {
  display: block; font: 600 9.5px/1.3 var(--ff-body); letter-spacing: 1.3px; text-transform: uppercase;
  color: color-mix(in srgb, var(--c) 80%, var(--text-primary));
}
.rt-sheet .rt-shh h2 { margin: 2px 0 0; font: 600 21px/1.2 var(--ff-display); letter-spacing: -0.6px; color: var(--text-primary); }
.rt-sheet .rt-shh .rt-hint { margin: 4px 0 0; }
.rt-sheet .rt-shx {
  flex: none; width: 34px; height: 34px; padding: 0; border: 0; border-radius: 50%; display: grid; place-items: center;
  color: var(--text-secondary); background: rgba(245, 239, 230, 0.06); box-shadow: inset 0 0 0 1px var(--divider);
}
.rt-sheet .rt-field { display: block; margin-top: 6px; }
.rt-sheet .rt-field .rt-fin { margin-top: 0; }
/* the AI proposals: flat rows inside the glass (never glass in glass, rule 5) */
.rt-sheet .card.rt-aicard {
  padding: 13px 14px; border: 0; border-radius: 16px; filter: none;
  background: rgba(245, 239, 230, 0.04); box-shadow: inset 0 0 0 1px var(--divider);
}
.rt-sheet .rt-aicard.is-off p { margin: 0; font-size: 13px; line-height: 1.5; color: var(--text-secondary); }
.rt-sheet .rt-aicard-t { font: 600 15px/1.25 var(--ff-display); color: var(--text-primary); }
.rt-sheet .rt-aicard-why { margin: 5px 0 0; font-size: 12.5px; line-height: 1.5; color: var(--text-secondary); }
.rt-sheet .rt-aicard-chips { display: flex; flex-wrap: wrap; gap: 6px; margin-top: 9px; }
.rt-sheet .rt-aicard-chips .chip {
  min-width: 0; max-width: 100%; padding: 3px 9px; border: 0; border-radius: 999px; font-size: 11px; font-weight: 600;
  overflow: hidden; text-overflow: ellipsis; color: var(--text-secondary);
  background: rgba(245, 239, 230, 0.05); box-shadow: inset 0 0 0 1px var(--divider);
}
.rt-sheet .rt-aicard-acts { display: flex; flex-wrap: wrap; gap: 8px; margin-top: 12px; }
.rt-sheet .rt-aicard-acts .chip { min-height: 36px; padding: 7px 14px; border: 0; border-radius: 999px; font-size: 12.5px; font-weight: 600; cursor: pointer; }
.rt-sheet .rt-aicard-acts .chip.rt-aicard-ok {
  color: var(--canvas); background: var(--c); box-shadow: 0 0 12px color-mix(in srgb, var(--c) 45%, transparent);
}
.rt-sheet .rt-aicard-acts .chip.rt-aicard-no {
  color: var(--text-secondary); background: rgba(245, 239, 230, 0.05); box-shadow: inset 0 0 0 1px var(--divider);
}
/* the anchor picker: flat option rows, the chosen one lit with a glowing radio */
.rt-sheet .rt-optgrp {
  margin: 14px 2px 8px; font: 600 9.5px/1.3 var(--ff-body); letter-spacing: 1.3px; text-transform: uppercase; color: var(--text-muted);
}
.rt-sheet .rt-optrow {
  display: flex; align-items: center; gap: 11px; width: 100%; margin: 0 0 6px; padding: 10px 12px; border: 0; border-radius: 14px;
  font: inherit; text-align: left; color: var(--text-primary); cursor: pointer;
  background: rgba(245, 239, 230, 0.04); box-shadow: inset 0 0 0 1px var(--divider);
}
.rt-sheet .rt-optrow .t-ico { flex: none; width: 28px; height: 28px; }
.rt-sheet .rt-optrow-nm { font-size: 13.5px; font-weight: 600; }
.rt-sheet .rt-optrow-nm small { font-size: 11px; font-weight: 400; color: var(--text-muted); }
.rt-sheet .rt-optrow-rad { width: 18px; height: 18px; border: 0; border-radius: 50%; background: none; box-shadow: inset 0 0 0 1.5px var(--text-muted); }
.rt-sheet .rt-optrow.on {
  background: color-mix(in srgb, var(--c) 10%, rgba(245, 239, 230, 0.03));
  box-shadow: inset 0 0 0 1px color-mix(in srgb, var(--c) 45%, transparent);
}
.rt-sheet .rt-optrow.on .rt-optrow-rad { background: none; box-shadow: inset 0 0 0 5px var(--c), 0 0 8px var(--c); }
.rt-sheet .rt-optrow.is-unlink { box-shadow: inset 0 0 0 1px color-mix(in srgb, var(--dv-coral) 30%, transparent); }
.rt-sheet .rt-optrow.is-unlink .rt-optrow-nm { color: color-mix(in srgb, var(--dv-coral) 55%, var(--text-primary)); }

@media (max-width: 360px) {
  .rt-szokasok .rt-fgrid { grid-template-columns: repeat(2, minmax(0, 1fr)); }
  .rt-wiz .rt-lifegrid { grid-template-columns: repeat(3, minmax(0, 1fr)); }
  .rt-hub .rt-nextcard .rt-bigtick { width: 54px; height: 54px; }
}
/* ── /uveg en2 rutin ── */

/* ── uveg en2 naplo (mezo-me75u.7) ── /me/naplo + journal / decision sheets ── */
/* Reference: docs/design_2.0/prototypes/src/uveg-en2-body.html `naplo()`, SH.journal, SH.decision
   (CSS `.decc .rate .decdone .month .jnote`). Ranking (bible §3.4): the hero is the frameless sage
   t-journal halo with the gratitude streak as the numeral (PageHero `art`); the Hálanapló streak is
   ONE sage glass card; each open decision is ONE gold glass card (1–4 flat, „5 · bevált" the lit
   gold pill; the settled row a t-tick line inside that same gold glass); the notes are flat cells;
   the empty window is dashed. Everything is scoped to `.mzj-page` / `.mzj-decsheet` — the old
   `mzh-*`/`mzp-*`/`mem-*` classes serve the Mezo hub, predictions and memoir too (U2 rule 13).
   The JournalSheet is the shared capture sheet (glass since U3, `── uveg nap rogzites (`, also
   opened from Nap and quick input — rule 43), so it is not restyled here; the DecisionReviewSheet
   joins that same capture-sheet material in gold and only its header + quote are dressed below. */
.mzj-page { --c: var(--dv-sage); }
.mzj-page.mz-page { background: transparent; }

/* page head: the lit sage „Új bejegyzés" pill with t-note (a filled CTA restates every colour, rule 36) */
.mzj-page .mz-pgact.mzj-newbtn {
  display: inline-flex; align-items: center; gap: 6px; min-width: 0; max-width: 62%;
  overflow: hidden; text-overflow: ellipsis; white-space: nowrap;
  border: 0; padding: 8px 14px 8px 10px; min-height: 40px; border-radius: 999px;
  font: 700 12.5px/1.2 var(--ff-body); color: #191614; background: var(--dv-sage);
  box-shadow: 0 0 14px color-mix(in srgb, var(--dv-sage) 55%, transparent);
}
.mzj-page .mz-pgact.mzj-newbtn .t-ico { flex: 0 0 auto; filter: none; }
.mzj-page .mz-pgact.mzj-newbtn:focus-visible { outline: 2px solid var(--dv-sage); outline-offset: 3px; }

/* hero: sage halo, a warm second hue */
.mzj-page .mz-page-hero.uv-hero { --c2: var(--dv-amber); }

/* section eyebrows (`h3('DÖNTÉSEK')`, the month line) */
.mzj-page .mz-eyebrow.mzj-sech, .mzj-page .mz-eyebrow.mzj-month {
  display: block; margin: 8px 2px 2px; font: 600 9.5px/1.2 var(--ff-body); letter-spacing: 1.3px;
  text-transform: uppercase; color: var(--text-muted);
}
.mzj-page .mz-eyebrow.mzj-month { margin: 6px 2px 8px; }

/* ── the Hálanapló streak: ONE sage glass card ── */
.mzj-page .mzj-grat.glass { --c: var(--dv-sage); padding: 15px 15px 14px; border: 0; border-radius: 22px; }
.mzj-page .mzj-grat-top { display: flex; align-items: center; gap: 10px; }
.mzj-page .mzj-grat-top > .t-ico { width: 34px; height: 34px; }
.mzj-page .mzj-grat .mzj-gtitle { display: block; font-size: 15px; font-weight: 600; letter-spacing: -0.3px; color: var(--text-primary); }
.mzj-page .mzj-grat .mzj-gsub { margin-top: 3px; font-size: 12.5px; line-height: 1.45; color: var(--text-secondary); }
/* „él a sorozat": a flat sage chip with the t-flame (secondary, inside the glass) */
.mzj-page .mzj-gchip {
  flex: 0 1 auto; min-width: 0; display: inline-flex; align-items: center; gap: 5px; padding: 4px 9px 4px 6px;
  border-radius: 999px; overflow: hidden; text-overflow: ellipsis; white-space: nowrap;
  font: 600 11px/1.2 var(--ff-body); color: color-mix(in srgb, var(--dv-sage) 75%, var(--text-primary));
  background: color-mix(in srgb, var(--dv-sage) 11%, rgba(245, 239, 230, 0.03));
  box-shadow: inset 0 0 0 1px color-mix(in srgb, var(--dv-sage) 30%, transparent);
}
.mzj-page .mzj-gchip .t-ico { flex: 0 0 auto; filter: none; }

/* ── a decision: ONE gold glass card (the prototype `.decc`) ── */
.mzj-page .mzj-deccard.glass { --c: var(--dv-amber); padding: 15px; border: 0; border-radius: 22px; }
.mzj-page .mzj-dechead { display: flex; flex-wrap: wrap; align-items: center; justify-content: space-between; gap: 8px; }
.mzj-page .mzj-dechead .mz-eyebrow {
  min-width: 0; font: 600 9.5px/1.2 var(--ff-body); letter-spacing: 1.3px; text-transform: uppercase;
  color: color-mix(in srgb, var(--dv-amber) 70%, var(--text-muted));
}
.mzj-page .mzj-decchip {
  min-width: 0; max-width: 100%; display: inline-flex; align-items: center; gap: 5px; padding: 4px 9px 4px 6px;
  border-radius: 999px; overflow: hidden; text-overflow: ellipsis; white-space: nowrap;
  font: 600 11px/1.2 var(--ff-body); color: color-mix(in srgb, var(--dv-amber) 75%, var(--text-primary));
  background: color-mix(in srgb, var(--dv-amber) 11%, rgba(245, 239, 230, 0.03));
  box-shadow: inset 0 0 0 1px color-mix(in srgb, var(--dv-amber) 30%, transparent);
}
.mzj-page .mzj-decchip.is-wait { color: var(--text-secondary); background: rgba(245, 239, 230, 0.05); box-shadow: inset 0 0 0 1px var(--divider); }
.mzj-page .mzj-decchip .t-ico { flex: 0 0 auto; filter: none; }
.mzj-page .mzj-deccard .mzj-decq { margin: 8px 0 0; font-size: 15px; font-weight: 400; line-height: 1.5; color: var(--text-primary); }
/* the 1–5 row: four flat cells + the lit gold „5 · bevált" */
.mzj-page .mzj-rate { display: grid; grid-template-columns: repeat(4, minmax(0, 1fr)) minmax(0, 1.8fr); gap: 6px; margin-top: 12px; }
.mzj-page .mzj-rate button {
  min-width: 0; min-height: 44px; padding: 0 6px; border: 0; border-radius: 12px; cursor: pointer;
  overflow: hidden; text-overflow: ellipsis; white-space: nowrap; text-align: center;
  font: 600 14px/1 var(--ff-body); font-variant-numeric: tabular-nums;
}
.mzj-page .mzj-rate .mzj-rate-n { color: var(--text-secondary); background: rgba(245, 239, 230, 0.05); box-shadow: inset 0 0 0 1px var(--divider); }
.mzj-page .mzj-rate .mzj-rate-cta {
  font-size: 13px; font-weight: 700; color: #191614; background: var(--dv-amber);
  box-shadow: 0 0 12px color-mix(in srgb, var(--dv-amber) 50%, transparent);
}
.mzj-page .mzj-rate button:focus-visible { outline: 2px solid var(--dv-amber); outline-offset: 2px; }
.mzj-page .mzj-deccard .mzj-decfoot { margin: 8px 0 0; padding: 0; font-size: 11px; font-weight: 400; line-height: 1.4; color: var(--text-muted); }
/* the settled state: a t-tick line, inside the same gold glass */
.mzj-page .mzj-decdone {
  display: flex; flex-wrap: wrap; align-items: center; gap: 10px;
  font: 600 13px/1.3 var(--ff-body); color: color-mix(in srgb, var(--dv-sage) 60%, #fff);
}
.mzj-page .mzj-decdone > .t-ico { flex: 0 0 auto; }
.mzj-page .mzj-decdone .mzj-decprose {
  margin-left: auto; min-height: 44px; padding: 6px 4px 6px 10px; border: 0; background: none; cursor: pointer;
  font: 600 12px/1.2 var(--ff-body); color: color-mix(in srgb, var(--dv-amber) 60%, #fff); box-shadow: none;
}
.mzj-page .mzj-decdone .mzj-decprose:focus-visible { outline: 2px solid var(--dv-amber); outline-offset: 2px; border-radius: 10px; }
@media (max-width: 360px) {
  .mzj-page .mzj-rate { grid-template-columns: repeat(4, minmax(0, 1fr)); }
  .mzj-page .mzj-rate .mzj-rate-cta { grid-column: 1 / -1; }
}

/* ── the notes: flat cells (secondary, not glass — the prototype `.jnote`) ── */
.mzj-page .mzj-note {
  display: block; width: 100%; margin: 0; padding: 13px 15px; border: 0; border-radius: 18px;
  text-align: left; cursor: pointer; font-family: inherit;
  background: rgba(245, 239, 230, 0.04); box-shadow: inset 0 0 0 1px var(--divider);
}
.mzj-page .mzj-note:focus-visible { outline: 2px solid var(--dv-sage); outline-offset: 2px; }
.mzj-page .mzj-note-dl {
  display: block; font: 600 10.5px/1.2 var(--ff-body); letter-spacing: 1px; text-transform: uppercase;
  color: color-mix(in srgb, var(--dv-sage) 70%, var(--text-primary));
}
.mzj-page .mzj-note-bd { margin: 5px 0 0; font-size: 14px; font-weight: 400; line-height: 1.55; color: var(--text-primary); overflow-wrap: anywhere; }
/* „Korábbi hónapok": a flat pager (the prototype `.btn.flatb`) */
.mzj-page .mzj-more {
  display: flex; align-items: center; justify-content: center; width: 100%; min-height: 48px; margin-top: 4px;
  padding: 12px 16px; border: 0; border-radius: 18px; cursor: pointer;
  font: 600 14px/1.2 var(--ff-body); color: var(--text-secondary);
  background: rgba(245, 239, 230, 0.05); box-shadow: inset 0 0 0 1px var(--divider);
}
.mzj-page .mzj-more:focus-visible { outline: 2px solid var(--dv-sage); outline-offset: 2px; }

/* ── states: loading skeletons flat on the dark ground, the error ghost flat, the empty window dashed ── */
.mzj-page .mzj-skel.card {
  border: 0; border-radius: 18px; filter: none;
  background: rgba(245, 239, 230, 0.04); box-shadow: inset 0 0 0 1px var(--divider);
}
.mzj-page .mzj-ghost > .card, .mzj-page .mzj-empty > .card { border: 0; filter: none; background: none; box-shadow: none; }
.mzj-page .mzj-ghost { border-radius: 18px; background: rgba(245, 239, 230, 0.04); box-shadow: inset 0 0 0 1px var(--divider); }
.mzj-page .mzj-empty.uv-empty { --c: var(--dv-sage); border-radius: 22px; }
.mzj-page :is(.mzj-ghost, .mzj-empty) .cta-primary {
  width: auto; min-height: 44px; padding: 10px 18px; border: 0; border-radius: 999px;
  font: 700 13px/1.2 var(--ff-body); color: #191614; background: var(--dv-sage);
  box-shadow: 0 0 14px color-mix(in srgb, var(--dv-sage) 50%, transparent);
}

/* ── the decision review sheet: the shared glass capture sheet, in gold ── */
.mzj-decsheet { --capture-accent: var(--dv-amber); }
.mzj-decsheet .mzj-dsh-head { display: flex; align-items: flex-start; gap: 12px; margin-bottom: 12px; }
.mzj-decsheet .mzj-dsh-head > .t-ico {
  width: 48px; height: 48px; flex: 0 0 auto;
  filter: drop-shadow(0 8px 10px rgba(0, 0, 0, 0.5)) drop-shadow(0 0 14px color-mix(in srgb, var(--dv-amber) 45%, transparent));
}
.mzj-decsheet .mzj-grow { flex: 1; min-width: 0; }
.mzj-decsheet .mzj-dsh-eb {
  display: block; font: 600 9.5px/1.2 var(--ff-body); letter-spacing: 1.3px; text-transform: uppercase; color: var(--text-muted);
}
.mzj-decsheet .mzj-dsh-title { margin: 2px 0 0; font: 600 21px/1.2 var(--ff-display); letter-spacing: -0.6px; color: var(--text-primary); }
.mzj-decsheet .mzj-dsh-quote {
  padding: 12px 14px; border-radius: 16px;
  background: color-mix(in srgb, var(--dv-amber) 7%, rgba(245, 239, 230, 0.03));
  box-shadow: inset 0 0 0 1px color-mix(in srgb, var(--dv-amber) 26%, transparent);
}
.mzj-decsheet .mzj-dsh-quote p { font-size: 14.5px; line-height: 1.55; color: var(--text-primary); }
.mzj-decsheet .mzj-dsh-rate { display: grid; grid-template-columns: repeat(5, minmax(0, 1fr)); gap: 6px; }
.mzj-decsheet .mzj-dsh-rate .chip { justify-content: center; min-height: 44px; padding: 0; border-radius: 12px; font-size: 14px; }

/* ── /uveg en2 naplo ── */

/* ── uveg en2 emberek (mezo-me75u.7) ── /me/people(+/jeloltek,/kor,/emlitesek,/heti,/:id) + person log / edit sheets ── */
/* Reference: docs/design_2.0/prototypes/src/uveg-en2-body.html `emberek()`, `jeloltek()`, `kor()`,
   `emlitesek()`, `heti()`, `ember()` and the `plog` / `pedit` sheets (owner OK). Every rule is
   scoped to a page root — `.ppl-hub`, `.ppl-jel`, `.ppl-kor`, `.ppl-eml`, `.ppl-heti`,
   `.ppl-detail` (all `.ppl-page`) — or to the portalled `.ppl-sheet`, because the old `ppl-*`
   skin further up is unscoped and light-world (bible rule 13); the old candidate / badge / FIGYELEM
   pulses are switched off here, not deleted. Ranking (§3.4): every hero is a frameless halo (the
   person page keeps its own ringed-avatar hero); the hub tiles, person cards, candidate card,
   rhythm / tone / direction / moment / quiet cards and the person page's section cards are
   `.glass` with ONE `--c`; stat cells, chips, mention rows, timeline / graph / quiet rows are flat;
   empty is dashed. Colour carries the TONE (rule 46): the `--ppl-tone-*` tokens resolve to the
   Mozaik accents inside these roots — Jó sage, OK sky, Vegyes amber, Nehéz coral. */
.ppl-page.mz-page { background: transparent; }
.ppl-page, .ppl-sheet {
  --ppl-tone-jo: var(--dv-sage);
  --ppl-tone-ok: var(--dv-sky);
  --ppl-tone-vegyes: var(--dv-amber);
  --ppl-tone-nehez: var(--dv-coral);
}
.ppl-hub, .ppl-kor, .ppl-detail { --c: var(--dv-rose); }
.ppl-jel { --c: var(--dv-amber); }
.ppl-eml { --c: var(--dv-sky); }
.ppl-heti { --c: var(--dv-lav); }
.ppl-page .mz-page-hero.uv-hero { --c2: var(--dv-lav); }

/* ── the glass body, restated: the old wash / card rules outrank `.glass` (rule 11) ── */
.ppl-hub .ppl-hub-tile.glass, .ppl-kor .ppl-tile.glass, .ppl-jel .ppl-candt.glass,
.ppl-eml .ppl-rhythm.glass, .ppl-heti .ppl-tonemixc.glass, .ppl-heti .ppl-dirt.glass,
.ppl-heti .ppl-momentt.glass, .ppl-heti .ppl-quietcard.glass,
.ppl-detail .ppl-trendcard.glass, .ppl-detail .ppl-ctxcard.glass, .ppl-detail .ppl-evtcard.glass,
.ppl-detail .ppl-tlcard.glass {
  border: 0; color: var(--text-primary);
  background:
    radial-gradient(120% 90% at 0% 0%, color-mix(in srgb, var(--c) 22%, transparent), transparent 62%),
    linear-gradient(160deg, rgba(52, 46, 41, 0.72), rgba(30, 27, 24, 0.60));
  box-shadow:
    0 16px 30px -16px rgba(0, 0, 0, 0.75),
    0 0 26px -6px color-mix(in srgb, var(--c) 30%, transparent),
    inset 0 1px 0 rgba(255, 244, 230, 0.10),
    inset 0 -14px 26px -18px color-mix(in srgb, var(--c) 55%, transparent);
}
.ppl-hub .ppl-hub-tile:focus-visible, .ppl-kor .ppl-tile:focus-visible, .ppl-heti .ppl-dirt:focus-visible,
.ppl-detail .ppl-evt:focus-visible, .ppl-page .ppl-act:focus-visible, .ppl-eml .ppl-fchip:focus-visible,
.ppl-detail .ppl-logcta:focus-visible {
  outline: 2px solid var(--c); outline-offset: 2px;
}

/* ── the page head: the lit „Log" pill (t-mic) and the flat „＋ Új személy" / „Szerkesztés" ── */
.ppl-page .mz-page-head .pgact.ppl-act {
  min-width: 0; min-height: 40px; padding: 0 14px; gap: 6px; border: 0; border-radius: 999px;
  font: 700 12.5px/1.2 var(--ff-body); overflow: hidden; text-overflow: ellipsis;
}
.ppl-page .mz-page-head .pgact.ppl-act { margin-left: auto; }
.ppl-page .pgact.ppl-act-lit {
  color: #191614; background: var(--c);
  box-shadow: 0 0 14px color-mix(in srgb, var(--c) 55%, transparent);
}
.ppl-page .pgact.ppl-act-flat {
  font-weight: 600; color: var(--text-secondary);
  background: rgba(245, 239, 230, 0.05); box-shadow: inset 0 0 0 1px var(--divider);
}
.ppl-page .ppl-act .t-ico { width: 18px; height: 18px; filter: none; }
.ppl-page .mz-page-head .pgact.ppl-act + .pgact.ppl-act { margin-left: 0; }

/* ── flat stat cells (hub + person page) ── */
.ppl-page .ppl-stats.mz-statstrip { display: grid; grid-template-columns: repeat(3, minmax(0, 1fr)); gap: 8px; }
.ppl-page .ppl-stats .mz-statcell {
  min-width: 0; padding: 10px 6px; border: 0; border-radius: 14px;
  background: rgba(245, 239, 230, 0.04); box-shadow: inset 0 0 0 1px var(--divider);
}
.ppl-page .ppl-stats .mz-statcell b {
  font-size: 20px; font-weight: 600; letter-spacing: -0.6px; color: var(--text-primary);
  overflow: hidden; text-overflow: ellipsis; white-space: nowrap;
}
.ppl-page .ppl-stats .mz-statcell small { display: block; margin-top: 2px; font-size: 10px; line-height: 1.3; color: var(--text-muted); }
.ppl-detail .ppl-stat-tone {
  color: color-mix(in srgb, var(--c) 80%, var(--text-primary));
  text-shadow: 0 0 12px color-mix(in srgb, var(--c) 45%, transparent);
}

/* ── section eyebrows, footnotes, the dashed empty state ── */
.ppl-page .ppl-lsec { display: flex; align-items: baseline; gap: 10px; padding: 18px 2px 8px; }
.ppl-page .ppl-lsec .mz-eyebrow { font: 600 9.5px/1.2 var(--ff-body); letter-spacing: 1.3px; color: var(--text-muted); }
.ppl-page .ppl-lsec .ppl-cnt, .ppl-page .ppl-lsec .ppl-lcnt {
  margin-left: auto; font-size: 11px; font-weight: 500; color: var(--text-muted);
}
.ppl-page .ppl-foot {
  margin: 18px 6px 0; padding: 12px 0 0; border-top: 1px solid var(--divider);
  font-size: 11.5px; font-weight: 400; line-height: 1.5; color: var(--text-muted); text-align: center;
}
.ppl-page .ppl-empty.uv-empty {
  padding: 14px 16px; border-radius: 20px; text-align: left;
  border: 1.5px dashed color-mix(in srgb, var(--c) 45%, transparent);
  background: rgba(245, 239, 230, 0.025); box-shadow: none;
  font-size: 12.5px; font-weight: 400; line-height: 1.5; color: var(--text-secondary);
}

/* ── the person avatar: a lit well ringed in the person's tone (`--pc`, or the card's `--c`) ── */
.ppl-page .ppl-mavat, .ppl-page .ppl-fp-avat {
  --ring: var(--pc, var(--c));
  flex: 0 0 auto; display: grid; place-items: center; border-radius: 50%;
  font-family: var(--ff-body); font-weight: 600; color: var(--text-primary);
  background: radial-gradient(circle at 35% 28%, #3A332D, color-mix(in srgb, var(--ring) 16%, #1E1B18));
}
.ppl-page .ppl-mavat {
  width: 26px; height: 26px; font-size: 11px;
  box-shadow: 0 0 0 1.5px color-mix(in srgb, var(--ring) 70%, transparent);
}

/* ═══ Hub ═══ */
.ppl-hub .mz-mosaic { gap: 10px; }
.ppl-hub .ppl-hub-tile.ppl-hub-gold { --c: var(--dv-amber); }
.ppl-hub .ppl-hub-tile.ppl-hub-rose { --c: var(--dv-rose); }
.ppl-hub .ppl-hub-tile.ppl-hub-sky  { --c: var(--dv-sky); }
.ppl-hub .ppl-hub-tile.ppl-hub-lav  { --c: var(--dv-lav); }
.ppl-hub .ppl-hub-tile.glass {
  display: flex; flex-direction: column; align-items: stretch; gap: 5px; min-width: 0; min-height: 138px;
  padding: 13px; border-radius: 20px; text-align: left;
}
.ppl-hub .ppl-hub-top { display: flex; justify-content: space-between; align-items: flex-start; gap: 8px; min-height: 42px; }
.ppl-hub .ppl-hub-top .t-ico { width: 42px; height: 42px; }
.ppl-hub .ppl-hub-tile .mz-eyebrow {
  margin-top: auto; font: 600 9.5px/1.2 var(--ff-body); letter-spacing: 1.3px;
  color: color-mix(in srgb, var(--c) 70%, var(--text-primary));
}
.ppl-hub .ppl-hub-main {
  font-size: 14.5px; font-weight: 600; letter-spacing: -0.2px; line-height: 1.3; color: var(--text-primary);
  overflow-wrap: anywhere;
}
.ppl-hub .ppl-hub-line {
  margin: 0; font-size: 11px; font-weight: 400; line-height: 1.35; color: var(--text-secondary);
  -webkit-line-clamp: 2;
}
/* the count badge: a lit pill in the tile's hue (the flag count coral) */
.ppl-hub .ppl-hub-top .ppl-hub-badge {
  position: static; min-width: 22px; height: 22px; padding: 0 7px; border-radius: 999px;
  display: grid; place-items: center; font-size: 11px; font-weight: 700; color: #191614;
  background: var(--c); box-shadow: 0 0 10px color-mix(in srgb, var(--c) 55%, transparent); animation: none;
}
.ppl-hub .ppl-hub-top .ppl-hub-badge.ppl-hub-badge-alert {
  background: var(--dv-coral); box-shadow: 0 0 10px color-mix(in srgb, var(--dv-coral) 55%, transparent);
}
/* the facepile: tone-ringed wells, overlapping, cut by a ground ring */
.ppl-hub .ppl-facepile { display: flex; padding-top: 4px; }
.ppl-hub .ppl-facepile .ppl-fp-avat {
  width: 28px; height: 28px; margin: 0 -6px 0 0; font-size: 11px;
  box-shadow: 0 0 0 2px var(--canvas), 0 0 0 3.5px color-mix(in srgb, var(--ring) 60%, transparent);
}
.ppl-hub .ppl-facepile .ppl-fp-avat:first-child { margin-left: 0; }

/* ═══ Jelöltek ═══ */
.ppl-jel .ppl-candt.glass { --c: var(--dv-amber); display: block; margin-bottom: 12px; padding: 15px; border-radius: 22px; text-align: left; }
/* the old light candidate pulse would repaint the glass shadow: off, but the entrance stays */
.ppl-jel .ppl-candt.glass { animation: none; }
@media (prefers-reduced-motion: no-preference) {
  .ppl-jel .mz-play .ppl-candt.glass.rise {
    animation: mz-rise 0.5s cubic-bezier(0.22, 0.9, 0.32, 1.15) forwards; animation-delay: var(--d, 0ms);
  }
}
.ppl-jel .ppl-candt-head { display: flex; align-items: center; gap: 10px; }
.ppl-jel .ppl-candt-head .t-ico { width: 38px; height: 38px; }
.ppl-jel .ppl-candt-head b { flex: 1; min-width: 0; font-size: 16px; font-weight: 600; overflow-wrap: anywhere; }
.ppl-jel .ppl-candchip {
  flex: 0 0 auto; padding: 4px 9px; border-radius: 999px; font-size: 11px; font-weight: 600;
  color: color-mix(in srgb, var(--c) 75%, var(--text-primary));
  background: color-mix(in srgb, var(--c) 11%, rgba(245, 239, 230, 0.03));
  box-shadow: inset 0 0 0 1px color-mix(in srgb, var(--c) 30%, transparent);
}
.ppl-jel .ppl-candt-q {
  margin-top: 10px; font-family: var(--ff-body); font-style: normal; font-size: 14px; font-weight: 400;
  line-height: 1.55; color: var(--text-primary);
}
.ppl-jel .ppl-candt-ev { margin-top: 8px; font-size: 11.5px; font-weight: 500; color: var(--text-muted); }
.ppl-jel .ppl-candbtns { display: grid; grid-template-columns: repeat(2, minmax(0, 1fr)); gap: 10px; margin-top: 14px; }
.ppl-jel .ppl-candbtns button {
  min-width: 0; min-height: 44px; padding: 8px 12px; border: 0; border-radius: 999px;
