.ppl-detail .ppl-tlrow > .t-ico { width: 24px; height: 24px; margin-top: 1px; }
.ppl-detail .ppl-tlbody { flex: 1; min-width: 0; }
.ppl-detail .ppl-tlrow .ppl-mtop { display: flex; align-items: center; gap: 6px; flex-wrap: wrap; }
.ppl-detail .ppl-tldot { width: 7px; height: 7px; border-radius: 50%; flex: 0 0 auto; background: var(--tc); box-shadow: 0 0 5px var(--tc); }
.ppl-detail .ppl-mtime { font-size: 11px; font-weight: 400; color: var(--text-muted); }
.ppl-detail .ppl-tlrow .ppl-mtiechip {
  padding: 0; font-size: 11px; font-weight: 400; color: var(--text-muted); background: none;
}
.ppl-detail .ppl-tlrow .ppl-mtiechip::before { content: '· '; }
.ppl-detail .ppl-tlrow .ppl-mx {
  margin: 4px 0 0; font-family: var(--ff-body); font-style: normal; font-size: 13.5px; font-weight: 400;
  line-height: 1.5; color: var(--text-primary);
}
/* „Log most": the lit rose pill */
.ppl-detail .ppl-logcta {
  display: flex; align-items: center; justify-content: center; gap: 8px; width: 100%; height: 48px; margin-top: 18px;
  border: 0; border-radius: 999px; cursor: pointer;
  font: 700 14.5px/1 var(--ff-body); color: #191614; background: var(--dv-rose);
  box-shadow: 0 0 14px color-mix(in srgb, var(--dv-rose) 55%, transparent);
}
.ppl-detail .ppl-logcta .t-ico { width: 20px; height: 20px; filter: none; }

/* ═══ The person log / edit sheets: ONE floating rose glass each (U2 rule 15) ═══ */
.sheet.glass.ppl-sheet {
  --c: var(--dv-rose);
  position: absolute; left: 10px; right: 10px; bottom: calc(10px + env(safe-area-inset-bottom));
  max-height: calc(100% - 70px); overflow-x: hidden; overflow-y: auto;
  padding: 4px 18px 20px; border: 0; border-radius: 30px; color: var(--text-primary);
}
.sheet.glass.ppl-sheet .sheet-handle { width: 40px; height: 5px; background: rgba(245, 239, 230, 0.22); }
.ppl-sheet .ppl-sh { display: flex; flex-direction: column; gap: 12px; padding: 4px 0 4px; }
.ppl-sheet .ppl-shh { display: flex; align-items: flex-start; gap: 12px; }
.ppl-sheet .ppl-shh > .t-ico { width: 48px; height: 48px; }
.ppl-sheet .ppl-shh-tx { flex: 1; min-width: 0; display: flex; flex-direction: column; gap: 2px; }
.ppl-sheet .ppl-sh-eye { font: 600 9.5px/1.2 var(--ff-body); letter-spacing: 1.3px; text-transform: uppercase; color: color-mix(in srgb, var(--c) 70%, var(--text-muted)); }
.ppl-sheet .ppl-sh-title { font-size: 21px; font-weight: 600; letter-spacing: -0.6px; color: var(--text-primary); }
.ppl-sheet .ppl-sh-x {
  width: 36px; height: 36px; flex: 0 0 auto; display: grid; place-items: center; border: 0; border-radius: 50%;
  cursor: pointer; font-size: 13px; color: var(--text-secondary);
  background: rgba(245, 239, 230, 0.06); box-shadow: inset 0 0 0 1px var(--divider);
}
.ppl-sheet .ppl-sh-voice {
  display: flex; align-items: center; gap: 12px; padding: 12px; border-radius: 16px;
  background: rgba(245, 239, 230, 0.04); box-shadow: inset 0 0 0 1px var(--divider);
}
.ppl-sheet .ppl-sh-mic {
  width: 52px; height: 52px; flex: 0 0 auto; display: grid; place-items: center; border-radius: 50%;
  background: radial-gradient(circle at 35% 28%, #3A332D, color-mix(in srgb, var(--c) 14%, #1E1B18));
  box-shadow: inset 0 1px 0 rgba(255, 244, 230, 0.08), 0 0 14px -4px color-mix(in srgb, var(--c) 50%, transparent);
}
.ppl-sheet .ppl-sh-mic .t-ico { width: 30px; height: 30px; }
.ppl-sheet .ppl-sh-voicetx { min-width: 0; display: flex; flex-direction: column; gap: 2px; }
.ppl-sheet .ppl-sh-voicetx strong { font-size: 14px; font-weight: 600; }
.ppl-sheet .ppl-sh-voicetx small { font-size: 11px; line-height: 1.45; color: var(--text-muted); }
.ppl-sheet .ppl-sh-or { display: flex; align-items: center; gap: 10px; }
.ppl-sheet .ppl-sh-or::before, .ppl-sheet .ppl-sh-or::after { content: ''; flex: 1; height: 1px; background: var(--divider); }
.ppl-sheet .ppl-sh-or span { font: 600 9.5px/1 var(--ff-body); letter-spacing: 1.3px; text-transform: uppercase; color: var(--text-muted); }
.ppl-sheet .ppl-sh-field { display: grid; gap: 6px; min-width: 0; }
.ppl-sheet .ppl-sh-lbl { font: 600 9.5px/1.2 var(--ff-body); letter-spacing: 1.3px; text-transform: uppercase; color: var(--text-muted); }
.ppl-sheet .ppl-sh-chips { display: flex; flex-wrap: wrap; align-items: center; gap: 6px; }
.ppl-sheet .ppl-sh-chip {
  --c: var(--dv-rose);
  min-width: 0; max-width: 100%; min-height: 36px; padding: 7px 12px; border: 0; border-radius: 999px;
  display: inline-flex; align-items: center; gap: 6px; cursor: pointer;
  font: 600 12px/1.2 var(--ff-body); color: var(--text-secondary);
  background: rgba(245, 239, 230, 0.05); box-shadow: inset 0 0 0 1px var(--divider);
}
.ppl-sheet .ppl-sh-chip.on { color: #191614; background: var(--c); box-shadow: 0 0 12px color-mix(in srgb, var(--c) 50%, transparent); }
.ppl-sheet .ppl-sh-dot { width: 7px; height: 7px; border-radius: 50%; background: var(--c); box-shadow: 0 0 6px var(--c); }
.ppl-sheet .ppl-sh-chip.on .ppl-sh-dot { background: #191614; box-shadow: none; }
.ppl-sheet .ppl-sh-chip:focus-visible, .ppl-sheet .ppl-sh-x:focus-visible, .ppl-sheet .ppl-sh-ghost:focus-visible,
.ppl-sheet .ppl-sh-cta:focus-visible, .ppl-sheet .ppl-sh-delbtn:focus-visible, .ppl-sheet .ppl-sh-aliasx:focus-visible {
  outline: 2px solid var(--dv-rose); outline-offset: 2px;
}
.ppl-sheet .ppl-sh-alias { cursor: default; padding-right: 6px; color: var(--text-primary); }
.ppl-sheet .ppl-sh-aliasx {
  width: 22px; height: 22px; display: grid; place-items: center; border: 0; border-radius: 50%; cursor: pointer;
  font-size: 10px; color: var(--text-muted); background: rgba(245, 239, 230, 0.06);
}
.ppl-sheet .ppl-sh-aliasinp { width: 128px; cursor: text; color: var(--text-primary); color-scheme: dark; }
.ppl-sheet .ppl-sh-inp, .ppl-sheet .ppl-sh-ta {
  width: 100%; min-width: 0; padding: 11px 13px; border: 0; border-radius: 14px;
  font: 400 14px/1.45 var(--ff-body); color: var(--text-primary); color-scheme: dark;
  background: rgba(245, 239, 230, 0.05); box-shadow: inset 0 0 0 1px var(--divider);
}
.ppl-sheet .ppl-sh-ta { min-height: 72px; resize: none; }
.ppl-sheet .ppl-sh-inp::placeholder, .ppl-sheet .ppl-sh-ta::placeholder, .ppl-sheet .ppl-sh-aliasinp::placeholder { color: var(--text-muted); }
.ppl-sheet .ppl-sh-inp:focus-visible, .ppl-sheet .ppl-sh-ta:focus-visible, .ppl-sheet .ppl-sh-aliasinp:focus-visible {
  outline: none; box-shadow: inset 0 0 0 1.5px var(--dv-rose);
}
.ppl-sheet .ppl-sh-pair { display: grid; grid-template-columns: repeat(2, minmax(0, 1fr)); gap: 10px; padding-top: 4px; }
.ppl-sheet .ppl-sh-ghost, .ppl-sheet .ppl-sh-cta {
  min-width: 0; min-height: 46px; border: 0; border-radius: 999px; cursor: pointer;
  display: inline-flex; align-items: center; justify-content: center; gap: 6px;
  font: 700 13.5px/1 var(--ff-body);
}
.ppl-sheet .ppl-sh-ghost { font-weight: 600; color: var(--text-secondary); background: rgba(245, 239, 230, 0.05); box-shadow: inset 0 0 0 1px var(--divider); }
.ppl-sheet .ppl-sh-cta { color: #191614; background: var(--dv-rose); box-shadow: 0 0 14px color-mix(in srgb, var(--dv-rose) 55%, transparent); }
.ppl-sheet .ppl-sh-cta:disabled { opacity: 0.45; cursor: default; box-shadow: none; }
.ppl-sheet .ppl-sh-cta .t-ico, .ppl-sheet .ppl-sh-delbtn .t-ico { width: 18px; height: 18px; filter: none; }
/* Törlés keeps its warning tone: a flat coral outline (U4 rule 29) */
.ppl-sheet .ppl-sh-del { display: grid; gap: 6px; }
.ppl-sheet .ppl-sh-delbtn {
  min-height: 44px; border: 0; border-radius: 999px; cursor: pointer;
  display: inline-flex; align-items: center; justify-content: center; gap: 6px;
  font: 600 13px/1 var(--ff-body); color: #FFB39C;
  background: rgba(255, 126, 92, 0.06); box-shadow: inset 0 0 0 1px rgba(255, 126, 92, 0.4);
}
.ppl-sheet .ppl-sh-delwarn { font-size: 11.5px; line-height: 1.45; text-align: center; color: var(--text-secondary); }
.ppl-sheet .ppl-sh-foot { font-size: 11px; line-height: 1.5; text-align: center; color: var(--text-muted); }

@media (max-width: 360px) {
  .ppl-page .ppl-stats .mz-statcell b { font-size: 17px; }
  .ppl-hub .ppl-hub-tile.glass, .ppl-heti .ppl-dirt.glass { padding: 12px 11px; }
  .ppl-detail .ppl-ctxbar { grid-template-columns: 78px minmax(0, 1fr) 34px; gap: 8px; }
  .ppl-page .mz-page-head .pgact.ppl-act { padding: 0 11px; font-size: 12px; }
}
@media (prefers-reduced-motion: reduce) {
  .ppl-hub .ppl-hub-tile, .ppl-kor .ppl-tile, .ppl-heti .ppl-dirt { transition: none; }
}

/* ── /uveg en2 emberek ── */

/* ── uveg en2 ertesitesek (mezo-me75u.7) ── /me/ertesitesek + /settings/notifications ── */
/* Ranking (bible §3.4, prototype uveg-en2.html `ertesitesek()` / `bert()`). Every rule is scoped
   to a page root — `.nf-page` (the feed) or `.ntf-page` (the settings) — because the header
   notification panel (`── uveg nap uzenetek (`) speaks the same vocabulary (rule 13).
   Feed: the halo PageHero (t-bell, sky); day eyebrows; each notification is a FLAT row (rank 3)
   with the kind's 3D icon in a lit 42px well tinted by its family; an unread row (the opening
   snapshot) gets a sky wash, a sky inset edge and a glowing sky dot; loading = flat skeleton
   rows; empty = dashed sky outline. Settings: the halo PageHero; the NAPI TERHELÉS preview is ONE
   sky glass card (lit sky bars, coral inside a dense window, flat coral note); the master switch
   is a one-row sky glass card; the test CTA is a flat pill; each category group is ONE sky glass
   card with flat hairline-separated rows (the `.srows` pattern) and sky-lit switches (`.uv-tgl`,
   the Toggle `glass` variant); the install gate is an amber glass notice. */

/* the ground: the aurora shows through; quiet eyebrows and principle footnotes */
.nf-page.mz-page, .ntf-page.mz-page { background: transparent; }
.nf-page .mz-page-body, .ntf-page .mz-page-body { padding: 2px 16px 22px; }

/* ── feed (/me/ertesitesek) ── */
.nf-page .nf-group + .nf-group { margin-top: 2px; }
.nf-page .nf-daylabel {
  padding: 16px 4px 8px; font: 600 9.5px/1.2 var(--ff-body); letter-spacing: 1.3px;
  text-transform: uppercase; color: var(--text-muted);
}
.nf-page .nf-row {
  --c: var(--dv-sky);
  display: flex; align-items: flex-start; gap: 12px; position: relative; width: 100%;
  padding: 12px 14px 12px 12px; border: 0; border-radius: 18px; text-align: left; color: inherit;
  background: rgba(245, 239, 230, 0.035); box-shadow: inset 0 0 0 1px var(--divider);
}
.nf-page .nf-row + .nf-row { margin-top: 7px; }
.nf-page .nf-row:focus-visible { outline: 2px solid var(--dv-sky); outline-offset: 2px; }
.nf-page .nf-row.unread {
  background: color-mix(in srgb, var(--dv-sky) 7%, rgba(245, 239, 230, 0.03));
  box-shadow: inset 0 0 0 1px var(--divider), inset 2px 0 0 var(--dv-sky);
}
.nf-page .nf-row .nf-dot {
  position: absolute; left: auto; top: auto; right: 14px; bottom: 14px; transform: none;
  width: 7px; height: 7px; border-radius: 50%;
  background: var(--dv-sky); box-shadow: 0 0 8px var(--dv-sky);
}
/* the kind's family tint publishes `--c` on the well itself (rule 4) — the same families the
   old `.nf-ico.*` washes drew, now lighting the kit well */
.nf-page .nf-ico.uv-well { width: 42px; height: 42px; border-radius: 50%; }
.nf-page .nf-ico.pattern, .nf-page .nf-ico.character { --c: var(--dv-lav); }
.nf-page .nf-ico.knowledge, .nf-page .nf-ico.habit { --c: var(--dv-sage); }
.nf-page .nf-ico.prediction, .nf-page .nf-ico.people { --c: var(--dv-sky); }
.nf-page .nf-ico.experiment, .nf-page .nf-ico.memoir { --c: var(--dv-amber); }
.nf-page .nf-ico.goal { --c: var(--dv-coral); }
.nf-page .nf-ico.memory { --c: var(--text-muted); }
.nf-page .nf-ico .t-ico { filter: drop-shadow(0 4px 5px rgba(0, 0, 0, 0.5)); }
.nf-page .nf-txt { flex: 1; min-width: 0; display: block; }
.nf-page .nf-t { display: block; font: 600 14px/1.3 var(--ff-body); color: var(--text-primary); }
.nf-page .nf-x {
  display: -webkit-box; -webkit-line-clamp: 2; -webkit-box-orient: vertical; overflow: hidden;
  margin-top: 3px; font: 400 12px/1.4 var(--ff-body); color: var(--text-secondary);
}
.nf-page .nf-time {
  flex: 0 0 auto; margin-top: 2px; white-space: nowrap; font: 500 11px/1 var(--ff-body);
  color: var(--text-muted); font-variant-numeric: tabular-nums;
}
.nf-page .nf-loading { display: flex; flex-direction: column; gap: 7px; padding-top: 14px; }
.nf-page .nf-skel { background: rgba(245, 239, 230, 0.035); box-shadow: inset 0 0 0 1px var(--divider); }
.nf-page .nf-empty.uv-empty {
  --c: var(--dv-sky);
  margin: 14px 0 0; padding: 22px 16px; border-radius: 18px; text-align: center;
  font-size: 13.5px; color: var(--text-secondary);
}
.nf-page .nf-note {
  margin: 22px 10px 0; font-size: 12px; line-height: 1.55; text-align: center; color: var(--text-muted);
}

/* ── settings (/settings/notifications) ── */
.ntf-page .eyebrow {
  display: block; padding: 18px 4px 8px; font: 600 9.5px/1.2 var(--ff-body); letter-spacing: 1.3px;
  text-transform: uppercase; color: var(--text-muted);
}
/* the glass body restated where the old Mozaik rules keep a border / light skin (rule 11) */
.ntf-page .ntf-prev.glass, .ntf-page .ntf-masterrow.glass, .ntf-page .ntf-cats.glass, .ntf-page .ntf-gate.glass {
  border: 0;
  background:
    radial-gradient(120% 90% at 0% 0%, color-mix(in srgb, var(--c) 22%, transparent), transparent 62%),
    linear-gradient(160deg, rgba(52, 46, 41, 0.72), rgba(30, 27, 24, 0.6));
  box-shadow:
    0 16px 30px -16px rgba(0, 0, 0, 0.75),
    0 0 26px -6px color-mix(in srgb, var(--c) 30%, transparent),
    inset 0 1px 0 rgba(255, 244, 230, 0.1),
    inset 0 -14px 26px -18px color-mix(in srgb, var(--c) 55%, transparent);
}

/* NAPI TERHELÉS — one sky glass card, lit bars, coral where the day crowds */
.ntf-page .ntf-prev.glass { display: block; padding: 14px 15px 13px; border-radius: 22px; }
.ntf-page .ntf-prev-top { display: flex; align-items: baseline; justify-content: space-between; gap: 10px; }
.ntf-page .ntf-prev-eb {
  font: 600 9.5px/1.2 var(--ff-body); letter-spacing: 1.3px; text-transform: uppercase;
  color: color-mix(in srgb, var(--c) 70%, var(--text-primary));
}
.ntf-page .ntf-prev-total { font-size: 15px; font-weight: 600; color: var(--text-primary); font-variant-numeric: tabular-nums; }
.ntf-page .ntf-prev-bars { display: flex; align-items: flex-end; gap: 2px; height: 54px; margin-top: 12px; }
.ntf-page .ntf-prev-bars i { flex: 1; min-height: 2px; border-radius: 2px 2px 1px 1px; background: rgba(245, 239, 230, 0.08); }
.ntf-page .ntf-prev-bars i.on {
  background: linear-gradient(180deg, color-mix(in srgb, var(--dv-sky) 55%, #fff), var(--dv-sky));
  box-shadow: 0 0 6px -1px var(--dv-sky);
}
.ntf-page .ntf-prev-bars i.hot {
  background: linear-gradient(180deg, color-mix(in srgb, var(--dv-coral) 50%, #fff), var(--dv-coral));
  box-shadow: 0 0 6px -1px var(--dv-coral);
}
.ntf-page .ntf-prev-axis {
  display: flex; justify-content: space-between; margin-top: 5px;
  font-size: 9.5px; color: var(--text-muted); font-variant-numeric: tabular-nums;
}
.ntf-page .ntf-prev-warn {
  display: flex; align-items: center; gap: 9px; margin: 12px 0 0; padding: 9px 11px; border-radius: 14px;
  font-size: 12px; font-weight: 500; line-height: 1.4;
  color: color-mix(in srgb, var(--dv-coral) 65%, var(--text-primary));
  background: color-mix(in srgb, var(--dv-coral) 10%, rgba(245, 239, 230, 0.03));
  box-shadow: inset 0 0 0 1px color-mix(in srgb, var(--dv-coral) 30%, transparent);
}
.ntf-page .ntf-prev-warn .t-ico { filter: drop-shadow(0 3px 4px rgba(0, 0, 0, 0.45)); }

/* the master switch — a one-row sky glass card */
.ntf-page .ntf-masterrow.glass { display: flex; align-items: center; gap: 12px; padding: 11px 14px; border-radius: 22px; }
.ntf-page .ntf-mic.uv-well, .ntf-page .ntf-cic.uv-well { width: 42px; height: 42px; border-radius: 50%; }
.ntf-page .ntf-master-tx, .ntf-page .ntf-cat-tx { display: flex; flex-direction: column; flex: 1; min-width: 0; }
.ntf-page .ntf-master-nm, .ntf-page .ntf-cat-nm { font-size: 14.5px; font-weight: 600; color: var(--text-primary); }
.ntf-page .ntf-master-sb, .ntf-page .ntf-cat-sb {
  margin-top: 1px; font-size: 11.5px; line-height: 1.35; color: var(--text-muted);
  overflow-wrap: anywhere;
}
.ntf-page .ntf-err { margin: -4px 4px 0; font-size: 12px; }

/* the test CTA — a flat pill (the prototype `btn flatb`), not a lit primary */
.ntf-page .ntf-testrow { border: 0; padding: 0; background: none; box-shadow: none; border-radius: 0; }
.ntf-page .ntf-testrow .cta-primary.ntf-testbtn {
  display: flex; align-items: center; justify-content: center; gap: 8px; width: 100%; height: 46px; padding: 0 16px;
  border: 0; border-radius: 999px; font-size: 14px; font-weight: 600; color: var(--text-primary);
  background: rgba(245, 239, 230, 0.05); box-shadow: inset 0 0 0 1px var(--divider);
}
.ntf-page .ntf-testrow .cta-primary.ntf-testbtn:disabled { opacity: 0.5; }
.ntf-page .ntf-testbtn .t-ico { filter: drop-shadow(0 3px 4px rgba(0, 0, 0, 0.45)); }
.ntf-page .ntf-testres { margin: 8px 4px 0; font-size: 12px; }

/* the category groups — ONE glass card each, flat hairline-separated rows (.srows / .srow3) */
.ntf-page .ntf-cats.glass { display: block; padding: 4px 14px; border-radius: 22px; }
.ntf-page .ntf-catrow {
  display: flex; align-items: center; gap: 12px; margin: 0; padding: 11px 0;
  border: 0; border-radius: 0; background: none; box-shadow: none; opacity: 1;
}
.ntf-page .ntf-catrow + .ntf-catrow { border-top: 1px solid var(--divider); }
/* an off category keeps its row; only the art and the words quieten (the switch says "off") */
.ntf-page .ntf-catrow.off .ntf-cic { filter: saturate(0.35) brightness(0.8); }
.ntf-page .ntf-catrow.off .ntf-cat-nm { color: var(--text-secondary); }
.ntf-page .ntf-leadch {
  flex: 0 0 auto; padding: 2px 7px; border-radius: 999px; font-size: 10.5px; font-weight: 700;
  color: var(--text-secondary); background: rgba(245, 239, 230, 0.06); font-variant-numeric: tabular-nums;
}
.ntf-page .ntf-foot { margin: 0; padding: 18px 10px 0; font-size: 12px; font-weight: 400; line-height: 1.55; text-align: center; color: var(--text-muted); }

/* the sky-lit switch (Toggle `glass`) — lit in the surrounding card's `--c` */
.ntf-page .uv-tgl {
  position: relative; flex: 0 0 auto; width: 44px; height: 26px; padding: 0; border: 0; border-radius: 999px;
  cursor: pointer; background: rgba(245, 239, 230, 0.1); box-shadow: inset 0 0 0 1px var(--divider);
  transition: background 0.2s ease, box-shadow 0.2s ease;
}
.ntf-page .uv-tgl-knob {
  position: absolute; left: 3px; top: 3px; width: 20px; height: 20px; border-radius: 50%;
  background: #B7A899; transition: left 0.2s var(--uv-ease, ease), background 0.2s ease;
}
.ntf-page .uv-tgl.is-on {
  background: color-mix(in srgb, var(--c, var(--dv-sky)) 70%, #1E1B18);
  box-shadow: 0 0 12px -2px var(--c, var(--dv-sky));
}
.ntf-page .uv-tgl.is-on .uv-tgl-knob { left: 21px; background: #FFF6EA; }
.ntf-page .uv-tgl:disabled { cursor: not-allowed; opacity: 0.45; }
.ntf-page .uv-tgl:focus-visible { outline: 2px solid var(--c, var(--dv-sky)); outline-offset: 2px; }

/* the install gate — the page's one object, an amber glass notice */
.ntf-page .ntf-gate.glass { display: flex; align-items: flex-start; gap: 12px; padding: 14px 15px; border-radius: 22px; }
.ntf-page .ntf-gate p { margin: 0; font-size: 13px; line-height: 1.55; color: var(--text-secondary); }
.ntf-page .ntf-gate strong { color: color-mix(in srgb, var(--c) 70%, var(--text-primary)); font-weight: 600; }

/* ── /uveg en2 ertesitesek ── */

/* ── uveg en2 beallitasok (mezo-me75u.7) ── /settings/* (SettingsFrame, SettingsRow), /settings/me/goal, /settings/account, /settings/mezo/* ── */
/* Prototype uveg-en2 `beall() btrain() bme() bcel() bmezo() bnap() balt() bfiok() bszemely()`.
   Ranking: the hero is a FRAMELESS halo with the domain's Boop (owner, „vegyes", 2026-09-24); the
   „Innen érkeztél" card, the domain tiles, each section's row card, the editorial card and the forms
   are `.glass`; rows, stat cells, day cells, inputs and chips inside them are flat.
   `--sa` is the settings accent a domain class publishes; every glass here sets `--c: var(--sa)` on
   ITSELF (rule 4). settings.css / personal-settings.css / goalSettingsEditor.css load after this
   file, so every glass body is restated at a higher specificity (rule 11).
   Fuel's own settings pages (/settings/fuel, /settings/fuel/slots) import only
   `useSettingsOrigin` — no SettingsFrame markup — so nothing here reaches them. */
.settings-page, .settings-guard-sheet { --sa: var(--dv-lav); }
.settings-page.settings-fuel, .settings-page .settings-fuel { --sa: var(--dv-sage); }
.settings-page.settings-train, .settings-page .settings-train { --sa: var(--dv-coral); }
.settings-page.settings-mezo, .settings-page .settings-mezo { --sa: var(--dv-lav); }
.settings-page.settings-me, .settings-page .settings-me { --sa: var(--dv-rose); }
.settings-page.settings-nap, .settings-page .settings-nap { --sa: var(--dv-amber); }
.settings-page .settings-sky { --sa: var(--dv-sky); }
main.settings-page {
  max-width: 540px; margin: 0 auto; padding: 4px 16px 100px;
  background: transparent; color: var(--text-primary);
}
.settings-page a:focus-visible, .settings-page button:focus-visible,
.settings-page input:focus-visible, .settings-page textarea:focus-visible { outline: 2px solid var(--sa); outline-offset: 3px; }

/* ── breadcrumb: the glass back pill + the „SAJÁT RITMUSODRA" tag (prototype `.bc`) ── */
.settings-page .settings-breadcrumb { display: flex; align-items: center; justify-content: space-between; gap: 12px; padding: 0; }
.settings-page .settings-back.glass {
  --c: #8A7A6A; display: inline-flex; align-items: center; gap: 6px; height: 38px; padding: 0 14px 0 11px;
  border: 0; border-radius: 999px; font-size: 13.5px; font-weight: 600; color: var(--text-secondary);
}
.settings-page .settings-back b { font-size: 19px; font-weight: 400; line-height: 1; margin-top: -2px; }
.settings-page .settings-breadcrumb > span { font: 600 9.5px/1.2 var(--ff-body); letter-spacing: 1.3px; color: var(--text-muted); }

/* ── hero: frameless halo, upright Geist copy left, the Boop tilted 7° right (prototype `.sthero`) ── */
.settings-page .settings-hero {
  --c: var(--sa); position: relative; isolation: isolate; overflow: visible;
  display: grid; grid-template-columns: minmax(0, 1fr) auto; align-items: center; gap: 10px;
  margin: 0; padding: 12px 4px 10px;
}
/* the halo stays inside the page's side padding, so it needs no clip (a clip drew a hard edge) */
.settings-page .settings-hero::before {
  content: ''; position: absolute; right: -14px; top: 50%; z-index: -1; pointer-events: none;
  width: 300px; max-width: calc(100% + 28px); height: 240px; transform: translateY(-50%);
  background: radial-gradient(farthest-side at 55% 50%,
    color-mix(in srgb, var(--c) 30%, transparent),
    color-mix(in srgb, var(--dv-amber) 10%, transparent) 42%, transparent 72%);
}
.settings-page .settings-hero .settings-kicker {
  display: block; font: 600 9.5px/1.2 var(--ff-body); letter-spacing: 1.3px;
  color: color-mix(in srgb, var(--c) 70%, var(--text-primary));
}
.settings-page .settings-hero h1 {
  margin: 5px 0 0; font-family: var(--ff-body); font-style: normal; font-size: 27px; font-weight: 600;
  letter-spacing: -0.8px; line-height: 1.12; color: var(--text-primary); overflow-wrap: anywhere;
}
.settings-page .settings-hero p { margin: 6px 0 0; font-size: 12.5px; line-height: 1.45; color: var(--text-secondary); }
.settings-page .settings-hero > .boop {
  flex: none; transform: rotate(7deg);
  filter: drop-shadow(0 10px 14px rgba(0, 0, 0, 0.5)) drop-shadow(0 0 16px color-mix(in srgb, var(--c) 40%, transparent));
}

/* ── section eyebrows, footnotes (prototype `h3()` / `principle()`) ── */
.settings-page .settings-section-label {
  margin: 22px 2px 8px; font: 600 9.5px/1.3 var(--ff-body); letter-spacing: 1.4px; text-transform: uppercase;
  color: var(--text-muted);
}
.settings-page .settings-footnote, .settings-page .settings-note {
  margin: 0; padding: 22px 10px 0; border: 0; text-align: center;
  font-size: 12px; line-height: 1.55; color: var(--text-muted);
}
.settings-page .settings-gap { height: 10px; }

/* ── the glass bodies, restated (rule 11: the feature sheets load after this file) ── */
.settings-page .settings-current.glass, .settings-page .settings-domain.glass,
.settings-page .settings-wash.glass, .settings-page .settings-rows.glass,
.settings-page .settings-account-wash.glass, .settings-page .personal-editor.glass,
.settings-page .personal-core.glass, .settings-page .personal-learned.glass,
.settings-page .personal-context-list.glass {
  --c: var(--sa); border: 0;
  background:
    radial-gradient(120% 90% at 0% 0%, color-mix(in srgb, var(--c) 22%, transparent), transparent 62%),
    linear-gradient(160deg, rgba(52, 46, 41, 0.72), rgba(30, 27, 24, 0.6));
  box-shadow:
    0 16px 30px -16px rgba(0, 0, 0, 0.75),
    0 0 26px -6px color-mix(in srgb, var(--c) 30%, transparent),
    inset 0 1px 0 rgba(255, 244, 230, 0.1),
    inset 0 -14px 26px -18px color-mix(in srgb, var(--c) 55%, transparent);
}

/* ── hub: „Innen érkeztél" (prototype `.from`) ── */
.settings-page .settings-current.glass {
  display: flex; align-items: center; gap: 12px; margin: 6px 0 0; padding: 12px 14px; border-radius: 20px;
  color: var(--text-primary);
}
.settings-page .settings-current > div { flex: 1; min-width: 0; }
.settings-page .settings-current .settings-kicker { display: block; font: 600 9.5px/1.2 var(--ff-body); letter-spacing: 1.3px; color: var(--text-muted); }
.settings-page .settings-current strong { display: block; margin: 2px 0 0; font-family: var(--ff-body); font-size: 15px; font-weight: 600; }
.settings-page .settings-current p { margin: 0; font-size: 11.5px; line-height: 1.35; color: var(--text-secondary); }
.settings-page .settings-current > span[aria-hidden] { flex: none; font-size: 18px; color: var(--text-muted); }

/* ── hub: the domain tiles, one accent each; Nap spans both columns (prototype `.domg .domt`) ── */
.settings-page .settings-domain-grid { display: grid; grid-template-columns: 1fr 1fr; gap: 10px; align-items: stretch; }
.settings-page .settings-domain.glass {
  display: flex; flex-direction: column; gap: 3px; min-width: 0; min-height: 162px; margin: 0;
  padding: 13px; border-radius: 22px; color: var(--text-primary);
}
.settings-page .settings-domain > .boop { margin-bottom: auto; }
.settings-page .settings-domain strong {
  display: block; margin: 8px 0 0; font-family: var(--ff-body); font-size: 17px; font-weight: 600; letter-spacing: -0.4px;
}
.settings-page .settings-domain p { margin: 0; font-size: 12px; line-height: 1.35; color: var(--text-secondary); }
.settings-page .settings-domain small { display: block; margin-top: 4px; font-size: 10.5px; line-height: 1.35; color: var(--text-muted); }
.settings-page .settings-domain > .settings-domain-arrow {
  position: absolute; top: 12px; right: 14px; font-size: 14px; color: color-mix(in srgb, var(--c) 70%, var(--text-muted));
}
.settings-page .settings-domain.glass:last-child {
  grid-column: 1 / -1; display: grid; grid-template-columns: 54px minmax(0, 1fr); column-gap: 12px; row-gap: 3px;
  align-items: center; min-height: 0;
}
.settings-page .settings-domain.glass:last-child > .boop { grid-column: 1; grid-row: 1 / 4; margin: 0; align-self: center; }
.settings-page .settings-domain.glass:last-child > strong,
.settings-page .settings-domain.glass:last-child > p,
.settings-page .settings-domain.glass:last-child > small { grid-column: 2; margin-top: 0; }

/* ── the section card: flat rows, hairline between, a lit 42px well (prototype `.srows .srow3`) ── */
.settings-page .settings-rows.glass { display: block; margin: 0; padding: 4px 14px; border-radius: 22px; }
.settings-page .settings-rows .settings-row {
  display: flex; align-items: center; gap: 12px; width: 100%; margin: 0; padding: 11px 0;
  border: 0; background: none; text-align: left; font: inherit; color: var(--text-primary); cursor: pointer;
}
.settings-page .settings-rows .settings-row + .settings-row { border-top: 1px solid var(--divider); }
.settings-page .settings-row-art.uv-well {
  --c: var(--sa); flex: 0 0 42px; width: 42px; height: 42px; min-width: 0; padding: 0; border-radius: 50%;
  background: radial-gradient(circle at 35% 28%, #3A332D, color-mix(in srgb, var(--c) 14%, #1E1B18));
  box-shadow: inset 0 1px 0 rgba(255, 244, 230, 0.08),
    inset 0 -6px 12px -8px color-mix(in srgb, var(--c) 70%, transparent),
    0 0 14px -4px color-mix(in srgb, var(--c) 50%, transparent);
}
.settings-page .settings-row-copy { flex: 1; min-width: 0; }
.settings-page .settings-rows .settings-row strong { display: block; font-size: 14.5px; font-weight: 600; color: var(--text-primary); }
.settings-page .settings-rows .settings-row small { display: block; margin-top: 1px; font-size: 11.5px; line-height: 1.35; color: var(--text-muted); }
.settings-page .settings-rows .settings-row em {
  display: inline-block; margin-top: 5px; padding: 3px 8px; border-radius: 999px;
  font-size: 10px; font-weight: 700; font-style: normal; letter-spacing: 0.6px; text-transform: uppercase;
  color: color-mix(in srgb, var(--dv-amber) 70%, var(--text-primary));
  background: color-mix(in srgb, var(--dv-amber) 10%, transparent);
  box-shadow: inset 0 0 0 1px color-mix(in srgb, var(--dv-amber) 30%, transparent);
}
.settings-page .settings-chev { flex: none; font-size: 20px; line-height: 1; color: var(--text-muted); }
.settings-page .settings-row .settings-row-end { flex: none; }
.settings-page .settings-rows .settings-logout strong { color: color-mix(in srgb, var(--dv-coral) 60%, var(--text-primary)); }
.settings-page .settings-rows .settings-row:disabled { opacity: 0.55; cursor: default; }

/* ── the editorial card: upright lead, the big numbers as flat cells, the week as lit day cells ── */
.settings-page .settings-wash.glass { margin: 6px 0 12px; padding: 16px; border-radius: 22px; }
.settings-page .settings-wash .settings-editorial {
  margin: 0; font-family: var(--ff-body); font-style: normal; font-size: 15px; font-weight: 500;
  line-height: 1.5; letter-spacing: 0; color: var(--text-primary);
}
.settings-page .settings-wash p:not(.settings-editorial) { margin: 8px 0 0; font-size: 12.5px; line-height: 1.5; color: var(--text-secondary); }
.settings-page .settings-wash .settings-stats { display: grid; grid-template-columns: repeat(2, minmax(0, 1fr)); gap: 8px; margin-top: 12px; }
.settings-page .settings-stats > div {
  min-width: 0; padding: 10px 8px; border-radius: 14px; text-align: center;
  background: rgba(245, 239, 230, 0.05); box-shadow: inset 0 0 0 1px var(--divider);
}
.settings-page .settings-stats strong {
  display: block; font-family: var(--ff-body); font-size: 18px; font-weight: 600; letter-spacing: -0.3px;
  font-variant-numeric: tabular-nums; color: var(--text-primary); overflow-wrap: anywhere;
}
.settings-page .settings-stats small {
  display: block; margin-top: 2px; font-size: 9.5px; font-weight: 600; letter-spacing: 1.1px; text-transform: uppercase;
  color: var(--text-muted);
}
.settings-page .settings-week { display: grid; grid-template-columns: repeat(7, minmax(0, 1fr)); gap: 5px; margin-top: 12px; }
.settings-page .settings-day {
  min-width: 0; padding: 8px 0 7px; border-radius: 12px; text-align: center;
  font-size: 9.5px; font-weight: 600; color: var(--text-muted);
  background: rgba(245, 239, 230, 0.035); box-shadow: inset 0 0 0 1px var(--divider);
}
.settings-page .settings-day strong { display: block; margin-top: 4px; font-size: 11px; font-weight: 600; color: var(--text-primary); }
.settings-page .settings-day.is-on {
  background: color-mix(in srgb, var(--c) 14%, transparent);
  box-shadow: inset 0 0 0 1px color-mix(in srgb, var(--c) 50%, transparent);
}
.settings-page .settings-day.is-on strong { color: color-mix(in srgb, var(--c) 80%, var(--text-primary)); }

/* ── editor pages: the lit primary pill, status + retry ── */
.settings-page .settings-open-button {
  display: flex; align-items: center; justify-content: center; width: 100%; min-height: 44px; margin: 0 0 12px;
  padding: 0 18px; border: 0; border-radius: 999px; font: inherit; font-size: 13.5px; font-weight: 700;
  color: #191614; background: var(--sa); box-shadow: 0 0 14px color-mix(in srgb, var(--sa) 55%, transparent); cursor: pointer;
}
.settings-page .settings-open-button:disabled { opacity: 0.45; box-shadow: none; cursor: default; }
.settings-page .settings-status { margin: 0 2px 10px; font-size: 12.5px; line-height: 1.5; color: var(--text-secondary); }
.settings-page .settings-status button, .settings-page [role="alert"] > button {
  margin-left: 6px; padding: 5px 12px; border: 0; border-radius: 999px; font: inherit; font-size: 12px; font-weight: 600;
  color: var(--text-secondary); background: rgba(245, 239, 230, 0.05); box-shadow: inset 0 0 0 1px var(--divider); cursor: pointer;
}

/* ── Megjelenés és alkalmazás: the account card (prototype `balt()` — a `.from` with a well) ── */
.settings-page .settings-account-wash.glass {
  display: flex; align-items: center; gap: 12px; width: 100%; margin: 0 0 10px; padding: 12px 14px;
  border-radius: 20px; text-align: left; font: inherit; color: var(--text-primary); cursor: pointer;
}
.settings-page .settings-account-wash > span:nth-of-type(2) { flex: 1; min-width: 0; }
.settings-page .settings-account-wash strong { display: block; font-family: var(--ff-body); font-size: 15px; font-weight: 600; }
.settings-page .settings-account-wash small { display: block; margin-top: 1px; font-size: 11.5px; overflow-wrap: anywhere; color: var(--text-secondary); }

/* ── forms: a glass card, flat inputs, the lit CTA (prototype `bfiok()` / `bszemely()`) ── */
.settings-page .personal-editor.glass { --sa: var(--dv-lav); margin: 12px 0 10px; padding: 16px; border-radius: 22px; }
.settings-page .personal-editor.settings-account.glass { --sa: var(--dv-rose); display: grid; gap: 12px; margin-top: 6px; }
.settings-page .settings-account label {
  display: grid; gap: 6px; margin: 0; font: 600 9.5px/1.3 var(--ff-body); letter-spacing: 1.3px; text-transform: uppercase;
  color: var(--text-muted);
}
.settings-page .personal-editor input:not([type="checkbox"]), .settings-page .personal-editor textarea {
  display: block; width: 100%; box-sizing: border-box; margin: 0; padding: 11px 13px; border: 0; border-radius: 13px;
  font: 400 16px/1.4 var(--ff-body); letter-spacing: 0; text-transform: none; color: var(--text-primary); color-scheme: dark;
  background: rgba(245, 239, 230, 0.05); box-shadow: inset 0 0 0 1px var(--divider);
}
.settings-page .personal-editor textarea { min-height: 150px; padding: 13px; border-radius: 16px; font-size: 14px; line-height: 1.55; resize: vertical; }
.settings-page .personal-editor input:focus-visible, .settings-page .personal-editor textarea:focus-visible {
  outline: none; box-shadow: inset 0 0 0 1.5px var(--c);
}
.settings-page .personal-editor .settings-kicker { display: block; font: 600 9.5px/1.2 var(--ff-body); letter-spacing: 1.3px; color: var(--text-muted); }
.settings-page .personal-editor h2 {
  margin: 3px 0 0; font-family: var(--ff-body); font-style: normal; font-size: 17px; font-weight: 600; letter-spacing: -0.3px;
  color: var(--text-primary);
}
.settings-page .personal-editor p { margin: 6px 0 10px; font-size: 12.5px; line-height: 1.5; color: var(--text-secondary); }
.settings-page .personal-editor.settings-account p { margin: 0; }
.settings-page .personal-field-foot { display: flex; justify-content: space-between; margin: 6px 0 12px; font-size: 10.5px; color: var(--text-muted); }
.settings-page .personal-switch {
  display: flex; align-items: center; gap: 12px; margin: 0 0 12px; padding: 12px 0 0; border-top: 1px solid var(--divider);
}
.settings-page .personal-switch strong { display: block; font-size: 13px; font-weight: 600; color: var(--text-primary); }
.settings-page .personal-switch small { display: block; margin-top: 4px; font-size: 11.5px; line-height: 1.45; color: var(--text-muted); }
/* the checkbox wears the prototype `.tgl`: a track with a knob, lit in the accent when on */
.settings-page .personal-switch input[type="checkbox"] {
  appearance: none; -webkit-appearance: none; flex: none; width: 44px; height: 26px; margin: 0; border-radius: 999px; cursor: pointer;
  background: radial-gradient(circle at 13px 50%, #B7A899 0 10px, transparent 10.5px), rgba(245, 239, 230, 0.1);
  box-shadow: inset 0 0 0 1px var(--divider); transition: background 0.2s;
}
.settings-page .personal-switch input[type="checkbox"]:checked {
  background: radial-gradient(circle at 31px 50%, #FFF6EA 0 10px, transparent 10.5px), color-mix(in srgb, var(--c) 70%, #1E1B18);
  box-shadow: 0 0 12px -2px var(--c);
}
.settings-page .personal-switch input[type="checkbox"]:disabled { opacity: 0.5; }
.settings-page .personal-editor .cta-primary {
  display: flex; align-items: center; justify-content: center; width: 100%; min-height: 44px; margin: 2px 0 0; padding: 0 18px;
  border: 0; border-radius: 999px; font: inherit; font-size: 13.5px; font-weight: 700;
  color: #191614; background: var(--c); box-shadow: 0 0 14px color-mix(in srgb, var(--c) 55%, transparent);
}
.settings-page .personal-editor .cta-primary:disabled { opacity: 0.45; box-shadow: none; }
.settings-page .personal-editor [role="status"] { color: color-mix(in srgb, var(--dv-sage) 75%, var(--text-primary)); }
.settings-page .personal-editor [role="alert"] { color: color-mix(in srgb, var(--dv-coral) 65%, var(--text-primary)); }

/* ── Rólam: the core facts card, the sources, the learned profile ── */
.settings-page .personal-sources { margin: 6px 0 0; }
.settings-page .personal-sources > .settings-kicker {
  display: block; margin: 22px 2px 8px; font: 600 9.5px/1.3 var(--ff-body); letter-spacing: 1.4px; color: var(--text-muted);
}
.settings-page .personal-core.glass { --sa: var(--dv-rose); margin: 0; padding: 14px 16px; border-radius: 22px; }
.settings-page .personal-core h2 {
  margin: 0; font: 600 9.5px/1.3 var(--ff-body); letter-spacing: 1.3px; text-transform: uppercase; color: var(--text-muted);
}
.settings-page .personal-core p { margin: 6px 0 0; font-size: 14px; line-height: 1.55; color: var(--text-primary); white-space: pre-wrap; overflow-wrap: anywhere; }
.settings-page .personal-learned.glass { margin: 12px 0 10px; padding: 16px; border-radius: 22px; }
.settings-page .personal-learned h2 {
  margin: 0 0 10px; font-family: var(--ff-body); font-style: normal; font-size: 15.5px; font-weight: 600; letter-spacing: -0.3px;
  color: var(--text-primary);
}
.settings-page .personal-learned p { margin: 8px 0 0; font-size: 12.5px; line-height: 1.5; color: var(--text-secondary); }
.settings-page .personal-learned .mz-facttile {
  border-radius: 16px; background: rgba(245, 239, 230, 0.05); box-shadow: inset 0 0 0 1px var(--divider);
}

/* ── Ezt kapja meg Mezo: one lav card, hairline sections, an included/left-out chip (prototype `.ctxsec`) ── */
.settings-page .personal-scope { margin: 6px 2px 10px; font-size: 12.5px; line-height: 1.5; color: var(--text-secondary); }
.settings-page .personal-context-list.glass { margin: 0; padding: 4px 14px; border-radius: 22px; }
.settings-page .personal-context-section { padding: 12px 0; border: 0; }
.settings-page .personal-context-section + .personal-context-section { border-top: 1px solid var(--divider); }
.settings-page .personal-context-section header { display: flex; align-items: center; justify-content: space-between; gap: 10px; }
.settings-page .personal-context-section h2 {
  flex: 1; min-width: 0; margin: 0; font-family: var(--ff-body); font-style: normal; font-size: 14px; font-weight: 600; color: var(--text-primary);
}
.settings-page .personal-context-section header > span {
  --k: var(--dv-sage); flex: none; display: inline-flex; align-items: center; gap: 4px; padding: 3px 9px 3px 5px; border-radius: 999px;
  font-size: 10.5px; font-weight: 600; color: color-mix(in srgb, var(--k) 80%, var(--text-primary));
  background: color-mix(in srgb, var(--k) 12%, transparent); box-shadow: inset 0 0 0 1px color-mix(in srgb, var(--k) 35%, transparent);
}
.settings-page .personal-context-section header > span[data-included="false"] { --k: var(--dv-coral); }
.settings-page .personal-context-section header > span .t-ico { filter: none; }
.settings-page .personal-context-section small { display: block; margin-top: 6px; font-size: 10.5px; color: var(--text-muted); }
.settings-page .personal-context-section p {
  margin: 6px 0 0; font-size: 12.5px; line-height: 1.5; color: var(--text-secondary); white-space: pre-wrap; overflow-wrap: anywhere;
}
.settings-page .personal-context-section a {
  display: inline-block; margin-top: 6px; font-size: 12px; font-weight: 600; color: color-mix(in srgb, var(--dv-lav) 70%, var(--text-primary));
}
.settings-page .personal-context-section a::after { content: ' ›'; }
.settings-page .personal-raw {
  margin: 10px 0 0; padding: 12px 14px; border-radius: 18px;
  background: rgba(245, 239, 230, 0.05); box-shadow: inset 0 0 0 1px var(--divider);
}
.settings-page .personal-raw summary { font-size: 14px; font-weight: 600; color: var(--text-secondary); cursor: pointer; text-align: center; }
.settings-page .personal-raw pre { margin: 10px 0 0; font-size: 12px; line-height: 1.6; color: var(--text-secondary); white-space: pre-wrap; overflow-wrap: anywhere; }

/* ── the unsaved-changes guard: ONE floating lav glass sheet (rule 15), lit + flat pills ── */
.sheet.glass.settings-guard-sheet {
  --c: var(--dv-lav);
  position: absolute; left: 10px; right: 10px; bottom: calc(10px + env(safe-area-inset-bottom));
  overflow-x: hidden; overflow-y: auto; border: 0; border-radius: 30px; padding: 4px 18px 18px;
}
.sheet.glass.settings-guard-sheet .sheet-handle { background: rgba(245, 239, 230, 0.22); }
.settings-guard-sheet .settings-guard-body { display: grid; gap: 10px; padding: 6px 0 0; }
.settings-guard-sheet .settings-guard-body h2 { margin: 0; font-size: 19px; font-weight: 600; letter-spacing: -0.5px; color: var(--text-primary); }
.settings-guard-sheet .settings-guard-body p { margin: 0 0 4px; font-size: 13px; line-height: 1.5; color: var(--text-secondary); }
.settings-guard-sheet .settings-guard-body .cta-primary, .settings-guard-sheet .settings-guard-body .cta-ghost {
  display: flex; align-items: center; justify-content: center; width: 100%; min-height: 44px; margin: 0; padding: 0 16px;
  border: 0; border-radius: 999px; font: inherit; font-size: 13.5px; cursor: pointer;
}
.settings-guard-sheet .settings-guard-body .cta-primary {
  font-weight: 700; color: #191614; background: var(--c); box-shadow: 0 0 14px color-mix(in srgb, var(--c) 55%, transparent);
}
.settings-guard-sheet .settings-guard-body .cta-ghost {
  font-weight: 600; color: var(--text-secondary); background: rgba(245, 239, 230, 0.05); box-shadow: inset 0 0 0 1px var(--divider);
}

/* ── /settings/me/goal: rose; halo hero (U6's .goal-dhero-settings), editor + saved goal as glass ── */
.goal-detail-settings-page.uv-goal { --c: var(--dv-rose); }
.goal-detail-settings-page .goal-pace-editor.glass, .goal-detail-settings-page .goal-settings-grid.glass {
  --c: var(--dv-rose); border: 0; border-radius: 22px;
  background:
    radial-gradient(120% 90% at 0% 0%, color-mix(in srgb, var(--c) 20%, transparent), transparent 62%),
    linear-gradient(160deg, rgba(52, 46, 41, 0.72), rgba(30, 27, 24, 0.6));
  box-shadow:
    0 16px 30px -16px rgba(0, 0, 0, 0.75),
    0 0 26px -6px color-mix(in srgb, var(--c) 26%, transparent),
    inset 0 1px 0 rgba(255, 244, 230, 0.1),
    inset 0 -14px 26px -18px color-mix(in srgb, var(--c) 50%, transparent);
}
.goal-detail-settings-page .goal-pace-editor.glass { display: grid; gap: 10px; margin: 12px 0; padding: 16px; }
.goal-detail-settings-page .goal-pace-editor .eyebrow {
  display: block; font: 600 9.5px/1.3 var(--ff-body); letter-spacing: 1.3px; text-transform: uppercase; color: var(--text-muted);
}
.goal-detail-settings-page .goal-pace-editor h2 {
  margin: -6px 0 0; font-family: var(--ff-body); font-size: 18px; font-weight: 600; letter-spacing: -0.4px; line-height: 1.2; color: var(--text-primary);
}
.goal-detail-settings-page .goal-pace-editor p { margin: 0; font-size: 12.5px; line-height: 1.5; color: var(--text-secondary); }
.goal-detail-settings-page .goal-pace-fields { display: grid; grid-template-columns: repeat(2, minmax(0, 1fr)); gap: 10px; }
.goal-detail-settings-page .goal-pace-fields label {
  display: grid; align-content: end; gap: 6px; min-width: 0;
  font: 600 9.5px/1.3 var(--ff-body); letter-spacing: 1.2px; text-transform: uppercase; color: var(--text-muted);
}
.goal-detail-settings-page .goal-pace-fields input {
  width: 100%; min-width: 0; box-sizing: border-box; padding: 11px 13px; border: 0; border-radius: 13px;
  font: 600 16px/1.3 var(--ff-body); letter-spacing: 0; text-transform: none; font-variant-numeric: tabular-nums;
  color: var(--text-primary); color-scheme: dark; background: rgba(245, 239, 230, 0.05); box-shadow: inset 0 0 0 1px var(--divider);
}
.goal-detail-settings-page .goal-pace-fields input:focus-visible { outline: none; box-shadow: inset 0 0 0 1.5px var(--c); }
/* the computed date: a sage-lit callout (prototype `.callout`), flat — never glass in glass */
.goal-detail-settings-page .goal-pace-arrival {
  display: grid; gap: 3px; padding: 12px 14px; border: 0; border-radius: 15px;
  background: color-mix(in srgb, var(--dv-sage) 9%, rgba(245, 239, 230, 0.03));
  box-shadow: inset 0 0 0 1px color-mix(in srgb, var(--dv-sage) 30%, transparent);
}
.goal-detail-settings-page .goal-pace-arrival span {
  font: 600 9.5px/1.3 var(--ff-body); letter-spacing: 1.2px; text-transform: uppercase;
  color: color-mix(in srgb, var(--dv-sage) 80%, var(--text-primary));
}
.goal-detail-settings-page .goal-pace-arrival output { font-family: var(--ff-body); font-size: 17px; font-weight: 600; color: var(--text-primary); }
.goal-detail-settings-page .goal-pace-verdict {
  padding: 11px 13px; border-radius: 14px; font-size: 12.5px; line-height: 1.5; color: var(--text-secondary);
  background: rgba(245, 239, 230, 0.05); box-shadow: inset 0 0 0 1px var(--divider);
}
.goal-detail-settings-page .goal-pace-verdict strong { color: var(--text-primary); font-weight: 600; }
.goal-detail-settings-page .goal-pace-editor [role="status"] { color: color-mix(in srgb, var(--dv-sage) 75%, var(--text-primary)); }
.goal-detail-settings-page .goal-pace-editor [role="alert"] { font-size: 12.5px; color: color-mix(in srgb, var(--dv-coral) 65%, var(--text-primary)); }
.goal-detail-settings-page .goal-pace-editor [role="alert"] button {
  margin-left: 6px; min-height: 0; padding: 5px 12px; border: 0; border-radius: 999px; font: inherit; font-size: 12px; font-weight: 600;
  color: var(--text-secondary); background: rgba(245, 239, 230, 0.05); box-shadow: inset 0 0 0 1px var(--divider);
}
.goal-detail-settings-page .goal-pace-editor .cta-primary,
.goal-detail-settings-page .mz-page-body > .cta-primary {
  display: flex; align-items: center; justify-content: center; width: 100%; min-height: 44px; padding: 0 18px;
  border: 0; border-radius: 999px; font: inherit; font-size: 13.5px; font-weight: 700;
  color: #191614; background: var(--dv-rose); box-shadow: 0 0 14px color-mix(in srgb, var(--dv-rose) 55%, transparent);
}
.goal-detail-settings-page .goal-pace-editor .cta-primary:disabled { opacity: 0.45; box-shadow: none; }
/* the saved goal: label ↔ value rows split by hairlines (prototype `.titrow`) */
.goal-detail-settings-page .goal-settings-grid.glass { display: block; padding: 4px 14px; }
.goal-detail-settings-page .goal-settings-grid > div {
  display: flex; align-items: baseline; justify-content: space-between; gap: 12px; padding: 11px 0; border-radius: 0; background: none;
}
.goal-detail-settings-page .goal-settings-grid > div + div { border-top: 1px solid var(--divider); }
.goal-detail-settings-page .goal-settings-grid small {
  font-size: 13px; font-weight: 500; letter-spacing: 0; text-transform: none; color: var(--text-secondary);
}
.goal-detail-settings-page .goal-settings-grid strong { font-size: 13.5px; font-weight: 600; text-align: right; color: var(--text-primary); }
/* the guards: flat chips with the shield, the active ones lit sage */
.goal-detail-settings-page .goal-settings-guards { display: flex; flex-wrap: wrap; gap: 7px; margin-top: 10px; }
.goal-detail-settings-page .goal-settings-guards span {
  display: inline-flex; align-items: center; gap: 5px; padding: 4px 11px 4px 6px; border-radius: 999px;
  font-size: 11.5px; font-weight: 600; color: var(--text-muted);
  background: rgba(245, 239, 230, 0.04); box-shadow: inset 0 0 0 1px var(--divider);
}
.goal-detail-settings-page .goal-settings-guards span .t-ico { opacity: 0.45; filter: grayscale(0.6); }
.goal-detail-settings-page .goal-settings-guards span.is-on {
  color: color-mix(in srgb, var(--dv-sage) 80%, var(--text-primary));
  background: color-mix(in srgb, var(--dv-sage) 12%, transparent);
  box-shadow: inset 0 0 0 1px color-mix(in srgb, var(--dv-sage) 35%, transparent);
}
.goal-detail-settings-page .goal-settings-guards span.is-on .t-ico { opacity: 1; filter: none; }
/* „Cél szerkesztése": a flat full-width button (prototype `.btn.flatb`) */
.goal-detail-settings-page .goal-settings-edit {
  width: 100%; min-height: 48px; margin-top: 12px; padding: 12px 16px; border: 0; border-radius: 18px;
  font: inherit; font-size: 14.5px; font-weight: 600; color: var(--text-secondary);
  background: rgba(245, 239, 230, 0.05); box-shadow: inset 0 0 0 1px var(--divider);
}

@media (max-width: 360px) {
  .settings-page .settings-hero > .boop { width: 72px; height: 72px; }
  .settings-page .settings-hero h1 { font-size: 24px; }
  .settings-page .settings-domain.glass { min-height: 150px; }
  .settings-page .settings-week { gap: 3px; }
  .settings-page .settings-day strong { font-size: 9.5px; }
  .goal-detail-settings-page .goal-pace-fields { grid-template-columns: 1fr; }
}

/* ── /uveg en2 beallitasok ── */
/* ── uveg mezo1 chat (mezo-me75u.8) ── /mezo/chat: own header, thread, tool strip, refs, recalled memories, feedback, composer + picker / actions sheets ── */
/* Scope: the page root `.mzc-u8` (the old `mzc-*` classes are shared with Fuel's WorkshopChatDock,
   rule 13); the two sheets portal out of the page, so they carry their own `.mzc-sheet`;
   FeedbackChips opts in through `.fbk-chips.is-3d` (the chat AND the glass memoir/prediction pages).
   Ranking: Mezo's answer = ONE lavender glass card; everything inside it is flat. */

/* header row: round glass buttons, a lit well with the Mezo glyph, the status dot */
.mzc-u8 .mzc-chathead {
  gap: 8px; padding: 12px 14px 10px;
  background: linear-gradient(180deg, var(--canvas) 80%, transparent);
}
.mzc-u8 .mzc-hdisc.glass {
  --c: var(--text-muted);
  width: 40px; height: 40px; border: 0; font-size: 19px; color: var(--text-secondary);
}
.mzc-u8 .mzc-hdisc.is-new.glass { --c: var(--dv-lav); }
.mzc-u8 .mzc-hdisc.glass:disabled { opacity: 0.45; }
.mzc-u8 .mzc-horb.uv-well { --c: var(--dv-lav); width: 44px; height: 44px; }
.mzc-u8 .mzc-horb svg, .mzc-u8 .mzc-horb.busy svg { animation: none; }
.mzc-u8 .mzc-horb.busy::before { border-color: color-mix(in srgb, var(--dv-lav) 55%, transparent); }
.mzc-u8 .mzc-hnm { font-size: 17px; font-weight: 600; letter-spacing: -0.3px; }
.mzc-u8 .mzc-hstat {
  display: block; min-width: 0; font-size: 11.5px; color: var(--text-secondary);
  white-space: nowrap; overflow: hidden; text-overflow: ellipsis;
}
.mzc-u8 .mzc-hdot {
  display: inline-block; margin-right: 6px; vertical-align: 1px;
  background: var(--dv-sage); box-shadow: 0 0 6px var(--dv-sage);
}
.mzc-u8 .mzc-hstat[data-st] .mzc-hdot { animation: none; }
.mzc-u8 .mzc-hstat[data-st="busy"] .mzc-hdot { background: var(--dv-amber); box-shadow: 0 0 6px var(--dv-amber); }
.mzc-u8 .mzc-hstat[data-st="off"] .mzc-hdot,
.mzc-u8 .mzc-hstat[data-st="demo"] .mzc-hdot { background: var(--text-muted); box-shadow: none; }

/* thread */
.mzc-u8 .chat-thread { padding: 4px 14px 12px; gap: 14px; }

/* Mezo's answer: the loud thing — one lavender glass card */
.mzc-u8 .mzc-msg-a.glass {
  width: 100%; max-width: 100%; padding: 12px 14px 13px; gap: 9px;
  border-radius: 20px 20px 20px 8px;
}
.mzc-u8 .mzc-meta { gap: 7px; font-size: 11px; color: var(--text-muted); flex-wrap: wrap; }
.mzc-u8 .mzc-meta .mzc-eb {
  font-size: 12px; font-weight: 600; letter-spacing: 0; text-transform: none; color: var(--text-primary);
}
.mzc-u8 .mzc-meta time { font-size: 11px; color: var(--text-muted); }
.mzc-u8 .mzc-warn {
  display: inline-flex; align-items: center; gap: 5px; margin-left: auto; padding: 3px 9px 3px 5px;
  border-radius: 999px; font-size: 11px; font-weight: 600; letter-spacing: 0; text-transform: none;
  color: color-mix(in srgb, var(--dv-amber) 75%, var(--text-primary));
  background: color-mix(in srgb, var(--dv-amber) 11%, rgba(245, 239, 230, 0.03));
  box-shadow: inset 0 0 0 1px color-mix(in srgb, var(--dv-amber) 30%, transparent);
}
.mzc-u8 .mzc-warn .t-ico, .mzc-u8 .mzc-meta .t-ico { filter: none; }
.mzc-u8 .mzc-msg-a .mzc-bub-a {
  padding: 0; border: 0; border-radius: 0; background: none; box-shadow: none;
  font-size: 14.5px; line-height: 1.58; color: var(--text-primary);
}
.mzc-u8 .mzc-bub-a .md-prose { font-size: 14.5px; line-height: 1.58; color: var(--text-primary); }
.mzc-u8 .mzc-bub-a .md-prose strong, .mzc-u8 .mzc-bub-a .md-prose b { font-weight: 600; color: #E6DDFF; }
.mzc-u8 .mzc-noanswer { font-size: 13px; font-style: normal; color: var(--text-muted); }

/* tool work strip: a flat cell inside the card */
.mzc-u8 .mzc-tools.mzc-wwrap {
  align-items: stretch; margin-bottom: 0; padding: 8px 10px; border-radius: 14px;
  background: rgba(245, 239, 230, 0.04); box-shadow: inset 0 0 0 1px var(--divider);
}
.mzc-u8 .mzc-wstrip {
  width: 100%; gap: 9px; padding: 0; border: 0; border-radius: 0; background: none; box-shadow: none;
  color: var(--text-secondary);
}
.mzc-u8 .mzc-wstk { padding-left: 6px; }
.mzc-u8 .mzc-wic { width: auto; height: auto; background: none; box-shadow: none; border-radius: 50%; }
.mzc-u8 .mzc-wic + .mzc-wic { margin-left: -6px; }
.mzc-u8 .mzc-wic .t-ico, .mzc-u8 .mzc-wic svg { filter: drop-shadow(0 2px 3px rgba(0, 0, 0, 0.55)); }
.mzc-u8 .mzc-wmore { margin-left: 2px; font-size: 10px; font-weight: 700; color: var(--text-muted); }
.mzc-u8 .mzc-wlbl {
  margin-left: 0; font-size: 12px; font-weight: 600; letter-spacing: 0; text-transform: none; color: var(--text-secondary);
}
.mzc-u8 .mzc-wsub { font-size: 12px; color: var(--text-muted); }
.mzc-u8 .mzc-wchev { margin-left: auto; }
.mzc-u8 .mzc-wpanel { margin-top: 0; padding: 0; border: 0; border-radius: 0; background: none; box-shadow: none; }
.mzc-u8 .mzc-wrow, .mzc-u8 .mzc-wrow + .mzc-wrow {
  align-items: flex-start; gap: 10px; margin-top: 8px; padding: 9px 0 3px; border-top: 1px solid var(--divider);
}
.mzc-u8 .mzc-wric { width: 28px; height: 28px; border-radius: 0; background: none; box-shadow: none; }
.mzc-u8 .mzc-wnm { font-size: 12.5px; font-weight: 600; }
.mzc-u8 .mzc-wprm, .mzc-u8 .mzc-wwhy { font-size: 11px; line-height: 1.4; color: var(--text-muted); }
.mzc-u8 .mzc-wout {
  margin-top: 5px; padding: 7px 9px; border-radius: 10px; font-size: 11.5px; color: var(--text-secondary);
  background: rgba(245, 239, 230, 0.04); box-shadow: inset 0 0 0 1px var(--divider);
}
.mzc-u8 .mzc-wout:focus-visible { outline-color: var(--dv-lav); }
.mzc-u8 .mzc-wocap { font-size: 9.5px; font-weight: 600; letter-spacing: 1.3px; color: var(--text-muted); }
.mzc-u8 .mzc-wst { color: var(--dv-sage); }
.mzc-u8 .mzc-wst .t-ico { filter: none; }
.mzc-u8 .mzc-wrow.run .mzc-wst { font-size: 11px; font-weight: 600; color: var(--dv-lav); }
.mzc-u8 .mzc-wrow.run .mzc-wst i { background: var(--dv-lav); box-shadow: 0 0 6px var(--dv-lav); }

/* "Amire épült" refs: flat domain-tinted chips */
.mzc-u8 .dm-sky { --dmc: var(--dv-sky); }
.mzc-u8 .dm-lav { --dmc: var(--dv-lav); }
.mzc-u8 .dm-sage { --dmc: var(--dv-sage); }
.mzc-u8 .dm-coral { --dmc: var(--dv-coral); }
.mzc-u8 .dm-gold { --dmc: var(--dv-amber); }
.mzc-u8 .dm-rose { --dmc: var(--dv-rose); }
.mzc-u8 .dm-neutral { --dmc: var(--text-muted); }
.mzc-u8 .mzc-reffoot { margin-top: 11px; padding-top: 10px; border-top: 1px solid var(--divider); }
.mzc-u8 .mzc-refeb { display: block; font-size: 9.5px; font-weight: 600; letter-spacing: 1.3px; color: var(--text-muted); }
.mzc-u8 .mzc-refrow { gap: 6px; margin-top: 7px; }
.mzc-u8 .mzc-refch, .mzc-u8 .mzc-refg {
  min-width: 0; max-width: 100%; gap: 5px; padding: 4px 10px 4px 5px; border: 0; border-radius: 999px;
  font-size: 11px; font-weight: 600;
  color: color-mix(in srgb, var(--dmc, var(--dv-lav)) 75%, var(--text-primary));
  background: color-mix(in srgb, var(--dmc, var(--dv-lav)) 11%, rgba(245, 239, 230, 0.03));
  box-shadow: inset 0 0 0 1px color-mix(in srgb, var(--dmc, var(--dv-lav)) 30%, transparent);
}
.mzc-u8 .mzc-refch .mzc-refk { color: var(--text-primary); font-weight: 700; }
.mzc-u8 .mzc-refg.on {
  color: #191614; background: var(--dmc, var(--dv-lav));
  box-shadow: 0 0 12px color-mix(in srgb, var(--dmc, var(--dv-lav)) 50%, transparent);
}
.mzc-u8 .mzc-refic { width: 16px; height: 16px; background: none; }
.mzc-u8 .mzc-refic .t-ico { filter: none; }

/* "Emlékek" recalled memories: a disclosure, then flat cells stacked */
.mzc-u8 .mzc-memwrap { margin-top: 2px; }
.mzc-u8 .mzc-membtn { padding: 0; gap: 7px; }
.mzc-u8 .mzc-memeb {
  gap: 7px; font-size: 12px; font-weight: 600; letter-spacing: 0; text-transform: none; color: var(--text-secondary);
}
.mzc-u8 .mzc-memeb .t-ico { filter: none; }
.mzc-u8 .mzc-memcards { display: grid; gap: 8px; margin: 0; padding: 6px 0 0; overflow: visible; }
.mzc-u8 .mzc-memcard, .mzc-u8 .mzc-memcard.feedback, .mzc-u8 .mzc-memcard.open {
  width: auto; min-width: 0; padding: 10px 11px; gap: 8px; border: 0; border-radius: 13px; transition: none;
  background: rgba(245, 239, 230, 0.04); box-shadow: inset 0 0 0 1px var(--divider);
}
.mzc-u8 .mzc-memtop { gap: 8px; }
.mzc-u8 .mzc-memic { width: 24px; height: 24px; border-radius: 0; background: none; box-shadow: none; }
.mzc-u8 .mzc-memic .t-ico { filter: none; }
.mzc-u8 .mzc-memkt { flex: 1; }
.mzc-u8 .mzc-memkind {
  font-size: 13px; font-weight: 600; letter-spacing: 0; text-transform: none; color: var(--text-primary);
}
.mzc-u8 .mzc-memd { font-size: 10.5px; color: var(--text-muted); }
.mzc-u8 .mzc-simr {
  width: auto; height: auto; padding: 2px 7px; border-radius: 8px; background: rgba(171, 159, 210, 0.14);
}
.mzc-u8 .mzc-simr-n {
  display: inline-block; width: auto; height: auto; background: none; white-space: nowrap;
  font-size: 11px; font-weight: 700; color: #E6DDFF;
}
.mzc-u8 .mzc-simr-n::after { content: '%'; }
.mzc-u8 .mzc-memindicator {
  padding: 2px 8px; font-size: 10.5px; font-weight: 600; color: var(--text-secondary);
  background: rgba(245, 239, 230, 0.05); box-shadow: inset 0 0 0 1px var(--divider);
}
.mzc-u8 .mzc-memgist { font-size: 12.5px; font-weight: 400; line-height: 1.5; color: var(--text-secondary); }
.mzc-u8 .mzc-memactions { gap: 6px; }
.mzc-u8 .mzc-memactions button {
  min-height: 30px; padding: 5px 10px; border: 0; border-radius: 999px;
  font: 600 11px/1.2 var(--ff-body); color: var(--text-secondary);
  background: rgba(245, 239, 230, 0.05); box-shadow: inset 0 0 0 1px var(--divider);
}
.mzc-u8 .mzc-memactions button[aria-pressed="true"] {
  color: #191614; background: var(--dv-lav); box-shadow: 0 0 10px rgba(171, 159, 210, 0.5);
}
.mzc-u8 .mzc-memactions button.danger { color: #FFB39C; }
.mzc-u8 .mzc-memactions button.confirm {
  color: #FFB39C; box-shadow: inset 0 0 0 1px color-mix(in srgb, var(--dv-coral) 55%, transparent);
}
.mzc-u8 .mzc-memstatus { font-size: 11px; font-weight: 600; color: var(--text-muted); }

/* the user's own words: flat warm amber-tinted bubble */
.mzc-u8 .mzc-msg-u { max-width: 84%; }
.mzc-u8 .mzc-bub-u {
  padding: 11px 14px 9px; border: 0; border-radius: 20px 20px 8px 20px;
  background: linear-gradient(160deg, rgba(255, 190, 96, 0.15), rgba(255, 190, 96, 0.06));
  box-shadow: inset 0 0 0 1px rgba(255, 190, 96, 0.24);
}
.mzc-u8 .mzc-bub-u p { font-size: 14.5px; line-height: 1.5; color: var(--text-primary); }
.mzc-u8 .mzc-msg-u time { font-size: 10.5px; color: var(--text-muted); }

/* Mezo is working: flat typing pill (and the pre-draft block with its live tool strip) */
.mzc-u8 .mzc-msg-a.mzc-think, .mzc-u8 .mzc-msg-a.mzc-pending {
  width: auto; max-width: 100%; padding: 10px 14px; gap: 7px; border-radius: 18px;
  background: rgba(245, 239, 230, 0.04); box-shadow: inset 0 0 0 1px var(--divider);
}
.mzc-u8 .mzc-msg-a.mzc-pending { width: 100%; }
.mzc-u8 .mzc-pending .mzc-tools.mzc-wwrap { padding: 0; background: none; box-shadow: none; }
.mzc-u8 .mzc-typing { width: auto; padding: 2px 0; border: 0; border-radius: 0; background: none; box-shadow: none; }
.mzc-u8 .mzc-typing > div { box-shadow: 0 0 6px var(--dv-lav); }
.mzc-u8 .mzc-phase { color: var(--text-secondary); }

/* a failed turn: dashed coral free space, lit "Újra", flat "Szerkesztés" */
.mzc-u8 .mzc-bub-err {
  align-self: stretch; padding: 12px 14px; border: 1.5px dashed rgba(255, 126, 92, 0.45); border-radius: 18px;
  background: none; box-shadow: none; font-size: 13px; line-height: 1.5; color: var(--text-secondary);
}
.mzc-u8 .mzc-bub-err b { color: #FFB39C; font-weight: 600; }
.mzc-u8 .mzc-errrow { display: flex; flex-wrap: wrap; gap: 8px; margin-top: 10px; }
.mzc-u8 .mzc-ebtn {
  min-height: 36px; padding: 8px 14px; border: 0; border-radius: 999px; font: 700 12.5px/1 var(--ff-body);
}
.mzc-u8 .mzc-ebtn.go { color: #191614; background: var(--dv-lav); box-shadow: 0 0 14px color-mix(in srgb, var(--dv-lav) 55%, transparent); }
.mzc-u8 .mzc-ebtn.ghost {
  font-weight: 600; color: var(--text-secondary); background: rgba(245, 239, 230, 0.05); box-shadow: inset 0 0 0 1px var(--divider);
}

/* companion switched off: dashed neutral banner */
.mzc-u8 .mzc-degr {
  margin: 0 14px; padding: 10px 12px; border-radius: 14px; border: 1.5px dashed rgba(138, 122, 106, 0.45);
}
.mzc-u8 .mzc-degr p { font-size: 12.5px; line-height: 1.5; color: var(--text-secondary); }

/* empty draft thread: frameless lavender halo + flat quick-question rows */
.mzc-u8 .mzc-empty { align-self: stretch; }
.mzc-u8 .mzc-emptyhero {
  position: relative; isolation: isolate; overflow-x: clip; text-align: center; padding: 26px 6px 6px;
}
.mzc-u8 .mzc-emptyhero::before {
  content: ''; position: absolute; left: 50%; top: 40%; z-index: -1; pointer-events: none;
  width: 320px; height: 240px; transform: translate(-50%, -50%);
  background: radial-gradient(ellipse at 50% 45%, rgba(171, 159, 210, 0.3), rgba(255, 190, 96, 0.1) 42%, transparent 68%);
}
.mzc-u8 .mzc-emptyhero .t-ico {
  margin: 0 auto;
  filter: drop-shadow(0 12px 14px rgba(0, 0, 0, 0.5)) drop-shadow(0 0 18px rgba(171, 159, 210, 0.45));
}
.mzc-u8 .mzc-emptyhero h2 { margin-top: 8px; font-size: 21px; font-weight: 600; letter-spacing: -0.5px; color: var(--text-primary); }
.mzc-u8 .mzc-emptyhero p { margin-top: 4px; font-size: 13px; line-height: 1.45; color: var(--text-secondary); }
.mzc-u8 .mzc-qqs { display: grid; gap: 8px; padding-top: 16px; }
.mzc-u8 .mzc-qq {
  display: flex; align-items: center; gap: 10px; width: 100%; min-width: 0; padding: 11px 13px;
  border: 0; border-radius: 16px; text-align: left;
  font-size: 13.5px; font-weight: 500; color: var(--text-primary);
  background: rgba(245, 239, 230, 0.04); box-shadow: inset 0 0 0 1px var(--divider);
}
.mzc-u8 .mzc-qq > span { min-width: 0; }

/* composer: a floating lavender glass pill without sheen, above the tab bar */
.mzc-u8 .chat-composer.glass {
  --c: var(--dv-lav);
  position: sticky; align-items: flex-end; gap: 8px; margin-left: 10px; margin-right: 10px;
  padding: 6px; border: 0; border-radius: 26px;
}
.mzc-u8 .mzc-composer textarea { color: var(--text-primary); color-scheme: dark; }
.mzc-u8 .mzc-composer textarea::placeholder { color: var(--text-muted); }
.mzc-u8 .mzc-cmic {
  color: var(--text-secondary); background: rgba(245, 239, 230, 0.06); box-shadow: inset 0 0 0 1px var(--divider);
}
.mzc-u8 .mzc-cmic.rec {
  color: #FFD2C4;
  background: radial-gradient(circle at 35% 30%, color-mix(in srgb, var(--dv-coral) 42%, #3A332D), color-mix(in srgb, var(--dv-coral) 16%, #1E1B18));
  box-shadow: 0 0 14px -2px rgba(255, 126, 92, 0.7), inset 0 0 0 1px rgba(255, 126, 92, 0.5);
}
.mzc-u8 .mzc-csend {
  background: radial-gradient(circle at 35% 30%, color-mix(in srgb, var(--dv-lav) 42%, #3A332D), color-mix(in srgb, var(--dv-lav) 16%, #1E1B18));
  box-shadow: 0 0 14px -2px rgba(171, 159, 210, 0.7), inset 0 0 0 1px rgba(171, 159, 210, 0.5);
}
.mzc-u8 .mzc-cmic .t-ico, .mzc-u8 .mzc-csend .t-ico { filter: drop-shadow(0 3px 4px rgba(0, 0, 0, 0.5)); }

/* FeedbackChips, üveg variant (`glyph3d`): flat pills, the chosen verdict/reason lit lavender */
.fbk-chips.is-3d { margin-top: 2px; }
.fbk-chips.is-3d .fbk-votes { flex-wrap: wrap; gap: 6px; }
.fbk-chips.is-3d .chip {
  display: inline-flex; align-items: center; gap: 5px; min-height: 32px; border: 0; border-radius: 999px;
  font: 600 11.5px/1.2 var(--ff-body); color: var(--text-secondary);
  background: rgba(245, 239, 230, 0.05); box-shadow: inset 0 0 0 1px var(--divider);
}
.fbk-chips.is-3d .chip .t-ico { filter: none; }
.fbk-chips.is-3d .chip[aria-pressed="true"], .fbk-chips.is-3d .chip.brand {
  color: #191614; background: var(--dv-lav); box-shadow: 0 0 10px rgba(171, 159, 210, 0.5);
}
.fbk-chips.is-3d .chip:focus-visible { outline: 2px solid var(--dv-lav); outline-offset: 2px; }

/* the two conversation sheets: ONE floating lavender glass each (U2 rule 15), flat rows inside */
.sheet.glass.mzc-sheet {
  --c: var(--dv-lav);
  position: absolute; left: 10px; right: 10px; bottom: calc(10px + env(safe-area-inset-bottom));
  overflow-x: hidden; overflow-y: auto; border: 0; border-radius: 30px; padding: 4px 18px 18px;
}
.sheet.glass.mzc-sheet .sheet-handle-zone { margin: 0 -18px 4px; }
.sheet.glass.mzc-sheet .sheet-handle { width: 40px; height: 5px; background: rgba(245, 239, 230, 0.22); }
.mzc-sheet .mzc-shbody { gap: 12px; }
.mzc-sheet .mzc-shh { display: flex; align-items: center; gap: 12px; margin-bottom: 2px; }
.mzc-sheet .mzc-sheb {
  font: 600 9.5px/1.3 var(--ff-body); letter-spacing: 1.3px; text-transform: uppercase;
  color: color-mix(in srgb, var(--dv-lav) 80%, var(--text-primary));
}
.mzc-sheet .mzc-shtitle {
  font-size: 21px; font-weight: 600; letter-spacing: -0.6px; line-height: 1.2; color: var(--text-primary);
  overflow: hidden; text-overflow: ellipsis; white-space: nowrap;
}
.mzc-sheet .mzc-shlist { max-height: 320px; overflow-y: auto; gap: 6px; }
.mzc-sheet .mzc-shrow {
  display: flex; align-items: center; gap: 11px; width: 100%; min-width: 0; padding: 10px 12px;
  border: 0; border-radius: 14px; text-align: left; color: var(--text-primary); cursor: pointer;
  background: rgba(245, 239, 230, 0.04); box-shadow: inset 0 0 0 1px var(--divider);
}
.mzc-sheet .mzc-shrow.is-on {
  box-shadow: inset 0 0 0 1px rgba(171, 159, 210, 0.45), 0 0 12px -4px rgba(171, 159, 210, 0.5);
}
.mzc-sheet .mzc-shrow.is-new {
  background: none; box-shadow: none; border: 1.5px dashed rgba(171, 159, 210, 0.45);
}
.mzc-sheet .mzc-shnm {
  display: block; min-width: 0; font-size: 14px; font-weight: 600; color: var(--text-primary);
  overflow: hidden; text-overflow: ellipsis; white-space: nowrap;
}
.mzc-sheet .mzc-shrow.is-warn .mzc-shnm { color: #FFB39C; }
.mzc-sheet .mzc-shsub { font-size: 11px; line-height: 1.35; color: var(--text-muted); }
.mzc-sheet .mzc-shrow .t-ico { filter: drop-shadow(0 3px 4px rgba(0, 0, 0, 0.5)); }
.mzc-sheet .mzc-shmore {
  width: 30px; height: 30px; border-radius: 50%; flex: none; display: grid; place-items: center;
  font-weight: 800; color: var(--text-secondary); background: rgba(245, 239, 230, 0.05);
}
.mzc-sheet .mzc-shinput {
  width: 100%; padding: 11px 13px; border: 0; border-radius: 14px; font-size: 14px;
  color: var(--text-primary); color-scheme: dark;
  background: rgba(245, 239, 230, 0.05); box-shadow: inset 0 0 0 1px var(--divider);
}
.mzc-sheet .mzc-shinput:focus { outline: none; box-shadow: inset 0 0 0 1.5px color-mix(in srgb, var(--dv-lav) 60%, transparent); }
.mzc-sheet .mzc-shpair { display: grid; grid-template-columns: 1fr 1fr; gap: 8px; margin-top: 4px; }
.mzc-sheet .mzc-shconfirm .mzc-shpair { margin-top: 12px; }
.mzc-sheet .mzc-shbtn {
  display: inline-flex; align-items: center; justify-content: center; gap: 6px; min-width: 0; min-height: 44px;
  padding: 8px 14px; border: 0; border-radius: 999px; font: 700 13px/1.2 var(--ff-body); cursor: pointer;
}
.mzc-sheet .mzc-shbtn .t-ico { filter: none; }
.mzc-sheet .mzc-shbtn.is-ghost {
  font-weight: 600; color: var(--text-secondary); background: rgba(245, 239, 230, 0.05); box-shadow: inset 0 0 0 1px var(--divider);
}
.mzc-sheet .mzc-shbtn.is-go { color: #191614; background: var(--dv-lav); box-shadow: 0 0 14px color-mix(in srgb, var(--dv-lav) 55%, transparent); }
.mzc-sheet .mzc-shbtn.is-warn { color: #191614; background: var(--dv-coral); box-shadow: 0 0 14px color-mix(in srgb, var(--dv-coral) 55%, transparent); }
.mzc-sheet .mzc-shbtn:disabled { opacity: 0.45; cursor: default; }
.mzc-sheet .mzc-shconfirm {
  padding: 12px; border-radius: 14px; border: 1.5px dashed rgba(255, 126, 92, 0.45);
  font-size: 13px; line-height: 1.5; color: var(--text-secondary);
}

/* 320–360px: the header row and its five controls shrink rather than overlap (rule 8) */
@media (max-width: 360px) {
  .mzc-u8 .mzc-chathead { gap: 6px; padding-inline: 10px; }
  .mzc-u8 .mzc-hdisc.glass { width: 36px; height: 36px; }
  .mzc-u8 .mzc-horb.uv-well { width: 38px; height: 38px; }
  .mzc-u8 .mzc-horb .t-ico { width: 26px; height: 26px; }
  .mzc-u8 .mzc-hnm { font-size: 15.5px; }
}

/* ── /uveg mezo1 chat ── */

/* ── uveg mezo1 coaching (mezo-me75u.8) ── /mezo/coaching, /mezo/coaching/megfigyelo, /mezo/coaching/kartya ── */

/* Reference: docs/design_2.0/prototypes/uveg-mezo.html #coaching, #megfigyelo, #kartya (owner OK,
   U8). Roots: `.coach-page` + `.coach-hub` / `.coach-obs` / `.coach-card` (MozaikPage className);
   every rule is scoped to them, because `mzp-*`, `mz-w-*` and `nap-mzmsg-*` are shared with
   Diagnózis / Kísérletek / Előrejelzések / NapMezoPage (rule 13) — the coaching pages now wear
   their own `coach-*` classes instead (rule 55). Ranking (bible §3.4): ONE `.glass` per screen —
   the hub's winner (amber), the observer's flagged rules (coral, the state that speaks), the
   card page's card (amber); everything else is flat, empty/loading/error is dashed. */
.coach-page.mz-page { background: transparent; }
.coach-page .mz-page-body { padding: 4px 16px 64px; }
.coach-page .coach-h3 { display: block; padding: 10px 4px 0; margin-bottom: -4px; }
.coach-page .mz-principle {
  margin: 22px 6px 0; padding-top: 12px; border-top: 1px solid var(--divider);
  font-size: 11.5px; font-weight: 400; line-height: 1.5; color: var(--text-muted); text-align: center;
}
.coach-page .coach-state { --c: var(--dv-amber); min-height: 54px; padding: 14px; border-radius: 20px; text-align: center; }
.coach-obs .coach-state { --c: var(--dv-lav); }
.coach-page .coach-state p { font-size: 13px; line-height: 1.5; color: var(--text-secondary); }
.coach-page .coach-grow { flex: 1; min-width: 0; }
.coach-page .coach-well { flex: 0 0 auto; }
.coach-page .coach-chev { flex: 0 0 auto; font-size: 18px; line-height: 1; color: var(--text-muted); }

/* rank plaque (prototype `.rank`) — tinted by the surface's own --c */
.coach-page .coach-rank {
  flex: 0 0 auto; min-width: 34px; height: 26px; padding: 0 7px; border-radius: 9px;
  display: grid; place-items: center; font-size: 12px; font-weight: 700; font-variant-numeric: tabular-nums;
  color: color-mix(in srgb, var(--c, var(--dv-lav)) 85%, var(--text-primary));
  background: color-mix(in srgb, var(--c, var(--dv-lav)) 12%, rgba(245, 239, 230, 0.03));
  box-shadow: inset 0 0 0 1px color-mix(in srgb, var(--c, var(--dv-lav)) 34%, transparent);
}
.coach-page .coach-rank.is-lg { min-width: 40px; height: 30px; font-size: 13.5px; }

/* state chips (prototype `.flatchip`) — flat, their own tone, the 3D icon without a halo */
.coach-page .coach-chips { display: flex; flex-wrap: wrap; gap: 6px; margin-top: 5px; }
.coach-page .coach-chip {
  --cc: var(--text-muted);
  display: inline-flex; align-items: center; gap: 5px; padding: 4px 9px 4px 6px; border-radius: 999px;
  font-size: 11px; font-weight: 600; line-height: 1.2; white-space: nowrap;
  color: color-mix(in srgb, var(--cc) 75%, var(--text-primary));
  background: color-mix(in srgb, var(--cc) 11%, rgba(245, 239, 230, 0.03));
  box-shadow: inset 0 0 0 1px color-mix(in srgb, var(--cc) 30%, transparent);
}
.coach-page .coach-chip.is-raised { --cc: var(--dv-coral); }
.coach-page .coach-chip.is-suppressed, .coach-page .coach-chip.is-winner { --cc: var(--dv-amber); }
.coach-page .coach-chip.is-clear { --cc: var(--dv-sage); }
.coach-page .coach-chip .t-ico { filter: none; }

/* flat evidence / fact cell (rule tile body + the card's facts) */
.coach-page .coach-fact {
  padding: 7px 10px; border-radius: 11px; background: rgba(245, 239, 230, 0.045);
  font-size: 12px; line-height: 1.45; color: var(--text-secondary); overflow-wrap: anywhere;
}
.coach-page .coach-fact .vl { font-variant-numeric: tabular-nums; }

/* ── hub: the gauge hero ── */
.coach-hub .coach-gauge { position: relative; width: 156px; height: 156px; margin: 8px auto 0; display: grid; place-items: center; }
.coach-hub .coach-gauge > svg.mzo-arc { position: absolute; inset: 0; width: 100%; height: 100%; overflow: visible; }
.coach-hub .coach-gauge-ctr { position: relative; display: grid; justify-items: center; text-align: center; }
.coach-hub .coach-gauge-ctr .t-ico {
  margin-bottom: -2px;
  filter: drop-shadow(0 6px 7px rgba(0, 0, 0, 0.55)) drop-shadow(0 0 10px color-mix(in srgb, var(--dv-amber) 40%, transparent));
}
.coach-hub .coach-gauge-ctr b {
  display: block; font-family: var(--ff-display); font-size: 50px; font-weight: 300; letter-spacing: -3px; line-height: 1;
  font-variant-numeric: tabular-nums; color: var(--text-primary);
}
.coach-hub .coach-gauge-ctr small { font-size: 9.5px; font-weight: 600; letter-spacing: 1.3px; text-transform: uppercase; color: var(--text-muted); }
.coach-hub .coach-legend {
  display: flex; justify-content: center; flex-wrap: wrap; gap: 6px 12px; margin-top: 10px;
  font-size: 11.5px; color: var(--text-secondary);
}
.coach-hub .coach-legend span { display: inline-flex; align-items: center; gap: 5px; white-space: nowrap; }
.coach-hub .coach-legend i { width: 8px; height: 8px; border-radius: 50%; background: var(--c); box-shadow: 0 0 6px var(--c); }

/* ── hub: THE one glass — the day's winner ── */
.coach-hub .coach-win.glass { --c: var(--dv-amber); padding: 14px 15px 13px; border-radius: 22px; color: var(--text-primary); }
.coach-hub .coach-win-top { display: flex; align-items: center; gap: 11px; }
.coach-hub .coach-win .coach-well { width: 48px; height: 48px; }
.coach-hub .coach-win-top strong { display: block; font-size: 17px; font-weight: 600; letter-spacing: -0.4px; line-height: 1.25; overflow-wrap: anywhere; }
.coach-hub .coach-win-why { margin-top: 10px; font-size: 13.5px; line-height: 1.5; color: var(--text-secondary); }

/* ── hub: the split as four flat cells, numerals in their state colour ── */
.coach-hub .coach-split.mz-statstrip { display: grid; grid-template-columns: repeat(4, minmax(0, 1fr)); gap: 8px; }
.coach-hub .coach-split .mz-statcell {
  min-width: 0; padding: 10px 4px; border: 0; border-radius: 14px; text-align: center;
  background: rgba(245, 239, 230, 0.05); box-shadow: inset 0 0 0 1px var(--divider);
}
.coach-hub .coach-split .mz-statcell b { font-size: 19px; font-weight: 600; letter-spacing: -0.6px; color: var(--text-primary); }
.coach-hub .coach-split .mz-statcell:nth-child(1) b { color: color-mix(in srgb, var(--dv-coral) 80%, #fff); }
.coach-hub .coach-split .mz-statcell:nth-child(2) b { color: color-mix(in srgb, var(--dv-amber) 80%, #fff); }
.coach-hub .coach-split .mz-statcell:nth-child(3) b { color: color-mix(in srgb, var(--dv-sage) 80%, #fff); }
.coach-hub .coach-split .mz-statcell small { display: block; margin-top: 2px; font-size: 10px; line-height: 1.3; color: var(--text-muted); overflow-wrap: anywhere; }

/* ── hub: the two doors — flat rows with a lit well ── */
.coach-hub .coach-doors { display: grid; gap: 8px; }
.coach-hub .coach-door {
  display: flex; align-items: center; gap: 12px; width: 100%; padding: 11px 14px 11px 11px;
  border: 0; border-radius: 18px; background: rgba(245, 239, 230, 0.035); box-shadow: inset 0 0 0 1px var(--divider);
  font: inherit; text-align: left; color: var(--text-primary); cursor: pointer;
}
.coach-hub .coach-door:focus-visible { outline: 2px solid var(--c); outline-offset: 2px; }
.coach-hub .coach-door .coach-well { width: 42px; height: 42px; }
.coach-hub .coach-door strong { display: block; font-size: 14.5px; font-weight: 600; letter-spacing: -0.2px; }
.coach-hub .coach-door small { display: block; margin-top: 1px; font-size: 11.5px; line-height: 1.35; color: var(--text-secondary); overflow-wrap: anywhere; }

/* ── observer: the day switcher as a flat pill ── */
.coach-obs .mzo-daysw {
  display: inline-flex; align-items: center; justify-content: center; gap: 4px; margin-top: 12px; padding: 4px;
  border-radius: 999px; background: rgba(245, 239, 230, 0.05); box-shadow: inset 0 0 0 1px var(--divider);
}
.coach-obs .mzo-daysw button {
  width: 34px; height: 34px; border: 0; border-radius: 50%; display: grid; place-items: center;
  background: none; box-shadow: none; font-size: 18px; color: var(--text-secondary); cursor: pointer;
}
.coach-obs .mzo-daysw button:disabled { opacity: 0.3; cursor: default; }
.coach-obs .mzo-daysw button:focus-visible { outline: 2px solid var(--dv-lav); outline-offset: 1px; }
.coach-obs .mzo-dlbl { min-width: 110px; }
.coach-obs .mzo-dlbl b { font-size: 13px; font-weight: 600; color: var(--text-primary); }
.coach-obs .mzo-dlbl small { font-size: 10.5px; font-weight: 500; letter-spacing: 0; text-transform: none; color: var(--text-muted); }
.coach-obs .coach-quiet { font-size: 12px; line-height: 1.5; color: var(--text-secondary); text-align: center; }

/* ── observer: rule tiles, ranked by STATE (the order stays the server's) ── */
.coach-obs .coach-rules { display: grid; gap: 8px; }
.coach-obs .mzo-rule { --c: var(--dv-coral); display: block; padding: 11px 12px; border: 0; border-radius: 18px; color: var(--text-primary); }
.coach-obs .mzo-rule:not(.glass) { background: rgba(245, 239, 230, 0.035); box-shadow: inset 0 0 0 1px var(--divider); }
/* flagged = the loud one; restate the glass shadow over the old `.mzo-rule.is-winner` ring (rule 11) */
.coach-obs .mzo-rule.glass {
  border: 0;
  box-shadow:
    0 16px 30px -16px rgba(0, 0, 0, 0.75),
    0 0 26px -6px color-mix(in srgb, var(--c) 30%, transparent),
    inset 0 1px 0 rgba(255, 244, 230, 0.10),
    inset 0 -14px 26px -18px color-mix(in srgb, var(--c) 55%, transparent);
}
.coach-obs .mzo-rule.is-suppressed { --c: var(--dv-amber); }
.coach-obs .mzo-rule.is-suppressed:not(.glass) {
  background: color-mix(in srgb, var(--dv-amber) 7%, rgba(245, 239, 230, 0.03));
  box-shadow: inset 0 0 0 1px color-mix(in srgb, var(--dv-amber) 28%, transparent);
}
.coach-obs .mzo-rule.is-clear { --c: var(--dv-sage); }
.coach-obs .mzo-rule.is-unavailable { --c: var(--text-muted); }
.coach-obs .mzo-rule.is-unavailable:not(.glass) {
  background: none; box-shadow: none;
  border: 1.5px dashed color-mix(in srgb, var(--text-muted) 45%, transparent);
}
/* a winner that has since gone quiet keeps a faint gold edge beside its Nyertes chip */
.coach-obs .mzo-rule.is-winner:not(.glass):not(.is-unavailable) {
  box-shadow: inset 0 0 0 1px color-mix(in srgb, var(--dv-amber) 45%, transparent);
}
.coach-obs .mzo-rule-head {
  display: flex; align-items: center; gap: 10px; width: 100%; padding: 0; border: 0;
  background: none; font: inherit; text-align: left; color: inherit;
}
.coach-obs button.mzo-rule-head { cursor: pointer; }
.coach-obs button.mzo-rule-head:focus-visible { outline: 2px solid var(--c); outline-offset: 3px; border-radius: 12px; }
.coach-obs .mzo-rule-nm { display: block; font-size: 14px; font-weight: 600; line-height: 1.3; color: var(--text-primary); overflow-wrap: anywhere; }
.coach-obs .mzo-rule.is-clear .mzo-rule-nm, .coach-obs .mzo-rule.is-unavailable .mzo-rule-nm { font-weight: 500; color: var(--text-secondary); }
.coach-obs .mzo-rule.is-clear .mzo-rule-ic, .coach-obs .mzo-rule.is-unavailable .mzo-rule-ic { filter: grayscale(0.4) brightness(0.8); }
.coach-obs .mzo-rule .coach-chev { font-size: 13px; }
.coach-obs .mzo-rule.open .coach-chev { transform: rotate(180deg); }
