.kr9-page .kr9-inline { border: 0; background: none; padding: 4px 0; cursor: pointer; font-family: inherit; font-size: inherit; font-weight: 600; color: var(--dv-lav); }
.kr9-page .kr9-story-target { scroll-margin-top: 72px; border-radius: 22px; }
.kr9-page .kr9-story-target:focus-visible { outline: 2px solid var(--dv-lav); outline-offset: 2px; }
.kr9-page .kr9-post .tf-name { display: block; }
.kr9-page .kr9-post .kr9-self { font-size: 11px; font-weight: 700; color: color-mix(in srgb, var(--dv-lav) 70%, #fff); }
.kr9-page .kr9-post.is-outcome { box-shadow: inset 0 0 0 1px color-mix(in srgb, var(--dv-amber) 30%, transparent), 0 8px 18px -14px rgba(0, 0, 0, 0.6); }
.kr9-page .kr9-kind {
  flex: 0 0 auto; margin-left: auto; padding: 4px 9px; border-radius: 999px; font-size: 9.5px; font-weight: 700; letter-spacing: 0.4px;
  color: color-mix(in srgb, var(--c) 80%, #fff); background: color-mix(in srgb, var(--c) 14%, transparent);
  box-shadow: inset 0 0 0 1px color-mix(in srgb, var(--c) 32%, transparent);
}
.kr9-page .kr9-ptext { white-space: pre-wrap; }
.kr9-page .kr9-post > .tf-acts { margin-top: 8px; padding-top: 3px; border-top: 1px solid var(--divider); }
.kr9-page .kr9-post .tf-acts button { border: 0; background: transparent; cursor: pointer; font-family: inherit; }
.kr9-page .kr9-thread { margin-top: 6px; }
.kr9-page .kr9-ctx { margin: 8px 0 0; font-size: 11px; color: var(--text-muted); }
.kr9-page .kr9-link {
  display: inline-flex; align-items: center; min-height: 32px; padding: 4px 0; border: 0; background: none; cursor: pointer;
  text-decoration: none; font: 600 11.5px/1.2 var(--ff-body); color: color-mix(in srgb, var(--c, var(--dv-lav)) 78%, var(--text-primary));
}
.kr9-page .kr9-fb { margin-top: 6px; }

/* the shared comment / reply-thread pieces, dark inside these roots (their konzílium use is not touched) */
.kr9-page .kr-social-comment { gap: 8px; margin-top: 9px; }
.kr9-page .kr-social-comment > div {
  padding: 9px 11px; border-radius: 4px 14px 14px 14px;
  background: rgba(245, 239, 230, 0.05); box-shadow: inset 0 0 0 1px var(--divider);
}
.kr9-page .kr-social-comment.is-mezo > div { background: color-mix(in srgb, var(--dv-amber) 8%, transparent); box-shadow: inset 0 0 0 1px color-mix(in srgb, var(--dv-amber) 28%, transparent); }
.kr9-page .kr-social-comment strong { font-size: 12px; font-weight: 600; color: var(--text-primary); }
.kr9-page .kr-social-comment strong small { font-size: 10px; font-weight: 600; color: color-mix(in srgb, var(--dv-lav) 70%, #fff); margin-left: 4px; }
.kr9-page .kr-social-comment p { margin: 3px 0; font-size: 12px; line-height: 1.5; color: var(--text-secondary); }
.kr9-page .kr-social-comment small, .kr9-page .kr-peer-context, .kr9-page .kr-reply-status { font-size: 10px; color: var(--text-muted); }
.kr9-page .kr-self-avatar {
  width: 28px; height: 28px; display: grid; place-items: center; flex: 0 0 auto; border-radius: 50%;
  background: color-mix(in srgb, var(--dv-lav) 20%, transparent); color: color-mix(in srgb, var(--dv-lav) 75%, #fff); font-size: 10px; font-weight: 700;
}
.kr9-page .kr-quick-reply {
  display: flex; align-items: center; gap: 9px; width: 100%; margin-top: 9px; padding: 8px 12px; border: 0; border-radius: 999px; cursor: pointer;
  background: rgba(245, 239, 230, 0.04); box-shadow: inset 0 0 0 1px var(--divider); font: 400 12px/1.3 var(--ff-body); color: var(--text-muted); text-align: left;
}
.kr9-page .kr-quick-reply .kr-self-avatar { width: 26px; height: 26px; }
.kr9-page .kr-reply-composer { border-top: 1px solid var(--divider); }
.kr9-page .kr-reply-composer label, .kr9-page .kr-reply-composer small { color: var(--text-muted); }
.kr9-page .kr-reply-composer textarea {
  background: rgba(25, 22, 20, 0.45); border: 0; box-shadow: inset 0 0 0 1px var(--divider); color: var(--text-primary);
}
.kr9-page .kr-reply-composer textarea:focus-visible { outline: 2px solid color-mix(in srgb, var(--dv-lav) 70%, transparent); outline-offset: 1px; }
.kr9-page .kr-reply-composer .cta {
  border: 0; border-radius: 999px; cursor: pointer; font-weight: 650; color: var(--text-inverse); background: var(--dv-lav);
  box-shadow: 0 0 12px color-mix(in srgb, var(--dv-lav) 45%, transparent);
}
.kr9-page .kr-reply-saved { color: #a9d4b3; }
.kr9-page .kr-reply-error { color: #FFB39C; }
.kr9-page .kr-reply-reward { color: #a9d4b3; background: color-mix(in srgb, var(--dv-sage) 12%, transparent); box-shadow: inset 0 0 0 1px color-mix(in srgb, var(--dv-sage) 30%, transparent); animation: none; }
.kr9-page .kr-retry { color: var(--text-secondary); }

/* dimension page: hero figure, gauge, flat upright portrait, glass claim cases with flat-lit chips */
.kr9-page .kr9-rhero .kr9-rfig { margin: 0 auto; box-shadow: inset 0 1px 0 rgba(255, 244, 230, 0.08), 0 0 26px -4px color-mix(in srgb, var(--c) 55%, transparent); }
.kr9-page .kr9-chaptermark { display: grid; place-items: center; width: 92px; height: 92px; border-radius: 50%; background: radial-gradient(circle at 35% 28%, #3A332D, color-mix(in srgb, var(--c) 14%, #1E1B18)); }
.kr9-page .kr9-gauges { padding-bottom: 20px; }
.kr9-page .kr9-portrait {
  margin: 8px 16px 0; padding: 14px 15px; border-radius: 20px; white-space: pre-wrap; overflow-wrap: anywhere;
  background: rgba(245, 239, 230, 0.035); box-shadow: inset 0 0 0 1px var(--divider);
  font-size: 13.5px; line-height: 1.6; color: var(--text-primary);
}
.kr9-page .kr9-claims { gap: 10px; }
.kr9-page .kr9-claim .kr9-ctext { font-size: 14px; font-weight: 600; line-height: 1.42; }
.kr9-page .kr9-claim.kr9-sensitive { outline: 1px dashed color-mix(in srgb, var(--dv-lav) 55%, transparent); outline-offset: 3px; }
.kr9-page .kr9-retired { opacity: 0.6; }
.kr9-page .kr9-foot { display: block; margin-top: 9px; font-size: 10.5px; line-height: 1.45; color: var(--text-muted); }
.kr9-page .kr9-chips, .kr9-rolad .kr9-chips { display: flex; flex-wrap: wrap; gap: 6px; margin-top: 11px; }
.kr9-page .kr9-chip, .kr9-rolad .kr9-chip {
  display: inline-flex; align-items: center; gap: 6px; min-height: 36px; padding: 6px 12px 6px 8px; border: 0; border-radius: 999px; cursor: pointer;
  font: 600 12px/1.2 var(--ff-body); color: color-mix(in srgb, var(--c) 78%, #fff);
  background: color-mix(in srgb, var(--c) 14%, transparent); box-shadow: inset 0 0 0 1px color-mix(in srgb, var(--c) 38%, transparent);
}
.kr9-page .kr9-chip.is-main, .kr9-rolad .kr9-chip.is-main { color: var(--text-inverse); background: var(--c); box-shadow: 0 0 12px color-mix(in srgb, var(--c) 50%, transparent); }
.kr9-page .kr9-chip:disabled, .kr9-rolad .kr9-chip:disabled { opacity: 0.55; cursor: default; }
.kr9-page .kr9-chip .t-ico, .kr9-rolad .kr9-chip .t-ico { width: 17px; height: 17px; }
.kr9-rolad .kr9-chip:focus-visible { outline: 2px solid var(--c); outline-offset: 2px; }
.kr9-page .kr9-thanks { margin-top: 11px; }
.kr9-page .kr9-links { display: flex; flex-wrap: wrap; gap: 4px 16px; margin-top: 11px; padding-top: 8px; border-top: 1px solid var(--divider); }
.kr9-page .kr9-links button {
  min-height: 32px; padding: 4px 0; border: 0; background: none; cursor: pointer;
  font: 600 11.5px/1.2 var(--ff-body); color: color-mix(in srgb, var(--c) 75%, var(--text-primary));
}
.kr9-page .kr9-door { margin-top: 14px; }
.kr9-page .kr9-principle { margin: 20px 22px 0; padding-top: 12px; border-top: 1px solid var(--divider); font-size: 11px; line-height: 1.5; color: var(--text-muted); text-align: center; }

/* Rólad: the csapatfal heading with the living Boop on the right */
.kr9-rolad .kr9-rhead { display: flex; align-items: flex-end; justify-content: space-between; gap: 12px; }
.kr9-rolad .kr9-rhead > svg, .kr9-rolad .kr9-rhead > span { flex: 0 0 auto; filter: drop-shadow(0 8px 10px rgba(0, 0, 0, 0.5)) drop-shadow(0 0 14px color-mix(in srgb, var(--dv-rose) 45%, transparent)); }
.kr9-rolad .kr9-rlinks { padding-top: 4px; }

/* Rólad — a közös kép (U9b, mezo-zpxv7; prototype `uveg-mezo-teljes-u9.js` rolad()). Ranking (bible §3):
   the quote, the open candidates, the fact cases, the timeline card, the note and the doors are glass; the
   timeline's rows, a kept graph node and the quote's chips are flat; a snoozed / rejected decision is dashed. */
.kr9-rolad .kr9-week { flex-wrap: wrap; }
.kr9-rolad .kr9-week .tf-strip-text { font-weight: 500; line-height: 1.45; }
/* The text stays alongside the icon at its natural width; the link is forced onto its own row
   below via a 100% flex-basis — plain `flex-wrap: wrap` alone lets the wrappable flex-shrink
   text absorb the squeeze instead of the link ever moving down (mezo-zpxv7 runtime fix). */
.kr9-rolad .kr9-weeklink { flex: 1 0 100%; margin: 2px 0 0 34px; font-size: 11.5px; font-weight: 600; color: color-mix(in srgb, var(--dv-rose) 80%, #fff); text-decoration: none; white-space: nowrap; }
.kr9-rolad .kr9-quote { margin: 9px 16px 0; padding: 15px 16px; border-radius: 20px; }
.kr9-rolad .kr9-quote > p { margin: 0; font-family: var(--ff-serif); font-style: italic; font-size: 16.5px; line-height: 1.45; color: var(--text-primary); overflow-wrap: anywhere; }
.kr9-rolad .kr9-quote figcaption { display: block; margin-top: 7px; font-size: 10.5px; line-height: 1.45; color: var(--text-muted); }
.kr9-rolad .kr9-quote figcaption b { font-weight: 700; color: color-mix(in srgb, var(--c) 80%, #fff); }
.kr9-rolad .kr9-quote .kr9-qthanks { margin: 0; align-self: center; }
/* mezo-plbev item 5: `.kr9-page .kr9-thread` (descendant) never matches the reply-thread wrapper,
   which carries BOTH classes on the same element — this page-owned rule does the actual work. */
.kr9-rolad .kr9-quote-thread { margin-top: 10px; }
.kr9-rolad .kr9-qempty, .kr9-rolad .kr9-note { margin-top: 10px; }
.kr9-rolad .kr9-note { margin-top: 18px; }
.kr9-rolad .kr9-kept .tf-after { margin-bottom: 0; }
.kr9-rolad .kr9-gone { display: flex; gap: 11px; align-items: center; padding: 11px 14px; border-radius: 18px; border: 1.5px dashed rgba(142, 134, 163, 0.45); color: var(--text-secondary); }
.kr9-rolad .kr9-gone .t-ico { flex: 0 0 auto; width: 22px; height: 22px; opacity: 0.75; }
.kr9-rolad .kr9-gone b { display: block; font-size: 12.5px; font-weight: 600; line-height: 1.35; color: var(--text-secondary); overflow-wrap: anywhere; }
.kr9-rolad .kr9-gone small { display: block; margin-top: 2px; font-size: 11px; color: var(--text-muted); }
.kr9-rolad .kr9-quiet { margin: 0; padding: 2px 18px 0; font-size: 11.5px; line-height: 1.45; color: var(--text-muted); }
/* mezo-plbev fix round 1: `.kr9-page .kr9-link` never matches inside `.kr9-rolad` (no `.kr9-page`
   ancestor here) — this page-owned rule mirrors its declaration for the inbox's quiet retry. */
.kr9-rolad .kr9-retry {
  display: inline-flex; align-items: center; min-height: 32px; padding: 4px 0; border: 0; background: none; cursor: pointer;
  text-decoration: none; font: 600 11.5px/1.2 var(--ff-body); color: color-mix(in srgb, var(--c, var(--dv-lav)) 78%, var(--text-primary));
}
.kr9-rolad .kr9-factdoor .tf-cmain { align-items: center; }
.kr9-rolad .kr9-life { margin: 0; padding-top: 6px; padding-bottom: 6px; list-style: none; }
.kr9-rolad .kr9-lifer { display: flex; gap: 12px; align-items: flex-start; padding: 11px 2px; border-bottom: 1px solid var(--divider); }
.kr9-rolad .kr9-lifer:last-child { border-bottom: 0; }
.kr9-rolad .kr9-lifer u { flex: 0 0 auto; width: 10px; height: 10px; margin-top: 4px; border-radius: 50%; text-decoration: none;
  background: var(--dv-amber); box-shadow: 0 0 8px color-mix(in srgb, var(--dv-amber) 60%, transparent); }
.kr9-rolad .kr9-lifer.is-season u { background: var(--dv-sky); box-shadow: 0 0 8px color-mix(in srgb, var(--dv-sky) 60%, transparent); }
.kr9-rolad .kr9-lifetx { flex: 1; min-width: 0; }
.kr9-rolad .kr9-lifer b { display: block; font-size: 13.5px; font-weight: 600; line-height: 1.35; color: var(--text-primary); overflow-wrap: anywhere; }
.kr9-rolad .kr9-lifer small { display: block; margin-top: 2px; font-size: 11px; line-height: 1.4; color: var(--text-secondary); }
.kr9-rolad .kr9-lifer em { flex: 0 0 auto; margin-left: auto; font-style: normal; font-size: 10.5px; color: var(--text-muted); font-variant-numeric: tabular-nums; }

@keyframes kr9-in { from { opacity: 0; transform: translateY(10px); } to { opacity: 1; transform: none; } }
@keyframes kr9-spin { to { transform: rotate(270deg); } }
@media (prefers-reduced-motion: no-preference) {
  .kr9-page .rise { animation: kr9-in 0.5s var(--uv-ease, ease-out) both; animation-delay: var(--d, 0ms); }
  .kr9-page .kr9-bootring svg { animation: kr9-spin 2.4s linear infinite; }
}
/* 320px: a szekció-fej hint-je tördelhet (a „N témakör · mind pontosítható” 12px-lel kilógott) */
.kr9-page .tf-sec, .kr9-rolad .tf-sec { flex-wrap: wrap; row-gap: 4px; }
.kr9-page .tf-sec .tf-hint, .kr9-rolad .tf-sec .tf-hint { white-space: normal; min-width: 0; }
/* ── /uveg mezo2 karakter ── */

/* ── uveg mezo2 konzilium (mezo-me75u.9) ── /mezo/karakter/konzilium (+?id=, overview + conversation view, archive sheet) ── */

/* Page root `.kz-page` (KonziliumPage); the archive sheet portals outside it, so its content
   owns `.kz-arc`. Material from the tf-* kit (boop-world.css): tf-dhead, tf-sec, tf-rows,
   tf-case/tf-flatc, tf-st, tf-dash. Rank (bible §3): the three outcome cells are the ONE loud
   glass thing; rounds + collapsed threads flat; an opened thread and Mezo's rulings glass. */
.kz-page .tf-av > * { width: 80%; height: 80%; }
.kz-page .tf-dash .t-ico { flex: 0 0 auto; }
.kz-lede { margin: 0; padding: 2px 18px 4px; font-size: 12.5px; line-height: 1.5; color: var(--text-secondary); }

/* stepper ‹ [date ⌄] › */
.kz-step { display: flex; align-items: center; justify-content: center; gap: 8px; padding: 2px 16px 10px; }
.kz-step .kz-navbtn { width: 38px; height: 38px; display: grid; place-items: center; padding: 0; border: 0; border-radius: 50%;
  font-size: 17px; color: var(--text-secondary); background: rgba(245, 239, 230, 0.05); box-shadow: inset 0 0 0 1px var(--divider); }
.kz-step .kz-navbtn:disabled { opacity: 0.35; }
.kz-step .kz-date { min-height: 38px; padding: 0 16px; border: 0; border-radius: 999px; font-size: 12.5px; font-weight: 600; color: var(--text-primary); }
.kz-step .kz-datecv { margin-left: 6px; color: var(--text-muted); }

/* Áttekintés / Beszélgetés */
.kz-seg { --c: var(--dv-amber); display: flex; margin: 4px 16px 8px; padding: 3px; border-radius: 999px;
  background: rgba(245, 239, 230, 0.05); box-shadow: inset 0 0 0 1px var(--divider); }
.kz-seg button { flex: 1; min-height: 36px; padding: 0; border: 0; border-radius: 999px; background: none;
  font-size: 12.5px; font-weight: 600; color: var(--text-secondary); text-align: center; }
.kz-seg button.on { color: var(--canvas); background: var(--c); box-shadow: 0 0 12px color-mix(in srgb, var(--c) 45%, transparent); }

/* „Mi változott a dossziédban” — the loud element */
.kz-outcells { display: grid; grid-template-columns: repeat(3, minmax(0, 1fr)); gap: 8px; padding: 0 16px; }
.kz-outcells .kz-outcell { padding: 15px 6px 13px; border-radius: 20px; text-align: center; }
.kz-outcell b { display: block; font-size: 34px; font-weight: 300; letter-spacing: -1.4px; line-height: 1;
  color: color-mix(in srgb, var(--c) 72%, #fff); font-variant-numeric: tabular-nums; }
.kz-outcell small { display: block; margin-top: 7px; font-size: 8.5px; font-weight: 600; letter-spacing: 1px; text-transform: uppercase; color: var(--text-muted); }
.kz-extra { margin: 8px 16px 0; padding: 10px 13px; border-radius: 16px; font-size: 12px; line-height: 1.45; color: var(--text-secondary);
  background: rgba(245, 239, 230, 0.035); box-shadow: inset 0 0 0 1px rgba(245, 239, 230, 0.10); }

/* „Hogyan zajlott” — 4 flat round cards */
.kz-rounds .tf-rows { grid-template-columns: repeat(2, minmax(0, 1fr)); }
.kz-page .kz-round { padding: 12px 13px 13px; }
.kz-page .kz-round .tf-crow { margin-bottom: 7px; }
.kz-rval { display: block; font-size: 14.5px; font-weight: 600; letter-spacing: -0.25px; line-height: 1.3; color: var(--text-primary); font-variant-numeric: tabular-nums; }
.kz-page .kz-round.hot { box-shadow: inset 0 0 0 1px color-mix(in srgb, var(--dv-sky) 50%, transparent), 0 0 18px -6px color-mix(in srgb, var(--dv-sky) 55%, transparent); }
.kz-page .kz-round.hot .kz-rval { color: color-mix(in srgb, var(--dv-sky) 75%, #fff); }

/* threads — flat when collapsed, glass when open */
.kz-page .kz-thread { padding: 12px 13px 13px; }
.kz-thhead { display: flex; align-items: center; gap: 10px; width: 100%; min-height: 44px; padding: 0; border: 0; background: none;
  font: inherit; color: inherit; text-align: left; }
.kz-faces { display: flex; flex: 0 0 auto; padding-right: 8px; }
.kz-faces .kz-face { margin-right: -8px; box-shadow: 0 0 0 1.5px var(--canvas); }
.kz-page .kz-thread .tf-ctitle { font-size: 14.5px; }
.kz-deb { font-weight: 600; color: color-mix(in srgb, var(--dv-sky) 78%, #fff); }
.kz-throws { margin-top: 9px; }
.kz-throw { display: flex; align-items: baseline; gap: 9px; padding: 8px 2px 2px; border-top: 1px solid var(--divider); font-size: 12px; line-height: 1.45; color: var(--text-primary); }
.kz-throw .tf-st { flex: 0 0 auto; padding: 3px 8px; font-size: 7.5px; letter-spacing: 0.8px; }
.kz-thtx.dim { color: var(--text-muted); }
.kz-oc.acc { --s: var(--dv-sage); }
.kz-oc.acc.ret { --s: var(--dv-amber); }
.kz-oc.rej, .kz-oc.non { --s: #8E86A3; }
.kz-oc.non { opacity: 0.75; }
.kz-thbody { margin-top: 8px; }
.kz-thitem + .kz-thitem { margin-top: 14px; padding-top: 6px; border-top: 1px solid var(--divider); }

/* the chain / turns — flat comment panels in the character's accent (tcmt idiom) */
.kz-cmt { margin: 8px 0 0; padding: 11px 12px 10px; border-radius: 16px; background: rgba(245, 239, 230, 0.035);
  box-shadow: inset 0 0 0 1px rgba(245, 239, 230, 0.10), inset 3px 0 0 color-mix(in srgb, var(--c) 55%, transparent), 0 8px 18px -14px rgba(0, 0, 0, 0.6); }
.kz-cmth, .kz-rulinghd { display: flex; flex-wrap: wrap; align-items: center; gap: 8px; margin-bottom: 6px; }
.kz-who { font-size: 13px; font-weight: 600; letter-spacing: -0.2px; color: var(--text-primary); }
.kz-said { margin: 0; font-size: 12.5px; line-height: 1.55; color: var(--text-secondary); }
.kz-chip { --k: #8E86A3; display: inline-block; padding: 2px 8px; border-radius: 999px; font-size: 8px; font-weight: 700; letter-spacing: 0.9px;
  text-transform: uppercase; background: color-mix(in srgb, var(--k) 18%, transparent); color: color-mix(in srgb, var(--k) 82%, #fff);
  box-shadow: inset 0 0 0 1px color-mix(in srgb, var(--k) 35%, transparent); }
.kz-chip.sup, .kz-chip.acc { --k: var(--dv-sage); }
.kz-chip.cha { --k: var(--dv-rose); }
.kz-chip.nua { --k: var(--dv-sky); }
.kz-reply { display: flex; align-items: center; width: 100%; min-height: 40px; margin-top: 10px; padding: 8px 14px; border: 0; border-radius: 999px;
  font-size: 11.5px; font-weight: 600; text-align: left; color: color-mix(in srgb, var(--dv-lav) 78%, var(--text-primary));
  background: color-mix(in srgb, var(--dv-lav) 12%, transparent); box-shadow: inset 0 0 0 1px color-mix(in srgb, var(--dv-lav) 32%, transparent); }

/* conversation view */
.kz-cvsec h2 .kz-rn { font-weight: 400; color: var(--text-muted); }
.kz-cvsec.hot h2 .kz-rn { color: color-mix(in srgb, var(--dv-sky) 78%, #fff); }
.kz-cvlist { padding: 0 16px; }
.kz-cvlist > .kz-cmt:first-child { margin-top: 0; }
.kz-cvcard + .kz-cvcard { margin-top: 16px; }
.kz-cvquote { margin: 0 2px 2px; font-family: var(--ff-serif); font-style: italic; font-size: 13.5px; line-height: 1.4; color: var(--text-secondary); }
.kz-cvempty { margin: 0 16px; padding: 12px 13px; border-radius: 18px; border: 1.5px dashed rgba(142, 134, 163, 0.45);
  font-size: 12px; line-height: 1.45; color: var(--text-secondary); }
.kz-page .kz-ruling { padding: 13px 14px; border-radius: 20px; }
.kz-ruling + .kz-ruling { margin-top: 10px; }
.kz-ruling .kz-said, .kz-turn.ruling .kz-said { color: var(--text-primary); }

/* legacy prose fallback */
.kz-phase { padding: 22px 18px 4px; font-size: 9.5px; font-weight: 600; letter-spacing: 1.2px; text-transform: uppercase; color: var(--text-muted); }
.kz-turns { padding: 0 16px; }
.kz-page .kz-turn.ruling { margin: 10px 16px 0; padding: 13px 14px; border-radius: 20px; }
.kz-userline { display: block; margin: 6px 0 2px; padding: 6px 10px; border-radius: 12px;
  background: color-mix(in srgb, var(--dv-amber) 12%, transparent); box-shadow: inset 3px 0 0 var(--dv-amber); }
.kz-ul { display: block; font-size: 8.5px; font-weight: 700; letter-spacing: 1px; text-transform: uppercase; color: color-mix(in srgb, var(--dv-amber) 82%, #fff); }
.kz-ut { color: var(--text-primary); }

/* empty / not-found / honesty */
.kz-body > .kz-arcbtn { display: block; margin: 0 16px; min-height: 40px; padding: 0 16px; border: 0; border-radius: 999px;
  font-size: 12.5px; font-weight: 600; color: var(--text-primary); background: rgba(245, 239, 230, 0.05); box-shadow: inset 0 0 0 1px var(--divider); }
.kz-page .kz-honest { margin-top: 22px; }

/* archive sheet (plain Sheet primitive; flat rows, the open council lit) */
.kz-arc { --c: var(--dv-amber); }
.kz-archd { display: flex; align-items: center; gap: 8px; padding: 6px 4px 12px; font-size: 17px; font-weight: 600; letter-spacing: -0.4px; color: var(--text-primary); }
.kz-arccnt { padding: 2px 8px; border-radius: 999px; font-size: 10px; font-weight: 700; color: var(--text-secondary); background: rgba(245, 239, 230, 0.07); }
.kz-arcscroll { max-height: 62vh; overflow-y: auto; overscroll-behavior: contain; }
.kz-arcyr { padding: 16px 4px 2px; font-size: 20px; font-weight: 300; letter-spacing: -0.6px; color: var(--text-primary); }
.kz-arcmh { padding: 12px 4px 6px; font-size: 9.5px; font-weight: 600; letter-spacing: 1.2px; text-transform: uppercase; color: var(--text-muted); }
.kz-arcrow { display: flex; align-items: center; gap: 10px; width: 100%; min-height: 48px; margin-bottom: 6px; padding: 10px 12px; border: 0; border-radius: 16px;
  font: inherit; text-align: left; color: var(--text-primary); background: rgba(245, 239, 230, 0.035); box-shadow: inset 0 0 0 1px rgba(245, 239, 230, 0.10); }
.kz-arcrow.on { background: color-mix(in srgb, var(--c) 12%, transparent);
  box-shadow: inset 0 0 0 1px color-mix(in srgb, var(--c) 50%, transparent), 0 0 16px -6px color-mix(in srgb, var(--c) 55%, transparent); }
.kz-arcday { flex: 0 0 auto; font-size: 13px; font-weight: 600; }
.kz-arcout { flex: 1 1 auto; min-width: 0; font-size: 11px; line-height: 1.35; color: var(--text-secondary); }
.kz-arcout-other { color: var(--text-muted); }
.kz-kbadge { --k: #8E86A3; flex: 0 0 auto; margin-left: auto; padding: 3px 8px; border-radius: 999px; font-size: 7.5px; font-weight: 700; letter-spacing: 0.8px;
  background: color-mix(in srgb, var(--k) 18%, transparent); color: color-mix(in srgb, var(--k) 82%, #fff); }
.kz-kbadge.daily { --k: var(--dv-sage); }
.kz-kbadge.weekly { --k: var(--dv-lav); }
.kz-kbadge.monthly { --k: var(--dv-amber); }
.kz-kbadge.bootstrap { --k: var(--dv-sky); }

@media (prefers-reduced-motion: no-preference) {
  .kz-seg button, .kz-arcrow { transition: background-color 0.2s ease, box-shadow 0.2s ease, color 0.2s ease; }
}

/* ── /uveg mezo2 konzilium ── */

/* ── uveg mezo2 gepterem (mezo-me75u.9) ── /mezo/karakter/gepterem (+/osszes, /futasok, /futas/:id, /adatforrasok, /adatforrasok/kor/:n, /detektorok) ── */

/* The csapatfal D5 „dev-ajtó”: a modest slate page in the `tf-*` kit (boop-world.css) — the
   csapatfal's head, cases, lists and dashes; only what the kit lacks is written here, from
   prototypes/src/uveg-mezo-teljes-u9.css `m9-*`. Every rule is scoped to `.gtm-page` (rule 60). */
.gtm-page { padding-bottom: 28px; }
.gtm-page .gtm-lede { margin: 0; padding: 0 18px 10px; font-size: 12.5px; line-height: 1.5; color: var(--text-secondary); }
.gtm-page .gtm-lede b { color: var(--text-primary); font-weight: 600; }
.gtm-page .gtm-principle { margin: 20px 22px 0; padding-top: 12px; border-top: 1px solid var(--divider);
  font-size: 11px; line-height: 1.5; color: var(--text-muted); text-align: center; }
.gtm-page .tf-dash .t-ico { width: 24px; height: 24px; }
.gtm-page .tf-rows > .tf-dash { margin: 0; }
.gtm-page .tf-case .tf-cmain .tf-chev { margin-left: auto; }
.gtm-page .gtm-det { display: inline-block; padding: 3px 8px; border-radius: 7px; overflow-wrap: anywhere;
  font-family: ui-monospace, 'SF Mono', Menlo, monospace; font-size: 10.5px; line-height: 1.3; color: var(--text-secondary);
  background: rgba(245, 239, 230, 0.05); box-shadow: inset 0 0 0 1px var(--divider); }

/* Gépterem hub: lede, dashed intro, 7 slate glass doors */
.gtm-hub .gtm-intro { margin: 4px 16px 14px; }
.gtm-hub .gtm-doors .tf-ctitle { font-size: 14.5px; }
@media (hover: hover) and (prefers-reduced-motion: no-preference) {
  .gtm-hub .gtm-door { transition: transform 0.2s ease; }
  .gtm-hub .gtm-door:hover { transform: translateY(-2px); }
}

/* Összes funkció: 2-col grid of glass tiles, one wash accent each */
.gtm-menu-page .gtm-menu { display: grid; grid-template-columns: repeat(2, minmax(0, 1fr)); gap: 11px; padding: 0 16px; }
.gtm-menu-page .gtm-tile { display: flex; flex-direction: column; align-items: center; gap: 8px; min-width: 0;
  padding: 18px 10px 14px; border-radius: 20px; text-align: center; text-decoration: none; color: var(--text-primary); }
.gtm-menu-page .gtm-tile .t-ico { width: 52px; height: 52px; }
.gtm-menu-page .gtm-tile strong { font-size: 13.5px; font-weight: 600; line-height: 1.3; overflow-wrap: anywhere; }
.gtm-menu-page .gtm-tile > span { font-size: 10.5px; line-height: 1.4; color: var(--text-secondary); }
.gtm-menu-page .gtm-tile:active { transform: scale(0.97); }
@media (hover: hover) and (prefers-reduced-motion: no-preference) {
  .gtm-menu-page .gtm-tile { transition: transform 0.2s ease; }
  .gtm-menu-page .gtm-tile .t-ico { transition: transform 0.25s ease; }
  .gtm-menu-page .gtm-tile:hover { transform: translateY(-3px); }
  .gtm-menu-page .gtm-tile:hover .t-ico { transform: rotate(-7deg) scale(1.07); }
}

/* Futások: flat steppers around a glass week pill, the jump menu, day headers, ranked runs */
.gtm-futasok .gtm-week { position: relative; display: flex; align-items: center; gap: 8px; padding: 2px 16px 4px; }
.gtm-futasok .gtm-wstep { width: 36px; height: 36px; flex: 0 0 auto; display: grid; place-items: center; border-radius: 50%;
  font-size: 17px; color: var(--text-secondary); background: rgba(245, 239, 230, 0.05); box-shadow: inset 0 0 0 1px var(--divider); }
.gtm-futasok .gtm-wstep:disabled { opacity: 0.35; cursor: default; }
.gtm-futasok .gtm-wlwrap { flex: 1; min-width: 0; }
.gtm-futasok .gtm-wl { display: block; width: 100%; padding: 6px 10px; border-radius: 16px; text-align: center; color: var(--text-primary); }
.gtm-futasok .gtm-wl strong { display: block; font-size: 13.5px; font-weight: 600; }
.gtm-futasok .gtm-wl small { display: block; font-size: 10.5px; color: var(--text-muted); }
.gtm-futasok .gtm-wmenu { position: absolute; left: 16px; right: 16px; top: 46px; z-index: 12;
  display: flex; flex-wrap: wrap; gap: 6px; padding: 10px; border-radius: 18px; }
.gtm-futasok .gtm-wchip { padding: 6px 10px; border-radius: 999px; font-size: 11px; font-weight: 600; color: var(--text-secondary);
  background: rgba(245, 239, 230, 0.05); box-shadow: inset 0 0 0 1px var(--divider); }
.gtm-futasok .gtm-wchip.on { color: #191614; background: #B7ADCC; }
.gtm-futasok .gtm-day { display: flex; align-items: baseline; gap: 8px; padding: 14px 20px 6px;
  font-size: 9.5px; font-weight: 600; letter-spacing: 1.3px; color: var(--text-muted); text-transform: uppercase; }
.gtm-futasok .gtm-day b { color: var(--text-secondary); }
.gtm-futasok .gtm-day.today b { color: var(--dv-lav); }
.gtm-futasok .gtm-free { padding: 10px 13px; font-size: 11.5px; }
.gtm-futasok .gtm-free .t-ico { width: 20px; height: 20px; }
.gtm-futasok .gtm-future { opacity: 0.7; }
.gtm-futasok .gtm-run .tf-crow em .t-ico { width: 18px; height: 18px; }
.gtm-futasok .gtm-run.gtm-incomplete { box-shadow: inset 0 0 0 1px color-mix(in srgb, var(--dv-amber) 32%, transparent),
  inset 3px 0 0 color-mix(in srgb, var(--dv-amber) 60%, transparent); }
.gtm-futasok .gtm-rare .gtm-rare-empty { padding: 0 2px; }

/* Egy futás: flow cells, sage notes, the jellánc, op chips, CTA, the one glass AI-napló row */
.gtm-run-page .gtm-flow { display: flex; align-items: center; gap: 6px; padding: 4px 16px 2px; }
.gtm-run-page .gtm-flow-cell { flex: 1; min-width: 0; padding: 11px 4px 9px; border-radius: 16px; text-align: center;
  background: rgba(245, 239, 230, 0.04); box-shadow: inset 0 0 0 1px var(--divider); }
.gtm-run-page .gtm-flow-cell b { display: block; font-size: 30px; font-weight: 300; letter-spacing: -1.2px; line-height: 1.05; color: #CFC8E3; }
.gtm-run-page .gtm-flow-cell small { display: block; font-size: 8px; font-weight: 700; letter-spacing: 1px; color: var(--text-muted); text-transform: uppercase; }
.gtm-run-page .gtm-flow-arrow { font-style: normal; color: var(--text-muted); }
.gtm-run-page .gtm-pnote,
.gtm-run-page .gtm-chain { margin: 9px 16px; padding: 12px 13px 11px; border-radius: 18px; background: rgba(245, 239, 230, 0.035);
  box-shadow: inset 0 0 0 1px rgba(245, 239, 230, 0.10), inset 3px 0 0 color-mix(in srgb, var(--c) 55%, transparent); }
.gtm-run-page .gtm-pnote { margin-top: 14px; font-size: 12.5px; line-height: 1.6; color: var(--text-secondary); }
.gtm-run-page .gtm-chain-th { display: flex; flex-wrap: wrap; align-items: center; gap: 7px; margin-bottom: 7px; }
.gtm-run-page .gtm-chain-num { width: 22px; height: 22px; flex: 0 0 auto; display: grid; place-items: center; border-radius: 50%;
  font-size: 11px; font-weight: 700; color: color-mix(in srgb, var(--c) 85%, #fff);
  background: color-mix(in srgb, var(--c) 20%, transparent); box-shadow: inset 0 0 0 1px color-mix(in srgb, var(--c) 40%, transparent); }
.gtm-run-page .gtm-chain-code { margin: 0; font-size: 12px; line-height: 1.5; color: var(--text-secondary); }
.gtm-run-page .gtm-refcount { color: var(--text-muted); }
.gtm-run-page .gtm-chain-arrow { display: block; margin: 5px 0 3px; text-align: center; color: var(--text-muted); }
.gtm-run-page .gtm-chain-who { display: flex; align-items: center; gap: 9px; margin-bottom: 4px; }
.gtm-run-page .gtm-chain-who b { font-size: 13.5px; font-weight: 600; letter-spacing: -0.2px; }
.gtm-run-page .gtm-chain-obs { margin: 0; font-size: 12.5px; line-height: 1.6; color: var(--text-primary); }
.gtm-run-page .gtm-pills { display: flex; flex-wrap: wrap; gap: 6px; padding: 0 16px; }
.gtm-run-page .gtm-pill { display: inline-flex; align-items: center; gap: 7px; min-width: 0; padding: 4px 11px 4px 4px; border-radius: 999px;
  background: color-mix(in srgb, var(--c) 10%, transparent); box-shadow: inset 0 0 0 1px color-mix(in srgb, var(--c) 30%, transparent); }
.gtm-run-page .gtm-pill .tf-av { width: 24px; height: 24px; }
.gtm-run-page .gtm-pill .tf-av > * { width: 18px; height: 18px; }
.gtm-run-page .gtm-pill-tx { display: flex; align-items: baseline; gap: 5px; min-width: 0; font-size: 11px; }
.gtm-run-page .gtm-pill-tx b { font-weight: 600; color: var(--text-primary); }
.gtm-run-page .gtm-pill-tx small { font-size: 10.5px; color: var(--text-muted); }
.gtm-run-page .gtm-notcalled { padding-top: 10px; }
.gtm-run-page .gtm-ctarow { padding: 12px 16px 0; }
.gtm-run-page .gtm-cta { display: inline-flex; align-items: center; gap: 7px; padding: 9px 14px; border-radius: 999px;
  font-size: 12.5px; font-weight: 650; color: #191614; background: var(--c); box-shadow: 0 0 14px color-mix(in srgb, var(--c) 50%, transparent); }
.gtm-run-page .gtm-airow { margin-top: 18px; }
.gtm-run-page .gtm-ai .t-ico { width: 30px; height: 30px; }
.gtm-run-page .gtm-ai .tf-rowname { font-size: 13px; line-height: 1.35; }

/* Adatforrások + Kör: flat segmented control, one flat list, value chips, round rows */
.gtm-adat .gtm-seg { display: flex; margin: 4px 16px 12px; padding: 3px; border-radius: 999px;
  background: rgba(245, 239, 230, 0.05); box-shadow: inset 0 0 0 1px var(--divider); }
.gtm-adat .gtm-seg button { flex: 1; padding: 8px 0; border-radius: 999px; font-size: 12.5px; font-weight: 600; color: var(--text-secondary); text-align: center; }
.gtm-adat .gtm-seg button.on { color: #191614; background: var(--dv-sage); box-shadow: 0 0 12px color-mix(in srgb, var(--dv-sage) 45%, transparent); }
.gtm-adat .gtm-vchips { display: flex; flex-wrap: wrap; gap: 5px; margin-top: 5px; }
.gtm-adat .gtm-vchip { padding: 2px 8px; border-radius: 999px; font-size: 10px; font-weight: 600;
  color: color-mix(in srgb, var(--dv-sage) 80%, #fff); background: color-mix(in srgb, var(--dv-sage) 12%, transparent);
  box-shadow: inset 0 0 0 1px color-mix(in srgb, var(--dv-sage) 30%, transparent); }
.gtm-adat .gtm-landed { --c: var(--dv-sage); }
.gtm-adat .gtm-later { padding-top: 4px; }
.gtm-adat .gtm-korrow .tf-st { flex: 0 0 auto; }
.gtm-adat .gtm-chev { flex: 0 0 auto; color: var(--text-muted); font-size: 18px; }
.gtm-kor .gtm-items { margin-top: 2px; }
.gtm-kor .gtm-rmeta { display: flex; align-items: center; gap: 6px; flex: 0 0 auto; max-width: 50%; }
.gtm-kor .gtm-sensdot { width: 8px; height: 8px; flex: 0 0 auto; border-radius: 50%; background: var(--dv-lav);
  box-shadow: 0 0 8px color-mix(in srgb, var(--dv-lav) 60%, transparent); }
.gtm-kor .gtm-detcount { font-size: 10.5px; color: var(--text-muted); white-space: nowrap; }

/* Detektorok: one flat list — sentence, key chip, owner in its accent */
.gtm-detektorok .gtm-detline { display: block; font-size: 12.5px; font-weight: 500; line-height: 1.4; color: var(--text-primary); }
.gtm-detektorok .gtm-detmeta { display: flex; flex-wrap: wrap; align-items: center; gap: 8px; margin-top: 6px; font-size: 10.5px; }
.gtm-detektorok .gtm-detmeta b { font-weight: 700; }
/* ── /uveg mezo2 gepterem ── */

/* ── uveg mezo2 tudastar (mezo-me75u.9) ── /mezo/knowledge (base, tenyek, kategoriak, hogyan), /mezo/knowledge/node/:id ── */

/* Page root `.tud9` (KnowledgeListPage + KnowledgeNodePage) wears the csapatfal `tf-*` kit
   (boop-world.css); everything below is scoped to it. Ranking: the approval inbox is the ONE loud
   group (glass amber cases); the doors and kind tiles are glass rows/tiles; fact lists, folds,
   Q&A and the accepted row are flat; degraded / empty / no-match / empty kinds are dashed. */
.tud9 { padding-bottom: 28px; }
.tud9 .tud9-flow { display: flex; flex-direction: column; }
.tud9 .tf-dhead .tud9-help { --c: var(--dv-amber); width: 38px; height: 38px; flex: 0 0 auto; margin-left: auto; display: grid; place-items: center;
  font-size: 16px; font-weight: 600; color: #FFD99A; }
.tud9 .tf-dhead .tud9-help:focus-visible, .tud9 .tf-back:focus-visible { outline: 2px solid var(--c); outline-offset: 2px; }
.tud9 .tud9-big { text-align: center; padding: 2px 16px 8px; }
.tud9 .tud9-bignum { display: block; font-size: 64px; font-weight: 300; letter-spacing: -3.5px; line-height: 1; color: var(--text-primary); font-variant-numeric: tabular-nums; }
.tud9 .tud9-sub { display: block; margin-top: 5px; font-size: 11.5px; color: var(--text-secondary); }
.tud9 .tud9-sech { margin: 0; padding: 22px 18px 10px; font-size: 17px; font-weight: 600; letter-spacing: -0.4px; line-height: 1.25; color: var(--text-primary); }
.tud9 .tud9-dash .t-ico { flex: 0 0 auto; }

/* cases: the inbox (amber, Rólad-only since Task 11), life events (amber) / seasons (sky), the node page */
/* U9b (mezo-zpxv7 Task 11): the inbox cards (FactCandidateCard/LifeEventCandidateCard/
   LifeEventAcceptedCard) render on Rólad ONLY now — the Tudástár shows the pointer instead —
   so their rules are `.kr9-rolad`-only. `.tud9-acts`/`.tud9-btn` stay doubled: the Tudástár's
   own node-detail page (KnowledgeNodePage, `.tud9-node`) still uses the base/`.is-left`/`:disabled`/
   `:focus-visible`/icon-size forms (never `.is-main`, which only the Rólad cards use). */
.kr9-rolad .tud9-case .tf-cmain { align-items: flex-start; }
.kr9-rolad .tud9-case .tf-csub { display: block; -webkit-line-clamp: unset; overflow: visible; font-size: 12px; }
.kr9-rolad .tud9-case .tf-ctitle { overflow-wrap: anywhere; }
.kr9-rolad .tud9-conflictw { margin-top: 10px; }
.kr9-rolad .tud9-conflict { display: flex; align-items: flex-start; gap: 7px; margin: 0; padding: 10px 11px; border-radius: 14px; font-size: 12px; line-height: 1.45;
  color: var(--text-secondary); background: color-mix(in srgb, var(--dv-amber) 8%, transparent); box-shadow: inset 0 0 0 1px color-mix(in srgb, var(--dv-amber) 30%, transparent); overflow-wrap: anywhere; }
.kr9-rolad .tud9-conflict .t-ico { flex: 0 0 auto; margin-top: -1px; }
.kr9-rolad .tud9-chk { position: relative; display: flex; align-items: center; gap: 8px; min-height: 36px; margin-top: 6px; font-size: 12px; font-weight: 600; color: var(--text-primary); cursor: pointer; }
.kr9-rolad .tud9-chk input { position: absolute; left: 0; top: 50%; width: 19px; height: 19px; margin: -9.5px 0 0; opacity: 0; cursor: pointer; }
.kr9-rolad .tud9-chk i { width: 19px; height: 19px; flex: 0 0 auto; border-radius: 6px; display: grid; place-items: center;
  background: rgba(245, 239, 230, 0.06); box-shadow: inset 0 0 0 1px var(--divider); transition: background 0.2s ease, box-shadow 0.2s ease; }
.kr9-rolad .tud9-chk i .t-ico { visibility: hidden; }
.kr9-rolad .tud9-chk input:checked + i { background: var(--dv-amber); box-shadow: 0 0 10px color-mix(in srgb, var(--dv-amber) 50%, transparent); }
.kr9-rolad .tud9-chk input:checked + i .t-ico { visibility: visible; }
.kr9-rolad .tud9-chk input:focus-visible + i { outline: 2px solid var(--dv-amber); outline-offset: 2px; }
.tud9 .tud9-acts, .kr9-rolad .tud9-acts { display: grid; grid-template-columns: 1fr 1fr; gap: 8px; margin-top: 11px; }
.kr9-rolad .tud9-acts > .is-main { grid-column: 1 / -1; }
.kr9-rolad .tud9-acts.is-pair > .is-main { grid-column: auto; }
.tud9 .tud9-acts.is-left, .kr9-rolad .tud9-acts.is-left { display: flex; }
.tud9 .tud9-btn, .kr9-rolad .tud9-btn { display: inline-flex; align-items: center; justify-content: center; gap: 6px; min-height: 40px; padding: 8px 12px; border-radius: 999px;
  font-size: 12px; font-weight: 600; white-space: nowrap; color: var(--text-secondary); background: rgba(245, 239, 230, 0.05); box-shadow: inset 0 0 0 1px var(--divider); }
.kr9-rolad .tud9-btn.is-main { color: var(--text-inverse, #191614); font-weight: 650; background: var(--dv-sage); box-shadow: 0 0 14px color-mix(in srgb, var(--dv-sage) 45%, transparent); }
.tud9 .tud9-btn:disabled, .kr9-rolad .tud9-btn:disabled { opacity: 0.5; cursor: not-allowed; }
.tud9 .tud9-btn:focus-visible, .kr9-rolad .tud9-btn:focus-visible { outline: 2px solid var(--c, var(--dv-sage)); outline-offset: 2px; }
.tud9 .tud9-btn .t-ico, .kr9-rolad .tud9-btn .t-ico { width: 20px; height: 20px; }
.kr9-rolad .tud9-no { display: block; width: 100%; margin-top: 8px; padding: 6px 0; border: 0; background: none;
  font-size: 12px; font-weight: 600; text-align: center; text-decoration: underline; text-underline-offset: 2px;
  color: var(--text-muted); cursor: pointer; }
.kr9-rolad .tud9-no:hover, .kr9-rolad .tud9-no:focus-visible { color: var(--text-secondary); }
.kr9-rolad .tud9-no:focus-visible { outline: 2px solid var(--c, var(--dv-sage)); outline-offset: 2px; }
.tud9 .tud9-foot, .kr9-rolad .tud9-foot { display: block; margin: 9px 0 0; font-size: 10.5px; line-height: 1.45; color: var(--text-muted); }
.kr9-rolad .tud9-prov { margin: 9px 0 0; font-size: 11.5px; line-height: 1.5; color: var(--text-secondary); }
.kr9-rolad .tud9-refine { display: flex; align-items: center; gap: 8px; margin-top: 11px; }
.kr9-rolad .tud9-refine.is-col { flex-direction: column; align-items: stretch; margin-top: 2px; }
.kr9-rolad .tud9-refine.is-col .tud9-acts { margin-top: 2px; }
.kr9-rolad .tud9-input { flex: 1; min-width: 0; padding: 10px 12px; border: 0; border-radius: 14px; font: inherit; font-size: 13px; line-height: 1.4; resize: vertical;
  color: var(--text-primary); background: rgba(25, 22, 20, 0.45); box-shadow: inset 0 0 0 1px var(--divider); }
.kr9-rolad .tud9-input:focus-visible { outline: none; box-shadow: inset 0 0 0 1.5px color-mix(in srgb, var(--c, var(--dv-amber)) 70%, transparent); }
.kr9-rolad .tud9-accepted { display: flex; align-items: flex-start; gap: 12px; }
.kr9-rolad .tud9-accepted u { flex: 0 0 auto; width: 10px; height: 10px; margin-top: 5px; border-radius: 50%; background: var(--dv-sage);
  box-shadow: 0 0 8px color-mix(in srgb, var(--dv-sage) 60%, transparent); }
.kr9-rolad .tud9-acctx { flex: 1; min-width: 0; }
.kr9-rolad .tud9-acctx b { display: block; font-size: 14px; font-weight: 600; line-height: 1.35; overflow-wrap: anywhere; }
.kr9-rolad .tud9-acctx small { display: block; margin-top: 3px; font-size: 11px; font-weight: 600; color: color-mix(in srgb, var(--dv-sage) 80%, #fff); }

