.sheet.glass.m9m-sheet .sheet-handle { background: rgba(245, 239, 230, 0.22); }
.m9m-sheet .mnt-filter-head { justify-content: flex-start; }
.m9m-sheet .m9m-sheet-title { flex: 1; min-width: 0; }
.m9m-sheet .mnt-filter-head .eyebrow { color: var(--text-muted); }
.m9m-sheet .mnt-filter-head h2 { font-size: 21px; font-weight: 600; letter-spacing: -0.6px; }
.m9m-sheet .m9m-sheet-x { flex: 0 0 auto; width: 36px; height: 36px; padding: 0; border: 0; border-radius: 50%; display: grid; place-items: center; cursor: pointer;
  color: var(--text-secondary); background: rgba(245, 239, 230, 0.06); box-shadow: inset 0 0 0 1px var(--divider); }
.m9m-sheet .mnt-filter-label { color: var(--text-muted); }
.m9m-sheet .mnt-filter-option { border: 0; color: var(--text-secondary); background: rgba(245, 239, 230, 0.05); box-shadow: inset 0 0 0 1px var(--divider); }
.m9m-sheet .mnt-filter-option .t-ico { width: 22px; height: 22px; }
.m9m-sheet .mnt-filter-option[aria-pressed="true"] { color: #FFD99A; background: color-mix(in srgb, var(--dv-amber) 14%, transparent);
  box-shadow: inset 0 0 0 1.2px color-mix(in srgb, var(--dv-amber) 55%, transparent), 0 0 14px -4px color-mix(in srgb, var(--dv-amber) 60%, transparent); }
.m9m-sheet select { border: 0; color-scheme: dark; background: rgba(245, 239, 230, 0.05); box-shadow: inset 0 0 0 1px var(--divider); }
.m9m-sheet .mnt-filter-apply { display: inline-flex; align-items: center; justify-content: center; gap: 7px; border: 0; border-radius: 999px; color: #FFD99A;
  background: radial-gradient(90% 140% at 20% 20%, color-mix(in srgb, var(--dv-amber) 28%, transparent), rgba(245, 239, 230, 0.04));
  box-shadow: inset 0 0 0 1px color-mix(in srgb, var(--dv-amber) 45%, transparent), 0 0 16px -4px color-mix(in srgb, var(--dv-amber) 60%, transparent); }

/* Előrejelzések */
.m9e-root .m9e-hero { text-align: center; padding: 2px 16px 8px; }
.m9e-root .m9e-acc { display: inline-block; font-size: 84px; font-weight: 300; letter-spacing: -5px; line-height: 1; font-variant-numeric: tabular-nums;
  background: linear-gradient(135deg, var(--dv-sky) 0%, color-mix(in srgb, var(--dv-sky) 28%, #fff) 45%, color-mix(in srgb, var(--dv-amber) 70%, #fff) 100%);
  -webkit-background-clip: text; background-clip: text; color: transparent;
  filter: drop-shadow(0 6px 18px color-mix(in srgb, var(--dv-sky) 35%, transparent)); }
.m9e-root .m9e-acc small { font-size: 30px; letter-spacing: -1px; }
.m9e-root .m9e-hero > small { display: block; margin-top: 5px; font-size: 11.5px; color: var(--text-secondary); }
.m9e-root .m9e-note { margin: 0; padding: 4px 18px 10px; font-size: 12.5px; line-height: 1.5; color: var(--text-secondary); }
.m9e-root .m9e-state { line-height: 1.45; }
.m9e-root .m9e-state .m9e-statetx { display: block; }
.m9e-root .m9e-learn { font-weight: 700; color: var(--dv-sky); }
.m9e-root .m9e-state .m9e-learn { display: block; font-size: 9.5px; letter-spacing: 1.2px; text-transform: uppercase; }
.m9e-root .m9e-retry { margin-left: auto; flex: 0 0 auto; min-height: 40px; padding: 0 14px; border: 0; border-radius: 999px; cursor: pointer; font: inherit; font-size: 12px; font-weight: 600;
  color: #CFE3F5; background: color-mix(in srgb, var(--dv-sky) 18%, transparent); box-shadow: inset 0 0 0 1px color-mix(in srgb, var(--dv-sky) 45%, transparent); }
.m9e-root .m9e-filt { display: flex; gap: 6px; overflow-x: auto; padding: 0 16px 12px; scrollbar-width: none; }
.m9e-root .m9e-filt::-webkit-scrollbar { display: none; }
.m9e-root .m9e-filt button { flex: 0 0 auto; min-height: 36px; padding: 0 13px; border: 0; border-radius: 999px; cursor: pointer; white-space: nowrap;
  font: inherit; font-size: 11.5px; font-weight: 600; color: var(--text-secondary); background: rgba(245, 239, 230, 0.05); box-shadow: inset 0 0 0 1px var(--divider); }
.m9e-root .m9e-filt button.on { color: #191614; background: var(--dv-sky); box-shadow: 0 0 12px color-mix(in srgb, var(--dv-sky) 45%, transparent); }
.m9e-root .m9e-st { display: inline-flex; align-items: center; gap: 5px; }
.m9e-root .m9e-st .t-ico { width: 14px; height: 14px; }
.m9e-root .m9e-title { color: inherit; text-decoration: none; }
.m9e-root .m9e-conf { display: flex; align-items: center; gap: 10px; margin-top: 11px; }
.m9e-root .m9e-conf .uv-bar { flex: 1; margin-top: 0; }
.m9e-root .m9e-pct { font-size: 13px; font-weight: 600; color: color-mix(in srgb, var(--dv-sky) 60%, #fff); font-variant-numeric: tabular-nums; }
.m9e-root .m9e-basis { margin: 9px 0 0; font-size: 12px; line-height: 1.5; color: var(--text-secondary); }
.m9e-root .m9e-observed { margin: 9px 0 0; font-size: 11px; line-height: 1.45; color: var(--text-muted); }
.m9e-root .m9e-actual { margin-top: 10px; }
.m9e-root .m9e-fb { margin-top: 10px; }
@media (prefers-reduced-motion: no-preference) {
  .m9e-root .m9e-acc { animation: m9e-breathe 4.8s ease-in-out infinite; }
}
@keyframes m9e-breathe {
  0%, 100% { filter: drop-shadow(0 6px 18px color-mix(in srgb, var(--dv-sky) 30%, transparent)); }
  50% { filter: drop-shadow(0 6px 22px color-mix(in srgb, var(--dv-amber) 40%, transparent)); }
}
/* ── /uveg mezo2 mintak ── */

/* ══ mezo-nn7h0 · one background everywhere ═════════════════════════════════════════════
   Each page's hero halo painted a large wash in its own domain color (lila Mai, kék Fuel,
   borostyán Edzés, rózsa Én…), so every page read as a different background. The shared
   .uv-aurora is now THE background; the halos stay as a soft glow hugging the hero object. */
:root[data-theme="dark"] :is(
  .uv-halo, .fmx-hero, .fmx-detail-hero, .fmx-score-hero, .nap-hub .nap-center-orbit,
  .trm .trm-hero, .tw-load .ld-hero, .pl-dhero, .tw-map .ld-map-page,
  .gra-page .gr-streak.gr-band, .settings-page .settings-hero, .mzc-u8 .mzc-emptyhero
)::before { opacity: 0.4; }

/* mezo-5knnj · the header, the status bar and the page are ONE color, no transition.
   (1) MozaikPage's per-tone top wash (.mz-p-lav on A napom, …) painted each page its own
   colored band under the header — dark pages sit straight on the shared ground instead.
   (2) The aurora's upper blobs bled into the header zone, so the opaque header read as a
   darker strip; they now start below it (blur 60px ≈ 120px reach), leaving the top plain. */
:root[data-theme="dark"] .mz-page { background: transparent; }
:root[data-theme="dark"] .uv-aurora i:nth-child(1) { top: 300px; }
:root[data-theme="dark"] .uv-aurora i:nth-child(2) { top: 230px; }
:root[data-theme="dark"] .uv-aurora i:nth-child(3) { top: 600px; }
:root[data-theme="dark"] .uv-aurora i:nth-child(4) { top: 820px; }

/* (3) The page-top ambient halos (--halo-*) painted full-width colored bands on the heroes
   that wear them (Terv poszter, sablonok, heti térkép, …). Dark keeps the same hues at ~40%
   strength, like the ::before halos above, so they glow around the hero, not across the page. */
:root[data-theme="dark"] {
  --halo-amber:  radial-gradient(ellipse at 50% 30%, rgba(212,168,83,0.13) 0%, transparent 55%);
  --halo-sage:   radial-gradient(ellipse at 50% 30%, rgba(154,184,143,0.12) 0%, rgba(244,208,111,0.04) 30%, transparent 60%);
  --halo-rose:   radial-gradient(ellipse at 50% 30%, rgba(231,134,110,0.08) 0%, transparent 55%);
  --halo-blue:   radial-gradient(ellipse at 50% 30%, rgba(107,176,209,0.12) 0%, transparent 60%);
  --halo-violet: radial-gradient(ellipse at 50% 30%, rgba(154,95,196,0.10) 0%, transparent 60%);
  --halo-coral:  radial-gradient(ellipse at 50% 24%, rgba(255,107,74,0.14) 0%, rgba(212,168,83,0.05) 32%, transparent 64%);
}
